pub const max_source_bytes: usize = 128 * 1024;
pub const max_tokens: usize = 64 * 1024;
pub const max_nodes: usize = 48 * 1024;
pub const max_cells: usize = 32768;
const initial_string_bytes: usize = 1536 * 1024;
pub const max_strings: usize = 64 * 1024 * 1024;
const max_interned_strings: usize = 16 * 1024;
// Browser globals and mature platform prototypes legitimately exceed the
// compact language-only limits. Keep enough per-object and lexical capacity
// for the Web API surface plus page-owned properties.
pub const max_properties: usize = 256;
pub const max_bindings: usize = 256;
pub const max_items: usize = 64 * 1024;
const max_inline_properties: usize = 4;
const max_inline_bindings: usize = 16;
const max_inline_items: usize = 16;
const max_fused_expression_nodes: usize = 64;
pub const max_parameters: usize = 128;
pub const max_call_arguments: usize = 8 * 1024;
const argument_map_words: usize = (max_parameters + 63) / 64;
pub const max_modules: usize = 8;
const max_module_specifier_bytes: usize = 2048;
const max_module_exports: usize = 128;
pub const max_dynamic_programs: usize = 4;
pub const max_jobs: usize = 128;
pub const max_roots: usize = 512;
pub const max_call_depth: usize = 64;
pub const max_template_objects: usize = 128;
const max_regex_captures: usize = 32;
const max_regex_states: usize = 64;
const max_regex_backtrack_depth: usize = 32;
pub const default_step_budget: usize = 2_000_000;
pub const none: u16 = std.math.maxInt(u16);
pub const max_bytecode_instructions: usize = max_nodes * 3;
pub const max_bytecode_segments: usize = max_nodes;
pub const max_bytecode_stack: usize = max_parameters * 4;
pub const max_bytecode_frames: usize = max_call_depth * 4;
const max_identifier_cache_entries: usize = 4096;
pub const max_bigint_limbs: usize = 4096;
pub const max_bigint_bits: usize = max_bigint_limbs * @bitSizeOf(BigIntLimb);
pub const max_array_buffer_bytes: usize = 16 * 1024 * 1024;
const fiber_stack_bytes: usize = 1024 * 1024;
const identifier_ref_bit: u32 = 1 << 31;

pub const Error = error{
    SourceTooLarge,
    TokenLimit,
    NodeLimit,
    BytecodeLimit,
    BytecodeSegmentLimit,
    BytecodeInvalid,
    BytecodeStack,
    BytecodeFrameLimit,
    StringLimit,
    CellLimit,
    PropertyLimit,
    BindingLimit,
    ItemLimit,
    ModuleLimit,
    ProgramAllocation,
    JobLimit,
    RootLimit,
    GeneratorAllocation,
    SyntaxError,
    UnexpectedToken,
    UnknownIdentifier,
    NotCallable,
    NotObject,
    InvalidAssignment,
    ConstAssignment,
    TypeError,
    RangeError,
    UncaughtException,
    ScriptThrown,
    GeneratorReturn,
    StepLimit,
    Cancelled,
    CallDepth,
    ModuleNotFound,
    ModuleCycle,
};

fn isCatchableRuntimeError(err: Error) bool {
    return switch (err) {
        error.UnknownIdentifier,
        error.NotCallable,
        error.NotObject,
        error.InvalidAssignment,
        error.ConstAssignment,
        error.TypeError,
        error.RangeError,
        error.SyntaxError,
        => true,
        else => false,
    };
}

pub const Stop = struct {
    context: ?*anyopaque = null,
    requested: ?*const fn (?*anyopaque) bool = null,
    check_interval: usize = 1,

    pub fn isRequested(self: Stop) bool {
        const callback = self.requested orelse return false;
        return callback(self.context);
    }
};

pub const StringRef = extern struct {
    offset: u32 = 0,
    len: u32 = 0,

    pub fn bytes(self: StringRef, storage: []const u8) []const u8 {
        const start: usize = self.offset;
        const length: usize = self.len;
        if (start > storage.len or length > storage.len - start) return "";
        return storage[start .. start + length];
    }
};

pub const Value = union(enum) {
    undefined,
    null_value,
    boolean: bool,
    number: f64,
    bigint: u16,
    string: StringRef,
    cell: u16,

    pub fn isNullish(self: Value) bool {
        return self == .undefined or self == .null_value;
    }
};

