const CompiledProgramStorage = extern struct {
    instructions: [max_bytecode_instructions]BytecodeInstruction,
    segment_starts: [max_bytecode_segments]u32,
    segment_ends: [max_bytecode_segments]u32,
    segment_nodes: [max_bytecode_segments]u16,
    segment_max_stacks: [max_bytecode_segments]u16,
