    node_segments: [max_nodes]u16,
    function_prologue_segments: [max_nodes]u16,
};

const ProgramWorkspace = extern union {
    tokens: [max_tokens]Token,
    compiled: CompiledProgramStorage,
};

comptime {
    if (@sizeOf(BytecodeInstruction) != 8) @compileError("bytecode instruction is not compact");
    if (@sizeOf(CompiledProgramStorage) > @sizeOf([max_tokens]Token))
        @compileError(std.fmt.comptimePrint("compiled JavaScript storage {d} exceeds parser-token workspace {d}", .{ @sizeOf(CompiledProgramStorage), @sizeOf([max_tokens]Token) }));
}

