pub const ParseStats = struct {
    source_bytes: usize,
    tokens: usize,
    nodes: usize,
    functions: usize,
    modules: usize,
    bytecode_instructions: usize,
    bytecode_segments: usize,
};

pub const DiagnosticPhase = enum(u8) {
    none,
    parser,
    compiler,
    vm,
    host,
};

pub const Program = struct {
    source: [max_source_bytes]u8 = undefined,
    identifier_storage: [max_source_bytes]u8 = undefined,
    workspace: ProgramWorkspace = undefined,
    nodes: [max_nodes]Node = undefined,
    source_len: usize = 0,
    identifier_len: usize = 0,
    token_count: usize = 0,
    node_count: usize = 0,
    root: u16 = none,
    root_segment: u16 = none,
    bytecode_count: usize = 0,
    bytecode_segment_count: usize = 0,
    bytecode_valid: bool = false,
    bytecode_signature: u64 = 0,
    bytecode_generation: u64 = 0,
    bytecode_parse_generation: u64 = 0,
    strict_mode: bool = false,
    parse_generation: u64 = 0,
    function_count: usize = 0,
    module_statement_count: usize = 0,
    source_name: [128]u8 = .{0} ** 128,
    source_name_len: usize = 0,
    diagnostic_phase: DiagnosticPhase = .none,
    diagnostic_error: ?Error = null,
    diagnostic_offset: usize = 0,

    pub fn reset(self: *Program) void {
        self.source_len = 0;
        self.identifier_len = 0;
        self.token_count = 0;
        self.node_count = 0;
        self.root = none;
        self.root_segment = none;
        self.bytecode_count = 0;
        self.bytecode_segment_count = 0;
        self.bytecode_valid = false;
        self.bytecode_signature = 0;
        self.bytecode_parse_generation = 0;
        self.strict_mode = false;
        self.function_count = 0;
        self.module_statement_count = 0;
        self.source_name_len = 0;
        self.diagnostic_phase = .none;
        self.diagnostic_error = null;
        self.diagnostic_offset = 0;
    }

    pub fn setSourceName(self: *Program, name: []const u8) void {
        self.source_name_len = @min(name.len, self.source_name.len);
        if (self.source_name_len > 0) @memcpy(self.source_name[0..self.source_name_len], name[0..self.source_name_len]);
    }

    pub fn setDerivedSourceName(self: *Program, parent: []const u8, suffix: []const u8) void {
        const suffix_len = @min(suffix.len, self.source_name.len);
        const parent_len = @min(parent.len, self.source_name.len - suffix_len);
        if (parent_len > 0) @memcpy(self.source_name[0..parent_len], parent[0..parent_len]);
        if (suffix_len > 0) @memcpy(self.source_name[parent_len .. parent_len + suffix_len], suffix[suffix.len - suffix_len ..]);
        self.source_name_len = parent_len + suffix_len;
    }

    pub fn sourceName(self: *const Program) []const u8 {
        return if (self.source_name_len > 0) self.source_name[0..self.source_name_len] else "<script>";
    }

    pub fn sourceBytes(self: *const Program) []const u8 {
        return self.source[0..self.source_len];
    }

    pub fn nodeSourceOffset(self: *const Program, node_index: u16) usize {
        if (node_index == none or node_index >= self.node_count) return 0;
        const node = self.nodes[node_index];
        if (node.source_offset != std.math.maxInt(u32) and node.source_offset < self.source_len) return node.source_offset;
        if (node.source.len > 0 and node.source.offset & identifier_ref_bit == 0 and node.source.offset < self.source_len) return node.source.offset;
        if (node.text.len > 0 and node.text.offset & identifier_ref_bit == 0 and node.text.offset < self.source_len) return node.text.offset;
        return 0;
    }

    pub fn parse(self: *Program, source: []const u8) Error!ParseStats {
        return self.parseMode(source, false);
    }

    pub fn parseHostSource(self: *Program, source: []const u8) Error!ParseStats {
        return self.parseMode(source, true);
    }

    fn parseMode(self: *Program, source: []const u8, allow_top_level_return: bool) Error!ParseStats {
        const already_stored = source.len == 0 or source.ptr == self.source[0..].ptr;
        self.reset();
        self.parse_generation +%= 1;
        if (self.parse_generation == 0) self.parse_generation = 1;
        if (source.len > self.source.len) return error.SourceTooLarge;
        if (source.len > 0 and !already_stored) @memcpy(self.source[0..source.len], source);
        self.source_len = source.len;
        self.tokenize() catch |err| {
            if (self.diagnostic_error == null) self.recordProgramDiagnostic(.parser, err, if (self.token_count > 0) self.workspace.tokens[self.token_count - 1].source_offset else 0);
            return err;
        };
        var parser = Parser{ .program = self, .return_allowed = allow_top_level_return };
        self.root = parser.parseProgram() catch |err| {
            const token_index = @min(@max(parser.current, parser.furthest), self.token_count -| 1);
            const offset = if (self.token_count == 0)
                0
            else if (self.workspace.tokens[token_index].kind == .eof)
                self.source_len
            else
                self.workspace.tokens[token_index].source_offset;
            self.recordProgramDiagnostic(.parser, err, offset);
            return err;
        };
        self.markFunctionsNeedingArguments();
        self.compileBytecode() catch |err| {
            self.recordProgramDiagnostic(.compiler, err, 0);
            return err;
        };
        return .{
            .source_bytes = source.len,
            .tokens = self.token_count,
            .nodes = self.node_count,
            .functions = self.function_count,
            .modules = self.module_statement_count,
            .bytecode_instructions = self.bytecode_count,
            .bytecode_segments = self.bytecode_segment_count,
        };
    }

    fn markFunctionsNeedingArguments(self: *Program) void {
        for (self.nodes[0..self.node_count]) |*node| {
            if (node.kind == .function_declaration or node.kind == .function_expression)
                node.flags &= ~flag_needs_arguments;
        }
        for (self.workspace.tokens[0..self.token_count]) |token| {
            if (token.kind != .identifier) continue;
            const name = self.text(token.text);
            if (!equals(name, "arguments") and !equals(name, "eval")) continue;
            var selected: u16 = none;
            var selected_length: usize = std.math.maxInt(usize);
            for (self.nodes[0..self.node_count], 0..) |node, node_index| {
                if ((node.kind != .function_declaration and node.kind != .function_expression) or node.flags & flag_arrow != 0 or
                    node.source.len == 0 or node.source.offset & identifier_ref_bit != 0) continue;
                const start: usize = node.source.offset;
                const length: usize = node.source.len;
                if (token.source_offset < start or token.source_offset >= start + length or length >= selected_length) continue;
                selected = @intCast(node_index);
                selected_length = length;
            }
            if (selected != none) self.nodes[selected].flags |= flag_needs_arguments;
        }
    }

    fn recordProgramDiagnostic(self: *Program, phase: DiagnosticPhase, err: Error, offset: usize) void {
        self.diagnostic_phase = phase;
        self.diagnostic_error = err;
        self.diagnostic_offset = @min(offset, self.source_len);
    }

    pub fn text(self: *const Program, ref: StringRef) []const u8 {
        if (ref.offset & identifier_ref_bit != 0) {
            const offset: usize = ref.offset & ~identifier_ref_bit;
            const length: usize = ref.len;
            if (offset > self.identifier_len or length > self.identifier_len - offset) return "";
            return self.identifier_storage[offset .. offset + length];
        }
        return ref.bytes(self.source[0..self.source_len]);
    }

    fn appendIdentifierCodePoint(self: *Program, codepoint: u21) Error!void {
        var encoded: [4]u8 = undefined;
        const length = std.unicode.utf8Encode(codepoint, encoded[0..]) catch return error.SyntaxError;
        if (self.identifier_len + length > self.identifier_storage.len) return error.SourceTooLarge;
        @memcpy(self.identifier_storage[self.identifier_len .. self.identifier_len + length], encoded[0..length]);
        self.identifier_len += length;
    }

    fn addToken(self: *Program, token: Token) Error!void {
        if (self.token_count >= self.workspace.tokens.len) return error.TokenLimit;
        var stored = token;
        if (stored.end_line == 0) stored.end_line = stored.line;
        if (stored.source_offset == 0 and stored.text.offset & identifier_ref_bit == 0) stored.source_offset = stored.text.offset;
        self.workspace.tokens[self.token_count] = stored;
        self.token_count += 1;
    }

    fn addNode(self: *Program, node: Node) Error!u16 {
        if (self.node_count >= self.nodes.len or self.node_count >= none) return error.NodeLimit;
        const index: u16 = @intCast(self.node_count);
        self.nodes[self.node_count] = node;
        self.node_count += 1;
        return index;
    }

    fn compileBytecode(self: *Program) Error!void {
        self.bytecode_count = 0;
        self.bytecode_segment_count = 0;
        self.root_segment = none;
        self.bytecode_valid = false;
        @memset(self.workspace.compiled.node_segments[0..self.node_count], none);
        @memset(self.workspace.compiled.function_prologue_segments[0..self.node_count], none);
        self.root_segment = try self.compileStatementSegment(self.root);
        try self.validateBytecode();
        self.bytecode_signature = self.bytecodeFingerprint();
        self.bytecode_generation +%= 1;
        if (self.bytecode_generation == 0) self.bytecode_generation = 1;
        self.bytecode_parse_generation = self.parse_generation;
        self.bytecode_valid = true;
    }

    fn addBytecodeSegment(self: *Program, node: u16, kind: BytecodeSegmentKind) Error!u16 {
        if (self.bytecode_segment_count >= self.workspace.compiled.segment_starts.len or self.bytecode_segment_count >= none)
            return error.BytecodeSegmentLimit;
        const index: u16 = @intCast(self.bytecode_segment_count);
        self.workspace.compiled.segment_starts[index] = 0;
        self.workspace.compiled.segment_ends[index] = 0;
        self.workspace.compiled.segment_nodes[index] = node;
        self.workspace.compiled.segment_max_stacks[index] = 0;
        self.workspace.compiled.segment_kinds[index] = kind;
        self.bytecode_segment_count += 1;
        return index;
    }

    fn bytecodeSegment(self: *const Program, index: u16) BytecodeSegment {
        return .{
            .start = self.workspace.compiled.segment_starts[index],
            .end = self.workspace.compiled.segment_ends[index],
            .node = self.workspace.compiled.segment_nodes[index],
            .max_stack = self.workspace.compiled.segment_max_stacks[index],
            .kind = self.workspace.compiled.segment_kinds[index],
        };
    }

    fn emitBytecode(self: *Program, op: BytecodeOp, node: u16, flags: u8, b: u16, c: u16) Error!void {
        if (self.bytecode_count >= self.workspace.compiled.instructions.len) return error.BytecodeLimit;
        self.workspace.compiled.instructions[self.bytecode_count] = .{ .op = op, .flags = flags, .a = node, .b = b, .c = c };
        self.bytecode_count += 1;
    }

    fn segmentForNode(self: *const Program, node: u16) Error!u16 {
        if (node == none or node >= self.node_count) return error.BytecodeInvalid;
        const segment = self.workspace.compiled.node_segments[node];
        if (segment == none or segment >= self.bytecode_segment_count) return error.BytecodeInvalid;
        return segment;
    }

    fn compileStatementSegment(self: *Program, index: u16) Error!u16 {
        if (index == none or index >= self.node_count) return error.BytecodeInvalid;
        if (self.workspace.compiled.node_segments[index] != none) return self.workspace.compiled.node_segments[index];
        const node = self.nodes[index];
        const kind: BytecodeSegmentKind = switch (node.kind) {
            .program => .program,
            .block => if (node.flags & flag_declaration_list != 0) .statement else .block,
            .switch_case => .switch_case,
            else => .statement,
        };
        const segment_index = try self.addBytecodeSegment(index, kind);
        self.workspace.compiled.node_segments[index] = segment_index;
        try self.prepareStatementDependencies(index);
        self.workspace.compiled.segment_starts[segment_index] = @intCast(self.bytecode_count);
        switch (node.kind) {
            .program => {
                try self.emitVarHoists(node.a);
                try self.compileStatementList(node.a);
            },
            .block => try self.compileStatementList(node.a),
            .switch_case => try self.compileStatementList(node.b),
            else => try self.compileStatement(index),
        }
        self.workspace.compiled.segment_ends[segment_index] = @intCast(self.bytecode_count);
        return segment_index;
    }

    fn compileExpressionSegment(self: *Program, index: u16) Error!u16 {
        if (index == none or index >= self.node_count) return error.BytecodeInvalid;
        if (self.workspace.compiled.node_segments[index] != none) return self.workspace.compiled.node_segments[index];
        const segment_index = try self.addBytecodeSegment(index, .expression);
        self.workspace.compiled.node_segments[index] = segment_index;
        try self.prepareExpressionDependencies(index);
        self.workspace.compiled.segment_starts[segment_index] = @intCast(self.bytecode_count);
        try self.compileExpression(index);
        self.workspace.compiled.segment_ends[segment_index] = @intCast(self.bytecode_count);
        return segment_index;
    }

    fn compileFunctionDependencies(self: *Program, index: u16) Error!void {
        const node = self.nodes[index];
        if (node.kind != .function_declaration and node.kind != .function_expression) return error.BytecodeInvalid;
        var parameter = node.a;
        while (parameter != none) : (parameter = self.nodes[parameter].next) {
            const parameter_node = self.nodes[parameter];
            if (parameter_node.kind != .parameter) return error.BytecodeInvalid;
            if (parameter_node.a != none) _ = try self.compileExpressionSegment(parameter_node.a);
            if (parameter_node.b != none) try self.preparePatternDependencies(parameter_node.b, false);
        }
        if (isStatementKind(self.nodes[node.b].kind)) {
            _ = try self.compileStatementSegment(node.b);
        } else {
            _ = try self.compileExpressionSegment(node.b);
        }
        if (self.workspace.compiled.function_prologue_segments[index] != none) return;
        const segment_index = try self.addBytecodeSegment(index, .function_prologue);
        self.workspace.compiled.function_prologue_segments[index] = segment_index;
        self.workspace.compiled.segment_starts[segment_index] = @intCast(self.bytecode_count);
        if (self.nodes[node.b].kind == .block) try self.emitVarHoists(self.nodes[node.b].a);
        self.workspace.compiled.segment_ends[segment_index] = @intCast(self.bytecode_count);
    }

    fn prepareStatementListDependencies(self: *Program, first: u16) Error!void {
        var current = first;
        while (current != none) : (current = self.nodes[current].next) {
            _ = try self.compileStatementSegment(current);
        }
    }

    fn prepareStatementDependencies(self: *Program, index: u16) Error!void {
        if (index == none) return;
        const node = self.nodes[index];
        switch (node.kind) {
            .program, .block => try self.prepareStatementListDependencies(node.a),
            .switch_case => {
                if (node.a != none) _ = try self.compileExpressionSegment(node.a);
                try self.prepareStatementListDependencies(node.b);
            },
            .empty, .break_statement, .continue_statement, .import_statement, .export_list => {},
            .export_default => try self.prepareExpressionDependencies(node.a),
            .expression_statement => try self.prepareExpressionDependencies(node.a),
            .variable => {
                if (node.a != none) try self.prepareExpressionDependencies(node.a);
                if (node.b != none) try self.preparePatternDependencies(node.b, true);
            },
            .function_declaration => try self.compileFunctionDependencies(index),
            .class_declaration => try self.compileClassDependencies(index),
            .return_statement => if (node.a != none) try self.prepareExpressionDependencies(node.a),
            .throw_statement => try self.prepareExpressionDependencies(node.a),
            .if_statement => {
                _ = try self.compileExpressionSegment(node.a);
                _ = try self.compileStatementSegment(node.b);
                if (node.c != none) _ = try self.compileStatementSegment(node.c);
            },
            .while_statement, .do_while_statement => {
                _ = try self.compileExpressionSegment(node.a);
                _ = try self.compileStatementSegment(node.b);
            },
            .for_statement => {
                if (node.a != none) {
                    if (isStatementKind(self.nodes[node.a].kind))
                        _ = try self.compileStatementSegment(node.a)
                    else
                        _ = try self.compileExpressionSegment(node.a);
                }
                if (node.b != none) _ = try self.compileExpressionSegment(node.b);
                if (node.c != none) _ = try self.compileExpressionSegment(node.c);
                _ = try self.compileStatementSegment(node.d);
            },
            .for_in_statement, .for_of_statement => {
                const target = self.nodes[node.a];
                if (target.kind == .variable) {
                    try self.preparePatternDependencies(target.b, true);
                } else if (isPatternKind(target.kind)) {
                    try self.preparePatternDependencies(node.a, false);
                } else if (target.kind == .member) {
                    if (target.flags & flag_super == 0) _ = try self.compileExpressionSegment(target.a);
                    if (target.flags & flag_computed != 0) _ = try self.compileExpressionSegment(target.b);
                } else if (target.kind != .variable and target.kind != .identifier) {
                    return error.InvalidAssignment;
                }
                _ = try self.compileExpressionSegment(node.b);
                _ = try self.compileStatementSegment(node.c);
            },
            .switch_statement => {
                _ = try self.compileExpressionSegment(node.a);
                var current = node.b;
                while (current != none) : (current = self.nodes[current].next) {
                    _ = try self.compileStatementSegment(current);
                }
            },
            .labeled_statement => _ = try self.compileStatementSegment(node.a),
            .with_statement => {
                _ = try self.compileExpressionSegment(node.a);
                _ = try self.compileStatementSegment(node.b);
            },
            .try_statement => {
                _ = try self.compileStatementSegment(node.a);
                if (node.d != none) try self.preparePatternDependencies(node.d, true);
                if (node.b != none) _ = try self.compileStatementSegment(node.b);
                if (node.c != none) _ = try self.compileStatementSegment(node.c);
            },
            else => try self.prepareExpressionDependencies(index),
        }
    }

    fn prepareAssignableDependencies(self: *Program, index: u16) Error!void {
        const target = self.nodes[index];
        switch (target.kind) {
            .identifier => {},
            .member => {
                if (target.flags & flag_super == 0) try self.prepareExpressionDependencies(target.a);
                if (target.flags & flag_computed != 0) try self.prepareExpressionDependencies(target.b);
            },
            else => return error.InvalidAssignment,
        }
    }

    fn preparePatternDependencies(self: *Program, index: u16, binding: bool) Error!void {
        if (index == none or index >= self.node_count) return error.BytecodeInvalid;
        const pattern = self.nodes[index];
        switch (pattern.kind) {
            .identifier => {},
            .member => {
                if (binding) return error.SyntaxError;
                if (pattern.flags & flag_super == 0) _ = try self.compileExpressionSegment(pattern.a);
                if (pattern.flags & flag_computed != 0) _ = try self.compileExpressionSegment(pattern.b);
            },
            .array_pattern, .object_pattern => {
                var current = pattern.a;
                while (current != none) : (current = self.nodes[current].next) {
                    const element = self.nodes[current];
                    if (element.kind != .pattern_element) return error.BytecodeInvalid;
                    if (element.c != none) _ = try self.compileExpressionSegment(element.c);
                    if (element.b != none) _ = try self.compileExpressionSegment(element.b);
                    if (element.a != none) try self.preparePatternDependencies(element.a, binding);
                }
            },
            else => return error.InvalidAssignment,
        }
    }

    fn compileClassDependencies(self: *Program, index: u16) Error!void {
        const node = self.nodes[index];
        if (node.kind != .class_declaration and node.kind != .class_expression) return error.BytecodeInvalid;
        if (node.a != none) _ = try self.compileExpressionSegment(node.a);
        try self.compileFunctionDependencies(node.c);
        var current = node.b;
        while (current != none) : (current = self.nodes[current].next) {
            const element = self.nodes[current];
            if (element.kind != .class_element) return error.BytecodeInvalid;
            if (element.b != none) _ = try self.compileExpressionSegment(element.b);
            if (element.flags & flag_class_static_block != 0) {
                _ = try self.compileStatementSegment(element.a);
            } else if (element.flags & flag_class_field != 0) {
                if (element.a != none) _ = try self.compileExpressionSegment(element.a);
            } else {
                try self.compileFunctionDependencies(element.a);
            }
        }
    }

    fn prepareExpressionDependencies(self: *Program, index: u16) Error!void {
        if (index == none) return;
        const node = self.nodes[index];
        switch (node.kind) {
            .number_literal, .bigint_literal, .string_literal, .regex_literal, .boolean_literal, .null_literal, .undefined_literal, .identifier, .import_meta, .this_expression, .new_target => {},
            .dynamic_import => try self.prepareExpressionDependencies(node.a),
            .private_identifier => return error.SyntaxError,
            .private_in => try self.prepareExpressionDependencies(node.a),
            .super_reference => return error.SyntaxError,
            .super_call => {
                var argument = node.a;
                while (argument != none) : (argument = self.nodes[argument].next) {
                    const target = if (self.nodes[argument].kind == .spread_element) self.nodes[argument].a else argument;
                    try self.prepareExpressionDependencies(target);
                }
            },
            .template_literal => {
                var current = node.a;
                while (current != none) : (current = self.nodes[current].next) {
                    const part = self.nodes[current];
                    if (part.kind != .template_part) return error.BytecodeInvalid;
                    if (part.a != none) try self.prepareExpressionDependencies(part.a);
                }
            },
            .tagged_template => {
                try self.prepareExpressionDependencies(node.a);
                const literal = self.nodes[node.b];
                if (literal.kind != .template_literal) return error.BytecodeInvalid;
                var current = literal.a;
                while (current != none) : (current = self.nodes[current].next) {
                    const part = self.nodes[current];
                    if (part.kind != .template_part) return error.BytecodeInvalid;
                    if (part.a != none) try self.prepareExpressionDependencies(part.a);
                }
            },
            .optional_chain => {
                const base = self.nodes[node.a];
                if (base.kind == .member) {
                    if (base.flags & flag_super == 0) _ = try self.compileExpressionSegment(base.a);
                    if (base.flags & flag_computed != 0) _ = try self.compileExpressionSegment(base.b);
                } else {
                    _ = try self.compileExpressionSegment(node.a);
                }
                var current = node.b;
                while (current != none) : (current = self.nodes[current].next) {
                    const step = self.nodes[current];
                    switch (step.kind) {
                        .chain_member => {
                            if (step.flags & flag_computed != 0) _ = try self.compileExpressionSegment(step.a);
                        },
                        .chain_call => {
                            var argument = step.a;
                            while (argument != none) : (argument = self.nodes[argument].next) {
                                const target = if (self.nodes[argument].kind == .spread_element) self.nodes[argument].a else argument;
                                _ = try self.compileExpressionSegment(target);
                            }
                        },
                        else => return error.BytecodeInvalid,
                    }
                }
            },
            .parameter => {
                if (node.a != none) try self.prepareExpressionDependencies(node.a);
                if (node.b != none) try self.preparePatternDependencies(node.b, true);
            },
            .group => try self.prepareExpressionDependencies(node.a),
            .spread_element => try self.prepareExpressionDependencies(node.a),
            .array_literal => {
                var current = node.a;
                while (current != none) : (current = self.nodes[current].next) {
                    if (self.nodes[current].kind == .empty and self.nodes[current].flags & flag_elision != 0) continue;
                    try self.prepareExpressionDependencies(current);
                }
            },
            .object_literal => {
                var current = node.a;
                while (current != none) : (current = self.nodes[current].next) {
                    const property = self.nodes[current];
                    if (property.flags & flag_elision != 0 and property.flags & flag_spread == 0) return error.SyntaxError;
                    if (property.flags & flag_spread != 0) {
                        try self.prepareExpressionDependencies(property.a);
                        continue;
                    }
                    if (property.flags & flag_computed != 0) try self.prepareExpressionDependencies(property.b);
                    try self.prepareExpressionDependencies(property.a);
                }
            },
            .function_expression => try self.compileFunctionDependencies(index),
            .yield_expression => if (node.a != none) try self.prepareExpressionDependencies(node.a),
            .await_expression => try self.prepareExpressionDependencies(node.a),
            .class_expression => try self.compileClassDependencies(index),
            .unary => {
                const operation: UnaryOp = @enumFromInt(node.flags);
                if (operation == .delete_value) {
                    if (self.nodes[node.a].kind == .optional_chain)
                        try self.prepareExpressionDependencies(node.a)
                    else
                        try self.prepareAssignableDependencies(node.a);
                } else try self.prepareExpressionDependencies(node.a);
            },
            .binary => {
                try self.prepareExpressionDependencies(node.a);
                const operation: BinaryOp = @enumFromInt(node.flags);
                if (operation == .logical_and or operation == .logical_or or operation == .nullish)
                    _ = try self.compileExpressionSegment(node.b)
                else
                    try self.prepareExpressionDependencies(node.b);
            },
            .conditional => {
                try self.prepareExpressionDependencies(node.a);
                _ = try self.compileExpressionSegment(node.b);
                _ = try self.compileExpressionSegment(node.c);
            },
            .assignment => {
                const operation: AssignmentOp = @enumFromInt(node.flags);
                if (isPatternKind(self.nodes[node.a].kind)) {
                    if (operation != .assign) return error.InvalidAssignment;
                    try self.preparePatternDependencies(node.a, false);
                    try self.prepareExpressionDependencies(node.b);
                    return;
                }
                try self.prepareAssignableDependencies(node.a);
                if (isLogicalAssignment(operation))
                    _ = try self.compileExpressionSegment(node.b)
                else
                    try self.prepareExpressionDependencies(node.b);
            },
            .update => try self.prepareAssignableDependencies(node.a),
            .member => {
                if (node.flags & flag_super == 0) try self.prepareExpressionDependencies(node.a);
                if (node.flags & flag_computed != 0) try self.prepareExpressionDependencies(node.b);
            },
            .call => {
                try self.prepareExpressionDependencies(node.a);
                var current = node.b;
                while (current != none) : (current = self.nodes[current].next) try self.prepareExpressionDependencies(current);
            },
            .new_expression => try self.prepareExpressionDependencies(node.a),
            else => {
                if (isStatementKind(node.kind)) {
                    _ = try self.compileStatementSegment(index);
                } else {
                    return error.BytecodeInvalid;
                }
            },
        }
    }

    fn emitVarHoists(self: *Program, first: u16) Error!void {
        var current = first;
        while (current != none) : (current = self.nodes[current].next) {
            const node = self.nodes[current];
            if (node.kind == .variable and node.flags & flag_var != 0) {
                try self.emitPatternVarHoists(node.b);
                continue;
            }
            switch (node.kind) {
                .block, .program => try self.emitVarHoists(node.a),
                .if_statement => {
                    try self.emitVarHoistNode(node.b);
                    try self.emitVarHoistNode(node.c);
                },
                .while_statement, .do_while_statement => try self.emitVarHoistNode(node.b),
                .for_statement => {
                    try self.emitVarHoistNode(node.a);
                    try self.emitVarHoistNode(node.d);
                },
                .for_in_statement, .for_of_statement => {
                    try self.emitVarHoistNode(node.a);
                    try self.emitVarHoistNode(node.c);
                },
                .switch_statement => {
                    var case_index = node.b;
                    while (case_index != none) : (case_index = self.nodes[case_index].next) {
                        try self.emitVarHoists(self.nodes[case_index].b);
                    }
                },
                .labeled_statement => try self.emitVarHoistNode(node.a),
                .try_statement => {
                    try self.emitVarHoistNode(node.a);
                    try self.emitVarHoistNode(node.b);
                    try self.emitVarHoistNode(node.c);
                },
                else => {},
            }
        }
    }

    fn emitPatternVarHoists(self: *Program, index: u16) Error!void {
        if (index == none or index >= self.node_count) return error.BytecodeInvalid;
        const pattern = self.nodes[index];
        if (pattern.kind == .identifier) {
            try self.emitBytecode(.hoist_var, index, 0, none, none);
            return;
        }
        if (!isPatternKind(pattern.kind)) return error.BytecodeInvalid;
        var current = pattern.a;
        while (current != none) : (current = self.nodes[current].next) {
            const element = self.nodes[current];
            if (element.kind != .pattern_element) return error.BytecodeInvalid;
            if (element.a != none) try self.emitPatternVarHoists(element.a);
        }
    }

    fn emitVarHoistNode(self: *Program, index: u16) Error!void {
        if (index == none) return;
        const node = self.nodes[index];
        if (node.kind == .variable and node.flags & flag_var != 0) {
            try self.emitPatternVarHoists(node.b);
        } else if (node.kind != .function_declaration) {
            if (node.kind == .block or node.kind == .program)
                try self.emitVarHoists(node.a)
            else
                try self.emitVarHoists(index);
        }
    }

    fn compileStatementList(self: *Program, first: u16) Error!void {
        var current = first;
        while (current != none) : (current = self.nodes[current].next) {
            if (self.nodes[current].kind == .function_declaration)
                try self.emitBytecode(.function_declaration, current, 0, none, none);
        }
        current = first;
        while (current != none) : (current = self.nodes[current].next) {
            try self.emitBytecode(.block, current, 0, try self.segmentForNode(current), none);
        }
    }

    fn compileStatement(self: *Program, index: u16) Error!void {
        const node = self.nodes[index];
        switch (node.kind) {
            .empty => {
                try self.emitBytecode(.push_undefined, index, 0, none, none);
                try self.emitBytecode(.expression_result, index, 0, none, none);
            },
            .program, .block, .switch_case => try self.emitBytecode(.block, index, 0, try self.segmentForNode(index), none),
            .expression_statement => {
                const expression = if (node.a != none and node.a < self.node_count) self.nodes[node.a] else Node{};
                if (expression.kind == .conditional) {
                    var remaining: usize = max_fused_expression_nodes;
                    if (self.primitiveConditionalCandidate(node.a, &remaining)) {
                        const fast_pc = self.bytecode_count;
                        try self.emitBytecode(.primitive_conditional_statement, node.a, 0, 0, none);
                        try self.compileExpression(node.a);
                        try self.emitBytecode(.expression_result, index, 0, none, none);
                        const fallback_count = self.bytecode_count - fast_pc - 1;
                        if (fallback_count > std.math.maxInt(u16)) return error.BytecodeLimit;
                        self.workspace.compiled.instructions[fast_pc].b = @intCast(fallback_count);
                        return;
                    }
                }
                var expression_remaining: usize = max_fused_expression_nodes;
                if (self.numericExpressionCandidate(node.a, &expression_remaining)) {
                    const fast_pc = self.bytecode_count;
                    try self.emitBytecode(.numeric_expression_statement, node.a, 0, 0, none);
                    try self.compileExpression(node.a);
                    try self.emitBytecode(.expression_result, index, 0, none, none);
                    const fallback_count = self.bytecode_count - fast_pc - 1;
                    if (fallback_count > std.math.maxInt(u16)) return error.BytecodeLimit;
                    self.workspace.compiled.instructions[fast_pc].b = @intCast(fallback_count);
                    return;
                }
                if (expression.kind == .assignment and expression.a != none and expression.a < self.node_count and
                    self.nodes[expression.a].kind == .identifier and !isLogicalAssignment(@enumFromInt(expression.flags)))
                {
                    var remaining: usize = max_fused_expression_nodes;
                    if (self.numericExpressionCandidate(expression.b, &remaining)) {
                        const fast_pc = self.bytecode_count;
                        try self.emitBytecode(.primitive_assignment_statement, node.a, 0, 0, none);
                        try self.compileExpression(node.a);
                        try self.emitBytecode(.expression_result, index, 0, none, none);
                        const fallback_count = self.bytecode_count - fast_pc - 1;
                        if (fallback_count > std.math.maxInt(u16)) return error.BytecodeLimit;
                        self.workspace.compiled.instructions[fast_pc].b = @intCast(fallback_count);
                        return;
                    }
                }
                try self.compileExpression(node.a);
                try self.emitBytecode(.expression_result, index, 0, none, none);
            },
            .variable => {
                if (node.a == none) {
                    try self.emitBytecode(.push_undefined, index, 0, none, none);
                } else {
                    var remaining: usize = max_fused_expression_nodes;
                    if (self.numericExpressionCandidate(node.a, &remaining)) {
                        const fast_pc = self.bytecode_count;
                        try self.emitBytecode(.numeric_variable, index, 0, 0, none);
                        try self.compileExpression(node.a);
                        try self.emitBytecode(.variable, index, 0, none, none);
                        const fallback_count = self.bytecode_count - fast_pc - 1;
                        if (fallback_count > std.math.maxInt(u16)) return error.BytecodeLimit;
                        self.workspace.compiled.instructions[fast_pc].b = @intCast(fallback_count);
                        return;
                    }
                    try self.compileExpression(node.a);
                }
                try self.emitBytecode(.variable, index, 0, none, none);
            },
            .function_declaration => try self.emitBytecode(.function_declaration, index, 0, none, none),
            .class_declaration => try self.emitBytecode(.class_declaration, index, 0, none, none),
            .return_statement => if (node.a == none)
                try self.emitBytecode(.return_undefined, index, 0, none, none)
            else {
                var remaining: usize = max_fused_expression_nodes;
                if (self.numericExpressionCandidate(node.a, &remaining)) {
                    try self.emitBytecode(.numeric_return_value, node.a, 0, 0, none);
                    try self.compileExpression(node.a);
                    try self.emitBytecode(.return_value, index, 0, none, none);
                    return;
                }
                try self.compileExpression(node.a);
                try self.emitBytecode(.return_value, index, 0, none, none);
            },
            .throw_statement => {
                try self.compileExpression(node.a);
                try self.emitBytecode(.throw_value, index, 0, none, none);
            },
            .if_statement => try self.emitBytecode(.if_statement, index, 0, none, none),
            .while_statement => try self.emitBytecode(.while_statement, index, 0, none, none),
            .do_while_statement => try self.emitBytecode(.do_while_statement, index, 0, none, none),
            .for_statement => try self.emitBytecode(.for_statement, index, 0, none, none),
            .for_in_statement => try self.emitBytecode(.for_in_statement, index, 0, none, none),
            .for_of_statement => try self.emitBytecode(.for_of_statement, index, 0, none, none),
            .switch_statement => try self.emitBytecode(.switch_statement, index, 0, none, none),
            .labeled_statement => try self.emitBytecode(.labeled_statement, index, 0, none, none),
            .break_statement => try self.emitBytecode(.break_statement, index, 0, none, none),
            .continue_statement => try self.emitBytecode(.continue_statement, index, 0, none, none),
            .with_statement => try self.emitBytecode(.with_statement, index, 0, none, none),
            .try_statement => try self.emitBytecode(.try_statement, index, 0, none, none),
            .import_statement => try self.emitBytecode(.import_statement, index, 0, none, none),
            .export_list => try self.emitBytecode(.export_list, index, 0, none, none),
            .export_default => {
                try self.compileExpression(node.a);
                try self.emitBytecode(.export_default, index, 0, none, none);
            },
            else => {
                try self.compileExpression(index);
                try self.emitBytecode(.expression_result, index, 0, none, none);
            },
        }
    }

    fn compileMemberReference(self: *Program, index: u16) Error!void {
        const member = self.nodes[index];
        if (member.kind != .member) return error.InvalidAssignment;
        if (member.flags & (flag_computed | flag_private | flag_super) == 0 and member.a != none and
            member.a < self.node_count and self.nodes[member.a].kind == .identifier)
        {
            try self.emitBytecode(.named_member_reference_identifier, index, 0, none, none);
            return;
        }
        if (member.flags & flag_super != 0)
            try self.emitBytecode(.load_super_receiver, index, 0, none, none)
        else
            try self.compileExpression(member.a);
        if (member.flags & flag_computed != 0)
            try self.compileExpression(member.b)
        else
            try self.emitBytecode(.push_property_name, index, 0, none, none);
    }

    fn compileSuperCall(self: *Program, index: u16) Error!void {
        const node = self.nodes[index];
        if (node.kind != .super_call) return error.BytecodeInvalid;
        var has_spread = false;
        var argument = node.a;
        while (argument != none) : (argument = self.nodes[argument].next) {
            if (self.nodes[argument].kind == .spread_element) has_spread = true;
        }
        if (has_spread) {
            try self.emitBytecode(.array_begin, index, 0, none, none);
            argument = node.a;
            while (argument != none) : (argument = self.nodes[argument].next) {
                const item = self.nodes[argument];
                if (item.kind == .spread_element) {
                    try self.compileExpression(item.a);
                    try self.emitBytecode(.array_spread, argument, 0, none, none);
                } else {
                    try self.compileExpression(argument);
                    try self.emitBytecode(.array_append, argument, 0, none, none);
                }
            }
            try self.emitBytecode(.super_call_spread, index, 0, none, none);
            return;
        }
        var argument_count: usize = 0;
        argument = node.a;
        while (argument != none) : (argument = self.nodes[argument].next) {
            if (argument_count >= max_parameters) return error.RangeError;
            try self.compileExpression(argument);
            argument_count += 1;
        }
        try self.emitBytecode(.super_call, index, 0, @intCast(argument_count), none);
    }

    fn optionalChainContainsPrivate(self: *const Program, index: u16) bool {
        if (index == none or index >= self.node_count) return false;
        const chain = self.nodes[index];
        if (chain.kind != .optional_chain) return false;
        if (self.nodes[chain.a].kind == .member and self.nodes[chain.a].flags & flag_private != 0) return true;
        var current = chain.b;
        while (current != none) : (current = self.nodes[current].next) {
            if (self.nodes[current].kind == .chain_member and self.nodes[current].flags & flag_private != 0) return true;
        }
        return false;
    }

    fn compileCall(self: *Program, index: u16, construct: bool) Error!void {
        const node = self.nodes[index];
        if (node.kind != .call) return error.BytecodeInvalid;
        const callee = self.nodes[node.a];
        if (callee.kind == .member) {
            if (callee.flags & (flag_computed | flag_private | flag_super) == 0 and callee.a != none and
                callee.a < self.node_count and self.nodes[callee.a].kind == .identifier)
            {
                try self.emitBytecode(.prepare_named_member_call_identifier, node.a, 0, none, none);
            } else {
                try self.compileMemberReference(node.a);
                try self.emitBytecode(.prepare_member_call, node.a, 0, none, none);
            }
        } else if (callee.kind == .identifier) {
            try self.emitBytecode(.prepare_identifier_call, node.a, 0, none, none);
        } else {
            try self.emitBytecode(.push_undefined, node.a, 0, none, none);
            try self.compileExpression(node.a);
        }
        var has_spread = false;
        var argument = node.b;
        while (argument != none) : (argument = self.nodes[argument].next) {
            if (self.nodes[argument].kind == .spread_element) has_spread = true;
        }
        if (has_spread) {
            try self.emitBytecode(.array_begin, index, 0, none, none);
            argument = node.b;
            while (argument != none) : (argument = self.nodes[argument].next) {
                const item = self.nodes[argument];
                if (item.kind == .spread_element) {
                    try self.compileExpression(item.a);
                    try self.emitBytecode(.array_spread, argument, 0, none, none);
                } else {
                    try self.compileExpression(argument);
                    try self.emitBytecode(.array_append, argument, 0, none, none);
                }
            }
            try self.emitBytecode(.call_spread, index, if (construct) 1 else 0, none, none);
            return;
        }
        var argument_count: usize = 0;
        var current = node.b;
        while (current != none) : (current = self.nodes[current].next) {
            if (argument_count >= max_parameters) return error.RangeError;
            try self.compileExpression(current);
            argument_count += 1;
        }
        try self.emitBytecode(.call, index, if (construct) 1 else 0, @intCast(argument_count), none);
    }

    fn numericExpressionCandidate(self: *const Program, index: u16, remaining: *usize) bool {
        if (index == none or index >= self.node_count or remaining.* == 0) return false;
        remaining.* -= 1;
        const node = self.nodes[index];
        return switch (node.kind) {
            .number_literal, .string_literal, .boolean_literal, .null_literal, .undefined_literal, .identifier, .this_expression => true,
            .unary => blk: {
                const operation: UnaryOp = @enumFromInt(node.flags);
                break :blk operation != .delete_value and self.numericExpressionCandidate(node.a, remaining);
            },
            .binary => self.numericExpressionCandidate(node.a, remaining) and self.numericExpressionCandidate(node.b, remaining),
            .assignment => !isLogicalAssignment(@enumFromInt(node.flags)) and
                self.numericAssignmentTargetCandidate(node.a, remaining) and self.numericExpressionCandidate(node.b, remaining),
            .update => self.numericAssignmentTargetCandidate(node.a, remaining),
            .member => node.flags & (flag_private | flag_super) == 0 and self.numericExpressionCandidate(node.a, remaining) and
                (node.flags & flag_computed == 0 or self.numericExpressionCandidate(node.b, remaining)),
            .call => self.numericCallCandidate(index, remaining),
            else => false,
        };
    }

    fn numericCallCandidate(self: *const Program, node_index: u16, remaining: *usize) bool {
        const call_node = self.nodes[node_index];
        if (call_node.a == none or call_node.a >= self.node_count) return false;
        const callee = self.nodes[call_node.a];
        switch (callee.kind) {
            .identifier => if (equals(self.text(callee.text), "eval")) return false,
            .member => if (!self.numericAssignmentTargetCandidate(call_node.a, remaining)) return false,
            else => return false,
        }
        var argument = call_node.b;
        while (argument != none) : (argument = self.nodes[argument].next) {
            if (argument >= self.node_count or self.nodes[argument].kind == .spread_element or
                !self.numericExpressionCandidate(argument, remaining)) return false;
        }
        return true;
    }

    fn numericAssignmentTargetCandidate(self: *const Program, index: u16, remaining: *usize) bool {
        if (index == none or index >= self.node_count) return false;
        const target = self.nodes[index];
        if (target.kind == .identifier) return true;
        return target.kind == .member and target.flags & (flag_private | flag_super) == 0 and
            self.numericExpressionCandidate(target.a, remaining) and
            (target.flags & flag_computed == 0 or self.numericExpressionCandidate(target.b, remaining));
    }

    fn primitiveConditionalCandidate(self: *const Program, index: u16, remaining: *usize) bool {
        if (index == none or index >= self.node_count or remaining.* == 0) return false;
        remaining.* -= 1;
        const node = self.nodes[index];
        return node.kind == .conditional and self.numericExpressionCandidate(node.a, remaining);
    }

    fn compileExpression(self: *Program, index: u16) Error!void {
        if (index != none and index < self.node_count) {
            const node = self.nodes[index];
            const kind = node.kind;
            if (kind == .conditional) {
                var remaining: usize = max_fused_expression_nodes;
                if (self.primitiveConditionalCandidate(index, &remaining)) {
                    const fast_pc = self.bytecode_count;
                    try self.emitBytecode(.primitive_conditional, index, 0, 0, none);
                    try self.compileExpressionRaw(index);
                    const fallback_count = self.bytecode_count - fast_pc - 1;
                    if (fallback_count > std.math.maxInt(u16)) return error.BytecodeLimit;
                    self.workspace.compiled.instructions[fast_pc].b = @intCast(fallback_count);
                    return;
                }
            }
            if (kind == .assignment and node.a != none and node.a < self.node_count and self.nodes[node.a].kind == .identifier and
                !isLogicalAssignment(@enumFromInt(node.flags)))
            {
                var remaining: usize = max_fused_expression_nodes;
                if (self.numericExpressionCandidate(node.b, &remaining)) {
                    const fast_pc = self.bytecode_count;
                    try self.emitBytecode(.primitive_assignment, index, 0, 0, none);
                    try self.compileExpressionRaw(index);
                    const fallback_count = self.bytecode_count - fast_pc - 1;
                    if (fallback_count > std.math.maxInt(u16)) return error.BytecodeLimit;
                    self.workspace.compiled.instructions[fast_pc].b = @intCast(fallback_count);
                    return;
                }
            }
            if (kind == .unary or kind == .binary) {
                var remaining: usize = max_fused_expression_nodes;
                if (self.numericExpressionCandidate(index, &remaining)) {
                    const fast_pc = self.bytecode_count;
                    try self.emitBytecode(.numeric_expression, index, 0, 0, none);
                    try self.compileExpressionRaw(index);
                    const fallback_count = self.bytecode_count - fast_pc - 1;
                    if (fallback_count > std.math.maxInt(u16)) return error.BytecodeLimit;
                    self.workspace.compiled.instructions[fast_pc].b = @intCast(fallback_count);
                    return;
                }
            }
        }
        try self.compileExpressionRaw(index);
    }

    fn compileExpressionRaw(self: *Program, index: u16) Error!void {
        if (index == none) {
            try self.emitBytecode(.push_undefined, none, 0, none, none);
            return;
        }
        const node = self.nodes[index];
        switch (node.kind) {
            .number_literal => try self.emitBytecode(.push_number, index, 0, none, none),
            .bigint_literal => try self.emitBytecode(.push_bigint, index, 0, none, none),
            .string_literal => try self.emitBytecode(.push_string, index, 0, none, none),
            .regex_literal => try self.emitBytecode(.push_regex, index, 0, none, none),
            .boolean_literal => try self.emitBytecode(.push_boolean, index, @intCast(node.flags & 1), none, none),
            .null_literal => try self.emitBytecode(.push_null, index, 0, none, none),
            .undefined_literal => try self.emitBytecode(.push_undefined, index, 0, none, none),
            .group => try self.compileExpression(node.a),
            .template_literal => {
                var current = node.a;
                if (current == none or self.nodes[current].kind != .template_part) return error.BytecodeInvalid;
                try self.emitBytecode(.push_string, current, 0, none, none);
                while (self.nodes[current].a != none) {
                    try self.compileExpression(self.nodes[current].a);
                    try self.emitBytecode(.binary, self.nodes[current].a, @intFromEnum(BinaryOp.add), none, none);
                    current = self.nodes[current].next;
                    if (current == none or self.nodes[current].kind != .template_part) return error.BytecodeInvalid;
                    try self.emitBytecode(.push_string, current, 0, none, none);
                    try self.emitBytecode(.binary, current, @intFromEnum(BinaryOp.add), none, none);
                }
                if (self.nodes[current].next != none) return error.BytecodeInvalid;
            },
            .tagged_template => {
                const tag = self.nodes[node.a];
                if (tag.kind == .member) {
                    try self.compileMemberReference(node.a);
                    try self.emitBytecode(.prepare_member_call, node.a, 0, none, none);
                } else {
                    try self.emitBytecode(.push_undefined, node.a, 0, none, none);
                    try self.compileExpression(node.a);
                }
                try self.emitBytecode(.push_template_object, node.b, 0, none, none);
                const literal = self.nodes[node.b];
                var argument_count: usize = 1;
                var current = literal.a;
                while (current != none) : (current = self.nodes[current].next) {
                    const part = self.nodes[current];
                    if (part.a == none) continue;
                    if (argument_count >= max_parameters) return error.RangeError;
                    try self.compileExpression(part.a);
                    argument_count += 1;
                }
                try self.emitBytecode(.call, index, 0, @intCast(argument_count), none);
            },
            .optional_chain => try self.emitBytecode(.optional_chain, index, 0, none, none),
            .identifier => try self.emitBytecode(.load_identifier, index, 0, none, none),
            .array_literal => {
                try self.emitBytecode(.array_begin, index, 0, none, none);
                var current = node.a;
                while (current != none) : (current = self.nodes[current].next) {
                    const item = self.nodes[current];
                    if (item.kind == .spread_element) {
                        try self.compileExpression(item.a);
                        try self.emitBytecode(.array_spread, current, 0, none, none);
                    } else {
                        if (item.kind == .empty and item.flags & flag_elision != 0)
                            try self.emitBytecode(.push_undefined, current, 0, none, none)
                        else
                            try self.compileExpression(current);
                        try self.emitBytecode(.array_append, current, if (item.kind == .empty and item.flags & flag_elision != 0) 1 else 0, none, none);
                    }
                }
            },
            .object_literal => {
                try self.emitBytecode(.object_begin, index, 0, none, none);
                var current = node.a;
                while (current != none) : (current = self.nodes[current].next) {
                    const property = self.nodes[current];
                    if (property.flags & flag_spread != 0) {
                        try self.compileExpression(property.a);
                        try self.emitBytecode(.object_spread, current, 0, none, none);
                        continue;
                    }
                    if (property.flags & flag_computed != 0)
                        try self.compileExpression(property.b)
                    else if (property.flags & flag_key_number != 0)
                        try self.emitBytecode(.push_number, current, 0, none, none)
                    else if (property.flags & flag_key_string != 0)
                        try self.emitBytecode(.push_string, current, 0, none, none)
                    else
                        try self.emitBytecode(.push_property_name, current, 0, none, none);
                    try self.compileExpression(property.a);
                    try self.emitBytecode(.object_set, current, 0, none, none);
                }
            },
            .function_expression => try self.emitBytecode(.make_function, index, 0, none, none),
            .yield_expression => {
                try self.compileExpression(node.a);
                try self.emitBytecode(.yield_value, index, @intCast(node.flags & flag_yield_delegate), none, none);
            },
            .await_expression => {
                try self.compileExpression(node.a);
                try self.emitBytecode(.await_value, index, 0, none, none);
            },
            .dynamic_import => {
                try self.compileExpression(node.a);
                try self.emitBytecode(.dynamic_import, index, 0, none, none);
            },
            .import_meta => try self.emitBytecode(.import_meta, index, 0, none, none),
            .this_expression => try self.emitBytecode(.load_this, index, 0, none, none),
            .new_target => try self.emitBytecode(.load_new_target, index, 0, none, none),
            .class_expression => try self.emitBytecode(.make_class, index, 0, none, none),
            .private_in => {
                try self.compileExpression(node.a);
                try self.emitBytecode(.private_in, index, 0, none, none);
            },
            .private_identifier => return error.SyntaxError,
            .super_call => try self.compileSuperCall(index),
            .super_reference => return error.SyntaxError,
            .unary => {
                const operation: UnaryOp = @enumFromInt(node.flags);
                if (operation == .type_of and self.nodes[node.a].kind == .identifier) {
                    try self.emitBytecode(.type_of_identifier, node.a, 0, none, none);
                } else if (operation == .delete_value) {
                    const target = self.nodes[node.a];
                    switch (target.kind) {
                        .identifier => try self.emitBytecode(.delete_identifier, node.a, 0, none, none),
                        .member => {
                            if (target.flags & (flag_private | flag_super) != 0) return error.SyntaxError;
                            try self.compileMemberReference(node.a);
                            try self.emitBytecode(.delete_member, node.a, 0, none, none);
                        },
                        .optional_chain => {
                            if (self.optionalChainContainsPrivate(node.a)) return error.SyntaxError;
                            try self.emitBytecode(.optional_chain, node.a, 1, none, none);
                        },
                        else => return error.InvalidAssignment,
                    }
                } else {
                    try self.compileExpression(node.a);
                    try self.emitBytecode(.unary, index, @intCast(node.flags), none, none);
                }
            },
            .binary => {
                try self.compileExpression(node.a);
                const operation: BinaryOp = @enumFromInt(node.flags);
                if (operation == .logical_and or operation == .logical_or or operation == .nullish) {
                    try self.emitBytecode(.short_binary, index, @intCast(node.flags), try self.segmentForNode(node.b), none);
                } else {
                    try self.compileExpression(node.b);
                    try self.emitBytecode(.binary, index, @intCast(node.flags), none, none);
                }
            },
            .conditional => {
                try self.compileExpression(node.a);
                try self.emitBytecode(.conditional, index, 0, try self.segmentForNode(node.b), try self.segmentForNode(node.c));
            },
            .assignment => {
                const target = self.nodes[node.a];
                const operation: AssignmentOp = @enumFromInt(node.flags);
                switch (target.kind) {
                    .array_pattern, .object_pattern => {
                        if (operation != .assign) return error.InvalidAssignment;
                        try self.compileExpression(node.b);
                        try self.emitBytecode(.assign_pattern, index, 0, none, none);
                    },
                    .identifier => {
                        if (isLogicalAssignment(operation)) {
                            try self.emitBytecode(.load_identifier, node.a, 0, none, none);
                            try self.emitBytecode(.logical_assign_identifier, node.a, @intCast(node.flags), try self.segmentForNode(node.b), none);
                        } else {
                            if (operation != .assign) try self.emitBytecode(.load_identifier, node.a, 0, none, none);
                            try self.compileExpression(node.b);
                            try self.emitBytecode(.assign_identifier, node.a, @intCast(node.flags), none, none);
                        }
                    },
                    .member => {
                        try self.compileMemberReference(node.a);
                        if (isLogicalAssignment(operation)) {
                            try self.emitBytecode(.load_member_for_assignment, node.a, 0, none, none);
                            try self.emitBytecode(.logical_assign_member, node.a, @intCast(node.flags), try self.segmentForNode(node.b), none);
                        } else {
                            if (operation != .assign) try self.emitBytecode(.load_member_for_assignment, node.a, 0, none, none);
                            try self.compileExpression(node.b);
                            try self.emitBytecode(.assign_member, node.a, @intCast(node.flags), none, none);
                        }
                    },
                    else => return error.InvalidAssignment,
                }
            },
            .update => {
                const target = self.nodes[node.a];
                switch (target.kind) {
                    .identifier => {
                        try self.emitBytecode(.load_identifier, node.a, 0, none, none);
                        try self.emitBytecode(.update_identifier, node.a, @intCast(node.flags), none, none);
                    },
                    .member => {
                        try self.compileMemberReference(node.a);
                        try self.emitBytecode(.update_member, node.a, @intCast(node.flags), none, none);
                    },
                    else => return error.InvalidAssignment,
                }
            },
            .member => {
                if (node.flags & (flag_computed | flag_private | flag_super) == 0 and node.a != none and
                    node.a < self.node_count and self.nodes[node.a].kind == .identifier)
                {
                    try self.emitBytecode(.get_named_member_identifier, index, 0, none, none);
                } else {
                    try self.compileMemberReference(index);
                    try self.emitBytecode(.get_member, index, 0, none, none);
                }
            },
            .call => try self.compileCall(index, false),
            .new_expression => {
                if (self.nodes[node.a].kind == .call) {
                    try self.compileCall(node.a, true);
                } else {
                    try self.emitBytecode(.push_undefined, node.a, 0, none, none);
                    try self.compileExpression(node.a);
                    try self.emitBytecode(.call, index, 1, 0, none);
                }
            },
            else => return error.BytecodeInvalid,
        }
    }

    pub fn validateBytecode(self: *Program) Error!void {
        if (self.root_segment == none or self.root_segment >= self.bytecode_segment_count) return error.BytecodeInvalid;
        if (self.bytecode_count > self.workspace.compiled.instructions.len or self.bytecode_segment_count > self.workspace.compiled.segment_starts.len)
            return error.BytecodeInvalid;
        var segment_index: usize = 0;
        while (segment_index < self.bytecode_segment_count) : (segment_index += 1) {
            const segment = self.bytecodeSegment(@intCast(segment_index));
            const start: usize = segment.start;
            const end: usize = segment.end;
            if (start > end or end > self.bytecode_count) return error.BytecodeInvalid;
            if (segment.node == none or segment.node >= self.node_count) return error.BytecodeInvalid;
            var depth: usize = 0;
            var peak: usize = 0;
            for (self.workspace.compiled.instructions[start..end]) |instruction| {
                if (instruction.a != none and instruction.a >= self.node_count) return error.BytecodeInvalid;
                var required: usize = 0;
                var remove: usize = 0;
                var add: usize = 0;
                switch (instruction.op) {
                    .push_undefined,
                    .push_null,
                    .push_boolean,
                    .push_number,
                    .push_bigint,
                    .push_string,
                    .push_template_object,
                    .push_regex,
                    .load_identifier,
                    .array_begin,
                    .object_begin,
                    .make_function,
                    .make_class,
                    .type_of_identifier,
                    .delete_identifier,
                    .push_property_name,
                    .optional_chain,
                    .load_super_receiver,
                    .import_meta,
                    .load_this,
                    .load_new_target,
                    .get_named_member_identifier,
                    => add = 1,
                    .prepare_identifier_call, .named_member_reference_identifier, .prepare_named_member_call_identifier => add = 2,
                    .array_append, .array_spread, .object_spread, .binary => {
                        required = 2;
                        remove = 2;
                        add = 1;
                    },
                    .object_set => {
                        required = 3;
                        remove = 2;
                    },
                    .unary, .short_binary, .conditional, .update_identifier, .private_in, .yield_value, .await_value, .dynamic_import => {
                        required = 1;
                        remove = 1;
                        add = 1;
                    },
                    .load_member_for_assignment => {
                        required = 2;
                        add = 1;
                    },
                    .assign_identifier => {
                        const operation: AssignmentOp = @enumFromInt(instruction.flags);
                        required = if (operation == .assign) 1 else 2;
                        remove = required;
                        add = 1;
                    },
                    .assign_pattern => {
                        required = 1;
                        remove = 1;
                        add = 1;
                    },
                    .logical_assign_identifier => {
                        required = 1;
                        remove = 1;
                        add = 1;
                    },
                    .assign_member => {
                        const operation: AssignmentOp = @enumFromInt(instruction.flags);
                        required = if (operation == .assign) 3 else 4;
                        remove = required;
                        add = 1;
                    },
                    .logical_assign_member => {
                        required = 3;
                        remove = 3;
                        add = 1;
                    },
                    .delete_member, .update_member, .get_member => {
                        required = 2;
                        remove = 2;
                        add = 1;
                    },
                    .prepare_member_call => required = 2,
                    .call => {
                        required = @as(usize, instruction.b) + 2;
                        remove = required;
                        add = 1;
                    },
                    .call_spread => {
                        required = 3;
                        remove = 3;
                        add = 1;
                    },
                    .super_call => {
                        required = instruction.b;
                        remove = instruction.b;
                        add = 1;
                    },
                    .super_call_spread => {
                        required = 1;
                        remove = 1;
                        add = 1;
                    },
                    .expression_result, .variable, .return_value, .throw_value, .export_default => {
                        required = 1;
                        remove = 1;
                    },
                    else => {},
                }
                if (depth < required or depth < remove) return error.BytecodeStack;
                depth -= remove;
                if (add > max_bytecode_stack -| depth) return error.BytecodeStack;
                depth += add;
                peak = @max(peak, depth);
                switch (instruction.op) {
                    .block => if (instruction.b == none or instruction.b >= self.bytecode_segment_count) return error.BytecodeInvalid,
                    .short_binary => if (instruction.b == none or instruction.b >= self.bytecode_segment_count) return error.BytecodeInvalid,
                    .logical_assign_identifier, .logical_assign_member => if (instruction.b == none or instruction.b >= self.bytecode_segment_count) return error.BytecodeInvalid,
                    .conditional => if (instruction.b == none or instruction.b >= self.bytecode_segment_count or instruction.c == none or instruction.c >= self.bytecode_segment_count) return error.BytecodeInvalid,
                    else => {},
                }
            }
            const expected: usize = if (segment.kind == .expression) 1 else 0;
            if (depth != expected) return error.BytecodeStack;
            self.workspace.compiled.segment_max_stacks[segment_index] = @intCast(peak);
        }
    }

    pub fn bytecodeReady(self: *const Program) bool {
        return self.bytecode_valid and
            self.bytecode_generation != 0 and
            self.bytecode_parse_generation == self.parse_generation;
    }

    /// Returns the immutable bytecode generation used by execution caches.
    /// Zero means that parsing or compilation has not produced executable
    /// bytecode for the current parse generation.
    pub fn bytecodeGeneration(self: *const Program) u64 {
        return if (self.bytecodeReady()) self.bytecode_generation else 0;
    }

    /// Performs the expensive full-program fingerprint comparison. Normal,
    /// generator and async calls deliberately use `bytecodeReady` instead;
    /// trusted tooling can request this diagnostic after raw bytecode access.
    pub fn verifyBytecodeIntegrity(self: *const Program) bool {
        return self.bytecodeReady() and
            self.bytecode_signature != 0 and
            self.bytecode_signature == self.bytecodeFingerprint();
    }

    /// Invalidates bytecode before any explicit out-of-band mutation. The
    /// next successful parse/compile publishes a new non-zero generation.
    pub fn invalidateBytecode(self: *Program) void {
        self.bytecode_valid = false;
        self.bytecode_signature = 0;
        self.bytecode_parse_generation = 0;
    }

    fn bytecodeFingerprint(self: *const Program) u64 {
        var hash: u64 = 14695981039346656037;
        hash = bytecodeHashValue(hash, self.bytecode_count);
        hash = bytecodeHashValue(hash, self.bytecode_segment_count);
        hash = bytecodeHashValue(hash, self.root_segment);
        for (self.workspace.compiled.instructions[0..self.bytecode_count]) |instruction| {
            hash = bytecodeHashValue(hash, @intFromEnum(instruction.op));
            hash = bytecodeHashValue(hash, instruction.flags);
            hash = bytecodeHashValue(hash, instruction.a);
            hash = bytecodeHashValue(hash, instruction.b);
            hash = bytecodeHashValue(hash, instruction.c);
        }
        var segment_index: usize = 0;
        while (segment_index < self.bytecode_segment_count) : (segment_index += 1) {
            const segment = self.bytecodeSegment(@intCast(segment_index));
            hash = bytecodeHashValue(hash, segment.start);
            hash = bytecodeHashValue(hash, segment.end);
            hash = bytecodeHashValue(hash, segment.node);
            hash = bytecodeHashValue(hash, segment.max_stack);
            hash = bytecodeHashValue(hash, @intFromEnum(segment.kind));
        }
        return if (hash == 0) 1 else hash;
    }

    fn scanIdentifier(self: *Program, source: []const u8, start: usize) Error!IdentifierScan {
        const storage_start = self.identifier_len;
        var cursor = start;
        var first = true;
        var had_escape = false;
        while (cursor < source.len) {
            const escaped = source[cursor] == '\\';
            had_escape = had_escape or escaped;
            const codepoint = if (escaped)
                try scanUnicodeEscape(source, cursor)
            else
                try decodeSourceCodePoint(source, cursor);
            const allowed = if (first)
                isIdentifierStartCodePoint(codepoint.value)
            else
                isIdentifierContinueCodePoint(codepoint.value);
            if (!allowed) {
                if (first or escaped) return error.SyntaxError;
                break;
            }
            try self.appendIdentifierCodePoint(codepoint.value);
            cursor = codepoint.end;
            first = false;
        }
        if (first) return error.SyntaxError;
        return .{
            .end = cursor,
            .text = makeIdentifierRef(storage_start, self.identifier_len - storage_start),
            .had_escape = had_escape,
        };
    }

    fn tokenize(self: *Program) Error!void {
        const source = self.source[0..self.source_len];
        var cursor: usize = 0;
        var line: u32 = 1;
        var column: u32 = 1;
        errdefer |err| self.recordProgramDiagnostic(.parser, err, cursor);
        var template_brace_depths: [max_call_depth]u16 = [_]u16{0} ** max_call_depth;
        var template_depth: usize = 0;
        while (cursor < source.len) {
            const byte = source[cursor];
            if (byte == '}' and template_depth > 0 and template_brace_depths[template_depth - 1] == 0) {
                const token_line = line;
                advancePosition(byte, &line, &column);
                cursor += 1;
                const chunk = try scanTemplateChunk(source, &cursor, &line, &column);
                try self.addToken(.{
                    .kind = if (chunk.has_substitution) .template_middle else .template_tail,
                    .text = chunk.text,
                    .number = if (templateChunkCookedValid(source[chunk.text.offset..][0..chunk.text.len])) 0 else 1,
                    .line = token_line,
                    .end_line = line,
                });
                if (!chunk.has_substitution) template_depth -= 1;
                continue;
            }
            const source_codepoint = try decodeSourceCodePoint(source, cursor);
            if (isEcmaWhiteSpace(source_codepoint.value) or isEcmaLineTerminator(source_codepoint.value)) {
                try advanceSourcePosition(source, &cursor, &line, &column);
                continue;
            }
            if (cursor == 0 and byte == '#' and cursor + 1 < source.len and source[cursor + 1] == '!') {
                cursor += 2;
                column += 2;
                while (cursor < source.len) {
                    const current = try decodeSourceCodePoint(source, cursor);
                    if (isEcmaLineTerminator(current.value)) break;
                    cursor = current.end;
                    column += 1;
                }
                continue;
            }
            if (byte == '/' and cursor + 1 < source.len and source[cursor + 1] == '/') {
                cursor += 2;
                column += 2;
                while (cursor < source.len) {
                    const current = try decodeSourceCodePoint(source, cursor);
                    if (isEcmaLineTerminator(current.value)) break;
                    cursor = current.end;
                    column += 1;
                }
                continue;
            }
            if (byte == '/' and cursor + 1 < source.len and source[cursor + 1] == '*') {
                cursor += 2;
                column += 2;
                var closed = false;
                while (cursor + 1 < source.len) {
                    if (source[cursor] == '*' and source[cursor + 1] == '/') {
                        cursor += 2;
                        column += 2;
                        closed = true;
                        break;
                    }
                    try advanceSourcePosition(source, &cursor, &line, &column);
                }
                if (!closed) return error.SyntaxError;
                continue;
            }

            if (byte == '/' and !tokenCanEndExpression(if (self.token_count > 0) self.workspace.tokens[self.token_count - 1].kind else .eof)) {
                const start = cursor;
                cursor = scanRegex(source, cursor) orelse return error.SyntaxError;
                column += @intCast(cursor - start);
                try self.addToken(.{
                    .kind = .regex,
                    .text = makeSourceRef(start, cursor - start),
                    .line = line,
                    .end_line = line,
                });
                continue;
            }

            const token_line = line;
            if (isPotentialIdentifierStart(byte)) {
                const identifier_start = cursor;
                const identifier = try self.scanIdentifier(source, cursor);
                column += @intCast(identifier.end - cursor);
                cursor = identifier.end;
                const identifier_text = self.text(identifier.text);
                const decoded_kind = keyword(identifier_text);
                try self.addToken(.{
                    .kind = if (identifier.had_escape and isReservedKeyword(decoded_kind)) .escaped_reserved else if (identifier.had_escape) .identifier else decoded_kind,
                    .flags = if (identifier.had_escape) 1 else 0,
                    .source_offset = @intCast(identifier_start),
                    .text = identifier.text,
                    .line = token_line,
                    .end_line = line,
                });
                continue;
            }
            if (byte == '#' and cursor + 1 < source.len and isPotentialIdentifierStart(source[cursor + 1])) {
                const identifier_start = cursor + 1;
                const identifier = try self.scanIdentifier(source, identifier_start);
                column += @intCast(identifier.end - cursor);
                cursor = identifier.end;
                try self.addToken(.{
                    .kind = .private_identifier,
                    .flags = if (identifier.had_escape) 1 else 0,
                    .source_offset = @intCast(identifier_start - 1),
                    .text = identifier.text,
                    .line = token_line,
                    .end_line = line,
                });
                continue;
            }
            if (std.ascii.isDigit(byte) or (byte == '.' and cursor + 1 < source.len and std.ascii.isDigit(source[cursor + 1]))) {
                const start = cursor;
                cursor = scanNumber(source, cursor);
                column += @intCast(cursor - start);
                const number_text = source[start..cursor];
                if (number_text[number_text.len - 1] == 'n') {
                    if (!bigIntLiteralValid(number_text)) return error.SyntaxError;
                    try self.addToken(.{
                        .kind = .bigint,
                        .text = makeSourceRef(start, number_text.len),
                        .line = token_line,
                        .end_line = line,
                    });
                    continue;
                }
                const value = parseNumber(number_text) catch return error.SyntaxError;
                try self.addToken(.{
                    .kind = .number,
                    .text = makeSourceRef(start, number_text.len),
                    .number = value,
                    .line = token_line,
                    .end_line = line,
                });
                continue;
            }
            if (byte == '`') {
                const chunk_line = token_line;
                advancePosition(byte, &line, &column);
                cursor += 1;
                const chunk = try scanTemplateChunk(source, &cursor, &line, &column);
                try self.addToken(.{
                    .kind = if (chunk.has_substitution) .template_head else .template,
                    .text = chunk.text,
                    .number = if (templateChunkCookedValid(source[chunk.text.offset..][0..chunk.text.len])) 0 else 1,
                    .line = chunk_line,
                    .end_line = line,
                });
                if (chunk.has_substitution) {
                    if (template_depth >= template_brace_depths.len) return error.CallDepth;
                    template_brace_depths[template_depth] = 0;
                    template_depth += 1;
                }
                continue;
            }
            if (byte == '\'' or byte == '"') {
                const quote = byte;
                const start = cursor + 1;
                cursor += 1;
                column += 1;
                while (cursor < source.len) {
                    const current = try decodeSourceCodePoint(source, cursor);
                    if (current.value == quote) break;
                    if (isEcmaLineTerminator(current.value)) return error.SyntaxError;
                    if (current.value == '\\') {
                        cursor = current.end;
                        column += 1;
                        if (cursor >= source.len) return error.SyntaxError;
                        const escaped = try decodeSourceCodePoint(source, cursor);
                        if (isEcmaLineTerminator(escaped.value)) {
                            try advanceSourcePosition(source, &cursor, &line, &column);
                        } else {
                            cursor = escaped.end;
                            column += 1;
                        }
                        continue;
                    }
                    cursor = current.end;
                    column += 1;
                }
                if (cursor >= source.len or source[cursor] != quote) return error.SyntaxError;
                const length = cursor - start;
                if (!stringLiteralCookedValid(source[start .. start + length])) return error.SyntaxError;
                cursor += 1;
                column += 1;
                try self.addToken(.{
                    .kind = .string,
                    .text = makeSourceRef(start, length),
                    .line = token_line,
                    .end_line = line,
                });
                continue;
            }

            const matched = operatorToken(source, cursor);
            if (matched) |entry| {
                try self.addToken(.{
                    .kind = entry.kind,
                    .text = makeSourceRef(cursor, entry.len),
                    .line = token_line,
                    .end_line = line,
                });
                cursor += entry.len;
                column += @intCast(entry.len);
                if (template_depth > 0) {
                    if (entry.kind == .l_brace) {
                        if (template_brace_depths[template_depth - 1] == std.math.maxInt(u16)) return error.SyntaxError;
                        template_brace_depths[template_depth - 1] += 1;
                    } else if (entry.kind == .r_brace) {
                        if (template_brace_depths[template_depth - 1] == 0) return error.SyntaxError;
                        template_brace_depths[template_depth - 1] -= 1;
                    }
                }
                continue;
            }
            return error.UnexpectedToken;
        }
        if (template_depth != 0) return error.SyntaxError;
        try self.addToken(.{ .kind = .eof, .line = line, .end_line = line });
    }
};

const SourceCodePoint = struct {
    value: u21,
    end: usize,
};

const IdentifierScan = struct {
    text: StringRef,
    end: usize,
    had_escape: bool,
};

fn decodeSourceCodePoint(source: []const u8, start: usize) Error!SourceCodePoint {
    if (start >= source.len) return error.SyntaxError;
    const length = std.unicode.utf8ByteSequenceLength(source[start]) catch return error.SyntaxError;
    if (start + length > source.len) return error.SyntaxError;
    const codepoint = std.unicode.utf8Decode(source[start .. start + length]) catch return error.SyntaxError;
    return .{ .value = codepoint, .end = start + length };
}

fn scanUnicodeEscape(source: []const u8, start: usize) Error!SourceCodePoint {
    const escaped = try scanStringUnicodeEscape(source, start);
    if (escaped.value >= 0xd800 and escaped.value <= 0xdfff) return error.SyntaxError;
    return .{ .value = @intCast(escaped.value), .end = escaped.end };
}

const EscapedCodePoint = struct {
    value: u32,
    end: usize,
};

fn scanStringUnicodeEscape(source: []const u8, start: usize) Error!EscapedCodePoint {
    if (start + 2 > source.len or source[start] != '\\' or source[start + 1] != 'u') return error.SyntaxError;
    var cursor = start + 2;
    var codepoint: u32 = 0;
    if (cursor < source.len and source[cursor] == '{') {
        cursor += 1;
        const digits_start = cursor;
        while (cursor < source.len and source[cursor] != '}') : (cursor += 1) {
            if (cursor - digits_start >= 6) return error.SyntaxError;
            codepoint = (codepoint << 4) | (hexDigit(source[cursor]) orelse return error.SyntaxError);
        }
        if (cursor == digits_start or cursor >= source.len or source[cursor] != '}' or codepoint > 0x10ffff) return error.SyntaxError;
        cursor += 1;
    } else {
        if (cursor + 4 > source.len) return error.SyntaxError;
        for (source[cursor .. cursor + 4]) |digit| codepoint = (codepoint << 4) | (hexDigit(digit) orelse return error.SyntaxError);
        cursor += 4;
    }
    return .{ .value = codepoint, .end = cursor };
}

fn isIdentifierStartCodePoint(codepoint: u21) bool {
    return codepoint == '$' or codepoint == '_' or unicode_identifier.isIdentifierStart(codepoint);
}

fn isIdentifierContinueCodePoint(codepoint: u21) bool {
    return codepoint == '$' or codepoint == '_' or codepoint == 0x200c or codepoint == 0x200d or unicode_identifier.isIdentifierContinue(codepoint);
}

fn identifierSourceEnd(source: []const u8, start: usize) Error!usize {
    var cursor = start;
    var first = true;
    while (cursor < source.len) {
        const escaped = source[cursor] == '\\';
        const codepoint = if (escaped) try scanUnicodeEscape(source, cursor) else try decodeSourceCodePoint(source, cursor);
        const allowed = if (first) isIdentifierStartCodePoint(codepoint.value) else isIdentifierContinueCodePoint(codepoint.value);
        if (!allowed) {
            if (first or escaped) return error.SyntaxError;
            break;
        }
        cursor = codepoint.end;
        first = false;
    }
    if (first) return error.SyntaxError;
    return cursor;
}

const TemplateChunk = struct {
    text: StringRef,
    has_substitution: bool,
};

fn scanTemplateChunk(source: []const u8, cursor: *usize, line: *u32, column: *u32) Error!TemplateChunk {
    const start = cursor.*;
    var escaped = false;
    while (cursor.* < source.len) {
        const current = try decodeSourceCodePoint(source, cursor.*);
        if (!escaped and current.value == '`') {
            const result = TemplateChunk{ .text = makeSourceRef(start, cursor.* - start), .has_substitution = false };
            try advanceSourcePosition(source, cursor, line, column);
            return result;
        }
        if (!escaped and current.value == '$' and cursor.* + 1 < source.len and source[cursor.* + 1] == '{') {
            const result = TemplateChunk{ .text = makeSourceRef(start, cursor.* - start), .has_substitution = true };
            try advanceSourcePosition(source, cursor, line, column);
            try advanceSourcePosition(source, cursor, line, column);
            return result;
        }
        if (!escaped and current.value == '\\')
            escaped = true
        else
            escaped = false;
        try advanceSourcePosition(source, cursor, line, column);
    }
    return error.SyntaxError;
}

fn templateChunkCookedValid(source: []const u8) bool {
    var cursor: usize = 0;
    while (cursor < source.len) {
        if (source[cursor] != '\\') {
            cursor += 1;
            continue;
        }
        cursor += 1;
        if (cursor >= source.len) return false;
        const escaped = source[cursor];
        cursor += 1;
        if (escaped == 'x') {
            if (cursor + 2 > source.len or hexDigit(source[cursor]) == null or hexDigit(source[cursor + 1]) == null) return false;
            cursor += 2;
            continue;
        }
        if (escaped == 'u') {
            if (cursor < source.len and source[cursor] == '{') {
                cursor += 1;
                const digits_start = cursor;
                var codepoint: u32 = 0;
                while (cursor < source.len and source[cursor] != '}') : (cursor += 1) {
                    const digit = hexDigit(source[cursor]) orelse return false;
                    if (cursor - digits_start >= 6) return false;
                    codepoint = (codepoint << 4) | digit;
                }
                if (cursor == digits_start or cursor >= source.len or source[cursor] != '}' or codepoint > 0x10FFFF or (codepoint >= 0xD800 and codepoint <= 0xDFFF)) return false;
                cursor += 1;
                continue;
            }
            if (cursor + 4 > source.len) return false;
            for (source[cursor .. cursor + 4]) |digit| if (hexDigit(digit) == null) return false;
            cursor += 4;
            continue;
        }
        if (escaped >= '1' and escaped <= '9') return false;
        if (escaped == '0' and cursor < source.len and std.ascii.isDigit(source[cursor])) return false;
        if (escaped == '\r' and cursor < source.len and source[cursor] == '\n') cursor += 1;
    }
    return true;
}

fn stringLiteralCookedValid(source: []const u8) bool {
    var cursor: usize = 0;
    while (cursor < source.len) {
        const current = decodeSourceCodePoint(source, cursor) catch return false;
        if (current.value != '\\') {
            if (isEcmaLineTerminator(current.value)) return false;
            cursor = current.end;
            continue;
        }
        const escape_start = cursor;
        cursor = current.end;
        if (cursor >= source.len) return false;
        const escaped = decodeSourceCodePoint(source, cursor) catch return false;
        if (isEcmaLineTerminator(escaped.value)) {
            cursor = escaped.end;
            if (escaped.value == '\r' and cursor < source.len and source[cursor] == '\n') cursor += 1;
            continue;
        }
        if (escaped.value == 'x') {
            cursor = escaped.end;
            if (cursor + 2 > source.len or hexDigit(source[cursor]) == null or hexDigit(source[cursor + 1]) == null) return false;
            cursor += 2;
            continue;
        }
        if (escaped.value == 'u') {
            cursor = (scanStringUnicodeEscape(source, escape_start) catch return false).end;
            continue;
        }
        cursor = escaped.end;
    }
    return true;
}

fn decodedStringEqualsAscii(source: []const u8, expected: []const u8) bool {
    var input: usize = 0;
    var output: usize = 0;
    while (input < source.len) {
        var decoded: u32 = source[input];
        input += 1;
        if (decoded == '\\') {
            if (input >= source.len) return false;
            const escaped = source[input];
            input += 1;
            if (escaped == '\n') continue;
            if (escaped == '\r') {
                if (input < source.len and source[input] == '\n') input += 1;
                continue;
            }
            if (escaped == 'x') {
                if (input + 2 > source.len) return false;
                decoded = (@as(u32, hexDigit(source[input]) orelse return false) << 4) |
                    (hexDigit(source[input + 1]) orelse return false);
                input += 2;
            } else if (escaped == 'u') {
                decoded = 0;
                if (input < source.len and source[input] == '{') {
                    input += 1;
                    const start = input;
                    while (input < source.len and source[input] != '}') : (input += 1) {
                        if (input - start >= 6) return false;
                        decoded = (decoded << 4) | (hexDigit(source[input]) orelse return false);
                    }
                    if (input == start or input >= source.len or source[input] != '}' or decoded > 0x10FFFF) return false;
                    input += 1;
                } else {
                    if (input + 4 > source.len) return false;
                    for (source[input .. input + 4]) |digit| decoded = (decoded << 4) | (hexDigit(digit) orelse return false);
                    input += 4;
                }
            } else {
                decoded = switch (escaped) {
                    'n' => '\n',
                    'r' => '\r',
                    't' => '\t',
                    'b' => 8,
                    'f' => 12,
                    'v' => 11,
                    '0' => 0,
                    else => escaped,
                };
            }
        }
        if (decoded > 0x7F or output >= expected.len or expected[output] != @as(u8, @intCast(decoded))) return false;
        output += 1;
    }
    return output == expected.len;
}

fn bytecodeHashValue(initial: u64, value: anytype) u64 {
    var hash = initial;
    var number: u64 = @intCast(value);
    var byte_index: usize = 0;
    while (byte_index < @sizeOf(u64)) : (byte_index += 1) {
        hash ^= @as(u8, @truncate(number));
        hash *%= 1099511628211;
        number >>= 8;
    }
    return hash;
}

const OperatorToken = struct {
    kind: TokenKind,
    len: usize,
};

fn operatorToken(source: []const u8, cursor: usize) ?OperatorToken {
    const rest = source[cursor..];
    if (startsWith(rest, ">>>=")) return .{ .kind = .shift_unsigned_equal, .len = 4 };
    if (startsWith(rest, "?.") and (rest.len < 3 or !std.ascii.isDigit(rest[2]))) return .{ .kind = .question_dot, .len = 2 };
    const triples = [_]struct { text: []const u8, kind: TokenKind }{
        .{ .text = "===", .kind = .equal_equal_equal },
        .{ .text = "!==", .kind = .bang_equal_equal },
        .{ .text = ">>>", .kind = .shift_unsigned },
        .{ .text = "<<=", .kind = .shift_left_equal },
        .{ .text = ">>=", .kind = .shift_right_equal },
        .{ .text = "**=", .kind = .star_star_equal },
        .{ .text = "&&=", .kind = .and_and_equal },
        .{ .text = "||=", .kind = .or_or_equal },
        .{ .text = "??=", .kind = .nullish_equal },
        .{ .text = "...", .kind = .ellipsis },
    };
    for (triples) |entry| {
        if (startsWith(rest, entry.text)) return .{ .kind = entry.kind, .len = entry.text.len };
    }
    const doubles = [_]struct { text: []const u8, kind: TokenKind }{
        .{ .text = "=>", .kind = .fat_arrow },
        .{ .text = "==", .kind = .equal_equal },
        .{ .text = "!=", .kind = .bang_equal },
        .{ .text = "<=", .kind = .less_equal },
        .{ .text = ">=", .kind = .greater_equal },
        .{ .text = "&&", .kind = .and_and },
        .{ .text = "||", .kind = .or_or },
        .{ .text = "??", .kind = .nullish },
        .{ .text = "++", .kind = .plus_plus },
        .{ .text = "--", .kind = .minus_minus },
        .{ .text = "+=", .kind = .plus_equal },
        .{ .text = "-=", .kind = .minus_equal },
        .{ .text = "*=", .kind = .star_equal },
        .{ .text = "**", .kind = .star_star },
        .{ .text = "/=", .kind = .slash_equal },
        .{ .text = "%=", .kind = .percent_equal },
        .{ .text = "&=", .kind = .ampersand_equal },
        .{ .text = "|=", .kind = .pipe_equal },
        .{ .text = "^=", .kind = .caret_equal },
        .{ .text = "<<", .kind = .shift_left },
        .{ .text = ">>", .kind = .shift_right },
    };
    for (doubles) |entry| {
        if (startsWith(rest, entry.text)) return .{ .kind = entry.kind, .len = entry.text.len };
    }
    return switch (source[cursor]) {
        '(' => .{ .kind = .l_paren, .len = 1 },
        ')' => .{ .kind = .r_paren, .len = 1 },
        '{' => .{ .kind = .l_brace, .len = 1 },
        '}' => .{ .kind = .r_brace, .len = 1 },
        '[' => .{ .kind = .l_bracket, .len = 1 },
        ']' => .{ .kind = .r_bracket, .len = 1 },
        ';' => .{ .kind = .semicolon, .len = 1 },
        ',' => .{ .kind = .comma, .len = 1 },
        '.' => .{ .kind = .dot, .len = 1 },
        ':' => .{ .kind = .colon, .len = 1 },
        '?' => .{ .kind = .question, .len = 1 },
        '+' => .{ .kind = .plus, .len = 1 },
        '-' => .{ .kind = .minus, .len = 1 },
        '*' => .{ .kind = .star, .len = 1 },
        '/' => .{ .kind = .slash, .len = 1 },
        '%' => .{ .kind = .percent, .len = 1 },
        '!' => .{ .kind = .bang, .len = 1 },
        '~' => .{ .kind = .tilde, .len = 1 },
        '&' => .{ .kind = .ampersand, .len = 1 },
        '|' => .{ .kind = .pipe, .len = 1 },
        '^' => .{ .kind = .caret, .len = 1 },
        '=' => .{ .kind = .equal, .len = 1 },
        '<' => .{ .kind = .less, .len = 1 },
        '>' => .{ .kind = .greater, .len = 1 },
        else => null,
    };
}

fn tokenCanEndExpression(kind: TokenKind) bool {
    return switch (kind) {
        .identifier,
        .number,
        .bigint,
        .string,
        .template,
        .template_tail,
        .regex,
        .kw_true,
        .kw_false,
        .kw_null,
        .kw_this,
        .r_paren,
        .r_bracket,
        .r_brace,
        .plus_plus,
        .minus_minus,
        => true,
        else => false,
    };
}

fn scanRegex(source: []const u8, start: usize) ?usize {
    if (start >= source.len or source[start] != '/') return null;
    var cursor = start + 1;
    var escaped = false;
    var in_class = false;
    while (cursor < source.len) {
        const codepoint = decodeSourceCodePoint(source, cursor) catch return null;
        if (isEcmaLineTerminator(codepoint.value)) return null;
        if (escaped) {
            escaped = false;
            cursor = codepoint.end;
            continue;
        }
        if (codepoint.value == '\\') {
            escaped = true;
            cursor = codepoint.end;
            continue;
        }
        if (codepoint.value == '[') {
            in_class = true;
            cursor = codepoint.end;
            continue;
        }
        if (codepoint.value == ']' and in_class) {
            in_class = false;
            cursor = codepoint.end;
            continue;
        }
        if (codepoint.value == '/' and !in_class) {
            cursor = codepoint.end;
            while (cursor < source.len and std.ascii.isAlphabetic(source[cursor])) cursor += 1;
            return cursor;
        }
        cursor = codepoint.end;
    }
    return null;
}

const ObjectPropertyName = struct {
    kind: TokenKind,
    text: StringRef = .{},
    expression: u16 = none,
    number: f64 = 0,
    flags: u16 = 0,
};

const FunctionParts = struct {
    parameters: u16,
    body: u16,
    strict: bool = false,
};

const ForEnumerationKind = enum(u8) {
    none,
    in,
    of,
};

const max_active_labels: usize = 256;
const iteration_label_source_marker: u32 = std.math.maxInt(u32);

const ActiveLabel = struct {
    name: StringRef = .{},
    iteration: bool = false,
};

const Parser = struct {
    program: *Program,
    current: usize = 0,
    furthest: usize = 0,
    allow_in: bool = true,
    current_class: u16 = none,
    super_class: u16 = none,
    super_call_allowed: bool = false,
    super_static: bool = false,
    allow_yield: bool = false,
    yield_reserved: bool = false,
    allow_await: bool = false,
    await_reserved: bool = false,
    allow_new_target: bool = false,
    return_allowed: bool = false,
    arguments_forbidden: bool = false,
    breakable_depth: usize = 0,
    iteration_depth: usize = 0,
    active_labels: [max_active_labels]ActiveLabel = [_]ActiveLabel{.{}} ** max_active_labels,
    active_label_count: usize = 0,

    fn parseProgram(self: *Parser) Error!u16 {
        const root = try self.program.addNode(.{ .kind = .program });
        var first: u16 = none;
        var last: u16 = none;
        while (!self.at(.eof)) {
            const statement = try self.parseStatementListItem(true);
            appendNode(self.program, &first, &last, statement);
        }
        self.program.nodes[root].a = first;
        try self.validateStatementListDeclarations(first, true);
        if (self.statementListHasUseStrict(first)) {
            self.program.strict_mode = true;
            try self.validateStrictRange(0, self.program.node_count);
        }
        return root;
    }

    fn statementListHasUseStrict(self: *const Parser, first: u16) bool {
        var current = first;
        while (current != none) : (current = self.program.nodes[current].next) {
            const statement = self.program.nodes[current];
            if (statement.kind != .expression_statement or statement.a == none) return false;
            const expression = self.program.nodes[statement.a];
            if (expression.kind != .string_literal) return false;
            if (decodedStringEqualsAscii(self.program.text(expression.text), "use strict")) return true;
        }
        return false;
    }

    fn blockHasUseStrict(self: *const Parser, block: u16) bool {
        if (block == none or self.program.nodes[block].kind != .block) return false;
        return self.statementListHasUseStrict(self.program.nodes[block].a);
    }

    fn restrictedStrictName(self: *const Parser, ref: StringRef) bool {
        const name = self.program.text(ref);
        return equals(name, "eval") or equals(name, "arguments");
    }

    fn strictNumberLiteralValid(self: *const Parser, ref: StringRef) bool {
        const source = self.program.text(ref);
        if (source.len < 2 or source[0] != '0') return true;
        if (source[1] == 'x' or source[1] == 'X' or source[1] == 'b' or source[1] == 'B' or source[1] == 'o' or source[1] == 'O') return true;
        return source[1] == '.' or source[1] == 'e' or source[1] == 'E' or source[1] == '_';
    }

    fn strictStringLiteralValid(self: *const Parser, ref: StringRef) bool {
        const source = self.program.text(ref);
        var cursor: usize = 0;
        while (cursor < source.len) : (cursor += 1) {
            if (source[cursor] != 92 or cursor + 1 >= source.len) continue;
            cursor += 1;
            const escaped = source[cursor];
            if (escaped >= '1' and escaped <= '9') return false;
            if (escaped == '0' and cursor + 1 < source.len and std.ascii.isDigit(source[cursor + 1])) return false;
        }
        return true;
    }

    fn validateStrictPattern(self: *Parser, index: u16) Error!void {
        if (index == none) return;
        const pattern = self.program.nodes[index];
        if (pattern.kind == .identifier) {
            if (self.restrictedStrictName(pattern.text)) return error.SyntaxError;
            return;
        }
        if (!isPatternKind(pattern.kind)) return;
        var current = pattern.a;
        while (current != none) : (current = self.program.nodes[current].next) {
            const element = self.program.nodes[current];
            if (element.kind == .pattern_element and element.a != none) try self.validateStrictPattern(element.a);
        }
    }

    fn validateStrictRange(self: *Parser, start: usize, end: usize) Error!void {
        for (self.program.nodes[start..end]) |*node| {
            switch (node.kind) {
                .function_declaration, .function_expression => {
                    node.flags |= flag_strict;
                    if (node.text.len != 0 and self.restrictedStrictName(node.text)) return error.SyntaxError;
                    try self.validateParameterList(node.a, false);
                    var parameter = node.a;
                    while (parameter != none) : (parameter = self.program.nodes[parameter].next)
                        try self.validateStrictPattern(self.program.nodes[parameter].b);
                },
                .variable => try self.validateStrictPattern(node.b),
                .try_statement => if (node.d != none) try self.validateStrictPattern(node.d),
                .number_literal => if (!self.strictNumberLiteralValid(node.text)) return error.SyntaxError,
                .string_literal => if (!self.strictStringLiteralValid(node.text)) return error.SyntaxError,
                .unary => if (@as(UnaryOp, @enumFromInt(node.flags)) == .delete_value and node.a != none and self.program.nodes[node.a].kind == .identifier) return error.SyntaxError,
                .assignment, .update => if (node.a != none and self.program.nodes[node.a].kind == .identifier and self.restrictedStrictName(self.program.nodes[node.a].text)) return error.SyntaxError,
                .with_statement => return error.SyntaxError,
                else => {},
            }
        }
    }

    fn parseStatementListItem(self: *Parser, top_level: bool) Error!u16 {
        if (self.at(.kw_let) or self.at(.kw_const)) return self.parseVariable(false, true);
        if (self.at(.kw_function) or (self.at(.kw_async) and self.peekKind(1) == .kw_function and self.tokensShareLine(self.current, self.current + 1))) return self.parseFunctionDeclaration(false);
        if (self.match(.kw_class)) return self.parseClassDefinition(true, false);
        if (self.at(.kw_import) and self.peekKind(1) != .l_paren and self.peekKind(1) != .dot) {
            if (!top_level) return error.SyntaxError;
            _ = self.advance();
            return self.parseImport();
        }
        if (self.at(.kw_export)) {
            if (!top_level) return error.SyntaxError;
            _ = self.advance();
            return self.parseExport();
        }
        return self.parseStatement();
    }

    fn parseStatement(self: *Parser) Error!u16 {
        if (self.match(.semicolon)) return self.program.addNode(.{ .kind = .empty });
        if (self.at(.l_brace)) return self.parseBlock();
        if (self.at(.identifier) and self.peekKind(1) == .colon) {
            const label = self.advance();
            if (self.yield_reserved and self.identifierEquals(label, "yield")) return error.SyntaxError;
            if (self.await_reserved and self.identifierEquals(label, "await")) return error.SyntaxError;
            try self.expect(.colon);
            if (self.findActiveLabel(label.text) != null or self.active_label_count >= self.active_labels.len) return error.SyntaxError;
            const iteration = self.labeledTargetIsIteration();
            self.active_labels[self.active_label_count] = .{ .name = label.text, .iteration = iteration };
            self.active_label_count += 1;
            defer self.active_label_count -= 1;
            const target = try self.parseStatement();
            if (iteration) try self.attachIterationLabel(target, label.text);
            return self.program.addNode(.{ .kind = .labeled_statement, .a = target, .text = label.text });
        }
        if (self.at(.kw_var)) return self.parseVariable(false, true);
        if (self.at(.kw_let) or self.at(.kw_const) or self.at(.kw_function) or self.at(.kw_class) or
            (self.at(.kw_import) and self.peekKind(1) != .l_paren and self.peekKind(1) != .dot) or self.at(.kw_export) or
            (self.at(.kw_async) and self.peekKind(1) == .kw_function and self.tokensShareLine(self.current, self.current + 1))) return error.SyntaxError;
        if (self.match(.kw_return)) {
            if (!self.return_allowed) return error.SyntaxError;
            const value = if (self.lineTerminatorBeforeCurrent() or self.at(.semicolon) or self.at(.r_brace) or self.at(.eof)) none else try self.parseExpression();
            try self.consumeSemicolon();
            return self.program.addNode(.{ .kind = .return_statement, .a = value });
        }
        if (self.match(.kw_throw)) {
            if (self.lineTerminatorBeforeCurrent()) return error.SyntaxError;
            const value = try self.parseExpression();
            try self.consumeSemicolon();
            return self.program.addNode(.{ .kind = .throw_statement, .a = value });
        }
        if (self.match(.kw_break)) {
            const label = if (!self.lineTerminatorBeforeCurrent() and self.at(.identifier)) self.advance().text else StringRef{};
            if (self.yield_reserved and label.len != 0 and equals(self.program.text(label), "yield")) return error.SyntaxError;
            if (self.await_reserved and label.len != 0 and equals(self.program.text(label), "await")) return error.SyntaxError;
            if (label.len == 0 and self.breakable_depth == 0) return error.SyntaxError;
            if (label.len != 0 and self.findActiveLabel(label) == null) return error.SyntaxError;
            try self.consumeSemicolon();
            return self.program.addNode(.{ .kind = .break_statement, .text = label });
        }
        if (self.match(.kw_continue)) {
            const label = if (!self.lineTerminatorBeforeCurrent() and self.at(.identifier)) self.advance().text else StringRef{};
            if (self.yield_reserved and label.len != 0 and equals(self.program.text(label), "yield")) return error.SyntaxError;
            if (self.await_reserved and label.len != 0 and equals(self.program.text(label), "await")) return error.SyntaxError;
            if (label.len == 0 and self.iteration_depth == 0) return error.SyntaxError;
            if (label.len != 0) {
                const active = self.findActiveLabel(label) orelse return error.SyntaxError;
                if (!active.iteration) return error.SyntaxError;
            }
            try self.consumeSemicolon();
            return self.program.addNode(.{ .kind = .continue_statement, .text = label });
        }
        if (self.match(.kw_debugger)) {
            try self.consumeSemicolon();
            return self.program.addNode(.{ .kind = .empty });
        }
        if (self.match(.kw_with)) {
            try self.expect(.l_paren);
            const object = try self.parseExpression();
            try self.expect(.r_paren);
            return self.program.addNode(.{ .kind = .with_statement, .a = object, .b = try self.parseStatement() });
        }
        if (self.match(.kw_if)) return self.parseIf();
        if (self.match(.kw_while)) return self.parseWhile();
        if (self.match(.kw_do)) return self.parseDoWhile();
        if (self.match(.kw_for)) return self.parseFor();
        if (self.match(.kw_switch)) return self.parseSwitch();
        if (self.match(.kw_try)) return self.parseTry();
        const expression = try self.parseExpression();
        try self.consumeSemicolon();
        return self.program.addNode(.{ .kind = .expression_statement, .a = expression });
    }

    fn findActiveLabel(self: *const Parser, name: StringRef) ?ActiveLabel {
        var index = self.active_label_count;
        while (index > 0) {
            index -= 1;
            const active = self.active_labels[index];
            if (equals(self.program.text(active.name), self.program.text(name))) return active;
        }
        return null;
    }

    fn labeledTargetIsIteration(self: *const Parser) bool {
        var cursor = self.current;
        while (self.peekKindAt(cursor) == .identifier and self.peekKindAt(cursor + 1) == .colon) cursor += 2;
        return switch (self.peekKindAt(cursor)) {
            .kw_while, .kw_do, .kw_for => true,
            else => false,
        };
    }

    fn attachIterationLabel(self: *Parser, statement: u16, name: StringRef) Error!void {
        var target = statement;
        while (target != none and self.program.nodes[target].kind == .labeled_statement) target = self.program.nodes[target].a;
        if (target == none) return error.SyntaxError;
        const target_kind = self.program.nodes[target].kind;
        if (target_kind != .while_statement and target_kind != .do_while_statement and target_kind != .for_statement and
            target_kind != .for_in_statement and target_kind != .for_of_statement) return error.SyntaxError;
        const previous = if (self.program.nodes[target].source.len == iteration_label_source_marker)
            @as(u16, @intCast(self.program.nodes[target].source.offset))
        else
            none;
        const metadata = try self.program.addNode(.{ .kind = .property, .text = name, .next = previous });
        self.program.nodes[target].source = .{ .offset = metadata, .len = iteration_label_source_marker };
    }

    fn appendScopeName(_: *Parser, names: []StringRef, count: *usize, name: StringRef) Error!void {
        if (name.len == 0 or count.* >= names.len) return error.BindingLimit;
        names[count.*] = name;
        count.* += 1;
    }

    fn appendUniqueScopeName(self: *Parser, names: []StringRef, count: *usize, name: StringRef) Error!void {
        for (names[0..count.*]) |existing|
            if (equals(self.program.text(existing), self.program.text(name))) return;
        try self.appendScopeName(names, count, name);
    }

    fn appendUniquePatternNames(self: *Parser, pattern_index: u16, names: []StringRef, count: *usize) Error!void {
        if (pattern_index == none or pattern_index >= self.program.node_count) return error.SyntaxError;
        const pattern = self.program.nodes[pattern_index];
        if (pattern.kind == .identifier) {
            try self.appendUniqueScopeName(names, count, pattern.text);
            return;
        }
        if (!isPatternKind(pattern.kind)) return error.SyntaxError;
        var element = pattern.a;
        while (element != none) : (element = self.program.nodes[element].next) {
            if (self.program.nodes[element].kind != .pattern_element) return error.SyntaxError;
            if (self.program.nodes[element].a != none)
                try self.appendUniquePatternNames(self.program.nodes[element].a, names, count);
        }
    }

    fn appendDirectLexicalNames(self: *Parser, statement: u16, function_body: bool, names: []StringRef, count: *usize) Error!void {
        if (statement == none) return;
        const node = self.program.nodes[statement];
        if (node.kind == .block and node.flags & flag_declaration_list != 0) {
            var current = node.a;
            while (current != none) : (current = self.program.nodes[current].next)
                try self.appendDirectLexicalNames(current, function_body, names, count);
            return;
        }
        switch (node.kind) {
            .variable => if (node.flags & flag_var == 0) try self.collectPatternNames(node.b, names, count),
            .class_declaration => try self.appendScopeName(names, count, node.text),
            .function_declaration => if (!function_body) try self.appendScopeName(names, count, node.text),
            .import_statement => {
                var binding = node.a;
                while (binding != none) : (binding = self.program.nodes[binding].next) {
                    const local = self.program.nodes[binding].a;
                    if (local != none) try self.appendScopeName(names, count, self.program.nodes[local].text);
                }
            },
            else => {},
        }
    }

    fn appendRecursiveVarNames(self: *Parser, statement: u16, names: []StringRef, count: *usize) Error!void {
        if (statement == none) return;
        const node = self.program.nodes[statement];
        switch (node.kind) {
            .variable => if (node.flags & flag_var != 0) try self.appendUniquePatternNames(node.b, names, count),
            .function_declaration, .class_declaration => {},
            .program, .block => {
                var current = node.a;
                while (current != none) : (current = self.program.nodes[current].next)
                    try self.appendRecursiveVarNames(current, names, count);
            },
            .if_statement => {
                try self.appendRecursiveVarNames(node.b, names, count);
                try self.appendRecursiveVarNames(node.c, names, count);
            },
            .while_statement, .do_while_statement => try self.appendRecursiveVarNames(node.b, names, count),
            .for_statement => {
                try self.appendRecursiveVarNames(node.a, names, count);
                try self.appendRecursiveVarNames(node.d, names, count);
            },
            .for_in_statement, .for_of_statement => {
                try self.appendRecursiveVarNames(node.a, names, count);
                try self.appendRecursiveVarNames(node.c, names, count);
            },
            .switch_statement => {
                var case_index = node.b;
                while (case_index != none) : (case_index = self.program.nodes[case_index].next) {
                    var current = self.program.nodes[case_index].b;
                    while (current != none) : (current = self.program.nodes[current].next)
                        try self.appendRecursiveVarNames(current, names, count);
                }
            },
            .labeled_statement => try self.appendRecursiveVarNames(node.a, names, count),
            .with_statement => try self.appendRecursiveVarNames(node.b, names, count),
            .try_statement => {
                try self.appendRecursiveVarNames(node.a, names, count);
                try self.appendRecursiveVarNames(node.b, names, count);
                try self.appendRecursiveVarNames(node.c, names, count);
            },
            else => {},
        }
    }

    fn validateStatementListDeclarations(self: *Parser, first: u16, function_body: bool) Error!void {
        var lexical: [max_bindings]StringRef = undefined;
        var variable: [max_bindings]StringRef = undefined;
        var lexical_count: usize = 0;
        var variable_count: usize = 0;
        var current = first;
        while (current != none) : (current = self.program.nodes[current].next) {
            try self.appendDirectLexicalNames(current, function_body, lexical[0..], &lexical_count);
            if (function_body and self.program.nodes[current].kind == .function_declaration)
                try self.appendUniqueScopeName(variable[0..], &variable_count, self.program.nodes[current].text);
            try self.appendRecursiveVarNames(current, variable[0..], &variable_count);
        }
        for (lexical[0..lexical_count], 0..) |name, index| {
            for (lexical[index + 1 .. lexical_count]) |other|
                if (equals(self.program.text(name), self.program.text(other))) return error.SyntaxError;
            for (variable[0..variable_count]) |other|
                if (equals(self.program.text(name), self.program.text(other))) return error.SyntaxError;
        }
    }

    fn validateParametersAgainstBody(self: *Parser, parameters: u16, body: u16) Error!void {
        var parameter_names: [max_bindings]StringRef = undefined;
        var lexical_names: [max_bindings]StringRef = undefined;
        var parameter_count: usize = 0;
        var lexical_count: usize = 0;
        var parameter = parameters;
        while (parameter != none) : (parameter = self.program.nodes[parameter].next)
            try self.collectPatternNames(self.program.nodes[parameter].b, parameter_names[0..], &parameter_count);
        var statement = self.program.nodes[body].a;
        while (statement != none) : (statement = self.program.nodes[statement].next)
            try self.appendDirectLexicalNames(statement, true, lexical_names[0..], &lexical_count);
        for (parameter_names[0..parameter_count]) |name|
            for (lexical_names[0..lexical_count]) |other|
                if (equals(self.program.text(name), self.program.text(other))) return error.SyntaxError;
    }

    fn parseBlock(self: *Parser) Error!u16 {
        return self.parseBlockMode(false);
    }

    fn parseFunctionBody(self: *Parser) Error!u16 {
        return self.parseBlockMode(true);
    }

    fn parseBlockMode(self: *Parser, function_body: bool) Error!u16 {
        try self.expect(.l_brace);
        const block = try self.program.addNode(.{ .kind = .block });
        var first: u16 = none;
        var last: u16 = none;
        while (!self.at(.r_brace) and !self.at(.eof)) {
            appendNode(self.program, &first, &last, try self.parseStatementListItem(false));
        }
        try self.expect(.r_brace);
        self.program.nodes[block].a = first;
        try self.validateStatementListDeclarations(first, function_body);
        return block;
    }

    fn parseVariable(self: *Parser, exported: bool, allow_asi: bool) Error!u16 {
        const declaration_kind = self.advance().kind;
        const is_const = declaration_kind == .kw_const;
        var first: u16 = none;
        var last: u16 = none;
        while (true) {
            const target = try self.parseBindingTarget();
            var initializer: u16 = none;
            if (self.match(.equal)) initializer = try self.parseAssignment();
            if ((is_const or isPatternKind(self.program.nodes[target].kind)) and initializer == none) return error.SyntaxError;
            const node = try self.program.addNode(.{
                .kind = .variable,
                .a = initializer,
                .b = target,
                .text = if (self.program.nodes[target].kind == .identifier) self.program.nodes[target].text else .{},
                .flags = (if (is_const) flag_const else 0) |
                    (if (declaration_kind == .kw_var) flag_var else 0) |
                    (if (exported) flag_exported else 0),
            });
            appendNode(self.program, &first, &last, node);
            if (!self.match(.comma)) break;
        }
        if (allow_asi)
            try self.consumeSemicolon()
        else
            try self.expect(.semicolon);
        if (first == last) return first;
        return self.program.addNode(.{ .kind = .block, .a = first, .flags = flag_declaration_list });
    }

    fn parseBindingTarget(self: *Parser) Error!u16 {
        if (self.at(.identifier)) {
            const identifier = self.advance();
            if (self.yield_reserved and self.identifierEquals(identifier, "yield")) return error.SyntaxError;
            if (self.await_reserved and self.identifierEquals(identifier, "await")) return error.SyntaxError;
            return self.program.addNode(.{ .kind = .identifier, .text = identifier.text });
        }
        if (self.match(.l_bracket)) return self.parseArrayBindingPattern();
        if (self.match(.l_brace)) return self.parseObjectBindingPattern();
        return error.SyntaxError;
    }

    fn parseArrayBindingPattern(self: *Parser) Error!u16 {
        var first: u16 = none;
        var last: u16 = none;
        while (!self.at(.r_bracket)) {
            if (self.match(.comma)) {
                appendNode(self.program, &first, &last, try self.program.addNode(.{ .kind = .pattern_element, .flags = flag_elision }));
                continue;
            }
            const rest = self.match(.ellipsis);
            const target = try self.parseBindingTarget();
            var initializer: u16 = none;
            if (self.match(.equal)) {
                if (rest) return error.SyntaxError;
                initializer = try self.parseAssignment();
            }
            appendNode(self.program, &first, &last, try self.program.addNode(.{
                .kind = .pattern_element,
                .a = target,
                .b = initializer,
                .flags = if (rest) flag_rest else 0,
            }));
            if (rest) {
                if (!self.at(.r_bracket)) return error.SyntaxError;
                break;
            }
            if (!self.match(.comma)) break;
        }
        try self.expect(.r_bracket);
        return self.program.addNode(.{ .kind = .array_pattern, .a = first });
    }

    fn parseObjectBindingPattern(self: *Parser) Error!u16 {
        var first: u16 = none;
        var last: u16 = none;
        while (!self.at(.r_brace)) {
            if (self.match(.ellipsis)) {
                const target = try self.parseBindingTarget();
                if (self.program.nodes[target].kind != .identifier) return error.SyntaxError;
                appendNode(self.program, &first, &last, try self.program.addNode(.{
                    .kind = .pattern_element,
                    .a = target,
                    .flags = flag_rest,
                }));
                if (!self.at(.r_brace)) return error.SyntaxError;
                break;
            }
            const key = try self.parseObjectPropertyName();
            const target = if (self.match(.colon))
                try self.parseBindingTarget()
            else if (key.kind == .identifier or key.kind == .kw_async)
                try self.program.addNode(.{ .kind = .identifier, .text = key.text })
            else
                return error.SyntaxError;
            const initializer = if (self.match(.equal)) try self.parseAssignment() else none;
            appendNode(self.program, &first, &last, try self.program.addNode(.{
                .kind = .pattern_element,
                .a = target,
                .b = initializer,
                .c = key.expression,
                .text = key.text,
                .number = key.number,
                .flags = key.flags,
            }));
            if (!self.match(.comma)) break;
            if (self.at(.r_brace)) break;
        }
        try self.expect(.r_brace);
        return self.program.addNode(.{ .kind = .object_pattern, .a = first });
    }

    fn parseFunctionDeclaration(self: *Parser, exported: bool) Error!u16 {
        const source_start = self.program.workspace.tokens[self.current].source_offset;
        var flags: u16 = if (exported) flag_exported else 0;
        if (self.match(.kw_async)) flags |= flag_async;
        try self.expect(.kw_function);
        const generator = self.match(.star);
        if (generator) flags |= flag_generator;
        const name = try self.expectIdentifier();
        if (self.yield_reserved and self.identifierEquals(name, "yield")) return error.SyntaxError;
        if (self.await_reserved and self.identifierEquals(name, "await")) return error.SyntaxError;
        const parts = try self.parseFunctionPartsWithoutSuper(flags & flag_async == 0 and !generator, generator, flags & flag_async != 0);
        if (parts.strict and self.restrictedStrictName(name.text)) return error.SyntaxError;
        self.program.function_count += 1;
        return self.program.addNode(.{
            .kind = .function_declaration,
            .a = parts.parameters,
            .b = parts.body,
            .text = name.text,
            .source = self.functionSource(source_start),
            .flags = flags | (if (parts.strict) flag_strict else 0),
        });
    }

    fn parseClassDefinition(self: *Parser, declaration: bool, exported: bool) Error!u16 {
        var name: StringRef = .{};
        if (self.at(.identifier)) {
            const name_token = self.advance();
            if (self.yield_reserved and self.identifierEquals(name_token, "yield")) return error.SyntaxError;
            if (self.await_reserved and self.identifierEquals(name_token, "await")) return error.SyntaxError;
            name = name_token.text;
        } else if (declaration) {
            return error.SyntaxError;
        }
        const heritage = if (self.match(.kw_extends)) try self.parseAssignment() else none;
        const strict_range_start = self.program.node_count;
        try self.expect(.l_brace);
        const previous_class = self.current_class;
        const class_index = try self.program.addNode(.{
            .kind = if (declaration) .class_declaration else .class_expression,
            .a = heritage,
            .d = previous_class,
            .text = name,
            .flags = if (exported) flag_exported else 0,
        });
        self.current_class = class_index;
        defer self.current_class = previous_class;
        var first: u16 = none;
        var last: u16 = none;
        var constructor: u16 = none;
        while (!self.at(.r_brace) and !self.at(.eof)) {
            if (self.match(.semicolon)) continue;
            const source_start = self.peek().source_offset;
            var element_flags: u16 = 0;
            if (self.classStaticModifierAhead()) {
                _ = self.advance();
                element_flags |= flag_class_static;
                if (self.at(.l_brace)) {
                    const block = try self.parseClassStaticBlock(class_index);
                    appendNode(self.program, &first, &last, try self.program.addNode(.{
                        .kind = .class_element,
                        .a = block,
                        .flags = flag_class_static | flag_class_static_block,
                    }));
                    continue;
                }
            }
            var async_method = false;
            var generator_method = self.match(.star);
            if (!generator_method and self.at(.kw_async) and self.peekKind(1) == .star and self.tokensShareLine(self.current, self.current + 1)) {
                _ = self.advance();
                _ = self.advance();
                async_method = true;
                generator_method = true;
            } else if (!generator_method and self.objectAccessorAhead()) {
                const prefix = self.advance();
                element_flags |= if (equals(self.program.text(prefix.text), "get")) flag_getter else flag_setter;
            } else if (!generator_method and self.objectAsyncMethodAhead()) {
                _ = self.advance();
                async_method = true;
            }
            const key = if (self.at(.private_identifier)) blk: {
                const private_name = self.advance();
                if (equals(self.program.text(private_name.text), "constructor")) return error.SyntaxError;
                break :blk ObjectPropertyName{
                    .kind = .private_identifier,
                    .text = private_name.text,
                    .flags = flag_private,
                };
            } else try self.parseObjectPropertyName();
            if (self.at(.l_paren)) {
                const constructor_name = key.flags & flag_private == 0 and self.classPropertyNameEquals(key, "constructor");
                const parts = try self.parseFunctionPartsWithSuper(
                    false,
                    class_index,
                    element_flags & flag_class_static != 0,
                    constructor_name and heritage != none,
                    generator_method,
                    async_method,
                );
                if (element_flags & flag_getter != 0 and parts.parameters != none) return error.SyntaxError;
                if (element_flags & flag_setter != 0 and (parts.parameters == none or self.program.nodes[parts.parameters].next != none or
                    self.program.nodes[parts.parameters].a != none or self.program.nodes[parts.parameters].flags & flag_rest != 0)) return error.SyntaxError;
                if (constructor_name and (element_flags & flag_class_static != 0 or element_flags & (flag_getter | flag_setter) != 0 or async_method or generator_method)) return error.SyntaxError;
                const function = try self.program.addNode(.{
                    .kind = .function_expression,
                    .a = parts.parameters,
                    .b = parts.body,
                    .text = key.text,
                    .source = self.functionSource(source_start),
                    .flags = (if (async_method) flag_async else 0) |
                        (if (generator_method) flag_generator else 0) |
                        (if (constructor_name) flag_class_constructor else flag_method) | flag_strict,
                });
                self.program.function_count += 1;
                if (constructor_name) {
                    if (constructor != none) return error.SyntaxError;
                    constructor = function;
                }
                const element = try self.program.addNode(.{
                    .kind = .class_element,
                    .a = function,
                    .b = key.expression,
                    .text = key.text,
                    .number = key.number,
                    .flags = element_flags | key.flags,
                });
                try self.validatePrivateElementDuplicate(first, element);
                appendNode(self.program, &first, &last, element);
                continue;
            }
            if (async_method or generator_method or element_flags & (flag_getter | flag_setter) != 0) return error.SyntaxError;
            if (self.classPropertyNameEquals(key, "constructor")) return error.SyntaxError;
            if (element_flags & flag_class_static != 0 and self.classPropertyNameEquals(key, "prototype")) return error.SyntaxError;
            const initializer = if (self.match(.equal))
                try self.parseClassFieldInitializer(class_index, element_flags & flag_class_static != 0)
            else
                none;
            const element = try self.program.addNode(.{
                .kind = .class_element,
                .a = initializer,
                .b = key.expression,
                .text = key.text,
                .number = key.number,
                .flags = element_flags | key.flags | flag_class_field,
            });
            try self.validatePrivateElementDuplicate(first, element);
            appendNode(self.program, &first, &last, element);
            try self.consumeSemicolon();
        }
        try self.expect(.r_brace);
        if (constructor == none) {
            const body = try self.program.addNode(.{ .kind = .block });
            constructor = try self.program.addNode(.{
                .kind = .function_expression,
                .b = body,
                .text = name,
                .flags = flag_class_constructor | flag_class_default | (if (heritage != none) flag_class_derived else 0),
            });
            self.program.function_count += 1;
        } else if (heritage != none) {
            self.program.nodes[constructor].flags |= flag_class_derived;
        }
        self.program.nodes[class_index] = .{
            .kind = if (declaration) .class_declaration else .class_expression,
            .a = heritage,
            .b = first,
            .c = constructor,
            .d = previous_class,
            .text = name,
            .flags = if (exported) flag_exported else 0,
        };
        try self.validateStrictRange(strict_range_start, self.program.node_count);
        try self.validatePrivateReferences(class_index);
        return class_index;
    }

    fn validatePrivateElementDuplicate(self: *const Parser, first: u16, candidate_index: u16) Error!void {
        const candidate = self.program.nodes[candidate_index];
        if (candidate.flags & flag_private == 0) return;
        var current = first;
        while (current != none) : (current = self.program.nodes[current].next) {
            const existing = self.program.nodes[current];
            if (existing.flags & flag_private == 0 or !equals(self.program.text(existing.text), self.program.text(candidate.text))) continue;
            const accessor_pair = existing.flags & flag_class_static == candidate.flags & flag_class_static and
                ((existing.flags & flag_getter != 0 and candidate.flags & flag_setter != 0) or
                    (existing.flags & flag_setter != 0 and candidate.flags & flag_getter != 0));
            if (!accessor_pair) return error.SyntaxError;
        }
    }

    fn validatePrivateReferences(self: *Parser, class_index: u16) Error!void {
        var node_index: usize = 0;
        while (node_index < self.program.node_count) : (node_index += 1) {
            var node = &self.program.nodes[node_index];
            if (node.kind != .private_identifier and node.kind != .private_in and
                !((node.kind == .member or node.kind == .chain_member) and node.flags & flag_private != 0)) continue;
            if (!self.privateClassChainContains(node.c, class_index)) continue;
            var owner = node.c;
            var resolved = false;
            while (owner != none) : (owner = self.program.nodes[owner].d) {
                var element_index = self.program.nodes[owner].b;
                while (element_index != none) : (element_index = self.program.nodes[element_index].next) {
                    const element = self.program.nodes[element_index];
                    if (element.flags & flag_private != 0 and equals(self.program.text(element.text), self.program.text(node.text))) {
                        node.c = owner;
                        resolved = true;
                        break;
                    }
                }
                if (resolved) break;
            }
            if (!resolved and self.program.nodes[class_index].d == none) return error.SyntaxError;
        }
    }

    fn privateClassChainContains(self: *const Parser, start: u16, expected: u16) bool {
        var current = start;
        while (current != none) : (current = self.program.nodes[current].d) {
            if (current == expected) return true;
        }
        return false;
    }

    fn classStaticModifierAhead(self: *const Parser) bool {
        if (!self.at(.identifier) or !equals(self.program.text(self.peek().text), "static")) return false;
        return switch (self.peekKind(1)) {
            .l_paren, .equal, .semicolon, .r_brace => false,
            else => true,
        };
    }

    fn classPropertyNameEquals(self: *const Parser, key: ObjectPropertyName, expected: []const u8) bool {
        if (key.expression != none or key.flags & flag_key_number != 0) return false;
        if (key.flags & flag_key_string != 0) return decodedStringEqualsAscii(self.program.text(key.text), expected);
        return equals(self.program.text(key.text), expected);
    }

    fn parseFunctionPartsWithoutSuper(self: *Parser, allow_duplicate_simple: bool, generator: bool, async_function: bool) Error!FunctionParts {
        const previous_class = self.super_class;
        const previous_call = self.super_call_allowed;
        const previous_static = self.super_static;
        self.super_class = none;
        self.super_call_allowed = false;
        self.super_static = false;
        defer {
            self.super_class = previous_class;
            self.super_call_allowed = previous_call;
            self.super_static = previous_static;
        }
        return self.parseFunctionParts(allow_duplicate_simple, generator, async_function);
    }

    fn parseFunctionPartsWithSuper(self: *Parser, allow_duplicate_simple: bool, class_index: u16, static: bool, allow_call: bool, generator: bool, async_function: bool) Error!FunctionParts {
        const previous_class = self.super_class;
        const previous_call = self.super_call_allowed;
        const previous_static = self.super_static;
        self.super_class = class_index;
        self.super_call_allowed = allow_call;
        self.super_static = static;
        defer {
            self.super_class = previous_class;
            self.super_call_allowed = previous_call;
            self.super_static = previous_static;
        }
        return self.parseFunctionParts(allow_duplicate_simple, generator, async_function);
    }

    fn parseBlockWithSuper(self: *Parser, class_index: u16, static: bool) Error!u16 {
        const previous_class = self.super_class;
        const previous_call = self.super_call_allowed;
        const previous_static = self.super_static;
        self.super_class = class_index;
        self.super_call_allowed = false;
        self.super_static = static;
        defer {
            self.super_class = previous_class;
            self.super_call_allowed = previous_call;
            self.super_static = previous_static;
        }
        return self.parseBlock();
    }

    fn parseExpressionWithSuper(self: *Parser, class_index: u16, static: bool) Error!u16 {
        const previous_class = self.super_class;
        const previous_call = self.super_call_allowed;
        const previous_static = self.super_static;
        self.super_class = class_index;
        self.super_call_allowed = false;
        self.super_static = static;
        defer {
            self.super_class = previous_class;
            self.super_call_allowed = previous_call;
            self.super_static = previous_static;
        }
        return self.parseAssignment();
    }

    fn parseClassStaticBlock(self: *Parser, class_index: u16) Error!u16 {
        const previous_allow_yield = self.allow_yield;
        const previous_yield_reserved = self.yield_reserved;
        const previous_allow_await = self.allow_await;
        const previous_await_reserved = self.await_reserved;
        const previous_return_allowed = self.return_allowed;
        const previous_arguments_forbidden = self.arguments_forbidden;
        const previous_breakable_depth = self.breakable_depth;
        const previous_iteration_depth = self.iteration_depth;
        const previous_active_label_count = self.active_label_count;
        self.allow_yield = false;
        self.yield_reserved = true;
        self.allow_await = false;
        self.await_reserved = true;
        self.return_allowed = false;
        self.arguments_forbidden = true;
        self.breakable_depth = 0;
        self.iteration_depth = 0;
        self.active_label_count = 0;
        defer {
            self.allow_yield = previous_allow_yield;
            self.yield_reserved = previous_yield_reserved;
            self.allow_await = previous_allow_await;
            self.await_reserved = previous_await_reserved;
            self.return_allowed = previous_return_allowed;
            self.arguments_forbidden = previous_arguments_forbidden;
            self.breakable_depth = previous_breakable_depth;
            self.iteration_depth = previous_iteration_depth;
            self.active_label_count = previous_active_label_count;
        }
        return self.parseBlockWithSuper(class_index, true);
    }

    fn parseClassFieldInitializer(self: *Parser, class_index: u16, static: bool) Error!u16 {
        const previous_allow_yield = self.allow_yield;
        const previous_yield_reserved = self.yield_reserved;
        const previous_allow_await = self.allow_await;
        const previous_await_reserved = self.await_reserved;
        const previous_arguments_forbidden = self.arguments_forbidden;
        self.allow_yield = false;
        self.yield_reserved = true;
        self.allow_await = false;
        self.await_reserved = true;
        self.arguments_forbidden = true;
        defer {
            self.allow_yield = previous_allow_yield;
            self.yield_reserved = previous_yield_reserved;
            self.allow_await = previous_allow_await;
            self.await_reserved = previous_await_reserved;
            self.arguments_forbidden = previous_arguments_forbidden;
        }
        return self.parseExpressionWithSuper(class_index, static);
    }

    fn parseFunctionParts(self: *Parser, allow_duplicate_simple: bool, generator: bool, async_function: bool) Error!FunctionParts {
        const strict_range_start = self.program.node_count;
        const previous_allow_yield = self.allow_yield;
        const previous_yield_reserved = self.yield_reserved;
        const previous_allow_await = self.allow_await;
        const previous_await_reserved = self.await_reserved;
        const previous_allow_new_target = self.allow_new_target;
        const previous_return_allowed = self.return_allowed;
        const previous_arguments_forbidden = self.arguments_forbidden;
        const previous_breakable_depth = self.breakable_depth;
        const previous_iteration_depth = self.iteration_depth;
        const previous_active_label_count = self.active_label_count;
        defer {
            self.allow_yield = previous_allow_yield;
            self.yield_reserved = previous_yield_reserved;
            self.allow_await = previous_allow_await;
            self.await_reserved = previous_await_reserved;
            self.allow_new_target = previous_allow_new_target;
            self.return_allowed = previous_return_allowed;
            self.arguments_forbidden = previous_arguments_forbidden;
            self.breakable_depth = previous_breakable_depth;
            self.iteration_depth = previous_iteration_depth;
            self.active_label_count = previous_active_label_count;
        }
        self.allow_new_target = true;
        self.return_allowed = true;
        self.arguments_forbidden = false;
        self.breakable_depth = 0;
        self.iteration_depth = 0;
        self.active_label_count = 0;
        self.allow_yield = false;
        self.yield_reserved = generator;
        self.allow_await = false;
        self.await_reserved = async_function;
        try self.expect(.l_paren);
        const parameters = try self.parseParameterList();
        try self.validateParameterList(parameters, allow_duplicate_simple);
        self.allow_yield = generator;
        self.yield_reserved = generator;
        self.allow_await = async_function;
        self.await_reserved = async_function;
        const body = try self.parseFunctionBody();
        try self.validateParametersAgainstBody(parameters, body);
        const strict = self.blockHasUseStrict(body);
        if (strict) {
            try self.validateParameterList(parameters, false);
            var parameter = parameters;
            while (parameter != none) : (parameter = self.program.nodes[parameter].next)
                try self.validateStrictPattern(self.program.nodes[parameter].b);
            try self.validateStrictRange(strict_range_start, self.program.node_count);
        }
        return .{ .parameters = parameters, .body = body, .strict = strict };
    }

    fn parseParameterList(self: *Parser) Error!u16 {
        var first: u16 = none;
        var last: u16 = none;
        var count: usize = 0;
        if (!self.at(.r_paren)) {
            while (true) {
                if (count >= max_parameters) return error.BindingLimit;
                const rest = self.match(.ellipsis);
                const target = try self.parseBindingTarget();
                var initializer: u16 = none;
                if (self.match(.equal)) {
                    if (rest) return error.SyntaxError;
                    initializer = try self.parseAssignment();
                }
                const node = try self.program.addNode(.{
                    .kind = .parameter,
                    .a = initializer,
                    .b = target,
                    .text = if (self.program.nodes[target].kind == .identifier) self.program.nodes[target].text else .{},
                    .flags = if (rest) flag_rest else 0,
                });
                appendNode(self.program, &first, &last, node);
                count += 1;
                if (rest) {
                    if (!self.at(.r_paren)) return error.SyntaxError;
                    break;
                }
                if (!self.match(.comma)) break;
                if (self.at(.r_paren)) break;
            }
        }
        try self.expect(.r_paren);
        return first;
    }

    fn validateParameterList(self: *Parser, first: u16, allow_duplicate_simple: bool) Error!void {
        var names: [max_bindings]StringRef = undefined;
        var name_count: usize = 0;
        var simple = true;
        var parameter = first;
        while (parameter != none) : (parameter = self.program.nodes[parameter].next) {
            const node = self.program.nodes[parameter];
            if (node.kind != .parameter) return error.SyntaxError;
            if (node.flags & flag_rest != 0 or node.a != none or self.program.nodes[node.b].kind != .identifier) simple = false;
            try self.collectPatternNames(node.b, names[0..], &name_count);
        }
        for (names[0..name_count], 0..) |name, index| {
            for (names[index + 1 .. name_count]) |later| {
                if (equals(self.program.text(name), self.program.text(later)) and !(allow_duplicate_simple and simple)) return error.SyntaxError;
            }
        }
    }

    fn collectPatternNames(self: *Parser, index: u16, names: []StringRef, count: *usize) Error!void {
        if (index == none or index >= self.program.node_count) return error.SyntaxError;
        const pattern = self.program.nodes[index];
        if (pattern.kind == .identifier) {
            if (count.* >= names.len) return error.BindingLimit;
            names[count.*] = pattern.text;
            count.* += 1;
            return;
        }
        if (!isPatternKind(pattern.kind)) return error.SyntaxError;
        var current = pattern.a;
        while (current != none) : (current = self.program.nodes[current].next) {
            const element = self.program.nodes[current];
            if (element.kind != .pattern_element) return error.SyntaxError;
            if (element.a != none) try self.collectPatternNames(element.a, names, count);
        }
    }

    fn parseIf(self: *Parser) Error!u16 {
        try self.expect(.l_paren);
        const condition = try self.parseExpression();
        try self.expect(.r_paren);
        const then_branch = try self.parseStatement();
        const else_branch = if (self.match(.kw_else)) try self.parseStatement() else none;
        return self.program.addNode(.{ .kind = .if_statement, .a = condition, .b = then_branch, .c = else_branch });
    }

    fn parseWhile(self: *Parser) Error!u16 {
        const source_offset = self.program.workspace.tokens[self.current - 1].source_offset;
        try self.expect(.l_paren);
        const condition = try self.parseExpression();
        try self.expect(.r_paren);
        return self.program.addNode(.{ .kind = .while_statement, .a = condition, .b = try self.parseIterationStatement(), .source_offset = source_offset });
    }

    fn parseIterationStatement(self: *Parser) Error!u16 {
        self.breakable_depth += 1;
        self.iteration_depth += 1;
        defer {
            self.breakable_depth -= 1;
            self.iteration_depth -= 1;
        }
        return self.parseStatement();
    }

    fn parseDoWhile(self: *Parser) Error!u16 {
        const source_offset = self.program.workspace.tokens[self.current - 1].source_offset;
        const body = try self.parseIterationStatement();
        try self.expect(.kw_while);
        try self.expect(.l_paren);
        const condition = try self.parseExpression();
        try self.expect(.r_paren);
        _ = self.match(.semicolon);
        return self.program.addNode(.{ .kind = .do_while_statement, .a = condition, .b = body, .source_offset = source_offset });
    }

    fn parseFor(self: *Parser) Error!u16 {
        const source_offset = self.program.workspace.tokens[self.current - 1].source_offset;
        if (!self.allow_await and self.atUnescapedIdentifier("await")) return error.SyntaxError;
        const async_iteration = self.allow_await and self.atUnescapedIdentifier("await");
        if (async_iteration) _ = self.advance();
        try self.expect(.l_paren);
        const declaration_enumeration = if (self.at(.kw_let) or self.at(.kw_const) or self.at(.kw_var)) self.forEnumerationHeadAhead(1) else .none;
        if (declaration_enumeration != .none) {
            if (async_iteration and declaration_enumeration != .of) return error.SyntaxError;
            const declaration = self.advance();
            const target = try self.parseBindingTarget();
            try self.consumeForEnumerationSeparator(declaration_enumeration);
            const variable = try self.program.addNode(.{
                .kind = .variable,
                .b = target,
                .text = if (self.program.nodes[target].kind == .identifier) self.program.nodes[target].text else .{},
                .flags = (if (declaration.kind == .kw_const) flag_const else 0) |
                    (if (declaration.kind == .kw_var) flag_var else 0),
            });
            const iterable = try self.parseExpression();
            try self.expect(.r_paren);
            return self.program.addNode(.{
                .kind = if (declaration_enumeration == .in) .for_in_statement else .for_of_statement,
                .a = variable,
                .b = iterable,
                .c = try self.parseIterationStatement(),
                .flags = if (async_iteration) flag_async else 0,
                .source_offset = source_offset,
            });
        }
        const assignment_enumeration = self.forEnumerationHeadAhead(0);
        if (assignment_enumeration != .none) {
            if (async_iteration and assignment_enumeration != .of) return error.SyntaxError;
            const target = try self.convertAssignmentTarget(try self.parseConditionalNoIn());
            try self.consumeForEnumerationSeparator(assignment_enumeration);
            const iterable = try self.parseExpression();
            try self.expect(.r_paren);
            return self.program.addNode(.{
                .kind = if (assignment_enumeration == .in) .for_in_statement else .for_of_statement,
                .a = target,
                .b = iterable,
                .c = try self.parseIterationStatement(),
                .flags = if (async_iteration) flag_async else 0,
                .source_offset = source_offset,
            });
        }
        if (async_iteration) return error.SyntaxError;
        var initializer: u16 = none;
        if (!self.at(.semicolon)) {
            const previous_allow_in = self.allow_in;
            self.allow_in = false;
            defer self.allow_in = previous_allow_in;
            if (self.at(.kw_let) or self.at(.kw_const) or self.at(.kw_var)) {
                initializer = try self.parseVariable(false, false);
            } else {
                initializer = try self.parseExpression();
                try self.expect(.semicolon);
            }
        } else {
            _ = self.advance();
        }
        const condition = if (!self.at(.semicolon)) try self.parseExpression() else none;
        try self.expect(.semicolon);
        const update = if (!self.at(.r_paren)) try self.parseExpression() else none;
        try self.expect(.r_paren);
        const body = try self.parseIterationStatement();
        return self.program.addNode(.{ .kind = .for_statement, .a = initializer, .b = condition, .c = update, .d = body, .source_offset = source_offset });
    }

    fn parseConditionalNoIn(self: *Parser) Error!u16 {
        const previous_allow_in = self.allow_in;
        self.allow_in = false;
        defer self.allow_in = previous_allow_in;
        return self.parseConditional();
    }

    fn parseSwitch(self: *Parser) Error!u16 {
        self.breakable_depth += 1;
        defer self.breakable_depth -= 1;
        try self.expect(.l_paren);
        const discriminant = try self.parseExpression();
        try self.expect(.r_paren);
        try self.expect(.l_brace);
        var first_case: u16 = none;
        var last_case: u16 = none;
        while (!self.at(.r_brace) and !self.at(.eof)) {
            var case_test: u16 = none;
            if (self.match(.kw_case)) {
                case_test = try self.parseExpression();
            } else if (!self.match(.kw_default)) {
                return error.UnexpectedToken;
            }
            try self.expect(.colon);
            var first_statement: u16 = none;
            var last_statement: u16 = none;
            while (!self.at(.kw_case) and !self.at(.kw_default) and !self.at(.r_brace) and !self.at(.eof)) {
                appendNode(self.program, &first_statement, &last_statement, try self.parseStatementListItem(false));
            }
            appendNode(self.program, &first_case, &last_case, try self.program.addNode(.{
                .kind = .switch_case,
                .a = case_test,
                .b = first_statement,
            }));
        }
        try self.expect(.r_brace);
        var lexical_names: [max_bindings]StringRef = undefined;
        var variable_names: [max_bindings]StringRef = undefined;
        var lexical_count: usize = 0;
        var variable_count: usize = 0;
        var case_index = first_case;
        while (case_index != none) : (case_index = self.program.nodes[case_index].next) {
            var statement = self.program.nodes[case_index].b;
            while (statement != none) : (statement = self.program.nodes[statement].next) {
                try self.appendDirectLexicalNames(statement, false, lexical_names[0..], &lexical_count);
                try self.appendRecursiveVarNames(statement, variable_names[0..], &variable_count);
            }
        }
        for (lexical_names[0..lexical_count], 0..) |name, index| {
            for (lexical_names[index + 1 .. lexical_count]) |other|
                if (equals(self.program.text(name), self.program.text(other))) return error.SyntaxError;
            for (variable_names[0..variable_count]) |other|
                if (equals(self.program.text(name), self.program.text(other))) return error.SyntaxError;
        }
        return self.program.addNode(.{ .kind = .switch_statement, .a = discriminant, .b = first_case });
    }

    fn parseTry(self: *Parser) Error!u16 {
        const body = try self.parseBlock();
        var catch_name: StringRef = .{};
        var catch_pattern: u16 = none;
        var catch_body: u16 = none;
        var finally_body: u16 = none;
        if (self.match(.kw_catch)) {
            if (self.match(.l_paren)) {
                catch_pattern = try self.parseBindingTarget();
                if (self.program.nodes[catch_pattern].kind == .identifier) catch_name = self.program.nodes[catch_pattern].text;
                try self.expect(.r_paren);
            }
            catch_body = try self.parseBlock();
            if (catch_pattern != none) {
                var catch_names: [max_bindings]StringRef = undefined;
                var lexical_names: [max_bindings]StringRef = undefined;
                var catch_count: usize = 0;
                var lexical_count: usize = 0;
                try self.collectPatternNames(catch_pattern, catch_names[0..], &catch_count);
                var statement = self.program.nodes[catch_body].a;
                while (statement != none) : (statement = self.program.nodes[statement].next)
                    try self.appendDirectLexicalNames(statement, false, lexical_names[0..], &lexical_count);
                for (catch_names[0..catch_count]) |name|
                    for (lexical_names[0..lexical_count]) |other|
                        if (equals(self.program.text(name), self.program.text(other))) return error.SyntaxError;
            }
        }
        if (self.match(.kw_finally)) finally_body = try self.parseBlock();
        if (catch_body == none and finally_body == none) return error.SyntaxError;
        return self.program.addNode(.{
            .kind = .try_statement,
            .a = body,
            .b = catch_body,
            .c = finally_body,
            .d = catch_pattern,
            .text = catch_name,
        });
    }

    fn forEnumerationHeadAhead(self: *const Parser, skip: usize) ForEnumerationKind {
        var cursor = self.current + skip;
        var parentheses: usize = 0;
        var brackets: usize = 0;
        var braces: usize = 0;
        while (cursor < self.program.token_count) : (cursor += 1) {
            const kind = self.program.workspace.tokens[cursor].kind;
            switch (kind) {
                .l_paren => parentheses += 1,
                .r_paren => {
                    if (parentheses == 0 and brackets == 0 and braces == 0) return .none;
                    parentheses -|= 1;
                },
                .l_bracket => brackets += 1,
                .r_bracket => {
                    brackets -|= 1;
                },
                .l_brace => braces += 1,
                .r_brace => {
                    braces -|= 1;
                },
                .kw_in => if (parentheses == 0 and brackets == 0 and braces == 0) return .in,
                .identifier => if (parentheses == 0 and brackets == 0 and braces == 0 and
                    equals(self.program.text(self.program.workspace.tokens[cursor].text), "of")) return .of,
                .semicolon, .eof => if (parentheses == 0 and brackets == 0 and braces == 0) return .none,
                else => {},
            }
        }
        return .none;
    }

    fn consumeForEnumerationSeparator(self: *Parser, kind: ForEnumerationKind) Error!void {
        switch (kind) {
            .in => try self.expect(.kw_in),
            .of => {
                if (!self.at(.identifier) or !equals(self.program.text(self.peek().text), "of")) return error.UnexpectedToken;
                _ = self.advance();
            },
            .none => return error.UnexpectedToken,
        }
    }

    fn parseImport(self: *Parser) Error!u16 {
        var first: u16 = none;
        var last: u16 = none;
        if (self.at(.string)) {
            const module_name = self.advance();
            try self.consumeSemicolon();
            self.program.module_statement_count += 1;
            return self.program.addNode(.{ .kind = .import_statement, .text = module_name.text });
        }
        if (self.at(.identifier)) {
            const local = self.advance();
            const local_node = try self.program.addNode(.{ .kind = .identifier, .text = local.text });
            appendNode(self.program, &first, &last, try self.program.addNode(.{
                .kind = .property,
                .a = local_node,
                .flags = flag_module_default,
            }));
            if (self.match(.comma)) {
                // A default binding may be followed by named or namespace bindings.
            } else {
                try self.expect(.kw_from);
                const module_name = self.advance();
                if (module_name.kind != .string) return error.SyntaxError;
                try self.consumeSemicolon();
                self.program.module_statement_count += 1;
                return self.program.addNode(.{ .kind = .import_statement, .a = first, .text = module_name.text });
            }
        }
        if (self.match(.star)) {
            try self.expect(.kw_as);
            const local = try self.expectIdentifier();
            const local_node = try self.program.addNode(.{ .kind = .identifier, .text = local.text });
            appendNode(self.program, &first, &last, try self.program.addNode(.{
                .kind = .property,
                .a = local_node,
                .flags = flag_module_namespace,
            }));
        } else if (self.match(.l_brace)) {
            while (!self.at(.r_brace)) {
                const imported = self.advance();
                if (imported.kind != .identifier and imported.kind != .kw_default) return error.SyntaxError;
                const local = if (self.match(.kw_as)) try self.expectIdentifier() else imported;
                const local_node = try self.program.addNode(.{ .kind = .identifier, .text = local.text });
                const binding = try self.program.addNode(.{
                    .kind = .property,
                    .a = local_node,
                    .text = imported.text,
                    .flags = if (imported.kind == .kw_default) flag_module_default else 0,
                });
                appendNode(self.program, &first, &last, binding);
                if (!self.match(.comma)) break;
                if (self.at(.r_brace)) break;
            }
            try self.expect(.r_brace);
        } else return error.SyntaxError;
        try self.expect(.kw_from);
        const module_name = self.advance();
        if (module_name.kind != .string) return error.SyntaxError;
        try self.consumeSemicolon();
        self.program.module_statement_count += 1;
        return self.program.addNode(.{ .kind = .import_statement, .a = first, .text = module_name.text });
    }

    fn parseExport(self: *Parser) Error!u16 {
        self.program.module_statement_count += 1;
        if (self.at(.kw_let) or self.at(.kw_const) or self.at(.kw_var)) return self.parseVariable(true, true);
        if (self.at(.kw_function) or (self.at(.kw_async) and self.peekKind(1) == .kw_function and self.tokensShareLine(self.current, self.current + 1))) return self.parseFunctionDeclaration(true);
        if (self.match(.kw_class)) return self.parseClassDefinition(true, true);
        if (self.match(.kw_default)) {
            const expression = if (self.match(.kw_function))
                try self.parseFunctionExpression(false, self.program.workspace.tokens[self.current - 1].source_offset)
            else if (self.at(.kw_async) and self.peekKind(1) == .kw_function and self.tokensShareLine(self.current, self.current + 1)) blk: {
                const async_token = self.advance();
                try self.expect(.kw_function);
                break :blk try self.parseFunctionExpression(true, async_token.source_offset);
            } else if (self.match(.kw_class))
                try self.parseClassDefinition(false, false)
            else
                try self.parseAssignment();
            try self.consumeSemicolon();
            return self.program.addNode(.{ .kind = .export_default, .a = expression });
        }
        if (self.match(.star)) {
            var first: u16 = none;
            var flags: u16 = flag_module_star;
            if (self.match(.kw_as)) {
                const exported = try self.expectIdentifier();
                first = try self.program.addNode(.{
                    .kind = .property,
                    .text = exported.text,
                    .flags = flag_module_namespace,
                });
                flags = 0;
            }
            try self.expect(.kw_from);
            const module_name = self.advance();
            if (module_name.kind != .string) return error.SyntaxError;
            try self.consumeSemicolon();
            return self.program.addNode(.{ .kind = .export_list, .a = first, .text = module_name.text, .flags = flags });
        }
        if (self.match(.l_brace)) {
            var first: u16 = none;
            var last: u16 = none;
            while (!self.at(.r_brace)) {
                const local = self.advance();
                if (local.kind != .identifier and local.kind != .kw_default) return error.SyntaxError;
                const exported = if (self.match(.kw_as)) self.advance() else local;
                if (exported.kind != .identifier and exported.kind != .kw_default) return error.SyntaxError;
                const local_node = try self.program.addNode(.{ .kind = .identifier, .text = local.text });
                const entry = try self.program.addNode(.{
                    .kind = .property,
                    .a = local_node,
                    .text = exported.text,
                    .flags = (if (local.kind == .kw_default) flag_module_default else 0) |
                        (if (exported.kind == .kw_default) flag_module_export_default else 0),
                });
                appendNode(self.program, &first, &last, entry);
                if (!self.match(.comma)) break;
                if (self.at(.r_brace)) break;
            }
            try self.expect(.r_brace);
            var source: StringRef = .{};
            if (self.match(.kw_from)) {
                const module_name = self.advance();
                if (module_name.kind != .string) return error.SyntaxError;
                source = module_name.text;
            }
            try self.consumeSemicolon();
            return self.program.addNode(.{ .kind = .export_list, .a = first, .text = source });
        }
        return error.SyntaxError;
    }

    fn parseExpression(self: *Parser) Error!u16 {
        var expression = try self.parseAssignment();
        while (self.match(.comma)) {
            expression = try self.program.addNode(.{
                .kind = .binary,
                .a = expression,
                .b = try self.parseAssignment(),
                .flags = @intFromEnum(BinaryOp.comma),
            });
        }
        return expression;
    }

    fn parseAssignment(self: *Parser) Error!u16 {
        if (self.allow_yield and self.atUnescapedIdentifier("yield")) return self.parseYieldExpression();
        var left = try self.parseConditional();
        const operation: ?AssignmentOp = switch (self.peek().kind) {
            .equal => .assign,
            .plus_equal => .add,
            .minus_equal => .subtract,
            .star_equal => .multiply,
            .star_star_equal => .exponentiate,
            .slash_equal => .divide,
            .percent_equal => .remainder,
            .ampersand_equal => .bitwise_and,
            .caret_equal => .bitwise_xor,
            .pipe_equal => .bitwise_or,
            .shift_left_equal => .shift_left,
            .shift_right_equal => .shift_right,
            .shift_unsigned_equal => .shift_unsigned,
            .and_and_equal => .logical_and,
            .or_or_equal => .logical_or,
            .nullish_equal => .nullish,
            else => null,
        };
        if (operation) |op| {
            if (self.program.nodes[left].kind == .optional_chain) return error.SyntaxError;
            if (op == .assign and (self.program.nodes[left].kind == .array_literal or self.program.nodes[left].kind == .object_literal)) {
                left = try self.convertAssignmentPattern(left);
            } else if (isPatternKind(self.program.nodes[left].kind)) {
                return error.SyntaxError;
            }
            _ = self.advance();
            left = try self.program.addNode(.{
                .kind = .assignment,
                .a = left,
                .b = try self.parseAssignment(),
                .flags = @intFromEnum(op),
            });
        }
        return left;
    }

    fn parseYieldExpression(self: *Parser) Error!u16 {
        _ = self.advance();
        const delegate = !self.lineTerminatorBeforeCurrent() and self.match(.star);
        if (delegate and (self.at(.semicolon) or self.at(.r_brace) or self.at(.eof))) return error.SyntaxError;
        const omitted = !delegate and (self.lineTerminatorBeforeCurrent() or self.at(.semicolon) or self.at(.r_brace) or
            self.at(.eof) or self.at(.comma) or self.at(.r_paren) or self.at(.r_bracket) or self.at(.colon));
        const value = if (omitted) none else try self.parseAssignment();
        return self.program.addNode(.{
            .kind = .yield_expression,
            .a = value,
            .flags = if (delegate) flag_yield_delegate else 0,
        });
    }

    fn convertAssignmentTarget(self: *Parser, index: u16) Error!u16 {
        return switch (self.program.nodes[index].kind) {
            .identifier, .member => index,
            .group => self.convertAssignmentTarget(self.program.nodes[index].a),
            .array_pattern, .object_pattern => index,
            .array_literal, .object_literal => self.convertAssignmentPattern(index),
            else => error.InvalidAssignment,
        };
    }

    fn convertAssignmentPattern(self: *Parser, index: u16) Error!u16 {
        var pattern = &self.program.nodes[index];
        if (pattern.kind == .array_literal) {
            const original_first = pattern.a;
            pattern.kind = .array_pattern;
            pattern.a = none;
            var first: u16 = none;
            var last: u16 = none;
            var current = original_first;
            while (current != none) {
                const next = self.program.nodes[current].next;
                const item = self.program.nodes[current];
                const element = if (item.kind == .empty and item.flags & flag_elision != 0)
                    try self.program.addNode(.{ .kind = .pattern_element, .flags = flag_elision })
                else if (item.kind == .spread_element) blk: {
                    if (next != none or item.flags & flag_elision != 0) return error.SyntaxError;
                    break :blk try self.program.addNode(.{
                        .kind = .pattern_element,
                        .a = try self.convertAssignmentTarget(item.a),
                        .flags = flag_rest,
                    });
                } else if (item.kind == .assignment) blk: {
                    if (@as(AssignmentOp, @enumFromInt(item.flags)) != .assign) return error.InvalidAssignment;
                    break :blk try self.program.addNode(.{
                        .kind = .pattern_element,
                        .a = try self.convertAssignmentTarget(item.a),
                        .b = item.b,
                    });
                } else try self.program.addNode(.{
                    .kind = .pattern_element,
                    .a = try self.convertAssignmentTarget(current),
                });
                appendNode(self.program, &first, &last, element);
                current = next;
            }
            self.program.nodes[index].a = first;
            return index;
        }
        if (pattern.kind != .object_literal) return error.InvalidAssignment;
        const original_first = pattern.a;
        pattern.kind = .object_pattern;
        pattern.a = none;
        var first: u16 = none;
        var last: u16 = none;
        var current = original_first;
        while (current != none) {
            const next = self.program.nodes[current].next;
            const property = self.program.nodes[current];
            if (property.kind != .property) return error.InvalidAssignment;
            var target = property.a;
            var initializer = property.c;
            var flags = property.flags & ~(flag_proto_setter | flag_elision | flag_spread);
            if (property.flags & flag_spread != 0) {
                if (next != none or property.flags & flag_elision != 0) return error.SyntaxError;
                target = try self.convertAssignmentTarget(property.a);
                flags = flag_rest;
            } else {
                if (self.program.nodes[target].kind == .assignment) {
                    const assignment = self.program.nodes[target];
                    if (@as(AssignmentOp, @enumFromInt(assignment.flags)) != .assign or initializer != none) return error.InvalidAssignment;
                    target = assignment.a;
                    initializer = assignment.b;
                }
                target = try self.convertAssignmentTarget(target);
            }
            appendNode(self.program, &first, &last, try self.program.addNode(.{
                .kind = .pattern_element,
                .a = target,
                .b = initializer,
                .c = property.b,
                .text = property.text,
                .number = property.number,
                .flags = flags,
            }));
            current = next;
        }
        self.program.nodes[index].a = first;
        return index;
    }

    fn parseConditional(self: *Parser) Error!u16 {
        const condition = try self.parseBinary(1);
        if (!self.match(.question)) return condition;
        const then_value = try self.parseAssignment();
        try self.expect(.colon);
        const else_value = try self.parseAssignment();
        return self.program.addNode(.{ .kind = .conditional, .a = condition, .b = then_value, .c = else_value });
    }

    fn parseBinary(self: *Parser, minimum_precedence: u8) Error!u16 {
        var left = try self.parseUnary();
        while (binaryInfo(self.peek().kind)) |info| {
            if (info.operation == .in and !self.allow_in) break;
            if (info.precedence < minimum_precedence) break;
            if (info.operation == .exponentiate and self.program.nodes[left].kind == .unary) return error.SyntaxError;
            _ = self.advance();
            const right = try self.parseBinary(if (info.operation == .exponentiate) info.precedence else info.precedence + 1);
            if (self.program.nodes[left].kind == .private_identifier) {
                if (info.operation != .in) return error.SyntaxError;
                const private_name = self.program.nodes[left];
                left = try self.program.addNode(.{
                    .kind = .private_in,
                    .a = right,
                    .c = private_name.c,
                    .text = private_name.text,
                });
                continue;
            }
            const left_operation = nodeBinaryOperation(self.program, left);
            const right_operation = nodeBinaryOperation(self.program, right);
            if (info.operation == .nullish) {
                if (left_operation == .logical_and or left_operation == .logical_or or
                    right_operation == .logical_and or right_operation == .logical_or) return error.SyntaxError;
            } else if (info.operation == .logical_and or info.operation == .logical_or) {
                if (left_operation == .nullish or right_operation == .nullish) return error.SyntaxError;
            }
            left = try self.program.addNode(.{
                .kind = .binary,
                .a = left,
                .b = right,
                .flags = @intFromEnum(info.operation),
            });
        }
        return left;
    }

    fn parseUnary(self: *Parser) Error!u16 {
        if (self.allow_await and self.atUnescapedIdentifier("await")) {
            _ = self.advance();
            return self.program.addNode(.{ .kind = .await_expression, .a = try self.parseUnary() });
        }
        const operation: ?UnaryOp = switch (self.peek().kind) {
            .plus => .positive,
            .minus => .negative,
            .bang => .logical_not,
            .tilde => .bitwise_not,
            .kw_typeof => .type_of,
            .kw_void => .void_value,
            .kw_delete => .delete_value,
            else => null,
        };
        if (operation) |op| {
            _ = self.advance();
            return self.program.addNode(.{ .kind = .unary, .a = try self.parseUnary(), .flags = @intFromEnum(op) });
        }
        if (self.at(.kw_new) and self.peekKind(1) == .dot) {
            _ = self.advance();
            _ = self.advance();
            const target = try self.expectIdentifier();
            if (!self.allow_new_target or !equals(self.program.text(target.text), "target")) return error.SyntaxError;
            return self.program.addNode(.{ .kind = .new_target });
        }
        if (self.match(.kw_new)) {
            var constructor = if (self.at(.kw_new)) try self.parseUnary() else try self.parsePrimary();
            while (true) {
                if (self.match(.dot)) {
                    const property = try self.expectPropertyName();
                    constructor = try self.program.addNode(.{ .kind = .member, .a = constructor, .text = property.text });
                    continue;
                }
                if (self.match(.l_bracket)) {
                    const property = try self.parseExpression();
                    try self.expect(.r_bracket);
                    constructor = try self.program.addNode(.{ .kind = .member, .a = constructor, .b = property, .flags = flag_computed });
                    continue;
                }
                break;
            }
            if (self.at(.question_dot)) return error.SyntaxError;
            if (self.match(.l_paren)) constructor = try self.program.addNode(.{
                .kind = .call,
                .a = constructor,
                .b = try self.parseCallArguments(),
            });
            if (self.program.nodes[constructor].kind == .optional_chain or self.program.nodes[constructor].kind == .super_call) return error.SyntaxError;
            return self.parsePostfixFrom(try self.program.addNode(.{ .kind = .new_expression, .a = constructor }));
        }
        if (self.at(.plus_plus) or self.at(.minus_minus)) {
            const increment = self.advance().kind == .plus_plus;
            const target = try self.parseUnary();
            if (self.program.nodes[target].kind == .optional_chain) return error.SyntaxError;
            return self.program.addNode(.{
                .kind = .update,
                .a = target,
                .flags = flag_prefix | @as(u16, if (increment) 1 else 0),
            });
        }
        return self.parsePostfix();
    }

    fn parsePostfix(self: *Parser) Error!u16 {
        return self.parsePostfixFrom(try self.parsePrimary());
    }

    fn parsePostfixFrom(self: *Parser, initial: u16) Error!u16 {
        var expression = initial;
        var chain: u16 = none;
        var last_chain_step: u16 = none;
        while (true) {
            if (self.at(.template) or self.at(.template_head)) {
                if (chain != none) return error.SyntaxError;
                const literal = try self.parseTemplateLiteral(self.advance(), true);
                expression = try self.program.addNode(.{ .kind = .tagged_template, .a = expression, .b = literal });
                continue;
            }
            if (self.match(.question_dot)) {
                if (self.program.nodes[expression].kind == .super_reference) return error.SyntaxError;
                if (chain == none) {
                    chain = try self.program.addNode(.{ .kind = .optional_chain, .a = expression });
                    expression = chain;
                }
                const step = if (self.match(.l_bracket)) blk: {
                    const property = try self.parseExpression();
                    try self.expect(.r_bracket);
                    break :blk try self.program.addNode(.{ .kind = .chain_member, .a = property, .flags = flag_optional | flag_computed });
                } else if (self.match(.l_paren)) blk: {
                    break :blk try self.program.addNode(.{ .kind = .chain_call, .a = try self.parseCallArguments(), .flags = flag_optional });
                } else if (self.at(.private_identifier)) blk: {
                    if (self.current_class == none) return error.SyntaxError;
                    const property = self.advance();
                    break :blk try self.program.addNode(.{
                        .kind = .chain_member,
                        .c = self.current_class,
                        .text = property.text,
                        .flags = flag_optional | flag_private,
                    });
                } else blk: {
                    if (!isPropertyNameToken(self.peek().kind)) return error.SyntaxError;
                    const property = self.advance();
                    break :blk try self.program.addNode(.{ .kind = .chain_member, .text = property.text, .flags = flag_optional });
                };
                self.appendChainStep(chain, &last_chain_step, step);
                continue;
            }
            if (self.match(.dot)) {
                if (self.program.nodes[expression].kind == .super_reference) {
                    if (self.at(.private_identifier)) return error.SyntaxError;
                    const property = try self.expectPropertyName();
                    expression = try self.program.addNode(.{
                        .kind = .member,
                        .c = self.super_class,
                        .text = property.text,
                        .flags = flag_super | (if (self.super_static) flag_super_static else 0),
                    });
                    continue;
                }
                if (self.at(.private_identifier)) {
                    if (self.current_class == none) return error.SyntaxError;
                    const property = self.advance();
                    const member = try self.program.addNode(.{
                        .kind = .member,
                        .a = expression,
                        .c = self.current_class,
                        .text = property.text,
                        .flags = flag_private,
                    });
                    if (chain != none) {
                        self.program.nodes[member].kind = .chain_member;
                        self.program.nodes[member].a = none;
                        self.appendChainStep(chain, &last_chain_step, member);
                    } else {
                        expression = member;
                    }
                    continue;
                }
                const property = try self.expectPropertyName();
                if (chain != none) {
                    self.appendChainStep(chain, &last_chain_step, try self.program.addNode(.{ .kind = .chain_member, .text = property.text }));
                } else {
                    expression = try self.program.addNode(.{ .kind = .member, .a = expression, .text = property.text });
                }
                continue;
            }
            if (self.match(.l_bracket)) {
                const property = try self.parseExpression();
                try self.expect(.r_bracket);
                if (self.program.nodes[expression].kind == .super_reference) {
                    expression = try self.program.addNode(.{
                        .kind = .member,
                        .b = property,
                        .c = self.super_class,
                        .flags = flag_super | flag_computed | (if (self.super_static) flag_super_static else 0),
                    });
                    continue;
                }
                if (chain != none) {
                    self.appendChainStep(chain, &last_chain_step, try self.program.addNode(.{ .kind = .chain_member, .a = property, .flags = flag_computed }));
                } else {
                    expression = try self.program.addNode(.{ .kind = .member, .a = expression, .b = property, .flags = flag_computed });
                }
                continue;
            }
            if (self.match(.l_paren)) {
                const arguments = try self.parseCallArguments();
                if (self.program.nodes[expression].kind == .super_reference) {
                    if (!self.super_call_allowed) return error.SyntaxError;
                    expression = try self.program.addNode(.{
                        .kind = .super_call,
                        .a = arguments,
                        .c = self.super_class,
                    });
                    continue;
                }
                if (chain != none) {
                    self.appendChainStep(chain, &last_chain_step, try self.program.addNode(.{ .kind = .chain_call, .a = arguments }));
                } else {
                    expression = try self.program.addNode(.{ .kind = .call, .a = expression, .b = arguments });
                }
                continue;
            }
            if (!self.lineTerminatorBeforeCurrent() and (self.at(.plus_plus) or self.at(.minus_minus))) {
                if (chain != none) return error.SyntaxError;
                const increment = self.advance().kind == .plus_plus;
                expression = try self.program.addNode(.{
                    .kind = .update,
                    .a = expression,
                    .flags = @as(u16, if (increment) 1 else 0),
                });
                continue;
            }
            break;
        }
        if (self.program.nodes[expression].kind == .super_reference) return error.SyntaxError;
        return expression;
    }

    fn appendChainStep(self: *Parser, chain: u16, last: *u16, step: u16) void {
        if (last.* == none)
            self.program.nodes[chain].b = step
        else
            self.program.nodes[last.*].next = step;
        last.* = step;
    }

    fn parseCallArguments(self: *Parser) Error!u16 {
        var first: u16 = none;
        var last: u16 = none;
        if (!self.at(.r_paren)) {
            while (true) {
                if (self.match(.ellipsis)) {
                    appendNode(self.program, &first, &last, try self.program.addNode(.{
                        .kind = .spread_element,
                        .a = try self.parseAssignment(),
                    }));
                } else {
                    appendNode(self.program, &first, &last, try self.parseAssignment());
                }
                if (!self.match(.comma)) break;
                if (self.at(.r_paren)) break;
            }
        }
        try self.expect(.r_paren);
        return first;
    }

    fn parsePrimary(self: *Parser) Error!u16 {
        const token = self.advance();
        return switch (token.kind) {
            .number => self.program.addNode(.{ .kind = .number_literal, .text = token.text, .number = token.number }),
            .bigint => self.program.addNode(.{ .kind = .bigint_literal, .text = token.text }),
            .string => self.program.addNode(.{ .kind = .string_literal, .text = token.text }),
            .template, .template_head => self.parseTemplateLiteral(token, false),
            .regex => self.program.addNode(.{ .kind = .regex_literal, .text = token.text }),
            .kw_true => self.program.addNode(.{ .kind = .boolean_literal, .flags = 1 }),
            .kw_false => self.program.addNode(.{ .kind = .boolean_literal }),
            .kw_null => self.program.addNode(.{ .kind = .null_literal }),
            .kw_this => self.program.addNode(.{ .kind = .this_expression }),
            .kw_import => if (self.match(.l_paren)) blk: {
                const specifier = try self.parseAssignment();
                try self.expect(.r_paren);
                break :blk self.program.addNode(.{ .kind = .dynamic_import, .a = specifier });
            } else if (self.match(.dot)) blk: {
                const meta = try self.expectIdentifier();
                if (!equals(self.program.text(meta.text), "meta")) return error.SyntaxError;
                self.program.module_statement_count += 1;
                break :blk self.program.addNode(.{ .kind = .import_meta });
            } else error.SyntaxError,
            .identifier => if ((self.yield_reserved and self.identifierEquals(token, "yield")) or
                (self.await_reserved and self.identifierEquals(token, "await")) or
                (self.arguments_forbidden and self.identifierEquals(token, "arguments")))
                error.SyntaxError
            else
                self.parseIdentifierOrArrow(token),
            .kw_function => self.parseFunctionExpression(false, token.source_offset),
            .kw_async => self.parseAsyncExpression(token.source_offset),
            .kw_class => self.parseClassDefinition(false, false),
            .kw_super => if (self.super_class == none)
                error.SyntaxError
            else
                self.program.addNode(.{
                    .kind = .super_reference,
                    .c = self.super_class,
                    .flags = if (self.super_static) flag_super_static else 0,
                }),
            .private_identifier => if (self.current_class == none)
                error.SyntaxError
            else
                self.program.addNode(.{ .kind = .private_identifier, .c = self.current_class, .text = token.text }),
            .l_paren => self.parseParenthesizedOrArrow(token.source_offset),
            .l_bracket => self.parseArrayLiteral(),
            .l_brace => self.parseObjectLiteral(),
            .escaped_reserved => error.SyntaxError,
            else => error.UnexpectedToken,
        };
    }

    fn parseIdentifierOrArrow(self: *Parser, token: Token) Error!u16 {
        const identifier = try self.program.addNode(.{ .kind = .identifier, .text = token.text });
        if (self.lineTerminatorBeforeCurrent() or !self.match(.fat_arrow)) return identifier;
        const target = try self.program.addNode(.{ .kind = .identifier, .text = token.text });
        const parameter = try self.program.addNode(.{ .kind = .parameter, .b = target, .text = token.text });
        const body = try self.parseArrowBody(false);
        if (self.program.nodes[body.body].kind == .block) try self.validateParametersAgainstBody(parameter, body.body);
        self.program.function_count += 1;
        return self.program.addNode(.{ .kind = .function_expression, .a = parameter, .b = body.body, .source = self.functionSource(token.source_offset), .flags = body.flags | flag_arrow });
    }

    fn parseTemplateLiteral(self: *Parser, first_token: Token, tagged: bool) Error!u16 {
        if (first_token.kind != .template and first_token.kind != .template_head) return error.UnexpectedToken;
        if (!tagged and first_token.number != 0) return error.SyntaxError;
        const first_part = try self.program.addNode(.{
            .kind = .template_part,
            .text = first_token.text,
            .flags = if (first_token.number != 0) 1 else 0,
        });
        const literal = try self.program.addNode(.{ .kind = .template_literal, .a = first_part });
        if (first_token.kind == .template) return literal;

        var current_part = first_part;
        while (true) {
            self.program.nodes[current_part].a = try self.parseExpression();
            const continuation = self.advance();
            if (continuation.kind != .template_middle and continuation.kind != .template_tail) return error.UnexpectedToken;
            if (!tagged and continuation.number != 0) return error.SyntaxError;
            const next_part = try self.program.addNode(.{
                .kind = .template_part,
                .text = continuation.text,
                .flags = if (continuation.number != 0) 1 else 0,
            });
            self.program.nodes[current_part].next = next_part;
            current_part = next_part;
            if (continuation.kind == .template_tail) return literal;
        }
    }

    fn parseAsyncExpression(self: *Parser, source_start: u32) Error!u16 {
        const async_identifier = Node{ .kind = .identifier, .text = makeSourceRef(source_start, "async".len) };
        if (self.lineTerminatorBeforeCurrent()) return self.program.addNode(async_identifier);
        if (self.match(.kw_function)) return self.parseFunctionExpression(true, source_start);
        if (self.at(.l_paren) and self.asyncParenthesizedArrowAhead()) {
            _ = self.advance();
            const parameters = try self.parseArrowParameterList(true);
            try self.validateParameterList(parameters, false);
            try self.expect(.fat_arrow);
            const body = try self.parseArrowBody(true);
            if (self.program.nodes[body.body].kind == .block) try self.validateParametersAgainstBody(parameters, body.body);
            self.program.function_count += 1;
            return self.program.addNode(.{ .kind = .function_expression, .a = parameters, .b = body.body, .source = self.functionSource(source_start), .flags = body.flags | flag_async | flag_arrow });
        }
        if (!self.at(.identifier) or self.peekKind(1) != .fat_arrow or !self.tokensShareLine(self.current, self.current + 1)) return self.program.addNode(async_identifier);
        const parameter = self.advance();
        const target = try self.program.addNode(.{ .kind = .identifier, .text = parameter.text });
        const parameter_node = try self.program.addNode(.{ .kind = .parameter, .b = target, .text = parameter.text });
        try self.expect(.fat_arrow);
        const body = try self.parseArrowBody(true);
        if (self.program.nodes[body.body].kind == .block) try self.validateParametersAgainstBody(parameter_node, body.body);
        self.program.function_count += 1;
        return self.program.addNode(.{ .kind = .function_expression, .a = parameter_node, .b = body.body, .source = self.functionSource(source_start), .flags = body.flags | flag_async | flag_arrow });
    }

    fn parseFunctionExpression(self: *Parser, async_function: bool, source_start: u32) Error!u16 {
        const generator = self.match(.star);
        var name: StringRef = .{};
        if (self.at(.identifier)) {
            const name_token = self.advance();
            if (self.yield_reserved and self.identifierEquals(name_token, "yield")) return error.SyntaxError;
            if (self.await_reserved and self.identifierEquals(name_token, "await")) return error.SyntaxError;
            name = name_token.text;
        }
        const parts = try self.parseFunctionPartsWithoutSuper(!async_function and !generator, generator, async_function);
        if (parts.strict and name.len != 0 and self.restrictedStrictName(name)) return error.SyntaxError;
        self.program.function_count += 1;
        return self.program.addNode(.{
            .kind = .function_expression,
            .a = parts.parameters,
            .b = parts.body,
            .text = name,
            .source = self.functionSource(source_start),
            .flags = (if (async_function) flag_async else 0) | (if (generator) flag_generator else 0) |
                (if (parts.strict) flag_strict else 0),
        });
    }

    fn parseParenthesizedOrArrow(self: *Parser, source_start: u32) Error!u16 {
        if (self.parenthesizedArrowAhead()) {
            const parameters = try self.parseArrowParameterList(false);
            try self.validateParameterList(parameters, false);
            try self.expect(.fat_arrow);
            const body = try self.parseArrowBody(false);
            if (self.program.nodes[body.body].kind == .block) try self.validateParametersAgainstBody(parameters, body.body);
            self.program.function_count += 1;
            return self.program.addNode(.{ .kind = .function_expression, .a = parameters, .b = body.body, .source = self.functionSource(source_start), .flags = body.flags | flag_arrow });
        }
        const expression = try self.parseExpression();
        try self.expect(.r_paren);
        return self.program.addNode(.{ .kind = .group, .a = expression });
    }

    fn parseArrowParameterList(self: *Parser, async_function: bool) Error!u16 {
        const previous_allow_yield = self.allow_yield;
        const previous_allow_await = self.allow_await;
        const previous_await_reserved = self.await_reserved;
        self.allow_yield = false;
        self.allow_await = false;
        self.await_reserved = async_function;
        defer {
            self.allow_yield = previous_allow_yield;
            self.allow_await = previous_allow_await;
            self.await_reserved = previous_await_reserved;
        }
        return self.parseParameterList();
    }

    fn parenthesizedArrowAhead(self: *const Parser) bool {
        var cursor = self.current;
        var nested_parentheses: usize = 0;
        while (cursor < self.program.token_count) : (cursor += 1) {
            switch (self.program.workspace.tokens[cursor].kind) {
                .l_paren => nested_parentheses += 1,
                .r_paren => {
                    if (nested_parentheses == 0) {
                        const arrow_index = @min(cursor + 1, self.program.token_count - 1);
                        return self.peekKindAt(arrow_index) == .fat_arrow and
                            self.program.workspace.tokens[cursor].line == self.program.workspace.tokens[arrow_index].line;
                    }
                    nested_parentheses -= 1;
                },
                .eof => return false,
                else => {},
            }
        }
        return false;
    }

    fn asyncParenthesizedArrowAhead(self: *const Parser) bool {
        if (!self.at(.l_paren)) return false;
        var cursor = self.current + 1;
        var nested_parentheses: usize = 0;
        while (cursor < self.program.token_count) : (cursor += 1) {
            switch (self.program.workspace.tokens[cursor].kind) {
                .l_paren => nested_parentheses += 1,
                .r_paren => {
                    if (nested_parentheses == 0) {
                        const arrow_index = @min(cursor + 1, self.program.token_count - 1);
                        return self.peekKindAt(arrow_index) == .fat_arrow and self.tokensShareLine(cursor, arrow_index);
                    }
                    nested_parentheses -= 1;
                },
                .eof => return false,
                else => {},
            }
        }
        return false;
    }

    fn peekKindAt(self: *const Parser, index: usize) TokenKind {
        return self.program.workspace.tokens[@min(index, self.program.token_count - 1)].kind;
    }

    fn tokensShareLine(self: *const Parser, left: usize, right: usize) bool {
        const maximum = self.program.token_count - 1;
        return self.program.workspace.tokens[@min(left, maximum)].line == self.program.workspace.tokens[@min(right, maximum)].line;
    }

    fn functionSource(self: *const Parser, source_start: u32) StringRef {
        if (self.current == 0) return .{};
        const final = self.program.workspace.tokens[self.current - 1];
        var source_end: u32 = if (final.text.offset & identifier_ref_bit != 0)
            @intCast(identifierSourceEnd(self.program.source[0..self.program.source_len], final.source_offset) catch final.source_offset)
        else
            final.text.offset + final.text.len;
        if (final.kind == .string or final.kind == .template or final.kind == .template_tail) source_end += 1;
        if (source_end < source_start) return .{};
        return .{ .offset = source_start, .len = source_end - source_start };
    }

    fn parseArrowBody(self: *Parser, async_function: bool) Error!struct { body: u16, flags: u16 } {
        const strict_range_start = self.program.node_count;
        const previous_allow_yield = self.allow_yield;
        const previous_yield_reserved = self.yield_reserved;
        const previous_allow_await = self.allow_await;
        const previous_await_reserved = self.await_reserved;
        const previous_return_allowed = self.return_allowed;
        const previous_breakable_depth = self.breakable_depth;
        const previous_iteration_depth = self.iteration_depth;
        const previous_active_label_count = self.active_label_count;
        self.allow_yield = false;
        self.yield_reserved = false;
        self.allow_await = async_function;
        self.await_reserved = async_function;
        self.return_allowed = true;
        self.breakable_depth = 0;
        self.iteration_depth = 0;
        self.active_label_count = 0;
        defer {
            self.allow_yield = previous_allow_yield;
            self.yield_reserved = previous_yield_reserved;
            self.allow_await = previous_allow_await;
            self.await_reserved = previous_await_reserved;
            self.return_allowed = previous_return_allowed;
            self.breakable_depth = previous_breakable_depth;
            self.iteration_depth = previous_iteration_depth;
            self.active_label_count = previous_active_label_count;
        }
        if (self.at(.l_brace)) {
            const body = try self.parseFunctionBody();
            // Arrow parameters are validated before this point; their bound
            // names must still remain disjoint from body lexical declarations.
            const strict = self.blockHasUseStrict(body);
            if (strict) try self.validateStrictRange(strict_range_start, self.program.node_count);
            return .{ .body = body, .flags = if (strict) flag_strict else 0 };
        }
        return .{ .body = try self.parseAssignment(), .flags = flag_prefix };
    }

    fn parseArrayLiteral(self: *Parser) Error!u16 {
        var first: u16 = none;
        var last: u16 = none;
        while (!self.at(.r_bracket)) {
            if (self.match(.comma)) {
                appendNode(self.program, &first, &last, try self.program.addNode(.{ .kind = .empty, .flags = flag_elision }));
                continue;
            }
            const spread = self.match(.ellipsis);
            const element = if (spread)
                try self.program.addNode(.{
                    .kind = .spread_element,
                    .a = try self.parseAssignment(),
                })
            else
                try self.parseAssignment();
            appendNode(self.program, &first, &last, element);
            if (!self.match(.comma)) break;
            if (spread and self.at(.r_bracket)) self.program.nodes[element].flags |= flag_elision;
        }
        try self.expect(.r_bracket);
        return self.program.addNode(.{ .kind = .array_literal, .a = first });
    }

    fn parseObjectLiteral(self: *Parser) Error!u16 {
        var first: u16 = none;
        var last: u16 = none;
        var has_proto_setter = false;
        while (!self.at(.r_brace)) {
            if (self.match(.ellipsis)) {
                const property = try self.program.addNode(.{
                    .kind = .property,
                    .a = try self.parseAssignment(),
                    .flags = flag_spread,
                });
                appendNode(self.program, &first, &last, property);
                if (!self.match(.comma)) break;
                if (self.at(.r_brace)) {
                    self.program.nodes[property].flags |= flag_elision;
                    break;
                }
                continue;
            }
            const source_start = self.peek().source_offset;
            var property_flags: u16 = 0;
            var async_method = false;
            var generator_method = self.match(.star);
            if (!generator_method and self.at(.kw_async) and self.peekKind(1) == .star and self.tokensShareLine(self.current, self.current + 1)) {
                _ = self.advance();
                _ = self.advance();
                async_method = true;
                generator_method = true;
            } else if (!generator_method and self.objectAccessorAhead()) {
                const prefix = self.advance();
                property_flags |= if (equals(self.program.text(prefix.text), "get")) flag_getter else flag_setter;
            } else if (!generator_method and self.objectAsyncMethodAhead()) {
                _ = self.advance();
                async_method = true;
            }
            const key = try self.parseObjectPropertyName();
            var value: u16 = none;
            var pattern_default: u16 = none;
            if (property_flags & (flag_getter | flag_setter) != 0) {
                const parts = try self.parseFunctionPartsWithoutSuper(false, false, false);
                if (property_flags & flag_getter != 0) {
                    if (parts.parameters != none) return error.SyntaxError;
                } else {
                    if (parts.parameters == none or self.program.nodes[parts.parameters].next != none or
                        self.program.nodes[parts.parameters].a != none or self.program.nodes[parts.parameters].flags & flag_rest != 0) return error.SyntaxError;
                }
                value = try self.program.addNode(.{
                    .kind = .function_expression,
                    .a = parts.parameters,
                    .b = parts.body,
                    .text = key.text,
                    .source = self.functionSource(source_start),
                    .flags = if (parts.strict) flag_strict else 0,
                });
                self.program.function_count += 1;
            } else if (self.at(.l_paren)) {
                const parts = try self.parseFunctionPartsWithoutSuper(false, generator_method, async_method);
                value = try self.program.addNode(.{
                    .kind = .function_expression,
                    .a = parts.parameters,
                    .b = parts.body,
                    .text = key.text,
                    .source = self.functionSource(source_start),
                    .flags = (if (async_method) flag_async else 0) | (if (generator_method) flag_generator else 0) | flag_method |
                        (if (parts.strict) flag_strict else 0),
                });
                self.program.function_count += 1;
            } else if (async_method or generator_method) {
                return error.SyntaxError;
            } else if (self.match(.colon)) {
                value = try self.parseAssignment();
                if (key.expression == none and ((key.kind == .identifier and equals(self.program.text(key.text), "__proto__")) or
                    (key.kind == .string and decodedStringEqualsAscii(self.program.text(key.text), "__proto__"))))
                {
                    if (has_proto_setter) return error.SyntaxError;
                    has_proto_setter = true;
                    property_flags |= flag_proto_setter;
                }
            } else if (key.kind == .identifier or key.kind == .kw_async) {
                if (self.yield_reserved and equals(self.program.text(key.text), "yield")) return error.SyntaxError;
                if (self.await_reserved and equals(self.program.text(key.text), "await")) return error.SyntaxError;
                value = try self.program.addNode(.{ .kind = .identifier, .text = key.text });
                if (self.match(.equal)) {
                    pattern_default = try self.parseAssignment();
                    property_flags |= flag_elision;
                }
            } else {
                return error.SyntaxError;
            }
            appendNode(self.program, &first, &last, try self.program.addNode(.{
                .kind = .property,
                .a = value,
                .b = key.expression,
                .c = pattern_default,
                .text = key.text,
                .number = key.number,
                .flags = property_flags | key.flags,
            }));
            if (!self.match(.comma)) break;
        }
        try self.expect(.r_brace);
        return self.program.addNode(.{ .kind = .object_literal, .a = first });
    }

    fn parseObjectPropertyName(self: *Parser) Error!ObjectPropertyName {
        if (self.match(.l_bracket)) {
            const expression = try self.parseExpression();
            try self.expect(.r_bracket);
            return .{ .kind = .l_bracket, .expression = expression, .flags = flag_computed };
        }
        const token = self.advance();
        if (isPropertyNameToken(token.kind)) return .{ .kind = token.kind, .text = token.text };
        if (token.kind == .string) return .{ .kind = token.kind, .text = token.text, .flags = flag_key_string };
        if (token.kind == .number) return .{ .kind = token.kind, .text = token.text, .number = token.number, .flags = flag_key_number };
        return error.SyntaxError;
    }

    fn objectAccessorAhead(self: *const Parser) bool {
        if (!self.at(.identifier)) return false;
        const name = self.program.text(self.peek().text);
        if (!equals(name, "get") and !equals(name, "set")) return false;
        return self.objectPropertyFollowedByParenAt(self.current + 1);
    }

    fn objectAsyncMethodAhead(self: *const Parser) bool {
        if (!self.at(.kw_async) or !self.tokensShareLine(self.current, self.current + 1)) return false;
        return self.objectPropertyFollowedByParenAt(self.current + 1);
    }

    fn objectPropertyFollowedByParenAt(self: *const Parser, start: usize) bool {
        if (start >= self.program.token_count) return false;
        const token = self.program.workspace.tokens[start];
        if (isPropertyNameToken(token.kind) or token.kind == .private_identifier or token.kind == .string or token.kind == .number)
            return self.peekKindAt(start + 1) == .l_paren;
        if (token.kind != .l_bracket) return false;
        var depth: usize = 1;
        var cursor = start + 1;
        while (cursor < self.program.token_count) : (cursor += 1) {
            switch (self.peekKindAt(cursor)) {
                .l_bracket => depth += 1,
                .r_bracket => {
                    depth -= 1;
                    if (depth == 0) return self.peekKindAt(cursor + 1) == .l_paren;
                },
                .eof => return false,
                else => {},
            }
        }
        return false;
    }

    fn peek(self: *const Parser) Token {
        return self.program.workspace.tokens[@min(self.current, self.program.token_count - 1)];
    }

    fn peekKind(self: *const Parser, offset: usize) TokenKind {
        return self.program.workspace.tokens[@min(self.current + offset, self.program.token_count - 1)].kind;
    }

    fn at(self: *const Parser, kind: TokenKind) bool {
        return self.peek().kind == kind;
    }

    fn advance(self: *Parser) Token {
        const token = self.peek();
        if (self.current + 1 < self.program.token_count) self.current += 1;
        self.furthest = @max(self.furthest, self.current);
        return token;
    }

    fn match(self: *Parser, kind: TokenKind) bool {
        if (!self.at(kind)) return false;
        _ = self.advance();
        return true;
    }

    fn expect(self: *Parser, kind: TokenKind) Error!void {
        if (!self.match(kind)) return error.UnexpectedToken;
    }

    fn expectIdentifier(self: *Parser) Error!Token {
        if (self.at(.escaped_reserved)) return error.SyntaxError;
        if (!self.at(.identifier)) return error.UnexpectedToken;
        return self.advance();
    }

    fn expectPropertyName(self: *Parser) Error!Token {
        if (!isPropertyNameToken(self.peek().kind)) return error.UnexpectedToken;
        return self.advance();
    }

    fn lineTerminatorBeforeCurrent(self: *const Parser) bool {
        if (self.current == 0) return false;
        return self.program.workspace.tokens[self.current - 1].end_line < self.peek().line;
    }

    fn consumeSemicolon(self: *Parser) Error!void {
        if (self.match(.semicolon)) return;
        if (self.at(.r_brace) or self.at(.eof) or self.lineTerminatorBeforeCurrent()) return;
        return error.SyntaxError;
    }

    fn isUnescapedIdentifier(self: *const Parser, token: Token, expected: []const u8) bool {
        return token.flags & 1 == 0 and self.identifierEquals(token, expected);
    }

    fn identifierEquals(self: *const Parser, token: Token, expected: []const u8) bool {
        return token.kind == .identifier and equals(self.program.text(token.text), expected);
    }

    fn atUnescapedIdentifier(self: *const Parser, expected: []const u8) bool {
        return self.isUnescapedIdentifier(self.peek(), expected);
    }
};

const BinaryInfo = struct {
    operation: BinaryOp,
    precedence: u8,
};

fn binaryInfo(kind: TokenKind) ?BinaryInfo {
    return switch (kind) {
        .nullish => .{ .operation = .nullish, .precedence = 1 },
        .or_or => .{ .operation = .logical_or, .precedence = 2 },
        .and_and => .{ .operation = .logical_and, .precedence = 3 },
        .pipe => .{ .operation = .bitwise_or, .precedence = 4 },
        .caret => .{ .operation = .bitwise_xor, .precedence = 5 },
        .ampersand => .{ .operation = .bitwise_and, .precedence = 6 },
        .equal_equal => .{ .operation = .equal, .precedence = 7 },
        .equal_equal_equal => .{ .operation = .strict_equal, .precedence = 7 },
        .bang_equal => .{ .operation = .not_equal, .precedence = 7 },
        .bang_equal_equal => .{ .operation = .strict_not_equal, .precedence = 7 },
        .less => .{ .operation = .less, .precedence = 8 },
        .less_equal => .{ .operation = .less_equal, .precedence = 8 },
        .greater => .{ .operation = .greater, .precedence = 8 },
        .greater_equal => .{ .operation = .greater_equal, .precedence = 8 },
        .kw_in => .{ .operation = .in, .precedence = 8 },
        .kw_instanceof => .{ .operation = .instance_of, .precedence = 8 },
        .shift_left => .{ .operation = .shift_left, .precedence = 9 },
        .shift_right => .{ .operation = .shift_right, .precedence = 9 },
        .shift_unsigned => .{ .operation = .shift_unsigned, .precedence = 9 },
        .plus => .{ .operation = .add, .precedence = 10 },
        .minus => .{ .operation = .subtract, .precedence = 10 },
        .star => .{ .operation = .multiply, .precedence = 11 },
        .slash => .{ .operation = .divide, .precedence = 11 },
        .percent => .{ .operation = .remainder, .precedence = 11 },
        .star_star => .{ .operation = .exponentiate, .precedence = 12 },
        else => null,
    };
}

fn isLogicalAssignment(operation: AssignmentOp) bool {
    return operation == .logical_and or operation == .logical_or or operation == .nullish;
}

fn nodeBinaryOperation(program: *const Program, index: u16) ?BinaryOp {
    if (index == none or index >= program.node_count) return null;
    const node = program.nodes[index];
    if (node.kind != .binary) return null;
    return @enumFromInt(node.flags);
}

