comptime {
    if (target_builtin.cpu.arch != .x86_64) @compileError("R4JS resumable fibers require the R4OS x86_64 target");
    if (@offsetOf(FiberContext, "rsp") != 0 or @offsetOf(FiberContext, "xmm") != 96 or @sizeOf(FiberContext) != 256)
        @compileError("R4JS fiber context layout changed");
}

