fn initializeFiberContext(context: *FiberContext, stack: []u8, entry: FiberEntry, argument0: *anyopaque, argument1: usize) void {
    context.* = .{};
    const stack_end = @intFromPtr(stack.ptr + stack.len) & ~@as(usize, 15);
    // The synthetic ret must reproduce the ABI stack alignment at a normal
    // function entry. Windows additionally needs a return slot and 32 bytes
    // of caller-provided shadow space above the entry stack pointer.
    const stack_pointer = if (target_builtin.os.tag == .windows) stack_end - 48 else stack_end - 16;
    const return_slot: *usize = @ptrFromInt(stack_pointer);
    return_slot.* = @intFromPtr(entry);
    context.rsp = stack_pointer;
    if (target_builtin.os.tag == .windows) {
        context.argument0 = @intFromPtr(argument0);
        context.argument1 = argument1;
    } else {
        context.rdi = @intFromPtr(argument0);
        context.rsi = argument1;
    }
}

fn fiberSwitch(from: *FiberContext, to: *FiberContext) void {
    const callable: *const fn (*FiberContext, *FiberContext) callconv(.c) void = @ptrCast(&fiberSwitchNaked);
    callable(from, to);
}

fn fiberSwitchNaked() callconv(.naked) void {
    @setRuntimeSafety(false);
    if (target_builtin.os.tag == .windows) {
        asm volatile (
            \\ movq %%rsp, 0(%%rcx)
            \\ movq %%rbx, 8(%%rcx)
            \\ movq %%rbp, 16(%%rcx)
            \\ movq %%rdi, 24(%%rcx)
            \\ movq %%rsi, 32(%%rcx)
            \\ movq %%r12, 40(%%rcx)
            \\ movq %%r13, 48(%%rcx)
            \\ movq %%r14, 56(%%rcx)
            \\ movq %%r15, 64(%%rcx)
            \\ stmxcsr 88(%%rcx)
            \\ fnstcw 92(%%rcx)
            \\ movdqu %%xmm6, 96(%%rcx)
            \\ movdqu %%xmm7, 112(%%rcx)
            \\ movdqu %%xmm8, 128(%%rcx)
            \\ movdqu %%xmm9, 144(%%rcx)
            \\ movdqu %%xmm10, 160(%%rcx)
            \\ movdqu %%xmm11, 176(%%rcx)
            \\ movdqu %%xmm12, 192(%%rcx)
            \\ movdqu %%xmm13, 208(%%rcx)
            \\ movdqu %%xmm14, 224(%%rcx)
            \\ movdqu %%xmm15, 240(%%rcx)
            \\ movq %%rdx, %%rax
            \\ movq 0(%%rax), %%rsp
            \\ movq 8(%%rax), %%rbx
            \\ movq 16(%%rax), %%rbp
            \\ movq 40(%%rax), %%r12
            \\ movq 48(%%rax), %%r13
            \\ movq 56(%%rax), %%r14
            \\ movq 64(%%rax), %%r15
            \\ ldmxcsr 88(%%rax)
            \\ fldcw 92(%%rax)
            \\ movdqu 96(%%rax), %%xmm6
            \\ movdqu 112(%%rax), %%xmm7
            \\ movdqu 128(%%rax), %%xmm8
            \\ movdqu 144(%%rax), %%xmm9
            \\ movdqu 160(%%rax), %%xmm10
            \\ movdqu 176(%%rax), %%xmm11
            \\ movdqu 192(%%rax), %%xmm12
            \\ movdqu 208(%%rax), %%xmm13
            \\ movdqu 224(%%rax), %%xmm14
            \\ movdqu 240(%%rax), %%xmm15
            \\ movq 72(%%rax), %%rcx
            \\ movq 80(%%rax), %%rdx
            \\ movq 24(%%rax), %%rdi
            \\ movq 32(%%rax), %%rsi
            \\ retq
        );
    } else {
        asm volatile (
            \\ movq %%rsp, 0(%%rdi)
            \\ movq %%rbx, 8(%%rdi)
            \\ movq %%rbp, 16(%%rdi)
            \\ movq %%rdi, 24(%%rdi)
            \\ movq %%rsi, 32(%%rdi)
            \\ movq %%r12, 40(%%rdi)
            \\ movq %%r13, 48(%%rdi)
            \\ movq %%r14, 56(%%rdi)
            \\ movq %%r15, 64(%%rdi)
            \\ stmxcsr 88(%%rdi)
            \\ fnstcw 92(%%rdi)
            \\ movq %%rsi, %%rax
            \\ movq 0(%%rax), %%rsp
            \\ movq 8(%%rax), %%rbx
            \\ movq 16(%%rax), %%rbp
            \\ movq 40(%%rax), %%r12
            \\ movq 48(%%rax), %%r13
            \\ movq 56(%%rax), %%r14
            \\ movq 64(%%rax), %%r15
            \\ ldmxcsr 88(%%rax)
            \\ fldcw 92(%%rax)
            \\ movq 24(%%rax), %%rdi
            \\ movq 32(%%rax), %%rsi
            \\ retq
        );
    }
}

fn generatorFiberEntry(raw_runtime: *anyopaque, raw_state: usize) callconv(.c) noreturn {
    const runtime: *Runtime = @ptrCast(@alignCast(raw_runtime));
    const state: *GeneratorFiberState = @ptrFromInt(raw_state);
    runtime.runGeneratorFiber(state);
}

fn asyncFiberEntry(raw_runtime: *anyopaque, raw_state: usize) callconv(.c) noreturn {
    const runtime: *Runtime = @ptrCast(@alignCast(raw_runtime));
    const state: *AsyncFiberState = @ptrFromInt(raw_state);
    runtime.runAsyncFiber(state);
}

