    pub fn initialize(self: *Runtime, program_allocator: ProgramAllocator) void {
        self.program_allocator = program_allocator;
        self.string_capacity = 0;
        self.string_len = 0;
        self.accessor_memory = null;
        self.accessor_capacity = 0;
        for (&self.cells) |*cell| {
            cell.occupied = false;
            cell.generation = 0;
        }
        self.generator_state_head = null;
        self.active_generator_state = null;
        self.async_state_head = null;
        self.active_async_state = null;
        self.external_root_marker = .{};
        self.clock_source = .{};
        self.promise_rejection_tracker = .{};
        self.module_count = 0;
        for (&self.modules) |*module| module.program = null;
        self.dynamic_program_count = 0;
        self.dynamic_programs = [_]?*Program{null} ** max_dynamic_programs;
        self.active_host_construct = false;
        self.identifier_cache = [_]IdentifierCacheEntry{.{}} ** max_identifier_cache_entries;
        self.stop_check_countdown = 0;
    }

