    fn captureExecution(self: *Runtime, destination: *ExecutionSnapshot) void {
        destination.active_program = self.active_program;
        destination.active_env = self.active_env;
        destination.active_exports = self.active_exports;
        destination.active_module = self.active_module;
        destination.active_generator_state = self.active_generator_state;
        destination.active_async_state = self.active_async_state;
        destination.root_count = self.root_count;
        if (self.root_count > 0) @memcpy(destination.roots[0..self.root_count], self.roots[0..self.root_count]);
        destination.bytecode_value_count = self.bytecode_value_count;
        if (self.bytecode_value_count > 0)
            @memcpy(destination.bytecode_values[0..self.bytecode_value_count], self.bytecode_values[0..self.bytecode_value_count]);
        destination.bytecode_frame_count = self.bytecode_frame_count;
        if (self.bytecode_frame_count > 0)
            @memcpy(destination.bytecode_frames[0..self.bytecode_frame_count], self.bytecode_frames[0..self.bytecode_frame_count]);
        destination.call_depth = self.call_depth;
        if (self.call_depth > 0) @memcpy(destination.call_environments[0..self.call_depth], self.call_environments[0..self.call_depth]);
        destination.pending_exception = self.pending_exception;
        destination.pending_generator_return = self.pending_generator_return;
        destination.diagnostic_name = self.diagnostic_name;
        destination.diagnostic_name_len = self.diagnostic_name_len;
        destination.diagnostic_context = self.diagnostic_context;
        destination.diagnostic_context_len = self.diagnostic_context_len;
        destination.diagnostic_call_name = self.diagnostic_call_name;
        destination.diagnostic_call_name_len = self.diagnostic_call_name_len;
        destination.diagnostic_program = self.diagnostic_program;
        destination.diagnostic_node = self.diagnostic_node;
        destination.diagnostic_opcode = self.diagnostic_opcode;
        destination.diagnostic_value = self.diagnostic_value;
        destination.diagnostic_site = self.diagnostic_site;
        destination.diagnostic_limit_required = self.diagnostic_limit_required;
        destination.diagnostic_limit_available = self.diagnostic_limit_available;
        destination.diagnostic_phase = self.diagnostic_phase;
        destination.diagnostic_error_name = self.diagnostic_error_name;
        destination.diagnostic_error_name_len = self.diagnostic_error_name_len;
        destination.diagnostic_source_name = self.diagnostic_source_name;
        destination.diagnostic_source_name_len = self.diagnostic_source_name_len;
        destination.diagnostic_line = self.diagnostic_line;
        destination.diagnostic_column = self.diagnostic_column;
        destination.diagnostic_stack = self.diagnostic_stack;
        destination.diagnostic_stack_len = self.diagnostic_stack_len;
    }

