        self.root_count = source.root_count;
        if (source.root_count > 0) @memcpy(self.roots[0..source.root_count], source.roots[0..source.root_count]);
        self.bytecode_value_count = source.bytecode_value_count;
        if (source.bytecode_value_count > 0)
            @memcpy(self.bytecode_values[0..source.bytecode_value_count], source.bytecode_values[0..source.bytecode_value_count]);
        self.bytecode_frame_count = source.bytecode_frame_count;
        if (source.bytecode_frame_count > 0)
            @memcpy(self.bytecode_frames[0..source.bytecode_frame_count], source.bytecode_frames[0..source.bytecode_frame_count]);
        self.call_depth = source.call_depth;
        if (source.call_depth > 0) @memcpy(self.call_environments[0..source.call_depth], source.call_environments[0..source.call_depth]);
        self.pending_exception = source.pending_exception;
