    pub fn markExternal(self: *Runtime, value: Value) void {
        self.markValue(value);
    }

    pub fn evaluate(self: *Runtime, program: *const Program) Error!Value {
        self.clearSuccessfulDiagnostic();
        if (!program.bytecodeReady()) {
            self.captureDiagnostic(.compiler, error.BytecodeInvalid, program, none);
            return error.BytecodeInvalid;
        }
        const previous_program = self.active_program;
        defer self.active_program = previous_program;
        self.active_program = program;
        self.active_env = self.global_env;
        self.active_exports = none;
        self.active_module = none;
        self.stats.steps = 0;
        self.stats.bytecode_instructions = 0;
        self.stats.bytecode_frames_peak = 0;
        self.bytecode_value_count = 0;
        self.bytecode_frame_count = 0;
        const completion = try self.executeBytecodeSegment(program, program.root_segment, self.global_env);
        if (completion.kind == .thrown) return error.UncaughtException;
        self.clearSuccessfulDiagnostic();
        return completion.value;
    }

    pub fn evaluateSource(self: *Runtime, program: *Program, source: []const u8) Error!Value {
        _ = program.parseHostSource(source) catch |err| {
            program.setSourceName("<host>");
            self.captureProgramDiagnostic(program, err);
            return err;
        };
        program.setSourceName("<host>");
        return self.evaluate(program);
    }

    pub fn evaluateScriptSource(self: *Runtime, program: *Program, source: []const u8) Error!Value {
        return self.evaluateNamedScriptSource(program, "<script>", source);
    }

    pub fn evaluateNamedScriptSource(self: *Runtime, program: *Program, source_name: []const u8, source: []const u8) Error!Value {
        _ = program.parse(source) catch |err| {
            program.setSourceName(source_name);
            self.captureProgramDiagnostic(program, err);
            return err;
        };
        program.setSourceName(source_name);
        if (program.module_statement_count != 0) {
            self.captureDiagnostic(.parser, error.SyntaxError, program, program.root);
            return error.SyntaxError;
        }
        return self.evaluate(program);
    }

    pub fn global(self: *Runtime, name: []const u8) ?Value {
        return self.lookup(self.global_env, name);
    }

    pub fn activeProgram(self: *const Runtime) ?*const Program {
        return self.active_program;
    }

    pub fn executionSite(self: *const Runtime) ?ExecutionSite {
        const program = self.diagnostic_program orelse self.active_program orelse return null;
        const node_index = self.diagnostic_node;
        if (node_index == none or node_index >= program.node_count) return null;
        const offset = diagnosticNodeOffset(program, node_index);
        const position = sourcePosition(program, offset);
        return .{
            .node = node_index,
            .kind = program.nodes[node_index].kind,
            .op = self.diagnostic_opcode,
            .offset = offset,
            .line = position.line,
            .column = position.column,
        };
    }

    pub fn hostCallIsConstruct(self: *const Runtime) bool {
        return self.active_host_construct;
    }

    pub fn defineGlobal(self: *Runtime, name: []const u8, value: Value, constant: bool) Error!void {
        try self.defineBinding(self.global_env, name, value, constant);
    }

    pub fn registerModule(self: *Runtime, name: []const u8, source: []const u8) Error!void {
        if (name.len == 0 or name.len > max_module_specifier_bytes) return error.StringLimit;
        if (self.module_count >= self.modules.len) return error.ModuleLimit;
        if (self.findModule(name) != null) return error.SyntaxError;
        const index = self.module_count;
        const stored_name = try self.storeString(name);
        const program = self.program_allocator.create(self.program_allocator.context) orelse return error.ProgramAllocation;
        errdefer self.program_allocator.destroy(self.program_allocator.context, program);
        program.reset();
        _ = program.parse(source) catch |err| {
            program.setSourceName(name);
            self.captureProgramDiagnostic(program, err);
            return err;
        };
        program.setSourceName(name);
        var strict_parser = Parser{ .program = program };
        strict_parser.validateStrictRange(0, program.node_count) catch |err| {
            self.captureDiagnostic(.parser, err, program, program.root);
            return err;
        };
        program.strict_mode = true;
        program.compileBytecode() catch |err| {
            self.captureDiagnostic(.compiler, err, program, program.root);
            return err;
        };
        self.modules[index] = .{
            .occupied = true,
            .name = stored_name,
            .program = program,
            .state = .registered,
            .exports = none,
        };
        self.module_count += 1;
    }

    pub fn evaluateModule(self: *Runtime, name: []const u8) Error!Value {
        const module_index = self.findModule(name) orelse return error.ModuleNotFound;
        return self.evaluateResolvedModule(module_index);
    }

    pub fn moduleDependencies(self: *Runtime, name: []const u8, output: [][]const u8) Error!usize {
        const module_index = self.findModule(name) orelse return error.ModuleNotFound;
        const program = self.modules[module_index].program orelse return error.ModuleNotFound;
        var count: usize = 0;
        for (program.nodes[0..program.node_count]) |node| {
            const dependency = switch (node.kind) {
                .import_statement => node.text,
                .export_list => if (node.text.len > 0) node.text else continue,
                else => continue,
            };
            const decoded = try self.decodeSourceString(program, dependency);
            var duplicate = false;
            for (output[0..count]) |existing| {
                if (equals(existing, decoded)) {
                    duplicate = true;
                    break;
                }
            }
            if (duplicate) continue;
            if (count >= output.len) return error.ModuleLimit;
            output[count] = decoded;
            count += 1;
        }
        return count;
    }

    fn evaluateModuleFrom(self: *Runtime, referrer: u16, specifier: []const u8) Error!Value {
        const module_index = self.resolveModuleIndex(referrer, specifier) orelse return error.ModuleNotFound;
        return self.evaluateResolvedModule(module_index);
    }

    fn evaluateResolvedModule(self: *Runtime, module_index: usize) Error!Value {
        const result = try self.evaluateModuleIndex(module_index);
        self.validateModuleLinks() catch |err| {
            self.modules[module_index].state = .failed;
            self.modules[module_index].failure = err;
            return err;
        };
        return result;
    }

    fn dynamicImport(self: *Runtime, specifier: Value) Error!Value {
        const name = try self.toString(specifier);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .string = name });
        const promise = try self.createPromise();
        try self.pushRoot(promise);
        try self.enqueueJob(&self.microtasks, &self.microtask_head, &self.microtask_count, .{
            .kind = .dynamic_import,
            .argument = .{ .string = name },
            .promise = promise.cell,
            .generator = self.active_module,
        });
        return promise;
    }

    fn importMeta(self: *Runtime) Error!Value {
        if (self.active_module == none or self.active_module >= self.module_count) return error.SyntaxError;
        var module = &self.modules[self.active_module];
        if (module.meta != none) return .{ .cell = module.meta };
        const meta = try self.allocateCell(.object);
        module.meta = meta;
        const name = self.stringBytes(module.name);
        try self.setProperty(.{ .cell = meta }, "name", .{ .string = try self.storeString(name) });
        try self.setProperty(.{ .cell = meta }, "url", .{ .string = try self.storeString(name) });
        self.cells[meta].frozen = true;
        return .{ .cell = meta };
    }

    pub fn enqueueTask(self: *Runtime, callback: Value, argument: Value) Error!void {
        try self.enqueueJob(&self.tasks, &self.task_head, &self.task_count, .{ .callback = callback, .argument = argument });
    }

    pub fn enqueueMicrotask(self: *Runtime, callback: Value, argument: Value) Error!void {
        try self.enqueueJob(&self.microtasks, &self.microtask_head, &self.microtask_count, .{ .callback = callback, .argument = argument });
    }

    fn callableOrigin(self: *const Runtime, callable: Value) struct { program: ?*const Program, module: u16 } {
        var current = callable;
        var depth: usize = 0;
        origin: while (current == .cell and depth < max_call_depth) : (depth += 1) {
            const index = current.cell;
            if (index >= self.cells.len or !self.cells[index].occupied) break;
            const cell = &self.cells[index];
            if (cell.program_ref) |program| return .{ .program = program, .module = cell.module };
            switch (cell.kind) {
                .bound_function => current = cell.promise_value,
                .proxy => current = cell.receiver,
                else => break :origin,
            }
        }
        return .{ .program = null, .module = none };
    }

    fn enqueueJob(self: *Runtime, queue: *[max_jobs]Job, head: *usize, count: *usize, job: Job) Error!void {
        var bound = job;
        if (bound.program == null) {
            const origin = self.callableOrigin(bound.callback);
            bound.program = origin.program orelse self.active_program;
            bound.module = if (origin.program != null) origin.module else self.active_module;
        }
        try enqueue(queue, head, count, bound);
    }

    pub fn drainJobs(self: *Runtime, program: *const Program, maximum_jobs: usize) Error!usize {
        var executed: usize = 0;
        while (executed < maximum_jobs) {
            self.resetExecutionTurnStatistics();
            try self.checkpoint();
            while (self.microtask_count > 0 and executed < maximum_jobs) {
                const job = dequeue(&self.microtasks, &self.microtask_head, &self.microtask_count);
                self.resetExecutionTurnStatistics();
                try self.runJob(program, job);
                self.clearSuccessfulDiagnostic();
                self.stats.microtasks_run += 1;
                executed += 1;
            }
            if (executed >= maximum_jobs or self.task_count == 0) break;
            const job = dequeue(&self.tasks, &self.task_head, &self.task_count);
            self.resetExecutionTurnStatistics();
            try self.runJob(program, job);
            self.clearSuccessfulDiagnostic();
            self.stats.tasks_run += 1;
            executed += 1;
        }
        return executed;
    }

    fn resetExecutionTurnStatistics(self: *Runtime) void {
        self.stats.steps = 0;
        self.stats.bytecode_instructions = 0;
        self.stats.bytecode_frames_peak = 0;
    }

    fn clearSuccessfulDiagnostic(self: *Runtime) void {
        self.diagnostic_name_len = 0;
        self.diagnostic_context_len = 0;
        self.diagnostic_call_name_len = 0;
        self.diagnostic_value = .undefined;
        self.diagnostic_site = .none;
        self.diagnostic_phase = .none;
        self.diagnostic_error_name_len = 0;
        self.diagnostic_source_name_len = 0;
        self.diagnostic_line = 0;
        self.diagnostic_column = 0;
        self.diagnostic_stack_len = 0;
    }

    pub fn createPromise(self: *Runtime) Error!Value {
        return .{ .cell = try self.allocateCell(.promise) };
    }

    fn promiseResolvedValue(self: *Runtime, value: Value) Error!Value {
        if (self.isCellKind(value, .promise)) return value;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(value);
        const promise = try self.createPromise();
        try self.pushRoot(promise);
        try self.settlePromise(promise.cell, .fulfilled, value);
        return promise;
    }

    pub fn resolvePromise(self: *Runtime, promise: Value, value: Value) Error!void {
        const index = try self.expectCellKind(promise, .promise);
        try self.settlePromise(index, .fulfilled, value);
    }

    pub fn rejectPromise(self: *Runtime, promise: Value, value: Value) Error!void {
        const index = try self.expectCellKind(promise, .promise);
        try self.settlePromise(index, .rejected, value);
    }

    pub fn throwValue(self: *Runtime, value: Value) Error!Value {
        self.pending_exception = value;
        return error.ScriptThrown;
    }

    pub fn hostRootMark(self: *const Runtime) usize {
        return self.root_count;
    }

    pub fn hostRoot(self: *Runtime, value: Value) Error!void {
        try self.pushRoot(value);
    }

    pub fn restoreHostRoots(self: *Runtime, mark: usize) void {
        std.debug.assert(mark <= self.root_count);
        self.root_count = mark;
    }

    pub fn collectGarbage(self: *Runtime) void {
        for (&self.cells) |*cell| cell.marked = false;
        self.gc_symbol_marks = [_]u64{0} ** gc_symbol_mark_words;
        self.gc_mark_progress = 0;
        self.mark_queue_head = 0;
        self.mark_queue_count = 0;
        self.markCell(self.global_env);
        self.markCell(self.active_env);
        self.markCell(self.active_exports);
        self.markCell(self.iterator_prototype);
        self.markCell(self.iterator_helper_prototype);
        self.markCell(self.iterator_wrapper_prototype);
        self.markCell(self.array_iterator_prototype);
        self.markCell(self.promise_prototype);
        self.markCell(self.string_iterator_prototype);
        self.markCell(self.map_iterator_prototype);
        self.markCell(self.set_iterator_prototype);
        self.markCell(self.bigint_prototype);
        for (self.call_environments[0..self.call_depth]) |environment| self.markCell(environment);
        self.markValue(self.pending_exception);
        self.markValue(self.pending_generator_return);
        if (self.active_generator_state) |state| if (state.occupied) self.markCell(state.owner_cell);
        self.markValue(self.diagnostic_value);
        for (self.roots[0..self.root_count]) |value| self.markValue(value);
        for (self.bytecode_values[0..self.bytecode_value_count]) |value| self.markValue(value);
        for (self.bytecode_frames[0..self.bytecode_frame_count]) |frame| {
            self.markCell(frame.environment);
            self.markValue(frame.last_value);
        }
        for (self.template_objects[0..self.template_object_count]) |entry| self.markValue(entry.value);
        for (self.shared_natives) |value| self.markValue(value);
        if (self.external_root_marker.mark) |mark| mark(self, self.external_root_marker.context);
        for (0..self.module_count) |index| {
            self.markCell(self.modules[index].exports);
            self.markCell(self.modules[index].environment);
            self.markCell(self.modules[index].meta);
            self.markValue(self.modules[index].failure_value);
        }
        markJobs(self, self.tasks[0..], self.task_head, self.task_count);
        markJobs(self, self.microtasks[0..], self.microtask_head, self.microtask_count);

        self.drainMarkQueue();
        self.markWeakMapValues();
        self.clearDeadWeakEntries();

        var collected: usize = 0;
        for (&self.cells) |*cell| {
            if (cell.occupied and !cell.marked) {
                if (cell.kind == .generator) self.releaseGeneratorState(cell);
                if (cell.kind == .promise and cell.host_context != null) self.releaseAsyncState(cell);
                if (cell.host_tag == bigint_primitive_tag) self.releaseBigIntCell(cell);
                if (cell.host_tag == array_buffer_tag or cell.host_tag == shared_array_buffer_tag) self.releaseArrayBufferCell(cell);
                self.releaseBindingStorage(cell);
                self.releaseItemStorage(cell);
                self.releasePropertyStorage(cell);
                cell.occupied = false;
                collected += 1;
            }
        }
        for (self.accessorStorage()) |*accessor| {
            if (accessor.occupied and (accessor.owner >= self.cells.len or !self.cells[accessor.owner].occupied)) accessor.occupied = false;
        }
        self.stats.collections += 1;
        self.stats.collected_cells += collected;
        self.stats.live_cells = self.countLiveCells();
        self.scheduleNextCollection();
    }

    fn scheduleNextCollection(self: *Runtime) void {
        const occupied = @min(self.stats.live_cells, self.cells.len);
        const free_cells = self.cells.len - occupied;
        const interval = std.math.clamp(free_cells / 4, 512, 4096);
        self.next_gc_allocation = self.stats.allocations + interval;
    }

    fn drainMarkQueue(self: *Runtime) void {
        while (self.mark_queue_head < self.mark_queue_count) {
            const index = self.mark_queue[self.mark_queue_head];
            self.mark_queue_head += 1;
            const cell = &self.cells[index];
            self.markCell(cell.parent);
            self.markCell(cell.prototype);
            self.markCell(cell.private_storage);
            self.markValue(cell.receiver);
            self.markValue(cell.promise_value);
            for (self.propertyStorageConst(index)[0..cell.property_count]) |property| {
                self.markSymbolRef(property.key);
                self.markValue(property.value);
            }
            for (self.accessorStorage()) |*accessor| if (accessor.occupied and accessor.owner == index) {
                self.markSymbolRef(accessor.key);
                self.markValue(accessor.getter);
                self.markValue(accessor.setter);
            };
            switch (cell.kind) {
                .environment => {
                    for (self.bindingStorageConst(index)[0..cell.binding_count]) |binding| self.markValue(binding.value);
                    if (cell.object_environment) self.markValue(cell.receiver);
                },
                .array, .function, .bound_function => for (self.itemStorageConst(index)[0..cell.item_count]) |item| self.markValue(item),
                .object => if (cell.host_tag == map_tag or cell.host_tag == set_tag) {
                    for (self.itemStorageConst(index)[0..cell.item_count], 0..) |item, item_index|
                        if (self.arrayItemPresent(index, item_index)) self.markValue(item);
                } else if (cell.host_tag == promise_reaction_tag) {
                    for (self.itemStorageConst(index)[0..cell.item_count]) |item| self.markValue(item);
                } else if (isIteratorStorageTag(cell.host_tag)) {
                    for (self.itemStorageConst(index)[0..cell.item_count]) |item| self.markValue(item);
                },
                .promise => {
                    self.markAsyncState(cell.host_context);
                },
                .generator => self.markGeneratorState(cell.host_context),
                else => {},
            }
        }
    }

    fn markWeakMapValues(self: *Runtime) void {
        while (true) {
            const progress = self.gc_mark_progress;
            for (&self.cells, 0..) |*cell, index| {
                if (!cell.occupied or !cell.marked or cell.host_tag != weak_map_tag) continue;
                var slot: usize = 0;
                while (slot < cell.item_count) : (slot += 2) {
                    if (!self.arrayItemPresent(@intCast(index), slot)) continue;
                    if (self.weakKeyMarked(self.itemStorageConst(@intCast(index))[slot]))
                        self.markValue(self.itemStorageConst(@intCast(index))[slot + 1]);
                }
            }
            self.drainMarkQueue();
            if (self.gc_mark_progress == progress) break;
        }
    }

    fn clearDeadWeakEntries(self: *Runtime) void {
        for (&self.cells, 0..) |*cell, index| {
            if (!cell.occupied or !cell.marked or (cell.host_tag != weak_map_tag and cell.host_tag != weak_set_tag)) continue;
            const stride: usize = if (cell.host_tag == weak_map_tag) 2 else 1;
            var slot: usize = 0;
            while (slot < cell.item_count) : (slot += stride) {
                if (!self.arrayItemPresent(@intCast(index), slot)) continue;
                if (!self.weakKeyMarked(self.itemStorageConst(@intCast(index))[slot])) self.clearWeakCollectionEntry(@intCast(index), slot);
            }
        }
    }

    pub fn valueString(self: *const Runtime, value: Value) []const u8 {
        return switch (value) {
            .string => |ref| ref.bytes(self.strings[0..self.string_len]),
            else => "",
        };
    }

    pub fn valueNumber(self: *Runtime, value: Value) Error!f64 {
        return self.toNumber(value);
    }

    pub fn valueBigIntString(self: *Runtime, value: Value) Error![]const u8 {
        return self.stringBytes(try self.bigIntToStringRef(value, 10));
    }

    pub fn valueBoolean(self: *const Runtime, value: Value) bool {
        return self.truthy(value);
    }

    pub fn sameValue(self: *const Runtime, left: Value, right: Value) bool {
        return self.strictEqual(left, right);
    }

    pub fn valueCallable(self: *const Runtime, value: Value) bool {
        return self.isCallableValue(value);
    }

    pub fn diagnosticName(self: *const Runtime) []const u8 {
        return self.diagnostic_name[0..self.diagnostic_name_len];
    }

    pub fn diagnosticContext(self: *const Runtime) []const u8 {
        return self.diagnostic_context[0..self.diagnostic_context_len];
    }

    pub fn diagnosticPhase(self: *const Runtime) DiagnosticPhase {
        return self.diagnostic_phase;
    }

    pub fn diagnosticErrorName(self: *const Runtime) []const u8 {
        return self.diagnostic_error_name[0..self.diagnostic_error_name_len];
    }

    pub fn diagnosticSourceName(self: *const Runtime) []const u8 {
        return self.diagnostic_source_name[0..self.diagnostic_source_name_len];
    }

    pub fn diagnosticLine(self: *const Runtime) u32 {
        return self.diagnostic_line;
    }

    pub fn diagnosticColumn(self: *const Runtime) u32 {
        return self.diagnostic_column;
    }

    pub fn diagnosticStack(self: *const Runtime) []const u8 {
        return self.diagnostic_stack[0..self.diagnostic_stack_len];
    }

    pub fn diagnosticLimitRequired(self: *const Runtime) usize {
        return self.diagnostic_limit_required;
    }

    pub fn diagnosticLimitAvailable(self: *const Runtime) usize {
        return self.diagnostic_limit_available;
    }

    pub fn makeString(self: *Runtime, value: []const u8) Error!Value {
        return .{ .string = try self.storeString(value) };
    }

    pub fn coerceString(self: *Runtime, value: Value) Error!Value {
        return .{ .string = try self.toString(value) };
    }

    pub fn coerceUSVString(self: *Runtime, value: Value) Error!Value {
        return self.nativeStringToWellFormed(value);
    }

    pub fn createObject(self: *Runtime) Error!Value {
        return .{ .cell = try self.allocateCell(.object) };
    }

    pub fn createArray(self: *Runtime, values: []const Value) Error!Value {
        return self.arrayFromValues(values);
    }

    pub fn createUint8Array(self: *Runtime, bytes: []const u8) Error!Value {
        const value = try self.createTypedArrayLength(.uint8, bytes.len);
        const range = try self.typedArrayRange(value.cell);
        @memcpy(arrayBufferBytes(range.storage)[range.offset .. range.offset + bytes.len], bytes);
        return value;
    }

    pub fn createArrayBufferCopy(self: *Runtime, bytes: []const u8) Error!Value {
        const value = try self.createArrayBuffer(bytes.len, bytes.len, false);
        const storage = try self.arrayBufferStorage(value);
        @memcpy(arrayBufferBytes(storage)[0..bytes.len], bytes);
        return value;
    }

    pub fn copyBufferSource(self: *Runtime, value: Value, destination: []u8) Error![]const u8 {
        var source: []const u8 = undefined;
        if (self.isBufferObject(value)) {
            const storage = try self.bufferStorage(value);
            source = arrayBufferBytes(storage)[0..storage.byte_length];
        } else if (self.isDataView(value)) {
            const range = try self.dataViewRange(value.cell);
            source = arrayBufferBytes(range.storage)[range.offset .. range.offset + range.length];
        } else if (self.isTypedArray(value)) {
            const range = try self.typedArrayRange(value.cell);
            const byte_length = range.length * range.element.byteSize();
            source = arrayBufferBytes(range.storage)[range.offset .. range.offset + byte_length];
        } else {
            return error.TypeError;
        }
        if (source.len > destination.len) return error.RangeError;
        @memcpy(destination[0..source.len], source);
        return destination[0..source.len];
    }

    pub fn uint8ArrayBytes(self: *Runtime, value: Value) Error![]u8 {
        if (self.typedArrayElement(value) != .uint8) return error.TypeError;
        const range = try self.typedArrayRange(value.cell);
        if (range.storage.immutable) return error.TypeError;
        return arrayBufferBytes(range.storage)[range.offset .. range.offset + range.length];
    }

    pub fn writableIntegerTypedArrayBytes(self: *Runtime, value: Value) Error![]u8 {
        const element = self.typedArrayElement(value) orelse return error.TypeError;
        switch (element) {
            .int8, .uint8, .uint8_clamped, .int16, .uint16, .int32, .uint32, .bigint64, .biguint64 => {},
            .float16, .float32, .float64 => return error.TypeError,
        }
        const range = try self.typedArrayRange(value.cell);
        if (range.storage.immutable) return error.TypeError;
        const byte_length = range.length * element.byteSize();
        return arrayBufferBytes(range.storage)[range.offset .. range.offset + byte_length];
    }

    pub fn createHostFunction(self: *Runtime, tag: u16, context: ?*anyopaque, callback: HostFunction) Error!Value {
        const index = try self.allocateCell(.host_function);
        self.cells[index].host_function = callback;
        self.cells[index].host_context = context;
        self.cells[index].host_tag = tag;
        self.cells[index].program_ref = self.active_program;
        self.cells[index].module = self.active_module;
        return .{ .cell = index };
    }

    pub fn createHostConstructor(self: *Runtime, tag: u16, context: ?*anyopaque, callback: HostFunction) Error!Value {
        const value = try self.createHostFunction(tag, context, callback);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(value);
        self.cells[value.cell].host_constructible = true;
        const prototype = try self.createObject();
        try self.pushRoot(prototype);
        try self.defineOwnDataProperty(prototype, "constructor", value);
        try self.makeOwnPropertyNonEnumerable(prototype, "constructor");
        try self.defineOwnDataProperty(value, "prototype", prototype);
        try self.makeOwnPropertyNonEnumerable(value, "prototype");
        return value;
    }

    pub fn setHostPropertyHooks(
        self: *Runtime,
        object: Value,
        tag: u16,
        context: ?*anyopaque,
        getter: ?HostPropertyGet,
        setter: ?HostPropertySet,
    ) Error!void {
        const index = try self.expectObject(object);
        self.cells[index].host_tag = tag;
        self.cells[index].host_context = context;
        self.cells[index].host_property_get = getter;
        self.cells[index].host_property_set = setter;
    }

    pub fn setHostState(self: *Runtime, object: Value, expected_tag: u16, first: Value, second: Value) Error!void {
        const index = try self.expectObject(object);
        if (self.cells[index].host_tag != expected_tag) return error.TypeError;
        self.cells[index].receiver = first;
        self.cells[index].promise_value = second;
    }

    pub fn hostState(self: *Runtime, object: Value, expected_tag: u16) Error![2]Value {
        const index = try self.expectObject(object);
        if (self.cells[index].host_tag != expected_tag) return error.TypeError;
        return .{ self.cells[index].receiver, self.cells[index].promise_value };
    }

    pub fn hostTag(self: *Runtime, object: Value) Error!u16 {
        return self.cells[try self.expectObject(object)].host_tag;
    }

    pub fn setPrototype(self: *Runtime, object: Value, prototype: Value) Error!void {
        if (!try self.setPrototypeInternal(object, prototype)) return error.TypeError;
    }

    pub fn setFunctionMetadata(self: *Runtime, function: Value, name: []const u8, length: usize) Error!void {
        if (!self.isCallableValue(function)) return error.TypeError;
        try self.defineFunctionMetadata(function, "name", .{ .string = try self.storeString(name) });
        try self.defineFunctionMetadata(function, "length", .{ .number = @floatFromInt(length) });
    }

    pub fn installHostMethod(self: *Runtime, object: Value, name: []const u8, function: Value, length: usize) Error!void {
        try self.setProperty(object, name, function);
        try self.makeOwnPropertyNonEnumerable(object, name);
        try self.setFunctionMetadata(function, name, length);
    }

    pub fn installHostAccessor(self: *Runtime, object: Value, name: []const u8, getter: Value, setter: ?Value) Error!void {
        try self.defineOwnAccessor(object, name, getter, true);
        try self.setFunctionMetadata(getter, try self.prefixedFunctionName("get ", name), 0);
        if (setter) |function| {
            try self.defineOwnAccessor(object, name, function, false);
            try self.setFunctionMetadata(function, try self.prefixedFunctionName("set ", name), 1);
        }
        try self.makeOwnPropertyNonEnumerable(object, name);
    }

    fn prefixedFunctionName(self: *Runtime, prefix: []const u8, name: []const u8) Error![]const u8 {
        var buffer: [96]u8 = undefined;
        const text = std.fmt.bufPrint(buffer[0..], "{s}{s}", .{ prefix, name }) catch return error.StringLimit;
        return self.stringBytes(try self.storeString(text));
    }

    pub fn set(self: *Runtime, object: Value, name: []const u8, value: Value) Error!void {
        try self.setProperty(object, name, value);
    }

    pub fn setKey(self: *Runtime, object: Value, key: Value, value: Value) Error!void {
        const property_key = try self.toPropertyKey(key);
        try self.setProperty(object, self.stringBytes(property_key), value);
    }

    pub fn get(self: *Runtime, object: Value, name: []const u8) Error!Value {
        return self.getProperty(object, name);
    }

    pub fn getKey(self: *Runtime, object: Value, key: Value) Error!Value {
        const property_key = try self.toPropertyKey(key);
        return self.getProperty(object, self.stringBytes(property_key));
    }

    pub fn callValue(self: *Runtime, program: *const Program, callable: Value, receiver: Value, arguments: []const Value) Error!Value {
        return self.call(program, callable, receiver, arguments, false);
    }

    pub fn constructValue(self: *Runtime, program: *const Program, constructor: Value, arguments: []const Value) Error!Value {
        return self.call(program, constructor, .undefined, arguments, true);
    }

    fn bytecodePush(self: *Runtime, value: Value) Error!void {
        if (self.bytecode_value_count >= self.bytecode_values.len) return error.BytecodeStack;
        self.bytecode_values[self.bytecode_value_count] = value;
        self.bytecode_value_count += 1;
    }

    fn bytecodePop(self: *Runtime) Error!Value {
        if (self.bytecode_value_count == 0) return error.BytecodeStack;
        self.bytecode_value_count -= 1;
        return self.bytecode_values[self.bytecode_value_count];
    }

    fn bytecodeValueFromSegment(self: *Runtime, program: *const Program, segment: u16, environment: u16) Error!Value {
        const completion = try self.executeBytecodeSegment(program, segment, environment);
        if (completion.kind == .thrown) {
            self.pending_exception = completion.value;
            return error.ScriptThrown;
        }
        if (completion.kind != .normal) return error.BytecodeInvalid;
        return completion.value;
    }

    fn bytecodeValueFromNode(self: *Runtime, program: *const Program, node: u16, environment: u16) Error!Value {
        if (node == none or node >= program.node_count) return error.BytecodeInvalid;
        const segment = program.workspace.compiled.node_segments[node];
        if (segment == none) return error.BytecodeInvalid;
        return self.bytecodeValueFromSegment(program, segment, environment);
    }

    fn executeBytecodeNode(self: *Runtime, program: *const Program, node: u16, environment: u16) Error!Completion {
        if (node == none) return .{};
        if (node >= program.node_count) return error.BytecodeInvalid;
        if (program.nodes[node].kind == .block and !blockNeedsEnvironment(program, node)) {
            var current = program.nodes[node].a;
            var completion = Completion{};
            while (current != none) : (current = program.nodes[current].next) {
                completion = try self.executeBytecodeNode(program, current, environment);
                if (completion.kind != .normal) return completion;
            }
            return completion;
        }
        const segment = program.workspace.compiled.node_segments[node];
        if (segment == none) return error.BytecodeInvalid;
        return self.executeBytecodeSegment(program, segment, environment);
    }

    fn executeBytecodeSegment(self: *Runtime, program: *const Program, segment_index: u16, environment: u16) Error!Completion {
        return self.executeBytecodeSegmentInner(program, segment_index, environment) catch |err| {
            if (err == error.ScriptThrown) return .{ .kind = .thrown, .value = self.pending_exception };
            return err;
        };
    }

    fn executeBytecodeSegmentInner(self: *Runtime, program: *const Program, segment_index: u16, parent_environment: u16) Error!Completion {
        if (!program.bytecode_valid or segment_index == none or segment_index >= program.bytecode_segment_count)
            return error.BytecodeInvalid;
        if (self.bytecode_frame_count >= self.bytecode_frames.len) return error.BytecodeFrameLimit;
        const segment = program.bytecodeSegment(segment_index);
        const start: usize = segment.start;
        const end: usize = segment.end;
        if (start > end or end > program.bytecode_count) return error.BytecodeInvalid;
        const stack_base = self.bytecode_value_count;
        if (stack_base > std.math.maxInt(u16)) return error.BytecodeStack;
        var environment = parent_environment;
        if (segment.kind == .block and blockNeedsEnvironment(program, segment.node)) {
            environment = try self.allocateCell(.environment);
            self.cells[environment].parent = parent_environment;
        }
        const frame_index = self.bytecode_frame_count;
        self.bytecode_frames[frame_index] = .{
            .program = program,
            .segment = segment_index,
            .environment = environment,
            .stack_base = @intCast(stack_base),
        };
        self.bytecode_frame_count += 1;
        self.stats.bytecode_frames_peak = @max(self.stats.bytecode_frames_peak, self.bytecode_frame_count);
        const previous_active_env = self.active_env;
        self.active_env = environment;
        defer {
            self.active_env = previous_active_env;
            self.bytecode_value_count = stack_base;
            self.bytecode_frame_count = frame_index;
        }
        errdefer |err| if (self.diagnostic_phase != .host)
            self.captureDiagnostic(.vm, err, program, self.diagnostic_node);

        var pc = start;
        while (pc < end) : (pc += 1) {
            const instruction = program.workspace.compiled.instructions[pc];
            const node = if (instruction.a != none and instruction.a < program.node_count) program.nodes[instruction.a] else Node{};
            self.diagnostic_program = program;
            self.diagnostic_node = instruction.a;
            self.diagnostic_opcode = instruction.op;
            try self.checkpoint();
            self.stats.bytecode_instructions += 1;
            switch (instruction.op) {
                .hoist_var => {
                    const name = program.text(node.text);
                    if (self.lookupOwn(environment, name) == null) try self.defineBinding(environment, name, .undefined, false);
                },
                .function_declaration => {
                    const value = try self.bytecodeFunctionDeclaration(program, instruction.a, environment);
                    self.bytecode_frames[frame_index].last_value = value;
                },
                .class_declaration => {
                    const value = try self.createClass(program, instruction.a, environment);
                    try self.defineBinding(environment, program.text(node.text), value, false);
                    if (node.flags & flag_exported != 0 and self.active_exports != none)
                        try self.registerModuleExport(program.text(node.text), program.text(node.text), none, .local, true);
                    self.bytecode_frames[frame_index].last_value = value;
                },
                .expression_result => self.bytecode_frames[frame_index].last_value = try self.bytecodePop(),
                .numeric_expression_statement => if (try self.numericExpressionValue(program, instruction.a, environment)) |value| {
                    self.bytecode_frames[frame_index].last_value = value;
                    pc += instruction.b;
                },
                .primitive_assignment_statement => if (try self.primitiveAssignmentValue(program, instruction.a, environment)) |value| {
                    self.bytecode_frames[frame_index].last_value = value;
                    pc += instruction.b;
                },
                .primitive_conditional_statement => if (try self.primitiveConditionalValue(program, instruction.a, environment)) |value| {
                    self.bytecode_frames[frame_index].last_value = value;
                    pc += instruction.b;
                },
                .variable => {
                    const value = self.bytecode_values[self.bytecode_value_count - 1];
                    try self.applyPattern(program, node.b, value, environment, .{
                        .binding = true,
                        .constant = node.flags & flag_const != 0,
                        .var_binding = node.flags & flag_var != 0,
                        .exported = node.flags & flag_exported != 0,
                    });
                    _ = try self.bytecodePop();
                    self.bytecode_frames[frame_index].last_value = value;
                },
                .numeric_variable => if (try self.numericExpressionValue(program, node.a, environment)) |value| {
                    try self.applyPattern(program, node.b, value, environment, .{
                        .binding = true,
                        .constant = node.flags & flag_const != 0,
                        .var_binding = node.flags & flag_var != 0,
                        .exported = node.flags & flag_exported != 0,
                    });
                    self.bytecode_frames[frame_index].last_value = value;
                    pc += instruction.b;
                },
                .return_value => return .{ .kind = .returned, .value = try self.bytecodePop() },
                .numeric_return_value => if (try self.numericExpressionValue(program, instruction.a, environment)) |value|
                    return .{ .kind = .returned, .value = value },
                .return_undefined => return .{ .kind = .returned },
                .throw_value => return .{ .kind = .thrown, .value = try self.bytecodePop() },
                .block => {
                    const completion = try self.executeBytecodeSegment(program, instruction.b, environment);
                    if (completion.kind != .normal) return completion;
                    self.bytecode_frames[frame_index].last_value = completion.value;
                },
                .if_statement => {
                    const completion = try self.executeBytecodeIf(program, node, environment);
                    if (completion.kind != .normal) return completion;
                    self.bytecode_frames[frame_index].last_value = completion.value;
                },
                .while_statement => {
                    const completion = try self.executeBytecodeWhile(program, node, environment, false);
                    if (completion.kind != .normal) return completion;
                    self.bytecode_frames[frame_index].last_value = completion.value;
                },
                .do_while_statement => {
                    const completion = try self.executeBytecodeWhile(program, node, environment, true);
                    if (completion.kind != .normal) return completion;
                    self.bytecode_frames[frame_index].last_value = completion.value;
                },
                .for_statement => {
                    const completion = try self.executeBytecodeFor(program, node, environment);
                    if (completion.kind != .normal) return completion;
                    self.bytecode_frames[frame_index].last_value = completion.value;
                },
                .for_in_statement => {
                    const completion = try self.executeBytecodeForIn(program, node, environment);
                    if (completion.kind != .normal) return completion;
                    self.bytecode_frames[frame_index].last_value = completion.value;
                },
                .for_of_statement => {
                    const completion = if (node.flags & flag_async != 0)
                        try self.executeBytecodeForAwaitOf(program, node, environment)
                    else
                        try self.executeBytecodeForOf(program, node, environment);
                    if (completion.kind != .normal) return completion;
                    self.bytecode_frames[frame_index].last_value = completion.value;
                },
                .switch_statement => {
                    const completion = try self.executeBytecodeSwitch(program, node, environment);
                    if (completion.kind != .normal) return completion;
                    self.bytecode_frames[frame_index].last_value = completion.value;
                },
                .labeled_statement => {
                    const completion = try self.executeBytecodeNode(program, node.a, environment);
                    if (completion.kind == .break_loop and completion.label.len != 0 and
                        equals(program.text(completion.label), program.text(node.text)))
                    {
                        self.bytecode_frames[frame_index].last_value = completion.value;
                        continue;
                    }
                    if (completion.kind != .normal) return completion;
                    self.bytecode_frames[frame_index].last_value = completion.value;
                },
                .break_statement => return .{ .kind = .break_loop, .label = node.text },
                .continue_statement => return .{ .kind = .continue_loop, .label = node.text },
                .with_statement => {
                    const completion = try self.executeBytecodeWith(program, node, environment);
                    if (completion.kind != .normal) return completion;
                    self.bytecode_frames[frame_index].last_value = completion.value;
                },
                .try_statement => {
                    const completion = try self.executeBytecodeTry(program, node, environment);
                    if (completion.kind != .normal) return completion;
                    self.bytecode_frames[frame_index].last_value = completion.value;
                },
                .import_statement => self.bytecode_frames[frame_index].last_value = try self.executeBytecodeImport(program, node, environment),
                .export_list => self.bytecode_frames[frame_index].last_value = try self.executeBytecodeExport(program, node, environment),
                .export_default => self.bytecode_frames[frame_index].last_value = try self.executeBytecodeExportDefault(try self.bytecodePop(), environment),
                .push_undefined => try self.bytecodePush(.undefined),
                .push_null => try self.bytecodePush(.null_value),
                .push_boolean => try self.bytecodePush(.{ .boolean = instruction.flags != 0 }),
                .push_number => try self.bytecodePush(.{ .number = node.number }),
                .numeric_expression => if (try self.numericExpressionValue(program, instruction.a, environment)) |value| {
                    try self.bytecodePush(value);
                    pc += instruction.b;
                },
                .primitive_assignment => if (try self.primitiveAssignmentValue(program, instruction.a, environment)) |value| {
                    try self.bytecodePush(value);
                    pc += instruction.b;
                },
                .primitive_conditional => if (try self.primitiveConditionalValue(program, instruction.a, environment)) |value| {
                    try self.bytecodePush(value);
                    pc += instruction.b;
                },
                .push_bigint => try self.bytecodePush(try self.createBigIntFromLiteral(program.text(node.text))),
                .push_string => try self.bytecodePush(.{ .string = try self.decodeString(program, node.text) }),
                .push_template_object => try self.bytecodePush(try self.templateObject(program, instruction.a)),
                .push_regex => try self.bytecodePush(try self.createRegex(program.text(node.text))),
                .load_identifier => try self.bytecodePush(try self.lookupRequiredCached(program, instruction.a, environment)),
                .array_begin => try self.bytecodePush(.{ .cell = try self.allocateCell(.array) }),
                .array_append => try self.bytecodeArrayAppend(instruction.flags != 0),
                .array_spread => try self.bytecodeArraySpread(program),
                .object_begin => try self.bytecodePush(.{ .cell = try self.allocateCell(.object) }),
                .object_set => try self.bytecodeObjectSet(program, node),
                .object_spread => try self.bytecodeObjectSpread(),
                .make_function => try self.bytecodePush(try self.createFunction(program, instruction.a, environment, node.flags)),
                .make_class => try self.bytecodePush(try self.createClass(program, instruction.a, environment)),
                .private_in => try self.bytecodePrivateIn(program, node, environment),
                .load_super_receiver => try self.bytecodePush(try self.superReceiver(environment)),
                .super_call => {
                    const argument_count: usize = instruction.b;
                    if (self.bytecode_value_count < argument_count) return error.BytecodeStack;
                    const base = self.bytecode_value_count - argument_count;
                    const result = try self.performSuperCall(program, environment, self.bytecode_values[base..self.bytecode_value_count]);
                    self.bytecode_value_count = base;
                    try self.bytecodePush(result);
                },
                .super_call_spread => {
                    if (self.bytecode_value_count < 1) return error.BytecodeStack;
                    const base = self.bytecode_value_count - 1;
                    const array = try self.expectCellKind(self.bytecode_values[base], .array);
                    const result = try self.performSuperCall(program, environment, self.itemStorageConst(array)[0..self.cells[array].item_count]);
                    self.bytecode_value_count = base;
                    try self.bytecodePush(result);
                },
                .unary => try self.bytecodeUnary(@enumFromInt(instruction.flags)),
                .type_of_identifier => {
                    const binding = try self.resolveBinding(environment, program.text(node.text));
                    try self.bytecodePush(.{ .string = try self.storeString(if (binding) |present| self.typeName(present.value) else "undefined") });
                },
                .delete_identifier => try self.bytecodePush(.{ .boolean = try self.bytecodeDeleteIdentifier(program, node, environment) }),
                .delete_member => try self.bytecodeDeleteMember(),
                .binary => try self.bytecodeBinary(@enumFromInt(instruction.flags)),
                .short_binary => try self.bytecodeShortBinary(program, @enumFromInt(instruction.flags), instruction.b, environment),
                .conditional => try self.bytecodeConditional(program, instruction.b, instruction.c, environment),
                .assign_identifier => try self.bytecodeAssignIdentifier(program, instruction.a, @enumFromInt(instruction.flags), environment),
                .logical_assign_identifier => try self.bytecodeLogicalAssignIdentifier(program, node, @enumFromInt(instruction.flags), instruction.b, environment),
                .load_member_for_assignment => try self.bytecodeLoadMemberForAssignment(program, node, environment),
                .assign_member => try self.bytecodeAssignMember(program, node, @enumFromInt(instruction.flags), environment),
                .assign_pattern => try self.bytecodeAssignPattern(program, node, environment),
                .logical_assign_member => try self.bytecodeLogicalAssignMember(program, node, @enumFromInt(instruction.flags), instruction.b, environment),
                .update_identifier => try self.bytecodeUpdateIdentifier(program, instruction.a, instruction.flags, environment),
                .update_member => try self.bytecodeUpdateMember(program, node, instruction.flags, environment),
                .push_property_name => try self.bytecodePush(.{ .string = try self.storeString(program.text(node.text)) }),
                .named_member_reference_identifier => try self.bytecodeNamedIdentifierMember(program, instruction.a, environment, .reference),
                .get_named_member_identifier => try self.bytecodeNamedIdentifierMember(program, instruction.a, environment, .value),
                .prepare_named_member_call_identifier => try self.bytecodeNamedIdentifierMember(program, instruction.a, environment, .call),
                .get_member => try self.bytecodeGetMember(program, instruction.a, environment, false),
                .prepare_member_call => try self.bytecodeGetMember(program, instruction.a, environment, true),
                .prepare_identifier_call => try self.bytecodePrepareIdentifierCall(program, node, environment),
                .call => try self.bytecodeCall(program, instruction.a, instruction.b, instruction.flags != 0),
                .call_spread => try self.bytecodeCallSpread(program, instruction.a, instruction.flags != 0),
                .optional_chain => try self.bytecodePush(try self.evaluateOptionalChain(program, instruction.a, environment, instruction.flags != 0)),
                .yield_value => {
                    const yielded = try self.bytecodePop();
                    try self.bytecodePush(if (instruction.flags != 0)
                        try self.yieldGeneratorDelegate(program, yielded)
                    else
                        try self.yieldGeneratorValue(yielded));
                },
                .await_value => {
                    const awaited = try self.bytecodePop();
                    try self.bytecodePush(try self.awaitAsyncValue(awaited));
                },
                .dynamic_import => {
                    const specifier = try self.bytecodePop();
                    try self.bytecodePush(try self.dynamicImport(specifier));
                },
                .import_meta => try self.bytecodePush(try self.importMeta()),
                .load_this => try self.bytecodePush(try self.thisValue(environment)),
                .load_new_target => try self.bytecodePush(self.lookup(environment, internal_new_target) orelse .undefined),
            }
        }
        if (segment.kind == .expression) {
            if (self.bytecode_value_count != stack_base + 1) return error.BytecodeStack;
            return .{ .value = try self.bytecodePop() };
        }
        if (self.bytecode_value_count != stack_base) return error.BytecodeStack;
        return .{ .value = self.bytecode_frames[frame_index].last_value };
    }

    fn bytecodeFunctionDeclaration(self: *Runtime, program: *const Program, index: u16, environment: u16) Error!Value {
        const node = program.nodes[index];
        const name = program.text(node.text);
        if (self.lookupOwn(environment, name)) |existing| return existing;
        const function = try self.createFunction(program, index, environment, node.flags);
        try self.defineBinding(environment, name, function, true);
        if (node.flags & flag_exported != 0 and self.active_exports != none)
            try self.registerModuleExport(name, name, none, .local, true);
        return function;
    }

    fn classElementName(self: *Runtime, program: *const Program, element: Node, environment: u16) Error!StringRef {
        if (element.flags & flag_computed != 0) {
            const segment = program.workspace.compiled.node_segments[element.b];
            if (segment == none) return error.BytecodeInvalid;
            return self.toPropertyKey(try self.bytecodeValueFromSegment(program, segment, environment));
        }
        if (element.flags & flag_key_number != 0) return self.toString(.{ .number = element.number });
        if (element.flags & flag_key_string != 0) return self.decodeString(program, element.text);
        return self.storeString(program.text(element.text));
    }

    fn classBrand(self: *Runtime, class_index: u16, environment: u16) Error!u16 {
        var name_buffer: [32]u8 = undefined;
        const name = classBrandBindingName(class_index, name_buffer[0..]) catch return error.StringLimit;
        const value = self.lookup(environment, name) orelse return error.TypeError;
        return switch (value) {
            .cell => |cell| if (cell < self.cells.len and self.cells[cell].occupied and self.cells[cell].kind == .function)
                cell
            else
                error.TypeError,
            else => error.TypeError,
        };
    }

    fn superReceiver(self: *Runtime, environment: u16) Error!Value {
        return self.lookup(environment, "this") orelse error.TypeError;
    }

    fn superBase(self: *Runtime, member: Node, environment: u16) Error!Value {
        const constructor = try self.classBrand(member.c, environment);
        const base = if (member.flags & flag_super_static != 0)
            self.cells[constructor].prototype
        else blk: {
            const prototype = try self.getProperty(.{ .cell = constructor }, "prototype");
            const prototype_index = try self.privateObjectIndex(prototype);
            break :blk self.cells[prototype_index].prototype;
        };
        if (base == none or base >= self.cells.len or !self.cells[base].occupied) return error.TypeError;
        return .{ .cell = base };
    }

    fn getSuperProperty(self: *Runtime, member: Node, environment: u16, receiver: Value, name: []const u8) Error!Value {
        return self.getPropertyFrom(try self.superBase(member, environment), name, receiver);
    }

    fn setSuperReceiverData(self: *Runtime, receiver: Value, name: []const u8, value: Value) Error!void {
        const receiver_index = try self.expectObject(receiver);
        if (self.findAccessor(receiver_index, name) != null) return error.TypeError;
        try self.defineOwnDataProperty(receiver, name, value);
    }

    fn setSuperProperty(self: *Runtime, member: Node, environment: u16, receiver: Value, name: []const u8, value: Value) Error!void {
        var current = (try self.superBase(member, environment)).cell;
        while (true) {
            if (self.findAccessor(current, name)) |accessor| {
                if (accessor.setter == .undefined) return error.TypeError;
                _ = try self.callAccessor(accessor.setter, receiver, &.{value});
                return;
            }
            for (self.propertyStorageConst(current)[0..self.cells[current].property_count]) |property| {
                if (!equals(self.stringBytes(property.key), name)) continue;
                try self.setSuperReceiverData(receiver, name, value);
                return;
            }
            const parent = self.cells[current].prototype;
            if (parent == none) break;
            if (parent >= self.cells.len or !self.cells[parent].occupied) return error.TypeError;
            current = parent;
        }
        try self.setSuperReceiverData(receiver, name, value);
    }

    fn definePrivateData(self: *Runtime, object: Value, brand: u16, name: []const u8, value: Value, kind: PrivateElementKind) Error!void {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(object);
        try self.pushRoot(.{ .cell = brand });
        try self.pushRoot(value);
        const owner = try self.privateObjectIndex(object);
        const bucket = try self.ensurePrivateBrandBucket(owner, brand);
        if (self.privateBucketHas(bucket, name)) return error.BytecodeInvalid;
        try self.defineOwnDataProperty(.{ .cell = bucket }, name, value);
        if (kind == .method) {
            const markers = try self.ensurePrivateMethodMarkers(bucket);
            try self.defineOwnDataProperty(.{ .cell = markers }, name, .{ .boolean = true });
        }
    }

    fn definePrivateAccessor(self: *Runtime, object: Value, brand: u16, name: []const u8, callable: Value, getter: bool) Error!void {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(object);
        try self.pushRoot(.{ .cell = brand });
        try self.pushRoot(callable);
        const owner = try self.privateObjectIndex(object);
        const bucket = try self.ensurePrivateBrandBucket(owner, brand);
        if (self.findAccessor(bucket, name) == null and self.privateBucketDataProperty(bucket, name) != null) return error.BytecodeInvalid;
        try self.defineOwnAccessor(.{ .cell = bucket }, name, callable, getter);
    }

    fn privateObjectIndex(self: *Runtime, object: Value) Error!u16 {
        return switch (object) {
            .cell => |cell| if (cell < self.cells.len and self.cells[cell].occupied and self.cells[cell].kind != .environment)
                cell
            else
                error.TypeError,
            else => error.TypeError,
        };
    }

    fn hasPrivate(self: *Runtime, object: Value, brand: u16, name: []const u8) Error!bool {
        const owner = try self.privateObjectIndex(object);
        const bucket = self.privateBrandBucket(owner, brand) orelse return false;
        return self.privateBucketHas(bucket, name);
    }

    fn getPrivate(self: *Runtime, object: Value, brand: u16, name: []const u8) Error!Value {
        const owner = try self.privateObjectIndex(object);
        const bucket = self.privateBrandBucket(owner, brand) orelse return error.TypeError;
        if (self.findAccessor(bucket, name)) |accessor| {
            if (accessor.getter == .undefined) return error.TypeError;
            return self.callAccessor(accessor.getter, object, &.{});
        }
        const property = self.privateBucketDataProperty(bucket, name) orelse return error.TypeError;
        return property.value;
    }

    fn setPrivate(self: *Runtime, object: Value, brand: u16, name: []const u8, value: Value) Error!void {
        const owner = try self.privateObjectIndex(object);
        const bucket = self.privateBrandBucket(owner, brand) orelse return error.TypeError;
        if (self.findAccessor(bucket, name)) |accessor| {
            if (accessor.setter == .undefined) return error.TypeError;
            _ = try self.callAccessor(accessor.setter, object, &.{value});
            return;
        }
        const property = self.privateBucketDataPropertyMutable(bucket, name) orelse return error.TypeError;
        if (self.privateMethodMarkers(bucket)) |markers| {
            if (self.privateBucketDataProperty(markers, name) != null) return error.TypeError;
        }
        property.value = value;
    }

    fn privateBrandBucket(self: *Runtime, owner: u16, brand: u16) ?u16 {
        const root = self.cells[owner].private_storage;
        if (root == none or root >= self.cells.len or !self.cells[root].occupied) return null;
        var key_buffer: [32]u8 = undefined;
        const key = privateBrandBucketName(brand, key_buffer[0..]) catch return null;
        const property = self.privateBucketDataProperty(root, key) orelse return null;
        return switch (property.value) {
            .cell => |bucket| if (bucket < self.cells.len and self.cells[bucket].occupied) bucket else null,
            else => null,
        };
    }

    fn ensurePrivateBrandBucket(self: *Runtime, owner: u16, brand: u16) Error!u16 {
        if (self.privateBrandBucket(owner, brand)) |bucket| return bucket;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = owner });
        try self.pushRoot(.{ .cell = brand });
        var root = self.cells[owner].private_storage;
        if (root == none) {
            root = try self.allocateCell(.object);
            self.cells[root].prototype = none;
            self.cells[owner].private_storage = root;
        }
        try self.pushRoot(.{ .cell = root });
        const bucket = try self.allocateCell(.object);
        self.cells[bucket].prototype = none;
        self.cells[bucket].parent = brand;
        try self.pushRoot(.{ .cell = bucket });
        var key_buffer: [32]u8 = undefined;
        const key = privateBrandBucketName(brand, key_buffer[0..]) catch return error.StringLimit;
        try self.defineOwnDataProperty(.{ .cell = root }, key, .{ .cell = bucket });
        return bucket;
    }

    fn privateMethodMarkers(self: *Runtime, bucket: u16) ?u16 {
        const markers = self.cells[bucket].private_storage;
        if (markers == none or markers >= self.cells.len or !self.cells[markers].occupied) return null;
        return markers;
    }

    fn ensurePrivateMethodMarkers(self: *Runtime, bucket: u16) Error!u16 {
        if (self.privateMethodMarkers(bucket)) |markers| return markers;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = bucket });
        const markers = try self.allocateCell(.object);
        self.cells[markers].prototype = none;
        self.cells[bucket].private_storage = markers;
        return markers;
    }

    fn privateBucketHas(self: *Runtime, bucket: u16, name: []const u8) bool {
        return self.privateBucketDataProperty(bucket, name) != null or self.findAccessor(bucket, name) != null;
    }

    fn privateBucketDataProperty(self: *const Runtime, bucket: u16, name: []const u8) ?Property {
        const cell = &self.cells[bucket];
        for (self.propertyStorageConst(bucket)[0..cell.property_count]) |property| {
            if (equals(self.stringBytes(property.key), name)) return property;
        }
        return null;
    }

    fn privateBucketDataPropertyMutable(self: *Runtime, bucket: u16, name: []const u8) ?*Property {
        const count = self.cells[bucket].property_count;
        for (self.propertyStorage(bucket)[0..count]) |*property| {
            if (equals(self.stringBytes(property.key), name)) return property;
        }
        return null;
    }

    fn createClass(self: *Runtime, program: *const Program, index: u16, parent: u16) Error!Value {
        if (index == none or index >= program.node_count) return error.BytecodeInvalid;
        const node = program.nodes[index];
        if (node.kind != .class_declaration and node.kind != .class_expression) return error.BytecodeInvalid;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        var heritage: Value = .undefined;
        var instance_parent = self.object_prototype;
        if (node.a != none) {
            heritage = try self.bytecodeValueFromNode(program, node.a, parent);
            try self.pushRoot(heritage);
            if (heritage == .null_value) {
                instance_parent = none;
            } else {
                if (!self.isConstructor(heritage)) return error.TypeError;
                const base_prototype = try self.getProperty(heritage, "prototype");
                instance_parent = switch (base_prototype) {
                    .null_value => none,
                    .cell => |cell| try self.privateObjectIndex(.{ .cell = cell }),
                    else => return error.TypeError,
                };
            }
        }
        const class_environment = try self.allocateCell(.environment);
        self.cells[class_environment].parent = parent;
        try self.pushRoot(.{ .cell = class_environment });
        const constructor_node = program.nodes[node.c];
        const constructor = try self.createFunction(program, node.c, class_environment, constructor_node.flags);
        try self.pushRoot(constructor);
        self.cells[constructor.cell].host_tag = index;
        self.cells[constructor.cell].promise_value = heritage;
        if (heritage == .cell) self.cells[constructor.cell].prototype = heritage.cell;
        var brand_name_buffer: [32]u8 = undefined;
        const brand_name = classBrandBindingName(index, brand_name_buffer[0..]) catch return error.StringLimit;
        try self.defineBinding(class_environment, brand_name, constructor, true);
        if (node.text.len > 0) try self.defineBinding(class_environment, program.text(node.text), constructor, true);
        const prototype = Value{ .cell = try self.allocateCell(.object) };
        try self.pushRoot(prototype);
        self.cells[prototype.cell].prototype = instance_parent;
        try self.defineOwnDataProperty(prototype, "constructor", constructor);
        try self.defineOwnDataProperty(constructor, "prototype", prototype);

        var element_count: usize = 0;
        var current = node.b;
        while (current != none) : (current = program.nodes[current].next) element_count += 1;
        if (element_count > max_items / 2) return error.ItemLimit;
        try self.ensureItemCapacity(constructor.cell, element_count * 2);
        self.cells[constructor.cell].item_count = element_count * 2;

        const static_environment = try self.allocateCell(.environment);
        self.cells[static_environment].parent = class_environment;
        try self.pushRoot(.{ .cell = static_environment });
        try self.defineBinding(static_environment, "this", constructor, true);

        // All class element keys are evaluated before static initializers. The
        // second slot per element retains the shared method/accessor function.
        current = node.b;
        var ordinal: usize = 0;
        while (current != none) : (current = program.nodes[current].next) {
            const element = program.nodes[current];
            if (element.kind != .class_element) return error.BytecodeInvalid;
            if (element.flags & flag_class_static_block != 0) {
                self.itemStorage(constructor.cell)[ordinal * 2] = .undefined;
                self.itemStorage(constructor.cell)[ordinal * 2 + 1] = .undefined;
                ordinal += 1;
                continue;
            }
            const name = if (element.flags & flag_private != 0)
                try self.storeString(program.text(element.text))
            else
                try self.classElementName(program, element, class_environment);
            self.itemStorage(constructor.cell)[ordinal * 2] = .{ .string = name };
            self.itemStorage(constructor.cell)[ordinal * 2 + 1] = .undefined;
            ordinal += 1;
        }

        current = node.b;
        ordinal = 0;
        while (current != none) : (current = program.nodes[current].next) {
            const element = program.nodes[current];
            if (element.flags & flag_class_static_block == 0 and element.flags & flag_class_field == 0 and element.a != node.c) {
                const name_value = self.itemStorageConst(constructor.cell)[ordinal * 2];
                if (name_value != .string) return error.BytecodeInvalid;
                const method_node = program.nodes[element.a];
                const method = try self.createFunction(program, element.a, class_environment, method_node.flags);
                self.itemStorage(constructor.cell)[ordinal * 2 + 1] = method;
                const target = if (element.flags & flag_class_static != 0) constructor else prototype;
                if (element.flags & flag_private != 0) {
                    if (element.flags & flag_class_static != 0) {
                        if (element.flags & flag_getter != 0)
                            try self.definePrivateAccessor(target, constructor.cell, self.stringBytes(name_value.string), method, true)
                        else if (element.flags & flag_setter != 0)
                            try self.definePrivateAccessor(target, constructor.cell, self.stringBytes(name_value.string), method, false)
                        else
                            try self.definePrivateData(target, constructor.cell, self.stringBytes(name_value.string), method, .method);
                    }
                } else if (element.flags & flag_getter != 0) {
                    try self.defineOwnAccessor(target, self.stringBytes(name_value.string), method, true);
                } else if (element.flags & flag_setter != 0) {
                    try self.defineOwnAccessor(target, self.stringBytes(name_value.string), method, false);
                } else {
                    try self.defineOwnDataProperty(target, self.stringBytes(name_value.string), method);
                }
            }
            ordinal += 1;
        }

        current = node.b;
        ordinal = 0;
        while (current != none) : (current = program.nodes[current].next) {
            const element = program.nodes[current];
            if (element.flags & flag_class_static_block != 0) {
                const completion = try self.executeBytecodeNode(program, element.a, static_environment);
                if (completion.kind == .thrown) {
                    self.pending_exception = completion.value;
                    return error.ScriptThrown;
                }
                if (completion.kind != .normal) return error.BytecodeInvalid;
            } else if (element.flags & flag_class_field != 0 and element.flags & flag_class_static != 0) {
                const name_value = self.itemStorageConst(constructor.cell)[ordinal * 2];
                if (name_value != .string) return error.BytecodeInvalid;
                const value = if (element.a == none)
                    Value.undefined
                else
                    try self.bytecodeValueFromNode(program, element.a, static_environment);
                if (element.flags & flag_private != 0)
                    try self.definePrivateData(constructor, constructor.cell, self.stringBytes(name_value.string), value, .field)
                else
                    try self.defineOwnDataProperty(constructor, self.stringBytes(name_value.string), value);
            }
            ordinal += 1;
        }
        return constructor;
    }

    fn initializeClassInstance(self: *Runtime, program: *const Program, function_index: u16, this_value: Value) Error!void {
        const class_index = self.cells[function_index].host_tag;
        if (class_index == none or class_index >= program.node_count) return error.BytecodeInvalid;
        const class_node = program.nodes[class_index];
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(this_value);
        const environment = try self.allocateCell(.environment);
        self.cells[environment].parent = self.cells[function_index].parent;
        try self.pushRoot(.{ .cell = environment });
        try self.defineBinding(environment, "this", this_value, true);
        var current = class_node.b;
        var ordinal: usize = 0;
        while (current != none) : (current = program.nodes[current].next) {
            const element = program.nodes[current];
            if (element.flags & flag_private != 0 and element.flags & flag_class_static == 0 and
                element.flags & flag_class_field == 0 and element.a != class_node.c)
            {
                if (ordinal * 2 + 1 >= self.cells[function_index].item_count) return error.BytecodeInvalid;
                const name_value = self.itemStorageConst(function_index)[ordinal * 2];
                const method = self.itemStorageConst(function_index)[ordinal * 2 + 1];
                if (name_value != .string or method == .undefined) return error.BytecodeInvalid;
                if (element.flags & flag_getter != 0)
                    try self.definePrivateAccessor(this_value, function_index, self.stringBytes(name_value.string), method, true)
                else if (element.flags & flag_setter != 0)
                    try self.definePrivateAccessor(this_value, function_index, self.stringBytes(name_value.string), method, false)
                else
                    try self.definePrivateData(this_value, function_index, self.stringBytes(name_value.string), method, .method);
            }
            ordinal += 1;
        }
        current = class_node.b;
        ordinal = 0;
        while (current != none) : (current = program.nodes[current].next) {
            const element = program.nodes[current];
            if (element.flags & flag_class_field != 0 and element.flags & flag_class_static == 0) {
                if (ordinal * 2 >= self.cells[function_index].item_count) return error.BytecodeInvalid;
                const name_value = self.itemStorageConst(function_index)[ordinal * 2];
                if (name_value != .string) return error.BytecodeInvalid;
                const value = if (element.a == none)
                    Value.undefined
                else
                    try self.bytecodeValueFromNode(program, element.a, environment);
                if (element.flags & flag_private != 0)
                    try self.definePrivateData(this_value, function_index, self.stringBytes(name_value.string), value, .field)
                else
                    try self.defineOwnDataProperty(this_value, self.stringBytes(name_value.string), value);
            }
            ordinal += 1;
        }
    }

    fn bytecodeArrayAppend(self: *Runtime, hole: bool) Error!void {
        if (self.bytecode_value_count < 2) return error.BytecodeStack;
        const array_value = self.bytecode_values[self.bytecode_value_count - 2];
        const item = self.bytecode_values[self.bytecode_value_count - 1];
        const index = try self.expectCellKind(array_value, .array);
        try self.ensureItemCapacity(index, self.cells[index].item_count + 1);
        self.itemStorage(index)[self.cells[index].item_count] = item;
        self.setArrayItemPresent(index, self.cells[index].item_count, !hole);
        self.cells[index].item_count += 1;
        self.cells[index].array_length = self.cells[index].item_count;
        self.bytecode_value_count -= 1;
    }

    fn bytecodeArraySpread(self: *Runtime, program: *const Program) Error!void {
        if (self.bytecode_value_count < 2) return error.BytecodeStack;
        const array_value = self.bytecode_values[self.bytecode_value_count - 2];
        const source = self.bytecode_values[self.bytecode_value_count - 1];
        const index = try self.expectCellKind(array_value, .array);
        try self.appendIterableToArray(program, index, source, max_items);
        self.bytecode_value_count -= 1;
    }

    fn bytecodeObjectSpread(self: *Runtime) Error!void {
        if (self.bytecode_value_count < 2) return error.BytecodeStack;
        const target = self.bytecode_values[self.bytecode_value_count - 2];
        const source = self.bytecode_values[self.bytecode_value_count - 1];
        try self.copyDataProperties(target, source, &.{}, false);
        self.bytecode_value_count -= 1;
    }

    fn bytecodeAssignPattern(self: *Runtime, program: *const Program, assignment: Node, environment: u16) Error!void {
        if (self.bytecode_value_count < 1 or assignment.kind != .assignment) return error.BytecodeStack;
        const value = self.bytecode_values[self.bytecode_value_count - 1];
        try self.applyPattern(program, assignment.a, value, environment, .{});
    }

    fn bytecodeCallSpread(self: *Runtime, program: *const Program, node_index: u16, construct: bool) Error!void {
        if (self.bytecode_value_count < 3) return error.BytecodeStack;
        const base = self.bytecode_value_count - 3;
        const receiver = self.bytecode_values[base];
        const callable = self.bytecode_values[base + 1];
        const arguments_index = try self.expectCellKind(self.bytecode_values[base + 2], .array);
        const argument_count = self.effectiveArrayLength(arguments_index);
        if (argument_count > max_call_arguments or argument_count != self.cells[arguments_index].item_count) return error.RangeError;
        self.diagnostic_program = program;
        self.diagnostic_node = node_index;
        const result = try self.call(
            program,
            callable,
            receiver,
            self.itemStorageConst(arguments_index)[0..argument_count],
            construct,
        );
        self.bytecode_value_count = base;
        try self.bytecodePush(result);
    }

    fn openAsyncIterator(self: *Runtime, program: *const Program, source: Value) Error!AsyncIteratorCursor {
        const property_name = self.stringBytes(self.symbol_async_iterator);
        const has_async_method = source == .cell and try self.hasProperty(source, property_name);
        if (!has_async_method) {
            return .{
                .synchronous = true,
                .source = source,
                .sync_cursor = try self.openIterator(program, source),
            };
        }
        const method = try self.getProperty(source, property_name);
        if (!self.isCallableValue(method)) return error.TypeError;
        const iterator = try self.call(program, method, source, &.{}, false);
        _ = try self.expectObject(iterator);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(iterator);
        const next_method = try self.getProperty(iterator, "next");
        if (!self.isCallableValue(next_method)) return error.TypeError;
        return .{
            .source = source,
            .iterator = iterator,
            .next_method = next_method,
        };
    }

    fn rootAsyncIterator(self: *Runtime, cursor: AsyncIteratorCursor) Error!void {
        if (cursor.synchronous) {
            try self.rootIterator(cursor.sync_cursor);
            return;
        }
        try self.pushRoot(cursor.source);
        try self.pushRoot(cursor.iterator);
        try self.pushRoot(cursor.next_method);
    }

    fn asyncIteratorNext(self: *Runtime, program: *const Program, cursor: *AsyncIteratorCursor, value: Value, has_value: bool) Error!IteratorStep {
        if (cursor.done) return .{ .done = true };
        if (cursor.synchronous) {
            const step = if (has_value)
                try self.iteratorNextWithValue(program, &cursor.sync_cursor, value)
            else
                try self.iteratorNext(program, &cursor.sync_cursor);
            if (step.done) {
                cursor.done = true;
                return step;
            }
            return .{ .done = false, .value = try self.awaitAsyncValue(step.value) };
        }
        const result = try self.call(
            program,
            cursor.next_method,
            cursor.iterator,
            if (has_value) &.{value} else &.{},
            false,
        );
        const awaited = try self.awaitAsyncValue(result);
        _ = try self.expectObject(awaited);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(awaited);
        const done = self.truthy(try self.getProperty(awaited, "done"));
        const item = try self.getProperty(awaited, "value");
        if (done) cursor.done = true;
        return .{ .done = done, .value = item };
    }

    fn asyncIteratorClose(self: *Runtime, program: *const Program, cursor: *AsyncIteratorCursor) Error!void {
        if (cursor.done) return;
        cursor.done = true;
        const iterator = if (cursor.synchronous) cursor.sync_cursor.iterator else cursor.iterator;
        if (cursor.synchronous and cursor.sync_cursor.kind != .custom) {
            cursor.sync_cursor.done = true;
            return;
        }
        const return_method = try self.getProperty(iterator, "return");
        if (return_method.isNullish()) return;
        if (!self.isCallableValue(return_method)) return error.TypeError;
        const result = try self.call(program, return_method, iterator, &.{}, false);
        const awaited = try self.awaitAsyncValue(result);
        _ = try self.expectObject(awaited);
        if (cursor.synchronous) cursor.sync_cursor.done = true;
    }

    fn openIterator(self: *Runtime, program: *const Program, source: Value) Error!IteratorCursor {
        const property_name = self.stringBytes(self.symbol_iterator);
        const builtin = switch (source) {
            .string => IteratorKind.string,
            .cell => |index| if (index < self.cells.len and self.cells[index].occupied and self.cells[index].kind == .array)
                IteratorKind.array
            else
                IteratorKind.custom,
            else => IteratorKind.custom,
        };
        const has_custom_method = switch (source) {
            .cell => try self.hasProperty(source, property_name),
            else => false,
        };
        if (!has_custom_method and builtin != .custom) {
            return .{
                .kind = builtin,
                .source = source,
                .length = switch (source) {
                    .string => |ref| runtimeStringElementCount(self.stringBytes(ref)),
                    .cell => |index| self.effectiveArrayLength(index),
                    else => unreachable,
                },
            };
        }
        if (source != .cell) return error.TypeError;
        const method = try self.getProperty(source, property_name);
        if (method.isNullish() or !self.isCallableValue(method)) return error.TypeError;
        const iterator = try self.call(program, method, source, &.{}, false);
        _ = try self.expectObject(iterator);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(iterator);
        const next_method = try self.getProperty(iterator, "next");
        if (!self.isCallableValue(next_method)) return error.TypeError;
        return .{
            .kind = .custom,
            .source = source,
            .iterator = iterator,
            .next_method = next_method,
        };
    }

    fn rootIterator(self: *Runtime, cursor: IteratorCursor) Error!void {
        try self.pushRoot(cursor.source);
        if (cursor.kind == .custom) {
            try self.pushRoot(cursor.iterator);
            try self.pushRoot(cursor.next_method);
        }
    }

    fn iteratorNext(self: *Runtime, program: *const Program, cursor: *IteratorCursor) Error!IteratorStep {
        return self.iteratorNextInternal(program, cursor, null, false);
    }

    fn iteratorNextWithValue(self: *Runtime, program: *const Program, cursor: *IteratorCursor, input: ?Value) Error!IteratorStep {
        return self.iteratorNextInternal(program, cursor, input, true);
    }

    fn iteratorNextInternal(self: *Runtime, program: *const Program, cursor: *IteratorCursor, input: ?Value, read_done_value: bool) Error!IteratorStep {
        if (cursor.done) return .{ .done = true };
        switch (cursor.kind) {
            .array => {
                if (cursor.index >= cursor.length) {
                    cursor.done = true;
                    return .{ .done = true };
                }
                const index = try self.expectCellKind(cursor.source, .array);
                const value = if (cursor.index < self.cells[index].item_count)
                    self.itemStorageConst(index)[cursor.index]
                else
                    Value.undefined;
                cursor.index += 1;
                return .{ .done = false, .value = value };
            },
            .string => {
                if (cursor.index >= cursor.length) {
                    cursor.done = true;
                    return .{ .done = true };
                }
                const ref = cursor.source.string;
                const bytes = runtimeStringElementAt(self.stringBytes(ref), cursor.index) orelse return error.TypeError;
                cursor.index += 1;
                return .{ .done = false, .value = .{ .string = try self.storeString(bytes) } };
            },
            .custom => {
                var argument: [1]Value = undefined;
                const arguments: []const Value = if (input) |value| blk: {
                    argument[0] = value;
                    break :blk argument[0..1];
                } else &.{};
                const result = try self.call(program, cursor.next_method, cursor.iterator, arguments, false);
                _ = try self.expectObject(result);
                const root_base = self.root_count;
                defer self.root_count = root_base;
                try self.pushRoot(result);
                const done = self.truthy(try self.getProperty(result, "done"));
                if (done) {
                    cursor.done = true;
                    return .{ .done = true, .value = if (read_done_value) try self.getProperty(result, "value") else .undefined };
                }
                return .{ .done = false, .value = try self.getProperty(result, "value") };
            },
        }
    }

    fn iteratorClose(self: *Runtime, program: *const Program, cursor: *IteratorCursor) Error!void {
        if (cursor.done) return;
        cursor.done = true;
        if (cursor.kind != .custom) return;
        const return_method = try self.getProperty(cursor.iterator, "return");
        if (return_method.isNullish()) return;
        if (!self.isCallableValue(return_method)) return error.TypeError;
        const result = try self.call(program, return_method, cursor.iterator, &.{}, false);
        _ = try self.expectObject(result);
    }

    fn appendIterableToArray(self: *Runtime, program: *const Program, destination: u16, source: Value, limit: usize) Error!void {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = destination });
        try self.pushRoot(source);
        var cursor = try self.openIterator(program, source);
        try self.rootIterator(cursor);
        errdefer self.iteratorClose(program, &cursor) catch {};
        while (true) {
            const step = try self.iteratorNext(program, &cursor);
            if (step.done) break;
            if (self.cells[destination].item_count >= limit) return error.RangeError;
            const item_root = self.root_count;
            defer self.root_count = item_root;
            try self.pushRoot(step.value);
            try self.ensureItemCapacity(destination, self.cells[destination].item_count + 1);
            self.itemStorage(destination)[self.cells[destination].item_count] = step.value;
            self.setArrayItemPresent(destination, self.cells[destination].item_count, true);
            self.cells[destination].item_count += 1;
        }
        self.cells[destination].array_length = self.cells[destination].item_count;
    }

    fn patternPropertyName(self: *Runtime, program: *const Program, element: Node, environment: u16) Error!StringRef {
        if (element.flags & flag_computed != 0) {
            const segment = program.workspace.compiled.node_segments[element.c];
            if (segment == none) return error.BytecodeInvalid;
            const value = try self.bytecodeValueFromSegment(program, segment, environment);
            return self.toPropertyKey(value);
        }
        if (element.flags & flag_key_number != 0) return self.toString(.{ .number = element.number });
        if (element.flags & flag_key_string != 0) return self.decodeString(program, element.text);
        return self.storeString(program.text(element.text));
    }

    fn patternValueOrDefault(self: *Runtime, program: *const Program, element: Node, value: Value, environment: u16) Error!Value {
        if (value != .undefined or element.b == none) return value;
        const segment = program.workspace.compiled.node_segments[element.b];
        if (segment == none) return error.BytecodeInvalid;
        return self.bytecodeValueFromSegment(program, segment, environment);
    }

    fn applyPattern(self: *Runtime, program: *const Program, index: u16, value: Value, environment: u16, options: PatternOptions) Error!void {
        if (index == none or index >= program.node_count) return error.BytecodeInvalid;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(value);
        const pattern = program.nodes[index];
        switch (pattern.kind) {
            .identifier => {
                const name = program.text(pattern.text);
                if (options.binding) {
                    if (options.var_binding and self.lookup(environment, name) != null)
                        try self.assignLexicalBinding(environment, name, value)
                    else
                        try self.defineBinding(environment, name, value, options.constant);
                    if (options.exported and self.active_exports != none)
                        try self.registerModuleExport(name, name, none, .local, true);
                } else {
                    try self.assignBinding(environment, name, value);
                }
            },
            .member => {
                if (options.binding) return error.SyntaxError;
                const object = if (pattern.flags & flag_super != 0)
                    try self.superReceiver(environment)
                else
                    try self.bytecodeValueFromNode(program, pattern.a, environment);
                try self.pushRoot(object);
                const name = if (pattern.flags & flag_computed != 0) blk: {
                    const property = try self.bytecodeValueFromNode(program, pattern.b, environment);
                    break :blk self.stringBytes(try self.toPropertyKey(property));
                } else program.text(pattern.text);
                if (pattern.flags & flag_private != 0)
                    try self.setPrivate(object, try self.classBrand(pattern.c, environment), name, value)
                else if (pattern.flags & flag_super != 0)
                    try self.setSuperProperty(pattern, environment, object, name, value)
                else
                    try self.setProperty(object, name, value);
            },
            .array_pattern => {
                var cursor = try self.openIterator(program, value);
                try self.rootIterator(cursor);
                errdefer self.iteratorClose(program, &cursor) catch {};
                var current = pattern.a;
                while (current != none) : (current = program.nodes[current].next) {
                    const element = program.nodes[current];
                    if (element.kind != .pattern_element) return error.BytecodeInvalid;
                    if (element.flags & flag_elision != 0) {
                        _ = try self.iteratorNext(program, &cursor);
                        continue;
                    }
                    if (element.flags & flag_rest != 0) {
                        const rest = Value{ .cell = try self.allocateCell(.array) };
                        try self.pushRoot(rest);
                        while (true) {
                            const step = try self.iteratorNext(program, &cursor);
                            if (step.done) break;
                            const item_root = self.root_count;
                            defer self.root_count = item_root;
                            try self.pushRoot(step.value);
                            try self.ensureItemCapacity(rest.cell, self.cells[rest.cell].item_count + 1);
                            self.itemStorage(rest.cell)[self.cells[rest.cell].item_count] = step.value;
                            self.setArrayItemPresent(rest.cell, self.cells[rest.cell].item_count, true);
                            self.cells[rest.cell].item_count += 1;
                        }
                        self.cells[rest.cell].array_length = self.cells[rest.cell].item_count;
                        try self.applyPattern(program, element.a, rest, environment, options);
                        continue;
                    }
                    const step = try self.iteratorNext(program, &cursor);
                    const item = if (step.done) Value.undefined else step.value;
                    try self.applyPattern(program, element.a, try self.patternValueOrDefault(program, element, item, environment), environment, options);
                }
                try self.iteratorClose(program, &cursor);
            },
            .object_pattern => {
                if (value.isNullish()) return error.TypeError;
                var excluded: [max_properties]StringRef = undefined;
                var excluded_count: usize = 0;
                var current = pattern.a;
                while (current != none) : (current = program.nodes[current].next) {
                    const element = program.nodes[current];
                    if (element.kind != .pattern_element) return error.BytecodeInvalid;
                    if (element.flags & flag_rest != 0) {
                        const rest = Value{ .cell = try self.allocateCell(.object) };
                        try self.pushRoot(rest);
                        try self.copyDataProperties(rest, value, excluded[0..excluded_count], false);
                        try self.applyPattern(program, element.a, rest, environment, options);
                        continue;
                    }
                    if (excluded_count >= excluded.len) return error.PropertyLimit;
                    const name = try self.patternPropertyName(program, element, environment);
                    excluded[excluded_count] = name;
                    excluded_count += 1;
                    const property_value = try self.getProperty(value, self.stringBytes(name));
                    try self.applyPattern(program, element.a, try self.patternValueOrDefault(program, element, property_value, environment), environment, options);
                }
            },
            else => return error.InvalidAssignment,
        }
    }

    fn propertyExcluded(self: *const Runtime, name: []const u8, excluded: []const StringRef) bool {
        for (excluded) |ref| if (equals(name, self.stringBytes(ref))) return true;
        return false;
    }

    fn copyDataProperties(self: *Runtime, target: Value, source: Value, excluded: []const StringRef, set_target: bool) Error!void {
        if (source.isNullish()) return;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(target);
        try self.pushRoot(source);
        switch (source) {
            .string => |ref| {
                if (self.symbolParts(ref) != null) return;
                const length = runtimeStringUnitCount(self.stringBytes(ref));
                var item_index: usize = 0;
                while (item_index < length) : (item_index += 1) {
                    var name_buffer: [32]u8 = undefined;
                    const name = std.fmt.bufPrint(name_buffer[0..], "{d}", .{item_index}) catch return error.StringLimit;
                    if (self.propertyExcluded(name, excluded)) continue;
                    const item = Value{ .string = try self.storeStringUnit(runtimeStringUnitAt(self.stringBytes(ref), item_index) orelse return error.TypeError) };
                    if (set_target) try self.setProperty(target, name, item) else try self.defineOwnDataProperty(target, name, item);
                }
            },
            .cell => |index| {
                if (index >= self.cells.len or !self.cells[index].occupied) return error.NotObject;
                if (self.cells[index].kind == .proxy) {
                    const keys = try self.ownKeysInternal(source);
                    try self.pushRoot(keys);
                    for (self.itemStorageConst(keys.cell)[0..self.cells[keys.cell].item_count]) |key_value| {
                        const key = self.stringBytes(key_value.string);
                        if (self.propertyExcluded(key, excluded)) continue;
                        const descriptor = try self.nativeObjectGetDescriptor(&.{ source, key_value });
                        if (descriptor == .undefined or !self.truthy(try self.getProperty(descriptor, "enumerable"))) continue;
                        const property_value = try self.getProperty(source, key);
                        if (set_target) try self.setProperty(target, key, property_value) else try self.defineOwnDataProperty(target, key, property_value);
                    }
                    return;
                }
                if (self.cells[index].kind == .array) {
                    try self.syncMappedArguments(index);
                    var item_index: usize = 0;
                    while (item_index < self.cells[index].item_count) : (item_index += 1) {
                        if (!self.arrayItemPresent(index, item_index)) continue;
                        var name_buffer: [32]u8 = undefined;
                        const name = std.fmt.bufPrint(name_buffer[0..], "{d}", .{item_index}) catch return error.StringLimit;
                        if (self.propertyExcluded(name, excluded)) continue;
                        if (set_target)
                            try self.setProperty(target, name, self.itemStorageConst(index)[item_index])
                        else
                            try self.defineOwnDataProperty(target, name, self.itemStorageConst(index)[item_index]);
                    }
                }
                var property_index: usize = 0;
                while (property_index < self.cells[index].property_count) : (property_index += 1) {
                    const property = self.propertyStorageConst(index)[property_index];
                    if (!property.enumerable) continue;
                    const key = self.stringBytes(property.key);
                    if (self.propertyExcluded(key, excluded)) continue;
                    const property_value = try self.getProperty(source, key);
                    if (set_target) try self.setProperty(target, key, property_value) else try self.defineOwnDataProperty(target, key, property_value);
                }
            },
            .number, .boolean => {},
            else => {},
        }
    }

    fn bytecodeObjectSet(self: *Runtime, program: *const Program, property: Node) Error!void {
        _ = program;
        if (self.bytecode_value_count < 3) return error.BytecodeStack;
        const base = self.bytecode_value_count - 3;
        const object = self.bytecode_values[base];
        const name = try self.bytecodePropertyName(self.bytecode_values[base + 1]);
        const value = self.bytecode_values[base + 2];
        if (property.flags & flag_proto_setter != 0) {
            const object_index = try self.expectObject(object);
            switch (value) {
                .null_value => self.cells[object_index].prototype = none,
                .cell => self.cells[object_index].prototype = try self.expectObject(value),
                else => {},
            }
        } else if (property.flags & flag_getter != 0) {
            try self.defineOwnAccessor(object, name, value, true);
        } else if (property.flags & flag_setter != 0) {
            try self.defineOwnAccessor(object, name, value, false);
        } else {
            try self.defineOwnDataProperty(object, name, value);
        }
        self.bytecode_value_count = base + 1;
    }

    fn bytecodeUnary(self: *Runtime, operation: UnaryOp) Error!void {
        if (self.bytecode_value_count < 1) return error.BytecodeStack;
        const value = self.bytecode_values[self.bytecode_value_count - 1];
        self.bytecode_values[self.bytecode_value_count - 1] = switch (operation) {
            .positive => .{ .number = try self.toNumber(value) },
            .negative => blk: {
                const primitive = try self.toPrimitive(value, .number);
                break :blk if (primitive == .bigint) try self.bigIntUnaryNegative(primitive) else .{ .number = -(try self.toNumber(primitive)) };
            },
            .logical_not => .{ .boolean = !self.truthy(value) },
            .bitwise_not => blk: {
                const primitive = try self.toPrimitive(value, .number);
                break :blk if (primitive == .bigint) try self.bigIntUnaryNot(primitive) else .{ .number = @floatFromInt(~toInt32(try self.toNumber(primitive))) };
            },
            .type_of => .{ .string = try self.storeString(self.typeName(value)) },
            .void_value => .undefined,
            .delete_value => return error.BytecodeInvalid,
        };
    }

    fn bytecodeBinaryValue(self: *Runtime, operation: BinaryOp, left: Value, right: Value) Error!Value {
        if (left == .number and right == .number) return numberBinaryValue(operation, left.number, right.number);
        return switch (operation) {
            .add => self.addValues(left, right),
            .subtract,
            .multiply,
            .divide,
            .remainder,
            .exponentiate,
            .bitwise_and,
            .bitwise_xor,
            .bitwise_or,
            .shift_left,
            .shift_right,
            .shift_unsigned,
            => self.numericBinary(operation, left, right),
            .equal => .{ .boolean = try self.looseEqual(left, right) },
            .strict_equal => .{ .boolean = self.strictEqual(left, right) },
            .not_equal => .{ .boolean = !(try self.looseEqual(left, right)) },
            .strict_not_equal => .{ .boolean = !self.strictEqual(left, right) },
            .less, .less_equal, .greater, .greater_equal => blk: {
                const order = try self.relationalCompare(left, right) orelse break :blk .{ .boolean = false };
                break :blk .{ .boolean = switch (operation) {
                    .less => order == .lt,
                    .less_equal => order != .gt,
                    .greater => order == .gt,
                    .greater_equal => order != .lt,
                    else => unreachable,
                } };
            },
            .in => .{ .boolean = try self.hasProperty(right, self.stringBytes(try self.toPropertyKey(left))) },
            .instance_of => .{ .boolean = try self.instanceOfValue(left, right) },
            .logical_and, .logical_or, .nullish, .comma => right,
        };
    }

    fn numberBinaryValue(operation: BinaryOp, left: f64, right: f64) Error!Value {
        return switch (operation) {
            .add => .{ .number = left + right },
            .subtract => .{ .number = left - right },
            .multiply => .{ .number = left * right },
            .divide => .{ .number = left / right },
            .remainder => .{ .number = @rem(left, right) },
            .exponentiate => .{ .number = std.math.pow(f64, left, right) },
            .bitwise_and => .{ .number = @floatFromInt(toInt32(left) & toInt32(right)) },
            .bitwise_xor => .{ .number = @floatFromInt(toInt32(left) ^ toInt32(right)) },
            .bitwise_or => .{ .number = @floatFromInt(toInt32(left) | toInt32(right)) },
            .shift_left => .{ .number = @floatFromInt(toInt32(left) << @intCast(toUint32(right) & 31)) },
            .shift_right => .{ .number = @floatFromInt(toInt32(left) >> @intCast(toUint32(right) & 31)) },
            .shift_unsigned => .{ .number = @floatFromInt(toUint32(left) >> @intCast(toUint32(right) & 31)) },
            .equal, .strict_equal => .{ .boolean = left == right },
            .not_equal, .strict_not_equal => .{ .boolean = left != right },
            .less => .{ .boolean = left < right },
            .less_equal => .{ .boolean = left <= right },
            .greater => .{ .boolean = left > right },
            .greater_equal => .{ .boolean = left >= right },
            .logical_and, .logical_or, .nullish, .comma => .{ .number = right },
            .in, .instance_of => error.TypeError,
        };
    }

    fn bytecodePrivateIn(self: *Runtime, program: *const Program, node: Node, environment: u16) Error!void {
        if (self.bytecode_value_count < 1 or node.kind != .private_in) return error.BytecodeStack;
        const object_index = self.bytecode_value_count - 1;
        const object = self.bytecode_values[object_index];
        const brand = try self.classBrand(node.c, environment);
        self.bytecode_values[object_index] = .{
            .boolean = try self.hasPrivate(object, brand, program.text(node.text)),
        };
    }

    fn bytecodeBinary(self: *Runtime, operation: BinaryOp) Error!void {
        if (self.bytecode_value_count < 2) return error.BytecodeStack;
        const base = self.bytecode_value_count - 2;
        const result = try self.bytecodeBinaryValue(operation, self.bytecode_values[base], self.bytecode_values[base + 1]);
        self.bytecode_value_count = base;
        try self.bytecodePush(result);
    }

    fn bytecodeShortBinary(self: *Runtime, program: *const Program, operation: BinaryOp, right_segment: u16, environment: u16) Error!void {
        if (self.bytecode_value_count < 1) return error.BytecodeStack;
        const left_index = self.bytecode_value_count - 1;
        const left = self.bytecode_values[left_index];
        const use_right = switch (operation) {
            .logical_and => self.truthy(left),
            .logical_or => !self.truthy(left),
            .nullish => left.isNullish(),
            else => return error.BytecodeInvalid,
        };
        if (!use_right) return;
        const right = try self.bytecodeValueFromSegment(program, right_segment, environment);
        self.bytecode_values[left_index] = right;
    }

    fn bytecodeConditional(self: *Runtime, program: *const Program, then_segment: u16, else_segment: u16, environment: u16) Error!void {
        if (self.bytecode_value_count < 1) return error.BytecodeStack;
        const condition_index = self.bytecode_value_count - 1;
        const segment = if (self.truthy(self.bytecode_values[condition_index])) then_segment else else_segment;
        self.bytecode_values[condition_index] = try self.bytecodeValueFromSegment(program, segment, environment);
    }

    fn bytecodeAssignmentValue(self: *Runtime, operation: AssignmentOp, current: Value, right: Value) Error!Value {
        return switch (operation) {
            .assign => right,
            .add => self.addValues(current, right),
            .subtract => self.numericBinary(.subtract, current, right),
            .multiply => self.numericBinary(.multiply, current, right),
            .divide => self.numericBinary(.divide, current, right),
            .remainder => self.numericBinary(.remainder, current, right),
            .exponentiate => self.numericBinary(.exponentiate, current, right),
            .bitwise_and => self.numericBinary(.bitwise_and, current, right),
            .bitwise_xor => self.numericBinary(.bitwise_xor, current, right),
            .bitwise_or => self.numericBinary(.bitwise_or, current, right),
            .shift_left => self.numericBinary(.shift_left, current, right),
            .shift_right => self.numericBinary(.shift_right, current, right),
            .shift_unsigned => self.numericBinary(.shift_unsigned, current, right),
            .logical_and, .logical_or, .nullish => error.BytecodeInvalid,
        };
    }

    fn bytecodeLogicalAssignmentUsesRight(self: *Runtime, operation: AssignmentOp, current: Value) Error!bool {
        return switch (operation) {
            .logical_and => self.truthy(current),
            .logical_or => !self.truthy(current),
            .nullish => current.isNullish(),
            else => error.BytecodeInvalid,
        };
    }

    fn bytecodeLogicalAssignIdentifier(self: *Runtime, program: *const Program, identifier: Node, operation: AssignmentOp, right_segment: u16, environment: u16) Error!void {
        if (self.bytecode_value_count < 1) return error.BytecodeStack;
        const value_index = self.bytecode_value_count - 1;
        const current = self.bytecode_values[value_index];
        if (!try self.bytecodeLogicalAssignmentUsesRight(operation, current)) return;
        const right = try self.bytecodeValueFromSegment(program, right_segment, environment);
        try self.assignBinding(environment, program.text(identifier.text), right);
        self.bytecode_values[value_index] = right;
    }

    fn bytecodeLogicalAssignMember(self: *Runtime, program: *const Program, member: Node, operation: AssignmentOp, right_segment: u16, environment: u16) Error!void {
        if (self.bytecode_value_count < 3) return error.BytecodeStack;
        const base = self.bytecode_value_count - 3;
        const object = self.bytecode_values[base];
        const name_value = self.bytecode_values[base + 1];
        const current = self.bytecode_values[base + 2];
        var result = current;
        if (try self.bytecodeLogicalAssignmentUsesRight(operation, current)) {
            result = try self.bytecodeValueFromSegment(program, right_segment, environment);
            const name = try self.bytecodePropertyName(name_value);
            if (member.flags & flag_private != 0)
                try self.setPrivate(object, try self.classBrand(member.c, environment), name, result)
            else if (member.flags & flag_super != 0)
                try self.setSuperProperty(member, environment, object, name, result)
            else
                try self.setProperty(object, name, result);
        }
        self.bytecode_value_count = base;
        try self.bytecodePush(result);
    }

    fn bytecodeAssignIdentifier(self: *Runtime, program: *const Program, node_index: u16, operation: AssignmentOp, environment: u16) Error!void {
        if (node_index == none or node_index >= program.node_count) return error.BytecodeInvalid;
        const required: usize = if (operation == .assign) 1 else 2;
        if (self.bytecode_value_count < required) return error.BytecodeStack;
        const base = self.bytecode_value_count - required;
        const right = self.bytecode_values[self.bytecode_value_count - 1];
        const current = if (operation == .assign) Value.undefined else self.bytecode_values[base];
        const result = try self.bytecodeAssignmentValue(operation, current, right);
        try self.assignIdentifierCached(program, node_index, environment, result);
        self.bytecode_value_count = base;
        try self.bytecodePush(result);
    }

    fn bytecodePropertyName(self: *Runtime, value: Value) Error![]const u8 {
        return self.stringBytes(try self.toPropertyKey(value));
    }

    fn bytecodeLoadMemberForAssignment(self: *Runtime, program: *const Program, member: Node, environment: u16) Error!void {
        _ = program;
        if (self.bytecode_value_count < 2) return error.BytecodeStack;
        const object = self.bytecode_values[self.bytecode_value_count - 2];
        const name_value = self.bytecode_values[self.bytecode_value_count - 1];
        const name = try self.bytecodePropertyName(name_value);
        const value = if (member.flags & flag_private != 0)
            try self.getPrivate(object, try self.classBrand(member.c, environment), name)
        else if (member.flags & flag_super != 0)
            try self.getSuperProperty(member, environment, object, name)
        else
            try self.getProperty(object, name);
        try self.bytecodePush(value);
    }

    fn bytecodeAssignMember(self: *Runtime, program: *const Program, member: Node, operation: AssignmentOp, environment: u16) Error!void {
        _ = program;
        const required: usize = if (operation == .assign) 3 else 4;
        if (self.bytecode_value_count < required) return error.BytecodeStack;
        const base = self.bytecode_value_count - required;
        const object = self.bytecode_values[base];
        const name_value = self.bytecode_values[base + 1];
        const current = if (operation == .assign) Value.undefined else self.bytecode_values[base + 2];
        const right = self.bytecode_values[self.bytecode_value_count - 1];
        const result = try self.bytecodeAssignmentValue(operation, current, right);
        const name = try self.bytecodePropertyName(name_value);
        if (member.flags & flag_private != 0)
            try self.setPrivate(object, try self.classBrand(member.c, environment), name, result)
        else if (member.flags & flag_super != 0)
            try self.setSuperProperty(member, environment, object, name, result)
        else
            try self.setProperty(object, name, result);
        self.bytecode_value_count = base;
        try self.bytecodePush(result);
    }

    fn bytecodeUpdateIdentifier(self: *Runtime, program: *const Program, node_index: u16, flags: u8, environment: u16) Error!void {
        if (node_index == none or node_index >= program.node_count) return error.BytecodeInvalid;
        if (self.bytecode_value_count < 1) return error.BytecodeStack;
        const value_index = self.bytecode_value_count - 1;
        const previous = self.bytecode_values[value_index];
        const numeric = try self.toPrimitive(previous, .number);
        const next = if (numeric == .bigint)
            try self.bigIntAddSmall(numeric, if (flags & 1 != 0) 1 else -1)
        else blk: {
            const number = try self.toNumber(numeric);
            break :blk Value{ .number = if (flags & 1 != 0) number + 1 else number - 1 };
        };
        try self.assignIdentifierCached(program, node_index, environment, next);
        self.bytecode_values[value_index] = if (flags & @as(u8, @intCast(flag_prefix)) != 0) next else numeric;
    }

    fn bytecodeUpdateMember(self: *Runtime, program: *const Program, member: Node, flags: u8, environment: u16) Error!void {
        _ = program;
        if (self.bytecode_value_count < 2) return error.BytecodeStack;
        const base = self.bytecode_value_count - 2;
        const object = self.bytecode_values[base];
        const name_value = self.bytecode_values[base + 1];
        const name = try self.bytecodePropertyName(name_value);
        const brand = if (member.flags & flag_private != 0) try self.classBrand(member.c, environment) else none;
        const previous = if (brand != none)
            try self.getPrivate(object, brand, name)
        else if (member.flags & flag_super != 0)
            try self.getSuperProperty(member, environment, object, name)
        else
            try self.getProperty(object, name);
        const numeric = try self.toPrimitive(previous, .number);
        const next = if (numeric == .bigint)
            try self.bigIntAddSmall(numeric, if (flags & 1 != 0) 1 else -1)
        else blk: {
            const number = try self.toNumber(numeric);
            break :blk Value{ .number = if (flags & 1 != 0) number + 1 else number - 1 };
        };
        if (brand != none)
            try self.setPrivate(object, brand, name, next)
        else if (member.flags & flag_super != 0)
            try self.setSuperProperty(member, environment, object, name, next)
        else
            try self.setProperty(object, name, next);
        self.bytecode_value_count = base;
        try self.bytecodePush(if (flags & @as(u8, @intCast(flag_prefix)) != 0) next else numeric);
    }

    fn bytecodeDeleteMember(self: *Runtime) Error!void {
        if (self.bytecode_value_count < 2) return error.BytecodeStack;
        const base = self.bytecode_value_count - 2;
        const object = self.bytecode_values[base];
        const name = try self.bytecodePropertyName(self.bytecode_values[base + 1]);
        const deleted = try self.deleteOwnProperty(object, name);
        self.bytecode_value_count = base;
        try self.bytecodePush(.{ .boolean = deleted });
    }

    fn bytecodeDeleteIdentifier(self: *Runtime, program: *const Program, identifier: Node, environment: u16) Error!bool {
        const name = program.text(identifier.text);
        var current = environment;
        while (current != none) : (current = self.cells[current].parent) {
            const cell = &self.cells[current];
            if (!cell.object_environment or !try self.objectEnvironmentHasBinding(cell.receiver, name)) continue;
            if (cell.receiver == .cell) return self.deleteOwnProperty(cell.receiver, name);
            return true;
        }
        return true;
    }

    fn bytecodePrepareIdentifierCall(self: *Runtime, program: *const Program, identifier: Node, environment: u16) Error!void {
        const name = program.text(identifier.text);
        const binding = try self.resolveBinding(environment, name) orelse {
            self.recordDiagnostic(name);
            self.recordDiagnosticContext(program, identifier.text);
            return error.UnknownIdentifier;
        };
        const direct_eval = !binding.object and equals(name, "eval") and
            self.global("eval") != null and self.strictEqual(binding.value, self.global("eval").?);
        try self.bytecodePush(if (binding.object) binding.receiver else if (direct_eval) binding.value else .undefined);
        try self.bytecodePush(binding.value);
    }

    fn bytecodeGetMember(self: *Runtime, program: *const Program, node_index: u16, environment: u16, preserve_receiver: bool) Error!void {
        if (self.bytecode_value_count < 2 or node_index == none or node_index >= program.node_count) return error.BytecodeStack;
        const base = self.bytecode_value_count - 2;
        const object = self.bytecode_values[base];
        const name = try self.bytecodePropertyName(self.bytecode_values[base + 1]);
        self.diagnostic_program = program;
        self.diagnostic_node = node_index;
        self.diagnostic_value = object;
        self.recordDiagnostic(name);
        const member = program.nodes[node_index];
        if (member.flags & flag_computed == 0) self.recordDiagnosticContext(program, member.text);
        const value = if (member.flags & flag_private != 0)
            try self.getPrivate(object, try self.classBrand(member.c, environment), name)
        else if (member.flags & flag_super != 0)
            try self.getSuperProperty(member, environment, object, name)
        else
            try self.getProperty(object, name);
        if (preserve_receiver) {
            self.diagnostic_call_name_len = @min(name.len, self.diagnostic_call_name.len);
            if (self.diagnostic_call_name_len > 0)
                @memcpy(self.diagnostic_call_name[0..self.diagnostic_call_name_len], name[0..self.diagnostic_call_name_len]);
            self.bytecode_values[base + 1] = value;
        } else {
            self.bytecode_value_count = base;
            try self.bytecodePush(value);
        }
    }

    const NamedIdentifierMemberMode = enum { reference, value, call };

    fn bytecodeNamedIdentifierMember(self: *Runtime, program: *const Program, node_index: u16, environment: u16, mode: NamedIdentifierMemberMode) Error!void {
        if (node_index == none or node_index >= program.node_count) return error.BytecodeInvalid;
        const member = program.nodes[node_index];
        if (member.kind != .member or member.flags & (flag_computed | flag_private | flag_super) != 0 or
            member.a == none or member.a >= program.node_count or program.nodes[member.a].kind != .identifier)
            return error.BytecodeInvalid;
        const object = try self.lookupRequiredCached(program, member.a, environment);
        const name = program.text(member.text);
        self.diagnostic_program = program;
        self.diagnostic_node = node_index;
        self.diagnostic_value = object;
        self.recordDiagnostic(name);
        self.recordDiagnosticContext(program, member.text);
        if (mode == .reference) {
            try self.bytecodePush(object);
            try self.bytecodePush(.{ .string = try self.storeString(name) });
            return;
        }
        const value = try self.getProperty(object, name);
        if (mode == .call) {
            self.diagnostic_call_name_len = @min(name.len, self.diagnostic_call_name.len);
            if (self.diagnostic_call_name_len > 0)
                @memcpy(self.diagnostic_call_name[0..self.diagnostic_call_name_len], name[0..self.diagnostic_call_name_len]);
            try self.bytecodePush(object);
            try self.bytecodePush(value);
        } else {
            try self.bytecodePush(value);
        }
    }

    fn bytecodeCall(self: *Runtime, program: *const Program, node_index: u16, argument_count: u16, construct: bool) Error!void {
        const required = @as(usize, argument_count) + 2;
        if (self.bytecode_value_count < required) return error.BytecodeStack;
        const base = self.bytecode_value_count - required;
        const receiver = self.bytecode_values[base];
        const callable = self.bytecode_values[base + 1];
        self.diagnostic_program = program;
        self.diagnostic_node = node_index;
        const result = try self.call(
            program,
            callable,
            receiver,
            self.bytecode_values[base + 2 .. self.bytecode_value_count],
            construct,
        );
        self.bytecode_value_count = base;
        try self.bytecodePush(result);
    }

    fn evaluateOptionalChain(self: *Runtime, program: *const Program, chain_index: u16, environment: u16, delete_final: bool) Error!Value {
        if (chain_index == none or chain_index >= program.node_count) return error.BytecodeInvalid;
        const chain = program.nodes[chain_index];
        if (chain.kind != .optional_chain or chain.a == none or chain.b == none) return error.BytecodeInvalid;

        const root_base = self.root_count;
        defer self.root_count = root_base;
        var receiver: Value = .undefined;
        var current: Value = .undefined;
        const base = program.nodes[chain.a];
        if (base.kind == .member) {
            receiver = if (base.flags & flag_super != 0)
                try self.superReceiver(environment)
            else
                try self.bytecodeValueFromNode(program, base.a, environment);
            try self.pushRoot(receiver);
            try self.pushRoot(.undefined);
            const name = if (base.flags & flag_computed != 0)
                try self.optionalComputedPropertyName(program, base.b, environment)
            else
                program.text(base.text);
            current = if (base.flags & flag_private != 0)
                try self.getPrivate(receiver, try self.classBrand(base.c, environment), name)
            else if (base.flags & flag_super != 0)
                try self.getSuperProperty(base, environment, receiver, name)
            else
                try self.getProperty(receiver, name);
            self.roots[root_base + 1] = current;
        } else {
            if (base.kind == .identifier) {
                const name = program.text(base.text);
                const binding = try self.resolveBinding(environment, name) orelse {
                    self.recordDiagnostic(name);
                    self.recordDiagnosticContext(program, base.text);
                    return error.UnknownIdentifier;
                };
                current = binding.value;
                if (binding.object) receiver = binding.receiver;
            } else {
                current = try self.bytecodeValueFromNode(program, chain.a, environment);
            }
            try self.pushRoot(receiver);
            try self.pushRoot(current);
        }

        var step_index = chain.b;
        while (step_index != none) {
            const step = program.nodes[step_index];
            const final_step = step.next == none;
            switch (step.kind) {
                .chain_member => {
                    if (step.flags & flag_optional != 0 and current.isNullish()) return if (delete_final) .{ .boolean = true } else .undefined;
                    const name = if (step.flags & flag_computed != 0)
                        try self.optionalComputedPropertyName(program, step.a, environment)
                    else
                        program.text(step.text);
                    if (delete_final and final_step) return .{ .boolean = try self.deleteOwnProperty(current, name) };
                    receiver = current;
                    self.roots[root_base] = receiver;
                    current = if (step.flags & flag_private != 0)
                        try self.getPrivate(receiver, try self.classBrand(step.c, environment), name)
                    else
                        try self.getProperty(receiver, name);
                    self.roots[root_base + 1] = current;
                },
                .chain_call => {
                    if (step.flags & flag_optional != 0 and current.isNullish()) return if (delete_final) .{ .boolean = true } else .undefined;
                    var arguments: [max_parameters]Value = undefined;
                    var argument_count: usize = 0;
                    const argument_root_base = self.root_count;
                    var argument = step.a;
                    while (argument != none) : (argument = program.nodes[argument].next) {
                        const argument_node = program.nodes[argument];
                        if (argument_node.kind == .spread_element) {
                            const spread_argument_start = argument_count;
                            const spread_root_base = self.root_count;
                            const spread = try self.bytecodeValueFromNode(program, argument_node.a, environment);
                            try self.pushRoot(spread);
                            var cursor = try self.openIterator(program, spread);
                            try self.rootIterator(cursor);
                            errdefer self.iteratorClose(program, &cursor) catch {};
                            while (true) {
                                const iterator_step = try self.iteratorNext(program, &cursor);
                                if (iterator_step.done) break;
                                if (argument_count >= arguments.len) return error.RangeError;
                                arguments[argument_count] = iterator_step.value;
                                try self.pushRoot(arguments[argument_count]);
                                argument_count += 1;
                            }
                            self.root_count = spread_root_base;
                            for (arguments[spread_argument_start..argument_count]) |spread_argument| try self.pushRoot(spread_argument);
                        } else {
                            if (argument_count >= arguments.len) return error.RangeError;
                            arguments[argument_count] = try self.bytecodeValueFromNode(program, argument, environment);
                            try self.pushRoot(arguments[argument_count]);
                            argument_count += 1;
                        }
                    }
                    current = try self.call(program, current, receiver, arguments[0..argument_count], false);
                    self.root_count = argument_root_base;
                    receiver = .undefined;
                    self.roots[root_base] = receiver;
                    self.roots[root_base + 1] = current;
                    if (delete_final and final_step) return .{ .boolean = true };
                },
                else => return error.BytecodeInvalid,
            }
            step_index = step.next;
        }
        return current;
    }

    fn optionalComputedPropertyName(self: *Runtime, program: *const Program, expression: u16, environment: u16) Error![]const u8 {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        const property = try self.bytecodeValueFromNode(program, expression, environment);
        try self.pushRoot(property);
        return self.stringBytes(try self.toPropertyKey(property));
    }

    fn executeBytecodeIf(self: *Runtime, program: *const Program, node: Node, environment: u16) Error!Completion {
        if (try self.executeNumericIfDispatch(program, node, environment)) |completion| return completion;
        if (self.numericLexicalCondition(program, node.a, environment)) |condition| {
            const branch = if (condition) node.b else node.c;
            return self.executeBytecodeStatementFast(program, branch, environment);
        }
        const condition = try self.bytecodeValueFromNode(program, node.a, environment);
        return self.executeBytecodeStatementFast(program, if (self.truthy(condition)) node.b else node.c, environment);
    }

    fn blockNeedsEnvironment(program: *const Program, node_index: u16) bool {
        if (node_index == none or node_index >= program.node_count) return true;
        const block = program.nodes[node_index];
        if (block.kind != .block) return true;
        var current = block.a;
        while (current != none) : (current = program.nodes[current].next) {
            if (statementDeclaresLexical(program, current)) return true;
        }
        return false;
    }

    fn statementDeclaresLexical(program: *const Program, node_index: u16) bool {
        if (node_index == none or node_index >= program.node_count) return true;
        const statement = program.nodes[node_index];
        if (statement.kind == .block and statement.flags & flag_declaration_list != 0) {
            var declaration = statement.a;
            while (declaration != none) : (declaration = program.nodes[declaration].next)
                if (statementDeclaresLexical(program, declaration)) return true;
            return false;
        }
        if (statement.kind == .function_declaration or statement.kind == .class_declaration) return true;
        return statement.kind == .variable and statement.flags & flag_var == 0;
    }

    const NumericIfCase = struct {
        name: StringRef,
        number: f64,
        branch: u16,
        alternate: u16,
    };

    fn numericIfCase(program: *const Program, node: Node) ?NumericIfCase {
        if (node.kind != .if_statement or node.a == none or node.a >= program.node_count) return null;
        const condition = program.nodes[node.a];
        if (condition.kind != .binary) return null;
        const operation: BinaryOp = @enumFromInt(condition.flags);
        if (operation != .equal and operation != .strict_equal) return null;
        if (condition.a == none or condition.a >= program.node_count or condition.b == none or condition.b >= program.node_count) return null;
        const left = program.nodes[condition.a];
        const right = program.nodes[condition.b];
        if (left.kind == .identifier and right.kind == .number_literal) return .{
            .name = left.text,
            .number = right.number,
            .branch = node.b,
            .alternate = node.c,
        };
        if (right.kind == .identifier and left.kind == .number_literal) return .{
            .name = right.text,
            .number = left.number,
            .branch = node.b,
            .alternate = node.c,
        };
        return null;
    }

    fn lexicalNumberWithoutObjectEnvironment(self: *Runtime, environment: u16, name: []const u8) ?f64 {
        var current = environment;
        while (current != none) {
            const cell = &self.cells[current];
            if (cell.object_environment) return null;
            for (self.bindingStorageConst(current)[0..cell.binding_count]) |binding| {
                if (!equals(self.stringBytes(binding.name), name)) continue;
                const value = self.bindingValue(binding) orelse return null;
                return if (value == .number) value.number else null;
            }
            current = cell.parent;
        }
        return null;
    }

    fn numericLexicalCondition(self: *Runtime, program: *const Program, node_index: u16, environment: u16) ?bool {
        if (node_index == none or node_index >= program.node_count) return null;
        const condition = program.nodes[node_index];
        if (condition.kind != .binary or condition.a == none or condition.a >= program.node_count or condition.b == none or condition.b >= program.node_count)
            return null;
        const left = program.nodes[condition.a];
        const right = program.nodes[condition.b];
        if (left.kind != .identifier and right.kind != .identifier) return null;
        const left_value = switch (left.kind) {
            .identifier => self.lexicalNumberWithoutObjectEnvironment(environment, program.text(left.text)) orelse return null,
            .number_literal => left.number,
            else => return null,
        };
        const right_value = switch (right.kind) {
            .identifier => self.lexicalNumberWithoutObjectEnvironment(environment, program.text(right.text)) orelse return null,
            .number_literal => right.number,
            else => return null,
        };
        const operation: BinaryOp = @enumFromInt(condition.flags);
        return switch (operation) {
            .equal, .strict_equal => left_value == right_value,
            .not_equal, .strict_not_equal => left_value != right_value,
            .less => left_value < right_value,
            .less_equal => left_value <= right_value,
            .greater => left_value > right_value,
            .greater_equal => left_value >= right_value,
            else => null,
        };
    }

    fn numericExpressionValue(self: *Runtime, program: *const Program, node_index: u16, environment: u16) Error!?Value {
        if (node_index == none or node_index >= program.node_count) return null;
        const node = program.nodes[node_index];
        return switch (node.kind) {
            .number_literal => Value{ .number = node.number },
            .string_literal => Value{ .string = try self.decodeString(program, node.text) },
            .boolean_literal => Value{ .boolean = node.flags & 1 != 0 },
            .null_literal => Value.null_value,
            .undefined_literal => Value.undefined,
            .identifier => try self.lookupRequiredCached(program, node_index, environment),
            .this_expression => try self.thisValue(environment),
            .unary => blk: {
                const operation: UnaryOp = @enumFromInt(node.flags);
                if (operation == .type_of and node.a != none and node.a < program.node_count and program.nodes[node.a].kind == .identifier) {
                    const binding = try self.resolveBinding(environment, program.text(program.nodes[node.a].text));
                    break :blk Value{ .string = try self.storeString(if (binding) |present| self.typeName(present.value) else "undefined") };
                }
                const value = (try self.numericExpressionValue(program, node.a, environment)) orelse break :blk null;
                const root_base = self.root_count;
                defer self.root_count = root_base;
                try self.pushRoot(value);
                break :blk switch (operation) {
                    .positive => Value{ .number = try self.toNumber(value) },
                    .negative => Value{ .number = -(try self.toNumber(value)) },
                    .logical_not => Value{ .boolean = !self.truthy(value) },
                    .bitwise_not => Value{ .number = @floatFromInt(~toInt32(try self.toNumber(value))) },
                    .type_of => Value{ .string = try self.storeString(self.typeName(value)) },
                    .void_value => Value.undefined,
                    .delete_value => null,
                };
            },
            .binary => blk: {
                const operation: BinaryOp = @enumFromInt(node.flags);
                const left = (try self.numericExpressionValue(program, node.a, environment)) orelse break :blk null;
                const root_base = self.root_count;
                defer self.root_count = root_base;
                try self.pushRoot(left);
                const use_right = switch (operation) {
                    .logical_and => self.truthy(left),
                    .logical_or => !self.truthy(left),
                    .nullish => left.isNullish(),
                    else => true,
                };
                if (!use_right) break :blk left;
                const right = (try self.numericExpressionValue(program, node.b, environment)) orelse break :blk null;
                try self.pushRoot(right);
                break :blk try self.bytecodeBinaryValue(operation, left, right);
            },
            .assignment => try self.primitiveAssignmentValue(program, node_index, environment),
            .update => try self.primitiveUpdateValue(program, node_index, environment),
            .call => try self.numericCallValue(program, node_index, environment),
            .member => blk: {
                if (node.flags & (flag_private | flag_super) != 0) break :blk null;
                const object = (try self.numericExpressionValue(program, node.a, environment)) orelse break :blk null;
                const root_base = self.root_count;
                defer self.root_count = root_base;
                try self.pushRoot(object);
                if (node.flags & flag_computed == 0) break :blk try self.getProperty(object, program.text(node.text));
                const property = (try self.numericExpressionValue(program, node.b, environment)) orelse break :blk null;
                try self.pushRoot(property);
                const property_key = try self.toPropertyKey(property);
                break :blk try self.getProperty(object, self.stringBytes(property_key));
            },
            else => null,
        };
    }

    fn numericCallValue(self: *Runtime, program: *const Program, node_index: u16, environment: u16) Error!?Value {
        if (node_index == none or node_index >= program.node_count) return null;
        const call_node = program.nodes[node_index];
        if (call_node.kind != .call or call_node.a == none or call_node.a >= program.node_count) return null;
        const callee = program.nodes[call_node.a];
        const root_base = self.root_count;
        defer self.root_count = root_base;
        var receiver: Value = .undefined;
        var callable: Value = .undefined;
        switch (callee.kind) {
            .identifier => {
                const name = program.text(callee.text);
                if (equals(name, "eval")) return null;
                const binding = try self.resolveBinding(environment, name) orelse {
                    self.recordDiagnostic(name);
                    self.recordDiagnosticContext(program, callee.text);
                    return error.UnknownIdentifier;
                };
                receiver = if (binding.object) binding.receiver else .undefined;
                callable = binding.value;
            },
            .member => {
                if (callee.flags & (flag_private | flag_super) != 0) return null;
                receiver = (try self.numericExpressionValue(program, callee.a, environment)) orelse return null;
                try self.pushRoot(receiver);
                if (callee.flags & flag_computed != 0) {
                    const property = (try self.numericExpressionValue(program, callee.b, environment)) orelse return null;
                    try self.pushRoot(property);
                    const property_key = try self.toPropertyKey(property);
                    callable = try self.getProperty(receiver, self.stringBytes(property_key));
                } else {
                    callable = try self.getProperty(receiver, program.text(callee.text));
                }
            },
            else => return null,
        }
        try self.pushRoot(receiver);
        try self.pushRoot(callable);
        var arguments: [max_fused_expression_nodes]Value = undefined;
        var argument_count: usize = 0;
        var argument = call_node.b;
        while (argument != none) : (argument = program.nodes[argument].next) {
            if (argument_count >= arguments.len or argument >= program.node_count or program.nodes[argument].kind == .spread_element)
                return null;
            arguments[argument_count] = (try self.numericExpressionValue(program, argument, environment)) orelse return null;
            try self.pushRoot(arguments[argument_count]);
            argument_count += 1;
        }
        return try self.call(program, callable, receiver, arguments[0..argument_count], false);
    }

    fn primitiveAssignmentValue(self: *Runtime, program: *const Program, node_index: u16, environment: u16) Error!?Value {
        if (node_index == none or node_index >= program.node_count) return null;
        const assignment = program.nodes[node_index];
        if (assignment.kind != .assignment or assignment.a == none or assignment.a >= program.node_count) return null;
        const target = program.nodes[assignment.a];
        const operation: AssignmentOp = @enumFromInt(assignment.flags);
        if (isLogicalAssignment(operation)) return null;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        switch (target.kind) {
            .identifier => {
                const current = if (operation == .assign)
                    Value.undefined
                else
                    try self.lookupRequiredCached(program, assignment.a, environment);
                try self.pushRoot(current);
                const right = (try self.numericExpressionValue(program, assignment.b, environment)) orelse return null;
                try self.pushRoot(right);
                const result = try self.bytecodeAssignmentValue(operation, current, right);
                try self.assignIdentifierCached(program, assignment.a, environment, result);
                return result;
            },
            .member => {
                if (target.flags & (flag_private | flag_super) != 0) return null;
                const object = (try self.numericExpressionValue(program, target.a, environment)) orelse return null;
                try self.pushRoot(object);
                var property_key: StringRef = .{};
                if (target.flags & flag_computed != 0) {
                    const property = (try self.numericExpressionValue(program, target.b, environment)) orelse return null;
                    try self.pushRoot(property);
                    property_key = try self.toPropertyKey(property);
                }
                const current = if (operation == .assign)
                    Value.undefined
                else if (target.flags & flag_computed != 0)
                    try self.getProperty(object, self.stringBytes(property_key))
                else
                    try self.getProperty(object, program.text(target.text));
                try self.pushRoot(current);
                const right = (try self.numericExpressionValue(program, assignment.b, environment)) orelse return null;
                try self.pushRoot(right);
                const result = try self.bytecodeAssignmentValue(operation, current, right);
                try self.setProperty(
                    object,
                    if (target.flags & flag_computed != 0) self.stringBytes(property_key) else program.text(target.text),
                    result,
                );
                return result;
            },
            else => return null,
        }
    }

    fn primitiveUpdateValue(self: *Runtime, program: *const Program, node_index: u16, environment: u16) Error!?Value {
        if (node_index == none or node_index >= program.node_count) return null;
        const update = program.nodes[node_index];
        if (update.kind != .update or update.a == none or update.a >= program.node_count) return null;
        const target = program.nodes[update.a];
        const root_base = self.root_count;
        defer self.root_count = root_base;
        var object: Value = .undefined;
        var property_key: StringRef = .{};
        const previous = switch (target.kind) {
            .identifier => try self.lookupRequiredCached(program, update.a, environment),
            .member => previous: {
                if (target.flags & (flag_private | flag_super) != 0) return null;
                object = (try self.numericExpressionValue(program, target.a, environment)) orelse return null;
                try self.pushRoot(object);
                if (target.flags & flag_computed != 0) {
                    const property = (try self.numericExpressionValue(program, target.b, environment)) orelse return null;
                    try self.pushRoot(property);
                    property_key = try self.toPropertyKey(property);
                }
                break :previous try self.getProperty(
                    object,
                    if (target.flags & flag_computed != 0) self.stringBytes(property_key) else program.text(target.text),
                );
            },
            else => return null,
        };
        try self.pushRoot(previous);
        const numeric = try self.toPrimitive(previous, .number);
        try self.pushRoot(numeric);
        const next = if (numeric == .bigint)
            try self.bigIntAddSmall(numeric, if (update.flags & 1 != 0) 1 else -1)
        else blk: {
            const number = try self.toNumber(numeric);
            break :blk Value{ .number = if (update.flags & 1 != 0) number + 1 else number - 1 };
        };
        if (target.kind == .identifier)
            try self.assignIdentifierCached(program, update.a, environment, next)
        else
            try self.setProperty(
                object,
                if (target.flags & flag_computed != 0) self.stringBytes(property_key) else program.text(target.text),
                next,
            );
        return if (update.flags & flag_prefix != 0) next else numeric;
    }

    fn primitiveConditionalValue(self: *Runtime, program: *const Program, node_index: u16, environment: u16) Error!?Value {
        if (node_index == none or node_index >= program.node_count) return null;
        var current = node_index;
        var first = true;
        while (current != none and current < program.node_count and program.nodes[current].kind == .conditional) {
            const node = program.nodes[current];
            const condition = (try self.numericExpressionValue(program, node.a, environment)) orelse {
                if (first) return null;
                return try self.bytecodeValueFromNode(program, current, environment);
            };
            current = if (self.truthy(condition)) node.b else node.c;
            first = false;
        }
        if (current == none or current >= program.node_count) return error.BytecodeInvalid;
        if (program.nodes[current].kind == .assignment)
            if (try self.primitiveAssignmentValue(program, current, environment)) |value| return value;
        return try self.bytecodeValueFromNode(program, current, environment);
    }

    fn primitiveIdentifierValue(self: *Runtime, program: *const Program, node_index: u16, environment: u16) Error!?Value {
        const ref = program.nodes[node_index].text;
        const name = program.text(ref);
        const slot = self.identifierCacheSlot(program, node_index);
        if (self.cachedIdentifierValue(slot, program, node_index, environment, name)) |value| {
            self.stats.identifier_cache_hits += 1;
            return switch (value) {
                .undefined, .null_value, .boolean, .number, .string => value,
                else => null,
            };
        }

        self.stats.identifier_cache_misses += 1;
        var current = environment;
        var depth: usize = 0;
        while (current != none) {
            const cell = &self.cells[current];
            if (cell.object_environment) return null;
            for (self.bindingStorageConst(current)[0..cell.binding_count], 0..) |binding, binding_index| {
                if (!equals(self.stringBytes(binding.name), name)) continue;
                self.cacheIdentifierBinding(slot, program, node_index, environment, current, depth, binding_index);
                const value = self.bindingValue(binding) orelse Value.undefined;
                return switch (value) {
                    .undefined, .null_value, .boolean, .number, .string => value,
                    else => null,
                };
            }
            current = cell.parent;
            depth += 1;
        }
        self.recordDiagnostic(name);
        self.recordDiagnosticContext(program, ref);
        return error.UnknownIdentifier;
    }

    fn evaluateBytecodeLoopCondition(self: *Runtime, program: *const Program, node_index: u16, environment: u16) Error!bool {
        if (self.numericLexicalCondition(program, node_index, environment)) |condition| {
            self.diagnostic_program = program;
            self.diagnostic_node = node_index;
            self.diagnostic_opcode = .binary;
            try self.checkpoint();
            self.stats.bytecode_instructions += 1;
            return condition;
        }
        return self.truthy(try self.bytecodeValueFromNode(program, node_index, environment));
    }

    fn executeNumericIfDispatch(self: *Runtime, program: *const Program, node: Node, environment: u16) Error!?Completion {
        const first = numericIfCase(program, node) orelse return null;
        const state = self.lexicalNumberWithoutObjectEnvironment(environment, program.text(first.name)) orelse return null;

        var current = first;
        while (true) {
            if (state == current.number) {
                return try self.executeBytecodeStatementFast(program, current.branch, environment);
            }
            if (current.alternate == none) return Completion{};
            if (current.alternate >= program.node_count) return error.BytecodeInvalid;
            const alternate = program.nodes[current.alternate];
            const next = numericIfCase(program, alternate) orelse
                return try self.executeBytecodeStatementFast(program, current.alternate, environment);
            if (!equals(program.text(first.name), program.text(next.name)))
                return try self.executeBytecodeStatementFast(program, current.alternate, environment);
            current = next;
        }
    }

    fn executeBytecodeStatementFast(self: *Runtime, program: *const Program, node_index: u16, environment: u16) Error!Completion {
        if (node_index == none) return .{};
        if (node_index >= program.node_count) return error.BytecodeInvalid;
        const node = program.nodes[node_index];
        if (node.kind == .block and !blockNeedsEnvironment(program, node_index)) {
            var current = node.a;
            var completion = Completion{};
            while (current != none) : (current = program.nodes[current].next) {
                completion = try self.executeBytecodeStatementFast(program, current, environment);
                if (completion.kind != .normal) return completion;
            }
            return completion;
        }
        if (node.kind == .if_statement) return self.executeBytecodeIf(program, node, environment);
        if (try self.executePrimitiveStatement(program, node_index, environment)) |completion| return completion;
        return self.executeBytecodeNode(program, node_index, environment);
    }

    fn executePrimitiveStatement(self: *Runtime, program: *const Program, node_index: u16, environment: u16) Error!?Completion {
        if (node_index == none or node_index >= program.node_count) return null;
        const node = program.nodes[node_index];
        if (node.kind != .expression_statement or node.a == none or node.a >= program.node_count) return null;
        const expression = program.nodes[node.a];
        const value = switch (expression.kind) {
            .assignment => (try self.primitiveAssignmentValue(program, node.a, environment)) orelse return null,
            .conditional => (try self.primitiveConditionalValue(program, node.a, environment)) orelse return null,
            else => return null,
        };
        return Completion{ .value = value };
    }

    fn executeBytecodeWith(self: *Runtime, program: *const Program, node: Node, parent: u16) Error!Completion {
        const object = try self.bytecodeValueFromNode(program, node.a, parent);
        if (object == .undefined or object == .null_value) return error.TypeError;
        if (object == .cell) _ = try self.expectObject(object);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(object);
        const environment = try self.allocateCell(.environment);
        self.cells[environment].parent = parent;
        self.cells[environment].object_environment = true;
        self.cells[environment].receiver = object;
        return self.executeBytecodeNode(program, node.b, environment);
    }

    fn completionTargetsLoop(program: *const Program, node: Node, completion: Completion) bool {
        if (completion.label.len == 0) return true;
        if (node.source.len != iteration_label_source_marker) return false;
        var current: u16 = @intCast(node.source.offset);
        while (current != none) : (current = program.nodes[current].next) {
            if (equals(program.text(program.nodes[current].text), program.text(completion.label))) return true;
        }
        return false;
    }

    fn executeBytecodeWhile(self: *Runtime, program: *const Program, node: Node, environment: u16, post_test: bool) Error!Completion {
        var first = true;
        while (post_test and first or try self.evaluateBytecodeLoopCondition(program, node.a, environment)) {
            if (post_test and first) {
                try self.checkpoint();
                self.stats.bytecode_instructions += 1;
            }
            first = false;
            const completion = try self.executeBytecodeLoopBody(program, node.b, environment);
            switch (completion.kind) {
                .normal => {},
                .continue_loop => if (!completionTargetsLoop(program, node, completion)) return completion,
                .break_loop => if (completionTargetsLoop(program, node, completion)) return .{} else return completion,
                else => return completion,
            }
            if (post_test and !(try self.evaluateBytecodeLoopCondition(program, node.a, environment))) break;
        }
        return .{};
    }

    fn executeBytecodeFor(self: *Runtime, program: *const Program, node: Node, parent: u16) Error!Completion {
        var environment = parent;
        if (node.a != none and statementDeclaresLexical(program, node.a)) {
            environment = try self.allocateCell(.environment);
            self.cells[environment].parent = parent;
        }
        if (node.a != none) {
            const completion = try self.executeBytecodeNode(program, node.a, environment);
            if (completion.kind != .normal) return completion;
        }
        while (node.b == none or try self.evaluateBytecodeLoopCondition(program, node.b, environment)) {
            if (node.b == none) {
                try self.checkpoint();
                self.stats.bytecode_instructions += 1;
            }
            const completion = try self.executeBytecodeLoopBody(program, node.d, environment);
            switch (completion.kind) {
                .normal => {},
                .continue_loop => if (!completionTargetsLoop(program, node, completion)) return completion,
                .break_loop => if (completionTargetsLoop(program, node, completion)) return .{} else return completion,
                else => return completion,
            }
            if (node.c != none) _ = try self.bytecodeValueFromNode(program, node.c, environment);
        }
        return .{};
    }

    fn executeBytecodeLoopBody(self: *Runtime, program: *const Program, node_index: u16, environment: u16) Error!Completion {
        return self.executeBytecodeStatementFast(program, node_index, environment);
    }

    fn bytecodeAssignForInTarget(self: *Runtime, program: *const Program, target_index: u16, environment: u16, value: Value) Error!void {
        const target = program.nodes[target_index];
        switch (target.kind) {
            .variable => try self.applyPattern(program, target.b, value, environment, .{}),
            .identifier => try self.assignBinding(environment, program.text(target.text), value),
            .array_pattern, .object_pattern => try self.applyPattern(program, target_index, value, environment, .{}),
            .member => {
                const object = if (target.flags & flag_super != 0)
                    try self.superReceiver(environment)
                else
                    try self.bytecodeValueFromNode(program, target.a, environment);
                const name_value = if (target.flags & flag_computed != 0)
                    try self.bytecodeValueFromNode(program, target.b, environment)
                else
                    Value{ .string = try self.storeString(program.text(target.text)) };
                const name = try self.bytecodePropertyName(name_value);
                if (target.flags & flag_private != 0)
                    try self.setPrivate(object, try self.classBrand(target.c, environment), name, value)
                else if (target.flags & flag_super != 0)
                    try self.setSuperProperty(target, environment, object, name, value)
                else
                    try self.setProperty(object, name, value);
            },
            else => return error.InvalidAssignment,
        }
    }

    fn declarePatternNames(self: *Runtime, program: *const Program, index: u16, environment: u16) Error!void {
        if (index == none or index >= program.node_count) return error.BytecodeInvalid;
        const pattern = program.nodes[index];
        if (pattern.kind == .identifier) {
            const name = program.text(pattern.text);
            if (self.lookupOwn(environment, name) == null) try self.defineBinding(environment, name, .undefined, false);
            return;
        }
        if (!isPatternKind(pattern.kind)) return error.BytecodeInvalid;
        var current = pattern.a;
        while (current != none) : (current = program.nodes[current].next) {
            const element = program.nodes[current];
            if (element.kind != .pattern_element) return error.BytecodeInvalid;
            if (element.a != none) try self.declarePatternNames(program, element.a, environment);
        }
    }

    fn executeBytecodeForIn(self: *Runtime, program: *const Program, node: Node, parent: u16) Error!Completion {
        const environment = try self.allocateCell(.environment);
        self.cells[environment].parent = parent;
        const target = program.nodes[node.a];
        if (target.kind == .variable) try self.declarePatternNames(program, target.b, environment);
        const iterable = try self.bytecodeValueFromNode(program, node.b, environment);
        const cell_index = try self.expectObject(iterable);
        var item_index: usize = 0;
        if (self.cells[cell_index].kind == .array) {
            while (item_index < self.cells[cell_index].item_count) : (item_index += 1) {
                var buffer: [20]u8 = undefined;
                const key_text = std.fmt.bufPrint(buffer[0..], "{d}", .{item_index}) catch return error.StringLimit;
                try self.bytecodeAssignForInTarget(program, node.a, environment, .{ .string = try self.storeString(key_text) });
                const completion = try self.executeBytecodeNode(program, node.c, environment);
                switch (completion.kind) {
                    .normal => {},
                    .continue_loop => if (!completionTargetsLoop(program, node, completion)) return completion,
                    .break_loop => if (completionTargetsLoop(program, node, completion)) return .{} else return completion,
                    else => return completion,
                }
            }
        }
        item_index = 0;
        while (item_index < self.cells[cell_index].property_count) : (item_index += 1) {
            const key = Value{ .string = self.propertyStorageConst(cell_index)[item_index].key };
            try self.bytecodeAssignForInTarget(program, node.a, environment, key);
            const completion = try self.executeBytecodeNode(program, node.c, environment);
            switch (completion.kind) {
                .normal => {},
                .continue_loop => if (!completionTargetsLoop(program, node, completion)) return completion,
                .break_loop => if (completionTargetsLoop(program, node, completion)) return .{} else return completion,
                else => return completion,
            }
        }
        return .{};
    }

    fn executeBytecodeForOf(self: *Runtime, program: *const Program, node: Node, parent: u16) Error!Completion {
        const iterable = try self.bytecodeValueFromNode(program, node.b, parent);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(iterable);
        var cursor = try self.openIterator(program, iterable);
        try self.rootIterator(cursor);
        errdefer self.iteratorClose(program, &cursor) catch {};
        const target = program.nodes[node.a];
        while (true) {
            const step = try self.iteratorNext(program, &cursor);
            if (step.done) return .{};
            const iteration_root = self.root_count;
            defer self.root_count = iteration_root;
            try self.pushRoot(step.value);
            var iteration_environment = parent;
            if (target.kind == .variable) {
                if (target.flags & flag_var != 0) {
                    try self.applyPattern(program, target.b, step.value, parent, .{});
                } else {
                    iteration_environment = try self.allocateCell(.environment);
                    self.cells[iteration_environment].parent = parent;
                    try self.pushRoot(.{ .cell = iteration_environment });
                    try self.applyPattern(program, target.b, step.value, iteration_environment, .{
                        .binding = true,
                        .constant = target.flags & flag_const != 0,
                    });
                }
            } else {
                try self.bytecodeAssignForInTarget(program, node.a, parent, step.value);
            }
            const completion = try self.executeBytecodeNode(program, node.c, iteration_environment);
            switch (completion.kind) {
                .normal => {},
                .continue_loop => if (!completionTargetsLoop(program, node, completion)) {
                    try self.iteratorClose(program, &cursor);
                    return completion;
                },
                .break_loop => {
                    if (!completionTargetsLoop(program, node, completion)) {
                        try self.iteratorClose(program, &cursor);
                        return completion;
                    }
                    try self.iteratorClose(program, &cursor);
                    return .{};
                },
                .thrown => {
                    self.iteratorClose(program, &cursor) catch {};
                    return completion;
                },
                else => {
                    try self.iteratorClose(program, &cursor);
                    return completion;
                },
            }
        }
    }

    fn executeBytecodeForAwaitOf(self: *Runtime, program: *const Program, node: Node, parent: u16) Error!Completion {
        const iterable = try self.bytecodeValueFromNode(program, node.b, parent);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(iterable);
        var cursor = try self.openAsyncIterator(program, iterable);
        try self.rootAsyncIterator(cursor);
        errdefer self.asyncIteratorClose(program, &cursor) catch {};
        const target = program.nodes[node.a];
        while (true) {
            const step = try self.asyncIteratorNext(program, &cursor, .undefined, false);
            if (step.done) return .{};
            const iteration_root = self.root_count;
            defer self.root_count = iteration_root;
            try self.pushRoot(step.value);
            var iteration_environment = parent;
            if (target.kind == .variable) {
                if (target.flags & flag_var != 0) {
                    try self.applyPattern(program, target.b, step.value, parent, .{});
                } else {
                    iteration_environment = try self.allocateCell(.environment);
                    self.cells[iteration_environment].parent = parent;
                    try self.pushRoot(.{ .cell = iteration_environment });
                    try self.applyPattern(program, target.b, step.value, iteration_environment, .{
                        .binding = true,
                        .constant = target.flags & flag_const != 0,
                    });
                }
            } else {
                try self.bytecodeAssignForInTarget(program, node.a, parent, step.value);
            }
            const completion = try self.executeBytecodeNode(program, node.c, iteration_environment);
            switch (completion.kind) {
                .normal => {},
                .continue_loop => if (!completionTargetsLoop(program, node, completion)) {
                    try self.asyncIteratorClose(program, &cursor);
                    return completion;
                },
                .break_loop => {
                    if (!completionTargetsLoop(program, node, completion)) {
                        try self.asyncIteratorClose(program, &cursor);
                        return completion;
                    }
                    try self.asyncIteratorClose(program, &cursor);
                    return .{};
                },
                .thrown => {
                    self.asyncIteratorClose(program, &cursor) catch {};
                    return completion;
                },
                else => {
                    try self.asyncIteratorClose(program, &cursor);
                    return completion;
                },
            }
        }
    }

    fn executeBytecodeSwitch(self: *Runtime, program: *const Program, node: Node, environment: u16) Error!Completion {
        const discriminant = try self.bytecodeValueFromNode(program, node.a, environment);
        var current = node.b;
        var default_case: u16 = none;
        var start_case: u16 = none;
        while (current != none) : (current = program.nodes[current].next) {
            const case_node = program.nodes[current];
            if (case_node.a == none) {
                if (default_case == none) default_case = current;
            } else if (self.strictEqual(discriminant, try self.bytecodeValueFromNode(program, case_node.a, environment))) {
                start_case = current;
                break;
            }
        }
        if (start_case == none) start_case = default_case;
        current = start_case;
        while (current != none) : (current = program.nodes[current].next) {
            const completion = try self.executeBytecodeNode(program, current, environment);
            if (completion.kind == .break_loop and completion.label.len == 0) return .{};
            if (completion.kind != .normal) return completion;
        }
        return .{};
    }

    fn executeBytecodeTry(self: *Runtime, program: *const Program, node: Node, environment: u16) Error!Completion {
        var completion = self.executeBytecodeNode(program, node.a, environment) catch |err| blk: {
            if (err == error.GeneratorReturn) break :blk Completion{ .kind = .returned, .value = self.pending_generator_return };
            if (!isCatchableRuntimeError(err)) return err;
            break :blk Completion{ .kind = .thrown, .value = try self.runtimeErrorValue(err) };
        };
        if (completion.kind == .thrown and node.b != none) {
            const catch_environment = try self.allocateCell(.environment);
            self.cells[catch_environment].parent = environment;
            if (node.d != none) try self.applyPattern(program, node.d, completion.value, catch_environment, .{ .binding = true });
            completion = try self.executeBytecodeNode(program, node.b, catch_environment);
        }
        if (node.c != none) {
            const final_completion = try self.executeBytecodeNode(program, node.c, environment);
            if (final_completion.kind != .normal) return final_completion;
        }
        return completion;
    }

    fn executeBytecodeImport(self: *Runtime, program: *const Program, node: Node, environment: u16) Error!Value {
        const module_name = try self.decodeSourceString(program, node.text);
        const module_index = self.resolveModuleIndex(self.active_module, module_name) orelse return error.ModuleNotFound;
        const exports = try self.evaluateModuleIndex(module_index);
        var current = node.a;
        while (current != none) : (current = program.nodes[current].next) {
            const binding = program.nodes[current];
            const local = program.nodes[binding.a];
            if (binding.flags & flag_module_namespace != 0) {
                try self.defineBinding(environment, program.text(local.text), exports, true);
            } else {
                const imported_name = if (binding.flags & flag_module_default != 0) "default" else program.text(binding.text);
                if (self.modules[module_index].state == .evaluated and !self.moduleHasExport(@intCast(module_index), imported_name)) return error.SyntaxError;
                try self.defineImportedBinding(environment, program.text(local.text), @intCast(module_index), imported_name);
            }
        }
        return exports;
    }

    fn executeBytecodeExport(self: *Runtime, program: *const Program, node: Node, _: u16) Error!Value {
        if (self.active_exports == none) return .undefined;
        var source_module: u16 = none;
        if (node.text.len != 0) {
            const source_name = try self.decodeSourceString(program, node.text);
            const source_index = self.resolveModuleIndex(self.active_module, source_name) orelse return error.ModuleNotFound;
            _ = try self.evaluateModuleIndex(source_index);
            source_module = @intCast(source_index);
        }
        if (node.flags & flag_module_star != 0) {
            if (source_module == none) return error.SyntaxError;
            const source = &self.modules[source_module];
            for (source.export_entries[0..source.export_count]) |entry| {
                const exported_name = self.stringBytes(entry.name);
                if (equals(exported_name, "default")) continue;
                if (entry.kind != .ambiguous)
                    try self.registerModuleExport(exported_name, exported_name, source_module, .indirect, false);
            }
        }
        var current = node.a;
        while (current != none) : (current = program.nodes[current].next) {
            const entry = program.nodes[current];
            const exported_name = if (entry.flags & flag_module_export_default != 0) "default" else program.text(entry.text);
            if (entry.flags & flag_module_namespace != 0) {
                if (source_module == none) return error.SyntaxError;
                try self.registerModuleExport(exported_name, exported_name, source_module, .namespace, true);
            } else {
                const local = program.nodes[entry.a];
                const local_name = if (entry.flags & flag_module_default != 0) "default" else program.text(local.text);
                if (source_module != none and self.modules[source_module].state == .evaluated and !self.moduleHasExport(source_module, local_name)) return error.SyntaxError;
                try self.registerModuleExport(exported_name, local_name, source_module, if (source_module == none) .local else .indirect, true);
            }
        }
        return .{ .cell = self.active_exports };
    }

    fn executeBytecodeExportDefault(self: *Runtime, value: Value, environment: u16) Error!Value {
        const binding_name = "\x00R4JS.defaultExport";
        if (self.lookupOwn(environment, binding_name) == null)
            try self.defineBinding(environment, binding_name, value, true)
        else
            return error.SyntaxError;
        try self.registerModuleExport("default", binding_name, none, .local, true);
        return value;
    }

    fn registerModuleExport(self: *Runtime, name: []const u8, local_name: []const u8, source_module: u16, kind: ModuleExportKind, explicit: bool) Error!void {
        if (self.active_module == none or self.active_module >= self.module_count) return error.SyntaxError;
        var module = &self.modules[self.active_module];
        for (module.export_entries[0..module.export_count]) |*entry| {
            if (!equals(self.stringBytes(entry.name), name)) continue;
            if (entry.kind == kind and entry.source_module == source_module and equals(self.stringBytes(entry.local_name), local_name)) {
                entry.explicit = entry.explicit or explicit;
                return;
            }
            if (!explicit) {
                if (!entry.explicit) entry.kind = .ambiguous;
                return;
            }
            if (entry.explicit) return error.SyntaxError;
            entry.local_name = try self.storeString(local_name);
            entry.source_module = source_module;
            entry.kind = kind;
            entry.explicit = true;
            return;
        }
        if (module.export_count >= module.export_entries.len) return error.PropertyLimit;
        const stored_name = try self.storeString(name);
        const stored_local_name = try self.storeString(local_name);
        var insert_at: usize = 0;
        while (insert_at < module.export_count and std.mem.order(u8, self.stringBytes(module.export_entries[insert_at].name), name) == .lt)
            insert_at += 1;
        const namespace = module.exports;
        var cell = &self.cells[namespace];
        try self.ensurePropertyCapacity(namespace, cell.property_count + 1);
        var move = module.export_count;
        while (move > insert_at) : (move -= 1) {
            module.export_entries[move] = module.export_entries[move - 1];
            self.propertyStorage(namespace)[move] = self.propertyStorageConst(namespace)[move - 1];
        }
        module.export_entries[insert_at] = .{
            .name = stored_name,
            .local_name = stored_local_name,
            .source_module = source_module,
            .kind = kind,
            .explicit = explicit,
        };
        module.export_count += 1;
        self.propertyStorage(namespace)[insert_at] = .{
            .key = stored_name,
            .value = .undefined,
            .writable = true,
            .enumerable = true,
            .configurable = false,
        };
        cell.property_count += 1;
    }

    fn moduleExportValue(self: *Runtime, module_index: u16, name: []const u8, depth: usize) ?Value {
        if (module_index == none or module_index >= self.module_count or depth > max_modules * 2) return null;
        const module = &self.modules[module_index];
        for (module.export_entries[0..module.export_count]) |entry| {
            if (!equals(self.stringBytes(entry.name), name)) continue;
            return switch (entry.kind) {
                .local => self.lookup(module.environment, self.stringBytes(entry.local_name)),
                .indirect => self.moduleExportValue(entry.source_module, self.stringBytes(entry.local_name), depth + 1),
                .namespace => if (entry.source_module < self.module_count)
                    Value{ .cell = self.modules[entry.source_module].exports }
                else
                    null,
                .ambiguous => null,
            };
        }
        return null;
    }

    fn moduleHasExport(self: *const Runtime, module_index: u16, name: []const u8) bool {
        if (module_index == none or module_index >= self.module_count) return false;
        const module = &self.modules[module_index];
        for (module.export_entries[0..module.export_count]) |entry| {
            if (equals(self.stringBytes(entry.name), name)) return entry.kind != .ambiguous;
        }
        return false;
    }

    fn evaluateModuleIndex(self: *Runtime, index: usize) Error!Value {
        var module = &self.modules[index];
        const program = module.program orelse return error.ModuleNotFound;
        if (!program.bytecodeReady()) return error.BytecodeInvalid;
        if (module.state == .evaluated or module.state == .evaluating) return .{ .cell = module.exports };
        if (module.state == .failed) {
            if (module.failure_value != .undefined) self.pending_exception = module.failure_value;
            return module.failure orelse error.UncaughtException;
        }
        module.exports = try self.allocateCell(.module_namespace);
        self.cells[module.exports].module = @intCast(index);
        self.cells[module.exports].extensible = false;
        self.cells[module.exports].sealed = true;
        module.environment = try self.allocateCell(.environment);
        self.cells[module.environment].parent = self.global_env;
        module.state = .evaluating;
        const environment = module.environment;
        const previous_env = self.active_env;
        const previous_exports = self.active_exports;
        const previous_module = self.active_module;
        const previous_program = self.active_program;
        defer {
            self.active_program = previous_program;
            self.active_env = previous_env;
            self.active_exports = previous_exports;
            self.active_module = previous_module;
        }
        self.active_program = program;
        self.active_env = environment;
        self.active_exports = module.exports;
        self.active_module = @intCast(index);
        const completion = self.executeBytecodeSegment(program, program.root_segment, environment) catch |err| {
            module.state = .failed;
            module.failure = err;
            if (err == error.ScriptThrown) module.failure_value = self.pending_exception;
            return err;
        };
        if (completion.kind == .thrown) {
            module.state = .failed;
            module.failure = error.ScriptThrown;
            module.failure_value = completion.value;
            self.pending_exception = completion.value;
            return error.ScriptThrown;
        }
        module.state = .evaluated;
        try self.finalizeModuleNamespace(@intCast(index));
        return .{ .cell = module.exports };
    }

    fn finalizeModuleNamespace(self: *Runtime, module_index: u16) Error!void {
        var module = &self.modules[module_index];
        const namespace = module.exports;
        if (namespace == none or self.symbol_to_string_tag.len == 0) return;
        var write: usize = 0;
        for (module.export_entries[0..module.export_count], 0..) |entry, read| {
            if (entry.kind == .ambiguous) continue;
            if (write != read) {
                module.export_entries[write] = entry;
                self.propertyStorage(namespace)[write] = self.propertyStorageConst(namespace)[read];
            }
            write += 1;
        }
        module.export_count = write;
        self.cells[namespace].property_count = write;
        for (self.propertyStorageConst(namespace)[0..self.cells[namespace].property_count]) |property|
            if (equals(self.stringBytes(property.key), self.stringBytes(self.symbol_to_string_tag))) return;
        try self.ensurePropertyCapacity(namespace, self.cells[namespace].property_count + 1);
        self.propertyStorage(namespace)[self.cells[namespace].property_count] = .{
            .key = self.symbol_to_string_tag,
            .value = .{ .string = try self.storeString("Module") },
            .writable = false,
            .enumerable = false,
            .configurable = false,
        };
        self.cells[namespace].property_count += 1;
    }

    fn nativeIsConstructor(id: NativeId) bool {
        return switch (id) {
            .object_constructor,
            .function_constructor,
            .array_constructor,
            .string_constructor,
            .regex_constructor,
            .number_constructor,
            .array_buffer_constructor,
            .shared_array_buffer_constructor,
            .data_view_constructor,
            .typed_array_constructor,
            .boolean_constructor,
            .error_constructor,
            .aggregate_error_constructor,
            .map_constructor,
            .set_constructor,
            .weak_map_constructor,
            .weak_set_constructor,
            .date_constructor,
            .iterator_constructor,
            .proxy_constructor,
            .promise_constructor,
            => true,
            else => false,
        };
    }

    fn isConstructor(self: *const Runtime, value: Value) bool {
        var current = value;
        var depth: usize = 0;
        while (depth < max_call_depth) : (depth += 1) {
            const index = switch (current) {
                .cell => |cell| cell,
                else => return false,
            };
            if (index >= self.cells.len or !self.cells[index].occupied) return false;
            const cell = &self.cells[index];
            switch (cell.kind) {
                .function => {
                    const function_program = cell.program_ref orelse return false;
                    if (cell.node == none or cell.node >= function_program.node_count) return false;
                    const flags = function_program.nodes[cell.node].flags;
                    return flags & (flag_arrow | flag_method | flag_generator) == 0 and flags & flag_async == 0;
                },
                .bound_function => current = cell.promise_value,
                .proxy => return cell.host_constructible,
                .native_function => return nativeIsConstructor(cell.native_id),
                .host_function => return cell.host_constructible,
                else => return false,
            }
        }
        return false;
    }

    fn call(self: *Runtime, program: *const Program, callable: Value, receiver: Value, arguments: []const Value, construct: bool) Error!Value {
        return self.callWithNewTarget(program, callable, receiver, arguments, construct, if (construct) callable else .undefined);
    }

    fn callWithNewTarget(self: *Runtime, program: *const Program, callable: Value, receiver: Value, arguments: []const Value, construct: bool, new_target: Value) Error!Value {
        const index = switch (callable) {
            .cell => |cell| cell,
            else => {
                self.diagnostic_site = .call;
                self.diagnostic_value = callable;
                return error.NotCallable;
            },
        };
        if (index >= self.cells.len or !self.cells[index].occupied) {
            self.diagnostic_site = .call;
            self.diagnostic_value = callable;
            return error.NotCallable;
        }
        if (construct and !self.isConstructor(callable)) return error.TypeError;
        const origin_program = self.cells[index].program_ref;
        const previous_program = self.active_program;
        const previous_module = self.active_module;
        const previous_exports = self.active_exports;
        self.active_program = origin_program orelse program;
        if (origin_program != null) {
            self.active_module = self.cells[index].module;
            self.active_exports = if (self.active_module != none and self.active_module < self.module_count)
                self.modules[self.active_module].exports
            else
                none;
        }
        defer {
            self.active_program = previous_program;
            self.active_module = previous_module;
            self.active_exports = previous_exports;
        }
        return switch (self.cells[index].kind) {
            .function => self.callFunction(program, index, receiver, arguments, construct, new_target),
            .bound_function => self.callBound(program, index, arguments, construct, new_target),
            .proxy => self.callProxy(program, callable, receiver, arguments, construct, new_target),
            .native_function => self.callNative(program, self.cells[index].native_id, if (self.cells[index].receiver != .undefined) self.cells[index].receiver else receiver, arguments, construct, new_target),
            .host_function => {
                const callback = self.cells[index].host_function orelse return error.NotCallable;
                const previous_host_construct = self.active_host_construct;
                self.active_host_construct = construct;
                defer self.active_host_construct = previous_host_construct;
                const result = callback(
                    self,
                    self.cells[index].host_context,
                    self.cells[index].host_tag,
                    if (self.cells[index].receiver != .undefined) self.cells[index].receiver else receiver,
                    arguments,
                ) catch |err| {
                    self.captureDiagnostic(.host, err, self.active_program orelse program, self.diagnostic_node);
                    return err;
                };
                if (construct and result == .cell) {
                    _ = try self.privateObjectIndex(result);
                    const prototype = try self.getProperty(new_target, "prototype");
                    if (prototype == .cell) {
                        _ = try self.privateObjectIndex(prototype);
                        self.cells[result.cell].prototype = prototype.cell;
                    }
                }
                return result;
            },
            else => blk: {
                self.diagnostic_site = .call;
                self.diagnostic_value = callable;
                break :blk error.NotCallable;
            },
        };
    }

    fn callAccessor(self: *Runtime, callable: Value, receiver: Value, arguments: []const Value) Error!Value {
        const index = switch (callable) {
            .cell => |cell| cell,
            else => return error.NotCallable,
        };
        if (index >= self.cells.len or !self.cells[index].occupied) return error.NotCallable;
        const program = self.cells[index].program_ref orelse self.diagnostic_program orelse return error.TypeError;
        return self.call(program, callable, receiver, arguments, false);
    }

    const ProxyParts = struct {
        target: Value,
        handler: Value,
    };

    fn proxyParts(self: *Runtime, proxy: Value) Error!ProxyParts {
        const index = try self.expectCellKind(proxy, .proxy);
        const target = self.cells[index].receiver;
        const handler = self.cells[index].promise_value;
        if (target != .cell or handler != .cell) return error.TypeError;
        _ = try self.expectObject(target);
        _ = try self.expectObject(handler);
        return .{ .target = target, .handler = handler };
    }

    fn proxyTrap(self: *Runtime, program: *const Program, proxy: Value, name: []const u8) Error!?struct { parts: ProxyParts, trap: Value } {
        const parts = try self.proxyParts(proxy);
        const trap = try self.getProperty(parts.handler, name);
        if (trap == .undefined or trap == .null_value) return null;
        if (!self.isCallableValue(trap)) return error.TypeError;
        _ = program;
        return .{ .parts = parts, .trap = trap };
    }

    fn createArgumentArray(self: *Runtime, arguments: []const Value) Error!Value {
        const result: Value = .{ .cell = try self.allocateCell(.array) };
        try self.ensureItemCapacity(result.cell, arguments.len);
        for (arguments, 0..) |argument, index| {
            self.itemStorage(result.cell)[index] = argument;
            self.setArrayItemPresent(result.cell, index, true);
        }
        self.cells[result.cell].item_count = arguments.len;
        self.cells[result.cell].array_length = arguments.len;
        return result;
    }

    fn callProxy(self: *Runtime, program: *const Program, proxy: Value, receiver: Value, arguments: []const Value, construct: bool, new_target: Value) Error!Value {
        const state = try self.proxyParts(proxy);
        if (construct) {
            if (!self.isConstructor(state.target)) return error.TypeError;
            const trap_state = try self.proxyTrap(program, proxy, "construct") orelse
                return self.callWithNewTarget(program, state.target, .undefined, arguments, true, new_target);
            const root_base = self.root_count;
            defer self.root_count = root_base;
            try self.pushRoot(proxy);
            const argument_array = try self.createArgumentArray(arguments);
            try self.pushRoot(argument_array);
            const result = try self.call(program, trap_state.trap, trap_state.parts.handler, &.{ trap_state.parts.target, argument_array, new_target }, false);
            _ = try self.expectObject(result);
            return result;
        }
        if (!self.isCallableValue(state.target)) return error.NotCallable;
        const trap_state = try self.proxyTrap(program, proxy, "apply") orelse
            return self.call(program, state.target, receiver, arguments, false);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(proxy);
        const argument_array = try self.createArgumentArray(arguments);
        try self.pushRoot(argument_array);
        return self.call(program, trap_state.trap, trap_state.parts.handler, &.{ trap_state.parts.target, receiver, argument_array }, false);
    }

    fn createProxy(self: *Runtime, target: Value, handler: Value) Error!Value {
        _ = try self.expectObject(target);
        _ = try self.expectObject(handler);
        const proxy: Value = .{ .cell = try self.allocateCell(.proxy) };
        self.cells[proxy.cell].receiver = target;
        self.cells[proxy.cell].promise_value = handler;
        self.cells[proxy.cell].object_environment = self.isCallableValue(target);
        self.cells[proxy.cell].host_constructible = self.isConstructor(target);
        return proxy;
    }

    fn nativeProxyConstructor(self: *Runtime, arguments: []const Value, construct: bool) Error!Value {
        if (!construct or arguments.len < 2) return error.TypeError;
        return self.createProxy(arguments[0], arguments[1]);
    }

    fn nativeProxyRevocable(self: *Runtime, arguments: []const Value) Error!Value {
        if (arguments.len < 2) return error.TypeError;
        const result: Value = .{ .cell = try self.allocateCell(.object) };
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(result);
        const proxy = try self.createProxy(arguments[0], arguments[1]);
        try self.pushRoot(proxy);
        const revoke = try self.createNative(.proxy_revoke, proxy);
        try self.pushRoot(revoke);
        try self.defineFunctionMetadata(revoke, "length", .{ .number = 0 });
        try self.defineFunctionMetadata(revoke, "name", .{ .string = try self.storeString("") });
        try self.defineOwnDataProperty(result, "proxy", proxy);
        try self.defineOwnDataProperty(result, "revoke", revoke);
        return result;
    }

    fn nativeProxyRevoke(self: *Runtime, receiver: Value) Error!Value {
        const index = try self.expectCellKind(receiver, .proxy);
        self.cells[index].receiver = .undefined;
        self.cells[index].promise_value = .undefined;
        return .undefined;
    }

    fn createConstructReceiver(self: *Runtime, new_target: Value) Error!Value {
        var prototype = self.object_prototype;
        const candidate = try self.getProperty(new_target, "prototype");
        if (candidate == .cell) {
            _ = try self.privateObjectIndex(candidate);
            prototype = candidate.cell;
        }
        const result = Value{ .cell = try self.allocateCell(.object) };
        self.cells[result.cell].prototype = prototype;
        return result;
    }

    fn superFunctionEnvironment(self: *Runtime, environment: u16) Error!u16 {
        var current = environment;
        while (current != none) {
            if (self.lookupOwn(current, internal_current_function) != null) return current;
            if (current >= self.cells.len or !self.cells[current].occupied or self.cells[current].kind != .environment) break;
            current = self.cells[current].parent;
        }
        return error.TypeError;
    }

    fn performSuperCall(self: *Runtime, program: *const Program, environment: u16, arguments: []const Value) Error!Value {
        const function_environment = try self.superFunctionEnvironment(environment);
        if (self.lookupOwn(function_environment, "this") != null) return error.TypeError;
        const current_function = self.lookupOwn(function_environment, internal_current_function) orelse return error.TypeError;
        const function_index = switch (current_function) {
            .cell => |cell| cell,
            else => return error.TypeError,
        };
        if (function_index >= self.cells.len or !self.cells[function_index].occupied or self.cells[function_index].kind != .function)
            return error.TypeError;
        const function_program = self.cells[function_index].program_ref orelse program;
        if (self.cells[function_index].node == none or self.cells[function_index].node >= function_program.node_count)
            return error.BytecodeInvalid;
        const function_node = function_program.nodes[self.cells[function_index].node];
        if (function_node.flags & (flag_class_constructor | flag_class_derived) != (flag_class_constructor | flag_class_derived))
            return error.TypeError;
        const base_index = self.cells[function_index].prototype;
        if (base_index == none or base_index >= self.cells.len or !self.cells[base_index].occupied) return error.TypeError;
        const base_constructor = Value{ .cell = base_index };
        if (!self.isConstructor(base_constructor)) return error.TypeError;
        const new_target = self.lookupOwn(function_environment, internal_new_target) orelse return error.TypeError;
        const result = try self.callWithNewTarget(program, base_constructor, .undefined, arguments, true, new_target);
        _ = try self.privateObjectIndex(result);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(result);
        try self.defineBinding(function_environment, "this", result, true);
        try self.initializeClassInstance(function_program, function_index, result);
        return result;
    }

    fn createAsyncFunction(self: *Runtime, program: *const Program, function_index: u16, receiver: Value, arguments: []const Value) Error!Value {
        if (arguments.len > max_parameters) return error.RangeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = function_index });
        try self.pushRoot(receiver);
        for (arguments) |argument| try self.pushRoot(argument);
        const promise = try self.createPromise();
        try self.pushRoot(promise);

        const memory = self.program_allocator.allocate(
            self.program_allocator.context,
            @sizeOf(AsyncFiberState),
            @alignOf(AsyncFiberState),
        ) orelse return error.GeneratorAllocation;
        var state: *AsyncFiberState = @ptrCast(@alignCast(memory));
        state.* = .{};
        state.occupied = true;
        state.owner_promise = promise.cell;
        state.function_cell = function_index;
        state.program = program;
        state.receiver = receiver;
        state.argument_count = arguments.len;
        if (arguments.len > 0) @memcpy(state.arguments[0..arguments.len], arguments);
        state.status = .executing;
        const stack = self.program_allocator.allocate(
            self.program_allocator.context,
            fiber_stack_bytes,
            16,
        ) orelse {
            self.program_allocator.free(
                self.program_allocator.context,
                @ptrCast(state),
                @sizeOf(AsyncFiberState),
                @alignOf(AsyncFiberState),
            );
            return error.GeneratorAllocation;
        };
        state.stack_memory = stack;
        initializeFiberContext(&state.fiber_context, stack[0..fiber_stack_bytes], asyncFiberEntry, self, @intFromPtr(state));
        state.next = self.async_state_head;
        if (state.next) |next| next.previous = state;
        self.async_state_head = state;
        self.cells[promise.cell].host_context = state;
        state.async_execution.active_env = self.cells[function_index].parent;
        state.async_execution.active_exports = self.active_exports;
        state.async_execution.active_module = self.active_module;
        state.async_execution.active_async_state = state;

        self.captureExecution(&state.caller_execution);
        self.restoreExecution(&state.async_execution);
        fiberSwitch(&state.caller_context, &state.fiber_context);
        clearExecutionSnapshot(&state.caller_execution);
        if (state.status == .completed) try self.finishAsyncState(state);
        return promise;
    }

    fn runAsyncFiber(self: *Runtime, state: *AsyncFiberState) noreturn {
        const program = state.program orelse unreachable;
        state.entering_function = true;
        const result = self.callFunction(
            program,
            state.function_cell,
            state.receiver,
            state.arguments[0..state.argument_count],
            false,
            .undefined,
        ) catch |err| result: {
            state.failure = error.ScriptThrown;
            if (err == error.ScriptThrown) break :result self.pending_exception;
            break :result self.runtimeErrorValue(err) catch {
                state.failure = err;
                break :result .undefined;
            };
        };
        state.result = result;
        state.status = .completed;
        self.captureExecution(&state.async_execution);
        self.restoreExecution(&state.caller_execution);
        fiberSwitch(&state.fiber_context, &state.caller_context);
        while (true) fiberSwitch(&state.fiber_context, &state.caller_context);
    }

    fn awaitAsyncValue(self: *Runtime, value: Value) Error!Value {
        if (self.active_async_state == null) {
            const generator_state = self.active_generator_state orelse return error.TypeError;
            return self.awaitAsyncGeneratorValue(generator_state, value);
        }
        var state = self.active_async_state.?;
        if (!state.occupied or state.status != .executing) return error.TypeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(value);
        try self.pushRoot(.{ .cell = state.owner_promise });
        const source_value = try self.promiseResolvedValue(value);
        try self.pushRoot(source_value);
        const source = source_value.cell;
        const reaction = Reaction{ .async_owner = state.owner_promise };
        try self.addPromiseReaction(source, reaction);
        state.status = .suspended_await;
        self.captureExecution(&state.async_execution);
        self.restoreExecution(&state.caller_execution);
        fiberSwitch(&state.fiber_context, &state.caller_context);
        if (state.resume_rejected) {
            self.pending_exception = state.resume_value;
            return error.ScriptThrown;
        }
        return state.resume_value;
    }

    fn resumeAsyncState(self: *Runtime, owner_promise: u16, rejected: bool, value: Value) Error!void {
        if (owner_promise == none or owner_promise >= self.cells.len or !self.cells[owner_promise].occupied or
            self.cells[owner_promise].kind != .promise) return;
        var state: *AsyncFiberState = @ptrCast(@alignCast(self.cells[owner_promise].host_context orelse return));
        if (!state.occupied or state.owner_promise != owner_promise or state.status != .suspended_await) return;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = owner_promise });
        try self.pushRoot(value);
        state.resume_rejected = rejected;
        state.resume_value = value;
        self.captureExecution(&state.caller_execution);
        self.restoreExecution(&state.async_execution);
        state.status = .executing;
        fiberSwitch(&state.caller_context, &state.fiber_context);
        clearExecutionSnapshot(&state.caller_execution);
        if (state.status == .completed) try self.finishAsyncState(state);
    }

    fn finishAsyncState(self: *Runtime, state: *AsyncFiberState) Error!void {
        if (!state.occupied or state.status != .completed) return error.TypeError;
        const owner = state.owner_promise;
        const result = state.result;
        const failure = state.failure;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = owner });
        try self.pushRoot(result);
        self.detachAsyncState(state);
        if (failure != null)
            try self.settlePromise(owner, .rejected, result)
        else
            try self.settlePromise(owner, .fulfilled, result);
    }

    fn detachAsyncState(self: *Runtime, state: *AsyncFiberState) void {
        if (state.owner_promise != none and state.owner_promise < self.cells.len and
            self.cells[state.owner_promise].occupied and self.cells[state.owner_promise].host_context == @as(*anyopaque, @ptrCast(state)))
            self.cells[state.owner_promise].host_context = null;
        if (state.previous) |previous| previous.next = state.next else self.async_state_head = state.next;
        if (state.next) |next| next.previous = state.previous;
        if (self.active_async_state == state) self.active_async_state = null;
        state.occupied = false;
        clearExecutionSnapshot(&state.async_execution);
        clearExecutionSnapshot(&state.caller_execution);
        if (state.stack_memory) |stack| self.program_allocator.free(self.program_allocator.context, stack, fiber_stack_bytes, 16);
        state.stack_memory = null;
        self.program_allocator.free(
            self.program_allocator.context,
            @ptrCast(state),
            @sizeOf(AsyncFiberState),
            @alignOf(AsyncFiberState),
        );
    }

    fn createGenerator(self: *Runtime, program: *const Program, function_index: u16, receiver: Value, arguments: []const Value) Error!Value {
        if (arguments.len > max_parameters) return error.RangeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        const function_value = Value{ .cell = function_index };
        try self.pushRoot(function_value);
        try self.pushRoot(receiver);
        for (arguments) |argument| try self.pushRoot(argument);
        const prototype = try self.getProperty(function_value, "prototype");
        try self.pushRoot(prototype);
        const generator_cell = try self.allocateCell(.generator);
        self.cells[generator_cell].prototype = if (prototype == .cell) prototype.cell else self.object_prototype;

        const memory = self.program_allocator.allocate(
            self.program_allocator.context,
            @sizeOf(GeneratorFiberState),
            @alignOf(GeneratorFiberState),
        ) orelse return error.GeneratorAllocation;
        var state: *GeneratorFiberState = @ptrCast(@alignCast(memory));
        errdefer self.program_allocator.free(
            self.program_allocator.context,
            @ptrCast(state),
            @sizeOf(GeneratorFiberState),
            @alignOf(GeneratorFiberState),
        );
        state.* = .{};
        state.occupied = true;
        state.owner_cell = generator_cell;
        state.function_cell = function_index;
        state.program = program;
        state.receiver = receiver;
        state.argument_count = arguments.len;
        state.async_generator = program.nodes[self.cells[function_index].node].flags & flag_async != 0;
        if (arguments.len > 0) @memcpy(state.arguments[0..arguments.len], arguments);
        state.status = .suspended_start;
        state.next = self.generator_state_head;
        if (state.next) |next| next.previous = state;
        self.generator_state_head = state;
        self.cells[generator_cell].host_context = state;
        state.generator_execution.active_env = self.cells[function_index].parent;
        state.generator_execution.active_exports = self.active_exports;
        state.generator_execution.active_module = self.active_module;
        state.generator_execution.active_generator_state = state;
        return .{ .cell = generator_cell };
    }

    fn ensureGeneratorStack(self: *Runtime, state: *GeneratorFiberState) Error!void {
        if (state.stack_memory != null) return;
        const memory = self.program_allocator.allocate(
            self.program_allocator.context,
            fiber_stack_bytes,
            16,
        ) orelse return error.GeneratorAllocation;
        state.stack_memory = memory;
        initializeFiberContext(&state.fiber_context, memory[0..fiber_stack_bytes], generatorFiberEntry, self, @intFromPtr(state));
    }

    fn releaseGeneratorStack(self: *Runtime, state: *GeneratorFiberState) void {
        const memory = state.stack_memory orelse return;
        state.stack_memory = null;
        self.program_allocator.free(self.program_allocator.context, memory, fiber_stack_bytes, 16);
    }

    fn runGeneratorFiber(self: *Runtime, state: *GeneratorFiberState) noreturn {
        const program = state.program orelse unreachable;
        const function_cell = state.function_cell;
        const receiver = state.receiver;
        const argument_count = state.argument_count;
        var failure: ?Error = null;
        state.entering_function = true;
        const result = self.callFunction(
            program,
            function_cell,
            receiver,
            state.arguments[0..argument_count],
            false,
            .undefined,
        ) catch |err| result: {
            if (err == error.GeneratorReturn) break :result self.pending_generator_return;
            if (err == error.ScriptThrown) {
                failure = err;
                break :result self.pending_exception;
            }
            if (state.async_generator) {
                failure = error.ScriptThrown;
                break :result self.runtimeErrorValue(err) catch {
                    failure = err;
                    break :result .undefined;
                };
            }
            failure = err;
            break :result .undefined;
        };
        state.result = result;
        state.failure = failure;
        state.status = .completed;
        self.captureExecution(&state.generator_execution);
        self.restoreExecution(&state.caller_execution);
        fiberSwitch(&state.fiber_context, &state.caller_context);
        while (true)
            fiberSwitch(&state.fiber_context, &state.caller_context);
    }

    fn suspendGenerator(self: *Runtime, yielded: Value) Error!GeneratorResume {
        var state = self.active_generator_state orelse return error.TypeError;
        if (!state.occupied or state.status != .executing) return error.TypeError;
        state.result = yielded;
        state.failure = null;
        state.status = .suspended_yield;
        self.captureExecution(&state.generator_execution);
        self.restoreExecution(&state.caller_execution);
        fiberSwitch(&state.fiber_context, &state.caller_context);
        return .{ .kind = state.resume_kind, .value = state.resume_value };
    }

    fn yieldGeneratorValue(self: *Runtime, yielded: Value) Error!Value {
        const state = self.active_generator_state orelse return error.TypeError;
        const resolved = if (state.async_generator) try self.awaitAsyncGeneratorValue(state, yielded) else yielded;
        const resumed = try self.suspendGenerator(resolved);
        return switch (resumed.kind) {
            .next => resumed.value,
            .return_value => {
                self.pending_generator_return = resumed.value;
                return error.GeneratorReturn;
            },
            .throw_value => {
                self.pending_exception = resumed.value;
                return error.ScriptThrown;
            },
        };
    }

    fn yieldGeneratorDelegate(self: *Runtime, program: *const Program, iterable: Value) Error!Value {
        if (self.active_generator_state) |state| {
            if (state.async_generator) return self.yieldAsyncGeneratorDelegate(program, state, iterable);
        }
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(iterable);
        var cursor = try self.openIterator(program, iterable);
        try self.rootIterator(cursor);
        var step = try self.iteratorNext(program, &cursor);
        if (step.done) return step.value;
        var resumed = try self.suspendGenerator(step.value);
        while (true) {
            switch (resumed.kind) {
                .next => {
                    step = try self.iteratorNextWithValue(program, &cursor, resumed.value);
                    if (step.done) return step.value;
                    resumed = try self.suspendGenerator(step.value);
                },
                .return_value => {
                    if (cursor.kind != .custom) {
                        cursor.done = true;
                        self.pending_generator_return = resumed.value;
                        return error.GeneratorReturn;
                    }
                    const return_method = try self.getProperty(cursor.iterator, "return");
                    if (return_method.isNullish()) {
                        cursor.done = true;
                        self.pending_generator_return = resumed.value;
                        return error.GeneratorReturn;
                    }
                    if (!self.isCallableValue(return_method)) return error.TypeError;
                    const result = try self.call(program, return_method, cursor.iterator, &.{resumed.value}, false);
                    _ = try self.expectObject(result);
                    const result_root = self.root_count;
                    defer self.root_count = result_root;
                    try self.pushRoot(result);
                    const value = try self.getProperty(result, "value");
                    if (self.truthy(try self.getProperty(result, "done"))) {
                        cursor.done = true;
                        self.pending_generator_return = value;
                        return error.GeneratorReturn;
                    }
                    resumed = try self.suspendGenerator(value);
                },
                .throw_value => {
                    if (cursor.kind != .custom) return error.TypeError;
                    const throw_method = try self.getProperty(cursor.iterator, "throw");
                    if (throw_method.isNullish()) {
                        const return_method = try self.getProperty(cursor.iterator, "return");
                        if (!return_method.isNullish()) {
                            if (!self.isCallableValue(return_method)) return error.TypeError;
                            const close_result = try self.call(program, return_method, cursor.iterator, &.{}, false);
                            _ = try self.expectObject(close_result);
                        }
                        cursor.done = true;
                        return error.TypeError;
                    }
                    if (!self.isCallableValue(throw_method)) return error.TypeError;
                    const result = try self.call(program, throw_method, cursor.iterator, &.{resumed.value}, false);
                    _ = try self.expectObject(result);
                    const result_root = self.root_count;
                    defer self.root_count = result_root;
                    try self.pushRoot(result);
                    const value = try self.getProperty(result, "value");
                    if (self.truthy(try self.getProperty(result, "done"))) {
                        cursor.done = true;
                        return value;
                    }
                    resumed = try self.suspendGenerator(value);
                },
            }
        }
    }

    fn yieldAsyncGeneratorDelegate(self: *Runtime, program: *const Program, state: *GeneratorFiberState, iterable: Value) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(iterable);
        var cursor = try self.openAsyncIterator(program, iterable);
        try self.rootAsyncIterator(cursor);
        var step = try self.asyncIteratorNext(program, &cursor, .undefined, false);
        if (step.done) return self.awaitAsyncGeneratorValue(state, step.value);
        var yielded = try self.awaitAsyncGeneratorValue(state, step.value);
        var resumed = try self.suspendGenerator(yielded);
        while (true) {
            switch (resumed.kind) {
                .next => {
                    step = try self.asyncIteratorNext(program, &cursor, resumed.value, true);
                    if (step.done) return self.awaitAsyncGeneratorValue(state, step.value);
                    yielded = try self.awaitAsyncGeneratorValue(state, step.value);
                    resumed = try self.suspendGenerator(yielded);
                },
                .return_value => {
                    if (cursor.synchronous and cursor.sync_cursor.kind != .custom) {
                        cursor.done = true;
                        self.pending_generator_return = resumed.value;
                        return error.GeneratorReturn;
                    }
                    const iterator = if (cursor.synchronous) cursor.sync_cursor.iterator else cursor.iterator;
                    const return_method = try self.getProperty(iterator, "return");
                    if (return_method.isNullish()) {
                        cursor.done = true;
                        self.pending_generator_return = resumed.value;
                        return error.GeneratorReturn;
                    }
                    if (!self.isCallableValue(return_method)) return error.TypeError;
                    const result = try self.call(program, return_method, iterator, &.{resumed.value}, false);
                    const awaited = try self.awaitAsyncGeneratorValue(state, result);
                    _ = try self.expectObject(awaited);
                    const result_root = self.root_count;
                    defer self.root_count = result_root;
                    try self.pushRoot(awaited);
                    const value = try self.getProperty(awaited, "value");
                    if (self.truthy(try self.getProperty(awaited, "done"))) {
                        cursor.done = true;
                        self.pending_generator_return = try self.awaitAsyncGeneratorValue(state, value);
                        return error.GeneratorReturn;
                    }
                    yielded = try self.awaitAsyncGeneratorValue(state, value);
                    resumed = try self.suspendGenerator(yielded);
                },
                .throw_value => {
                    if (cursor.synchronous and cursor.sync_cursor.kind != .custom) return error.TypeError;
                    const iterator = if (cursor.synchronous) cursor.sync_cursor.iterator else cursor.iterator;
                    const throw_method = try self.getProperty(iterator, "throw");
                    if (throw_method.isNullish()) {
                        const return_method = try self.getProperty(iterator, "return");
                        if (!return_method.isNullish()) {
                            if (!self.isCallableValue(return_method)) return error.TypeError;
                            const close_result = try self.call(program, return_method, iterator, &.{}, false);
                            const awaited_close = try self.awaitAsyncGeneratorValue(state, close_result);
                            _ = try self.expectObject(awaited_close);
                        }
                        cursor.done = true;
                        return error.TypeError;
                    }
                    if (!self.isCallableValue(throw_method)) return error.TypeError;
                    const result = try self.call(program, throw_method, iterator, &.{resumed.value}, false);
                    const awaited = try self.awaitAsyncGeneratorValue(state, result);
                    _ = try self.expectObject(awaited);
                    const result_root = self.root_count;
                    defer self.root_count = result_root;
                    try self.pushRoot(awaited);
                    const value = try self.getProperty(awaited, "value");
                    if (self.truthy(try self.getProperty(awaited, "done"))) {
                        cursor.done = true;
                        return self.awaitAsyncGeneratorValue(state, value);
                    }
                    yielded = try self.awaitAsyncGeneratorValue(state, value);
                    resumed = try self.suspendGenerator(yielded);
                },
            }
        }
    }

    fn generatorIteratorResult(self: *Runtime, value: Value, done: bool) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(value);
        const result = Value{ .cell = try self.allocateCell(.object) };
        try self.pushRoot(result);
        try self.defineOwnDataProperty(result, "value", value);
        try self.defineOwnDataProperty(result, "done", .{ .boolean = done });
        return result;
    }

    fn generatorMethod(self: *Runtime, receiver: Value, kind: GeneratorResumeKind, value: Value) Error!Value {
        const generator_cell = try self.expectCellKind(receiver, .generator);
        const state: *GeneratorFiberState = @ptrCast(@alignCast(self.cells[generator_cell].host_context orelse return error.TypeError));
        if (!state.occupied or state.owner_cell != generator_cell) return error.TypeError;
        if (!state.async_generator) return self.resumeGenerator(receiver, kind, value);
        return self.enqueueAsyncGeneratorRequest(generator_cell, state, kind, value);
    }

    fn enqueueAsyncGeneratorRequest(self: *Runtime, generator_cell: u16, state: *GeneratorFiberState, kind: GeneratorResumeKind, value: Value) Error!Value {
        if (state.request_count >= state.requests.len) return error.JobLimit;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = generator_cell });
        try self.pushRoot(value);
        const promise = try self.createPromise();
        try self.pushRoot(promise);
        const slot = (state.request_head + state.request_count) % state.requests.len;
        state.requests[slot] = .{ .kind = kind, .value = value, .promise = promise.cell };
        const start_processing = state.request_count == 0 and state.status != .executing and state.status != .suspended_await;
        state.request_count += 1;
        if (start_processing) {
            self.enqueueJob(&self.microtasks, &self.microtask_head, &self.microtask_count, .{
                .kind = .async_generator_request,
                .generator = generator_cell,
            }) catch |err| {
                state.request_count -= 1;
                state.requests[slot] = .{};
                return err;
            };
        }
        return promise;
    }

    fn processAsyncGeneratorRequests(self: *Runtime, generator_cell: u16) Error!void {
        if (generator_cell == none or generator_cell >= self.cells.len or !self.cells[generator_cell].occupied or
            self.cells[generator_cell].kind != .generator) return;
        var state: *GeneratorFiberState = @ptrCast(@alignCast(self.cells[generator_cell].host_context orelse return));
        if (!state.occupied or !state.async_generator or state.owner_cell != generator_cell) return;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = generator_cell });
        while (state.request_count > 0 and state.status != .executing and state.status != .suspended_await) {
            const request = state.requests[state.request_head];
            switch (state.status) {
                .completed => switch (request.kind) {
                    .next => {
                        state.result = .undefined;
                        state.failure = null;
                    },
                    .return_value => {
                        state.result = request.value;
                        state.failure = null;
                    },
                    .throw_value => {
                        state.result = request.value;
                        state.failure = error.ScriptThrown;
                    },
                },
                .suspended_start => switch (request.kind) {
                    .next => {
                        state.resume_kind = .next;
                        state.resume_value = .undefined;
                        try self.ensureGeneratorStack(state);
                        try self.switchIntoGenerator(state);
                    },
                    .return_value => {
                        state.result = request.value;
                        state.failure = null;
                        state.status = .completed;
                    },
                    .throw_value => {
                        state.result = request.value;
                        state.failure = error.ScriptThrown;
                        state.status = .completed;
                    },
                },
                .suspended_yield => {
                    state.resume_kind = request.kind;
                    state.resume_value = request.value;
                    try self.switchIntoGenerator(state);
                },
                .executing, .suspended_await => return,
            }
            if (state.status == .suspended_await) return;
            try self.completeAsyncGeneratorRequest(state, request);
        }
    }

    fn switchIntoGenerator(self: *Runtime, state: *GeneratorFiberState) Error!void {
        self.captureExecution(&state.caller_execution);
        self.restoreExecution(&state.generator_execution);
        state.status = .executing;
        fiberSwitch(&state.caller_context, &state.fiber_context);
        clearExecutionSnapshot(&state.caller_execution);
        if (state.status == .executing) return error.TypeError;
    }

    fn completeAsyncGeneratorRequest(self: *Runtime, state: *GeneratorFiberState, request: AsyncGeneratorRequest) Error!void {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = state.owner_cell });
        try self.pushRoot(.{ .cell = request.promise });
        try self.pushRoot(state.result);
        if (state.status == .suspended_yield) {
            const result = try self.generatorIteratorResult(state.result, false);
            try self.settlePromise(request.promise, .fulfilled, result);
        } else if (state.status == .completed) {
            if (state.failure == null and !state.awaiting_completion) {
                const source_value = try self.promiseResolvedValue(state.result);
                try self.pushRoot(source_value);
                const source = source_value.cell;
                const reaction = Reaction{ .async_generator = state.owner_cell };
                try self.addPromiseReaction(source, reaction);
                state.awaiting_completion = true;
                state.status = .suspended_await;
                return;
            }
            clearExecutionSnapshot(&state.generator_execution);
            self.releaseGeneratorStack(state);
            state.argument_count = 0;
            state.receiver = .undefined;
            state.resume_value = .undefined;
            if (state.failure != null) {
                try self.settlePromise(request.promise, .rejected, state.result);
            } else {
                const completed_value = switch (request.kind) {
                    .next => state.result,
                    .return_value => if (state.result == .undefined) request.value else state.result,
                    .throw_value => state.result,
                };
                const result = try self.generatorIteratorResult(completed_value, true);
                try self.settlePromise(request.promise, .fulfilled, result);
            }
            state.failure = null;
            state.result = .undefined;
            state.awaiting_completion = false;
        } else {
            return error.TypeError;
        }
        state.requests[state.request_head] = .{};
        state.request_head = (state.request_head + 1) % state.requests.len;
        state.request_count -= 1;
    }

    fn awaitAsyncGeneratorValue(self: *Runtime, state: *GeneratorFiberState, value: Value) Error!Value {
        if (!state.occupied or !state.async_generator or state.status != .executing) return error.TypeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = state.owner_cell });
        try self.pushRoot(value);
        const source_value = try self.promiseResolvedValue(value);
        try self.pushRoot(source_value);
        const source = source_value.cell;
        const reaction = Reaction{ .async_generator = state.owner_cell };
        try self.addPromiseReaction(source, reaction);
        state.status = .suspended_await;
        self.captureExecution(&state.generator_execution);
        self.restoreExecution(&state.caller_execution);
        fiberSwitch(&state.fiber_context, &state.caller_context);
        if (state.await_rejected) {
            self.pending_exception = state.await_value;
            return error.ScriptThrown;
        }
        return state.await_value;
    }

    fn resumeAsyncGeneratorAwait(self: *Runtime, generator_cell: u16, rejected: bool, value: Value) Error!void {
        if (generator_cell == none or generator_cell >= self.cells.len or !self.cells[generator_cell].occupied or
            self.cells[generator_cell].kind != .generator) return;
        var state: *GeneratorFiberState = @ptrCast(@alignCast(self.cells[generator_cell].host_context orelse return));
        if (!state.occupied or !state.async_generator or state.owner_cell != generator_cell or
            state.status != .suspended_await or state.request_count == 0) return;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = generator_cell });
        try self.pushRoot(value);
        if (state.awaiting_completion) {
            state.result = value;
            state.failure = if (rejected) error.ScriptThrown else null;
            state.status = .completed;
            const request = state.requests[state.request_head];
            try self.completeAsyncGeneratorRequest(state, request);
            try self.processAsyncGeneratorRequests(generator_cell);
            return;
        }
        state.await_rejected = rejected;
        state.await_value = value;
        try self.switchIntoGenerator(state);
        if (state.status == .suspended_await) return;
        const request = state.requests[state.request_head];
        try self.completeAsyncGeneratorRequest(state, request);
        try self.processAsyncGeneratorRequests(generator_cell);
    }

    fn resumeGenerator(self: *Runtime, receiver: Value, kind: GeneratorResumeKind, value: Value) Error!Value {
        const generator_cell = try self.expectCellKind(receiver, .generator);
        var state: *GeneratorFiberState = @ptrCast(@alignCast(self.cells[generator_cell].host_context orelse return error.TypeError));
        if (!state.occupied or state.owner_cell != generator_cell) return error.TypeError;
        if (state.async_generator) return error.TypeError;
        switch (state.status) {
            .executing => return error.TypeError,
            .completed => return switch (kind) {
                .next => self.generatorIteratorResult(.undefined, true),
                .return_value => self.generatorIteratorResult(value, true),
                .throw_value => {
                    self.pending_exception = value;
                    return error.ScriptThrown;
                },
            },
            .suspended_start => switch (kind) {
                .return_value => {
                    state.status = .completed;
                    state.result = value;
                    state.argument_count = 0;
                    state.receiver = .undefined;
                    clearExecutionSnapshot(&state.generator_execution);
                    return self.generatorIteratorResult(value, true);
                },
                .throw_value => {
                    state.status = .completed;
                    state.result = value;
                    state.argument_count = 0;
                    state.receiver = .undefined;
                    clearExecutionSnapshot(&state.generator_execution);
                    self.pending_exception = value;
                    return error.ScriptThrown;
                },
                .next => {},
            },
            .suspended_yield => {},
            .suspended_await => return error.TypeError,
        }

        state.resume_kind = kind;
        state.resume_value = if (state.status == .suspended_start) Value.undefined else value;
        if (state.status == .suspended_start) try self.ensureGeneratorStack(state);
        self.captureExecution(&state.caller_execution);
        self.restoreExecution(&state.generator_execution);
        state.status = .executing;
        fiberSwitch(&state.caller_context, &state.fiber_context);
        clearExecutionSnapshot(&state.caller_execution);

        if (state.status == .suspended_yield)
            return self.generatorIteratorResult(state.result, false);
        if (state.status != .completed) return error.TypeError;
        clearExecutionSnapshot(&state.generator_execution);
        self.releaseGeneratorStack(state);
        state.argument_count = 0;
        state.receiver = .undefined;
        state.resume_value = .undefined;
        if (state.failure) |failure| {
            if (failure == error.ScriptThrown) {
                self.pending_exception = state.result;
                return error.ScriptThrown;
            }
            return failure;
        }
        return self.generatorIteratorResult(state.result, true);
    }

    fn callFunction(self: *Runtime, program: *const Program, function_index: u16, receiver: Value, arguments: []const Value, construct: bool, new_target: Value) Error!Value {
        const function = &self.cells[function_index];
        const function_program = function.program_ref orelse if (function.module == none)
            program
        else
            self.modules[function.module].program orelse return error.ModuleNotFound;
        if (!function_program.bytecodeReady()) return error.BytecodeInvalid;
        const node = function_program.nodes[function.node];
        const entering_this_async = if (self.active_async_state) |state|
            state.occupied and state.status == .executing and state.function_cell == function_index and state.entering_function
        else
            false;
        if (node.flags & flag_generator != 0) {
            if (construct) return error.TypeError;
            const entering_this_generator = if (self.active_generator_state) |state|
                state.occupied and state.status == .executing and state.function_cell == function_index and state.entering_function
            else
                false;
            if (!entering_this_generator)
                return self.createGenerator(function_program, function_index, receiver, arguments);
            self.active_generator_state.?.entering_function = false;
        }
        if (node.flags & flag_async != 0 and node.flags & flag_generator == 0 and !entering_this_async) {
            if (construct) return error.TypeError;
            return self.createAsyncFunction(function_program, function_index, receiver, arguments);
        }
        if (entering_this_async) self.active_async_state.?.entering_function = false;
        if (self.call_depth >= max_call_depth) return error.CallDepth;
        const frame_index = self.call_depth;
        self.call_environments[frame_index] = none;
        self.call_depth += 1;
        defer self.call_depth -= 1;
        const arrow = node.flags & flag_arrow != 0;
        const strict_function = node.flags & flag_strict != 0 or function.module != none;
        const class_constructor = node.flags & flag_class_constructor != 0;
        const derived_constructor = class_constructor and node.flags & flag_class_derived != 0;
        if (class_constructor and !construct) return error.TypeError;
        if ((arrow or node.flags & flag_method != 0) and construct) return error.TypeError;
        const environment = try self.allocateCell(.environment);
        self.call_environments[frame_index] = environment;
        self.cells[environment].parent = function.parent;
        const previous_active_env = self.active_env;
        self.active_env = environment;
        defer self.active_env = previous_active_env;
        const this_value = if (construct and !derived_constructor)
            try self.createConstructReceiver(new_target)
        else if (construct)
            Value.undefined
        else if (!strict_function and receiver.isNullish())
            self.global("globalThis") orelse receiver
        else
            receiver;
        if (!arrow) {
            try self.defineBinding(environment, internal_new_target, new_target, true);
            if (class_constructor) {
                try self.defineBinding(environment, internal_current_function, .{ .cell = function_index }, true);
            }
            if (!derived_constructor) try self.defineBinding(environment, "this", this_value, true);
            if (node.flags & flag_needs_arguments != 0)
                try self.defineBinding(environment, "arguments", try self.createArgumentsObject(function_program, function.node, environment, arguments, !strict_function), false);
        }
        var parameter = node.a;
        var argument_index: usize = 0;
        while (parameter != none) {
            const parameter_node = function_program.nodes[parameter];
            if (parameter_node.kind != .parameter) return error.BytecodeInvalid;
            var value: Value = undefined;
            if (parameter_node.flags & flag_rest != 0) {
                value = try self.arrayFromValues(if (argument_index < arguments.len) arguments[argument_index..] else &.{});
                argument_index = arguments.len;
            } else {
                value = if (argument_index < arguments.len) arguments[argument_index] else .undefined;
                argument_index += 1;
                if (value == .undefined and parameter_node.a != none) {
                    const default_segment = function_program.workspace.compiled.node_segments[parameter_node.a];
                    if (default_segment == none) return error.BytecodeInvalid;
                    value = try self.bytecodeValueFromSegment(function_program, default_segment, environment);
                }
            }
            try self.applyPattern(function_program, parameter_node.b, value, environment, .{ .binding = true });
            parameter = parameter_node.next;
        }
        if (class_constructor and !derived_constructor)
            try self.initializeClassInstance(function_program, function_index, this_value);
        if (derived_constructor and node.flags & flag_class_default != 0)
            _ = try self.performSuperCall(function_program, environment, arguments);
        const prologue_segment = function_program.workspace.compiled.function_prologue_segments[function.node];
        if (prologue_segment == none) return error.BytecodeInvalid;
        const prologue = try self.executeBytecodeSegment(function_program, prologue_segment, environment);
        if (prologue.kind != .normal) return error.BytecodeInvalid;
        const body_segment = function_program.workspace.compiled.node_segments[node.b];
        if (body_segment == none) return error.BytecodeInvalid;
        const completion = if (node.flags & flag_prefix != 0)
            Completion{ .kind = .returned, .value = try self.bytecodeValueFromSegment(function_program, body_segment, environment) }
        else
            try self.executeBytecodeSegment(function_program, body_segment, environment);
        var final_value: Value = undefined;
        if (completion.kind == .thrown) {
            self.pending_exception = completion.value;
            return error.ScriptThrown;
        } else {
            const result = if (completion.kind == .returned) completion.value else Value.undefined;
            if (construct and derived_constructor) {
                if (completion.kind == .returned and result == .cell) {
                    final_value = result;
                } else if (completion.kind == .returned and result != .undefined) {
                    return error.TypeError;
                } else {
                    final_value = self.lookupOwn(environment, "this") orelse return error.TypeError;
                }
            } else {
                final_value = if (construct and result != .cell) this_value else result;
            }
        }
        self.active_env = previous_active_env;
        if (self.stats.allocations >= self.next_gc_allocation) {
            try self.pushRoot(final_value);
            self.collectGarbage();
            self.popRoot();
        }
        return final_value;
    }

    fn callBound(self: *Runtime, program: *const Program, index: u16, arguments: []const Value, construct: bool, new_target: Value) Error!Value {
        const cell = &self.cells[index];
        var combined: [max_parameters]Value = [_]Value{.undefined} ** max_parameters;
        if (cell.item_count + arguments.len > combined.len) return error.RangeError;
        for (self.itemStorageConst(index)[0..cell.item_count], 0..) |argument, argument_index| combined[argument_index] = argument;
        for (arguments, 0..) |argument, argument_index| combined[cell.item_count + argument_index] = argument;
        const effective_new_target = if (construct and new_target == .cell and new_target.cell == index)
            cell.promise_value
        else
            new_target;
        return self.callWithNewTarget(
            program,
            cell.promise_value,
            cell.receiver,
            combined[0 .. cell.item_count + arguments.len],
            construct,
            effective_new_target,
        );
    }

    fn nativeFunctionConstructor(self: *Runtime, arguments: []const Value) Error!Value {
        var source: [max_source_bytes]u8 = undefined;
        var length: usize = 0;
        try appendBytes(source[0..], &length, "(function anonymous(");
        if (arguments.len > 1) {
            for (arguments[0 .. arguments.len - 1], 0..) |argument, index| {
                if (index > 0) try appendBytes(source[0..], &length, ",");
                const parameter = (try self.toString(argument)).bytes(self.strings[0..self.string_len]);
                try appendBytes(source[0..], &length, parameter);
            }
        }
        try appendBytes(source[0..], &length, "){\n");
        if (arguments.len > 0) {
            const body = (try self.toString(arguments[arguments.len - 1])).bytes(self.strings[0..self.string_len]);
            try appendBytes(source[0..], &length, body);
        }
        try appendBytes(source[0..], &length, "\n})");
        const source_value = Value{ .string = try self.storeString(source[0..length]) };
        const previous_environment = self.active_env;
        self.active_env = self.global_env;
        defer self.active_env = previous_environment;
        return self.nativeEval(&.{source_value}, false);
    }

