        if (self.isTypedArray(arguments[0])) switch (typedArrayPropertyIndex(name)) {
            .index => |item| {
                if (item >= self.typedArrayLengthOrZero(object_index)) return .undefined;
                try self.setProperty(descriptor, "value", try self.typedArrayRead(object_index, item));
                try self.setProperty(descriptor, "writable", .{ .boolean = true });
                try self.setProperty(descriptor, "enumerable", .{ .boolean = true });
                try self.setProperty(descriptor, "configurable", .{ .boolean = true });
                return descriptor;
            },
            .invalid_numeric => return .undefined,
            .ordinary => {},
        };
        if (self.cells[object_index].kind == .array) {
            if (equals(name, "length")) {
                try self.setProperty(descriptor, "value", .{ .number = @floatFromInt(@max(self.cells[object_index].array_length, self.cells[object_index].item_count)) });
                try self.setProperty(descriptor, "writable", .{ .boolean = self.cells[object_index].array_length_writable });
                try self.setProperty(descriptor, "enumerable", .{ .boolean = false });
                try self.setProperty(descriptor, "configurable", .{ .boolean = false });
                return descriptor;
            }
            if (parseArrayIndex(name)) |item| if (self.arrayItemPresent(object_index, item)) {
                try self.setProperty(descriptor, "value", self.itemStorageConst(object_index)[item]);
                try self.setProperty(descriptor, "writable", .{ .boolean = !self.cells[object_index].frozen });
                try self.setProperty(descriptor, "enumerable", .{ .boolean = true });
                try self.setProperty(descriptor, "configurable", .{ .boolean = !self.cells[object_index].sealed });
                return descriptor;
            };
        }
        if (!(try self.hasOwnProperty(arguments[0], name))) return .undefined;
        if (self.findAccessor(object_index, name)) |accessor| {
            try self.setProperty(descriptor, "get", accessor.getter);
            try self.setProperty(descriptor, "set", accessor.setter);
            try self.setProperty(descriptor, "enumerable", .{ .boolean = accessor.enumerable });
            try self.setProperty(descriptor, "configurable", .{ .boolean = accessor.configurable });
        } else {
            for (self.propertyStorageConst(object_index)[0..self.cells[object_index].property_count]) |property| {
                if (!equals(self.stringBytes(property.key), name)) continue;
                try self.setProperty(descriptor, "value", property.value);
                try self.setProperty(descriptor, "writable", .{ .boolean = property.writable });
                try self.setProperty(descriptor, "enumerable", .{ .boolean = property.enumerable });
                try self.setProperty(descriptor, "configurable", .{ .boolean = property.configurable });
                break;
            }
        }
        return descriptor;
    }

    fn nativeObjectGetPrototype(self: *Runtime, arguments: []const Value) Error!Value {
        if (arguments.len == 0) return error.TypeError;
        const object = try self.boxObject(arguments[0]);
        return self.getPrototypeInternal(object);
    }

    fn nativeObjectSetPrototype(self: *Runtime, arguments: []const Value) Error!Value {
        if (arguments.len < 2) return error.TypeError;
        _ = switch (arguments[1]) {
            .cell => try self.expectObject(arguments[1]),
            .null_value => none,
            else => return error.TypeError,
        };
        if (arguments[0].isNullish()) return error.TypeError;
        if (arguments[0] != .cell) return arguments[0];
        if (!try self.setPrototypeInternal(arguments[0], arguments[1])) return error.TypeError;
        return arguments[0];
    }

    fn templateObject(self: *Runtime, program: *const Program, node_index: u16) Error!Value {
        if (node_index == none or node_index >= program.node_count) return error.BytecodeInvalid;
        const literal = program.nodes[node_index];
        if (literal.kind != .template_literal) return error.BytecodeInvalid;
        var reusable_index: ?usize = null;
        for (self.template_objects[0..self.template_object_count], 0..) |entry, entry_index| {
            if (entry.program == program and entry.generation == program.parse_generation and entry.node == node_index) return entry.value;
            if (entry.program == program and entry.generation != program.parse_generation) reusable_index = entry_index;
        }
        const cache_index = reusable_index orelse self.template_object_count;
        if (cache_index >= self.template_objects.len) return error.RangeError;

        var cooked_values: [max_parameters]Value = undefined;
        var raw_values: [max_parameters]Value = undefined;
        var count: usize = 0;
        var current = literal.a;
        while (current != none) : (current = program.nodes[current].next) {
            if (count >= cooked_values.len) return error.RangeError;
            const part = program.nodes[current];
            if (part.kind != .template_part) return error.BytecodeInvalid;
            raw_values[count] = .{ .string = try self.storeTemplateRaw(program.text(part.text)) };
            cooked_values[count] = if (part.flags & 1 != 0)
                .undefined
            else
                .{ .string = try self.decodeTemplateString(program, part.text) };
            count += 1;
        }
        if (count == 0) return error.BytecodeInvalid;

        const root_base = self.root_count;
        defer self.root_count = root_base;
        const raw = try self.arrayFromValues(raw_values[0..count]);
        try self.pushRoot(raw);
        const cooked = try self.arrayFromValues(cooked_values[0..count]);
        try self.pushRoot(cooked);
        try self.setProperty(cooked, "raw", raw);
        self.cells[raw.cell].frozen = true;
        self.cells[cooked.cell].frozen = true;

        self.template_objects[cache_index] = .{
            .program = program,
            .generation = program.parse_generation,
            .node = node_index,
            .value = cooked,
        };
        if (reusable_index == null) self.template_object_count += 1;
        return cooked;
    }

    fn nativeArrayConstructor(self: *Runtime, arguments: []const Value) Error!Value {
        const index = try self.allocateCell(.array);
        if (arguments.len == 1 and arguments[0] == .number) {
            self.cells[index].array_length = try arrayLengthValue(arguments[0].number);
            return .{ .cell = index };
        }
        return self.fillArrayFromValues(index, arguments);
    }

    fn arrayFromValues(self: *Runtime, values: []const Value) Error!Value {
        const index = try self.allocateCell(.array);
        return self.fillArrayFromValues(index, values);
    }

    fn createArgumentsObject(self: *Runtime, program: *const Program, function_node: u16, environment: u16, values: []const Value, mapped: bool) Error!Value {
        const arguments = try self.arrayFromValues(values);
        const cell = &self.cells[arguments.cell];
        cell.program_ref = program;
        cell.node = function_node;
        cell.parent = environment;
        cell.receiver = .{ .number = @bitCast(@as(u64, 0)) };
        cell.promise_value = .{ .number = @bitCast(@as(u64, 0)) };
        if (!mapped) return arguments;
        if (function_node == none or function_node >= program.node_count) return error.BytecodeInvalid;
        const function = program.nodes[function_node];
        var names: [max_parameters]StringRef = undefined;
        var parameter_count: usize = 0;
        var parameter = function.a;
        while (parameter != none) : (parameter = program.nodes[parameter].next) {
            if (parameter_count >= names.len) return error.BindingLimit;
            const parameter_node = program.nodes[parameter];
            if (parameter_node.kind != .parameter or parameter_node.flags & flag_rest != 0 or
                parameter_node.a != none or program.nodes[parameter_node.b].kind != .identifier) return arguments;
            names[parameter_count] = program.nodes[parameter_node.b].text;
            parameter_count += 1;
        }
        const mapped_count = @min(values.len, parameter_count);
        for (0..mapped_count) |argument_index| {
            var duplicated_later = false;
            for (names[argument_index + 1 .. parameter_count]) |later| {
                if (equals(program.text(names[argument_index]), program.text(later))) {
                    duplicated_later = true;
                    break;
                }
            }
            if (!duplicated_later) self.setArgumentMapping(arguments.cell, argument_index, true);
        }
        return arguments;
    }

    fn mappedArgumentName(self: *const Runtime, index: u16, argument_index: usize) ?[]const u8 {
        if (argument_index >= max_parameters) return null;
        const cell = &self.cells[index];
        if (cell.kind != .array or cell.parent == none or
            self.argumentMapWord(index, argument_index / 64) & (@as(u64, 1) << @intCast(argument_index % 64)) == 0) return null;
        const program = cell.program_ref orelse return null;
        if (cell.node == none or cell.node >= program.node_count) return null;
        var parameter = program.nodes[cell.node].a;
        var current_index: usize = 0;
        while (parameter != none) : (parameter = program.nodes[parameter].next) {
            if (current_index == argument_index) {
                const parameter_node = program.nodes[parameter];
                if (parameter_node.kind != .parameter or program.nodes[parameter_node.b].kind != .identifier) return null;
                return program.text(program.nodes[parameter_node.b].text);
            }
            current_index += 1;
        }
        return null;
    }

    fn clearArgumentMapping(self: *Runtime, index: u16, argument_index: usize) void {
        if (argument_index >= max_parameters) return;
        self.setArgumentMapping(index, argument_index, false);
    }

    fn syncMappedArguments(self: *Runtime, index: u16) Error!void {
        if (index >= self.cells.len or self.cells[index].kind != .array or self.cells[index].parent == none) return;
        const count = @min(self.cells[index].item_count, max_parameters);
        for (0..count) |argument_index| {
            const name = self.mappedArgumentName(index, argument_index) orelse continue;
            self.itemStorage(index)[argument_index] = self.lookup(self.cells[index].parent, name) orelse .undefined;
        }
    }

    fn propagateMappedArguments(self: *Runtime, index: u16) Error!void {
        if (index >= self.cells.len or self.cells[index].kind != .array or self.cells[index].parent == none) return;
        for (0..max_parameters) |argument_index| {
            const name = self.mappedArgumentName(index, argument_index) orelse continue;
            if (argument_index >= self.cells[index].item_count) {
                self.clearArgumentMapping(index, argument_index);
                continue;
            }
            try self.assignBinding(self.cells[index].parent, name, self.itemStorageConst(index)[argument_index]);
        }
    }

    fn argumentMapWord(self: *const Runtime, index: u16, word: usize) u64 {
        if (word >= argument_map_words) return 0;
        const value = if (word == 0) self.cells[index].receiver else self.cells[index].promise_value;
        return if (value == .number) @bitCast(value.number) else 0;
    }

    fn setArgumentMapping(self: *Runtime, index: u16, argument_index: usize, mapped: bool) void {
        if (argument_index >= max_parameters) return;
        const word = argument_index / 64;
        const mask = @as(u64, 1) << @intCast(argument_index % 64);
        var bits = self.argumentMapWord(index, word);
        if (mapped)
            bits |= mask
        else
            bits &= ~mask;
        const value = Value{ .number = @bitCast(bits) };
        if (word == 0)
            self.cells[index].receiver = value
        else
            self.cells[index].promise_value = value;
    }

    fn fillArrayFromValues(self: *Runtime, index: u16, values: []const Value) Error!Value {
        if (values.len > max_items) return error.ItemLimit;
        try self.ensureItemCapacity(index, values.len);
        for (values, 0..) |value, item_index| {
            self.itemStorage(index)[item_index] = value;
            self.setArrayItemPresent(index, item_index, true);
        }
        self.cells[index].item_count = values.len;
        self.cells[index].array_length = values.len;
        return .{ .cell = index };
    }

    fn effectiveArrayLength(self: *const Runtime, index: u16) usize {
        return @max(self.cells[index].array_length, self.cells[index].item_count);
    }

    fn arrayLikeLength(self: *Runtime, receiver: Value) Error!usize {
        switch (receiver) {
            .undefined, .null_value => return error.TypeError,
            .string => |ref| return runtimeStringUnitCount(self.stringBytes(ref)),
            .cell => |index| if (index < self.cells.len and self.cells[index].occupied) {
                if (self.isTypedArray(receiver)) return (try self.typedArrayRange(index)).length;
                if (self.cells[index].kind == .array) return self.effectiveArrayLength(index);
            },
            else => {},
        }
        const number = try self.toNumber(try self.getProperty(receiver, "length"));
        if (std.math.isNan(number) or number <= 0) return 0;
        if (!std.math.isFinite(number) or number > @as(f64, @floatFromInt(max_items))) return error.ItemLimit;
        return @intFromFloat(@trunc(number));
    }

    fn arrayLikeHas(self: *Runtime, receiver: Value, item_index: usize) Error!bool {
        if (receiver == .string) return item_index < runtimeStringUnitCount(self.stringBytes(receiver.string));
        var name_buffer: [24]u8 = undefined;
        const name = std.fmt.bufPrint(name_buffer[0..], "{d}", .{item_index}) catch return error.RangeError;
        return self.hasProperty(receiver, name);
    }

    fn arrayLikeGet(self: *Runtime, receiver: Value, item_index: usize) Error!Value {
        var name_buffer: [24]u8 = undefined;
        const name = std.fmt.bufPrint(name_buffer[0..], "{d}", .{item_index}) catch return error.RangeError;
        return self.getProperty(receiver, name);
    }

    fn arrayLikeSet(self: *Runtime, receiver: Value, item_index: usize, value: Value) Error!void {
        var name_buffer: [24]u8 = undefined;
        const name = std.fmt.bufPrint(name_buffer[0..], "{d}", .{item_index}) catch return error.RangeError;
        try self.defineOwnDataProperty(receiver, name, value);
    }

    fn arrayLikeDelete(self: *Runtime, receiver: Value, item_index: usize) Error!void {
        var name_buffer: [24]u8 = undefined;
        const name = std.fmt.bufPrint(name_buffer[0..], "{d}", .{item_index}) catch return error.RangeError;
        if (!try self.deleteOwnProperty(receiver, name)) return error.TypeError;
    }

    fn arrayLikeSetLength(self: *Runtime, receiver: Value, length: usize) Error!void {
        if (length > max_items) return error.ItemLimit;
        const index = try self.expectObject(receiver);
        if (self.cells[index].kind != .array) {
            try self.defineOwnDataProperty(receiver, "length", .{ .number = @floatFromInt(length) });
            return;
        }
        if (self.cells[index].frozen or !self.cells[index].array_length_writable) return error.TypeError;
        const previous = self.effectiveArrayLength(index);
        if (length < previous) {
            var item_index = previous;
            while (item_index > length) {
                item_index -= 1;
                if (self.arrayItemPresent(index, item_index) and self.cells[index].sealed) return error.TypeError;
                if (item_index < self.cells[index].item_count) {
                    self.itemStorage(index)[item_index] = .undefined;
                    self.setArrayItemPresent(index, item_index, false);
                }
                self.clearArgumentMapping(index, item_index);
            }
            self.cells[index].item_count = @min(self.cells[index].item_count, length);
        }
        self.cells[index].array_length = length;
        try self.propagateMappedArguments(index);
    }

    fn arrayRelativeIndex(number: f64, length: usize) usize {
        if (std.math.isNan(number) or number == -std.math.inf(f64)) return 0;
        if (number == std.math.inf(f64)) return length;
        const integer = @trunc(number);
        if (integer < 0) return @intFromFloat(@max(0, @as(f64, @floatFromInt(length)) + integer));
        return @intFromFloat(@min(@as(f64, @floatFromInt(length)), integer));
    }

    fn createSparseArray(self: *Runtime, length: usize) Error!Value {
        if (length > max_items) return error.ItemLimit;
        const result: Value = .{ .cell = try self.allocateCell(.array) };
        self.cells[result.cell].array_length = length;
        return result;
    }

    fn setSparseArrayItem(self: *Runtime, array: Value, item_index: usize, value: Value) Error!void {
        try self.extendArrayItems(array.cell, item_index + 1);
        self.itemStorage(array.cell)[item_index] = value;
        self.setArrayItemPresent(array.cell, item_index, true);
        self.cells[array.cell].array_length = @max(self.cells[array.cell].array_length, item_index + 1);
    }

    fn createArrayResult(self: *Runtime, program: *const Program, constructor: Value, length: usize, pass_length: bool) Error!Value {
        if (self.isConstructor(constructor)) {
            const result = try self.call(
                program,
                constructor,
                .undefined,
                if (pass_length) &.{.{ .number = @floatFromInt(length) }} else &.{},
                true,
            );
            _ = try self.expectObject(result);
            return result;
        }
        return self.createSparseArray(if (pass_length) length else 0);
    }

    fn createArraySpeciesResult(self: *Runtime, program: *const Program, original: Value, length: usize) Error!Value {
        if (!self.isCellKind(original, .array)) return self.createSparseArray(length);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(original);
        var constructor = try self.getProperty(original, "constructor");
        try self.pushRoot(constructor);
        if (constructor == .cell) {
            constructor = try self.getProperty(constructor, self.stringBytes(self.symbol_species));
            try self.pushRoot(constructor);
            if (constructor == .null_value) constructor = .undefined;
        }
        if (constructor == .undefined) return self.createSparseArray(length);
        if (!self.isConstructor(constructor)) return error.TypeError;
        const result = try self.call(program, constructor, .undefined, &.{.{ .number = @floatFromInt(length) }}, true);
        _ = try self.expectObject(result);
        return result;
    }

    fn nativeArrayOf(self: *Runtime, program: *const Program, constructor: Value, arguments: []const Value) Error!Value {
        const result = try self.createArrayResult(program, constructor, arguments.len, true);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(result);
        for (arguments, 0..) |argument, item_index| try self.arrayLikeSet(result, item_index, argument);
        try self.arrayLikeSetLength(result, arguments.len);
        return result;
    }

    fn nativeArrayFrom(self: *Runtime, program: *const Program, constructor: Value, arguments: []const Value) Error!Value {
        if (arguments.len == 0 or arguments[0].isNullish()) return error.TypeError;
        const source = arguments[0];
        const map_function = if (arguments.len > 1) arguments[1] else Value.undefined;
        const this_argument = if (arguments.len > 2) arguments[2] else Value.undefined;
        if (map_function != .undefined and !self.isCallableValue(map_function)) return error.TypeError;

        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(source);
        try self.pushRoot(map_function);
        try self.pushRoot(this_argument);
        const iterable = switch (source) {
            .string => true,
            .cell => |index| self.cells[index].kind == .array or try self.hasProperty(source, self.stringBytes(self.symbol_iterator)),
            else => false,
        };
        if (iterable) {
            const result = try self.createArrayResult(program, constructor, 0, false);
            try self.pushRoot(result);
            var cursor = try self.openIterator(program, source);
            try self.rootIterator(cursor);
            errdefer self.iteratorClose(program, &cursor) catch {};
            var item_index: usize = 0;
            while (true) {
                const step = try self.iteratorNext(program, &cursor);
                if (step.done) break;
                if (item_index >= max_items) return error.ItemLimit;
                const value = if (map_function == .undefined)
                    step.value
                else
                    try self.call(program, map_function, this_argument, &.{ step.value, .{ .number = @floatFromInt(item_index) } }, false);
                try self.arrayLikeSet(result, item_index, value);
                item_index += 1;
            }
            try self.arrayLikeSetLength(result, item_index);
            return result;
        }

        const length = try self.arrayLikeLength(source);
        const result = try self.createArrayResult(program, constructor, length, true);
        try self.pushRoot(result);
        for (0..length) |item_index| {
            const source_value = try self.arrayLikeGet(source, item_index);
            const value = if (map_function == .undefined)
                source_value
            else
                try self.call(program, map_function, this_argument, &.{ source_value, .{ .number = @floatFromInt(item_index) } }, false);
            try self.arrayLikeSet(result, item_index, value);
        }
        return result;
    }

    fn nativeArrayFromAsync(self: *Runtime, program: *const Program, constructor: Value, arguments: []const Value) Error!Value {
        const promise = try self.createPromise();
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(promise);
        const chain = self.startArrayFromAsync(program, constructor, arguments) catch |err| {
            const rejection = if (err == error.ScriptThrown) self.pending_exception else try self.runtimeErrorValue(err);
            try self.rejectPromise(promise, rejection);
            return promise;
        };
        try self.pushRoot(chain);
        try self.resolvePromise(promise, chain);
        return promise;
    }

    fn startArrayFromAsync(self: *Runtime, program: *const Program, constructor: Value, arguments: []const Value) Error!Value {
        if (arguments.len == 0 or arguments[0].isNullish()) return error.TypeError;
        const source = arguments[0];
        const map_function = if (arguments.len > 1) arguments[1] else Value.undefined;
        const this_argument = if (arguments.len > 2) arguments[2] else Value.undefined;
        if (map_function != .undefined and !self.isCallableValue(map_function)) return error.TypeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(source);
        try self.pushRoot(map_function);
        try self.pushRoot(this_argument);

        var iterator: Value = .undefined;
        if (source == .cell and try self.hasProperty(source, self.stringBytes(self.symbol_async_iterator))) {
            const method = try self.getProperty(source, self.stringBytes(self.symbol_async_iterator));
            if (!self.isCallableValue(method)) return error.TypeError;
            iterator = try self.call(program, method, source, &.{}, false);
            _ = try self.expectObject(iterator);
        } else {
            const values = try self.nativeArrayFrom(program, .undefined, &.{source});
            try self.pushRoot(values);
            iterator = try self.nativeArrayIterator(values, 1);
        }
        try self.pushRoot(iterator);
        const next_method = try self.getProperty(iterator, "next");
        if (!self.isCallableValue(next_method)) return error.TypeError;
        try self.pushRoot(next_method);
        const result = try self.createArrayResult(program, constructor, 0, false);
        try self.pushRoot(result);
        const state: Value = .{ .cell = try self.allocateCell(.object) };
        try self.pushRoot(state);
        try self.setProperty(state, "iterator", iterator);
        try self.setProperty(state, "next", next_method);
        try self.setProperty(state, "result", result);
        try self.setProperty(state, "map", map_function);
        try self.setProperty(state, "thisArg", this_argument);
        try self.setProperty(state, "index", .{ .number = 0 });
        const step_callback = try self.createNative(.array_from_async_step, state);
        try self.pushRoot(step_callback);
        const value_callback = try self.createNative(.array_from_async_value, state);
        try self.pushRoot(value_callback);
        const commit_callback = try self.createNative(.array_from_async_commit, state);
        try self.setProperty(state, "step", step_callback);
        try self.setProperty(state, "valueCallback", value_callback);
        try self.setProperty(state, "commit", commit_callback);

        const next_result = try self.call(program, next_method, iterator, &.{}, false);
        try self.pushRoot(next_result);
        const awaited = try self.promiseResolvedValue(next_result);
        return self.nativePromiseThen(program, awaited, &.{step_callback});
    }

    fn nativeArrayFromAsyncStep(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        _ = try self.expectObject(receiver);
        const iteration = if (arguments.len > 0) arguments[0] else Value.undefined;
        _ = try self.expectObject(iteration);
        if (self.truthy(try self.getProperty(iteration, "done"))) {
            const result = try self.getProperty(receiver, "result");
            const length: usize = @intFromFloat(try self.toNumber(try self.getProperty(receiver, "index")));
            try self.arrayLikeSetLength(result, length);
            return result;
        }
        const value = try self.getProperty(iteration, "value");
        const awaited = try self.promiseResolvedValue(value);
        return self.nativePromiseThen(program, awaited, &.{try self.getProperty(receiver, "valueCallback")});
    }

    fn nativeArrayFromAsyncValue(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        _ = try self.expectObject(receiver);
        const value = if (arguments.len > 0) arguments[0] else Value.undefined;
        const map_function = try self.getProperty(receiver, "map");
        if (map_function == .undefined) return self.nativeArrayFromAsyncCommit(program, receiver, &.{value});
        const index = try self.getProperty(receiver, "index");
        const mapped = try self.call(program, map_function, try self.getProperty(receiver, "thisArg"), &.{ value, index }, false);
        const awaited = try self.promiseResolvedValue(mapped);
        return self.nativePromiseThen(program, awaited, &.{try self.getProperty(receiver, "commit")});
    }

    fn nativeArrayFromAsyncCommit(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        _ = try self.expectObject(receiver);
