        return result;
    }

    fn nativeArrayReduce(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value, reverse: bool) Error!Value {
        if (arguments.len == 0 or !self.isCallableValue(arguments[0])) return error.TypeError;
        const length = try self.arrayLikeLength(receiver);
        var accumulator = if (arguments.len > 1) arguments[1] else Value.undefined;
        var initialized = arguments.len > 1;
        var remaining = length;
        while (remaining > 0) {
            const item_index = if (reverse) remaining - 1 else length - remaining;
            remaining -= 1;
            if (!try self.arrayLikeHas(receiver, item_index)) continue;
            const item = try self.arrayLikeGet(receiver, item_index);
            if (!initialized) {
                accumulator = item;
                initialized = true;
                continue;
            }
            accumulator = try self.call(program, arguments[0], .undefined, &.{
                accumulator,
                item,
                .{ .number = @floatFromInt(item_index) },
                receiver,
            }, false);
        }
        if (!initialized) return error.TypeError;
        return accumulator;
    }

    fn nativeArraySort(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        const length = try self.arrayLikeLength(receiver);
        const comparator = if (arguments.len > 0) arguments[0] else Value.undefined;
        if (comparator != .undefined and !self.isCallableValue(comparator)) return error.TypeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        try self.pushRoot(comparator);
        const values = try self.createSparseArray(0);
        try self.pushRoot(values);
        var value_count: usize = 0;
        for (0..length) |item_index| {
            if (!try self.arrayLikeHas(receiver, item_index)) continue;
            try self.setSparseArrayItem(values, value_count, try self.arrayLikeGet(receiver, item_index));
            value_count += 1;
        }
        try self.sortDenseArray(program, values.cell, comparator);
        for (0..value_count) |item_index| try self.arrayLikeSet(receiver, item_index, self.itemStorageConst(values.cell)[item_index]);
        for (value_count..length) |item_index| try self.arrayLikeDelete(receiver, item_index);
        try self.arrayLikeSetLength(receiver, length);
        return receiver;
    }

    fn sortDenseArray(self: *Runtime, program: *const Program, index: u16, comparator: Value) Error!void {
        var outer: usize = 1;
        while (outer < self.cells[index].item_count) : (outer += 1) {
            var inner = outer;
            while (inner > 0) {
                const left = self.itemStorageConst(index)[inner - 1];
                const right = self.itemStorageConst(index)[inner];
                const order = if (left == .undefined)
                    if (right == .undefined) @as(f64, 0) else @as(f64, 1)
                else if (right == .undefined)
                    @as(f64, -1)
                else if (comparator != .undefined)
                    try self.toNumber(try self.call(program, comparator, .undefined, &.{ left, right }, false))
                else blk: {
                    const left_text = (try self.toString(left)).bytes(self.strings[0..self.string_len]);
                    const right_text = (try self.toString(right)).bytes(self.strings[0..self.string_len]);
                    break :blk switch (std.mem.order(u8, left_text, right_text)) {
                        .lt => @as(f64, -1),
                        .eq => @as(f64, 0),
                        .gt => @as(f64, 1),
                    };
                };
                if (!(order > 0)) break;
                self.itemStorage(index)[inner - 1] = right;
                self.itemStorage(index)[inner] = left;
                inner -= 1;
            }
        }
    }

    fn nativeArrayIterator(self: *Runtime, receiver: Value, kind: u16) Error!Value {
        if (receiver.isNullish()) return error.TypeError;
        const iterator: Value = .{ .cell = try self.allocateCell(.array_iterator) };
        self.cells[iterator.cell].receiver = receiver;
        self.cells[iterator.cell].host_tag = kind;
        self.cells[iterator.cell].array_length = 0;
        return iterator;
    }

    fn nativeArrayIteratorNext(self: *Runtime, receiver: Value) Error!Value {
        const iterator = try self.expectCellKind(receiver, .array_iterator);
        const source = self.cells[iterator].receiver;
        if (source == .undefined) return self.createIteratorResult(.undefined, true);
        const item_index = self.cells[iterator].array_length;
        const length = try self.arrayLikeLength(source);
        if (item_index >= length) {
            self.cells[iterator].receiver = .undefined;
            return self.createIteratorResult(.undefined, true);
        }
        self.cells[iterator].array_length = item_index + 1;
        const value = switch (self.cells[iterator].host_tag) {
            0 => Value{ .number = @floatFromInt(item_index) },
            1 => try self.arrayLikeGet(source, item_index),
            2 => try self.arrayFromValues(&.{ .{ .number = @floatFromInt(item_index) }, try self.arrayLikeGet(source, item_index) }),
            else => return error.TypeError,
        };
        return self.createIteratorResult(value, false);
    }

    fn createIteratorResult(self: *Runtime, value: Value, done: bool) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(value);
        const result: Value = .{ .cell = try self.allocateCell(.object) };
        try self.pushRoot(result);
        try self.setProperty(result, "value", value);
        try self.setProperty(result, "done", .{ .boolean = done });
        return result;
    }

    fn nativeArrayToReversed(self: *Runtime, receiver: Value) Error!Value {
        const length = try self.arrayLikeLength(receiver);
        const result = try self.createSparseArray(length);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        try self.pushRoot(result);
        for (0..length) |item_index|
            try self.setSparseArrayItem(result, item_index, try self.arrayLikeGet(receiver, length - item_index - 1));
        return result;
    }

    fn nativeArrayToSorted(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        const length = try self.arrayLikeLength(receiver);
        const comparator = if (arguments.len > 0) arguments[0] else Value.undefined;
        if (comparator != .undefined and !self.isCallableValue(comparator)) return error.TypeError;
        const result = try self.createSparseArray(length);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        try self.pushRoot(comparator);
        try self.pushRoot(result);
        for (0..length) |item_index| try self.setSparseArrayItem(result, item_index, try self.arrayLikeGet(receiver, item_index));
        try self.sortDenseArray(program, result.cell, comparator);
        return result;
    }

    fn nativeArrayToSpliced(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const length = try self.arrayLikeLength(receiver);
        const start = arrayRelativeIndex(if (arguments.len > 0) try self.toNumber(arguments[0]) else 0, length);
        const available = length - start;
        const requested = if (arguments.len == 0)
            0
        else if (arguments.len > 1)
            try self.toNumber(arguments[1])
        else
            @as(f64, @floatFromInt(available));
        const delete_count = @min(available, clampSubstringIndex(requested, available));
        const insert_count = arguments.len -| 2;
        const new_length = length - delete_count + insert_count;
        if (new_length > max_items) return error.ItemLimit;
        const result = try self.createSparseArray(new_length);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        try self.pushRoot(result);
        var destination: usize = 0;
        for (0..start) |source_index| {
            try self.setSparseArrayItem(result, destination, try self.arrayLikeGet(receiver, source_index));
            destination += 1;
        }
        for (arguments[2..]) |argument| {
            try self.setSparseArrayItem(result, destination, argument);
            destination += 1;
        }
        var source_index = start + delete_count;
        while (source_index < length) : (source_index += 1) {
            try self.setSparseArrayItem(result, destination, try self.arrayLikeGet(receiver, source_index));
            destination += 1;
        }
        return result;
    }

    fn nativeArrayWith(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const length = try self.arrayLikeLength(receiver);
        const number = try self.toNumber(if (arguments.len > 0) arguments[0] else .{ .number = 0 });
        if (!std.math.isFinite(number)) return error.RangeError;
        const integer = @trunc(number);
        const position = if (integer >= 0) integer else @as(f64, @floatFromInt(length)) + integer;
        if (position < 0 or position >= @as(f64, @floatFromInt(length))) return error.RangeError;
        const replacement = if (arguments.len > 1) arguments[1] else Value.undefined;
        const replace_index: usize = @intFromFloat(position);
        const result = try self.createSparseArray(length);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        try self.pushRoot(replacement);
        try self.pushRoot(result);
        for (0..length) |item_index| {
            const value = if (item_index == replace_index) replacement else try self.arrayLikeGet(receiver, item_index);
            try self.setSparseArrayItem(result, item_index, value);
        }
        return result;
    }

    fn collectionIndex(self: *Runtime, receiver: Value, map: ?bool) Error!u16 {
        const index = try self.expectObject(receiver);
        if (map) |want_map| {
            if (self.cells[index].host_tag != (if (want_map) map_tag else set_tag)) return error.TypeError;
        } else if (self.cells[index].host_tag != map_tag and self.cells[index].host_tag != set_tag) return error.TypeError;
        return index;
    }

    fn weakCollectionIndex(self: *Runtime, receiver: Value, map: ?bool) Error!u16 {
        const index = try self.expectObject(receiver);
        if (map) |want_map| {
            if (self.cells[index].host_tag != (if (want_map) weak_map_tag else weak_set_tag)) return error.TypeError;
        } else if (self.cells[index].host_tag != weak_map_tag and self.cells[index].host_tag != weak_set_tag) return error.TypeError;
        return index;
    }

    fn isMapCollectionTag(tag: u16) bool {
        return tag == map_tag or tag == weak_map_tag;
    }

    fn isPresenceCollectionTag(tag: u16) bool {
        return tag == map_tag or tag == set_tag or tag == weak_map_tag or tag == weak_set_tag;
    }

    fn isIteratorStorageTag(tag: u16) bool {
        return tag == iterator_helper_tag or tag == iterator_wrapper_tag or tag == iterator_concat_tag;
    }

    fn canonicalCollectionKey(value: Value) Value {
        if (value == .number and value.number == 0) return .{ .number = 0 };
        return value;
    }

    fn sameValueZero(self: *const Runtime, left: Value, right: Value) bool {
        return self.strictEqual(left, right) or (left == .number and right == .number and std.math.isNan(left.number) and std.math.isNan(right.number));
    }

    fn collectionFind(self: *const Runtime, index: u16, key: Value) ?usize {
        const stride: usize = if (isMapCollectionTag(self.cells[index].host_tag)) 2 else 1;
        var slot: usize = 0;
        while (slot < self.cells[index].item_count) : (slot += stride) {
            if (!self.arrayItemPresent(index, slot)) continue;
            if (self.sameValueZero(self.itemStorageConst(index)[slot], key)) return slot;
        }
        return null;
    }

    fn createCollection(self: *Runtime, prototype: Value, map: bool) Error!Value {
        const result: Value = .{ .cell = try self.allocateCell(.object) };
        self.cells[result.cell].host_tag = if (map) map_tag else set_tag;
        self.cells[result.cell].prototype = try self.expectObject(prototype);
        return result;
    }

    fn appendCollectionEntry(self: *Runtime, index: u16, key_value: Value, map_value: Value) Error!void {
        const key = canonicalCollectionKey(key_value);
        if (self.collectionFind(index, key)) |slot| {
            if (isMapCollectionTag(self.cells[index].host_tag)) self.itemStorage(index)[slot + 1] = map_value;
            return;
        }
        const stride: usize = if (isMapCollectionTag(self.cells[index].host_tag)) 2 else 1;
        const start = self.cells[index].item_count;
        try self.extendArrayItems(index, start + stride);
        self.itemStorage(index)[start] = key;
        self.setArrayItemPresent(index, start, true);
        if (stride == 2) {
            self.itemStorage(index)[start + 1] = map_value;
            self.setArrayItemPresent(index, start + 1, true);
        }
    }

    fn nativeCollectionConstructor(self: *Runtime, program: *const Program, default_prototype: Value, arguments: []const Value, map: bool, construct: bool, new_target: Value) Error!Value {
        if (!construct) return error.TypeError;
        const requested_prototype = if (new_target == .cell) try self.getProperty(new_target, "prototype") else .undefined;
        const prototype = if (requested_prototype == .cell) requested_prototype else default_prototype;
        const result = try self.createCollection(prototype, map);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(result);
        if (arguments.len == 0 or arguments[0].isNullish()) return result;
        try self.pushRoot(arguments[0]);
        const adder = try self.getProperty(result, if (map) "set" else "add");
        if (!self.isCallableValue(adder)) return error.TypeError;
        try self.pushRoot(adder);
        var cursor = try self.openIterator(program, arguments[0]);
        try self.rootIterator(cursor);
        errdefer self.iteratorClose(program, &cursor) catch {};
        const iteration_root = self.root_count;
        while (true) {
            self.root_count = iteration_root;
            const step = try self.iteratorNext(program, &cursor);
            if (step.done) break;
            try self.pushRoot(step.value);
            if (map) {
                if (step.value != .cell) return error.TypeError;
                _ = try self.call(program, adder, result, &.{ try self.arrayLikeGet(step.value, 0), try self.arrayLikeGet(step.value, 1) }, false);
            } else _ = try self.call(program, adder, result, &.{step.value}, false);
        }
        return result;
    }

    fn nativeMapSet(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.collectionIndex(receiver, true);
        try self.appendCollectionEntry(index, if (arguments.len > 0) arguments[0] else .undefined, if (arguments.len > 1) arguments[1] else .undefined);
        return receiver;
    }

    fn nativeSetAdd(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.collectionIndex(receiver, false);
        try self.appendCollectionEntry(index, if (arguments.len > 0) arguments[0] else .undefined, .undefined);
        return receiver;
    }

    fn nativeCollectionHas(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.collectionIndex(receiver, null);
        return .{ .boolean = self.collectionFind(index, canonicalCollectionKey(if (arguments.len > 0) arguments[0] else .undefined)) != null };
    }

    fn nativeMapGet(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.collectionIndex(receiver, true);
        const slot = self.collectionFind(index, canonicalCollectionKey(if (arguments.len > 0) arguments[0] else .undefined)) orelse return .undefined;
        return self.itemStorageConst(index)[slot + 1];
    }

    fn nativeCollectionDelete(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.collectionIndex(receiver, null);
        const slot = self.collectionFind(index, canonicalCollectionKey(if (arguments.len > 0) arguments[0] else .undefined)) orelse return .{ .boolean = false };
        self.itemStorage(index)[slot] = .undefined;
        self.setArrayItemPresent(index, slot, false);
        if (self.cells[index].host_tag == map_tag) {
            self.itemStorage(index)[slot + 1] = .undefined;
            self.setArrayItemPresent(index, slot + 1, false);
        }
        return .{ .boolean = true };
    }

    fn nativeCollectionClear(self: *Runtime, receiver: Value) Error!Value {
        const index = try self.collectionIndex(receiver, null);
        for (0..self.cells[index].item_count) |slot| {
            self.itemStorage(index)[slot] = .undefined;
            self.setArrayItemPresent(index, slot, false);
        }
        return .undefined;
    }

    fn nativeCollectionSize(self: *Runtime, receiver: Value) Error!Value {
        const index = try self.collectionIndex(receiver, null);
        const stride: usize = if (self.cells[index].host_tag == map_tag) 2 else 1;
        var size: usize = 0;
        var slot: usize = 0;
        while (slot < self.cells[index].item_count) : (slot += stride) if (self.arrayItemPresent(index, slot)) {
            size += 1;
        };
        return .{ .number = @floatFromInt(size) };
    }

    fn nativeMapGetOrInsert(self: *Runtime, receiver: Value, arguments: []const Value, computed: bool, program: *const Program) Error!Value {
        const index = try self.collectionIndex(receiver, true);
        const key = canonicalCollectionKey(if (arguments.len > 0) arguments[0] else .undefined);
        if (self.collectionFind(index, key)) |slot| return self.itemStorageConst(index)[slot + 1];
        var value = if (arguments.len > 1) arguments[1] else Value.undefined;
        if (computed) {
            if (!self.isCallableValue(value)) return error.TypeError;
            value = try self.call(program, value, .undefined, &.{key}, false);
        }
        try self.appendCollectionEntry(index, key, value);
        return value;
    }

    fn isRegisteredSymbol(self: *const Runtime, value: Value) bool {
        if (!self.isSymbolValue(value)) return false;
        for (self.symbol_registry[0..self.symbol_registry_count]) |entry|
            if (equals(self.stringBytes(entry.symbol), self.stringBytes(value.string))) return true;
        return false;
    }

    fn isWeakKey(self: *const Runtime, value: Value) bool {
        if (value == .cell) return value.cell < self.cells.len and self.cells[value.cell].occupied;
        return self.isSymbolValue(value) and !self.isRegisteredSymbol(value);
    }

    fn createWeakCollection(self: *Runtime, prototype: Value, map: bool) Error!Value {
        const result: Value = .{ .cell = try self.allocateCell(.object) };
        self.cells[result.cell].host_tag = if (map) weak_map_tag else weak_set_tag;
        self.cells[result.cell].prototype = try self.expectObject(prototype);
        return result;
    }

    fn nativeWeakCollectionConstructor(self: *Runtime, program: *const Program, default_prototype: Value, arguments: []const Value, map: bool, construct: bool, new_target: Value) Error!Value {
        if (!construct) return error.TypeError;
        const requested_prototype = if (new_target == .cell) try self.getProperty(new_target, "prototype") else .undefined;
        const prototype = if (requested_prototype == .cell) requested_prototype else default_prototype;
        const result = try self.createWeakCollection(prototype, map);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(result);
        if (arguments.len == 0 or arguments[0].isNullish()) return result;
        try self.pushRoot(arguments[0]);
        const adder = try self.getProperty(result, if (map) "set" else "add");
        if (!self.isCallableValue(adder)) return error.TypeError;
        try self.pushRoot(adder);
        var cursor = try self.openIterator(program, arguments[0]);
        try self.rootIterator(cursor);
        errdefer self.iteratorClose(program, &cursor) catch {};
        const iteration_root = self.root_count;
        while (true) {
            self.root_count = iteration_root;
            const step = try self.iteratorNext(program, &cursor);
            if (step.done) break;
            try self.pushRoot(step.value);
            if (map) {
                if (step.value != .cell) return error.TypeError;
                _ = try self.call(program, adder, result, &.{ try self.arrayLikeGet(step.value, 0), try self.arrayLikeGet(step.value, 1) }, false);
            } else _ = try self.call(program, adder, result, &.{step.value}, false);
        }
        return result;
    }

    fn nativeWeakMapSet(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.weakCollectionIndex(receiver, true);
        const key = if (arguments.len > 0) arguments[0] else Value.undefined;
        if (!self.isWeakKey(key)) return error.TypeError;
        try self.appendCollectionEntry(index, key, if (arguments.len > 1) arguments[1] else .undefined);
        return receiver;
    }

    fn nativeWeakSetAdd(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.weakCollectionIndex(receiver, false);
        const key = if (arguments.len > 0) arguments[0] else Value.undefined;
        if (!self.isWeakKey(key)) return error.TypeError;
        try self.appendCollectionEntry(index, key, .undefined);
        return receiver;
    }

    fn nativeWeakCollectionHas(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.weakCollectionIndex(receiver, null);
        const key = if (arguments.len > 0) arguments[0] else Value.undefined;
        return .{ .boolean = self.isWeakKey(key) and self.collectionFind(index, key) != null };
    }

    fn nativeWeakMapGet(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.weakCollectionIndex(receiver, true);
        const key = if (arguments.len > 0) arguments[0] else Value.undefined;
        if (!self.isWeakKey(key)) return .undefined;
        const slot = self.collectionFind(index, key) orelse return .undefined;
        return self.itemStorageConst(index)[slot + 1];
    }

    fn nativeWeakCollectionDelete(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.weakCollectionIndex(receiver, null);
        const key = if (arguments.len > 0) arguments[0] else Value.undefined;
        if (!self.isWeakKey(key)) return .{ .boolean = false };
        const slot = self.collectionFind(index, key) orelse return .{ .boolean = false };
        self.clearWeakCollectionEntry(index, slot);
        return .{ .boolean = true };
    }

    fn nativeWeakMapGetOrInsert(self: *Runtime, receiver: Value, arguments: []const Value, computed: bool, program: *const Program) Error!Value {
        const index = try self.weakCollectionIndex(receiver, true);
        const key = if (arguments.len > 0) arguments[0] else Value.undefined;
        if (!self.isWeakKey(key)) return error.TypeError;
        if (self.collectionFind(index, key)) |slot| return self.itemStorageConst(index)[slot + 1];
        var value = if (arguments.len > 1) arguments[1] else Value.undefined;
        if (computed) {
            if (!self.isCallableValue(value)) return error.TypeError;
            value = try self.call(program, value, .undefined, &.{key}, false);
        }
        try self.appendCollectionEntry(index, key, value);
        return value;
    }

    fn clearWeakCollectionEntry(self: *Runtime, index: u16, slot: usize) void {
        self.itemStorage(index)[slot] = .undefined;
        self.setArrayItemPresent(index, slot, false);
        if (self.cells[index].host_tag == weak_map_tag) {
            self.itemStorage(index)[slot + 1] = .undefined;
            self.setArrayItemPresent(index, slot + 1, false);
        }
    }

    fn nativeCollectionForEach(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.collectionIndex(receiver, null);
        if (arguments.len == 0 or !self.isCallableValue(arguments[0])) return error.TypeError;
        const this_arg = if (arguments.len > 1) arguments[1] else Value.undefined;
        const stride: usize = if (self.cells[index].host_tag == map_tag) 2 else 1;
        var slot: usize = 0;
        while (slot < self.cells[index].item_count) : (slot += stride) {
            if (!self.arrayItemPresent(index, slot)) continue;
            const key = self.itemStorageConst(index)[slot];
            const value = if (stride == 2) self.itemStorageConst(index)[slot + 1] else key;
            _ = try self.call(program, arguments[0], this_arg, &.{ value, key, receiver }, false);
        }
        return .undefined;
    }

    fn nativeCollectionIterator(self: *Runtime, receiver: Value, kind: u16) Error!Value {
        const index = try self.collectionIndex(receiver, null);
        const iterator: Value = .{ .cell = try self.allocateCell(.object) };
        self.cells[iterator.cell].host_tag = if (self.cells[index].host_tag == map_tag) map_iterator_tag else set_iterator_tag;
        self.cells[iterator.cell].prototype = if (self.cells[index].host_tag == map_tag) self.map_iterator_prototype else self.set_iterator_prototype;
        self.cells[iterator.cell].receiver = receiver;
        self.cells[iterator.cell].node = kind;
        self.cells[iterator.cell].array_length = 0;
        return iterator;
    }

    fn nativeCollectionIteratorNext(self: *Runtime, receiver: Value) Error!Value {
        const iterator = try self.expectObject(receiver);
        if (self.cells[iterator].host_tag != map_iterator_tag and self.cells[iterator].host_tag != set_iterator_tag) return error.TypeError;
        const source = self.cells[iterator].receiver;
        if (source == .undefined) return self.createIteratorResult(.undefined, true);
        const collection = try self.collectionIndex(source, self.cells[iterator].host_tag == map_iterator_tag);
        const stride: usize = if (self.cells[collection].host_tag == map_tag) 2 else 1;
        var slot = self.cells[iterator].array_length;
        while (slot < self.cells[collection].item_count and !self.arrayItemPresent(collection, slot)) slot += stride;
        if (slot >= self.cells[collection].item_count) {
            self.cells[iterator].receiver = .undefined;
            return self.createIteratorResult(.undefined, true);
        }
        self.cells[iterator].array_length = slot + stride;
        const key = self.itemStorageConst(collection)[slot];
        const value = if (stride == 2) self.itemStorageConst(collection)[slot + 1] else key;
        const result = switch (self.cells[iterator].node) {
            0 => key,
            1 => value,
            2 => try self.arrayFromValues(&.{ key, value }),
            else => return error.TypeError,
        };
        return self.createIteratorResult(result, false);
    }

    fn nativeMapGroupBy(self: *Runtime, program: *const Program, arguments: []const Value) Error!Value {
        if (arguments.len < 2 or !self.isCallableValue(arguments[1])) return error.TypeError;
        const map_constructor = self.global("Map") orelse return error.TypeError;
        const prototype = try self.getProperty(map_constructor, "prototype");
        const result = try self.createCollection(prototype, true);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(result);
        var cursor = try self.openIterator(program, arguments[0]);
        try self.rootIterator(cursor);
        errdefer self.iteratorClose(program, &cursor) catch {};
        var ordinal: usize = 0;
        const iteration_root = self.root_count;
        while (true) {
            self.root_count = iteration_root;
            const step = try self.iteratorNext(program, &cursor);
            if (step.done) break;
            try self.pushRoot(step.value);
            const key = try self.call(program, arguments[1], .undefined, &.{ step.value, .{ .number = @floatFromInt(ordinal) } }, false);
            try self.pushRoot(key);
            ordinal += 1;
            if (self.collectionFind(result.cell, canonicalCollectionKey(key))) |slot| {
                const group = self.itemStorageConst(result.cell)[slot + 1];
                try self.arrayLikeSet(group, try self.arrayLikeLength(group), step.value);
            } else {
                const group = try self.arrayFromValues(&.{step.value});
                try self.pushRoot(group);
                try self.appendCollectionEntry(result.cell, key, group);
            }
        }
        return result;
    }

    const SetRecord = struct { object: Value, size: usize, has: Value, keys: Value };

    fn getSetRecord(self: *Runtime, other: Value) Error!SetRecord {
        _ = try self.expectObject(other);
        const size_number = try self.toNumber(try self.getProperty(other, "size"));
        if (std.math.isNan(size_number) or size_number < 0) return error.RangeError;
        const has = try self.getProperty(other, "has");
        const keys = try self.getProperty(other, "keys");
        if (!self.isCallableValue(has) or !self.isCallableValue(keys)) return error.TypeError;
        const size: usize = if (!std.math.isFinite(size_number) or size_number > @as(f64, @floatFromInt(max_items))) max_items else @intFromFloat(@trunc(size_number));
        return .{ .object = other, .size = size, .has = has, .keys = keys };
    }

    fn createOrdinarySet(self: *Runtime) Error!Value {
        const constructor = self.global("Set") orelse return error.TypeError;
        return self.createCollection(try self.getProperty(constructor, "prototype"), false);
    }

    fn copySetEntries(self: *Runtime, source: u16, destination: u16) Error!void {
        var slot: usize = 0;
        while (slot < self.cells[source].item_count) : (slot += 1)
            if (self.arrayItemPresent(source, slot)) try self.appendCollectionEntry(destination, self.itemStorageConst(source)[slot], .undefined);
    }

    fn nativeSetComposition(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value, operation: SetComposition) Error!Value {
        const source = try self.collectionIndex(receiver, false);
        if (arguments.len == 0) return error.TypeError;
        const other = try self.getSetRecord(arguments[0]);
        const result = try self.createOrdinarySet();
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(result);
        if (operation == .union_set or operation == .symmetric_difference) try self.copySetEntries(source, result.cell);
        if (operation == .difference or operation == .intersection) {
            var slot: usize = 0;
            while (slot < self.cells[source].item_count) : (slot += 1) {
                if (!self.arrayItemPresent(source, slot)) continue;
                const value = self.itemStorageConst(source)[slot];
                const present = self.truthy(try self.call(program, other.has, other.object, &.{value}, false));
                if ((operation == .difference and !present) or (operation == .intersection and present)) try self.appendCollectionEntry(result.cell, value, .undefined);
            }
            return result;
        }
        const iterator = try self.call(program, other.keys, other.object, &.{}, false);
        var cursor = try self.openIterator(program, iterator);
        try self.rootIterator(cursor);
        errdefer self.iteratorClose(program, &cursor) catch {};
        const iteration_root = self.root_count;
        while (true) {
            self.root_count = iteration_root;
            const step = try self.iteratorNext(program, &cursor);
            if (step.done) break;
            try self.pushRoot(step.value);
            const found = self.collectionFind(result.cell, canonicalCollectionKey(step.value));
            if (operation == .symmetric_difference and found != null) {
                _ = try self.nativeCollectionDelete(result, &.{step.value});
            } else if (found == null) try self.appendCollectionEntry(result.cell, step.value, .undefined);
        }
        return result;
    }

    fn nativeSetRelation(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value, relation: SetRelation) Error!Value {
        const source = try self.collectionIndex(receiver, false);
        if (arguments.len == 0) return error.TypeError;
        const other = try self.getSetRecord(arguments[0]);
        if (relation == .subset or relation == .disjoint) {
            var slot: usize = 0;
            while (slot < self.cells[source].item_count) : (slot += 1) {
                if (!self.arrayItemPresent(source, slot)) continue;
                const present = self.truthy(try self.call(program, other.has, other.object, &.{self.itemStorageConst(source)[slot]}, false));
                if ((relation == .subset and !present) or (relation == .disjoint and present)) return .{ .boolean = false };
            }
            return .{ .boolean = true };
        }
        const iterator = try self.call(program, other.keys, other.object, &.{}, false);
        var cursor = try self.openIterator(program, iterator);
        try self.rootIterator(cursor);
        errdefer self.iteratorClose(program, &cursor) catch {};
        const iteration_root = self.root_count;
        while (true) {
            self.root_count = iteration_root;
            const step = try self.iteratorNext(program, &cursor);
            if (step.done) break;
            try self.pushRoot(step.value);
            if (self.collectionFind(source, canonicalCollectionKey(step.value)) == null) return .{ .boolean = false };
        }
        return .{ .boolean = true };
    }

    fn storeStringUnit(self: *Runtime, unit: u16) Error!StringRef {
        var buffer: [3]u8 = undefined;
        var length: usize = 0;
        try appendUtf8CodePoint(buffer[0..], &length, unit);
        return self.storeString(buffer[0..length]);
    }

    fn stringValue(self: *Runtime, receiver: Value) Error!StringRef {
        return switch (receiver) {
            .string => |ref| ref,
            .cell => |index| if (index < self.cells.len and self.cells[index].occupied and self.cells[index].host_tag == boxed_string_tag and self.cells[index].receiver == .string)
                self.cells[index].receiver.string
            else
                error.TypeError,
            else => error.TypeError,
        };
    }

    fn openDirectIterator(self: *Runtime, source: Value) Error!IteratorCursor {
        _ = try self.expectObject(source);
        const next_method = try self.getProperty(source, "next");
        if (!self.isCallableValue(next_method)) return error.TypeError;
        return .{
            .kind = .custom,
            .source = source,
            .iterator = source,
            .next_method = next_method,
        };
    }

    fn openFlattenableIterator(self: *Runtime, program: *const Program, source: Value, allow_string: bool) Error!IteratorCursor {
        if (source != .cell and !(allow_string and source == .string and !self.isSymbolValue(source))) return error.TypeError;
        const method = try self.getProperty(source, self.stringBytes(self.symbol_iterator));
        const iterator = if (method.isNullish()) blk: {
            if (source != .cell) return error.TypeError;
            break :blk source;
        } else blk: {
            if (!self.isCallableValue(method)) return error.TypeError;
            break :blk try self.call(program, method, source, &.{}, false);
        };
        return self.openDirectIterator(iterator);
    }

    fn closeDirectIterator(self: *Runtime, program: *const Program, source: Value) Error!void {
        _ = try self.expectObject(source);
        var cursor: IteratorCursor = .{
            .kind = .custom,
            .source = source,
            .iterator = source,
            .next_method = .undefined,
        };
        try self.iteratorClose(program, &cursor);
    }

    fn iteratorValidationError(self: *Runtime, program: *const Program, source: Value, original: Error) Error {
        const pending = self.pending_exception;
        self.closeDirectIterator(program, source) catch {};
        self.pending_exception = pending;
        return original;
    }

    fn closeIteratorPreservingError(self: *Runtime, program: *const Program, cursor: *IteratorCursor) void {
        const pending = self.pending_exception;
        self.iteratorClose(program, cursor) catch {};
        self.pending_exception = pending;
    }

    fn nativeIteratorConstructor(self: *Runtime, construct: bool, new_target: Value) Error!Value {
        if (!construct or (new_target == .cell and new_target.cell < self.cells.len and self.cells[new_target.cell].occupied and
            self.cells[new_target.cell].kind == .native_function and self.cells[new_target.cell].native_id == .iterator_constructor)) return error.TypeError;
        return .{ .cell = try self.allocateCell(.object) };
    }

    fn nativeIteratorConstructorGetter(self: *Runtime) Error!Value {
        return self.global("Iterator") orelse error.TypeError;
    }

    fn nativeIteratorAccessorSetter(self: *Runtime, receiver: Value, arguments: []const Value, tag: bool) Error!Value {
        const index = try self.expectObject(receiver);
        if (index == self.iterator_prototype) return error.TypeError;
        const name = if (tag) self.stringBytes(self.symbol_to_string_tag) else "constructor";
        try self.defineOwnDataProperty(receiver, name, if (arguments.len > 0) arguments[0] else .undefined);
        return .undefined;
    }

    fn createIteratorHelper(self: *Runtime, cursor: IteratorCursor, operand: Value, mode: IteratorHelperMode) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.rootIterator(cursor);
        try self.pushRoot(operand);
        const helper: Value = .{ .cell = try self.allocateCell(.object) };
        self.cells[helper.cell].host_tag = iterator_helper_tag;
        self.cells[helper.cell].prototype = self.iterator_helper_prototype;
        self.cells[helper.cell].node = @intFromEnum(mode);
        self.cells[helper.cell].receiver = cursor.iterator;
        self.cells[helper.cell].array_length = 0;
        self.cells[helper.cell].item_count = 4;
        self.itemStorage(helper.cell)[0] = cursor.next_method;
        self.itemStorage(helper.cell)[1] = operand;
        self.itemStorage(helper.cell)[2] = .undefined;
        self.itemStorage(helper.cell)[3] = .undefined;
        return helper;
    }

    fn nativeIteratorLazy(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value, mode: IteratorHelperMode) Error!Value {
        _ = try self.expectObject(receiver);
        var operand = if (arguments.len > 0) arguments[0] else Value.undefined;
        switch (mode) {
            .filter, .flat_map, .map => if (!self.isCallableValue(operand))
                return self.iteratorValidationError(program, receiver, error.TypeError),
            .drop, .take => {
                const number = self.toNumber(operand) catch |err| return self.iteratorValidationError(program, receiver, err);
                if (std.math.isNan(number)) return self.iteratorValidationError(program, receiver, error.RangeError);
                const integer = if (std.math.isFinite(number)) @trunc(number) else number;
                if (integer < 0) return self.iteratorValidationError(program, receiver, error.RangeError);
                operand = .{ .number = integer };
            },
        }
        const cursor = try self.openDirectIterator(receiver);
        return self.createIteratorHelper(cursor, operand, mode);
    }

    fn nativeIteratorFrom(self: *Runtime, program: *const Program, arguments: []const Value) Error!Value {
        const source = if (arguments.len > 0) arguments[0] else Value.undefined;
        const cursor = try self.openFlattenableIterator(program, source, true);
        if (self.prototypeChainContains(cursor.iterator.cell, self.iterator_prototype)) return cursor.iterator;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.rootIterator(cursor);
        const wrapper: Value = .{ .cell = try self.allocateCell(.object) };
        self.cells[wrapper.cell].host_tag = iterator_wrapper_tag;
        self.cells[wrapper.cell].prototype = self.iterator_wrapper_prototype;
        self.cells[wrapper.cell].receiver = cursor.iterator;
        self.cells[wrapper.cell].item_count = 1;
        self.itemStorage(wrapper.cell)[0] = cursor.next_method;
        return wrapper;
    }

    fn nativeIteratorConcat(self: *Runtime, program: *const Program, arguments: []const Value) Error!Value {
        _ = program;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        const helper: Value = .{ .cell = try self.allocateCell(.object) };
        try self.pushRoot(helper);
        self.cells[helper.cell].host_tag = iterator_concat_tag;
        self.cells[helper.cell].prototype = self.iterator_helper_prototype;
        for (arguments) |iterable| {
            _ = try self.expectObject(iterable);
            const method = try self.getProperty(iterable, self.stringBytes(self.symbol_iterator));
            if (method.isNullish() or !self.isCallableValue(method)) return error.TypeError;
            const count = self.cells[helper.cell].item_count;
            try self.ensureItemCapacity(helper.cell, count + 2);
            self.itemStorage(helper.cell)[count] = iterable;
            self.itemStorage(helper.cell)[count + 1] = method;
            self.cells[helper.cell].item_count = count + 2;
        }
        return helper;
    }

    fn iteratorCursorFromHelper(self: *Runtime, index: u16) Error!IteratorCursor {
        if (self.cells[index].receiver == .undefined or self.cells[index].item_count == 0) return error.TypeError;
        return .{
            .kind = .custom,
            .source = self.cells[index].receiver,
            .iterator = self.cells[index].receiver,
            .next_method = self.itemStorageConst(index)[0],
        };
    }

    fn finishIteratorHelper(self: *Runtime, index: u16) void {
        const count = self.cells[index].item_count;
        for (self.itemStorage(index)[0..count]) |*item| item.* = .undefined;
        self.cells[index].receiver = .undefined;
        self.cells[index].promise_value = .undefined;
        self.cells[index].array_length = if (self.cells[index].host_tag == iterator_concat_tag) count else 0;
    }

    fn nativeIteratorConcatNext(self: *Runtime, program: *const Program, index: u16) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = index });
        while (true) {
            try self.checkpoint();
            if (self.cells[index].receiver != .undefined) {
                var cursor: IteratorCursor = .{
                    .kind = .custom,
                    .source = self.cells[index].receiver,
                    .iterator = self.cells[index].receiver,
                    .next_method = self.cells[index].promise_value,
                };
                const step = self.iteratorNext(program, &cursor) catch |err| {
                    self.finishIteratorHelper(index);
                    return err;
                };
                if (!step.done) return self.createIteratorResult(step.value, false);
                self.cells[index].receiver = .undefined;
                self.cells[index].promise_value = .undefined;
                continue;
            }
            if (self.cells[index].array_length >= self.cells[index].item_count) {
                self.finishIteratorHelper(index);
                return self.createIteratorResult(.undefined, true);
            }
            const position = self.cells[index].array_length;
            const iterable = self.itemStorageConst(index)[position];
            const method = self.itemStorageConst(index)[position + 1];
            const iterator = self.call(program, method, iterable, &.{}, false) catch |err| {
                self.finishIteratorHelper(index);
                return err;
            };
            const cursor = self.openDirectIterator(iterator) catch |err| {
                self.finishIteratorHelper(index);
                return err;
            };
            self.cells[index].array_length = position + 2;
            self.cells[index].receiver = cursor.iterator;
            self.cells[index].promise_value = cursor.next_method;
        }
    }

    fn closeStoredIterator(self: *Runtime, program: *const Program, iterator: Value, next_method: Value) Error!void {
        if (iterator == .undefined) return;
        var cursor: IteratorCursor = .{
            .kind = .custom,
            .source = iterator,
            .iterator = iterator,
            .next_method = next_method,
        };
        try self.iteratorClose(program, &cursor);
    }

    fn nativeIteratorHelperNext(self: *Runtime, program: *const Program, receiver: Value) Error!Value {
        const index = try self.expectObject(receiver);
        const tag = self.cells[index].host_tag;
        if (tag != iterator_helper_tag and tag != iterator_concat_tag) return error.TypeError;
        if (tag == iterator_helper_tag and self.cells[index].item_count < 4) return error.TypeError;
        if (self.cells[index].binding_count != 0) return error.TypeError;
        self.cells[index].binding_count = 1;
        defer self.cells[index].binding_count = 0;
        if (tag == iterator_concat_tag) return self.nativeIteratorConcatNext(program, index);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        const mode: IteratorHelperMode = @enumFromInt(self.cells[index].node);
        while (true) {
            try self.checkpoint();
            if (self.cells[index].receiver == .undefined) return self.createIteratorResult(.undefined, true);
            if (mode == .flat_map and self.itemStorageConst(index)[2] != .undefined) {
                var inner: IteratorCursor = .{
                    .kind = .custom,
                    .source = self.itemStorageConst(index)[2],
                    .iterator = self.itemStorageConst(index)[2],
                    .next_method = self.itemStorageConst(index)[3],
                };
                const inner_step = self.iteratorNext(program, &inner) catch |err| {
                    var outer = try self.iteratorCursorFromHelper(index);
                    self.closeIteratorPreservingError(program, &outer);
                    self.finishIteratorHelper(index);
                    return err;
                };
                if (!inner_step.done) return self.createIteratorResult(inner_step.value, false);
                self.itemStorage(index)[2] = .undefined;
                self.itemStorage(index)[3] = .undefined;
                continue;
            }
            var cursor = try self.iteratorCursorFromHelper(index);
            if (mode == .take and self.itemStorageConst(index)[1].number == 0) {
                try self.iteratorClose(program, &cursor);
                self.finishIteratorHelper(index);
                return self.createIteratorResult(.undefined, true);
            }
            if (mode == .drop) {
                while (self.itemStorageConst(index)[1].number > 0) {
                    try self.checkpoint();
                    const dropped = self.iteratorNext(program, &cursor) catch |err| {
                        self.finishIteratorHelper(index);
                        return err;
                    };
                    if (dropped.done) {
                        self.finishIteratorHelper(index);
                        return self.createIteratorResult(.undefined, true);
                    }
                    if (std.math.isFinite(self.itemStorageConst(index)[1].number))
                        self.itemStorage(index)[1].number -= 1;
                }
            }
            if (mode == .take and std.math.isFinite(self.itemStorageConst(index)[1].number))
                self.itemStorage(index)[1].number -= 1;
            const step = self.iteratorNext(program, &cursor) catch |err| {
                self.finishIteratorHelper(index);
                return err;
            };
            if (step.done) {
                self.finishIteratorHelper(index);
                return self.createIteratorResult(.undefined, true);
            }
            switch (mode) {
                .drop, .take => return self.createIteratorResult(step.value, false),
                .map, .filter, .flat_map => {
                    const callback = self.itemStorageConst(index)[1];
                    const ordinal = self.cells[index].array_length;
                    const iteration_root = self.root_count;
                    try self.pushRoot(step.value);
                    const mapped = self.call(program, callback, .undefined, &.{ step.value, .{ .number = @floatFromInt(ordinal) } }, false) catch |err| {
                        self.root_count = iteration_root;
                        self.closeIteratorPreservingError(program, &cursor);
                        self.finishIteratorHelper(index);
                        return err;
                    };
                    self.cells[index].array_length = ordinal + 1;
                    if (mode == .map) return self.createIteratorResult(mapped, false);
                    if (mode == .filter) {
                        if (self.truthy(mapped)) return self.createIteratorResult(step.value, false);
                        self.root_count = iteration_root;
                        continue;
                    }
                    try self.pushRoot(mapped);
                    const inner = self.openFlattenableIterator(program, mapped, false) catch |err| {
                        self.root_count = iteration_root;
                        self.closeIteratorPreservingError(program, &cursor);
                        self.finishIteratorHelper(index);
                        return err;
                    };
                    self.itemStorage(index)[2] = inner.iterator;
                    self.itemStorage(index)[3] = inner.next_method;
                    self.root_count = iteration_root;
                },
            }
        }
    }

    fn nativeIteratorHelperReturn(self: *Runtime, program: *const Program, receiver: Value) Error!Value {
        const index = try self.expectObject(receiver);
        const tag = self.cells[index].host_tag;
        if (tag != iterator_helper_tag and tag != iterator_concat_tag) return error.TypeError;
        if (self.cells[index].binding_count != 0) return error.TypeError;
        self.cells[index].binding_count = 1;
        defer self.cells[index].binding_count = 0;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        var failure: ?Error = null;
        var failure_value: Value = .undefined;
        if (tag == iterator_helper_tag and self.cells[index].item_count >= 4 and self.itemStorageConst(index)[2] != .undefined) {
            self.closeStoredIterator(program, self.itemStorageConst(index)[2], self.itemStorageConst(index)[3]) catch |err| {
                failure = err;
                failure_value = self.pending_exception;
            };
        }
        if (self.cells[index].receiver != .undefined) {
            const next_method = if (tag == iterator_concat_tag) self.cells[index].promise_value else self.itemStorageConst(index)[0];
            self.closeStoredIterator(program, self.cells[index].receiver, next_method) catch |err| if (failure == null) {
                failure = err;
                failure_value = self.pending_exception;
            };
        }
        self.finishIteratorHelper(index);
        if (failure) |err| {
            self.pending_exception = failure_value;
            return err;
        }
        return self.createIteratorResult(.undefined, true);
    }

    fn nativeIteratorWrapperNext(self: *Runtime, program: *const Program, receiver: Value) Error!Value {
        const index = try self.expectObject(receiver);
        if (self.cells[index].host_tag != iterator_wrapper_tag or self.cells[index].item_count < 1) return error.TypeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        return self.call(program, self.itemStorageConst(index)[0], self.cells[index].receiver, &.{}, false);
    }

    fn nativeIteratorWrapperReturn(self: *Runtime, program: *const Program, receiver: Value) Error!Value {
        const index = try self.expectObject(receiver);
        if (self.cells[index].host_tag != iterator_wrapper_tag) return error.TypeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        const return_method = try self.getProperty(self.cells[index].receiver, "return");
        if (return_method.isNullish()) return self.createIteratorResult(.undefined, true);
        if (!self.isCallableValue(return_method)) return error.TypeError;
        return self.call(program, return_method, self.cells[index].receiver, &.{}, false);
    }

    fn nativeIteratorPredicate(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value, universal: bool, find: bool) Error!Value {
        _ = try self.expectObject(receiver);
        const callback = if (arguments.len > 0) arguments[0] else Value.undefined;
        if (!self.isCallableValue(callback)) return self.iteratorValidationError(program, receiver, error.TypeError);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        try self.pushRoot(callback);
        var cursor = try self.openDirectIterator(receiver);
        try self.rootIterator(cursor);
        var ordinal: usize = 0;
        const iteration_root = self.root_count;
        while (true) : (ordinal += 1) {
            try self.checkpoint();
            self.root_count = iteration_root;
            const step = try self.iteratorNext(program, &cursor);
            if (step.done) return if (find) .undefined else .{ .boolean = universal };
            try self.pushRoot(step.value);
            const selected_value = self.call(program, callback, .undefined, &.{ step.value, .{ .number = @floatFromInt(ordinal) } }, false) catch |err| {
                self.closeIteratorPreservingError(program, &cursor);
                return err;
            };
            const selected = self.truthy(selected_value);
            if (find and selected) {
                try self.iteratorClose(program, &cursor);
                return step.value;
            }
            if (!find and selected != universal) {
                try self.iteratorClose(program, &cursor);
                return .{ .boolean = !universal };
            }
        }
    }

