    fn nativeStringToWellFormed(self: *Runtime, receiver: Value) Error!Value {
        const source = (try self.toString(receiver)).bytes(self.strings[0..self.string_len]);
        const length = runtimeStringUnitCount(source);
        var buffer: [max_source_bytes]u8 = undefined;
        var output: usize = 0;
        var index: usize = 0;
        while (index < length) : (index += 1) {
            const unit = runtimeStringUnitAt(source, index).?;
            if (unit >= 0xd800 and unit <= 0xdbff) {
                if (runtimeStringUnitAt(source, index + 1)) |low| {
                    if (low >= 0xdc00 and low <= 0xdfff) {
                        const codepoint = 0x10000 + ((@as(u32, unit) - 0xd800) << 10) + (@as(u32, low) - 0xdc00);
                        try appendUtf8CodePoint(buffer[0..], &output, codepoint);
                        index += 1;
                        continue;
                    }
                }
                try appendUtf8CodePoint(buffer[0..], &output, 0xfffd);
            } else if (unit >= 0xdc00 and unit <= 0xdfff) {
                try appendUtf8CodePoint(buffer[0..], &output, 0xfffd);
            } else try appendUtf8CodePoint(buffer[0..], &output, unit);
        }
        return .{ .string = try self.storeString(buffer[0..output]) };
    }

    fn appendNormalizedCodepoint(self: *Runtime, count: *usize, codepoint: u21) Error!void {
        if (count.* >= self.unicode_scratch.len) return error.StringLimit;
        self.unicode_scratch[count.*] = codepoint;
        count.* += 1;
        const combining_class = unicode_string_normalization.combiningClass(codepoint);
        if (combining_class == 0) return;
        var position = count.* - 1;
        while (position > 0) {
            const previous_class = unicode_string_normalization.combiningClass(self.unicode_scratch[position - 1]);
            if (previous_class == 0 or previous_class <= combining_class) break;
            std.mem.swap(u21, &self.unicode_scratch[position - 1], &self.unicode_scratch[position]);
            position -= 1;
        }
    }

    fn appendStringDecomposition(self: *Runtime, count: *usize, codepoint: u21, compatibility: bool, depth: usize) Error!void {
        if (depth > 32) return error.RangeError;
        if (decomposeHangul(codepoint)) |hangul| {
            for (hangul.values[0..hangul.length]) |part| try self.appendStringDecomposition(count, part, compatibility, depth + 1);
            return;
        }
        if (unicode_string_normalization.decomposition(codepoint, compatibility)) |mapping| {
            for (mapping) |part| try self.appendStringDecomposition(count, part, compatibility, depth + 1);
            return;
        }
        try self.appendNormalizedCodepoint(count, codepoint);
    }

    fn composeStringNormalization(self: *Runtime, count: usize) usize {
        if (count == 0) return 0;
        var write: usize = 0;
        var starter: ?usize = null;
        var last_class: u8 = 0;
        for (self.unicode_scratch[0..count]) |codepoint| {
            const combining_class = unicode_string_normalization.combiningClass(codepoint);
            if (starter) |starter_index| {
                if (last_class == 0 or last_class < combining_class) {
                    if (composeUnicodePair(self.unicode_scratch[starter_index], codepoint)) |composed| {
                        self.unicode_scratch[starter_index] = composed;
                        continue;
                    }
                }
            }
            self.unicode_scratch[write] = codepoint;
            if (combining_class == 0) starter = write;
            last_class = combining_class;
            write += 1;
        }
        return write;
    }

    fn nativeStringNormalize(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const source = (try self.toString(receiver)).bytes(self.strings[0..self.string_len]);
        const form = if (arguments.len == 0 or arguments[0] == .undefined)
            "NFC"
        else
            (try self.toString(arguments[0])).bytes(self.strings[0..self.string_len]);
        const compatibility = equals(form, "NFKC") or equals(form, "NFKD");
        const compose = equals(form, "NFC") or equals(form, "NFKC");
        if (!compose and !compatibility and !equals(form, "NFD")) return error.RangeError;
        var count: usize = 0;
        var cursor: usize = 0;
        while (cursor < source.len) {
            const scalar = runtimeStringDecode(source, cursor);
            try self.appendStringDecomposition(&count, @intCast(scalar.value), compatibility, 0);
            cursor += scalar.length;
        }
        if (compose) count = self.composeStringNormalization(count);
        var buffer: [max_source_bytes]u8 = undefined;
        var output: usize = 0;
        for (self.unicode_scratch[0..count]) |codepoint| try appendUtf8CodePoint(buffer[0..], &output, codepoint);
        return .{ .string = try self.storeString(buffer[0..output]) };
    }

    fn nativeStringCase(self: *Runtime, receiver: Value, upper: bool) Error!Value {
        const source = (try self.toString(receiver)).bytes(self.strings[0..self.string_len]);
        var buffer: [max_source_bytes]u8 = undefined;
        var output: usize = 0;
        var cursor: usize = 0;
        var preceded_by_cased = false;
        while (cursor < source.len) {
            const scalar = runtimeStringDecode(source, cursor);
            const codepoint: u21 = @intCast(scalar.value);
            var mapping = if (upper) unicode_string_case.upper(codepoint) else unicode_string_case.lower(codepoint);
            if (!upper and codepoint == 0x03a3 and preceded_by_cased and runtimeStringFinalSigma(source, cursor + scalar.length))
                mapping = .{ .values = .{ 0x03c2, 0, 0 }, .length = 1 };
            for (mapping.values[0..mapping.length]) |mapped| try appendUtf8CodePoint(buffer[0..], &output, mapped);
            if (unicode_string_case.isCased(codepoint))
                preceded_by_cased = true
            else if (!unicode_string_case.isCaseIgnorable(codepoint))
                preceded_by_cased = false;
            cursor += scalar.length;
        }
        return .{ .string = try self.storeString(buffer[0..output]) };
    }

    fn appendSplitValue(self: *Runtime, array: u16, value: Value, limit: usize) Error!bool {
        if (self.cells[array].item_count >= limit) return false;
        try self.ensureItemCapacity(array, self.cells[array].item_count + 1);
        self.itemStorage(array)[self.cells[array].item_count] = value;
        self.setArrayItemPresent(array, self.cells[array].item_count, true);
        self.cells[array].item_count += 1;
        self.cells[array].array_length = self.cells[array].item_count;
        return self.cells[array].item_count < limit;
    }

    fn nativeStringSplitRegex(self: *Runtime, program: *const Program, source_ref: StringRef, separator: Value, limit: usize) Error!Value {
        const source = self.stringBytes(source_ref);
        const source_length = runtimeStringUnitCount(source);
        const pattern = (try self.toString(try self.getProperty(separator, "source"))).bytes(self.strings[0..self.string_len]);
        const original_flags = (try self.toString(try self.getProperty(separator, "flags"))).bytes(self.strings[0..self.string_len]);
        var flags_buffer: [8]u8 = undefined;
        var flags_length: usize = 0;
        for (original_flags) |flag| {
            if (flag == 'g' or flag == 'y') continue;
            flags_buffer[flags_length] = flag;
            flags_length += 1;
        }
        flags_buffer[flags_length] = 'g';
        flags_length += 1;
        const regex = try self.regexSpeciesClone(program, separator, pattern, flags_buffer[0..flags_length]);
        const array = try self.allocateCell(.array);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(regex);
        try self.pushRoot(.{ .cell = array });
        if (limit == 0) return .{ .cell = array };

        var cursor: usize = 0;
        var matched_any = false;
        var last_match_empty = false;
        while (self.cells[array].item_count < limit) {
            const result = try self.regexExec(program, regex, .{ .string = source_ref });
            if (result == .null_value) break;
            try self.pushRoot(result);
            const start = @as(usize, @intFromFloat(try self.toNumber(try self.getProperty(result, "index"))));
            const matched = (try self.toString(try self.arrayLikeGet(result, 0))).bytes(self.strings[0..self.string_len]);
            const matched_length = runtimeStringUnitCount(matched);
            const end = start + matched_length;
            if (matched_length == 0 and start == cursor) {
                if (start >= source_length) {
                    self.root_count -= 1;
                    last_match_empty = true;
                    break;
                }
                try self.setProperty(regex, "lastIndex", .{ .number = @floatFromInt(start + 1) });
                self.root_count -= 1;
                continue;
            }

            var segment_buffer: [max_source_bytes]u8 = undefined;
            var segment_length: usize = 0;
            try appendRuntimeStringUnits(segment_buffer[0..], &segment_length, source, cursor, start);
            if (!try self.appendSplitValue(array, .{ .string = try self.storeString(segment_buffer[0..segment_length]) }, limit)) {
                self.root_count -= 1;
                return .{ .cell = array };
            }
            const result_length = try self.arrayLikeLength(result);
            var capture_index: usize = 1;
            while (capture_index < result_length and self.cells[array].item_count < limit) : (capture_index += 1) {
                _ = try self.appendSplitValue(array, try self.arrayLikeGet(result, capture_index), limit);
            }
            matched_any = true;
            last_match_empty = matched_length == 0;
            cursor = end;
            if (matched_length == 0) try self.setProperty(regex, "lastIndex", .{ .number = @floatFromInt(start + 1) });
            self.root_count -= 1;
        }
        if (self.cells[array].item_count < limit and (cursor < source_length or !last_match_empty or !matched_any)) {
            var tail_buffer: [max_source_bytes]u8 = undefined;
            var tail_length: usize = 0;
            try appendRuntimeStringUnits(tail_buffer[0..], &tail_length, source, cursor, source_length);
            _ = try self.appendSplitValue(array, .{ .string = try self.storeString(tail_buffer[0..tail_length]) }, limit);
        }
        return .{ .cell = array };
    }

    fn nativeStringSplit(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        const source = (try self.toString(receiver)).bytes(self.strings[0..self.string_len]);
        const separator_argument = if (arguments.len > 0) arguments[0] else Value.undefined;
        if (try self.symbolMethod(separator_argument, self.symbol_split)) |method| {
            return self.call(program, method, separator_argument, &.{ .{ .string = try self.toString(receiver) }, if (arguments.len > 1) arguments[1] else .undefined }, false);
        }
        const limit: usize = if (arguments.len > 1) @min(@as(usize, toUint32(try self.toNumber(arguments[1]))), max_items) else max_items;
        const array = try self.allocateCell(.array);
        if (limit == 0) return .{ .cell = array };
        if (arguments.len == 0 or arguments[0] == .undefined) {
            self.itemStorage(array)[0] = .{ .string = try self.storeString(source) };
            self.setArrayItemPresent(array, 0, true);
            self.cells[array].item_count = 1;
            return .{ .cell = array };
        }
        const separator = (try self.toString(arguments[0])).bytes(self.strings[0..self.string_len]);
        const separator_length = runtimeStringUnitCount(separator);
        const source_length = runtimeStringUnitCount(source);
        if (separator_length == 0) {
            var unit_index: usize = 0;
            while (unit_index < source_length and self.cells[array].item_count < limit) : (unit_index += 1) {
                try self.ensureItemCapacity(array, self.cells[array].item_count + 1);
                self.itemStorage(array)[self.cells[array].item_count] = .{ .string = try self.storeStringUnit(runtimeStringUnitAt(source, unit_index).?) };
                self.setArrayItemPresent(array, self.cells[array].item_count, true);
                self.cells[array].item_count += 1;
            }
            return .{ .cell = array };
        }
        var start: usize = 0;
        while (self.cells[array].item_count < limit) {
            try self.ensureItemCapacity(array, self.cells[array].item_count + 1);
            const found = runtimeStringIndexOfUnits(source, separator, start);
            const end = found orelse source_length;
            var buffer: [max_source_bytes]u8 = undefined;
            var output: usize = 0;
            try appendRuntimeStringUnits(buffer[0..], &output, source, start, end);
            self.itemStorage(array)[self.cells[array].item_count] = .{ .string = try self.storeString(buffer[0..output]) };
            self.setArrayItemPresent(array, self.cells[array].item_count, true);
            self.cells[array].item_count += 1;
            if (found == null) break;
            start = end + separator_length;
        }
        return .{ .cell = array };
    }

    fn appendStringSubstitution(output: []u8, output_len: *usize, replacement: []const u8, source: []const u8, matched: []const u8, start: usize, end: usize) Error!void {
        var cursor: usize = 0;
        while (cursor < replacement.len) {
            if (replacement[cursor] != '$' or cursor + 1 >= replacement.len) {
                try appendBytes(output, output_len, replacement[cursor .. cursor + 1]);
                cursor += 1;
                continue;
            }
            const marker = replacement[cursor + 1];
            switch (marker) {
                '$' => try appendBytes(output, output_len, "$"),
                '&' => try appendBytes(output, output_len, matched),
                '`' => try appendRuntimeStringUnits(output, output_len, source, 0, start),
                '\'' => try appendRuntimeStringUnits(output, output_len, source, end, runtimeStringUnitCount(source)),
                else => {
                    try appendBytes(output, output_len, replacement[cursor .. cursor + 1]);
                    cursor += 1;
                    continue;
                },
            }
            cursor += 2;
        }
    }

    fn appendStringReplacement(self: *Runtime, program: *const Program, output: []u8, output_len: *usize, replacement: Value, source_ref: StringRef, matched: []const u8, start: usize, end: usize) Error!void {
        const source = self.stringBytes(source_ref);
        if (self.isCallableValue(replacement)) {
            const matched_ref = try self.storeString(matched);
            const result = try self.call(program, replacement, .undefined, &.{
                .{ .string = matched_ref },
                .{ .number = @floatFromInt(start) },
                .{ .string = source_ref },
            }, false);
            try appendBytes(output, output_len, (try self.toString(result)).bytes(self.strings[0..self.string_len]));
            return;
        }
        const replacement_text = (try self.toString(replacement)).bytes(self.strings[0..self.string_len]);
        try appendStringSubstitution(output, output_len, replacement_text, source, matched, start, end);
    }

    fn appendRegexReplacement(self: *Runtime, program: *const Program, output: []u8, output_len: *usize, replacement: Value, source_ref: StringRef, result: Value, start: usize, end: usize) Error!void {
        const source = self.stringBytes(source_ref);
        const result_length = try self.arrayLikeLength(result);
        const matched_value = try self.getProperty(result, "0");
        const matched = (try self.toString(matched_value)).bytes(self.strings[0..self.string_len]);
        const groups = try self.getProperty(result, "groups");
        if (self.isCallableValue(replacement)) {
            var callback_arguments: [max_regex_captures + 4]Value = undefined;
            const capture_count = result_length -| 1;
            callback_arguments[0] = matched_value;
            for (0..capture_count) |capture_index| callback_arguments[capture_index + 1] = try self.arrayLikeGet(result, capture_index + 1);
            callback_arguments[capture_count + 1] = .{ .number = @floatFromInt(start) };
            callback_arguments[capture_count + 2] = .{ .string = source_ref };
            var argument_count = capture_count + 3;
            if (groups != .undefined) {
                callback_arguments[argument_count] = groups;
                argument_count += 1;
            }
            const callback_result = try self.call(program, replacement, .undefined, callback_arguments[0..argument_count], false);
            try appendBytes(output, output_len, (try self.toString(callback_result)).bytes(self.strings[0..self.string_len]));
            return;
        }

        const replacement_text = (try self.toString(replacement)).bytes(self.strings[0..self.string_len]);
        var cursor: usize = 0;
        while (cursor < replacement_text.len) {
            if (replacement_text[cursor] != '$' or cursor + 1 >= replacement_text.len) {
                try appendBytes(output, output_len, replacement_text[cursor .. cursor + 1]);
                cursor += 1;
                continue;
            }
            const marker = replacement_text[cursor + 1];
            if (marker == '$') {
                try appendBytes(output, output_len, "$");
                cursor += 2;
                continue;
            }
            if (marker == '&') {
                try appendBytes(output, output_len, matched);
                cursor += 2;
                continue;
            }
            if (marker == '`') {
                try appendRuntimeStringUnits(output, output_len, source, 0, start);
                cursor += 2;
                continue;
            }
            if (marker == '\'') {
                try appendRuntimeStringUnits(output, output_len, source, end, runtimeStringUnitCount(source));
                cursor += 2;
                continue;
            }
            if (marker >= '1' and marker <= '9') {
                var capture_number: usize = marker - '0';
                var consumed: usize = 2;
                if (cursor + 2 < replacement_text.len and replacement_text[cursor + 2] >= '0' and replacement_text[cursor + 2] <= '9') {
                    const two_digit = capture_number * 10 + replacement_text[cursor + 2] - '0';
                    if (two_digit < result_length) {
                        capture_number = two_digit;
                        consumed = 3;
                    }
                }
                if (capture_number < result_length) {
                    const capture = try self.arrayLikeGet(result, capture_number);
                    if (capture != .undefined) try appendBytes(output, output_len, (try self.toString(capture)).bytes(self.strings[0..self.string_len]));
                    cursor += consumed;
                    continue;
                }
            }
            if (marker == '<' and groups != .undefined) {
                if (std.mem.indexOfScalarPos(u8, replacement_text, cursor + 2, '>')) |name_end| {
                    const capture = try self.getProperty(groups, replacement_text[cursor + 2 .. name_end]);
                    if (capture != .undefined) try appendBytes(output, output_len, (try self.toString(capture)).bytes(self.strings[0..self.string_len]));
                    cursor = name_end + 1;
                    continue;
                }
            }
            try appendBytes(output, output_len, replacement_text[cursor .. cursor + 1]);
            cursor += 1;
        }
    }

    fn nativeStringReplaceRegex(self: *Runtime, program: *const Program, source_ref: StringRef, regex: Value, replacement: Value, requested_all: bool) Error!Value {
        const source = self.stringBytes(source_ref);
        const source_length = runtimeStringUnitCount(source);
        const flags = (try self.toString(try self.getProperty(regex, "flags"))).bytes(self.strings[0..self.string_len]);
        const regex_global = std.mem.indexOfScalar(u8, flags, 'g') != null;
        if (requested_all and !regex_global) return error.TypeError;
        if (regex_global) try self.setProperty(regex, "lastIndex", .{ .number = 0 });
        var output: [max_source_bytes]u8 = undefined;
        var output_len: usize = 0;
        var cursor: usize = 0;
        var found_any = false;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        while (true) {
            const result = try self.regexExec(program, regex, .{ .string = source_ref });
            if (result == .null_value) break;
            try self.pushRoot(result);
            found_any = true;
            const start = @as(usize, @intFromFloat(try self.toNumber(try self.getProperty(result, "index"))));
            const matched_value = try self.getProperty(result, "0");
            const matched = (try self.toString(matched_value)).bytes(self.strings[0..self.string_len]);
            const end = start + runtimeStringUnitCount(matched);
            try appendRuntimeStringUnits(output[0..], &output_len, source, cursor, start);
            try self.appendRegexReplacement(program, output[0..], &output_len, replacement, source_ref, result, start, end);
            cursor = end;
            if (!regex_global) break;
            if (end == start) try self.setProperty(regex, "lastIndex", .{ .number = @floatFromInt(@min(source_length + 1, end + 1)) });
            self.root_count -= 1;
        }
        if (!found_any) return .{ .string = try self.storeString(source) };
        try appendRuntimeStringUnits(output[0..], &output_len, source, cursor, source_length);
        return .{ .string = try self.storeString(output[0..output_len]) };
    }

    fn nativeStringReplace(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value, requested_all: bool) Error!Value {
        const source_ref = try self.toString(receiver);
        const source = self.stringBytes(source_ref);
        if (arguments.len == 0) return .{ .string = try self.storeString(source) };
        const replacement = if (arguments.len > 1) arguments[1] else Value.undefined;
        if (requested_all and try self.isRegExpValue(arguments[0])) {
            const flags = (try self.toString(try self.getProperty(arguments[0], "flags"))).bytes(self.strings[0..self.string_len]);
            if (std.mem.indexOfScalar(u8, flags, 'g') == null) return error.TypeError;
        }
        if (try self.symbolMethod(arguments[0], self.symbol_replace)) |method| {
            return self.call(program, method, arguments[0], &.{ .{ .string = source_ref }, replacement }, false);
        }
        var needle_buffer: [256]u8 = undefined;
        var needle_len: usize = 0;
        const replace_all = requested_all;
        const needle_text = (try self.toString(arguments[0])).bytes(self.strings[0..self.string_len]);
        if (needle_text.len > needle_buffer.len) return error.StringLimit;
        if (needle_text.len > 0) @memcpy(needle_buffer[0..needle_text.len], needle_text);
        needle_len = needle_text.len;
        const needle = needle_buffer[0..needle_len];
        const source_length = runtimeStringUnitCount(source);
        const needle_length = runtimeStringUnitCount(needle);
        var output: [max_source_bytes]u8 = undefined;
        var output_len: usize = 0;
        if (needle_length == 0) {
            const boundary_count = if (replace_all) source_length + 1 else 1;
            var previous: usize = 0;
            for (0..boundary_count) |boundary| {
                try appendRuntimeStringUnits(output[0..], &output_len, source, previous, boundary);
                try self.appendStringReplacement(program, output[0..], &output_len, replacement, source_ref, needle, boundary, boundary);
                previous = boundary;
            }
            try appendRuntimeStringUnits(output[0..], &output_len, source, previous, source_length);
            return .{ .string = try self.storeString(output[0..output_len]) };
        }
        var cursor: usize = 0;
        var found_any = false;
        while (runtimeStringIndexOfUnits(source, needle, cursor)) |match_start| {
            found_any = true;
            try appendRuntimeStringUnits(output[0..], &output_len, source, cursor, match_start);
            try self.appendStringReplacement(program, output[0..], &output_len, replacement, source_ref, needle, match_start, match_start + needle_length);
            cursor = match_start + needle_length;
            if (!replace_all) break;
        }
        if (!found_any) return .{ .string = try self.storeString(source) };
        try appendRuntimeStringUnits(output[0..], &output_len, source, cursor, source_length);
        return .{ .string = try self.storeString(output[0..output_len]) };
    }

    fn nativeStringSubstr(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const source = (try self.toString(receiver)).bytes(self.strings[0..self.string_len]);
        const source_length = runtimeStringUnitCount(source);
        const start = relativeStringIndex(if (arguments.len > 0) try self.toNumber(arguments[0]) else 0, source_length);
        const requested = if (arguments.len > 1 and arguments[1] != .undefined) try self.toNumber(arguments[1]) else @as(f64, @floatFromInt(source_length - start));
        const count = if (std.math.isNan(requested) or requested <= 0)
            0
        else if (!std.math.isFinite(requested))
            source_length - start
        else
            @min(source_length - start, @as(usize, @intFromFloat(@trunc(requested))));
        var buffer: [max_source_bytes]u8 = undefined;
        var output: usize = 0;
        try appendRuntimeStringUnits(buffer[0..], &output, source, start, start + count);
        return .{ .string = try self.storeString(buffer[0..output]) };
    }

    fn nativeStringIterator(self: *Runtime, receiver: Value) Error!Value {
        const source = Value{ .string = try self.toString(receiver) };
        const iterator: Value = .{ .cell = try self.allocateCell(.string_iterator) };
        self.cells[iterator.cell].receiver = source;
        self.cells[iterator.cell].array_length = 0;
        return iterator;
    }

    fn nativeStringIteratorNext(self: *Runtime, receiver: Value) Error!Value {
        const iterator = try self.expectCellKind(receiver, .string_iterator);
        const source = self.cells[iterator].receiver;
        if (source != .string) return self.createIteratorResult(.undefined, true);
        const element_index = self.cells[iterator].array_length;
        const bytes = self.stringBytes(source.string);
        const element = runtimeStringElementAt(bytes, element_index) orelse {
            self.cells[iterator].receiver = .undefined;
            return self.createIteratorResult(.undefined, true);
        };
        self.cells[iterator].array_length = element_index + 1;
        return self.createIteratorResult(.{ .string = try self.storeString(element) }, false);
    }

    fn nativeStringHtml(self: *Runtime, receiver: Value, arguments: []const Value, tag: []const u8, attribute: ?[]const u8) Error!Value {
