        const source = try self.arrayBufferStorage(receiver);
        if (start + new_length > source.byte_length) return error.TypeError;
        const result = try self.createArrayBuffer(new_length, new_length, true);
        const target = try self.arrayBufferStorage(result);
        if (new_length > 0) @memcpy(arrayBufferBytes(target)[0..new_length], arrayBufferBytes(source)[start .. start + new_length]);
        return result;
    }

    fn nativeArrayBufferSlice(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        _ = try self.arrayBufferStorage(receiver);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        const original_length = (try self.arrayBufferStorage(receiver)).byte_length;
        const start = arrayRelativeIndex(try self.toNumber(if (arguments.len > 0) arguments[0] else .undefined), original_length);
        const end = if (arguments.len < 2 or arguments[1] == .undefined)
            original_length
        else
            arrayRelativeIndex(try self.toNumber(arguments[1]), original_length);
        const new_length = end -| start;

        var constructor = try self.getProperty(receiver, "constructor");
        try self.pushRoot(constructor);
        if (constructor == .cell) {
            constructor = try self.getProperty(constructor, self.stringBytes(self.symbol_species));
            try self.pushRoot(constructor);
            if (constructor == .null_value) constructor = .undefined;
        }
        const result = if (constructor == .undefined)
            try self.createArrayBuffer(new_length, new_length, false)
        else blk: {
            if (!self.isConstructor(constructor)) return error.TypeError;
            break :blk try self.call(program, constructor, .undefined, &.{.{ .number = @floatFromInt(new_length) }}, true);
        };
        try self.pushRoot(result);
        if (!self.isArrayBuffer(result) or self.strictEqual(result, receiver)) return error.TypeError;
        const target = try self.arrayBufferStorage(result);
        if (target.byte_length < new_length) return error.TypeError;
        const source = try self.arrayBufferStorage(receiver);
        if (start + new_length > source.byte_length) return error.TypeError;
        if (new_length > 0) @memcpy(arrayBufferBytes(target)[0..new_length], arrayBufferBytes(source)[start .. start + new_length]);
        return result;
    }

    fn nativeSharedArrayBufferConstructor(self: *Runtime, arguments: []const Value) Error!Value {
        const length = try self.toIndex(if (arguments.len > 0) arguments[0] else .undefined);
        var max_length = length;
        if (arguments.len > 1 and arguments[1] == .cell) {
            const option = try self.getProperty(arguments[1], "maxByteLength");
            if (option != .undefined) max_length = try self.toIndex(option);
        }
        if (max_length < length) return error.RangeError;
        return self.createSharedArrayBuffer(length, max_length);
    }

    const SharedArrayBufferGetter = enum { byte_length, max_byte_length, growable };

    fn nativeSharedArrayBufferGetter(self: *Runtime, receiver: Value, getter: SharedArrayBufferGetter) Error!Value {
        _ = try self.sharedArrayBufferIndex(receiver);
        const storage = try self.bufferStorage(receiver);
        return switch (getter) {
            .byte_length => .{ .number = @floatFromInt(storage.byte_length) },
            .max_byte_length => .{ .number = @floatFromInt(storage.max_byte_length) },
            .growable => .{ .boolean = storage.resizable },
        };
    }

    fn nativeSharedArrayBufferGrow(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.sharedArrayBufferIndex(receiver);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        const new_length = try self.toIndex(if (arguments.len > 0) arguments[0] else .undefined);
        const storage = try self.bufferStorage(receiver);
        if (!storage.resizable) return error.TypeError;
        if (new_length < storage.byte_length or new_length > storage.max_byte_length) return error.RangeError;
        if (new_length != storage.byte_length) try self.replaceArrayBufferStorage(index, new_length);
        return .undefined;
    }

    fn nativeSharedArrayBufferSlice(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        _ = try self.sharedArrayBufferIndex(receiver);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        const original_length = (try self.bufferStorage(receiver)).byte_length;
        const start = arrayRelativeIndex(try self.toNumber(if (arguments.len > 0) arguments[0] else .undefined), original_length);
        const end = if (arguments.len < 2 or arguments[1] == .undefined)
            original_length
        else
            arrayRelativeIndex(try self.toNumber(arguments[1]), original_length);
        const new_length = end -| start;

        var constructor = try self.getProperty(receiver, "constructor");
        try self.pushRoot(constructor);
        if (constructor == .cell) {
            constructor = try self.getProperty(constructor, self.stringBytes(self.symbol_species));
            try self.pushRoot(constructor);
            if (constructor == .null_value) constructor = .undefined;
        }
        const result = if (constructor == .undefined)
            try self.createSharedArrayBuffer(new_length, new_length)
        else blk: {
            if (!self.isConstructor(constructor)) return error.TypeError;
            break :blk try self.call(program, constructor, .undefined, &.{.{ .number = @floatFromInt(new_length) }}, true);
        };
        try self.pushRoot(result);
        if (!self.isSharedArrayBuffer(result) or self.strictEqual(result, receiver)) return error.TypeError;
        const target = try self.bufferStorage(result);
        if (target.byte_length < new_length) return error.TypeError;
        const source = try self.bufferStorage(receiver);
        if (start + new_length > source.byte_length) return error.TypeError;
        if (new_length > 0) @memcpy(arrayBufferBytes(target)[0..new_length], arrayBufferBytes(source)[start .. start + new_length]);
        return result;
    }

    const TypedArrayElement = enum(u8) {
        int8,
        uint8,
        uint8_clamped,
        int16,
        uint16,
        int32,
        uint32,
        float16,
        float32,
        float64,
        bigint64,
        biguint64,

        fn byteSize(self: TypedArrayElement) usize {
            return switch (self) {
                .int8, .uint8, .uint8_clamped => 1,
                .int16, .uint16, .float16 => 2,
                .int32, .uint32, .float32 => 4,
                .float64, .bigint64, .biguint64 => 8,
            };
        }

        fn name(self: TypedArrayElement) []const u8 {
            return switch (self) {
                .int8 => "Int8Array",
                .uint8 => "Uint8Array",
                .uint8_clamped => "Uint8ClampedArray",
                .int16 => "Int16Array",
                .uint16 => "Uint16Array",
                .int32 => "Int32Array",
                .uint32 => "Uint32Array",
                .float16 => "Float16Array",
                .float32 => "Float32Array",
                .float64 => "Float64Array",
                .bigint64 => "BigInt64Array",
                .biguint64 => "BigUint64Array",
            };
        }

        fn isBigInt(self: TypedArrayElement) bool {
            return self == .bigint64 or self == .biguint64;
        }

        fn dataViewElement(self: TypedArrayElement) DataViewElement {
            return switch (self) {
                .int8 => .int8,
                .uint8, .uint8_clamped => .uint8,
                .int16 => .int16,
                .uint16 => .uint16,
                .int32 => .int32,
                .uint32 => .uint32,
                .float16 => .float16,
                .float32 => .float32,
                .float64 => .float64,
                .bigint64 => .bigint64,
                .biguint64 => .biguint64,
            };
        }
    };

    const DataViewElement = enum {
        int8,
        uint8,
        int16,
        uint16,
        int32,
        uint32,
        float16,
        float32,
        float64,
        bigint64,
        biguint64,

        fn byteSize(self: DataViewElement) usize {
            return switch (self) {
                .int8, .uint8 => 1,
                .int16, .uint16, .float16 => 2,
                .int32, .uint32, .float32 => 4,
                .float64, .bigint64, .biguint64 => 8,
            };
        }

        fn isBigInt(self: DataViewElement) bool {
            return self == .bigint64 or self == .biguint64;
        }
    };

    const DataViewGetter = enum { buffer, byte_length, byte_offset };
    const DataViewRange = struct { storage: *ArrayBufferStorage, offset: usize, length: usize };

    fn isDataView(self: *const Runtime, value: Value) bool {
        return value == .cell and value.cell < self.cells.len and self.cells[value.cell].occupied and
            self.cells[value.cell].host_tag == data_view_tag;
    }

    fn dataViewIndex(self: *const Runtime, value: Value) Error!u16 {
        if (!self.isDataView(value)) return error.TypeError;
        return value.cell;
    }

    fn dataViewRange(self: *Runtime, index: u16) Error!DataViewRange {
        const cell = &self.cells[index];
        const storage = try self.bufferStorage(cell.receiver);
        const offset = cell.item_count;
        if (offset > storage.byte_length) return error.TypeError;
        const length = if (cell.array_length_writable) storage.byte_length - offset else cell.array_length;
        if (offset + length > storage.byte_length) return error.TypeError;
        return .{ .storage = storage, .offset = offset, .length = length };
    }

    fn nativeDataViewConstructor(self: *Runtime, arguments: []const Value) Error!Value {
        if (arguments.len == 0) return error.TypeError;
        const buffer = arguments[0];
        _ = try self.bufferStorage(buffer);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(buffer);
        const offset = try self.toIndex(if (arguments.len > 1) arguments[1] else .undefined);
        var storage = try self.bufferStorage(buffer);
        if (offset > storage.byte_length) return error.RangeError;
        const length_tracking = arguments.len < 3 or arguments[2] == .undefined;
        const length = if (length_tracking) storage.byte_length - offset else try self.toIndex(arguments[2]);
        storage = try self.bufferStorage(buffer);
        if (offset > storage.byte_length or length > storage.byte_length - offset) return error.RangeError;
        const object: Value = .{ .cell = try self.allocateCell(.object) };
        self.cells[object.cell].host_tag = data_view_tag;
        self.cells[object.cell].receiver = buffer;
        self.cells[object.cell].item_count = offset;
        self.cells[object.cell].array_length = length;
        self.cells[object.cell].array_length_writable = length_tracking and storage.resizable;
        self.cells[object.cell].prototype = self.data_view_prototype;
        return object;
    }

    fn nativeDataViewGetter(self: *Runtime, receiver: Value, getter: DataViewGetter) Error!Value {
        const index = try self.dataViewIndex(receiver);
        if (getter == .buffer) return self.cells[index].receiver;
        const range = self.dataViewRange(index) catch |err| switch (err) {
            error.TypeError => return .{ .number = 0 },
            else => return err,
        };
        return .{ .number = @floatFromInt(if (getter == .byte_length) range.length else range.offset) };
    }

    fn readDataViewBits(bytes: []const u8, offset: usize, size: usize, little_endian: bool) u64 {
        var value: u64 = 0;
        if (little_endian) {
            for (bytes[offset .. offset + size], 0..) |byte, index| value |= @as(u64, byte) << @intCast(index * 8);
        } else {
            for (bytes[offset .. offset + size]) |byte| value = (value << 8) | byte;
        }
        return value;
    }

    fn writeDataViewBits(bytes: []u8, offset: usize, size: usize, little_endian: bool, value: u64) void {
        for (0..size) |index| {
            const shift = if (little_endian) index * 8 else (size - index - 1) * 8;
            bytes[offset + index] = @truncate(value >> @intCast(shift));
        }
    }

    fn createBigIntFromUnsigned(self: *Runtime, value: u64) Error!Value {
        if (value == 0) return self.createBigIntFromScalar(0);
        var limbs = [_]BigIntLimb{@intCast(value)};
        return self.createBigIntFromConst(.{ .limbs = limbs[0..], .positive = true });
    }

    fn nativeDataViewGet(self: *Runtime, receiver: Value, arguments: []const Value, element: DataViewElement) Error!Value {
        const index = try self.dataViewIndex(receiver);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        const offset = try self.toIndex(if (arguments.len > 0) arguments[0] else .undefined);
        const range = try self.dataViewRange(index);
        const size = element.byteSize();
        if (offset > range.length or size > range.length - offset) return error.RangeError;
        const little_endian = size > 1 and arguments.len > 1 and self.truthy(arguments[1]);
        const bits = readDataViewBits(arrayBufferBytes(range.storage), range.offset + offset, size, little_endian);
        return switch (element) {
            .int8 => .{ .number = @floatFromInt(@as(i8, @bitCast(@as(u8, @truncate(bits))))) },
            .uint8 => .{ .number = @floatFromInt(@as(u8, @truncate(bits))) },
            .int16 => .{ .number = @floatFromInt(@as(i16, @bitCast(@as(u16, @truncate(bits))))) },
            .uint16 => .{ .number = @floatFromInt(@as(u16, @truncate(bits))) },
            .int32 => .{ .number = @floatFromInt(@as(i32, @bitCast(@as(u32, @truncate(bits))))) },
            .uint32 => .{ .number = @floatFromInt(@as(u32, @truncate(bits))) },
            .float16 => .{ .number = @floatCast(@as(f16, @bitCast(@as(u16, @truncate(bits))))) },
            .float32 => .{ .number = @floatCast(@as(f32, @bitCast(@as(u32, @truncate(bits))))) },
            .float64 => .{ .number = @bitCast(bits) },
            .bigint64 => self.createBigIntFromScalar(@bitCast(bits)),
            .biguint64 => self.createBigIntFromUnsigned(bits),
        };
    }

    fn nativeDataViewSet(self: *Runtime, receiver: Value, arguments: []const Value, element: DataViewElement) Error!Value {
        const index = try self.dataViewIndex(receiver);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        const offset = try self.toIndex(if (arguments.len > 0) arguments[0] else .undefined);
        const argument = if (arguments.len > 1) arguments[1] else .undefined;
        const bits: u64 = if (element.isBigInt()) blk: {
            const bigint = try self.toBigInt(argument, false);
            try self.pushRoot(bigint);
            const truncated = try self.nativeBigIntAsN(&.{ .{ .number = 64 }, bigint }, false);
            break :blk (try self.bigIntConst(truncated)).toInt(u64) catch return error.RangeError;
        } else switch (element) {
            .int8, .uint8 => @as(u8, @truncate(toUint32(try self.toNumber(argument)))),
            .int16, .uint16 => @as(u16, @truncate(toUint32(try self.toNumber(argument)))),
            .int32, .uint32 => toUint32(try self.toNumber(argument)),
            .float16 => @as(u16, @bitCast(@as(f16, @floatCast(try self.toNumber(argument))))),
            .float32 => @as(u32, @bitCast(@as(f32, @floatCast(try self.toNumber(argument))))),
            .float64 => @bitCast(try self.toNumber(argument)),
            else => unreachable,
        };
        const range = try self.dataViewRange(index);
        if (range.storage.immutable) return error.TypeError;
        const size = element.byteSize();
        if (offset > range.length or size > range.length - offset) return error.RangeError;
        const little_endian = size > 1 and arguments.len > 2 and self.truthy(arguments[2]);
        writeDataViewBits(arrayBufferBytes(range.storage), range.offset + offset, size, little_endian, bits);
        return .undefined;
    }

    const TypedArrayGetter = enum { buffer, byte_length, byte_offset, length };
    const TypedArrayRange = struct {
        storage: *ArrayBufferStorage,
        offset: usize,
        length: usize,
        element: TypedArrayElement,
    };
    const TypedArrayPropertyIndex = union(enum) {
        ordinary,
        invalid_numeric,
        index: usize,
    };

    fn typedArrayPropertyIndex(name: []const u8) TypedArrayPropertyIndex {
        if (name.len != 0 and (name.len == 1 or name[0] != '0')) {
            var digits = true;
            for (name) |byte| {
                if (!std.ascii.isDigit(byte)) {
                    digits = false;
                    break;
                }
            }
            if (digits) {
                const index = std.fmt.parseInt(usize, name, 10) catch return .invalid_numeric;
                const number = std.fmt.parseFloat(f64, name) catch return .ordinary;
                var canonical_buffer: [128]u8 = undefined;
                const canonical = std.fmt.bufPrint(canonical_buffer[0..], "{d}", .{number}) catch return .ordinary;
                if (!equals(canonical, name)) return .ordinary;
                return .{ .index = index };
            }
        }
        if (equals(name, "-0") or equals(name, "NaN") or equals(name, "Infinity") or equals(name, "-Infinity"))
            return .invalid_numeric;
        const number = std.fmt.parseFloat(f64, name) catch return .ordinary;
        var rendered_buffer: [128]u8 = undefined;
        const rendered = std.fmt.bufPrint(rendered_buffer[0..], "{d}", .{number}) catch return .ordinary;
        return if (equals(rendered, name)) .invalid_numeric else .ordinary;
    }

    fn typedArrayElement(self: *const Runtime, value: Value) ?TypedArrayElement {
        if (value != .cell or value.cell >= self.cells.len or !self.cells[value.cell].occupied) return null;
        const tag = self.cells[value.cell].host_tag;
        if (tag < typed_array_tag_base or tag >= typed_array_tag_base + 12) return null;
        return @enumFromInt(@as(u8, @intCast(tag - typed_array_tag_base)));
    }

    fn isTypedArray(self: *const Runtime, value: Value) bool {
        return self.typedArrayElement(value) != null;
    }

    fn typedArrayIndex(self: *const Runtime, value: Value) Error!u16 {
        if (!self.isTypedArray(value)) return error.TypeError;
        return value.cell;
    }

    fn typedArrayRange(self: *Runtime, index: u16) Error!TypedArrayRange {
        const cell = &self.cells[index];
        const element = self.typedArrayElement(.{ .cell = index }) orelse return error.TypeError;
        const storage = try self.bufferStorage(cell.receiver);
        const offset = cell.item_count;
        const size = element.byteSize();
        if (offset > storage.byte_length) return error.TypeError;
        const length = if (cell.array_length_writable)
            (storage.byte_length - offset) / size
        else
            cell.array_length;
        if (length > (storage.byte_length - offset) / size) return error.TypeError;
        return .{ .storage = storage, .offset = offset, .length = length, .element = element };
    }

    fn typedArrayLengthOrZero(self: *Runtime, index: u16) usize {
        return (self.typedArrayRange(index) catch return 0).length;
    }

    fn createTypedArrayView(self: *Runtime, element: TypedArrayElement, buffer: Value, offset: usize, length: usize, length_tracking: bool) Error!Value {
        const object: Value = .{ .cell = try self.allocateCell(.object) };
        self.cells[object.cell].host_tag = typed_array_tag_base + @intFromEnum(element);
        self.cells[object.cell].receiver = buffer;
        self.cells[object.cell].item_count = offset;
        self.cells[object.cell].array_length = length;
        self.cells[object.cell].array_length_writable = length_tracking;
        self.cells[object.cell].prototype = self.typed_array_prototypes[@intFromEnum(element)];
        return object;
    }

    fn createTypedArrayLength(self: *Runtime, element: TypedArrayElement, length: usize) Error!Value {
        const size = element.byteSize();
        if (length > max_array_buffer_bytes / size) return error.RangeError;
        const buffer = try self.createArrayBuffer(length * size, length * size, false);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(buffer);
        return self.createTypedArrayView(element, buffer, 0, length, false);
    }

    fn typedArrayValueFromBits(self: *Runtime, element: TypedArrayElement, bits: u64) Error!Value {
        return switch (element) {
            .int8 => .{ .number = @floatFromInt(@as(i8, @bitCast(@as(u8, @truncate(bits))))) },
            .uint8, .uint8_clamped => .{ .number = @floatFromInt(@as(u8, @truncate(bits))) },
            .int16 => .{ .number = @floatFromInt(@as(i16, @bitCast(@as(u16, @truncate(bits))))) },
            .uint16 => .{ .number = @floatFromInt(@as(u16, @truncate(bits))) },
            .int32 => .{ .number = @floatFromInt(@as(i32, @bitCast(@as(u32, @truncate(bits))))) },
            .uint32 => .{ .number = @floatFromInt(@as(u32, @truncate(bits))) },
            .float16 => .{ .number = @floatCast(@as(f16, @bitCast(@as(u16, @truncate(bits))))) },
            .float32 => .{ .number = @floatCast(@as(f32, @bitCast(@as(u32, @truncate(bits))))) },
            .float64 => .{ .number = @bitCast(bits) },
            .bigint64 => self.createBigIntFromScalar(@bitCast(bits)),
            .biguint64 => self.createBigIntFromUnsigned(bits),
        };
    }

    fn typedArrayRead(self: *Runtime, index: u16, item_index: usize) Error!Value {
        const range = try self.typedArrayRange(index);
        if (item_index >= range.length) return .undefined;
        const size = range.element.byteSize();
        const bits = readDataViewBits(arrayBufferBytes(range.storage), range.offset + item_index * size, size, true);
        return self.typedArrayValueFromBits(range.element, bits);
    }

    fn uint8Clamp(value: f64) u8 {
        if (std.math.isNan(value) or value <= 0) return 0;
        if (value >= 255) return 255;
        const floor = @floor(value);
        const fraction = value - floor;
        if (fraction > 0.5 or (fraction == 0.5 and @mod(floor, 2) != 0)) return @intFromFloat(floor + 1);
        return @intFromFloat(floor);
    }

    fn typedArrayValueBits(self: *Runtime, element: TypedArrayElement, value: Value) Error!u64 {
        return if (element.isBigInt()) blk: {
            const bigint = try self.toBigInt(value, false);
            try self.pushRoot(bigint);
            const truncated = try self.nativeBigIntAsN(&.{ .{ .number = 64 }, bigint }, false);
            break :blk (try self.bigIntConst(truncated)).toInt(u64) catch return error.RangeError;
        } else switch (element) {
            .int8, .uint8 => @as(u8, @truncate(toUint32(try self.toNumber(value)))),
            .uint8_clamped => uint8Clamp(try self.toNumber(value)),
            .int16, .uint16 => @as(u16, @truncate(toUint32(try self.toNumber(value)))),
            .int32, .uint32 => toUint32(try self.toNumber(value)),
            .float16 => @as(u16, @bitCast(@as(f16, @floatCast(try self.toNumber(value))))),
            .float32 => @as(u32, @bitCast(@as(f32, @floatCast(try self.toNumber(value))))),
            .float64 => @bitCast(try self.toNumber(value)),
            else => unreachable,
        };
    }

    fn typedArrayWrite(self: *Runtime, index: u16, item_index: usize, value: Value) Error!bool {
        const initial = self.typedArrayRange(index) catch |err| switch (err) {
            error.TypeError => return false,
            else => return err,
        };
        if (item_index >= initial.length) return false;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = index });
        const bits = try self.typedArrayValueBits(initial.element, value);
        const range = try self.typedArrayRange(index);
        if (range.storage.immutable) return error.TypeError;
        if (item_index >= range.length) return false;
        const size = range.element.byteSize();
        writeDataViewBits(arrayBufferBytes(range.storage), range.offset + item_index * size, size, true, bits);
        return true;
    }

    const AtomicsOperation = enum { add, bit_and, exchange, load, bit_or, store, sub, bit_xor };
    const AtomicsAccess = struct { typed: u16, element: TypedArrayElement, index: usize };

    fn atomicsAccess(self: *Runtime, arguments: []const Value, waitable: bool) Error!AtomicsAccess {
        if (arguments.len == 0) return error.TypeError;
        const typed = try self.typedArrayIndex(arguments[0]);
        const element = self.typedArrayElement(arguments[0]) orelse return error.TypeError;
        if (element == .uint8_clamped or element == .float16 or element == .float32 or element == .float64) return error.TypeError;
        if (waitable and element != .int32 and element != .bigint64) return error.TypeError;
        if (!self.isSharedArrayBuffer(self.cells[typed].receiver)) return error.TypeError;
        try self.pushRoot(arguments[0]);
        const item_index = try self.toIndex(if (arguments.len > 1) arguments[1] else .undefined);
        const range = try self.typedArrayRange(typed);
        if (item_index >= range.length) return error.RangeError;
        return .{ .typed = typed, .element = element, .index = item_index };
    }

    fn atomicsMask(size: usize) u64 {
        return if (size == 8) std.math.maxInt(u64) else (@as(u64, 1) << @intCast(size * 8)) - 1;
    }

    fn nativeAtomicsOperation(self: *Runtime, arguments: []const Value, operation: AtomicsOperation) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        const access = try self.atomicsAccess(arguments, false);
        const element = access.element;
        const size = element.byteSize();
        var range = try self.typedArrayRange(access.typed);
        var byte_offset = range.offset + access.index * size;
        var bytes = arrayBufferBytes(range.storage);
        const old_bits = readDataViewBits(bytes, byte_offset, size, true);
        if (operation == .load) return self.typedArrayValueFromBits(element, old_bits);

        const operand = if (arguments.len > 2) arguments[2] else Value.undefined;
        const operand_bits = try self.typedArrayValueBits(element, operand);
        range = try self.typedArrayRange(access.typed);
        if (access.index >= range.length) return error.RangeError;
        byte_offset = range.offset + access.index * size;
        bytes = arrayBufferBytes(range.storage);
        const current_bits = readDataViewBits(bytes, byte_offset, size, true);
        const mask = atomicsMask(size);
        var new_bits: u64 = switch (operation) {
            .add => current_bits +% operand_bits,
            .bit_and => current_bits & operand_bits,
            .exchange, .store => operand_bits,
            .bit_or => current_bits | operand_bits,
            .sub => current_bits -% operand_bits,
            .bit_xor => current_bits ^ operand_bits,
            .load => unreachable,
        };
        new_bits &= mask;

        writeDataViewBits(bytes, byte_offset, size, true, new_bits);
        return if (operation == .store)
            self.typedArrayValueFromBits(element, new_bits)
        else
            self.typedArrayValueFromBits(element, current_bits);
    }

    fn nativeAtomicsCompareExchange(self: *Runtime, arguments: []const Value) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        const access = try self.atomicsAccess(arguments, false);
        const expected = try self.typedArrayValueBits(access.element, if (arguments.len > 2) arguments[2] else .undefined);
        const replacement = try self.typedArrayValueBits(access.element, if (arguments.len > 3) arguments[3] else .undefined);
        const range = try self.typedArrayRange(access.typed);
        if (access.index >= range.length) return error.RangeError;
        const size = access.element.byteSize();
        const byte_offset = range.offset + access.index * size;
        const bytes = arrayBufferBytes(range.storage);
        const mask = atomicsMask(size);
        const old_bits = readDataViewBits(bytes, byte_offset, size, true);
        if ((old_bits & mask) == (expected & mask)) writeDataViewBits(bytes, byte_offset, size, true, replacement & mask);
        return self.typedArrayValueFromBits(access.element, old_bits);
    }

    fn nativeAtomicsIsLockFree(self: *Runtime, arguments: []const Value) Error!Value {
        const size = try self.toNumber(if (arguments.len > 0) arguments[0] else .undefined);
        return .{ .boolean = size == 1 or size == 2 or size == 4 or size == 8 };
    }

    fn nativeAtomicsNotify(self: *Runtime, arguments: []const Value) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        _ = try self.atomicsAccess(arguments, true);
        if (arguments.len > 2 and arguments[2] != .undefined) _ = try self.toNumber(arguments[2]);
        // R4JS has no Worker agents yet, hence there can be no waiter to wake.
        return .{ .number = 0 };
    }

    fn nativeAtomicsWait(self: *Runtime, arguments: []const Value, asynchronous: bool) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        const access = try self.atomicsAccess(arguments, true);
        const expected = try self.typedArrayValueBits(access.element, if (arguments.len > 2) arguments[2] else .undefined);
        if (arguments.len > 3 and arguments[3] != .undefined) _ = try self.toNumber(arguments[3]);
        const range = try self.typedArrayRange(access.typed);
        if (access.index >= range.length) return error.RangeError;
        const size = access.element.byteSize();
        const actual = readDataViewBits(arrayBufferBytes(range.storage), range.offset + access.index * size, size, true);
        const outcome = if (actual != (expected & atomicsMask(size))) "not-equal" else "timed-out";
        const outcome_value = Value{ .string = try self.storeString(outcome) };
        if (!asynchronous) return outcome_value;
        try self.pushRoot(outcome_value);
        const result: Value = .{ .cell = try self.allocateCell(.object) };
        try self.setProperty(result, "async", .{ .boolean = false });
        try self.setProperty(result, "value", outcome_value);
        return result;
    }

    fn nativeAtomicsPause(self: *Runtime, arguments: []const Value) Error!Value {
        if (arguments.len > 0 and arguments[0] != .undefined) {
            const hint = try self.toNumber(arguments[0]);
            if (!std.math.isFinite(hint) or hint < 0 or @trunc(hint) != hint) return error.RangeError;
        }
        return .undefined;
    }

    fn typedArrayTypeMarker(receiver: Value) Error!TypedArrayElement {
        if (receiver != .number or !std.math.isFinite(receiver.number) or @trunc(receiver.number) != receiver.number or receiver.number < 0 or receiver.number >= 12)
            return error.TypeError;
        return @enumFromInt(@as(u8, @intFromFloat(receiver.number)));
    }

    fn materializeTypedArraySource(self: *Runtime, program: *const Program, source: Value) Error!Value {
        if (self.symbol_iterator.len == 0 or !try self.hasProperty(source, self.stringBytes(self.symbol_iterator))) return source;
        const list = try self.createSparseArray(0);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(source);
        try self.pushRoot(list);
        var cursor = try self.openIterator(program, source);
        try self.rootIterator(cursor);
        while (true) {
            const step = self.iteratorNext(program, &cursor) catch |err| {
                self.closeIteratorPreservingError(program, &cursor);
                return err;
            };
            if (step.done) break;
            if (self.cells[list.cell].item_count >= max_items) {
                _ = self.iteratorClose(program, &cursor) catch {};
                return error.ItemLimit;
            }
            self.setSparseArrayItem(list, self.cells[list.cell].item_count, step.value) catch |err| {
                self.closeIteratorPreservingError(program, &cursor);
                return err;
            };
        }
        return list;
    }

    fn nativeTypedArrayConstructor(self: *Runtime, program: *const Program, marker: Value, arguments: []const Value) Error!Value {
        const element = try typedArrayTypeMarker(marker);
        const source = if (arguments.len > 0) arguments[0] else Value.undefined;
        if (self.isBufferObject(source)) {
            const size = element.byteSize();
            const offset = try self.toIndex(if (arguments.len > 1) arguments[1] else .undefined);
            var storage = try self.bufferStorage(source);
            if (offset % size != 0 or offset > storage.byte_length) return error.RangeError;
            const length_tracking = (arguments.len < 3 or arguments[2] == .undefined) and storage.resizable;
            const length = if (arguments.len < 3 or arguments[2] == .undefined)
                (storage.byte_length - offset) / size
            else
                try self.toIndex(arguments[2]);
            storage = try self.bufferStorage(source);
            if (offset > storage.byte_length or length > (storage.byte_length - offset) / size) return error.RangeError;
            if (!length_tracking and arguments.len < 3 and (storage.byte_length - offset) % size != 0) return error.RangeError;
            return self.createTypedArrayView(element, source, offset, length, length_tracking);
        }
        if (source == .cell or source == .string) {
            const root_base = self.root_count;
            defer self.root_count = root_base;
            try self.pushRoot(source);
            const values = try self.materializeTypedArraySource(program, source);
            try self.pushRoot(values);
            const length = try self.arrayLikeLength(values);
            const result = try self.createTypedArrayLength(element, length);
            try self.pushRoot(result);
            for (0..length) |item_index| _ = try self.typedArrayWrite(result.cell, item_index, try self.arrayLikeGet(values, item_index));
            return result;
        }
        return self.createTypedArrayLength(element, try self.toIndex(source));
    }

    fn nativeTypedArrayGetter(self: *Runtime, receiver: Value, getter: TypedArrayGetter) Error!Value {
        const index = try self.typedArrayIndex(receiver);
        if (getter == .buffer) return self.cells[index].receiver;
        const range = self.typedArrayRange(index) catch |err| switch (err) {
            error.TypeError => return .{ .number = 0 },
            else => return err,
        };
        return .{ .number = @floatFromInt(switch (getter) {
            .byte_length => range.length * range.element.byteSize(),
            .byte_offset => range.offset,
            .length => range.length,
            else => unreachable,
        }) };
    }

    fn nativeTypedArrayTag(self: *Runtime, receiver: Value) Error!Value {
        const element = self.typedArrayElement(receiver) orelse return .undefined;
        return .{ .string = try self.storeString(element.name()) };
    }

    fn nativeTypedArrayFrom(self: *Runtime, program: *const Program, constructor: Value, arguments: []const Value) Error!Value {
        if (!self.isConstructor(constructor) or arguments.len == 0 or arguments[0].isNullish()) return error.TypeError;
        const source = arguments[0];
        const map = if (arguments.len > 1) arguments[1] else .undefined;
        if (map != .undefined and !self.isCallableValue(map)) return error.TypeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(source);
        try self.pushRoot(map);
        const values = try self.materializeTypedArraySource(program, source);
        try self.pushRoot(values);
        const length = try self.arrayLikeLength(values);
        const result = try self.call(program, constructor, .undefined, &.{.{ .number = @floatFromInt(length) }}, true);
        const index = try self.typedArrayIndex(result);
        try self.pushRoot(result);
        if ((try self.typedArrayRange(index)).length < length) return error.TypeError;
        for (0..length) |item_index| {
            var value = try self.arrayLikeGet(values, item_index);
            if (map != .undefined) value = try self.call(program, map, if (arguments.len > 2) arguments[2] else .undefined, &.{ value, .{ .number = @floatFromInt(item_index) } }, false);
            _ = try self.typedArrayWrite(index, item_index, value);
        }
        return result;
    }

    fn nativeTypedArrayOf(self: *Runtime, program: *const Program, constructor: Value, arguments: []const Value) Error!Value {
        if (!self.isConstructor(constructor)) return error.TypeError;
        const result = try self.call(program, constructor, .undefined, &.{.{ .number = @floatFromInt(arguments.len) }}, true);
        const index = try self.typedArrayIndex(result);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(result);
        if ((try self.typedArrayRange(index)).length < arguments.len) return error.TypeError;
        for (arguments, 0..) |value, item_index| _ = try self.typedArrayWrite(index, item_index, value);
        return result;
    }

    const TypedArrayGenericMethod = enum {
        copy_within,
        every,
        find,
        find_index,
        find_last,
        find_last_index,
        for_each,
        includes,
        index_of,
        join,
        last_index_of,
        reduce,
        reduce_right,
        reverse,
        some,
        to_locale_string,
        to_string,
    };

    fn nativeTypedArrayAt(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        _ = try self.typedArrayRange(try self.typedArrayIndex(receiver));
        return self.nativeArrayAt(receiver, arguments);
    }

    fn nativeTypedArrayGeneric(self: *Runtime, receiver: Value, arguments: []const Value, method: TypedArrayGenericMethod, program: *const Program) Error!Value {
        _ = try self.typedArrayRange(try self.typedArrayIndex(receiver));
        return switch (method) {
            .copy_within => self.nativeTypedArrayCopyWithin(receiver, arguments),
            .every => self.nativeTypedArrayPredicate(program, receiver, arguments, true),
            .find => self.nativeArrayFind(program, receiver, arguments, false, false),
            .find_index => self.nativeArrayFind(program, receiver, arguments, false, true),
            .find_last => self.nativeArrayFind(program, receiver, arguments, true, false),
            .find_last_index => self.nativeArrayFind(program, receiver, arguments, true, true),
            .for_each => self.nativeTypedArrayForEach(program, receiver, arguments),
            .includes => self.nativeArrayIncludes(receiver, arguments),
            .index_of => self.nativeTypedArrayIndexOf(receiver, arguments, false),
            .join => self.nativeArrayJoin(receiver, arguments),
            .last_index_of => self.nativeTypedArrayIndexOf(receiver, arguments, true),
            .reduce => self.nativeTypedArrayReduce(program, receiver, arguments, false),
            .reduce_right => self.nativeTypedArrayReduce(program, receiver, arguments, true),
            .reverse => self.nativeArrayReverse(receiver),
            .some => self.nativeTypedArrayPredicate(program, receiver, arguments, false),
            .to_locale_string => self.nativeArrayToLocaleString(program, receiver),
            .to_string => self.nativeArrayToString(program, receiver),
        };
    }

    fn nativeTypedArrayForEach(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        if (arguments.len == 0 or !self.isCallableValue(arguments[0])) return error.TypeError;
        const length = try self.arrayLikeLength(receiver);
        const this_argument = if (arguments.len > 1) arguments[1] else Value.undefined;
        for (0..length) |item_index| _ = try self.call(program, arguments[0], this_argument, &.{
            try self.arrayLikeGet(receiver, item_index),
            .{ .number = @floatFromInt(item_index) },
            receiver,
        }, false);
        return .undefined;
    }

    fn nativeTypedArrayPredicate(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value, every: bool) Error!Value {
        if (arguments.len == 0 or !self.isCallableValue(arguments[0])) return error.TypeError;
        const length = try self.arrayLikeLength(receiver);
        const this_argument = if (arguments.len > 1) arguments[1] else Value.undefined;
        for (0..length) |item_index| {
            const accepted = self.truthy(try self.call(program, arguments[0], this_argument, &.{
                try self.arrayLikeGet(receiver, item_index),
                .{ .number = @floatFromInt(item_index) },
                receiver,
            }, false));
            if (accepted != every) return .{ .boolean = !every };
        }
        return .{ .boolean = every };
    }

    fn nativeTypedArrayReduce(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value, reverse: bool) Error!Value {
        if (arguments.len == 0 or !self.isCallableValue(arguments[0])) return error.TypeError;
        const length = try self.arrayLikeLength(receiver);
        var accumulator: Value = if (arguments.len > 1) arguments[1] else .undefined;
        var initialized = arguments.len > 1;
        var remaining = length;
        while (remaining > 0) {
            const item_index = if (reverse) remaining - 1 else length - remaining;
            remaining -= 1;
            const item = try self.arrayLikeGet(receiver, item_index);
            if (!initialized) {
                accumulator = item;
                initialized = true;
            } else accumulator = try self.call(program, arguments[0], .undefined, &.{
                accumulator,
                item,
                .{ .number = @floatFromInt(item_index) },
                receiver,
            }, false);
        }
        if (!initialized) return error.TypeError;
        return accumulator;
    }

    fn nativeTypedArrayIndexOf(self: *Runtime, receiver: Value, arguments: []const Value, reverse: bool) Error!Value {
        const length = try self.arrayLikeLength(receiver);
        if (length == 0) return .{ .number = -1 };
        const needle = if (arguments.len > 0) arguments[0] else Value.undefined;
        const from_number = if (arguments.len > 1) try self.toNumber(arguments[1]) else if (reverse) std.math.inf(f64) else 0;
        if ((!reverse and from_number == std.math.inf(f64)) or (reverse and from_number == -std.math.inf(f64))) return .{ .number = -1 };
        if (reverse) {
            const start_float = if (from_number == std.math.inf(f64))
                @as(f64, @floatFromInt(length - 1))
            else if (std.math.isNan(from_number))
                0
            else if (from_number < 0)
                @as(f64, @floatFromInt(length)) + @trunc(from_number)
            else
                @min(@as(f64, @floatFromInt(length - 1)), @trunc(from_number));
            if (start_float < 0) return .{ .number = -1 };
            var remaining: usize = @as(usize, @intFromFloat(start_float)) + 1;
            while (remaining > 0) {
                remaining -= 1;
                if (self.strictEqual(try self.arrayLikeGet(receiver, remaining), needle)) return .{ .number = @floatFromInt(remaining) };
            }
            return .{ .number = -1 };
        }
        const start_float = if (std.math.isNan(from_number) or from_number == -std.math.inf(f64))
            0
        else if (from_number < 0)
            @max(0, @as(f64, @floatFromInt(length)) + @trunc(from_number))
        else
            @trunc(from_number);
        if (start_float >= @as(f64, @floatFromInt(length))) return .{ .number = -1 };
        var item_index: usize = @intFromFloat(start_float);
        while (item_index < length) : (item_index += 1)
            if (self.strictEqual(try self.arrayLikeGet(receiver, item_index), needle)) return .{ .number = @floatFromInt(item_index) };
        return .{ .number = -1 };
    }

    fn nativeTypedArrayCopyWithin(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.typedArrayIndex(receiver);
        const length = (try self.typedArrayRange(index)).length;
