        const start = arrayRelativeIndex(try self.toNumber(if (arguments.len > 1) arguments[1] else .{ .number = 0 }), length);
        const end = arrayRelativeIndex(try self.toNumber(if (arguments.len > 2) arguments[2] else .{ .number = @floatFromInt(length) }), length);
        var count = @min(end -| start, length -| target);
        var from = start;
        var to = target;
        const backwards = from < to and to < from + count;
        if (backwards) {
            from += count;
            to += count;
        }
        while (count > 0) : (count -= 1) {
            if (backwards) {
                from -= 1;
                to -= 1;
            }
            _ = try self.typedArrayWrite(index, to, try self.arrayLikeGet(receiver, from));
            if (!backwards) {
                from += 1;
                to += 1;
            }
        }
        return receiver;
    }

    fn nativeTypedArrayIterator(self: *Runtime, receiver: Value, kind: u16) Error!Value {
        _ = try self.typedArrayRange(try self.typedArrayIndex(receiver));
        return self.nativeArrayIterator(receiver, kind);
    }

    fn typedArraySpeciesCreate(self: *Runtime, program: *const Program, original: Value, arguments: []const Value) Error!Value {
        const original_element = self.typedArrayElement(original) orelse return error.TypeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(original);
        var constructor = try self.getProperty(original, "constructor");
        try self.pushRoot(constructor);
