        const result = if (constructor == .undefined) blk: {
            if (arguments.len > 0 and self.isBufferObject(arguments[0])) {
                const offset = try self.toIndex(if (arguments.len > 1) arguments[1] else .undefined);
                const size = original_element.byteSize();
