                if (offset % size != 0 or offset > storage.byte_length) return error.RangeError;
                const length = if (arguments.len > 2) try self.toIndex(arguments[2]) else (storage.byte_length - offset) / size;
                if (length > (storage.byte_length - offset) / size) return error.RangeError;
