        const result_element = self.typedArrayElement(result) orelse return error.TypeError;
        if (result_element.isBigInt() != original_element.isBigInt()) return error.TypeError;
        _ = try self.typedArrayRange(result.cell);
        return result;
    }

    fn nativeTypedArrayMap(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        if (arguments.len == 0 or !self.isCallableValue(arguments[0])) return error.TypeError;
