        const end = @max(start, arrayRelativeIndex(if (arguments.len > 1) try self.toNumber(arguments[1]) else @floatFromInt(length), length));
        const count = end - start;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        const result = try self.typedArraySpeciesCreate(program, receiver, &.{.{ .number = @floatFromInt(count) }});
        try self.pushRoot(result);
        if ((try self.typedArrayRange(result.cell)).length < count) return error.TypeError;
