    }

    fn nativeTypedArrayFill(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.typedArrayIndex(receiver);
        const range = try self.typedArrayRange(index);
        const raw = if (arguments.len > 0) arguments[0] else Value.undefined;
        const value = if (range.element.isBigInt()) try self.toBigInt(raw, false) else Value{ .number = try self.toNumber(raw) };
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        try self.pushRoot(value);
        const start = arrayRelativeIndex(if (arguments.len > 1) try self.toNumber(arguments[1]) else 0, range.length);
        const end = @max(start, arrayRelativeIndex(if (arguments.len > 2) try self.toNumber(arguments[2]) else @floatFromInt(range.length), range.length));
        for (start..end) |item_index| if (!try self.typedArrayWrite(index, item_index, value)) return error.TypeError;
        return receiver;
    }

    fn nativeBigIntAsN(self: *Runtime, arguments: []const Value, signed: bool) Error!Value {
        const bits = try self.toIndex(if (arguments.len > 0) arguments[0] else .undefined);
        const value = try self.toBigInt(if (arguments.len > 1) arguments[1] else .undefined, false);
        const source = try self.bigIntConst(value);
        if (bits == 0) return self.createBigIntFromScalar(0);
        if (bits > max_bigint_bits) {
            if (signed and bits >= source.bitCountTwosComp()) return value;
            if (!signed and source.positive and bits >= source.bitCountAbs()) return value;
            return error.RangeError;
        }
        const required = @max(@as(usize, 1), BigIntCore.calcTwosCompLimbCount(bits));
        var result = BigIntCore.Mutable.init(self.bigint_result_scratch[0..required], 0);
        result.truncate(source, if (signed) .signed else .unsigned, bits);
        return self.storeBigIntMutable(result);
    }

    fn nativeParseFloat(self: *Runtime, arguments: []const Value) Error!Value {
        const source = (try self.toString(if (arguments.len > 0) arguments[0] else .undefined)).bytes(self.strings[0..self.string_len]);
        const text = trimNumberWhitespace(source);
        if (text.len == 0) return .{ .number = std.math.nan(f64) };
        var cursor: usize = 0;
        if (text[cursor] == '+' or text[cursor] == '-') cursor += 1;
        if (cursor + "Infinity".len <= text.len and equals(text[cursor .. cursor + "Infinity".len], "Infinity"))
            return .{ .number = if (text[0] == '-') -std.math.inf(f64) else std.math.inf(f64) };
        const integer_start = cursor;
        while (cursor < text.len and std.ascii.isDigit(text[cursor])) cursor += 1;
        var digits = cursor - integer_start;
        if (cursor < text.len and text[cursor] == '.') {
            cursor += 1;
            const fraction_start = cursor;
            while (cursor < text.len and std.ascii.isDigit(text[cursor])) cursor += 1;
            digits += cursor - fraction_start;
        }
        if (digits == 0) return .{ .number = std.math.nan(f64) };
        if (cursor < text.len and (text[cursor] == 'e' or text[cursor] == 'E')) {
            const exponent_marker = cursor;
            cursor += 1;
            if (cursor < text.len and (text[cursor] == '+' or text[cursor] == '-')) cursor += 1;
            const exponent_start = cursor;
            while (cursor < text.len and std.ascii.isDigit(text[cursor])) cursor += 1;
            if (cursor == exponent_start) cursor = exponent_marker;
        }
        const number = std.fmt.parseFloat(f64, text[0..cursor]) catch std.math.nan(f64);
        return .{ .number = number };
    }

    fn nativeNumberToString(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const number = (try self.numberValue(receiver)).number;
        const radix_number = if (arguments.len > 0 and arguments[0] != .undefined) try self.toNumber(arguments[0]) else 10;
        if (!std.math.isFinite(radix_number) or @trunc(radix_number) != radix_number or radix_number < 2 or radix_number > 36)
            return error.RangeError;
        const radix: u8 = @intFromFloat(radix_number);
        if (radix == 10 or !std.math.isFinite(number) or number == 0)
            return .{ .string = try self.formatDefaultNumber(number) };

        var buffer: [160]u8 = undefined;
        var length: usize = 0;
        const negative = number < 0;
        var magnitude = @abs(number);
        if (negative) {
            buffer[length] = '-';
            length += 1;
        }
        const integer_part = @floor(magnitude);
        if (integer_part > 9_007_199_254_740_991) return .{ .string = try self.formatDefaultNumber(number) };
        var integer: u64 = @intFromFloat(integer_part);
        var reverse: [80]u8 = undefined;
        var reverse_count: usize = 0;
        while (integer > 0) {
            reverse[reverse_count] = numberDigit(@intCast(integer % radix));
            reverse_count += 1;
            integer /= radix;
        }
        if (reverse_count == 0) {
            reverse[0] = '0';
            reverse_count = 1;
        }
        var index = reverse_count;
        while (index > 0) {
            index -= 1;
            buffer[length] = reverse[index];
            length += 1;
        }
        magnitude -= integer_part;
        if (magnitude != 0) {
            buffer[length] = '.';
            length += 1;
            var fraction_digits: usize = 0;
            while (magnitude != 0 and fraction_digits < 52 and length < buffer.len) : (fraction_digits += 1) {
                magnitude *= radix;
                const digit: u8 = @intFromFloat(@floor(magnitude));
                buffer[length] = numberDigit(digit);
                length += 1;
                magnitude -= digit;
            }
            while (length > 0 and buffer[length - 1] == '0') length -= 1;
            if (length > 0 and buffer[length - 1] == '.') length -= 1;
        }
        return .{ .string = try self.storeString(buffer[0..length]) };
    }

    fn nativeNumberFormat(self: *Runtime, receiver: Value, arguments: []const Value, format: NumberFormat) Error!Value {
        const raw_number = (try self.numberValue(receiver)).number;
        const number = if (raw_number == 0) @as(f64, 0) else raw_number;
        if (format == .locale) return .{ .string = try self.formatDefaultNumber(number) };
        if (!std.math.isFinite(number)) return .{ .string = try self.formatDefaultNumber(number) };

        const has_argument = arguments.len > 0 and arguments[0] != .undefined;
        if (format == .precision and !has_argument) return .{ .string = try self.formatDefaultNumber(number) };
        var requested: usize = 0;
        if (has_argument) {
            const raw = try self.toNumber(arguments[0]);
            if (!std.math.isFinite(raw)) return error.RangeError;
            const integer = @trunc(raw);
            const minimum: f64 = if (format == .precision) 1 else 0;
            if (integer < minimum or integer > 100) return error.RangeError;
            requested = @intFromFloat(integer);
        }

        var rendered_buffer: [512]u8 = undefined;
        var normalized_buffer: [512]u8 = undefined;
        const rendered = switch (format) {
            .exponential => std.fmt.float.render(rendered_buffer[0..], number, .{ .mode = .scientific, .precision = if (has_argument) requested else null }) catch return error.StringLimit,
            .fixed => blk: {
                if (@abs(number) >= 1.0e21) return .{ .string = try self.formatDefaultNumber(number) };
                break :blk std.fmt.float.render(rendered_buffer[0..], number, .{ .mode = .decimal, .precision = requested }) catch return error.StringLimit;
            },
            .precision => blk: {
                const exponent: i32 = if (number == 0) 0 else @intFromFloat(@floor(std.math.log10(@abs(number))));
                if (exponent < -6 or exponent >= @as(i32, @intCast(requested))) {
                    break :blk std.fmt.float.render(rendered_buffer[0..], number, .{ .mode = .scientific, .precision = requested - 1 }) catch return error.StringLimit;
                }
                const decimal_places: usize = @intCast(@as(i32, @intCast(requested)) - exponent - 1);
                break :blk std.fmt.float.render(rendered_buffer[0..], number, .{ .mode = .decimal, .precision = decimal_places }) catch return error.StringLimit;
            },
            .locale => unreachable,
        };
        const text = if (format == .exponential or std.mem.indexOfScalar(u8, rendered, 'e') != null)
            normalizeNumberExponent(rendered, normalized_buffer[0..]) catch return error.StringLimit
        else
            rendered;
        return .{ .string = try self.storeString(text) };
    }

    fn formatDefaultNumber(self: *Runtime, number: f64) Error!StringRef {
        if (std.math.isNan(number)) return self.storeString("NaN");
        if (std.math.isPositiveInf(number)) return self.storeString("Infinity");
        if (std.math.isNegativeInf(number)) return self.storeString("-Infinity");
        if (number == 0) return self.storeString("0");
        var buffer: [128]u8 = undefined;
        const text = std.fmt.bufPrint(buffer[0..], "{d}", .{number}) catch return error.StringLimit;
        return self.storeString(text);
    }

    fn runtimeErrorValue(self: *Runtime, err: Error) Error!Value {
        const message: Value = .{ .string = try self.storeString(@errorName(err)) };
        const name = switch (err) {
            error.UnknownIdentifier => "ReferenceError",
            error.RangeError => "RangeError",
            error.SyntaxError => "SyntaxError",
            else => "TypeError",
        };
        const constructor = self.global(name) orelse return error.TypeError;
        const prototype = try self.getProperty(constructor, "prototype");
        const object = try self.nativeError(null, prototype, &.{message}, false);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(object);
        if (self.diagnostic_stack_len > 0) {
            try self.defineOwnDataProperty(object, "stack", .{ .string = try self.storeString(self.diagnosticStack()) });
            try self.makeOwnPropertyNonEnumerable(object, "stack");
        }
        if (self.diagnostic_source_name_len > 0) {
            try self.defineOwnDataProperty(object, "sourceName", .{ .string = try self.storeString(self.diagnosticSourceName()) });
            try self.makeOwnPropertyNonEnumerable(object, "sourceName");
            try self.defineOwnDataProperty(object, "lineNumber", .{ .number = @floatFromInt(self.diagnostic_line) });
            try self.makeOwnPropertyNonEnumerable(object, "lineNumber");
            try self.defineOwnDataProperty(object, "columnNumber", .{ .number = @floatFromInt(self.diagnostic_column) });
            try self.makeOwnPropertyNonEnumerable(object, "columnNumber");
        }
        self.diagnostic_phase = .none;
        self.diagnostic_error_name_len = 0;
        self.diagnostic_source_name_len = 0;
        self.diagnostic_line = 0;
        self.diagnostic_column = 0;
        self.diagnostic_stack_len = 0;
        return object;
    }

    fn currentTimeMilliseconds(self: *const Runtime) f64 {
        const value = if (self.clock_source.now_milliseconds) |now| now(self.clock_source.context) else 0;
        return timeClip(value);
    }

    fn dateOffsetMinutes(self: *const Runtime, utc_milliseconds: f64) i32 {
        return if (self.clock_source.offset_minutes) |offset| offset(self.clock_source.context, utc_milliseconds) else 0;
    }

    fn utcFromLocalMilliseconds(self: *const Runtime, local_milliseconds: i64) f64 {
        const local: f64 = @floatFromInt(local_milliseconds);
        var utc = local - @as(f64, @floatFromInt(self.dateOffsetMinutes(local))) * 60000.0;
        utc = local - @as(f64, @floatFromInt(self.dateOffsetMinutes(utc))) * 60000.0;
        return utc;
    }

    fn nativeDate(self: *Runtime, program: *const Program, default_prototype: Value, arguments: []const Value, construct: bool, new_target: Value) Error!Value {
        if (!construct) return self.nativeDateFormatValue(self.currentTimeMilliseconds(), .string);
        const requested_prototype = if (new_target == .cell) try self.getProperty(new_target, "prototype") else .undefined;
        const prototype = if (requested_prototype == .cell) requested_prototype else default_prototype;
        var milliseconds = self.currentTimeMilliseconds();
        if (arguments.len == 1) {
            if (arguments[0] == .cell and arguments[0].cell < self.cells.len and self.cells[arguments[0].cell].occupied and self.cells[arguments[0].cell].host_tag == date_tag) {
                milliseconds = self.cells[arguments[0].cell].receiver.number;
            } else {
                const primitive = try self.toPrimitive(arguments[0], .default);
                milliseconds = if (primitive == .string) try self.parseDateString(self.stringBytes(primitive.string)) else timeClip(try self.toNumber(primitive));
            }
        } else if (arguments.len >= 2) {
            var year = try self.dateIntegerArgument(arguments, 0) orelse return self.createDate(prototype, std.math.nan(f64));
            const month = try self.dateIntegerArgument(arguments, 1) orelse return self.createDate(prototype, std.math.nan(f64));
            const date_value = try self.dateIntegerArgumentDefault(arguments, 2, 1) orelse return self.createDate(prototype, std.math.nan(f64));
            const hours = try self.dateIntegerArgumentDefault(arguments, 3, 0) orelse return self.createDate(prototype, std.math.nan(f64));
            const minutes = try self.dateIntegerArgumentDefault(arguments, 4, 0) orelse return self.createDate(prototype, std.math.nan(f64));
            const seconds = try self.dateIntegerArgumentDefault(arguments, 5, 0) orelse return self.createDate(prototype, std.math.nan(f64));
            const millis = try self.dateIntegerArgumentDefault(arguments, 6, 0) orelse return self.createDate(prototype, std.math.nan(f64));
            if (year >= 0 and year <= 99) year += 1900;
            const local = makeDateMilliseconds(year, month, date_value, hours, minutes, seconds, millis);
            milliseconds = timeClip(self.utcFromLocalMilliseconds(local));
        }
        _ = program;
        return self.createDate(prototype, milliseconds);
    }

    fn createDate(self: *Runtime, prototype: Value, milliseconds: f64) Error!Value {
        const object = Value{ .cell = try self.allocateCell(.object) };
        self.cells[object.cell].host_tag = date_tag;
        self.cells[object.cell].receiver = .{ .number = milliseconds };
        self.cells[object.cell].prototype = try self.expectObject(prototype);
        return object;
    }

    fn dateValue(self: *Runtime, receiver: Value) Error!f64 {
        const index = try self.expectObject(receiver);
        if (self.cells[index].host_tag != date_tag or self.cells[index].receiver != .number) return error.TypeError;
        return self.cells[index].receiver.number;
    }

    fn nativeDateParse(self: *Runtime, arguments: []const Value) Error!f64 {
        const text = try self.toString(if (arguments.len > 0) arguments[0] else .undefined);
        return self.parseDateString(self.stringBytes(text));
    }

    fn nativeDateUtc(self: *Runtime, arguments: []const Value) Error!f64 {
        var year = try self.dateIntegerArgument(arguments, 0) orelse return std.math.nan(f64);
        const month = try self.dateIntegerArgument(arguments, 1) orelse return std.math.nan(f64);
        const date_value = try self.dateIntegerArgumentDefault(arguments, 2, 1) orelse return std.math.nan(f64);
        const hours = try self.dateIntegerArgumentDefault(arguments, 3, 0) orelse return std.math.nan(f64);
        const minutes = try self.dateIntegerArgumentDefault(arguments, 4, 0) orelse return std.math.nan(f64);
        const seconds = try self.dateIntegerArgumentDefault(arguments, 5, 0) orelse return std.math.nan(f64);
        const millis = try self.dateIntegerArgumentDefault(arguments, 6, 0) orelse return std.math.nan(f64);
        if (year >= 0 and year <= 99) year += 1900;
        return timeClip(@floatFromInt(makeDateMilliseconds(year, month, date_value, hours, minutes, seconds, millis)));
    }

    fn dateIntegerArgument(self: *Runtime, arguments: []const Value, index: usize) Error!?i64 {
        const number = try self.toNumber(if (index < arguments.len) arguments[index] else .undefined);
        if (!std.math.isFinite(number)) return null;
        if (number > @as(f64, @floatFromInt(std.math.maxInt(i64))) or number < @as(f64, @floatFromInt(std.math.minInt(i64)))) return null;
        return @intFromFloat(@trunc(number));
    }

    fn dateIntegerArgumentDefault(self: *Runtime, arguments: []const Value, index: usize, default: i64) Error!?i64 {
        return if (index < arguments.len) self.dateIntegerArgument(arguments, index) else default;
    }

    fn nativeDateGet(self: *Runtime, receiver: Value, part: DatePart, utc: bool) Error!Value {
        const milliseconds = try self.dateValue(receiver);
        if (!std.math.isFinite(milliseconds)) return .{ .number = std.math.nan(f64) };
        const adjusted = if (utc) milliseconds else milliseconds + @as(f64, @floatFromInt(self.dateOffsetMinutes(milliseconds))) * 60000.0;
        const parts = dateParts(@intFromFloat(adjusted));
        const result = switch (part) {
            .date => parts.date,
            .day => parts.day,
            .full_year => parts.year,
            .hours => parts.hours,
            .milliseconds => parts.milliseconds,
            .minutes => parts.minutes,
            .month => parts.month,
            .seconds => parts.seconds,
        };
        return .{ .number = @floatFromInt(result) };
    }

    fn nativeDateTimezoneOffset(self: *Runtime, receiver: Value) Error!Value {
        const milliseconds = try self.dateValue(receiver);
        if (!std.math.isFinite(milliseconds)) return .{ .number = std.math.nan(f64) };
        return .{ .number = @floatFromInt(-self.dateOffsetMinutes(milliseconds)) };
    }

    fn nativeDateGetYear(self: *Runtime, receiver: Value) Error!Value {
        var value = try self.nativeDateGet(receiver, .full_year, false);
        if (value == .number and std.math.isFinite(value.number)) value.number -= 1900;
        return value;
    }

    fn nativeDateSetTime(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const index = try self.expectObject(receiver);
        if (self.cells[index].host_tag != date_tag) return error.TypeError;
        const value = timeClip(try self.toNumber(if (arguments.len > 0) arguments[0] else .undefined));
        self.cells[index].receiver = .{ .number = value };
        return .{ .number = value };
    }

    fn nativeDateSetYear(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        var year = try self.dateIntegerArgument(arguments, 0) orelse {
            const index = try self.expectObject(receiver);
            if (self.cells[index].host_tag != date_tag) return error.TypeError;
            return self.invalidateDate(index);
        };
        if (year >= 0 and year <= 99) year += 1900;
        return self.nativeDateSet(receiver, &.{.{ .number = @floatFromInt(year) }}, .full_year, false);
    }

    fn nativeDateSet(self: *Runtime, receiver: Value, arguments: []const Value, setter: DateSetter, utc: bool) Error!Value {
        const index = try self.expectObject(receiver);
        if (self.cells[index].host_tag != date_tag) return error.TypeError;
        var milliseconds = self.cells[index].receiver.number;
        if (!std.math.isFinite(milliseconds)) {
            if (setter != .full_year) return .{ .number = std.math.nan(f64) };
            milliseconds = 0;
        }
        const offset = if (utc) 0 else self.dateOffsetMinutes(milliseconds);
        const base = milliseconds + @as(f64, @floatFromInt(offset)) * 60000.0;
        var parts = dateParts(@intFromFloat(base));
        switch (setter) {
            .date => parts.date = try self.dateIntegerArgument(arguments, 0) orelse return self.invalidateDate(index),
            .full_year => {
                parts.year = try self.dateIntegerArgument(arguments, 0) orelse return self.invalidateDate(index);
                parts.month = try self.dateIntegerArgumentDefault(arguments, 1, parts.month) orelse return self.invalidateDate(index);
                parts.date = try self.dateIntegerArgumentDefault(arguments, 2, parts.date) orelse return self.invalidateDate(index);
            },
            .hours => {
                parts.hours = try self.dateIntegerArgument(arguments, 0) orelse return self.invalidateDate(index);
                parts.minutes = try self.dateIntegerArgumentDefault(arguments, 1, parts.minutes) orelse return self.invalidateDate(index);
                parts.seconds = try self.dateIntegerArgumentDefault(arguments, 2, parts.seconds) orelse return self.invalidateDate(index);
                parts.milliseconds = try self.dateIntegerArgumentDefault(arguments, 3, parts.milliseconds) orelse return self.invalidateDate(index);
            },
            .milliseconds => parts.milliseconds = try self.dateIntegerArgument(arguments, 0) orelse return self.invalidateDate(index),
            .minutes => {
                parts.minutes = try self.dateIntegerArgument(arguments, 0) orelse return self.invalidateDate(index);
                parts.seconds = try self.dateIntegerArgumentDefault(arguments, 1, parts.seconds) orelse return self.invalidateDate(index);
                parts.milliseconds = try self.dateIntegerArgumentDefault(arguments, 2, parts.milliseconds) orelse return self.invalidateDate(index);
            },
            .month => {
                parts.month = try self.dateIntegerArgument(arguments, 0) orelse return self.invalidateDate(index);
                parts.date = try self.dateIntegerArgumentDefault(arguments, 1, parts.date) orelse return self.invalidateDate(index);
            },
            .seconds => {
                parts.seconds = try self.dateIntegerArgument(arguments, 0) orelse return self.invalidateDate(index);
                parts.milliseconds = try self.dateIntegerArgumentDefault(arguments, 1, parts.milliseconds) orelse return self.invalidateDate(index);
            },
        }
        const composed = makeDateMilliseconds(parts.year, parts.month, parts.date, parts.hours, parts.minutes, parts.seconds, parts.milliseconds);
        const utc_value = if (utc) @as(f64, @floatFromInt(composed)) else self.utcFromLocalMilliseconds(composed);
        const clipped = timeClip(utc_value);
        self.cells[index].receiver = .{ .number = clipped };
        return .{ .number = clipped };
    }

    fn invalidateDate(self: *Runtime, index: u16) Value {
        self.cells[index].receiver = .{ .number = std.math.nan(f64) };
        return .{ .number = std.math.nan(f64) };
    }

    fn nativeDateFormat(self: *Runtime, receiver: Value, format: DateFormat) Error!Value {
        return self.nativeDateFormatValue(try self.dateValue(receiver), format);
    }

    fn nativeDateFormatValue(self: *Runtime, milliseconds: f64, format: DateFormat) Error!Value {
        if (!std.math.isFinite(milliseconds)) {
            if (format == .iso) return error.RangeError;
            return .{ .string = try self.storeString("Invalid Date") };
        }
        const utc = format == .iso or format == .utc;
        const offset = if (utc) 0 else self.dateOffsetMinutes(milliseconds);
        const parts = dateParts(@intFromFloat(milliseconds + @as(f64, @floatFromInt(offset)) * 60000.0));
        var buffer: [128]u8 = undefined;
        var length: usize = 0;
        switch (format) {
            .iso => try formatIsoDate(buffer[0..], &length, parts),
            .utc => try formatUtcDate(buffer[0..], &length, parts),
            .date => try formatDateOnly(buffer[0..], &length, parts),
            .time => try formatTimeOnly(buffer[0..], &length, parts, offset),
            .string => {
                try formatDateOnly(buffer[0..], &length, parts);
                try appendBytes(buffer[0..], &length, " ");
                try formatTimeOnly(buffer[0..], &length, parts, offset);
            },
            .locale_date => try formatLocaleDate(buffer[0..], &length, parts),
            .locale_time => try formatLocaleTime(buffer[0..], &length, parts),
            .locale_date_time => {
                try formatLocaleDate(buffer[0..], &length, parts);
                try appendBytes(buffer[0..], &length, ", ");
                try formatLocaleTime(buffer[0..], &length, parts);
            },
        }
        return .{ .string = try self.storeString(buffer[0..length]) };
    }

    fn nativeDateToJson(self: *Runtime, program: *const Program, receiver: Value) Error!Value {
        const primitive = try self.toPrimitive(receiver, .number);
        if (primitive == .number and !std.math.isFinite(primitive.number)) return .null_value;
        const method = try self.getProperty(receiver, "toISOString");
        if (!self.isCallableValue(method)) return error.TypeError;
        return self.call(program, method, receiver, &.{}, false);
    }

    fn nativeDateToPrimitive(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        _ = try self.expectObject(receiver);
        if (arguments.len == 0 or arguments[0] != .string) return error.TypeError;
        const hint = self.stringBytes(arguments[0].string);
        const prefer_string = equals(hint, "string") or equals(hint, "default");
        if (!prefer_string and !equals(hint, "number")) return error.TypeError;
        const first = if (prefer_string) "toString" else "valueOf";
        const second = if (prefer_string) "valueOf" else "toString";
        for ([_][]const u8{ first, second }) |name| {
            const method = try self.getProperty(receiver, name);
            if (!self.isCallableValue(method)) continue;
            const value = try self.call(program, method, receiver, &.{}, false);
            if (value != .cell) return value;
        }
        return error.TypeError;
    }

    fn parseDateString(self: *Runtime, input: []const u8) Error!f64 {
        const text = std.mem.trim(u8, input, " \t\r\n");
        if (parseIsoDateTime(text)) |parsed| {
            var milliseconds: f64 = @floatFromInt(parsed.milliseconds);
            if (parsed.local) milliseconds = self.utcFromLocalMilliseconds(parsed.milliseconds);
            return timeClip(milliseconds);
        }
        if (parseRfcDateTime(text)) |milliseconds| return timeClip(@floatFromInt(milliseconds));
        if (parseRuntimeDateTime(text)) |milliseconds| return timeClip(@floatFromInt(milliseconds));
        return std.math.nan(f64);
    }

    fn nativeSymbol(self: *Runtime, arguments: []const Value) Error!Value {
        if (arguments.len == 0 or arguments[0] == .undefined) return self.makeSymbolOptional(null);
        return self.makeSymbol((try self.toString(arguments[0])).bytes(self.strings[0..self.string_len]));
    }

    fn nativeSymbolFor(self: *Runtime, arguments: []const Value) Error!Value {
        const key = try self.toString(if (arguments.len > 0) arguments[0] else .undefined);
        for (self.symbol_registry[0..self.symbol_registry_count]) |entry| {
            if (equals(self.stringBytes(entry.key), self.stringBytes(key))) return .{ .string = entry.symbol };
        }
        if (self.symbol_registry_count >= self.symbol_registry.len) return error.PropertyLimit;
        const symbol = try self.makeSymbol(self.stringBytes(key));
        self.symbol_registry[self.symbol_registry_count] = .{ .key = key, .symbol = symbol.string };
        self.symbol_registry_count += 1;
        return symbol;
    }

    fn nativeSymbolKeyFor(self: *Runtime, arguments: []const Value) Error!Value {
        if (arguments.len == 0 or !self.isSymbolValue(arguments[0])) return error.TypeError;
        for (self.symbol_registry[0..self.symbol_registry_count]) |entry| {
            if (equals(self.stringBytes(entry.symbol), self.stringBytes(arguments[0].string))) return .{ .string = entry.key };
        }
        return .undefined;
    }

    fn symbolValue(self: *Runtime, receiver: Value) Error!Value {
        if (self.isSymbolValue(receiver)) return receiver;
        if (receiver == .cell and receiver.cell < self.cells.len and self.cells[receiver.cell].occupied and
            self.cells[receiver.cell].host_tag == boxed_symbol_tag and self.isSymbolValue(self.cells[receiver.cell].receiver))
        {
            return self.cells[receiver.cell].receiver;
        }
        return error.TypeError;
    }

    fn nativeSymbolToString(self: *Runtime, receiver: Value) Error!Value {
        const symbol = try self.symbolValue(receiver);
        const parts = self.symbolParts(symbol.string) orelse return error.TypeError;
        var output: usize = 0;
        try appendBytes(self.string_scratch[0..], &output, "Symbol(");
        if (parts.has_description) try appendBytes(self.string_scratch[0..], &output, parts.description);
        try appendBytes(self.string_scratch[0..], &output, ")");
        return .{ .string = try self.storeString(self.string_scratch[0..output]) };
    }

    fn nativeSymbolDescription(self: *Runtime, receiver: Value) Error!Value {
        const symbol = try self.symbolValue(receiver);
        const parts = self.symbolParts(symbol.string) orelse return error.TypeError;
        return if (parts.has_description) .{ .string = try self.storeString(parts.description) } else .undefined;
    }

    fn nativeAtob(self: *Runtime, arguments: []const Value) Error!Value {
        const source = (try self.toString(if (arguments.len > 0) arguments[0] else .undefined)).bytes(self.strings[0..self.string_len]);
        var decoded: [64 * 1024]u8 = undefined;
        var decoded_len: usize = 0;
        var accumulator: u32 = 0;
        var bits: u8 = 0;
        for (source) |byte| {
            if (std.ascii.isWhitespace(byte)) continue;
            if (byte == '=') break;
            const value = base64Value(byte) orelse return error.TypeError;
            accumulator = (accumulator << 6) | value;
            bits += 6;
            if (bits >= 8) {
                bits -= 8;
                if (decoded_len >= decoded.len) return error.StringLimit;
                decoded[decoded_len] = @truncate(accumulator >> @intCast(bits));
                decoded_len += 1;
                accumulator &= if (bits == 0) 0 else (@as(u32, 1) << @intCast(bits)) - 1;
            }
        }
        var output_len: usize = 0;
        for (decoded[0..decoded_len]) |byte| try appendUtf8CodePoint(self.string_scratch[0..], &output_len, byte);
        return .{ .string = try self.storeString(self.string_scratch[0..output_len]) };
    }

    fn nativeBtoa(self: *Runtime, arguments: []const Value) Error!Value {
        const source = (try self.toString(if (arguments.len > 0) arguments[0] else .undefined)).bytes(self.strings[0..self.string_len]);
        const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        var binary: [48 * 1024]u8 = undefined;
        var binary_len: usize = 0;
        var cursor: usize = 0;
        while (cursor < source.len) {
            const scalar = runtimeStringDecode(source, cursor);
            if (scalar.value > 0xff) return error.TypeError;
            if (binary_len >= binary.len) return error.StringLimit;
            binary[binary_len] = @intCast(scalar.value);
            binary_len += 1;
            cursor += scalar.length;
        }
        var output: [64 * 1024]u8 = undefined;
        const encoded_len = ((binary_len + 2) / 3) * 4;
        if (encoded_len > output.len) return error.StringLimit;
        var source_index: usize = 0;
        var output_index: usize = 0;
        while (source_index < binary_len) : (source_index += 3) {
            const first: u32 = binary[source_index];
            const second: u32 = if (source_index + 1 < binary_len) binary[source_index + 1] else 0;
            const third: u32 = if (source_index + 2 < binary_len) binary[source_index + 2] else 0;
            const value = (first << 16) | (second << 8) | third;
            output[output_index] = alphabet[@intCast((value >> 18) & 63)];
            output[output_index + 1] = alphabet[@intCast((value >> 12) & 63)];
            output[output_index + 2] = if (source_index + 1 < binary_len) alphabet[@intCast((value >> 6) & 63)] else '=';
            output[output_index + 3] = if (source_index + 2 < binary_len) alphabet[@intCast(value & 63)] else '=';
            output_index += 4;
        }
        return .{ .string = try self.storeString(output[0..encoded_len]) };
    }

    fn makeSymbol(self: *Runtime, description: []const u8) Error!Value {
        return self.makeSymbolOptional(description);
    }

    fn makeSymbolOptional(self: *Runtime, description: ?[]const u8) Error!Value {
        var id_buffer: [24]u8 = undefined;
        const id = std.fmt.bufPrint(id_buffer[0..], "{d}", .{self.next_symbol_id}) catch return error.StringLimit;
        var output: usize = 0;
        try appendBytes(self.string_scratch[0..], &output, symbol_prefix);
        try appendBytes(self.string_scratch[0..], &output, id);
        try appendBytes(self.string_scratch[0..], &output, ":");
        try appendBytes(self.string_scratch[0..], &output, if (description != null) "1" else "0");
        if (description) |text| try appendBytes(self.string_scratch[0..], &output, text);
        self.next_symbol_id +%= 1;
        return .{ .string = try self.storeString(self.string_scratch[0..output]) };
    }

    fn isSymbolValue(self: *const Runtime, value: Value) bool {
        return value == .string and self.symbolParts(value.string) != null;
    }

    fn symbolId(self: *const Runtime, ref: StringRef) ?usize {
        const bytes = self.stringBytes(ref);
        if (!std.mem.startsWith(u8, bytes, symbol_prefix)) return null;
        const marker = std.mem.indexOfScalarPos(u8, bytes, symbol_prefix.len, ':') orelse return null;
        const id = std.fmt.parseInt(usize, bytes[symbol_prefix.len..marker], 10) catch return null;
        return id;
    }

    fn symbolParts(self: *const Runtime, ref: StringRef) ?SymbolParts {
        const bytes = self.stringBytes(ref);
        if (!std.mem.startsWith(u8, bytes, symbol_prefix)) return null;
        const marker = std.mem.indexOfScalarPos(u8, bytes, symbol_prefix.len, ':') orelse return null;
        if (marker + 1 >= bytes.len or (bytes[marker + 1] != '0' and bytes[marker + 1] != '1')) return null;
        return .{ .has_description = bytes[marker + 1] == '1', .description = bytes[marker + 2 ..] };
    }

    fn storeStringUnits(self: *Runtime, source: []const u8, start: usize, end: usize) Error!StringRef {
        var output: usize = 0;
        try appendRuntimeStringUnits(self.string_scratch[0..], &output, source, start, end);
        return self.storeString(self.string_scratch[0..output]);
    }

    fn nativeRegexExec(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        if (!self.isRegex(receiver)) return error.TypeError;
        const pattern_value = try self.getProperty(receiver, "source");
        const flags_value = try self.getProperty(receiver, "flags");
        const original_pattern = (try self.toString(pattern_value)).bytes(self.strings[0..self.string_len]);
        const flags = (try self.toString(flags_value)).bytes(self.strings[0..self.string_len]);
        const input_ref = try self.toString(if (arguments.len > 0) arguments[0] else .undefined);
        const original_input = self.stringBytes(input_ref);
        const unicode_mode = std.mem.indexOfScalar(u8, flags, 'u') != null or std.mem.indexOfScalar(u8, flags, 'v') != null;
        var pattern = original_pattern;
        var input = original_input;
        if (!unicode_mode) {
            const pattern_length = try regexExpandCodeUnits(original_pattern, self.regex_pattern_scratch[0..]);
            const input_byte_length = try regexExpandCodeUnits(original_input, self.regex_input_scratch[0..]);
            pattern = self.regex_pattern_scratch[0..pattern_length];
            input = self.regex_input_scratch[0..input_byte_length];
        }
        const regex_global = std.mem.indexOfScalar(u8, flags, 'g') != null;
        const sticky = std.mem.indexOfScalar(u8, flags, 'y') != null;
        const use_last_index = regex_global or sticky;
        const input_length = runtimeStringUnitCount(original_input);
        const last_index = if (use_last_index) last_index: {
            const number = try self.toNumber(try self.getProperty(receiver, "lastIndex"));
            if (std.math.isNan(number) or number <= 0) break :last_index 0;
            if (!std.math.isFinite(number)) {
                try self.setProperty(receiver, "lastIndex", .{ .number = 0 });
                return .null_value;
            }
            const integer = @trunc(number);
            if (integer > @as(f64, @floatFromInt(input_length))) {
                try self.setProperty(receiver, "lastIndex", .{ .number = 0 });
                return .null_value;
            }
            break :last_index @as(usize, @intFromFloat(integer));
        } else 0;
        const start_byte = runtimeStringByteOffsetAtUnit(input, last_index) orelse {
            if (use_last_index) try self.setProperty(receiver, "lastIndex", .{ .number = 0 });
            return .null_value;
        };
        const found = (try regexFind(pattern, input, .{
            .ignore_case = std.mem.indexOfScalar(u8, flags, 'i') != null,
            .multiline = std.mem.indexOfScalar(u8, flags, 'm') != null,
            .dot_all = std.mem.indexOfScalar(u8, flags, 's') != null,
            .unicode = unicode_mode,
            .unicode_sets = std.mem.indexOfScalar(u8, flags, 'v') != null,
        }, start_byte, sticky)) orelse {
            if (use_last_index) try self.setProperty(receiver, "lastIndex", .{ .number = 0 });
            return .null_value;
        };
        const start = runtimeStringUnitCount(input[0..found.start]);
        const end = start + runtimeStringUnitCount(input[found.start..found.end]);
        if (use_last_index) try self.setProperty(receiver, "lastIndex", .{ .number = @floatFromInt(end) });
        var values: [max_regex_captures + 1]Value = undefined;
        values[0] = .{ .string = try self.storeStringUnits(original_input, start, end) };
        for (0..found.capture_count) |capture_index| {
            const capture = found.captures[capture_index];
            if (capture.matched()) {
                const capture_start_byte: usize = @intCast(capture.start);
                const capture_end_byte: usize = @intCast(capture.end);
                const capture_start = runtimeStringUnitCount(input[0..capture_start_byte]);
                const capture_end = capture_start + runtimeStringUnitCount(input[capture_start_byte..capture_end_byte]);
                values[capture_index + 1] = .{ .string = try self.storeStringUnits(original_input, capture_start, capture_end) };
            } else values[capture_index + 1] = .undefined;
        }
        const result = try self.arrayFromValues(values[0 .. found.capture_count + 1]);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(result);
        try self.setProperty(result, "index", .{ .number = @floatFromInt(start) });
        try self.setProperty(result, "input", .{ .string = input_ref });
        var has_named_captures = false;
        for (0..found.capture_count) |capture_index| {
            if (regexNamedCapture(pattern, capture_index) != null) {
                has_named_captures = true;
                break;
            }
        }
        if (has_named_captures) {
            const groups: Value = .{ .cell = try self.allocateCell(.object) };
            self.cells[groups.cell].prototype = none;
            try self.pushRoot(groups);
            for (0..found.capture_count) |capture_index| {
                if (regexNamedCapture(pattern, capture_index)) |name| {
                    const decoded_name = regexCaptureNameDecode(name, self.string_scratch[0..]) orelse return error.SyntaxError;
                    if (values[capture_index + 1] != .undefined or !(try self.hasOwnProperty(groups, decoded_name)))
                        try self.setProperty(groups, decoded_name, values[capture_index + 1]);
                }
            }
            try self.setProperty(result, "groups", groups);
        } else {
            try self.setProperty(result, "groups", .undefined);
        }
        if (std.mem.indexOfScalar(u8, flags, 'd') != null) {
            var index_values: [max_regex_captures + 1]Value = undefined;
            index_values[0] = try self.arrayFromValues(&.{ .{ .number = @floatFromInt(start) }, .{ .number = @floatFromInt(end) } });
            try self.pushRoot(index_values[0]);
            for (0..found.capture_count) |capture_index| {
                const capture = found.captures[capture_index];
                if (!capture.matched()) {
                    index_values[capture_index + 1] = .undefined;
                    continue;
                }
                const capture_start_byte: usize = @intCast(capture.start);
                const capture_end_byte: usize = @intCast(capture.end);
                const capture_start = runtimeStringUnitCount(input[0..capture_start_byte]);
                const capture_end = capture_start + runtimeStringUnitCount(input[capture_start_byte..capture_end_byte]);
                index_values[capture_index + 1] = try self.arrayFromValues(&.{ .{ .number = @floatFromInt(capture_start) }, .{ .number = @floatFromInt(capture_end) } });
                try self.pushRoot(index_values[capture_index + 1]);
            }
            const indices = try self.arrayFromValues(index_values[0 .. found.capture_count + 1]);
            try self.pushRoot(indices);
            if (has_named_captures) {
                const index_groups: Value = .{ .cell = try self.allocateCell(.object) };
                self.cells[index_groups.cell].prototype = none;
                try self.pushRoot(index_groups);
                for (0..found.capture_count) |capture_index| {
                    if (regexNamedCapture(pattern, capture_index)) |name| {
                        const decoded_name = regexCaptureNameDecode(name, self.string_scratch[0..]) orelse return error.SyntaxError;
                        if (index_values[capture_index + 1] != .undefined or !(try self.hasOwnProperty(index_groups, decoded_name)))
                            try self.setProperty(index_groups, decoded_name, index_values[capture_index + 1]);
                    }
                }
                try self.setProperty(indices, "groups", index_groups);
            } else {
                try self.setProperty(indices, "groups", .undefined);
            }
            try self.setProperty(result, "indices", indices);
        }
        return result;
    }

    fn regexExec(self: *Runtime, program: *const Program, receiver: Value, input: Value) Error!Value {
        const exec = try self.getProperty(receiver, "exec");
        if (self.isCallableValue(exec)) {
            const result = try self.call(program, exec, receiver, &.{input}, false);
            if (result == .null_value) return result;
            _ = try self.expectObject(result);
            return result;
        }
        if (!self.isRegex(receiver)) return error.TypeError;
        return self.nativeRegexExec(receiver, &.{input});
    }

    fn nativeRegexTest(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        const input: Value = .{ .string = try self.toString(if (arguments.len > 0) arguments[0] else .undefined) };
        return .{ .boolean = (try self.regexExec(program, receiver, input)) != .null_value };
    }

    fn nativeRegexToString(self: *Runtime, receiver: Value) Error!Value {
        _ = try self.expectObject(receiver);
        const source = (try self.toString(try self.getProperty(receiver, "source"))).bytes(self.strings[0..self.string_len]);
        const flags = (try self.toString(try self.getProperty(receiver, "flags"))).bytes(self.strings[0..self.string_len]);
        var buffer: [max_source_bytes]u8 = undefined;
        var output: usize = 0;
        try appendBytes(buffer[0..], &output, "/");
        try appendBytes(buffer[0..], &output, if (source.len == 0) "(?:)" else source);
        try appendBytes(buffer[0..], &output, "/");
        try appendBytes(buffer[0..], &output, flags);
        return .{ .string = try self.storeString(buffer[0..output]) };
    }

    fn nativeParseInt(self: *Runtime, arguments: []const Value) Error!Value {
        const source = (try self.toString(if (arguments.len > 0) arguments[0] else .undefined)).bytes(self.strings[0..self.string_len]);
        const text = trimNumberWhitespace(source);
        if (text.len == 0) return .{ .number = std.math.nan(f64) };
        var cursor: usize = 0;
        var negative = false;
        if (text[cursor] == '+' or text[cursor] == '-') {
            negative = text[cursor] == '-';
            cursor += 1;
        }
        var radix_value: i32 = 0;
        if (arguments.len > 1 and arguments[1] != .undefined) radix_value = toInt32(try self.toNumber(arguments[1]));
        if (radix_value != 0 and (radix_value < 2 or radix_value > 36)) return .{ .number = std.math.nan(f64) };
        var radix: u8 = if (radix_value == 0) 10 else @intCast(radix_value);
        if (cursor + 2 <= text.len and text[cursor] == '0' and (text[cursor + 1] == 'x' or text[cursor + 1] == 'X') and
            (radix_value == 0 or radix == 16))
        {
            radix = 16;
            cursor += 2;
        }
        var value: f64 = 0;
        var digits: usize = 0;
        while (cursor < text.len) : (cursor += 1) {
            const digit = numberDigitValue(text[cursor]) orelse break;
            if (digit >= radix) break;
            value = value * @as(f64, @floatFromInt(radix)) + @as(f64, @floatFromInt(digit));
            digits += 1;
        }
        if (digits == 0) return .{ .number = std.math.nan(f64) };
        return .{ .number = if (negative) -value else value };
    }

    fn nativeEval(self: *Runtime, arguments: []const Value, direct: bool) Error!Value {
        if (arguments.len == 0 or arguments[0] != .string) return if (arguments.len > 0) arguments[0] else .undefined;
        const source = self.stringBytes(arguments[0].string);
        const previous_environment = self.active_env;
        if (!direct) self.active_env = self.global_env;
        defer self.active_env = previous_environment;
        var selected: ?usize = null;
        var selected_existing = false;
        var lane_index: usize = 0;
        while (lane_index < self.dynamic_program_count) : (lane_index += 1) {
            const lane = self.dynamic_programs[lane_index] orelse continue;
            if (lane == self.active_program or lane == self.diagnostic_program) continue;
            if (lane.source_len + 2 + source.len > max_source_bytes) continue;
            selected = lane_index;
            selected_existing = true;
            break;
        }
        if (selected == null) {
            if (self.dynamic_program_count >= self.dynamic_programs.len) return error.ModuleLimit;
            selected = self.dynamic_program_count;
        }

        const selected_index = selected.?;
        const existing = if (selected_existing) self.dynamic_programs[selected_index].? else null;
        var previous_statements: usize = 0;
        if (existing) |program| {
            var statement = program.nodes[program.root].a;
            while (statement != none) : (statement = program.nodes[statement].next) previous_statements += 1;
        }

        const candidate = self.program_allocator.create(self.program_allocator.context) orelse return error.ProgramAllocation;
        var combined_length: usize = 0;
        if (existing) |program| {
            @memcpy(candidate.source[0..program.source_len], program.source[0..program.source_len]);
            combined_length = program.source_len;
            candidate.source[combined_length] = ';';
            candidate.source[combined_length + 1] = '\n';
            combined_length += 2;
        }
        @memcpy(candidate.source[combined_length .. combined_length + source.len], source);
        combined_length += source.len;
        const parent_source_name = if (self.active_program) |active| active.sourceName() else "<script>";
        _ = candidate.parse(candidate.source[0..combined_length]) catch |err| {
            candidate.setDerivedSourceName(parent_source_name, "#eval");
            self.captureProgramDiagnostic(candidate, err);
            self.program_allocator.destroy(self.program_allocator.context, candidate);
            return if (err == error.UnexpectedToken or err == error.InvalidAssignment or err == error.ConstAssignment)
                error.SyntaxError
            else
                err;
        };
        candidate.setDerivedSourceName(parent_source_name, "#eval");
        if (candidate.module_statement_count != 0) {
            self.program_allocator.destroy(self.program_allocator.context, candidate);
            return error.SyntaxError;
        }

        const program = if (existing) |current| blk: {
            current.* = candidate.*;
            self.program_allocator.destroy(self.program_allocator.context, candidate);
            break :blk current;
        } else blk: {
            self.dynamic_programs[selected_index] = candidate;
            self.dynamic_program_count += 1;
            break :blk candidate;
        };

        var statement = program.nodes[program.root].a;
        var skipped: usize = 0;
        while (statement != none and skipped < previous_statements) : (skipped += 1) statement = program.nodes[statement].next;
        var completion: Completion = .{};
        while (statement != none) {
            const next = program.nodes[statement].next;
            completion = try self.executeBytecodeNode(program, statement, self.active_env);
            if (completion.kind == .thrown) return error.ScriptThrown;
            if (completion.kind != .normal) break;
            statement = next;
        }
        return completion.value;
    }

    fn nativeMath(self: *Runtime, arguments: []const Value, maximum: bool) Error!Value {
        if (arguments.len == 0) return .{ .number = if (maximum) -std.math.inf(f64) else std.math.inf(f64) };
        var result = try self.toNumber(arguments[0]);
        for (arguments[1..]) |argument| {
            const value = try self.toNumber(argument);
            if (std.math.isNan(result) or std.math.isNan(value)) {
                result = std.math.nan(f64);
                continue;
            }
            if (maximum) {
                if (value > result or (value == 0 and result == 0 and std.math.signbit(result) and !std.math.signbit(value))) result = value;
            } else {
                if (value < result or (value == 0 and result == 0 and !std.math.signbit(result) and std.math.signbit(value))) result = value;
            }
        }
        return .{ .number = result };
    }

    fn nativeMathRound(self: *Runtime, arguments: []const Value) Error!Value {
        const number = try self.toNumber(if (arguments.len > 0) arguments[0] else .undefined);
        if (!std.math.isFinite(number) or number == 0) return .{ .number = number };
        if (number < 0 and number >= -0.5) return .{ .number = -0.0 };
        return .{ .number = @floor(number + 0.5) };
    }

    fn nativeMathUnary(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        if (receiver != .number or !std.math.isFinite(receiver.number)) return error.TypeError;
        const raw_operation = @as(i64, @intFromFloat(receiver.number));
        if (raw_operation < 0 or raw_operation > @intFromEnum(MathUnary.trunc)) return error.TypeError;
        const operation: MathUnary = @enumFromInt(@as(u8, @intCast(raw_operation)));
        const number = try self.toNumber(if (arguments.len > 0) arguments[0] else .undefined);
        const result: f64 = switch (operation) {
            .acos => std.math.acos(number),
            .acosh => std.math.acosh(number),
            .asin => std.math.asin(number),
            .asinh => std.math.asinh(number),
            .atan => std.math.atan(number),
            .atanh => std.math.atanh(number),
            .cbrt => std.math.cbrt(number),
            .ceil => @ceil(number),
            .cos => @cos(number),
            .cosh => std.math.cosh(number),
            .exp => @exp(number),
            .expm1 => std.math.expm1(number),
            .fround => @floatCast(@as(f32, @floatCast(number))),
            .f16round => @floatCast(@as(f16, @floatCast(number))),
            .log => @log(number),
            .log1p => std.math.log1p(number),
            .log10 => std.math.log10(number),
            .log2 => std.math.log2(number),
            .sign => if (std.math.isNan(number) or number == 0) number else if (number < 0) -1 else 1,
            .sin => @sin(number),
            .sinh => std.math.sinh(number),
            .tan => @tan(number),
            .tanh => std.math.tanh(number),
            .trunc => @trunc(number),
        };
        return .{ .number = result };
    }

    fn nativeMathAtan2(self: *Runtime, arguments: []const Value) Error!Value {
        const y = try self.toNumber(if (arguments.len > 0) arguments[0] else .undefined);
        const x = try self.toNumber(if (arguments.len > 1) arguments[1] else .undefined);
        return .{ .number = std.math.atan2(y, x) };
    }

    fn nativeMathClz32(self: *Runtime, arguments: []const Value) Error!Value {
        const value = toUint32(try self.toNumber(if (arguments.len > 0) arguments[0] else .undefined));
        return .{ .number = @floatFromInt(@clz(value)) };
    }

    fn nativeMathHypot(self: *Runtime, arguments: []const Value) Error!Value {
        var scale: f64 = 0;
        var squares: f64 = 0;
        var saw_nan = false;
        var saw_infinity = false;
        for (arguments) |argument| {
            const converted = try self.toNumber(argument);
            if (std.math.isNan(converted)) {
                saw_nan = true;
                continue;
            }
            if (std.math.isInf(converted)) {
                saw_infinity = true;
                continue;
            }
            const value = @abs(converted);
            if (value == 0) continue;
            if (value > scale) {
                const ratio = if (scale == 0) 0 else scale / value;
                squares = squares * ratio * ratio + 1;
                scale = value;
            } else {
                const ratio = value / scale;
                squares += ratio * ratio;
            }
        }
        if (saw_infinity) return .{ .number = std.math.inf(f64) };
        if (saw_nan) return .{ .number = std.math.nan(f64) };
        return .{ .number = if (scale == 0) 0 else scale * @sqrt(squares) };
    }

    fn nativeMathImul(self: *Runtime, arguments: []const Value) Error!Value {
        const left = toUint32(try self.toNumber(if (arguments.len > 0) arguments[0] else .undefined));
        const right = toUint32(try self.toNumber(if (arguments.len > 1) arguments[1] else .undefined));
        const product: i32 = @bitCast(left *% right);
        return .{ .number = @floatFromInt(product) };
    }

    fn nativeMathPow(self: *Runtime, arguments: []const Value) Error!Value {
        const base = try self.toNumber(if (arguments.len > 0) arguments[0] else .undefined);
        const exponent = try self.toNumber(if (arguments.len > 1) arguments[1] else .undefined);
        if (@abs(base) == 1 and std.math.isInf(exponent)) return .{ .number = std.math.nan(f64) };
        return .{ .number = std.math.pow(f64, base, exponent) };
    }

    fn nativeMathSumPrecise(self: *Runtime, program: *const Program, arguments: []const Value) Error!Value {
        if (arguments.len == 0 or arguments[0].isNullish()) return error.TypeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(arguments[0]);
        var cursor = try self.openIterator(program, arguments[0]);
        try self.rootIterator(cursor);
        errdefer self.iteratorClose(program, &cursor) catch {};

        var partials: [2048]f64 = undefined;
        var partial_count: usize = 0;
        var saw_finite = false;
        var saw_nan = false;
        var saw_positive_infinity = false;
        var saw_negative_infinity = false;
        while (true) {
            const step = try self.iteratorNext(program, &cursor);
            if (step.done) break;
            if (step.value != .number) return error.TypeError;
            var value = step.value.number;
            if (std.math.isNan(value)) {
                saw_nan = true;
                continue;
            }
            if (std.math.isPositiveInf(value)) {
                saw_positive_infinity = true;
                continue;
            }
            if (std.math.isNegativeInf(value)) {
                saw_negative_infinity = true;
                continue;
            }
            if (value == 0 and std.math.signbit(value)) continue;
            saw_finite = true;
            var write_index: usize = 0;
            for (partials[0..partial_count]) |partial_value| {
                var partial = partial_value;
                if (@abs(value) < @abs(partial)) std.mem.swap(f64, &value, &partial);
                const high = value + partial;
                const low = partial - (high - value);
                if (low != 0) {
                    partials[write_index] = low;
                    write_index += 1;
                }
                value = high;
            }
            if (write_index >= partials.len) return error.RangeError;
            partials[write_index] = value;
            partial_count = write_index + 1;
        }
        if (saw_nan or (saw_positive_infinity and saw_negative_infinity)) return .{ .number = std.math.nan(f64) };
        if (saw_positive_infinity) return .{ .number = std.math.inf(f64) };
        if (saw_negative_infinity) return .{ .number = -std.math.inf(f64) };
        if (!saw_finite) return .{ .number = -0.0 };
        var sum: f64 = 0;
        var index = partial_count;
        while (index > 0) {
            index -= 1;
            sum += partials[index];
        }
        return .{ .number = sum };
    }

    fn nativeMathRandom(self: *Runtime) Value {
        var state = self.random_state;
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        self.random_state = state;
        return .{ .number = @as(f64, @floatFromInt(state >> 11)) / 9007199254740992.0 };
    }

    fn nativeJsonParse(self: *Runtime, program: *const Program, arguments: []const Value) Error!Value {
        const source = (try self.toString(if (arguments.len > 0) arguments[0] else .undefined)).bytes(self.strings[0..self.string_len]);
        const reviver = arguments.len >= 2 and self.isCallableValue(arguments[1]);
        const record_capacity = if (reviver) @min(source.len + 1, max_items + 1) else 0;
        const record_bytes = record_capacity * @sizeOf(JsonSourceRecord);
        const record_memory = if (record_bytes > 0)
            self.program_allocator.allocate(self.program_allocator.context, record_bytes, @alignOf(JsonSourceRecord)) orelse return error.ProgramAllocation
        else
            null;
        defer if (record_memory) |memory|
            self.program_allocator.free(self.program_allocator.context, memory, record_bytes, @alignOf(JsonSourceRecord));
        const records: []JsonSourceRecord = if (record_memory) |memory| blk: {
            const pointer: [*]JsonSourceRecord = @ptrCast(@alignCast(memory));
            break :blk pointer[0..record_capacity];
        } else &.{};
        var parser = JsonParser{ .runtime = self, .source = source, .records = records };
        const value = try parser.parse();
        if (!reviver) return value;
        if (value != .cell) try parser.addSource(none, "", value, parser.root_start, parser.root_end);

        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(value);
        const holder = Value{ .cell = try self.allocateCell(.object) };
        try self.pushRoot(holder);
        try self.defineOwnDataProperty(holder, "", value);
        return self.walkJsonReviver(program, arguments[1], holder, "", records[0..parser.record_count], 0);
    }

    fn walkJsonReviver(self: *Runtime, program: *const Program, reviver: Value, holder: Value, key: []const u8, records: []const JsonSourceRecord, depth: usize) Error!Value {
        if (depth >= 64) return error.RangeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(holder);
        try self.pushRoot(reviver);
        const value = try self.getProperty(holder, key);
        try self.pushRoot(value);
        if (value == .cell) {
            const index = try self.expectObject(value);
            if (self.cells[index].kind == .array) {
                const length = self.effectiveArrayLength(index);
                var item_index: usize = 0;
                while (item_index < length) : (item_index += 1) {
                    var key_buffer: [32]u8 = undefined;
                    const item_key = std.fmt.bufPrint(key_buffer[0..], "{d}", .{item_index}) catch return error.StringLimit;
                    const revived = try self.walkJsonReviver(program, reviver, value, item_key, records, depth + 1);
                    if (revived == .undefined)
                        _ = try self.deleteOwnProperty(value, item_key)
                    else
                        try self.defineOwnDataProperty(value, item_key, revived);
                }
            } else {
                var keys: [max_properties]StringRef = undefined;
                var key_count: usize = 0;
                for (self.propertyStorageConst(index)[0..self.cells[index].property_count]) |property| {
                    if (!property.enumerable) continue;
                    keys[key_count] = property.key;
                    key_count += 1;
                }
                for (keys[0..key_count]) |property_key| {
                    const property_name = self.stringBytes(property_key);
                    const revived = try self.walkJsonReviver(program, reviver, value, property_name, records, depth + 1);
                    if (revived == .undefined)
                        _ = try self.deleteOwnProperty(value, property_name)
                    else
                        try self.defineOwnDataProperty(value, property_name, revived);
                }
            }
        }
        const key_value = Value{ .string = try self.storeString(key) };
        const context = Value{ .cell = try self.allocateCell(.object) };
        try self.pushRoot(context);
        const owner = if (depth == 0) none else if (holder == .cell and holder.cell < self.cells.len) holder.cell else none;
        var record_index = records.len;
        while (record_index > 0) {
            record_index -= 1;
            const record = records[record_index];
            if (record.owner == owner and equals(self.stringBytes(record.key), key) and sameJsonValue(self, record.value, value)) {
                try self.defineOwnDataProperty(context, "source", .{ .string = record.source });
                break;
            }
        }
        return self.call(program, reviver, holder, &.{ key_value, value, context }, false);
    }

    fn nativeJsonStringify(self: *Runtime, program: *const Program, arguments: []const Value) Error!Value {
        const value = if (arguments.len > 0) arguments[0] else Value.undefined;
        const replacer = if (arguments.len > 1) arguments[1] else Value.undefined;
        const space = if (arguments.len > 2) arguments[2] else Value.undefined;
        var stringifier = JsonStringifier{ .runtime = self, .program = program };
        if (self.isCallableValue(replacer)) {
            stringifier.replacer = replacer;
        } else if (self.isCellKind(replacer, .array)) {
            try stringifier.buildPropertyList(replacer.cell);
        }
        try stringifier.setGap(space);
        const holder = Value{ .cell = try self.allocateCell(.object) };
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(holder);
        try self.pushRoot(value);
        try self.defineOwnDataProperty(holder, "", value);
        if (!try stringifier.writeProperty(holder, "", false, 0)) return .undefined;
        return .{ .string = try self.storeString(stringifier.output[0..stringifier.output_len]) };
    }

    fn nativeJsonRaw(self: *Runtime, arguments: []const Value) Error!Value {
        const text = (try self.toString(if (arguments.len > 0) arguments[0] else .undefined)).bytes(self.strings[0..self.string_len]);
        if (text.len == 0 or !jsonRawBoundary(text[0], true) or !jsonRawBoundary(text[text.len - 1], false))
            return error.SyntaxError;
        var parser = JsonParser{ .runtime = self, .source = text };
        const parsed = try parser.parse();
        if (parsed == .cell) return error.SyntaxError;
        const object = Value{ .cell = try self.allocateCell(.object) };
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(object);
        self.cells[object.cell].prototype = none;
        self.cells[object.cell].host_tag = raw_json_tag;
        try self.defineOwnDataProperty(object, "rawJSON", .{ .string = try self.storeString(text) });
        self.cells[object.cell].frozen = true;
        for (self.propertyStorage(object.cell)[0..self.cells[object.cell].property_count]) |*property| {
            property.writable = false;
            property.configurable = false;
        }
        return object;
    }

    fn isRawJson(self: *const Runtime, value: Value) bool {
        return value == .cell and value.cell < self.cells.len and self.cells[value.cell].occupied and
            self.cells[value.cell].kind == .object and self.cells[value.cell].host_tag == raw_json_tag;
    }

    fn nativePromiseConstructor(self: *Runtime, program: *const Program, arguments: []const Value) Error!Value {
        if (arguments.len == 0 or !self.isCallableValue(arguments[0])) return error.TypeError;
        const promise = try self.createPromise();
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(promise);
        const pair = try self.createPromiseResolvingFunctions(promise.cell);
        const resolver = pair[0];
        const rejecter = pair[1];
        _ = self.call(program, arguments[0], .undefined, &.{ resolver, rejecter }, false) catch |err| {
            const rejection = if (err == error.ScriptThrown) self.pending_exception else Value{ .string = try self.storeString(@errorName(err)) };
            _ = try self.nativePromiseSettle(program, self.cells[rejecter.cell].receiver, &.{rejection}, true);
            return promise;
        };
        return promise;
    }

    fn nativePromiseSettle(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value, rejected: bool) Error!Value {
        const value = if (arguments.len > 0) arguments[0] else Value.undefined;
        if (receiver == .cell and receiver.cell < self.cells.len and self.cells[receiver.cell].occupied and
            self.cells[receiver.cell].kind == .object and self.cells[receiver.cell].host_tag == promise_resolution_record_tag)
        {
            const record = &self.cells[receiver.cell];
            if (record.frozen) return .undefined;
            record.frozen = true;
            const target = record.parent;
            if (target == none or target >= self.cells.len or !self.cells[target].occupied or self.cells[target].kind != .promise)
                return .undefined;
            if (rejected)
                try self.settlePromise(target, .rejected, value)
            else
                try self.settlePromise(target, .fulfilled, value);
            return .undefined;
        }
        if (self.isCellKind(receiver, .promise)) {
            if (rejected) try self.rejectPromise(receiver, value) else try self.resolvePromise(receiver, value);
            return receiver;
        }
        if (!self.isConstructor(receiver)) return error.TypeError;
        if (!rejected and self.isCellKind(value, .promise)) {
            const constructor = try self.getProperty(value, "constructor");
            if (self.strictEqual(constructor, receiver)) return value;
        }
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        try self.pushRoot(value);
        const capability = try self.newPromiseCapability(program, receiver);
        try self.pushRoot(capability.promise);
        try self.pushRoot(capability.resolve);
        try self.pushRoot(capability.reject);
        _ = try self.call(program, if (rejected) capability.reject else capability.resolve, .undefined, &.{value}, false);
        return capability.promise;
    }

    fn createPromiseResolvingFunctions(self: *Runtime, promise: u16) Error![2]Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = promise });
        const record = try self.allocateCell(.object);
        self.cells[record].parent = promise;
        self.cells[record].host_tag = promise_resolution_record_tag;
        try self.pushRoot(.{ .cell = record });
        const resolver = try self.createNative(.promise_resolve, .{ .cell = record });
        try self.pushRoot(resolver);
        const rejecter = try self.createNative(.promise_reject, .{ .cell = record });
        return .{ resolver, rejecter };
    }

    fn promiseSpeciesConstructor(self: *Runtime, promise: Value) Error!Value {
        var constructor = try self.getProperty(promise, "constructor");
        if (constructor == .undefined) return self.global("Promise") orelse error.TypeError;
        _ = try self.expectObject(constructor);
        constructor = try self.getProperty(constructor, self.stringBytes(self.symbol_species));
        if (constructor == .undefined or constructor == .null_value)
            return self.global("Promise") orelse error.TypeError;
        if (!self.isConstructor(constructor)) return error.TypeError;
        return constructor;
    }

    fn newPromiseCapability(self: *Runtime, program: *const Program, constructor: Value) Error!PromiseCapability {
        if (!self.isConstructor(constructor)) return error.TypeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(constructor);
        const record = try self.allocateCell(.object);
        self.cells[record].prototype = none;
        self.cells[record].host_tag = promise_capability_record_tag;
        try self.pushRoot(.{ .cell = record });
        const executor = try self.createNative(.promise_capability_executor, .{ .cell = record });
        try self.pushRoot(executor);
        const promise = try self.call(program, constructor, .undefined, &.{executor}, true);
        try self.pushRoot(promise);
        _ = try self.expectCellKind(promise, .promise);
        const resolve = self.cells[record].receiver;
        const reject = self.cells[record].promise_value;
        if (!self.isCallableValue(resolve) or !self.isCallableValue(reject)) return error.TypeError;
        return .{ .promise = promise, .resolve = resolve, .reject = reject };
    }

    fn nativePromiseCapabilityExecutor(self: *Runtime, receiver: Value, arguments: []const Value) Error!Value {
        const record = try self.expectCellKind(receiver, .object);
        if (self.cells[record].host_tag != promise_capability_record_tag or self.cells[record].frozen) return error.TypeError;
        const resolve = if (arguments.len > 0) arguments[0] else Value.undefined;
        const reject = if (arguments.len > 1) arguments[1] else Value.undefined;
        if (!self.isCallableValue(resolve) or !self.isCallableValue(reject)) return error.TypeError;
        self.cells[record].receiver = resolve;
        self.cells[record].promise_value = reject;
        self.cells[record].frozen = true;
        return .undefined;
    }

    fn nativePromiseThen(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        const promise_index = try self.expectCellKind(receiver, .promise);
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        if (arguments.len > 0) try self.pushRoot(arguments[0]);
        if (arguments.len > 1) try self.pushRoot(arguments[1]);
        const constructor = try self.promiseSpeciesConstructor(receiver);
        try self.pushRoot(constructor);
        const capability = try self.newPromiseCapability(program, constructor);
        try self.pushRoot(capability.promise);
        const child = capability.promise.cell;
        const reaction = Reaction{
            .on_fulfilled = if (arguments.len > 0 and self.isCallableValue(arguments[0])) arguments[0] else .undefined,
            .on_rejected = if (arguments.len > 1 and self.isCallableValue(arguments[1])) arguments[1] else .undefined,
            .child = child,
        };
        try self.addPromiseReaction(promise_index, reaction);
        return capability.promise;
    }

    fn nativePromiseCatch(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        return self.nativePromiseThen(program, receiver, &.{ .undefined, if (arguments.len > 0) arguments[0] else .undefined });
    }

    fn nativePromiseFinally(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        _ = try self.expectCellKind(receiver, .promise);
        const callback = if (arguments.len > 0) arguments[0] else Value.undefined;
        if (!self.isCallableValue(callback)) return self.nativePromiseThen(program, receiver, &.{ callback, callback });
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        try self.pushRoot(callback);
        const fulfilled_record = try self.allocateCell(.object);
        self.cells[fulfilled_record].prototype = none;
        self.cells[fulfilled_record].host_tag = promise_finally_record_tag;
        self.cells[fulfilled_record].receiver = callback;
        try self.pushRoot(.{ .cell = fulfilled_record });
        const rejected_record = try self.allocateCell(.object);
        self.cells[rejected_record].prototype = none;
        self.cells[rejected_record].host_tag = promise_finally_record_tag;
        self.cells[rejected_record].receiver = callback;
        self.cells[rejected_record].sealed = true;
        try self.pushRoot(.{ .cell = rejected_record });
        const fulfilled_handler = try self.createNative(.promise_finally_handler, .{ .cell = fulfilled_record });
        try self.pushRoot(fulfilled_handler);
        const rejected_handler = try self.createNative(.promise_finally_handler, .{ .cell = rejected_record });
        return self.nativePromiseThen(program, receiver, &.{ fulfilled_handler, rejected_handler });
    }

    fn nativePromiseFinallyHandler(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        const record = try self.expectCellKind(receiver, .object);
        if (self.cells[record].host_tag != promise_finally_record_tag) return error.TypeError;
        const original = if (arguments.len > 0) arguments[0] else Value.undefined;
        const rejected = self.cells[record].sealed;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(receiver);
        try self.pushRoot(original);
        const cleanup = try self.call(program, self.cells[record].receiver, .undefined, &.{}, false);
        try self.pushRoot(cleanup);
        const cleanup_promise = try self.promiseResolvedValue(cleanup);
        try self.pushRoot(cleanup_promise);
        const continuation_record = try self.allocateCell(.object);
        self.cells[continuation_record].prototype = none;
        self.cells[continuation_record].host_tag = promise_finally_continuation_tag;
        self.cells[continuation_record].receiver = original;
        self.cells[continuation_record].sealed = rejected;
        try self.pushRoot(.{ .cell = continuation_record });
        const continuation = try self.createNative(.promise_finally_continuation, .{ .cell = continuation_record });
        return self.nativePromiseThen(program, cleanup_promise, &.{continuation});
    }

    fn nativePromiseFinallyContinuation(self: *Runtime, receiver: Value) Error!Value {
        const record = try self.expectCellKind(receiver, .object);
        if (self.cells[record].host_tag != promise_finally_continuation_tag) return error.TypeError;
        if (self.cells[record].sealed) {
            self.pending_exception = self.cells[record].receiver;
            return error.ScriptThrown;
        }
        return self.cells[record].receiver;
    }

    fn nativePromiseCombinator(self: *Runtime, program: *const Program, constructor: Value, arguments: []const Value, mode: PromiseCombinatorMode) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(constructor);
        const capability = try self.newPromiseCapability(program, constructor);
        try self.pushRoot(capability.promise);
        const source = if (arguments.len > 0) arguments[0] else Value.undefined;
        try self.pushRoot(source);
        self.fillPromiseCombinator(program, capability.promise.cell, source, constructor, mode) catch |err| {
            const reason = if (err == error.ScriptThrown or err == error.UncaughtException)
                self.pending_exception
            else
                try self.runtimeErrorValue(err);
            try self.settlePromise(capability.promise.cell, .rejected, reason);
        };
        return capability.promise;
    }

    fn fillPromiseCombinator(self: *Runtime, program: *const Program, promise: u16, source: Value, constructor: Value, mode: PromiseCombinatorMode) Error!void {
        const resolve_method = try self.getProperty(constructor, "resolve");
        if (!self.isCallableValue(resolve_method)) return error.TypeError;
        var cursor = try self.openIterator(program, source);
        errdefer self.iteratorClose(program, &cursor) catch {};
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.rootIterator(cursor);
        try self.pushRoot(.{ .cell = promise });
        try self.pushRoot(constructor);
        try self.pushRoot(resolve_method);

        const aggregate = try self.allocateCell(.object);
        self.cells[aggregate].prototype = none;
        self.cells[aggregate].host_tag = promise_aggregate_tag;
        self.cells[aggregate].parent = promise;
        self.cells[aggregate].node = @intFromEnum(mode);
        self.cells[aggregate].reaction_count = 1;
        try self.pushRoot(.{ .cell = aggregate });
        const results: Value = .{ .cell = try self.allocateCell(.array) };
        self.cells[aggregate].private_storage = results.cell;
        try self.pushRoot(results);

        var index: usize = 0;
        while (true) {
            const step = try self.iteratorNext(program, &cursor);
            if (step.done) break;
            if (index >= none) return error.ItemLimit;
            const iteration_roots = self.root_count;
            defer self.root_count = iteration_roots;
            try self.pushRoot(step.value);
            if (mode != .race) {
                try self.ensureItemCapacity(results.cell, index + 1);
                self.itemStorage(results.cell)[index] = .undefined;
                self.setArrayItemPresent(results.cell, index, true);
                self.cells[results.cell].item_count = index + 1;
                self.cells[results.cell].array_length = index + 1;
            }
            const resolved = try self.call(program, resolve_method, constructor, &.{step.value}, false);
            try self.pushRoot(resolved);
            _ = try self.expectCellKind(resolved, .promise);
            const fulfilled = try self.createPromiseCombinatorHandler(aggregate, index, false);
            try self.pushRoot(fulfilled);
            const rejected = try self.createPromiseCombinatorHandler(aggregate, index, true);
            try self.pushRoot(rejected);
            const reaction_child = try self.createPromise();
            try self.pushRoot(reaction_child);
            self.cells[aggregate].reaction_count += 1;
            try self.addPromiseReaction(resolved.cell, .{
                .on_fulfilled = fulfilled,
                .on_rejected = rejected,
                .child = reaction_child.cell,
            });
            index += 1;
        }
        self.cells[aggregate].reaction_count -= 1;
        if (self.cells[aggregate].reaction_count != 0) return;
        switch (mode) {
            .all, .all_settled => try self.settlePromise(promise, .fulfilled, results),
            .any => try self.rejectPromiseAggregate(program, promise, results),
            .race => {},
        }
    }

    fn createPromiseCombinatorHandler(self: *Runtime, aggregate: u16, index: usize, rejected: bool) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = aggregate });
        const record = try self.allocateCell(.object);
        self.cells[record].prototype = none;
        self.cells[record].host_tag = promise_combinator_element_tag;
        self.cells[record].parent = aggregate;
        self.cells[record].node = @intCast(index);
        self.cells[record].sealed = rejected;
        try self.pushRoot(.{ .cell = record });
        return self.createNative(.promise_combinator_element, .{ .cell = record });
    }

    fn nativePromiseCombinatorElement(self: *Runtime, program: *const Program, receiver: Value, arguments: []const Value) Error!Value {
        const record = try self.expectCellKind(receiver, .object);
        if (self.cells[record].host_tag != promise_combinator_element_tag or self.cells[record].frozen) return .undefined;
        self.cells[record].frozen = true;
        const aggregate = self.cells[record].parent;
        if (aggregate == none or aggregate >= self.cells.len or !self.cells[aggregate].occupied or
            self.cells[aggregate].host_tag != promise_aggregate_tag or self.cells[aggregate].frozen)
            return .undefined;
        const promise = self.cells[aggregate].parent;
        const results = self.cells[aggregate].private_storage;
        if (promise == none or results == none) return error.TypeError;
        const mode: PromiseCombinatorMode = @enumFromInt(self.cells[aggregate].node);
        const rejected = self.cells[record].sealed;
        const value = if (arguments.len > 0) arguments[0] else Value.undefined;
        const index: usize = self.cells[record].node;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = aggregate });
        try self.pushRoot(value);

        if (mode == .race or (mode == .all and rejected) or (mode == .any and !rejected)) {
            self.cells[aggregate].frozen = true;
            try self.settlePromise(promise, if (rejected) .rejected else .fulfilled, value);
            return .undefined;
        }

        const stored = if (mode == .all_settled) blk: {
            const result: Value = .{ .cell = try self.allocateCell(.object) };
            try self.pushRoot(result);
            try self.defineOwnDataProperty(result, "status", .{ .string = try self.storeString(if (rejected) "rejected" else "fulfilled") });
            try self.defineOwnDataProperty(result, if (rejected) "reason" else "value", value);
            break :blk result;
        } else value;
        self.itemStorage(results)[index] = stored;
        if (self.cells[aggregate].reaction_count == 0) return error.TypeError;
        self.cells[aggregate].reaction_count -= 1;
        if (self.cells[aggregate].reaction_count != 0) return .undefined;
        self.cells[aggregate].frozen = true;
        if (mode == .any)
            try self.rejectPromiseAggregate(program, promise, .{ .cell = results })
        else
            try self.settlePromise(promise, .fulfilled, .{ .cell = results });
        return .undefined;
    }

    fn rejectPromiseAggregate(self: *Runtime, program: *const Program, promise: u16, errors: Value) Error!void {
        const constructor = self.global("AggregateError") orelse return error.TypeError;
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = promise });
        try self.pushRoot(errors);
        try self.pushRoot(constructor);
        const message: Value = .{ .string = try self.storeString("All promises were rejected") };
        try self.pushRoot(message);
        const reason = try self.call(program, constructor, .undefined, &.{ errors, message }, true);
        try self.settlePromise(promise, .rejected, reason);
    }

    fn nativePromiseTry(self: *Runtime, program: *const Program, constructor: Value, arguments: []const Value) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(constructor);
        const capability = try self.newPromiseCapability(program, constructor);
        try self.pushRoot(capability.promise);
        const callback = if (arguments.len > 0) arguments[0] else Value.undefined;
        const result = self.call(program, callback, .undefined, if (arguments.len > 1) arguments[1..] else &.{}, false) catch |err| {
            const reason = if (err == error.ScriptThrown or err == error.UncaughtException)
                self.pending_exception
            else
                try self.runtimeErrorValue(err);
            try self.settlePromise(capability.promise.cell, .rejected, reason);
            return capability.promise;
        };
        try self.pushRoot(result);
        try self.settlePromise(capability.promise.cell, .fulfilled, result);
        return capability.promise;
    }

    fn nativePromiseWithResolvers(self: *Runtime, program: *const Program, constructor: Value) Error!Value {
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(constructor);
        const capability = try self.newPromiseCapability(program, constructor);
        try self.pushRoot(capability.promise);
        try self.pushRoot(capability.resolve);
        try self.pushRoot(capability.reject);
        const result: Value = .{ .cell = try self.allocateCell(.object) };
        try self.pushRoot(result);
        try self.defineOwnDataProperty(result, "promise", capability.promise);
        try self.defineOwnDataProperty(result, "resolve", capability.resolve);
        try self.defineOwnDataProperty(result, "reject", capability.reject);
        return result;
    }

    fn addPromiseReaction(self: *Runtime, promise: u16, reaction: Reaction) Error!void {
        if (promise == none or promise >= self.cells.len or !self.cells[promise].occupied or self.cells[promise].kind != .promise)
            return error.TypeError;
        self.markPromiseHandled(promise);
        if (self.cells[promise].promise_state != .pending) return self.scheduleReaction(promise, reaction);

        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(.{ .cell = promise });
        try self.pushRoot(reaction.on_fulfilled);
        try self.pushRoot(reaction.on_rejected);
        if (reaction.child != none) try self.pushRoot(.{ .cell = reaction.child });
        if (reaction.async_owner != none) try self.pushRoot(.{ .cell = reaction.async_owner });
        if (reaction.async_generator != none) try self.pushRoot(.{ .cell = reaction.async_generator });

        const reaction_cell = try self.allocateCell(.object);
        self.cells[reaction_cell].prototype = none;
        self.cells[reaction_cell].host_tag = promise_reaction_tag;
        self.cells[reaction_cell].item_count = promise_reaction_item_count;
        const items = self.itemStorage(reaction_cell);
        items[0] = reaction.on_fulfilled;
        items[1] = reaction.on_rejected;
        items[2] = if (reaction.child == none) .undefined else .{ .cell = reaction.child };
        items[3] = if (reaction.async_owner == none) .undefined else .{ .cell = reaction.async_owner };
        items[4] = if (reaction.async_generator == none) .undefined else .{ .cell = reaction.async_generator };

        const tail = self.cells[promise].node;
        if (tail == none) {
            self.cells[promise].private_storage = reaction_cell;
        } else {
            self.cells[tail].parent = reaction_cell;
        }
        self.cells[promise].node = reaction_cell;
        self.cells[promise].reaction_count += 1;
    }

    fn markPromiseHandled(self: *Runtime, promise: u16) void {
        if (self.cells[promise].promise_handled) return;
        self.cells[promise].promise_handled = true;
        if (self.cells[promise].promise_rejection_reported) {
            if (self.promise_rejection_tracker.track) |track|
                track(self, self.promise_rejection_tracker.context, .{ .cell = promise }, self.cells[promise].promise_value, true);
        }
    }

    fn promiseReaction(self: *const Runtime, reaction_cell: u16) Reaction {
        const items = self.itemStorageConst(reaction_cell);
        return .{
            .on_fulfilled = items[0],
            .on_rejected = items[1],
            .child = valueCellOrNone(items[2]),
            .async_owner = valueCellOrNone(items[3]),
            .async_generator = valueCellOrNone(items[4]),
        };
    }

    fn settlePromise(self: *Runtime, index: u16, state: PromiseState, value: Value) Error!void {
        if (self.cells[index].promise_state != .pending) return;
        if (state == .fulfilled and self.isCellKind(value, .promise)) {
            const source = value.cell;
            if (source == index) {
                const reason = try self.storeString("Promise self-resolution");
                return self.settlePromise(index, .rejected, .{ .string = reason });
            }
            if (self.cells[source].promise_state == .pending) {
                try self.addPromiseReaction(source, .{ .child = index });
                return;
            }
            return self.settlePromise(index, self.cells[source].promise_state, self.cells[source].promise_value);
        }
        if (state == .fulfilled and value == .cell) {
            if (self.cells[index].promise_value == .cell and self.cells[index].promise_value.cell == value.cell) {
                const reason = try self.runtimeErrorValue(error.TypeError);
                return self.settlePromise(index, .rejected, reason);
            }
            const root_base = self.root_count;
            defer self.root_count = root_base;
            try self.pushRoot(.{ .cell = index });
            try self.pushRoot(value);
            const then_method = self.getProperty(value, "then") catch |err| {
                const reason = if (err == error.ScriptThrown) self.pending_exception else try self.runtimeErrorValue(err);
                return self.settlePromise(index, .rejected, reason);
            };
            if (self.isCallableValue(then_method)) {
                self.cells[index].promise_value = value;
                try self.pushRoot(then_method);
                try self.enqueueJob(&self.microtasks, &self.microtask_head, &self.microtask_count, .{
                    .kind = .promise_resolve_thenable,
                    .callback = then_method,
                    .argument = value,
                    .promise = index,
                });
                return;
            }
        }
        self.cells[index].promise_state = state;
        self.cells[index].promise_value = value;
        if (state == .rejected and !self.cells[index].promise_handled) {
            self.cells[index].promise_rejection_reported = true;
            if (self.promise_rejection_tracker.track) |track|
                track(self, self.promise_rejection_tracker.context, .{ .cell = index }, value, false);
        }
        var reaction_cell = self.cells[index].private_storage;
        while (reaction_cell != none) {
            const next = self.cells[reaction_cell].parent;
            try self.scheduleReaction(index, self.promiseReaction(reaction_cell));
            reaction_cell = next;
        }
        self.cells[index].private_storage = none;
        self.cells[index].node = none;
        self.cells[index].reaction_count = 0;
    }

    fn scheduleReaction(self: *Runtime, promise: u16, reaction: Reaction) Error!void {
        if (reaction.async_generator != none) {
            try self.enqueueJob(&self.microtasks, &self.microtask_head, &self.microtask_count, .{
                .kind = .async_generator_await,
                .generator = reaction.async_generator,
                .argument = self.cells[promise].promise_value,
                .rejected = self.cells[promise].promise_state == .rejected,
            });
            return;
        }
        if (reaction.async_owner != none) {
            try self.enqueueJob(&self.microtasks, &self.microtask_head, &self.microtask_count, .{
                .kind = .async_resume,
                .promise = reaction.async_owner,
                .argument = self.cells[promise].promise_value,
                .rejected = self.cells[promise].promise_state == .rejected,
            });
            return;
        }
        try self.enqueueJob(&self.microtasks, &self.microtask_head, &self.microtask_count, .{
            .kind = .promise_reaction,
            .promise = promise,
            .callback = if (self.cells[promise].promise_state == .rejected) reaction.on_rejected else reaction.on_fulfilled,
            .argument = self.cells[promise].promise_value,
            .rejected = self.cells[promise].promise_state == .rejected,
        });
        const slot = (self.microtask_head + self.microtask_count - 1) % self.microtasks.len;
        self.microtasks[slot].promise = reaction.child;
    }

    fn runJob(self: *Runtime, program: *const Program, job: Job) Error!void {
        const job_program = job.program orelse program;
        const previous_program = self.active_program;
        const previous_module = self.active_module;
        const previous_exports = self.active_exports;
        self.active_program = job_program;
        self.active_module = job.module;
        self.active_exports = if (job.module != none and job.module < self.module_count)
            self.modules[job.module].exports
        else
            none;
        defer {
            self.active_program = previous_program;
            self.active_module = previous_module;
            self.active_exports = previous_exports;
        }
        defer if (self.stats.allocations >= self.next_gc_allocation) self.collectGarbage();
        if (job.kind == .promise_resolve_thenable) {
            if (job.promise == none or job.promise >= self.cells.len or !self.cells[job.promise].occupied or
                self.cells[job.promise].kind != .promise or self.cells[job.promise].promise_state != .pending)
                return;
            if (self.promise_resolution_depth >= max_call_depth) {
                const reason = try self.runtimeErrorValue(error.TypeError);
                try self.settlePromise(job.promise, .rejected, reason);
                return;
            }
            const root_base = self.root_count;
            defer self.root_count = root_base;
            try self.pushRoot(.{ .cell = job.promise });
            try self.pushRoot(job.callback);
            try self.pushRoot(job.argument);
            const pair = try self.createPromiseResolvingFunctions(job.promise);
            try self.pushRoot(pair[0]);
            try self.pushRoot(pair[1]);
            self.promise_resolution_depth += 1;
            defer self.promise_resolution_depth -= 1;
            const then_program = if (job.callback == .cell and self.cells[job.callback.cell].program_ref != null)
                self.cells[job.callback.cell].program_ref.?
            else
                job_program;
            _ = self.call(then_program, job.callback, job.argument, &.{ pair[0], pair[1] }, false) catch |err| {
                const reason = if (err == error.ScriptThrown) self.pending_exception else try self.runtimeErrorValue(err);
                _ = try self.nativePromiseSettle(job_program, self.cells[pair[1].cell].receiver, &.{reason}, true);
                return;
            };
            return;
        }
        if (job.kind == .dynamic_import) {
            const module_name = if (job.argument == .string) self.stringBytes(job.argument.string) else "";
            const namespace = self.evaluateModuleFrom(job.generator, module_name) catch |err| {
                const rejection = if (err == error.ScriptThrown or err == error.UncaughtException)
                    self.pending_exception
                else
                    try self.runtimeErrorValue(err);
                try self.settlePromise(job.promise, .rejected, rejection);
                return;
            };
            try self.settlePromise(job.promise, .fulfilled, namespace);
            return;
        }
        if (job.kind == .async_generator_request) {
            try self.processAsyncGeneratorRequests(job.generator);
            return;
        }
        if (job.kind == .async_generator_await) {
            try self.resumeAsyncGeneratorAwait(job.generator, job.rejected, job.argument);
            return;
        }
        if (job.kind == .async_resume) {
            try self.resumeAsyncState(job.promise, job.rejected, job.argument);
            return;
        }
        if (job.kind == .promise_reaction) {
            // drainJobs has already removed this job from the queue. Keep its
            // child promise, callback and settlement value alive when the
            // reaction itself allocates enough to trigger a collection.
            const root_base = self.root_count;
            defer self.root_count = root_base;
            try self.pushRoot(.{ .cell = job.promise });
            try self.pushRoot(job.callback);
            try self.pushRoot(job.argument);
            if (job.callback == .undefined) {
                if (job.rejected) try self.settlePromise(job.promise, .rejected, job.argument) else try self.settlePromise(job.promise, .fulfilled, job.argument);
                return;
            }
            const result = self.call(job_program, job.callback, .undefined, &.{job.argument}, false) catch |err| {
                const rejection = if (err == error.ScriptThrown) self.pending_exception else Value{ .string = try self.storeString(@errorName(err)) };
                try self.settlePromise(job.promise, .rejected, rejection);
                return;
            };
            try self.settlePromise(job.promise, .fulfilled, result);
            return;
        }
        _ = try self.call(job_program, job.callback, .undefined, &.{job.argument}, false);
    }

    fn installIntrinsics(self: *Runtime) Error!void {
        try self.defineGlobal("undefined", .undefined, true);
        try self.defineGlobal("NaN", .{ .number = std.math.nan(f64) }, true);
        try self.defineGlobal("Infinity", .{ .number = std.math.inf(f64) }, true);
        const object = try self.createNative(.object_constructor, .undefined);
        try self.setProperty(object, "assign", try self.createNative(.object_assign, .undefined));
        try self.setProperty(object, "keys", try self.createNative(.object_keys, .undefined));
        try self.setProperty(object, "entries", try self.createNative(.object_entries, .undefined));
        try self.setProperty(object, "values", try self.createNative(.object_values, .undefined));
        try self.setProperty(object, "fromEntries", try self.createNative(.object_from_entries, .undefined));
        try self.setProperty(object, "groupBy", try self.createNative(.object_group_by, .undefined));
        try self.setProperty(object, "hasOwn", try self.createNative(.object_has_own_static, .undefined));
        try self.setProperty(object, "create", try self.createNative(.object_create, .undefined));
