                    cell.property_count = 0;
                    cell.binding_count = 0;
                    cell.item_count = 0;
                    cell.array_length = 0;
                    cell.array_length_writable = true;
                    cell.inline_item_presence = 0;
                    cell.binding_memory = null;
                    cell.binding_capacity = 0;
                    cell.item_memory = null;
                    cell.item_capacity = 0;
                    cell.item_presence_memory = null;
                    cell.item_presence_capacity = 0;
                    cell.property_memory = null;
                    cell.property_capacity = 0;
                    cell.reaction_count = 0;
                    cell.promise_handled = false;
                    cell.promise_rejection_reported = false;
                    cell.promise_state = .pending;
                    cell.promise_value = .undefined;
                    cell.storage = switch (kind) {
                        .environment => .{ .bindings = undefined },
                        .array, .bound_function => .{ .items = undefined },
                        .promise => .{ .items = undefined },
                        else => .{ .items = undefined },
                    };
                    self.stats.allocations += 1;
                    self.stats.live_cells += 1;
                    self.stats.peak_cells = @max(self.stats.peak_cells, self.stats.live_cells);
                    self.next_cell_hint = (index + 1) % self.cells.len;
                    return @intCast(index);
                }
            }
            if (retried_after_collection) return error.CellLimit;
            self.collectGarbage();
            retried_after_collection = true;
        }
    }

    fn bigIntStorageBytes(capacity: usize) usize {
        return @offsetOf(BigIntStorage, "first_limb") + @max(@as(usize, 1), capacity) * @sizeOf(BigIntLimb);
    }

    fn bigIntStorage(self: *const Runtime, index: u16) Error!*BigIntStorage {
        if (index >= self.cells.len or !self.cells[index].occupied or self.cells[index].host_tag != bigint_primitive_tag)
            return error.TypeError;
        return @ptrCast(@alignCast(self.cells[index].host_context orelse return error.TypeError));
    }

    fn bigIntStorageLimbs(storage: *BigIntStorage) []BigIntLimb {
        const pointer: [*]BigIntLimb = @ptrCast(&storage.first_limb);
        return pointer[0..storage.capacity];
    }

    fn bigIntConst(self: *const Runtime, value: Value) Error!BigIntCore.Const {
        const index = switch (value) {
            .bigint => |bigint| bigint,
            else => return error.TypeError,
        };
        const storage = try self.bigIntStorage(index);
        return .{
            .limbs = bigIntStorageLimbs(storage)[0..storage.limb_count],
            .positive = storage.positive,
        };
    }

    fn createBigIntFromConst(self: *Runtime, source: BigIntCore.Const) Error!Value {
        if (source.limbs.len > max_bigint_limbs) {
            self.diagnostic_limit_required = source.limbs.len;
            self.diagnostic_limit_available = max_bigint_limbs;
            return error.RangeError;
        }
        const capacity = @max(@as(usize, 1), source.limbs.len);
        const index = try self.allocateCell(.object);
        errdefer self.cells[index].occupied = false;
        const byte_count = bigIntStorageBytes(capacity);
        const memory = self.program_allocator.allocate(
            self.program_allocator.context,
            byte_count,
            @alignOf(BigIntStorage),
        ) orelse return error.ProgramAllocation;
        const storage: *BigIntStorage = @ptrCast(@alignCast(memory));
        storage.* = .{
            .limb_count = capacity,
            .capacity = capacity,
            .positive = source.positive or source.eqlZero(),
            .first_limb = 0,
        };
        const limbs = bigIntStorageLimbs(storage);
        @memcpy(limbs[0..source.limbs.len], source.limbs);
        var normalized = BigIntCore.Mutable{
            .limbs = limbs,
            .len = source.limbs.len,
            .positive = storage.positive,
        };
        normalized.normalize(source.limbs.len);
        storage.limb_count = normalized.len;
        storage.positive = normalized.positive or normalized.eqlZero();
        self.cells[index].prototype = none;
        self.cells[index].extensible = false;
        self.cells[index].host_tag = bigint_primitive_tag;
        self.cells[index].host_context = storage;
        return .{ .bigint = index };
    }

    fn releaseBigIntCell(self: *Runtime, cell: *Cell) void {
        const storage: *BigIntStorage = @ptrCast(@alignCast(cell.host_context orelse return));
        self.program_allocator.free(
            self.program_allocator.context,
            @ptrCast(storage),
            bigIntStorageBytes(storage.capacity),
            @alignOf(BigIntStorage),
        );
        cell.host_context = null;
    }

    fn releaseBigIntCells(self: *Runtime) void {
        for (&self.cells) |*cell| {
            if (!cell.occupied or cell.host_tag != bigint_primitive_tag) continue;
            self.releaseBigIntCell(cell);
            cell.occupied = false;
        }
    }

    fn arrayBufferStorageBytes(length: usize) usize {
        return @offsetOf(ArrayBufferStorage, "first_byte") + @max(@as(usize, 1), length);
    }

    fn arrayBufferBytes(storage: *ArrayBufferStorage) []u8 {
        const pointer: [*]u8 = @ptrCast(&storage.first_byte);
        return pointer[0..storage.allocation_length];
    }

    fn arrayBufferStorage(self: *const Runtime, value: Value) Error!*ArrayBufferStorage {
        const index = try self.arrayBufferIndex(value);
        return @ptrCast(@alignCast(self.cells[index].host_context orelse return error.TypeError));
    }

    fn bufferStorage(self: *const Runtime, value: Value) Error!*ArrayBufferStorage {
        const index = try self.bufferIndex(value);
        return @ptrCast(@alignCast(self.cells[index].host_context orelse return error.TypeError));
    }

    fn arrayBufferIndex(self: *const Runtime, value: Value) Error!u16 {
        const index = switch (value) {
            .cell => |cell| cell,
            else => return error.TypeError,
        };
        if (index >= self.cells.len or !self.cells[index].occupied or self.cells[index].host_tag != array_buffer_tag)
            return error.TypeError;
        return index;
    }

    fn sharedArrayBufferIndex(self: *const Runtime, value: Value) Error!u16 {
        const index = switch (value) {
            .cell => |cell| cell,
            else => return error.TypeError,
        };
        if (index >= self.cells.len or !self.cells[index].occupied or self.cells[index].host_tag != shared_array_buffer_tag)
            return error.TypeError;
        return index;
    }

    fn bufferIndex(self: *const Runtime, value: Value) Error!u16 {
        const index = switch (value) {
            .cell => |cell| cell,
            else => return error.TypeError,
        };
        if (index >= self.cells.len or !self.cells[index].occupied or
            (self.cells[index].host_tag != array_buffer_tag and self.cells[index].host_tag != shared_array_buffer_tag))
            return error.TypeError;
        return index;
    }

    fn isArrayBuffer(self: *const Runtime, value: Value) bool {
        return value == .cell and value.cell < self.cells.len and self.cells[value.cell].occupied and
            self.cells[value.cell].host_tag == array_buffer_tag;
    }

    fn isSharedArrayBuffer(self: *const Runtime, value: Value) bool {
        return value == .cell and value.cell < self.cells.len and self.cells[value.cell].occupied and
            self.cells[value.cell].host_tag == shared_array_buffer_tag;
    }

    fn isBufferObject(self: *const Runtime, value: Value) bool {
        return self.isArrayBuffer(value) or self.isSharedArrayBuffer(value);
    }

    fn createArrayBuffer(self: *Runtime, length: usize, max_length: usize, immutable: bool) Error!Value {
        return self.createBufferStorage(length, max_length, immutable, false);
    }

    fn createSharedArrayBuffer(self: *Runtime, length: usize, max_length: usize) Error!Value {
        return self.createBufferStorage(length, max_length, false, true);
    }

    fn createBufferStorage(self: *Runtime, length: usize, max_length: usize, immutable: bool, shared: bool) Error!Value {
        if (length > max_length or max_length > max_array_buffer_bytes) {
            self.diagnostic_limit_required = @max(length, max_length);
            self.diagnostic_limit_available = max_array_buffer_bytes;
            return error.RangeError;
        }
        const index = try self.allocateCell(.object);
        errdefer self.cells[index].occupied = false;
        const byte_count = arrayBufferStorageBytes(length);
        const memory = self.program_allocator.allocate(
            self.program_allocator.context,
            byte_count,
            @alignOf(ArrayBufferStorage),
        ) orelse return error.ProgramAllocation;
        const storage: *ArrayBufferStorage = @ptrCast(@alignCast(memory));
        storage.* = .{
            .byte_length = length,
            .max_byte_length = max_length,
            .allocation_length = length,
            .resizable = !immutable and max_length != length,
            .immutable = immutable,
            .first_byte = 0,
        };
        @memset(arrayBufferBytes(storage), 0);
        self.cells[index].host_tag = if (shared) shared_array_buffer_tag else array_buffer_tag;
        self.cells[index].host_context = storage;
        self.cells[index].prototype = if (shared) self.shared_array_buffer_prototype else self.array_buffer_prototype;
        return .{ .cell = index };
    }

    fn replaceArrayBufferStorage(self: *Runtime, cell: u16, new_length: usize) Error!void {
        const old = try self.bufferStorage(.{ .cell = cell });
        const byte_count = arrayBufferStorageBytes(new_length);
        const memory = self.program_allocator.allocate(
            self.program_allocator.context,
            byte_count,
            @alignOf(ArrayBufferStorage),
        ) orelse return error.ProgramAllocation;
        const replacement: *ArrayBufferStorage = @ptrCast(@alignCast(memory));
        replacement.* = .{
            .byte_length = new_length,
            .max_byte_length = old.max_byte_length,
            .allocation_length = new_length,
            .resizable = old.resizable,
            .immutable = old.immutable,
            .first_byte = 0,
        };
        const replacement_bytes = arrayBufferBytes(replacement);
        @memset(replacement_bytes, 0);
        const copy_length = @min(old.byte_length, new_length);
        if (copy_length > 0) @memcpy(replacement_bytes[0..copy_length], arrayBufferBytes(old)[0..copy_length]);
        self.program_allocator.free(
            self.program_allocator.context,
            @ptrCast(old),
            arrayBufferStorageBytes(old.allocation_length),
            @alignOf(ArrayBufferStorage),
        );
        self.cells[cell].host_context = replacement;
    }

    fn detachArrayBuffer(self: *Runtime, cell: u16) void {
        if (cell >= self.cells.len or self.cells[cell].host_tag != array_buffer_tag) return;
        const storage: *ArrayBufferStorage = @ptrCast(@alignCast(self.cells[cell].host_context orelse return));
        self.program_allocator.free(
            self.program_allocator.context,
            @ptrCast(storage),
            arrayBufferStorageBytes(storage.allocation_length),
            @alignOf(ArrayBufferStorage),
        );
        self.cells[cell].host_context = null;
    }

    fn releaseArrayBufferCell(self: *Runtime, cell: *Cell) void {
        const storage: *ArrayBufferStorage = @ptrCast(@alignCast(cell.host_context orelse return));
        self.program_allocator.free(
            self.program_allocator.context,
            @ptrCast(storage),
            arrayBufferStorageBytes(storage.allocation_length),
            @alignOf(ArrayBufferStorage),
        );
        cell.host_context = null;
    }

    fn releaseArrayBufferCells(self: *Runtime) void {
        for (&self.cells) |*cell| {
            if (!cell.occupied or (cell.host_tag != array_buffer_tag and cell.host_tag != shared_array_buffer_tag)) continue;
            self.releaseArrayBufferCell(cell);
            cell.occupied = false;
        }
    }

    fn createBigIntFromLiteral(self: *Runtime, literal: []const u8) Error!Value {
        if (!bigIntLiteralValid(literal)) return error.SyntaxError;
        const body = literal[0 .. literal.len - 1];
        var radix: u8 = 10;
        var digits = body;
        if (body.len >= 2 and body[0] == '0') {
            radix = switch (body[1]) {
                'x', 'X' => 16,
                'b', 'B' => 2,
                'o', 'O' => 8,
                else => 10,
            };
            if (radix != 10) digits = body[2..];
        }
        return self.createBigIntFromDigits(digits, radix, false, true);
    }

    fn createBigIntFromDigits(self: *Runtime, digits: []const u8, radix: u8, negative: bool, separators: bool) Error!Value {
        if (digits.len == 0) return error.SyntaxError;
        var digit_count: usize = 0;
        for (digits, 0..) |byte, index| {
            if (byte == '_') {
                if (!separators or index == 0 or index + 1 == digits.len) return error.SyntaxError;
                continue;
            }
            const digit = numberDigitValue(byte) orelse return error.SyntaxError;
            if (digit >= radix) return error.SyntaxError;
            digit_count += 1;
        }
        if (digit_count == 0) return error.SyntaxError;
        const required = BigIntCore.calcSetStringLimbCount(radix, digit_count);
        if (required > self.bigint_work_scratch.len) {
            self.diagnostic_limit_required = required;
            self.diagnostic_limit_available = max_bigint_limbs;
            return error.RangeError;
        }
        var mutable = BigIntCore.Mutable.init(self.bigint_work_scratch[0..@max(@as(usize, 1), required)], 0);
        mutable.setString(radix, digits) catch return error.SyntaxError;
        mutable.positive = !negative or mutable.eqlZero();
        if (mutable.len > max_bigint_limbs) return error.RangeError;
        return self.createBigIntFromConst(mutable.toConst());
    }

    fn createBigIntFromString(self: *Runtime, raw: []const u8) Error!Value {
        const text = trimNumberWhitespace(raw);
        if (text.len == 0) return self.createBigIntFromScalar(0);
        var negative = false;
        var digits = text;
        var radix: u8 = 10;
        if (digits[0] == '+' or digits[0] == '-') {
            negative = digits[0] == '-';
            digits = digits[1..];
            if (digits.len == 0) return error.SyntaxError;
        }
        if (digits.len >= 2 and digits[0] == '0') {
            const prefixed_radix: ?u8 = switch (digits[1]) {
                'x', 'X' => 16,
                'b', 'B' => 2,
                'o', 'O' => 8,
                else => null,
            };
            if (prefixed_radix) |base| {
                if (negative or text[0] == '+') return error.SyntaxError;
                radix = base;
                digits = digits[2..];
            }
        }
        return self.createBigIntFromDigits(digits, radix, negative, false);
    }

    fn createBigIntFromScalar(self: *Runtime, value: i64) Error!Value {
        var mutable = BigIntCore.Mutable.init(self.bigint_result_scratch[0..2], value);
        return self.createBigIntFromConst(mutable.toConst());
    }

    fn numberAsBigIntConst(self: *Runtime, number: f64) Error!BigIntCore.Const {
        if (!std.math.isFinite(number) or @trunc(number) != number) return error.RangeError;
        if (number == 0) {
            var zero = BigIntCore.Mutable.init(self.bigint_result_scratch[0..1], 0);
            return zero.toConst();
        }
        const bits: u64 = @bitCast(@abs(number));
        const exponent_bits: u16 = @intCast((bits >> 52) & 0x7ff);
        const fraction = bits & ((@as(u64, 1) << 52) - 1);
        const mantissa = if (exponent_bits == 0) fraction else fraction | (@as(u64, 1) << 52);
        const exponent: i32 = @as(i32, exponent_bits) - 1023 - 52;
        var source = BigIntCore.Mutable.init(self.bigint_remainder_scratch[0..2], mantissa);
        var result = BigIntCore.Mutable.init(self.bigint_result_scratch[0..], 0);
        if (exponent >= 0) {
            const shift: usize = @intCast(exponent);
            const required = source.len + shift / @bitSizeOf(BigIntLimb) + 1;
            if (required > max_bigint_limbs) return error.RangeError;
            result.limbs = self.bigint_result_scratch[0..required];
            result.shiftLeft(source.toConst(), shift);
        } else {
            const shift: usize = @intCast(-exponent);
            result.limbs = self.bigint_result_scratch[0..source.len];
            result.shiftRight(source.toConst(), shift);
        }
        result.positive = number >= 0 or result.eqlZero();
        return result.toConst();
    }

    fn createBigIntFromNumber(self: *Runtime, number: f64) Error!Value {
        return self.createBigIntFromConst(try self.numberAsBigIntConst(number));
    }

    fn toBigInt(self: *Runtime, value: Value, allow_number: bool) Error!Value {
        const primitive = if (value == .cell) try self.toPrimitive(value, .number) else value;
        return switch (primitive) {
            .bigint => primitive,
            .boolean => |boolean| self.createBigIntFromScalar(if (boolean) 1 else 0),
            .number => |number| if (allow_number) self.createBigIntFromNumber(number) else error.TypeError,
            .string => |ref| if (self.isSymbolValue(primitive)) error.TypeError else self.createBigIntFromString(self.stringBytes(ref)),
            else => error.TypeError,
        };
    }

    fn storeBigIntMutable(self: *Runtime, mutable: BigIntCore.Mutable) Error!Value {
        return self.createBigIntFromConst(mutable.toConst());
    }

    fn bigIntBinary(self: *Runtime, operation: BinaryOp, left: Value, right: Value) Error!Value {
        const a = try self.bigIntConst(left);
        const b = try self.bigIntConst(right);
        switch (operation) {
            .add => {
                const required = @max(a.limbs.len, b.limbs.len) + 1;
                var temporary = BigIntCore.Mutable.init(self.bigint_work_scratch[0..required], 0);
                temporary.add(a, b);
                if (temporary.len > max_bigint_limbs) return error.RangeError;
                return self.storeBigIntMutable(temporary);
            },
            .subtract => {
                const required = @max(a.limbs.len, b.limbs.len) + 1;
                var temporary = BigIntCore.Mutable.init(self.bigint_work_scratch[0..required], 0);
                temporary.sub(a, b);
                if (temporary.len > max_bigint_limbs) return error.RangeError;
                return self.storeBigIntMutable(temporary);
            },
            .multiply => {
                const required = a.limbs.len + b.limbs.len;
                if (required > self.bigint_work_scratch.len) return error.RangeError;
                var temporary = BigIntCore.Mutable.init(self.bigint_work_scratch[0..required], 0);
                temporary.mulNoAlias(a, b, null);
                if (temporary.len > max_bigint_limbs) return error.RangeError;
                return self.storeBigIntMutable(temporary);
            },
            .divide, .remainder => {
                if (b.eqlZero()) return error.RangeError;
                const work_count = BigIntCore.calcDivLimbsBufferLen(a.limbs.len, b.limbs.len);
                if (work_count > self.bigint_work_scratch.len) return error.RangeError;
                var quotient = BigIntCore.Mutable.init(self.bigint_result_scratch[0..@max(@as(usize, 1), a.limbs.len)], 0);
                var remainder = BigIntCore.Mutable.init(self.bigint_remainder_scratch[0..@max(@as(usize, 1), b.limbs.len)], 0);
                quotient.divTrunc(&remainder, a, b, self.bigint_work_scratch[0..work_count]);
                return self.storeBigIntMutable(if (operation == .divide) quotient else remainder);
            },
            .exponentiate => {
                if (!b.positive and !b.eqlZero()) return error.RangeError;
                if (b.eqlZero()) return self.createBigIntFromScalar(1);
                if (a.eqlZero()) return self.createBigIntFromScalar(0);
                if (a.orderAbs(.{ .limbs = &.{1}, .positive = true }) == .eq) {
                    const odd = b.limbs[0] & 1 != 0;
                    return self.createBigIntFromScalar(if (!a.positive and odd) -1 else 1);
                }
                const exponent = b.toInt(u32) catch return error.RangeError;
                return self.bigIntPow(a, exponent);
            },
            .bitwise_and => {
                const required = if (a.limbs.len >= b.limbs.len)
                    if (b.positive) b.limbs.len else if (a.positive) a.limbs.len else a.limbs.len + 1
                else if (a.positive) a.limbs.len else if (b.positive) b.limbs.len else b.limbs.len + 1;
                var temporary = BigIntCore.Mutable.init(self.bigint_work_scratch[0..@max(@as(usize, 1), required)], 0);
                temporary.bitAnd(a, b);
                if (temporary.len > max_bigint_limbs) return error.RangeError;
                return self.storeBigIntMutable(temporary);
            },
            .bitwise_or => {
                const required = @max(a.limbs.len, b.limbs.len);
                var temporary = BigIntCore.Mutable.init(self.bigint_work_scratch[0..required], 0);
                temporary.bitOr(a, b);
                return self.storeBigIntMutable(temporary);
            },
            .bitwise_xor => {
                const required = @max(a.limbs.len, b.limbs.len) + @intFromBool(a.positive != b.positive);
                var temporary = BigIntCore.Mutable.init(self.bigint_work_scratch[0..required], 0);
                temporary.bitXor(a, b);
                if (temporary.len > max_bigint_limbs) return error.RangeError;
                return self.storeBigIntMutable(temporary);
            },
            .shift_left, .shift_right => return self.bigIntShift(operation, a, b),
            .shift_unsigned => return error.TypeError,
            else => return error.TypeError,
        }
    }

    fn bigIntPow(self: *Runtime, source: BigIntCore.Const, raw_exponent: u32) Error!Value {
        var accumulator = BigIntCore.Mutable.init(self.bigint_result_scratch[0..], 1);
        var factor = BigIntCore.Mutable.init(self.bigint_remainder_scratch[0..], 0);
        factor.copy(source);
        var exponent = raw_exponent;
        while (exponent > 0) {
            if (exponent & 1 != 0) {
                const required = accumulator.len + factor.len;
                if (required > self.bigint_work_scratch.len) return error.RangeError;
                var product = BigIntCore.Mutable.init(self.bigint_work_scratch[0..required], 0);
                product.mulNoAlias(accumulator.toConst(), factor.toConst(), null);
                if (product.len > max_bigint_limbs) return error.RangeError;
                accumulator.copy(product.toConst());
            }
            exponent >>= 1;
            if (exponent == 0) break;
            const required = factor.len * 2;
            if (required > self.bigint_work_scratch.len) return error.RangeError;
            var square = BigIntCore.Mutable.init(self.bigint_work_scratch[0..required], 0);
            square.mulNoAlias(factor.toConst(), factor.toConst(), null);
            if (square.len > max_bigint_limbs) return error.RangeError;
            factor.copy(square.toConst());
        }
        return self.storeBigIntMutable(accumulator);
    }

    fn bigIntShift(self: *Runtime, operation: BinaryOp, value: BigIntCore.Const, shift_value: BigIntCore.Const) Error!Value {
        var left = operation == .shift_left;
        if (!shift_value.positive and !shift_value.eqlZero()) left = !left;
        const magnitude = shift_value.abs().toInt(usize) catch {
            if (left and !value.eqlZero()) return error.RangeError;
            if (left) return self.createBigIntFromScalar(0);
            return self.createBigIntFromScalar(if (value.positive) 0 else -1);
        };
        if (left) {
            if (value.eqlZero()) return self.createBigIntFromScalar(0);
            const required = value.limbs.len + magnitude / @bitSizeOf(BigIntLimb) + 1;
            if (required > self.bigint_work_scratch.len) return error.RangeError;
            var result = BigIntCore.Mutable.init(self.bigint_work_scratch[0..required], 0);
            result.shiftLeft(value, magnitude);
            if (result.len > max_bigint_limbs) return error.RangeError;
            return self.storeBigIntMutable(result);
        }
        const required = if (magnitude / @bitSizeOf(BigIntLimb) >= value.limbs.len)
            1
        else
            value.limbs.len - magnitude / @bitSizeOf(BigIntLimb);
        var result = BigIntCore.Mutable.init(self.bigint_result_scratch[0..required], 0);
        result.shiftRight(value, magnitude);
        return self.storeBigIntMutable(result);
    }

    fn bigIntUnaryNegative(self: *Runtime, value: Value) Error!Value {
        const source = try self.bigIntConst(value);
        return self.createBigIntFromConst(if (source.eqlZero()) source.abs() else source.negate());
    }

    fn bigIntUnaryNot(self: *Runtime, value: Value) Error!Value {
        const source = try self.bigIntConst(value);
        const required = source.limbs.len + 1;
        var result = BigIntCore.Mutable.init(self.bigint_work_scratch[0..required], 0);
        result.copy(source.negate());
        result.addScalar(result.toConst(), -1);
        if (result.len > max_bigint_limbs) return error.RangeError;
        return self.storeBigIntMutable(result);
    }

    fn bigIntAddSmall(self: *Runtime, value: Value, amount: i64) Error!Value {
        const source = try self.bigIntConst(value);
        const required = source.limbs.len + 1;
        var result = BigIntCore.Mutable.init(self.bigint_work_scratch[0..required], 0);
        result.addScalar(source, amount);
        if (result.len > max_bigint_limbs) return error.RangeError;
        return self.storeBigIntMutable(result);
    }

    fn bigIntToStringRef(self: *Runtime, value: Value, radix: u8) Error!StringRef {
        const source = try self.bigIntConst(value);
        const size = source.sizeInBaseUpperBound(radix);
        const work_count = BigIntCore.calcToStringLimbsBufferLen(source.limbs.len, radix);
        if (size > self.string_scratch.len or work_count > self.bigint_work_scratch.len) return error.StringLimit;
        const length = source.toString(self.string_scratch[0..size], radix, .lower, self.bigint_work_scratch[0..work_count]);
        return self.storeString(self.string_scratch[0..length]);
    }

    fn bigIntToNumber(self: *Runtime, value: Value) Error!f64 {
        const source = try self.bigIntConst(value);
        return source.toFloat(f64, .nearest_even)[0];
    }

    fn compareBigIntAndNumber(self: *Runtime, bigint: Value, number: f64) Error!?std.math.Order {
        if (std.math.isNan(number)) return null;
        if (std.math.isPositiveInf(number)) return .lt;
        if (std.math.isNegativeInf(number)) return .gt;
        const source = try self.bigIntConst(bigint);
        if (@trunc(number) == number) return BigIntCore.Const.order(source, try self.numberAsBigIntConst(number));
        const integer = if (number > 0) @floor(number) else @ceil(number);
        const order = BigIntCore.Const.order(source, try self.numberAsBigIntConst(integer));
        if (order != .eq) return order;
        return if (number > integer) .lt else .gt;
    }

    fn propertyStorage(self: *Runtime, index: u16) []Property {
        const cell = &self.cells[index];
        return if (cell.property_memory) |memory|
            memory[0..cell.property_capacity]
        else
            cell.properties[0..];
    }

    fn propertyStorageConst(self: *const Runtime, index: u16) []const Property {
        const cell = &self.cells[index];
        return if (cell.property_memory) |memory|
            memory[0..cell.property_capacity]
        else
            cell.properties[0..];
    }

    fn ensurePropertyCapacity(self: *Runtime, index: u16, required: usize) Error!void {
        if (required <= self.propertyStorage(index).len) return;
        if (required > max_properties) {
            self.diagnostic_limit_required = required;
            self.diagnostic_limit_available = max_properties;
            return error.PropertyLimit;
        }
        const cell = &self.cells[index];
        var capacity = @max(cell.property_capacity, max_inline_properties);
        while (capacity < required) capacity = @min(max_properties, capacity * 2);
        const byte_count = capacity * @sizeOf(Property);
        const raw = self.program_allocator.allocate(
            self.program_allocator.context,
            byte_count,
            @alignOf(Property),
        ) orelse return error.ProgramAllocation;
        const memory: [*]Property = @ptrCast(@alignCast(raw));
        const old_properties = self.propertyStorageConst(index)[0..cell.property_count];
        if (old_properties.len > 0) @memcpy(memory[0..old_properties.len], old_properties);
        if (cell.property_memory) |old_memory| {
            self.program_allocator.free(
                self.program_allocator.context,
                @ptrCast(old_memory),
                cell.property_capacity * @sizeOf(Property),
                @alignOf(Property),
            );
        }
        cell.property_memory = memory;
        cell.property_capacity = capacity;
    }

    fn releasePropertyStorage(self: *Runtime, cell: *Cell) void {
        const memory = cell.property_memory orelse return;
        self.program_allocator.free(
            self.program_allocator.context,
            @ptrCast(memory),
            cell.property_capacity * @sizeOf(Property),
            @alignOf(Property),
        );
        cell.property_memory = null;
        cell.property_capacity = 0;
    }

    fn releasePropertyCells(self: *Runtime) void {
        for (&self.cells) |*cell| {
            if (!cell.occupied) continue;
            self.releasePropertyStorage(cell);
        }
    }

    fn accessorStorage(self: *Runtime) []Accessor {
        return if (self.accessor_memory) |memory| memory[0..self.accessor_capacity] else &.{};
    }

    fn accessorStorageConst(self: *const Runtime) []const Accessor {
        return if (self.accessor_memory) |memory| memory[0..self.accessor_capacity] else &.{};
    }

    fn allocateAccessor(self: *Runtime) Error!*Accessor {
        for (self.accessorStorage()) |*accessor| {
            if (!accessor.occupied) return accessor;
        }

        const old_capacity = self.accessor_capacity;
        if (old_capacity == std.math.maxInt(usize)) return error.ProgramAllocation;
        const required = old_capacity + 1;
        var capacity = @max(old_capacity, initial_accessor_capacity);
        while (capacity < required) {
            if (capacity > std.math.maxInt(usize) / 2) {
                capacity = required;
                break;
            }
            capacity *= 2;
        }
        if (capacity > std.math.maxInt(usize) / @sizeOf(Accessor)) return error.ProgramAllocation;
        const byte_count = capacity * @sizeOf(Accessor);
        const raw = self.program_allocator.allocate(
            self.program_allocator.context,
            byte_count,
            @alignOf(Accessor),
        ) orelse return error.ProgramAllocation;
        const memory: [*]Accessor = @ptrCast(@alignCast(raw));
        const old_accessors = self.accessorStorageConst();
        if (old_accessors.len > 0) @memcpy(memory[0..old_accessors.len], old_accessors);
        for (memory[old_capacity..capacity]) |*accessor| accessor.* = .{};
        if (self.accessor_memory) |old_memory| {
            self.program_allocator.free(
                self.program_allocator.context,
                @ptrCast(old_memory),
                old_capacity * @sizeOf(Accessor),
                @alignOf(Accessor),
            );
        }
        self.accessor_memory = memory;
        self.accessor_capacity = capacity;
        return &memory[old_capacity];
    }

    fn releaseAccessorStorage(self: *Runtime) void {
        const memory = self.accessor_memory orelse return;
        self.program_allocator.free(
            self.program_allocator.context,
            @ptrCast(memory),
            self.accessor_capacity * @sizeOf(Accessor),
            @alignOf(Accessor),
        );
        self.accessor_memory = null;
        self.accessor_capacity = 0;
    }

    fn bindingStorage(self: *Runtime, index: u16) []Binding {
        const cell = &self.cells[index];
        return if (cell.binding_memory) |memory|
            memory[0..cell.binding_capacity]
        else
            cell.storage.bindings[0..];
    }

    fn bindingStorageConst(self: *const Runtime, index: u16) []const Binding {
        const cell = &self.cells[index];
        return if (cell.binding_memory) |memory|
            memory[0..cell.binding_capacity]
        else
            cell.storage.bindings[0..];
    }

    fn ensureBindingCapacity(self: *Runtime, index: u16, required: usize) Error!void {
        if (required <= self.bindingStorage(index).len) return;
        if (required > max_bindings or self.cells[index].kind != .environment) {
            self.diagnostic_limit_required = required;
            self.diagnostic_limit_available = max_bindings;
            return error.BindingLimit;
        }
        const cell = &self.cells[index];
        var capacity = @max(cell.binding_capacity, max_inline_bindings);
        while (capacity < required) capacity = @min(max_bindings, capacity * 2);
        const byte_count = capacity * @sizeOf(Binding);
        const raw = self.program_allocator.allocate(
            self.program_allocator.context,
            byte_count,
            @alignOf(Binding),
        ) orelse return error.ProgramAllocation;
        const memory: [*]Binding = @ptrCast(@alignCast(raw));
        const old_bindings = self.bindingStorageConst(index)[0..cell.binding_count];
        if (old_bindings.len > 0) @memcpy(memory[0..old_bindings.len], old_bindings);
        if (cell.binding_memory) |old_memory| {
            self.program_allocator.free(
                self.program_allocator.context,
                @ptrCast(old_memory),
                cell.binding_capacity * @sizeOf(Binding),
                @alignOf(Binding),
            );
        }
        cell.binding_memory = memory;
        cell.binding_capacity = capacity;
    }

    fn releaseBindingStorage(self: *Runtime, cell: *Cell) void {
        const memory = cell.binding_memory orelse return;
        self.program_allocator.free(
            self.program_allocator.context,
            @ptrCast(memory),
            cell.binding_capacity * @sizeOf(Binding),
            @alignOf(Binding),
        );
        cell.binding_memory = null;
        cell.binding_capacity = 0;
    }

    fn releaseBindingCells(self: *Runtime) void {
        for (&self.cells) |*cell| {
            if (!cell.occupied) continue;
            self.releaseBindingStorage(cell);
        }
    }

    fn itemStorage(self: *Runtime, index: u16) []Value {
        const cell = &self.cells[index];
        return if (cell.item_memory) |memory|
            memory[0..cell.item_capacity]
        else
            cell.storage.items[0..];
    }

    fn itemStorageConst(self: *const Runtime, index: u16) []const Value {
        const cell = &self.cells[index];
        return if (cell.item_memory) |memory|
            memory[0..cell.item_capacity]
        else
            cell.storage.items[0..];
    }

    fn arrayItemPresent(self: *const Runtime, index: u16, item_index: usize) bool {
        if (item_index >= self.cells[index].item_count) return false;
        if (self.cells[index].kind != .array and !isPresenceCollectionTag(self.cells[index].host_tag)) return true;
        if (self.cells[index].item_presence_memory) |presence|
            return presence[item_index / 64] & (@as(u64, 1) << @intCast(item_index % 64)) != 0;
        if (item_index >= max_inline_items) return false;
        return self.cells[index].inline_item_presence & (@as(u16, 1) << @intCast(item_index)) != 0;
    }

    fn setArrayItemPresent(self: *Runtime, index: u16, item_index: usize, present: bool) void {
        if ((self.cells[index].kind != .array and !isPresenceCollectionTag(self.cells[index].host_tag)) or item_index >= max_items) return;
        if (self.cells[index].item_presence_memory) |presence| {
            const mask = @as(u64, 1) << @intCast(item_index % 64);
            if (present)
                presence[item_index / 64] |= mask
            else
                presence[item_index / 64] &= ~mask;
            return;
        }
        if (item_index < max_inline_items) {
            const mask = @as(u16, 1) << @intCast(item_index);
            if (present) self.cells[index].inline_item_presence |= mask else self.cells[index].inline_item_presence &= ~mask;
        }
    }

    fn extendArrayItems(self: *Runtime, index: u16, required: usize) Error!void {
        if (required <= self.cells[index].item_count) return;
        const old_count = self.cells[index].item_count;
        try self.ensureItemCapacity(index, required);
        for (old_count..required) |item_index| {
            self.itemStorage(index)[item_index] = .undefined;
            self.setArrayItemPresent(index, item_index, false);
        }
        self.cells[index].item_count = required;
    }

    fn ensureItemCapacity(self: *Runtime, index: u16, required: usize) Error!void {
        if (required <= self.itemStorage(index).len) return;
        const cell = &self.cells[index];
        if (required > max_items or (cell.kind != .array and cell.kind != .function and cell.kind != .bound_function and !isPresenceCollectionTag(cell.host_tag) and !isIteratorStorageTag(cell.host_tag))) {
            self.diagnostic_limit_required = required;
            self.diagnostic_limit_available = max_items;
            return error.ItemLimit;
        }
        var capacity = @max(cell.item_capacity, max_inline_items);
        while (capacity < required) capacity = @min(max_items, capacity * 2);
        const byte_count = capacity * @sizeOf(Value);
        const raw = self.program_allocator.allocate(
            self.program_allocator.context,
            byte_count,
            @alignOf(Value),
        ) orelse return error.ProgramAllocation;
        const memory: [*]Value = @ptrCast(@alignCast(raw));
        errdefer self.program_allocator.free(
            self.program_allocator.context,
            raw,
            byte_count,
            @alignOf(Value),
        );
        const old_items = self.itemStorageConst(index)[0..cell.item_count];
        if (old_items.len > 0) @memcpy(memory[0..old_items.len], old_items);

        var presence_memory: ?[*]u64 = null;
        var presence_capacity: usize = 0;
        if (cell.kind == .array or isPresenceCollectionTag(cell.host_tag)) {
            presence_capacity = (capacity + 63) / 64;
            const presence_byte_count = presence_capacity * @sizeOf(u64);
            const presence_raw = self.program_allocator.allocate(
                self.program_allocator.context,
                presence_byte_count,
                @alignOf(u64),
            ) orelse return error.ProgramAllocation;
            presence_memory = @ptrCast(@alignCast(presence_raw));
            @memset(presence_memory.?[0..presence_capacity], 0);
            if (cell.item_presence_memory) |old_presence| {
                @memcpy(presence_memory.?[0..cell.item_presence_capacity], old_presence[0..cell.item_presence_capacity]);
            } else {
                presence_memory.?[0] = cell.inline_item_presence;
            }
        }

        if (cell.item_memory) |old_memory| {
            self.program_allocator.free(
                self.program_allocator.context,
                @ptrCast(old_memory),
                cell.item_capacity * @sizeOf(Value),
                @alignOf(Value),
            );
        }
        if (cell.item_presence_memory) |old_presence| {
            self.program_allocator.free(
                self.program_allocator.context,
                @ptrCast(old_presence),
                cell.item_presence_capacity * @sizeOf(u64),
                @alignOf(u64),
            );
        }
        cell.item_memory = memory;
        cell.item_capacity = capacity;
        cell.item_presence_memory = presence_memory;
        cell.item_presence_capacity = presence_capacity;
    }

    fn releaseItemStorage(self: *Runtime, cell: *Cell) void {
        if (cell.item_memory) |memory| {
            self.program_allocator.free(
                self.program_allocator.context,
                @ptrCast(memory),
                cell.item_capacity * @sizeOf(Value),
                @alignOf(Value),
            );
        }
        if (cell.item_presence_memory) |presence| {
            self.program_allocator.free(
                self.program_allocator.context,
                @ptrCast(presence),
                cell.item_presence_capacity * @sizeOf(u64),
                @alignOf(u64),
            );
        }
        cell.item_memory = null;
        cell.item_capacity = 0;
        cell.item_presence_memory = null;
        cell.item_presence_capacity = 0;
    }

    fn releaseItemCells(self: *Runtime) void {
        for (&self.cells) |*cell| {
            if (!cell.occupied) continue;
            self.releaseItemStorage(cell);
        }
    }

    fn defineBinding(self: *Runtime, environment: u16, name: []const u8, value: Value, constant: bool) Error!void {
        var target = environment;
        while (target != none and target < self.cells.len and self.cells[target].kind == .environment and self.cells[target].object_environment)
            target = self.cells[target].parent;
        if (target == none or target >= self.cells.len or self.cells[target].kind != .environment) return error.TypeError;
        var cell = &self.cells[target];
        for (self.bindingStorage(target)[0..cell.binding_count]) |*binding| {
            if (equals(self.stringBytes(binding.name), name)) {
                if (binding.constant) return error.ConstAssignment;
                binding.value = value;
                return;
            }
        }
        self.ensureBindingCapacity(target, cell.binding_count + 1) catch |err| {
            self.recordDiagnostic(name);
            return err;
        };
        self.bindingStorage(target)[cell.binding_count] = .{ .name = try self.storeString(name), .value = value, .constant = constant };
        cell.binding_count += 1;
    }

    fn defineImportedBinding(self: *Runtime, environment: u16, name: []const u8, module_index: u16, import_name: []const u8) Error!void {
        if (environment == none or environment >= self.cells.len or self.cells[environment].kind != .environment) return error.TypeError;
        if (self.lookupOwn(environment, name) != null) return error.SyntaxError;
        var cell = &self.cells[environment];
        self.ensureBindingCapacity(environment, cell.binding_count + 1) catch |err| {
            self.recordDiagnostic(name);
            return err;
        };
        self.bindingStorage(environment)[cell.binding_count] = .{
            .name = try self.storeString(name),
            .constant = true,
            .import_module = module_index,
            .import_name = try self.storeString(import_name),
        };
        cell.binding_count += 1;
    }

    fn bindingValue(self: *Runtime, binding: Binding) ?Value {
        if (binding.import_module != none)
            return self.moduleExportValue(binding.import_module, self.stringBytes(binding.import_name), 0);
        return binding.value;
    }

    fn assignBinding(self: *Runtime, environment: u16, name: []const u8, value: Value) Error!void {
        var current = environment;
        while (current != none) {
            const cell = &self.cells[current];
            if (cell.object_environment and try self.objectEnvironmentHasBinding(cell.receiver, name)) {
                if (cell.receiver == .cell) try self.setProperty(cell.receiver, name, value);
                return;
            }
            for (self.bindingStorage(current)[0..cell.binding_count]) |*binding| {
                if (equals(self.stringBytes(binding.name), name)) {
                    if (binding.constant) return error.ConstAssignment;
                    binding.value = value;
                    return;
                }
            }
            current = cell.parent;
        }
        return error.UnknownIdentifier;
    }

    fn assignLexicalBinding(self: *Runtime, environment: u16, name: []const u8, value: Value) Error!void {
        var current = environment;
        while (current != none) {
            const cell = &self.cells[current];
            for (self.bindingStorage(current)[0..cell.binding_count]) |*binding| {
                if (equals(self.stringBytes(binding.name), name)) {
                    if (binding.constant) return error.ConstAssignment;
                    binding.value = value;
                    return;
                }
            }
            current = cell.parent;
        }
        return error.UnknownIdentifier;
    }

    fn resolveBinding(self: *Runtime, environment: u16, name: []const u8) Error!?ResolvedBinding {
        var current = environment;
        while (current != none) {
            const cell = &self.cells[current];
            if (cell.object_environment and try self.objectEnvironmentHasBinding(cell.receiver, name)) {
                return .{ .value = try self.getProperty(cell.receiver, name), .receiver = cell.receiver, .object = true };
            }
            for (self.bindingStorageConst(current)[0..cell.binding_count]) |binding| {
                if (equals(self.stringBytes(binding.name), name)) {
                    return .{ .value = self.bindingValue(binding) orelse .undefined };
                }
            }
            current = cell.parent;
        }
        return null;
    }

    fn objectEnvironmentHasBinding(self: *Runtime, receiver: Value, name: []const u8) Error!bool {
        if (!try self.hasProperty(receiver, name)) return false;
        if (self.symbol_unscopables.len == 0) return true;
        const unscopables = try self.getProperty(receiver, self.stringBytes(self.symbol_unscopables));
        if (unscopables != .cell) return true;
        return !self.truthy(try self.getProperty(unscopables, name));
    }

    fn lookup(self: *Runtime, environment: u16, name: []const u8) ?Value {
        var current = environment;
        while (current != none) {
            const cell = &self.cells[current];
            for (self.bindingStorageConst(current)[0..cell.binding_count]) |binding| {
                if (equals(self.stringBytes(binding.name), name)) return self.bindingValue(binding);
            }
            current = cell.parent;
        }
        return null;
    }

    fn thisValue(self: *Runtime, environment: u16) Error!Value {
        var current = environment;
        while (current != none) {
            const cell = &self.cells[current];
            var function_environment = false;
            for (self.bindingStorageConst(current)[0..cell.binding_count]) |binding| {
                const binding_name = self.stringBytes(binding.name);
                if (equals(binding_name, "this")) return self.bindingValue(binding) orelse .undefined;
                if (equals(binding_name, internal_new_target)) function_environment = true;
            }
            if (function_environment) return error.TypeError;
            current = cell.parent;
        }
        return if (self.active_module != none) .undefined else self.global("globalThis") orelse .undefined;
    }

    fn lookupRequired(self: *Runtime, program: *const Program, ref: StringRef, environment: u16) Error!Value {
        const name = program.text(ref);
        if (try self.resolveBinding(environment, name)) |binding| return binding.value;
        self.recordDiagnostic(name);
        self.recordDiagnosticContext(program, ref);
        return error.UnknownIdentifier;
    }

    fn lookupRequiredCached(self: *Runtime, program: *const Program, node_index: u16, environment: u16) Error!Value {
        if (node_index == none or node_index >= program.node_count) return error.BytecodeInvalid;
        const ref = program.nodes[node_index].text;
        const name = program.text(ref);
        const slot = self.identifierCacheSlot(program, node_index);
        if (self.cachedIdentifierValue(slot, program, node_index, environment, name)) |value| {
            self.stats.identifier_cache_hits += 1;
            return value;
        }

        self.stats.identifier_cache_misses += 1;
        var current = environment;
        var depth: usize = 0;
        while (current != none) {
            const cell = &self.cells[current];
            if (cell.object_environment) return self.lookupRequired(program, ref, environment);
            for (self.bindingStorageConst(current)[0..cell.binding_count], 0..) |binding, binding_index| {
                if (!equals(self.stringBytes(binding.name), name)) continue;
                self.cacheIdentifierBinding(slot, program, node_index, environment, current, depth, binding_index);
                return self.bindingValue(binding) orelse .undefined;
            }
            current = cell.parent;
            depth += 1;
        }
        self.recordDiagnostic(name);
        self.recordDiagnosticContext(program, ref);
        return error.UnknownIdentifier;
    }

    fn identifierCacheSlot(self: *const Runtime, program: *const Program, node_index: u16) usize {
        return ((@intFromPtr(program) >> 4) ^ (@as(usize, node_index) *% 0x9E37)) % self.identifier_cache.len;
    }

    fn cacheIdentifierBinding(self: *Runtime, slot: usize, program: *const Program, node_index: u16, environment: u16, binding_environment: u16, depth: usize, binding_index: usize) void {
        if (depth >= none or binding_index >= none) return;
        self.identifier_cache[slot] = .{
            .program = program,
            .program_generation = program.parse_generation,
            .node = node_index,
            .depth = @intCast(depth),
            .binding_index = @intCast(binding_index),
            .environment = environment,
            .environment_generation = self.cells[environment].generation,
            .environment_binding_count = @intCast(self.cells[environment].binding_count),
            .binding_environment = binding_environment,
            .binding_generation = self.cells[binding_environment].generation,
        };
    }

    fn cachedIdentifierValue(self: *Runtime, slot: usize, program: *const Program, node_index: u16, environment: u16, name: []const u8) ?Value {
        const location = self.cachedIdentifierLocation(slot, program, node_index, environment, name) orelse return null;
        const binding = self.bindingStorageConst(location.environment)[location.binding_index];
        return self.bindingValue(binding) orelse Value.undefined;
    }

    fn cachedIdentifierLocation(self: *Runtime, slot: usize, program: *const Program, node_index: u16, environment: u16, name: []const u8) ?CachedIdentifierLocation {
        const cached = &self.identifier_cache[slot];
        if (cached.program != program or cached.program_generation != program.parse_generation or cached.node != node_index or
            cached.depth == none or cached.binding_index == none) return null;
        if (cached.depth <= 1 and cached.environment == environment and environment != none and environment < self.cells.len and
            !self.cells[environment].object_environment and self.cells[environment].generation == cached.environment_generation and
            self.cells[environment].binding_count == cached.environment_binding_count and
            cached.binding_environment != none and cached.binding_environment < self.cells.len)
        {
            const direct_cell = &self.cells[cached.binding_environment];
            if (direct_cell.occupied and direct_cell.kind == .environment and !direct_cell.object_environment and
                direct_cell.generation == cached.binding_generation and cached.binding_index < direct_cell.binding_count)
            {
                return .{
                    .environment = cached.binding_environment,
                    .binding_index = cached.binding_index,
                };
            }
        }
        var current = environment;
        var depth: usize = 0;
        while (depth < cached.depth) : (depth += 1) {
            if (current == none or current >= self.cells.len) return null;
            const cell = &self.cells[current];
            if (!cell.occupied or cell.kind != .environment or cell.object_environment) return null;
            for (self.bindingStorageConst(current)[0..cell.binding_count]) |binding|
                if (equals(self.stringBytes(binding.name), name)) return null;
            current = cell.parent;
        }
        if (current == none or current >= self.cells.len) return null;
        const cell = &self.cells[current];
        if (!cell.occupied or cell.kind != .environment or cell.object_environment or cached.binding_index >= cell.binding_count) return null;
        const bindings = self.bindingStorageConst(current);
        for (bindings[0..cached.binding_index]) |binding|
            if (equals(self.stringBytes(binding.name), name)) return null;
        const binding = bindings[cached.binding_index];
        if (!equals(self.stringBytes(binding.name), name)) return null;
        cached.environment = environment;
        cached.environment_generation = self.cells[environment].generation;
        cached.environment_binding_count = @intCast(self.cells[environment].binding_count);
        cached.binding_environment = current;
        cached.binding_generation = cell.generation;
        return .{ .environment = current, .binding_index = cached.binding_index };
    }

    fn assignIdentifierCached(self: *Runtime, program: *const Program, node_index: u16, environment: u16, value: Value) Error!void {
        if (node_index == none or node_index >= program.node_count) return error.BytecodeInvalid;
        const name = program.text(program.nodes[node_index].text);
        const slot = self.identifierCacheSlot(program, node_index);
        if (self.cachedIdentifierLocation(slot, program, node_index, environment, name)) |location| {
            self.stats.identifier_cache_hits += 1;
            const binding = &self.bindingStorage(location.environment)[location.binding_index];
            if (binding.constant) return error.ConstAssignment;
            binding.value = value;
            return;
        }
        self.stats.identifier_cache_misses += 1;
        var current = environment;
        var depth: usize = 0;
        while (current != none) {
            const cell = &self.cells[current];
            if (cell.object_environment) return self.assignBinding(environment, name, value);
            for (self.bindingStorage(current)[0..cell.binding_count], 0..) |*binding, binding_index| {
                if (!equals(self.stringBytes(binding.name), name)) continue;
                self.cacheIdentifierBinding(slot, program, node_index, environment, current, depth, binding_index);
                if (binding.constant) return error.ConstAssignment;
                binding.value = value;
                return;
            }
            current = cell.parent;
            depth += 1;
        }
        return error.UnknownIdentifier;
    }

    fn recordDiagnosticContext(self: *Runtime, program: *const Program, ref: StringRef) void {
        if (ref.offset & identifier_ref_bit != 0) {
            self.diagnostic_context_len = 0;
            return;
        }
        const center: usize = ref.offset;
        const source = program.source[0..program.source_len];
        const start = center -| 80;
        const end = @min(source.len, center + @as(usize, ref.len) + 80);
        self.diagnostic_context_len = @min(end - start, self.diagnostic_context.len);
        if (self.diagnostic_context_len > 0) @memcpy(self.diagnostic_context[0..self.diagnostic_context_len], source[start .. start + self.diagnostic_context_len]);
    }

    fn recordDiagnostic(self: *Runtime, name: []const u8) void {
        self.diagnostic_name_len = @min(name.len, self.diagnostic_name.len);
        if (self.diagnostic_name_len > 0) @memcpy(self.diagnostic_name[0..self.diagnostic_name_len], name[0..self.diagnostic_name_len]);
    }

    fn diagnosticNodeOffset(program: *const Program, node_index: u16) usize {
        return program.nodeSourceOffset(node_index);
    }

    fn sourcePosition(program: *const Program, wanted_offset: usize) struct { line: u32, column: u32 } {
        const end = @min(wanted_offset, program.source_len);
        var line: u32 = 1;
        var column: u32 = 1;
        var offset: usize = 0;
        while (offset < end) : (offset += 1) {
            if (program.source[offset] == '\n') {
                line += 1;
                column = 1;
            } else {
                column += 1;
            }
        }
        return .{ .line = line, .column = column };
    }

    fn captureDiagnostic(self: *Runtime, phase: DiagnosticPhase, err: Error, program: *const Program, node_index: u16) void {
        const error_name = @errorName(err);
        const existing_error = self.diagnostic_error_name[0..self.diagnostic_error_name_len];
        const preserve_origin = phase == .vm and self.diagnostic_phase == .vm and equals(existing_error, error_name);
        const offset = diagnosticNodeOffset(program, node_index);
        const position = sourcePosition(program, offset);
        if (!preserve_origin) {
            self.diagnostic_phase = phase;
            self.diagnostic_error_name_len = @min(error_name.len, self.diagnostic_error_name.len);
            if (self.diagnostic_error_name_len > 0)
                @memcpy(self.diagnostic_error_name[0..self.diagnostic_error_name_len], error_name[0..self.diagnostic_error_name_len]);
            const source_name = program.sourceName();
            self.diagnostic_source_name_len = @min(source_name.len, self.diagnostic_source_name.len);
            if (self.diagnostic_source_name_len > 0)
                @memcpy(self.diagnostic_source_name[0..self.diagnostic_source_name_len], source_name[0..self.diagnostic_source_name_len]);
            self.diagnostic_line = position.line;
            self.diagnostic_column = position.column;
            self.diagnostic_context_len = 0;
            self.recordDiagnosticContext(program, .{ .offset = @intCast(offset), .len = 1 });
        }

        if (preserve_origin) return;
        self.diagnostic_stack_len = 0;
        var frame_count = self.bytecode_frame_count;
        while (frame_count > 0 and self.diagnostic_stack_len < self.diagnostic_stack.len) {
            frame_count -= 1;
            const frame = self.bytecode_frames[frame_count];
            const frame_program = frame.program orelse continue;
            const frame_node = if (frame.segment != none and frame.segment < frame_program.bytecode_segment_count)
                frame_program.workspace.compiled.segment_nodes[frame.segment]
            else
                none;
            const frame_position = sourcePosition(frame_program, diagnosticNodeOffset(frame_program, frame_node));
            if (self.diagnostic_stack_len > 0) appendBytes(self.diagnostic_stack[0..], &self.diagnostic_stack_len, "\n") catch break;
            appendBytes(self.diagnostic_stack[0..], &self.diagnostic_stack_len, "at ") catch break;
            appendBytes(self.diagnostic_stack[0..], &self.diagnostic_stack_len, frame_program.sourceName()) catch break;
            var position_buffer: [48]u8 = undefined;
            const rendered = std.fmt.bufPrint(position_buffer[0..], ":{d}:{d}", .{ frame_position.line, frame_position.column }) catch break;
            appendBytes(self.diagnostic_stack[0..], &self.diagnostic_stack_len, rendered) catch break;
        }
        if (self.diagnostic_stack_len == 0) {
            appendBytes(self.diagnostic_stack[0..], &self.diagnostic_stack_len, "at ") catch return;
            appendBytes(self.diagnostic_stack[0..], &self.diagnostic_stack_len, self.diagnosticSourceName()) catch return;
            var position_buffer: [48]u8 = undefined;
            const rendered = std.fmt.bufPrint(position_buffer[0..], ":{d}:{d}", .{ self.diagnostic_line, self.diagnostic_column }) catch return;
            appendBytes(self.diagnostic_stack[0..], &self.diagnostic_stack_len, rendered) catch return;
        }
    }

    fn captureProgramDiagnostic(self: *Runtime, program: *const Program, err: Error) void {
        self.captureDiagnostic(if (program.diagnostic_phase == .none) .parser else program.diagnostic_phase, program.diagnostic_error orelse err, program, none);
        const position = sourcePosition(program, program.diagnostic_offset);
        self.diagnostic_line = position.line;
        self.diagnostic_column = position.column;
        self.recordDiagnosticContext(program, .{ .offset = @intCast(program.diagnostic_offset), .len = 1 });
    }

    fn recordExpressionDiagnostic(self: *Runtime, program: *const Program, index: u16) void {
        if (index == none) return;
        const node = program.nodes[index];
        switch (node.kind) {
            .identifier, .member => if (node.text.len > 0) {
                self.recordDiagnostic(program.text(node.text));
                self.recordDiagnosticContext(program, node.text);
            } else self.recordExpressionDiagnostic(program, node.a),
            .call, .new_expression => self.recordExpressionDiagnostic(program, node.a),
            .conditional => self.recordExpressionDiagnostic(program, node.b),
            else => {},
        }
    }

    fn lookupOwn(self: *Runtime, environment: u16, name: []const u8) ?Value {
        if (environment == none or environment >= self.cells.len) return null;
        const cell = &self.cells[environment];
        for (self.bindingStorageConst(environment)[0..cell.binding_count]) |binding| {
            if (equals(self.stringBytes(binding.name), name)) return self.bindingValue(binding);
        }
        return null;
    }

    fn deleteOwnProperty(self: *Runtime, object: Value, name: []const u8) Error!bool {
        const cell_index = try self.expectObject(object);
        if (self.cells[cell_index].kind == .proxy) return self.proxyDelete(object, name);
        if (self.isTypedArray(object)) switch (typedArrayPropertyIndex(name)) {
            .index => |item_index| return item_index >= self.typedArrayLengthOrZero(cell_index),
            .invalid_numeric => return true,
            .ordinary => {},
        };
        var cell = &self.cells[cell_index];
        if (cell.frozen) return false;
        if (self.findAccessor(cell_index, name)) |accessor| if (!accessor.configurable) return false;
        if (cell.kind == .array) {
            if (parseArrayIndex(name)) |item_index| {
                if (cell.sealed and self.arrayItemPresent(cell_index, item_index)) return false;
                if (item_index < cell.item_count) {
                    self.itemStorage(cell_index)[item_index] = .undefined;
                    self.setArrayItemPresent(cell_index, item_index, false);
                }
                self.clearArgumentMapping(cell_index, item_index);
            }
        }
        for (self.accessorStorage()) |*accessor| {
            if (accessor.occupied and accessor.owner == cell_index and equals(self.stringBytes(accessor.key), name)) accessor.occupied = false;
        }
        var property_index: usize = 0;
        while (property_index < cell.property_count) : (property_index += 1) {
            if (!equals(self.stringBytes(self.propertyStorageConst(cell_index)[property_index].key), name)) continue;
            if (!self.propertyStorageConst(cell_index)[property_index].configurable) return false;
            var move = property_index + 1;
            while (move < cell.property_count) : (move += 1)
                self.propertyStorage(cell_index)[move - 1] = self.propertyStorageConst(cell_index)[move];
            cell.property_count -= 1;
            break;
        }
        return true;
    }

    fn defineOwnDataProperty(self: *Runtime, object: Value, name: []const u8, value: Value) Error!void {
        const index = try self.expectObject(object);
        if (self.cells[index].kind == .module_namespace) return error.TypeError;
        if (self.cells[index].kind == .proxy) {
            const descriptor: Value = .{ .cell = try self.allocateCell(.object) };
            const root_base = self.root_count;
            defer self.root_count = root_base;
            try self.pushRoot(descriptor);
            try self.defineOwnDataProperty(descriptor, "value", value);
            try self.defineOwnDataProperty(descriptor, "writable", .{ .boolean = true });
            try self.defineOwnDataProperty(descriptor, "enumerable", .{ .boolean = true });
            try self.defineOwnDataProperty(descriptor, "configurable", .{ .boolean = true });
            if (!try self.proxyDefineProperty(object, name, descriptor)) return error.TypeError;
            return;
        }
        if (self.isTypedArray(object)) switch (typedArrayPropertyIndex(name)) {
            .index => |item_index| {
                if (self.cells[index].frozen or !try self.typedArrayWrite(index, item_index, value)) return error.TypeError;
                return;
            },
            .invalid_numeric => return error.TypeError,
            .ordinary => {},
        };
        if (self.cells[index].frozen) return error.TypeError;
        if (self.cells[index].kind == .array) {
            if (equals(name, "length")) {
                try self.arrayLikeSetLength(object, try arrayLengthValue(try self.toNumber(value)));
                return;
            }
            if (parseArrayIndex(name)) |item_index| {
                if (!self.cells[index].array_length_writable and item_index >= self.effectiveArrayLength(index)) return error.TypeError;
                if (self.findAccessorMutable(index, name)) |accessor| {
                    if (!accessor.configurable) return error.TypeError;
                    accessor.occupied = false;
                    for (self.propertyStorage(index)[0..self.cells[index].property_count]) |*property| {
                        if (!equals(self.stringBytes(property.key), name)) continue;
                        property.value = value;
                        property.writable = true;
                        property.enumerable = true;
                        property.configurable = true;
                        return;
                    }
                }
                for (self.propertyStorage(index)[0..self.cells[index].property_count]) |*property| {
                    if (!equals(self.stringBytes(property.key), name)) continue;
                    if (!property.writable) return error.TypeError;
                    property.value = value;
                    return;
                }
                if (item_index >= self.cells[index].item_count and !self.cells[index].extensible) return error.TypeError;
                if (self.mappedArgumentName(index, item_index)) |mapped_name|
                    try self.assignBinding(self.cells[index].parent, mapped_name, value);
                try self.extendArrayItems(index, item_index + 1);
                self.itemStorage(index)[item_index] = value;
                self.setArrayItemPresent(index, item_index, true);
                self.cells[index].array_length = @max(self.cells[index].array_length, item_index + 1);
                return;
            }
        }
        if (self.findAccessorMutable(index, name)) |accessor| accessor.occupied = false;
        var cell = &self.cells[index];
        for (self.propertyStorage(index)[0..cell.property_count]) |*property| {
            if (!equals(self.stringBytes(property.key), name)) continue;
            if (!property.writable) return error.TypeError;
            property.value = value;
            return;
        }
        if (!cell.extensible) return error.TypeError;
        try self.ensurePropertyCapacity(index, cell.property_count + 1);
        self.propertyStorage(index)[cell.property_count] = .{ .key = try self.storeString(name), .value = value };
        cell.property_count += 1;
    }

    fn defineOwnAccessor(self: *Runtime, object: Value, name: []const u8, callable: Value, getter: bool) Error!void {
        const index = try self.expectObject(object);
        if (self.cells[index].kind == .proxy) {
            if (!self.isCallableValue(callable)) return error.TypeError;
            const descriptor: Value = .{ .cell = try self.allocateCell(.object) };
            const root_base = self.root_count;
            defer self.root_count = root_base;
            try self.pushRoot(descriptor);
            try self.defineOwnDataProperty(descriptor, if (getter) "get" else "set", callable);
            try self.defineOwnDataProperty(descriptor, "enumerable", .{ .boolean = true });
            try self.defineOwnDataProperty(descriptor, "configurable", .{ .boolean = true });
            if (!try self.proxyDefineProperty(object, name, descriptor)) return error.TypeError;
            return;
        }
        if (self.isTypedArray(object)) switch (typedArrayPropertyIndex(name)) {
            .index, .invalid_numeric => return error.TypeError,
            .ordinary => {},
        };
        if (self.cells[index].frozen) return error.TypeError;
        if (self.cells[index].kind == .array) {
            if (parseArrayIndex(name)) |item_index| self.clearArgumentMapping(index, item_index);
        }
        _ = switch (callable) {
            .cell => |cell| if (cell < self.cells.len and self.cells[cell].occupied and
                (self.cells[cell].kind == .function or self.cells[cell].kind == .bound_function or self.cells[cell].kind == .native_function or self.cells[cell].kind == .host_function)) cell else return error.TypeError,
            else => return error.TypeError,
        };
        var cell = &self.cells[index];
        var has_marker = false;
        for (self.propertyStorage(index)[0..cell.property_count]) |*property| {
            if (!equals(self.stringBytes(property.key), name)) continue;
            property.value = .undefined;
            has_marker = true;
            break;
        }
        if (!has_marker) {
            if (!cell.extensible) return error.TypeError;
            try self.ensurePropertyCapacity(index, cell.property_count + 1);
            self.propertyStorage(index)[cell.property_count] = .{ .key = try self.storeString(name), .value = .undefined };
            cell.property_count += 1;
        }
        if (self.findAccessorMutable(index, name)) |accessor| {
            if (!accessor.configurable) return error.TypeError;
            if (getter)
                accessor.getter = callable
            else
                accessor.setter = callable;
            return;
        }
        const accessor = try self.allocateAccessor();
        accessor.* = .{
            .occupied = true,
            .owner = index,
            .key = try self.storeString(name),
            .getter = if (getter) callable else .undefined,
            .setter = if (getter) .undefined else callable,
        };
    }

    fn setProperty(self: *Runtime, object: Value, name: []const u8, value: Value) Error!void {
        const index = try self.expectObject(object);
        if (self.cells[index].kind == .proxy) {
            _ = try self.proxySet(object, name, value, object);
            return;
        }
        if (self.cells[index].kind == .module_namespace) return;
        var cell = &self.cells[index];
        if (self.isTypedArray(object)) switch (typedArrayPropertyIndex(name)) {
            .index => |item_index| {
                if (!cell.frozen) _ = try self.typedArrayWrite(index, item_index, value);
                return;
            },
            .invalid_numeric => return,
            .ordinary => {},
        };
        if (cell.frozen) return;
        if (cell.host_property_set) |setter| {
            if (try setter(self, cell.host_context, cell.host_tag, object, name, value)) return;
        }
        if (cell.kind == .array) {
            if (equals(name, "length")) {
                if (cell.frozen or !cell.array_length_writable) return;
                try self.arrayLikeSetLength(object, try arrayLengthValue(try self.toNumber(value)));
                return;
            }
            if (parseArrayIndex(name)) |item_index| {
                if (!cell.array_length_writable and item_index >= self.effectiveArrayLength(index)) return;
                if (self.findAccessor(index, name)) |accessor| {
                    if (accessor.setter != .undefined) _ = try self.callAccessor(accessor.setter, object, &.{value});
                    return;
                }
                for (self.propertyStorage(index)[0..cell.property_count]) |*property| {
                    if (!equals(self.stringBytes(property.key), name)) continue;
                    if (property.writable) property.value = value;
                    return;
                }
                if (item_index >= cell.item_count and !cell.extensible) return;
                if (self.mappedArgumentName(index, item_index)) |mapped_name|
                    try self.assignBinding(cell.parent, mapped_name, value);
                try self.extendArrayItems(index, item_index + 1);
                self.itemStorage(index)[item_index] = value;
                self.setArrayItemPresent(index, item_index, true);
                cell.array_length = @max(cell.array_length, item_index + 1);
                return;
            }
        }
        if (self.findAccessor(index, name)) |accessor| {
            if (accessor.setter != .undefined) _ = try self.callAccessor(accessor.setter, object, &.{value});
            return;
        }
        for (self.propertyStorage(index)[0..cell.property_count]) |*property| {
            if (equals(self.stringBytes(property.key), name)) {
                if (!property.writable) return;
                property.value = value;
                return;
            }
        }
        var prototype = cell.prototype;
        while (prototype != none) {
            if (self.cells[prototype].kind == .proxy) {
                _ = try self.proxySet(.{ .cell = prototype }, name, value, object);
                return;
            }
            if (self.findAccessor(prototype, name)) |accessor| {
                if (accessor.setter != .undefined) _ = try self.callAccessor(accessor.setter, object, &.{value});
                return;
            }
            var inherited_data = false;
            var inherited_writable = true;
            for (self.propertyStorageConst(prototype)[0..self.cells[prototype].property_count]) |property| {
                if (equals(self.stringBytes(property.key), name)) {
                    inherited_data = true;
                    inherited_writable = property.writable;
                    break;
                }
            }
            if (inherited_data) {
                if (!inherited_writable) return;
                break;
            }
            prototype = self.cells[prototype].prototype;
        }
        if (!cell.extensible) return;
        try self.ensurePropertyCapacity(index, cell.property_count + 1);
        self.propertyStorage(index)[cell.property_count] = .{ .key = try self.storeString(name), .value = value };
        cell.property_count += 1;
    }

    fn defineDescriptor(self: *Runtime, object: Value, name: []const u8, descriptor: Value) Error!void {
        const index = try self.expectObject(object);
        if (self.cells[index].kind == .module_namespace) return error.TypeError;
        if (self.cells[index].kind == .proxy) {
            _ = try self.readDescriptorInfo(descriptor);
            if (!try self.proxyDefineProperty(object, name, descriptor)) return error.TypeError;
            return;
        }
        if (self.cells[index].frozen) return error.TypeError;
        _ = try self.expectObject(descriptor);
        const has_getter = try self.hasOwnProperty(descriptor, "get");
        const has_setter = try self.hasOwnProperty(descriptor, "set");
        const has_value = try self.hasOwnProperty(descriptor, "value");
        const has_writable = try self.hasOwnProperty(descriptor, "writable");
        const has_enumerable = try self.hasOwnProperty(descriptor, "enumerable");
        const has_configurable = try self.hasOwnProperty(descriptor, "configurable");
        if ((has_getter or has_setter) and (has_value or has_writable)) return error.TypeError;
        const getter = if (has_getter) try self.getProperty(descriptor, "get") else Value.undefined;
        const setter = if (has_setter) try self.getProperty(descriptor, "set") else Value.undefined;
        const value = if (has_value) try self.getProperty(descriptor, "value") else Value.undefined;
        if ((has_getter and getter != .undefined and !self.isCallableValue(getter)) or
            (has_setter and setter != .undefined and !self.isCallableValue(setter))) return error.TypeError;
        const writable = has_writable and self.truthy(try self.getProperty(descriptor, "writable"));
        const enumerable = has_enumerable and self.truthy(try self.getProperty(descriptor, "enumerable"));
        const configurable = has_configurable and self.truthy(try self.getProperty(descriptor, "configurable"));
        const accessor_descriptor = has_getter or has_setter;
        const data_descriptor = has_value or has_writable;

        if (self.isTypedArray(object)) switch (typedArrayPropertyIndex(name)) {
            .index => |item_index| {
                if (self.cells[index].frozen or accessor_descriptor or
                    (has_configurable and !configurable) or
                    (has_enumerable and !enumerable) or
                    (has_writable and !writable) or
                    item_index >= self.typedArrayLengthOrZero(index)) return error.TypeError;
                if (has_value and !try self.typedArrayWrite(index, item_index, value)) return error.TypeError;
                return;
            },
            .invalid_numeric => return error.TypeError,
            .ordinary => {},
        };

        if (self.cells[index].kind == .array and equals(name, "length")) {
            if (accessor_descriptor or configurable or enumerable) return error.TypeError;
            if (!self.cells[index].array_length_writable) {
                if (has_writable and writable) return error.TypeError;
                if (has_value and try arrayLengthValue(try self.toNumber(value)) != self.effectiveArrayLength(index)) return error.TypeError;
            }
            if (has_value) try self.arrayLikeSetLength(object, try arrayLengthValue(try self.toNumber(value)));
            if (has_writable and !writable) self.cells[index].array_length_writable = false;
            return;
        }

        if (self.cells[index].kind == .array) {
            if (parseArrayIndex(name)) |item_index| {
                if (item_index >= max_items) return error.RangeError;
                var stored_property = false;
                for (self.propertyStorageConst(index)[0..self.cells[index].property_count]) |property| {
                    if (equals(self.stringBytes(property.key), name)) {
                        stored_property = true;
                        break;
                    }
                }
                const stored_accessor = self.findAccessor(index, name) != null;
                const stored_item = self.arrayItemPresent(index, item_index);
                if (!stored_property and !stored_accessor and !stored_item and !self.cells[index].extensible) return error.TypeError;
                if (item_index >= self.effectiveArrayLength(index) and !self.cells[index].array_length_writable) return error.TypeError;
                if (stored_item and !stored_property and !stored_accessor) {
                    try self.ensurePropertyCapacity(index, self.cells[index].property_count + 1);
                    const current = try self.arrayLikeGet(object, item_index);
                    self.propertyStorage(index)[self.cells[index].property_count] = .{
                        .key = try self.storeString(name),
                        .value = current,
                        .writable = true,
                        .enumerable = true,
                        .configurable = true,
                    };
                    self.cells[index].property_count += 1;
                    self.itemStorage(index)[item_index] = .undefined;
                    self.setArrayItemPresent(index, item_index, false);
                    self.clearArgumentMapping(index, item_index);
                }
                self.cells[index].array_length = @max(self.cells[index].array_length, item_index + 1);
            }
        }

        var cell = &self.cells[index];
        var property_index: ?usize = null;
        for (self.propertyStorageConst(index)[0..cell.property_count], 0..) |property, candidate| {
            if (equals(self.stringBytes(property.key), name)) {
                property_index = candidate;
                break;
            }
        }
        const existing_accessor = self.findAccessorMutable(index, name);
        const exists = property_index != null or existing_accessor != null;
        if (!exists and !cell.extensible) return error.TypeError;
        if (exists) {
            const current_enumerable = if (existing_accessor) |accessor| accessor.enumerable else self.propertyStorageConst(index)[property_index.?].enumerable;
            const current_configurable = if (existing_accessor) |accessor| accessor.configurable else self.propertyStorageConst(index)[property_index.?].configurable;
            if (!current_configurable) {
                if (configurable or (has_enumerable and enumerable != current_enumerable)) return error.TypeError;
                if ((accessor_descriptor and existing_accessor == null) or (data_descriptor and existing_accessor != null)) return error.TypeError;
                if (existing_accessor) |accessor| {
                    if ((has_getter and !self.strictEqual(getter, accessor.getter)) or
                        (has_setter and !self.strictEqual(setter, accessor.setter))) return error.TypeError;
                } else {
                    const current = self.propertyStorageConst(index)[property_index.?];
                    if (!current.writable and ((has_writable and writable) or (has_value and !self.strictEqual(value, current.value)))) return error.TypeError;
                }
            }
        }

        if (!accessor_descriptor and !data_descriptor and exists) {
            if (existing_accessor) |accessor| {
                if (has_enumerable) accessor.enumerable = enumerable;
                if (has_configurable) accessor.configurable = configurable;
            } else {
                var property = &self.propertyStorage(index)[property_index.?];
                if (has_enumerable) property.enumerable = enumerable;
                if (has_configurable) property.configurable = configurable;
            }
            return;
        }

        if (accessor_descriptor) {
            if (property_index == null) {
                try self.ensurePropertyCapacity(index, cell.property_count + 1);
                self.propertyStorage(index)[cell.property_count] = .{
                    .key = try self.storeString(name),
                    .value = .undefined,
                    .writable = false,
                    .enumerable = enumerable,
                    .configurable = configurable,
                };
                property_index = cell.property_count;
                cell.property_count += 1;
            } else {
                var marker = &self.propertyStorage(index)[property_index.?];
                marker.value = .undefined;
                marker.writable = false;
                if (has_enumerable) marker.enumerable = enumerable;
                if (has_configurable) marker.configurable = configurable;
            }
            if (existing_accessor) |accessor| {
                if (has_getter) accessor.getter = getter;
                if (has_setter) accessor.setter = setter;
                if (has_enumerable) accessor.enumerable = enumerable;
                if (has_configurable) accessor.configurable = configurable;
                return;
            }
            const accessor = try self.allocateAccessor();
            accessor.* = .{
                .occupied = true,
                .owner = index,
                .key = try self.storeString(name),
                .getter = getter,
                .setter = setter,
                .enumerable = enumerable,
                .configurable = configurable,
            };
            return;
        }

        if (existing_accessor) |accessor| accessor.occupied = false;
        if (property_index) |existing_index| {
            var property = &self.propertyStorage(index)[existing_index];
            if (has_value) property.value = value;
            if (has_writable) property.writable = writable;
            if (has_enumerable) property.enumerable = enumerable;
            if (has_configurable) property.configurable = configurable;
            return;
        }
        try self.ensurePropertyCapacity(index, cell.property_count + 1);
        self.propertyStorage(index)[cell.property_count] = .{
            .key = try self.storeString(name),
            .value = value,
            .writable = writable,
            .enumerable = enumerable,
            .configurable = configurable,
        };
        cell.property_count += 1;
    }

    fn findAccessor(self: *const Runtime, owner: u16, name: []const u8) ?*const Accessor {
        for (self.accessorStorageConst()) |*accessor| {
            if (accessor.occupied and accessor.owner == owner and equals(self.stringBytes(accessor.key), name)) return accessor;
        }
        return null;
    }

    fn findAccessorMutable(self: *Runtime, owner: u16, name: []const u8) ?*Accessor {
        for (self.accessorStorage()) |*accessor| {
            if (accessor.occupied and accessor.owner == owner and equals(self.stringBytes(accessor.key), name)) return accessor;
        }
        return null;
    }

    fn hasProperty(self: *Runtime, object: Value, name: []const u8) Error!bool {
        switch (object) {
            .string => |ref| {
                if (self.symbolParts(ref) != null)
                    return self.symbol_prototype != none and try self.hasProperty(.{ .cell = self.symbol_prototype }, name);
                if (equals(name, "length")) return true;
                if (parseArrayIndex(name)) |index| return index < runtimeStringUnitCount(self.stringBytes(ref));
                return self.string_prototype != none and try self.hasProperty(.{ .cell = self.string_prototype }, name);
            },
            .number, .boolean => return equals(name, "toString") or equals(name, "valueOf"),
            .cell => |index| {
                if (index >= self.cells.len or !self.cells[index].occupied) {
                    self.diagnostic_site = .has_property;
                    self.diagnostic_value = object;
                    return error.NotObject;
                }
                const cell = &self.cells[index];
                if (cell.kind == .proxy) return self.proxyHas(object, name);
                if (self.isTypedArray(object)) switch (typedArrayPropertyIndex(name)) {
                    .index => |item_index| return item_index < self.typedArrayLengthOrZero(index),
                    .invalid_numeric => return false,
                    .ordinary => {},
                };
                if (cell.kind == .array) {
                    if (equals(name, "length")) return true;
                    if (parseArrayIndex(name)) |item_index| {
                        if (self.arrayItemPresent(index, item_index)) return true;
                        if (self.findAccessor(index, name) != null) return true;
                        for (self.propertyStorageConst(index)[0..cell.property_count]) |property|
                            if (equals(self.stringBytes(property.key), name)) return true;
                        if (cell.prototype != none) return self.hasProperty(.{ .cell = cell.prototype }, name);
                        return false;
                    }
                }
                for (self.propertyStorageConst(index)[0..cell.property_count]) |property| {
                    if (equals(self.stringBytes(property.key), name)) return true;
                }
                if (cell.host_property_get) |getter| return (try getter(self, cell.host_context, cell.host_tag, object, name)) != null;
                if (cell.prototype != none) return self.hasProperty(.{ .cell = cell.prototype }, name);
                return false;
            },
            else => {
                self.diagnostic_site = .has_property;
                self.diagnostic_value = object;
                return error.NotObject;
            },
        }
    }

    fn hasOwnProperty(self: *Runtime, object: Value, name: []const u8) Error!bool {
        switch (object) {
            .string => |ref| {
                if (self.symbolParts(ref) != null) return false;
                if (equals(name, "length")) return true;
                return if (parseArrayIndex(name)) |index| index < runtimeStringUnitCount(self.stringBytes(ref)) else false;
            },
            .cell => |index| {
                if (index >= self.cells.len or !self.cells[index].occupied) {
                    self.diagnostic_site = .has_own_property;
                    self.diagnostic_value = object;
                    return error.NotObject;
                }
                const cell = &self.cells[index];
                if (cell.kind == .proxy) return (try self.proxyGetOwnDescriptor(object, name)) != .undefined;
                if (self.isTypedArray(object)) switch (typedArrayPropertyIndex(name)) {
                    .index => |item_index| return item_index < self.typedArrayLengthOrZero(index),
                    .invalid_numeric => return false,
                    .ordinary => {},
                };
                if (cell.kind == .array) {
                    if (equals(name, "length")) return true;
                    if (parseArrayIndex(name)) |item_index| {
                        if (self.arrayItemPresent(index, item_index) or self.findAccessor(index, name) != null) return true;
                        for (self.propertyStorageConst(index)[0..cell.property_count]) |property|
                            if (equals(self.stringBytes(property.key), name)) return true;
                        return false;
                    }
                }
                for (self.propertyStorageConst(index)[0..cell.property_count]) |property| {
                    if (equals(self.stringBytes(property.key), name)) return true;
                }
                return false;
            },
            else => {
                self.diagnostic_site = .has_own_property;
                self.diagnostic_value = object;
                return error.NotObject;
            },
        }
    }

    fn instanceOfValue(self: *Runtime, value: Value, constructor: Value) Error!bool {
        _ = try self.expectObject(constructor);
        if (self.symbol_has_instance.len != 0) {
            const method = try self.getProperty(constructor, self.stringBytes(self.symbol_has_instance));
            if (method != .undefined and method != .null_value) {
                if (!self.isCallableValue(method)) return error.TypeError;
                const program = self.diagnostic_program orelse return error.TypeError;
                return self.truthy(try self.call(program, method, constructor, &.{value}, false));
            }
        }
        if (!self.isCallableValue(constructor)) return error.TypeError;
        return self.instanceOf(value, constructor);
    }

    fn instanceOf(self: *Runtime, value: Value, constructor: Value) Error!bool {
        const value_index = switch (value) {
            .cell => |index| index,
            else => return false,
        };
        const constructor_index = switch (constructor) {
            .cell => |index| index,
            else => return false,
        };
        if (value_index >= self.cells.len or constructor_index >= self.cells.len or
            !self.cells[value_index].occupied or !self.cells[constructor_index].occupied)
        {
            return false;
        }
        const constructor_cell = &self.cells[constructor_index];
        if (constructor_cell.kind == .bound_function) return self.instanceOf(value, constructor_cell.promise_value);
        if (constructor_cell.kind == .proxy) {
            if (!self.isCallableValue(constructor)) return false;
            const prototype = try self.getProperty(constructor, "prototype");
            if (prototype != .cell) return error.TypeError;
            var current = try self.getPrototypeInternal(value);
            var depth: usize = 0;
            while (current == .cell and depth < max_call_depth) : (depth += 1) {
                if (current.cell == prototype.cell) return true;
                current = try self.getPrototypeInternal(current);
            }
            return false;
        }
        if (self.cells[value_index].kind == .proxy) {
            const prototype = try self.getProperty(constructor, "prototype");
            if (prototype != .cell) return error.TypeError;
            var current = try self.getPrototypeInternal(value);
            var depth: usize = 0;
            while (current == .cell and depth < max_call_depth) : (depth += 1) {
                if (current.cell == prototype.cell) return true;
                current = try self.getPrototypeInternal(current);
            }
            return false;
        }
        if (constructor_cell.kind == .native_function) return switch (constructor_cell.native_id) {
            .object_constructor => self.cells[value_index].kind != .environment,
            .function_constructor => switch (self.cells[value_index].kind) {
                .function, .bound_function, .native_function, .host_function, .proxy => self.isCallableValue(value),
                else => false,
            },
            .array_constructor => self.cells[value_index].kind == .array,
            .map_constructor => self.cells[value_index].host_tag == map_tag,
            .set_constructor => self.cells[value_index].host_tag == set_tag,
            .weak_map_constructor => self.cells[value_index].host_tag == weak_map_tag,
            .weak_set_constructor => self.cells[value_index].host_tag == weak_set_tag,
            .date_constructor => self.cells[value_index].host_tag == date_tag,
            .array_buffer_constructor => self.cells[value_index].host_tag == array_buffer_tag,
            .shared_array_buffer_constructor => self.cells[value_index].host_tag == shared_array_buffer_tag,
            .data_view_constructor => self.cells[value_index].host_tag == data_view_tag,
            .typed_array_constructor => if (typedArrayTypeMarker(constructor_cell.receiver)) |element|
                self.typedArrayElement(value) == element
            else |_|
                self.isTypedArray(value) and self.prototypeChainContains(value_index, self.typed_array_prototype),
            .iterator_constructor => self.prototypeChainContains(value_index, self.iterator_prototype),
            .promise_constructor => self.cells[value_index].kind == .promise,
            .error_constructor, .aggregate_error_constructor => blk: {
                var prototype = none;
                for (self.propertyStorageConst(constructor_index)[0..constructor_cell.property_count]) |property| {
                    if (!equals(self.stringBytes(property.key), "prototype") or property.value != .cell) continue;
                    prototype = property.value.cell;
                    break;
                }
                if (prototype == none) break :blk false;
                var current = self.cells[value_index].prototype;
                while (current != none) {
                    if (current == prototype) break :blk true;
                    if (current >= self.cells.len or !self.cells[current].occupied) break;
                    current = self.cells[current].prototype;
                }
                break :blk false;
            },
            .regex_constructor => blk: {
                break :blk self.cells[value_index].host_tag == regex_tag;
            },
            .boolean_constructor => self.cells[value_index].host_tag == boxed_boolean_tag,
            .number_constructor => self.cells[value_index].host_tag == boxed_number_tag,
            .string_constructor => self.cells[value_index].host_tag == boxed_string_tag,
            else => false,
        };
        if (constructor_cell.kind == .function or constructor_cell.kind == .host_function) {
            var prototype = none;
            for (self.propertyStorageConst(constructor_index)[0..constructor_cell.property_count]) |property| {
                if (!equals(self.stringBytes(property.key), "prototype") or property.value != .cell) continue;
                prototype = property.value.cell;
                break;
            }
            if (prototype == none) return false;
            var current = try self.getPrototypeInternal(value);
            while (current == .cell) {
                if (current.cell == prototype) return true;
                current = try self.getPrototypeInternal(current);
            }
        }
        return false;
    }

    fn prototypeChainContains(self: *const Runtime, value_index: u16, prototype: u16) bool {
        if (prototype == none or value_index >= self.cells.len or !self.cells[value_index].occupied) return false;
        var current = self.cells[value_index].prototype;
        var depth: usize = 0;
        while (current != none and depth < max_call_depth) : (depth += 1) {
            if (current == prototype) return true;
            if (current >= self.cells.len or !self.cells[current].occupied) return false;
            current = self.cells[current].prototype;
        }
        return false;
    }

    fn getProperty(self: *Runtime, object: Value, name: []const u8) Error!Value {
        return self.getPropertyFrom(object, name, object);
    }

    fn getPropertyFrom(self: *Runtime, object: Value, name: []const u8, receiver: Value) Error!Value {
        switch (object) {
            .string => |ref| {
                if (self.symbolParts(ref) != null) {
                    if (self.symbol_prototype != none)
                        return self.getPropertyFrom(.{ .cell = self.symbol_prototype }, name, receiver);
                    return .undefined;
                }
                const text = self.stringBytes(ref);
                if (equals(name, "length")) return .{ .number = @floatFromInt(runtimeStringUnitCount(text)) };
                if (parseArrayIndex(name)) |index| {
                    const unit = runtimeStringUnitAt(text, index) orelse return .undefined;
                    return .{ .string = try self.storeStringUnit(unit) };
                }
                if (self.string_prototype != none)
                    return self.getPropertyFrom(.{ .cell = self.string_prototype }, name, receiver);
                return .undefined;
            },
            .number => {
                if (self.number_prototype != none)
                    return self.getPropertyFrom(.{ .cell = self.number_prototype }, name, receiver);
                return .undefined;
            },
            .bigint => {
                if (self.bigint_prototype != none)
                    return self.getPropertyFrom(.{ .cell = self.bigint_prototype }, name, receiver);
                return .undefined;
            },
            .boolean => {
                if (self.boolean_prototype != none)
                    return self.getPropertyFrom(.{ .cell = self.boolean_prototype }, name, receiver);
                return .undefined;
            },
            .cell => |index| {
                if (index >= self.cells.len or !self.cells[index].occupied) {
                    self.diagnostic_site = .get_property;
                    self.diagnostic_value = object;
                    return error.NotObject;
                }
                const cell = &self.cells[index];
                if (cell.kind == .proxy) return self.proxyGet(object, name, receiver);
                if (cell.kind == .module_namespace) {
                    if (equals(name, self.stringBytes(self.symbol_to_string_tag)))
                        return .{ .string = try self.storeString("Module") };
                    if (self.moduleExportValue(cell.module, name, 0)) |value| return value;
                    return .undefined;
                }
                if (cell.host_property_get) |getter| {
                    if (try getter(self, cell.host_context, cell.host_tag, object, name)) |value| return value;
                }
                if (self.isTypedArray(object)) switch (typedArrayPropertyIndex(name)) {
                    .index => |item_index| return self.typedArrayRead(index, item_index) catch |err| switch (err) {
                        error.TypeError => .undefined,
                        else => return err,
                    },
                    .invalid_numeric => return .undefined,
                    .ordinary => {},
                };
                if (cell.kind == .array) {
                    if (equals(name, "length")) return .{ .number = @floatFromInt(@max(cell.array_length, cell.item_count)) };
                    if (parseArrayIndex(name)) |item_index| {
                        if (self.mappedArgumentName(index, item_index)) |mapped_name|
                            return self.lookup(cell.parent, mapped_name) orelse .undefined;
                        if (self.findAccessor(index, name)) |accessor| {
                            if (accessor.getter != .undefined) return self.callAccessor(accessor.getter, receiver, &.{});
                            return .undefined;
                        }
                        for (self.propertyStorageConst(index)[0..cell.property_count]) |property|
                            if (equals(self.stringBytes(property.key), name)) return property.value;
                        if (self.arrayItemPresent(index, item_index)) return self.itemStorageConst(index)[item_index];
                        if (cell.prototype != none) return self.getPropertyFrom(.{ .cell = cell.prototype }, name, receiver);
                        return .undefined;
                    }
                }
                if (cell.kind == .generator) {
                    if (equals(name, "next")) return self.sharedNative(.generator_next);
                    if (equals(name, "return")) return self.sharedNative(.generator_return);
                    if (equals(name, "throw")) return self.sharedNative(.generator_throw);
                    const state: *GeneratorFiberState = @ptrCast(@alignCast(cell.host_context orelse return error.TypeError));
                    if (!state.async_generator and equals(name, self.stringBytes(self.symbol_iterator)))
                        return self.sharedNative(.generator_iterator);
                    if (state.async_generator and equals(name, self.stringBytes(self.symbol_async_iterator)))
                        return self.sharedNative(.generator_iterator);
                }
                if (cell.kind == .function or cell.kind == .bound_function or cell.kind == .native_function or cell.kind == .host_function) {
                    if (equals(name, "call")) return self.sharedNative(.function_call);
                    if (equals(name, "apply")) return self.sharedNative(.function_apply);
                    if (equals(name, "bind")) return self.sharedNative(.function_bind);
                }
                if (self.findAccessor(index, name)) |accessor| {
                    if (accessor.getter != .undefined) return self.callAccessor(accessor.getter, receiver, &.{});
                    return .undefined;
                }
                for (self.propertyStorageConst(index)[0..cell.property_count]) |property| {
                    if (!equals(self.stringBytes(property.key), name)) continue;
                    return property.value;
                }
                if (cell.kind == .function and equals(name, "prototype")) {
                    if (cell.program_ref) |function_program| {
                        if (cell.node != none and cell.node < function_program.node_count) {
                            const flags = function_program.nodes[cell.node].flags;
                            if (flags & flag_arrow != 0 or
                                flags & flag_method != 0 and flags & flag_generator == 0 or
                                flags & flag_async != 0 and flags & flag_generator == 0) return .undefined;
                        }
                    }
                    const prototype = Value{ .cell = try self.allocateCell(.object) };
                    if (cell.program_ref) |function_program| {
                        if (cell.node != none and cell.node < function_program.node_count) {
                            const flags = function_program.nodes[cell.node].flags;
                            if (flags & flag_generator != 0 and flags & flag_async == 0 and self.iterator_prototype != none)
                                self.cells[prototype.cell].prototype = self.iterator_prototype;
                        }
                    }
                    try self.setProperty(prototype, "constructor", object);
                    try self.setProperty(object, "prototype", prototype);
                    return prototype;
                }
                if (cell.prototype != none) {
                    return self.getPropertyFrom(.{ .cell = cell.prototype }, name, receiver);
                }
                return .undefined;
            },
            else => {
                self.diagnostic_site = .get_property;
                self.diagnostic_value = object;
                return error.NotObject;
            },
        }
    }

    fn expectObject(self: *Runtime, value: Value) Error!u16 {
        const index = switch (value) {
            .cell => |cell| cell,
            else => {
                self.diagnostic_site = .expect_object;
                self.diagnostic_value = value;
                return error.NotObject;
            },
        };
        if (index >= self.cells.len or !self.cells[index].occupied) {
            self.diagnostic_site = .expect_object;
            self.diagnostic_value = value;
            return error.NotObject;
        }
        return switch (self.cells[index].kind) {
            .object, .array, .function, .bound_function, .native_function, .host_function, .promise, .generator, .array_iterator, .string_iterator, .module_namespace, .proxy => index,
            else => blk: {
                self.diagnostic_site = .expect_object;
                self.diagnostic_value = value;
                break :blk error.NotObject;
            },
        };
    }

    fn expectCellKind(self: *Runtime, value: Value, kind: CellKind) Error!u16 {
        const index = switch (value) {
            .cell => |cell| cell,
            else => return error.TypeError,
        };
        if (index >= self.cells.len or !self.cells[index].occupied or self.cells[index].kind != kind) return error.TypeError;
        if (kind == .array) try self.syncMappedArguments(index);
        return index;
    }

    fn isCellKind(self: *const Runtime, value: Value, kind: CellKind) bool {
        return switch (value) {
            .cell => |index| index < self.cells.len and self.cells[index].occupied and self.cells[index].kind == kind,
            else => false,
        };
    }

    fn isArrayValue(self: *Runtime, value: Value) Error!bool {
        if (value != .cell or value.cell >= self.cells.len or !self.cells[value.cell].occupied) return false;
        if (self.cells[value.cell].kind == .array) return true;
        if (self.cells[value.cell].kind != .proxy) return false;
        return self.isArrayValue((try self.proxyParts(value)).target);
    }

    fn addValues(self: *Runtime, left: Value, right: Value) Error!Value {
        if (left == .number and right == .number) return .{ .number = left.number + right.number };
        const left_primitive = try self.toPrimitive(left, .default);
        const right_primitive = try self.toPrimitive(right, .default);
        if (left_primitive == .string or right_primitive == .string) {
            const left_text = self.stringBytes(try self.toString(left_primitive));
            const right_text = self.stringBytes(try self.toString(right_primitive));
            var buffer: [max_source_bytes]u8 = undefined;
            var length: usize = 0;
            try appendBytes(buffer[0..], &length, left_text);
            try appendBytes(buffer[0..], &length, right_text);
            return .{ .string = try self.storeString(buffer[0..length]) };
        }
        if (left_primitive == .bigint or right_primitive == .bigint) {
            if (left_primitive != .bigint or right_primitive != .bigint) return error.TypeError;
            return self.bigIntBinary(.add, left_primitive, right_primitive);
        }
        return .{ .number = (try self.toNumber(left_primitive)) + (try self.toNumber(right_primitive)) };
    }

    fn numericBinary(self: *Runtime, operation: BinaryOp, left: Value, right: Value) Error!Value {
        if (left == .number and right == .number) return numberBinaryValue(operation, left.number, right.number);
        const left_numeric = try self.toPrimitive(left, .number);
        const right_numeric = try self.toPrimitive(right, .number);
        if (left_numeric == .bigint or right_numeric == .bigint) {
            if (left_numeric != .bigint or right_numeric != .bigint) return error.TypeError;
            return self.bigIntBinary(operation, left_numeric, right_numeric);
        }
        const a = try self.toNumber(left_numeric);
        const b = try self.toNumber(right_numeric);
        return switch (operation) {
            .subtract => .{ .number = a - b },
            .multiply => .{ .number = a * b },
            .divide => .{ .number = a / b },
            .remainder => .{ .number = @rem(a, b) },
            .exponentiate => .{ .number = std.math.pow(f64, a, b) },
            .bitwise_and => .{ .number = @floatFromInt(toInt32(a) & toInt32(b)) },
            .bitwise_xor => .{ .number = @floatFromInt(toInt32(a) ^ toInt32(b)) },
            .bitwise_or => .{ .number = @floatFromInt(toInt32(a) | toInt32(b)) },
            .shift_left => .{ .number = @floatFromInt(toInt32(a) << @intCast(toUint32(b) & 31)) },
            .shift_right => .{ .number = @floatFromInt(toInt32(a) >> @intCast(toUint32(b) & 31)) },
            .shift_unsigned => .{ .number = @floatFromInt(toUint32(a) >> @intCast(toUint32(b) & 31)) },
            else => error.TypeError,
        };
    }

    fn compareRuntimeStrings(self: *const Runtime, left: StringRef, right: StringRef) std.math.Order {
        const left_bytes = self.stringBytes(left);
        const right_bytes = self.stringBytes(right);
        const left_count = runtimeStringUnitCount(left_bytes);
        const right_count = runtimeStringUnitCount(right_bytes);
        var index: usize = 0;
        while (index < @min(left_count, right_count)) : (index += 1) {
            const a = runtimeStringUnitAt(left_bytes, index).?;
            const b = runtimeStringUnitAt(right_bytes, index).?;
            if (a < b) return .lt;
            if (a > b) return .gt;
        }
        return std.math.order(left_count, right_count);
    }

    fn relationalCompare(self: *Runtime, left: Value, right: Value) Error!?std.math.Order {
        const a = try self.toPrimitive(left, .number);
        const b = try self.toPrimitive(right, .number);
        if (a == .string and b == .string and !self.isSymbolValue(a) and !self.isSymbolValue(b))
            return self.compareRuntimeStrings(a.string, b.string);
        if (self.isSymbolValue(a) or self.isSymbolValue(b)) return error.TypeError;
        if (a == .bigint) {
            if (b == .string) {
                const parsed = self.createBigIntFromString(self.stringBytes(b.string)) catch |err| switch (err) {
                    error.SyntaxError => return null,
                    else => return err,
                };
                return BigIntCore.Const.order(try self.bigIntConst(a), try self.bigIntConst(parsed));
            }
            return self.compareBigIntAndNumber(a, try self.toNumber(b));
        }
        if (b == .bigint) {
            if (a == .string) {
                const parsed = self.createBigIntFromString(self.stringBytes(a.string)) catch |err| switch (err) {
                    error.SyntaxError => return null,
                    else => return err,
                };
                return BigIntCore.Const.order(try self.bigIntConst(parsed), try self.bigIntConst(b));
            }
            const reverse = try self.compareBigIntAndNumber(b, try self.toNumber(a)) orelse return null;
            return switch (reverse) {
                .lt => .gt,
                .eq => .eq,
                .gt => .lt,
            };
        }
        const a_number = try self.toNumber(a);
        const b_number = try self.toNumber(b);
        if (std.math.isNan(a_number) or std.math.isNan(b_number)) return null;
        return std.math.order(a_number, b_number);
    }

    fn toNumber(self: *Runtime, value: Value) Error!f64 {
        return switch (value) {
            .undefined => std.math.nan(f64),
            .null_value => 0,
            .boolean => |boolean| if (boolean) 1 else 0,
            .number => |number| number,
            .bigint => return error.TypeError,
            .string => |ref| if (self.symbolParts(ref) != null) return error.TypeError else ecmaStringToNumber(trimNumberWhitespace(self.stringBytes(ref))),
            .cell => self.toNumber(try self.toPrimitive(value, .number)),
        };
    }

    fn numberFromString(self: *const Runtime, ref: StringRef) f64 {
        return ecmaStringToNumber(trimNumberWhitespace(self.stringBytes(ref)));
    }

    fn toString(self: *Runtime, value: Value) Error!StringRef {
        return switch (value) {
            .undefined => self.storeString("undefined"),
            .null_value => self.storeString("null"),
            .boolean => |boolean| self.storeString(if (boolean) "true" else "false"),
            .number => |number| self.formatDefaultNumber(number),
            .bigint => self.bigIntToStringRef(value, 10),
            .string => |ref| if (self.symbolParts(ref) != null) return error.TypeError else ref,
            .cell => self.toString(try self.toPrimitive(value, .string)),
        };
    }

    fn toPropertyKey(self: *Runtime, value: Value) Error!StringRef {
        if (self.isSymbolValue(value)) return value.string;
        return self.toString(value);
    }

    fn toPrimitive(self: *Runtime, value: Value, hint: PrimitiveHint) Error!Value {
        const index = switch (value) {
            .cell => |cell| cell,
            else => return value,
        };
        if (index >= self.cells.len or !self.cells[index].occupied) return error.NotObject;
        if (self.symbol_to_primitive.len != 0) {
            const exotic = try self.getProperty(value, self.stringBytes(self.symbol_to_primitive));
            if (exotic != .undefined) {
                if (!self.isCallableValue(exotic)) return error.TypeError;
                const program = self.diagnostic_program orelse return error.TypeError;
                const hint_value: Value = .{ .string = try self.storeString(switch (hint) {
                    .default => "default",
                    .number => "number",
                    .string => "string",
                }) };
                const result = try self.call(program, exotic, value, &.{hint_value}, false);
                if (result == .cell) return error.TypeError;
                return result;
            }
        }
        if (self.cells[index].kind == .array) return .{ .string = try self.arrayToString(index, 0) };
        if (self.cells[index].kind == .function) {
            const function = &self.cells[index];
            if (function.program_ref) |function_program| {
                if (function.node < function_program.node_count) {
                    const source = function_program.nodes[function.node].source.bytes(function_program.source[0..function_program.source_len]);
                    if (source.len > 0) return .{ .string = try self.storeString(source) };
                }
            }
            return .{ .string = try self.storeString("function(){}") };
        }
        if (switch (self.cells[index].kind) {
            .bound_function, .native_function, .host_function => true,
            else => false,
        }) return .{ .string = try self.storeString("function () { [native code] }") };

        const program = self.diagnostic_program orelse return .{ .string = try self.storeString("[object Object]") };
        const root_base = self.root_count;
        defer self.root_count = root_base;
        try self.pushRoot(value);
        const prefer_string = hint == .string;
        const first = if (prefer_string) "toString" else "valueOf";
        const second = if (prefer_string) "valueOf" else "toString";
        for ([_][]const u8{ first, second }) |name| {
            const method = try self.getProperty(value, name);
            if (!self.isCallableValue(method)) continue;
            try self.pushRoot(method);
            const result = try self.call(program, method, value, &.{}, false);
            if (result != .cell) return result;
        }
        return error.TypeError;
    }

    fn isCallableValue(self: *const Runtime, value: Value) bool {
        const index = switch (value) {
            .cell => |cell| cell,
            else => return false,
        };
        if (index >= self.cells.len or !self.cells[index].occupied) return false;
        return switch (self.cells[index].kind) {
            .function, .bound_function, .native_function, .host_function => true,
            .proxy => self.cells[index].object_environment,
            else => false,
        };
    }

    fn arrayToString(self: *Runtime, index: u16, depth: usize) Error!StringRef {
        if (depth >= 8) return self.storeString("");
        try self.syncMappedArguments(index);
        var buffer: [4096]u8 = undefined;
        var length: usize = 0;
        const array_length = self.effectiveArrayLength(index);
        var item_index: usize = 0;
        while (item_index < array_length) : (item_index += 1) {
            if (item_index > 0) try appendBytes(buffer[0..], &length, ",");
            if (item_index >= self.cells[index].item_count) continue;
            const item = self.itemStorageConst(index)[item_index];
            if (item.isNullish()) continue;
            const text = if (item == .cell and self.cells[item.cell].kind == .array)
                (try self.arrayToString(item.cell, depth + 1)).bytes(self.strings[0..self.string_len])
            else
                (try self.toString(item)).bytes(self.strings[0..self.string_len]);
            try appendBytes(buffer[0..], &length, text);
        }
        return self.storeString(buffer[0..length]);
    }

    fn truthy(self: *const Runtime, value: Value) bool {
        return switch (value) {
            .undefined, .null_value => false,
            .boolean => |boolean| boolean,
            .number => |number| number != 0 and !std.math.isNan(number),
            .bigint => |index| !(self.bigIntConst(.{ .bigint = index }) catch return false).eqlZero(),
            .string => |ref| ref.len != 0,
            .cell => true,
        };
    }

    fn strictEqual(self: *const Runtime, left: Value, right: Value) bool {
        if (std.meta.activeTag(left) != std.meta.activeTag(right)) return false;
        return switch (left) {
            .undefined, .null_value => true,
            .boolean => |value| value == right.boolean,
            .number => |value| value == right.number,
            .bigint => |index| BigIntCore.Const.eql(self.bigIntConst(.{ .bigint = index }) catch return false, self.bigIntConst(right) catch return false),
            .string => |value| equals(self.stringBytes(value), self.stringBytes(right.string)),
            .cell => |value| value == right.cell,
        };
    }

    fn looseEqual(self: *Runtime, left: Value, right: Value) Error!bool {
        if (std.meta.activeTag(left) == std.meta.activeTag(right)) return self.strictEqual(left, right);
        if (left.isNullish() and right.isNullish()) return true;
        if (left.isNullish() or right.isNullish()) return false;
        if (left == .cell) return self.looseEqual(try self.toPrimitive(left, .default), right);
        if (right == .cell) return self.looseEqual(left, try self.toPrimitive(right, .default));
        if (self.isSymbolValue(left) or self.isSymbolValue(right)) return false;
        if (left == .bigint or right == .bigint) {
            const bigint = if (left == .bigint) left else right;
            const other = if (left == .bigint) right else left;
            if (other == .string) {
                const parsed = self.createBigIntFromString(self.stringBytes(other.string)) catch |err| switch (err) {
                    error.SyntaxError => return false,
                    else => return err,
                };
                return self.strictEqual(bigint, parsed);
            }
            if (other == .number) {
                const order = try self.compareBigIntAndNumber(bigint, other.number) orelse return false;
                return order == .eq;
            }
            if (other == .boolean) return self.looseEqual(bigint, .{ .number = if (other.boolean) 1 else 0 });
            return false;
        }
        return (try self.toNumber(left)) == (try self.toNumber(right));
    }

    fn typeName(self: *const Runtime, value: Value) []const u8 {
        return switch (value) {
            .undefined => "undefined",
            .null_value => "object",
            .boolean => "boolean",
            .number => "number",
            .bigint => "bigint",
            .string => |ref| if (self.symbolParts(ref) != null) "symbol" else "string",
            .cell => |index| if (self.isCallableValue(.{ .cell = index })) "function" else "object",
        };
    }

    fn decodeString(self: *Runtime, program: *const Program, ref: StringRef) Error!StringRef {
        return self.decodeStringMode(program, ref, false);
    }

    fn decodeTemplateString(self: *Runtime, program: *const Program, ref: StringRef) Error!StringRef {
        return self.decodeStringMode(program, ref, true);
    }

    fn decodeStringMode(self: *Runtime, program: *const Program, ref: StringRef, normalize_line_endings: bool) Error!StringRef {
        const source = program.text(ref);
        const buffer = self.string_scratch[0..];
        if (source.len > buffer.len) return error.StringLimit;
        var input: usize = 0;
        var output: usize = 0;
        while (input < source.len) {
            if (source[input] != '\\') {
                if (normalize_line_endings and source[input] == '\r') {
                    buffer[output] = '\n';
                    output += 1;
                    input += 1;
                    if (input < source.len and source[input] == '\n') input += 1;
                    continue;
                }
                buffer[output] = source[input];
                input += 1;
                output += 1;
                continue;
            }
            const escape_start = input;
            input += 1;
            if (input >= source.len) return error.SyntaxError;
            const escaped_codepoint = try decodeSourceCodePoint(source, input);
            if (isEcmaLineTerminator(escaped_codepoint.value)) {
                input = escaped_codepoint.end;
                if (escaped_codepoint.value == '\r' and input < source.len and source[input] == '\n') input += 1;
                continue;
            }
            const escaped = source[input];
            input += 1;
            if (escaped == 'x') {
                if (input + 2 > source.len) return error.SyntaxError;
                const high = hexDigit(source[input]) orelse return error.SyntaxError;
                const low = hexDigit(source[input + 1]) orelse return error.SyntaxError;
                buffer[output] = (high << 4) | low;
                input += 2;
                output += 1;
                continue;
            }
            if (escaped == 'u') {
                const unicode_escape = try scanStringUnicodeEscape(source, escape_start);
                var codepoint = unicode_escape.value;
                input = unicode_escape.end;
                if (codepoint >= 0xd800 and codepoint <= 0xdbff and input + 2 <= source.len and source[input] == '\\' and source[input + 1] == 'u') {
                    const low = scanStringUnicodeEscape(source, input) catch null;
                    if (low) |low_escape| {
                        if (low_escape.value >= 0xdc00 and low_escape.value <= 0xdfff) {
                            codepoint = 0x10000 + ((codepoint - 0xd800) << 10) + (low_escape.value - 0xdc00);
                            input = low_escape.end;
                        }
                    }
                }
                try appendUtf8CodePoint(buffer, &output, codepoint);
                continue;
            }
            if (escaped >= '0' and escaped <= '7') {
                var octal: u8 = escaped - '0';
                var remaining: usize = if (escaped <= '3') 2 else 1;
                while (remaining > 0 and input < source.len and source[input] >= '0' and source[input] <= '7') : (remaining -= 1) {
                    octal = octal * 8 + (source[input] - '0');
                    input += 1;
                }
                buffer[output] = octal;
                output += 1;
                continue;
            }
            buffer[output] = switch (escaped) {
                'n' => '\n',
                'r' => '\r',
                't' => '\t',
                'b' => 8,
                'f' => 12,
                'v' => 11,
                '0' => 0,
                '\\' => '\\',
                '\'' => '\'',
                '"' => '"',
                '`' => '`',
                else => escaped,
            };
            output += 1;
        }
        return self.storeString(buffer[0..output]);
    }

    fn storeTemplateRaw(self: *Runtime, source: []const u8) Error!StringRef {
        if (std.mem.indexOfScalar(u8, source, '\r') == null) return self.storeString(source);
        const buffer = self.string_scratch[0..];
        if (source.len > buffer.len) return error.StringLimit;
        var input: usize = 0;
        var output: usize = 0;
        while (input < source.len) {
            if (source[input] == '\r') {
                buffer[output] = '\n';
                output += 1;
                input += 1;
                if (input < source.len and source[input] == '\n') input += 1;
            } else {
                buffer[output] = source[input];
                output += 1;
                input += 1;
            }
        }
        return self.storeString(buffer[0..output]);
    }

    fn decodeSourceString(self: *Runtime, program: *const Program, ref: StringRef) Error![]const u8 {
        const decoded = try self.decodeString(program, ref);
        return self.stringBytes(decoded);
    }

    fn storeString(self: *Runtime, value: []const u8) Error!StringRef {
        var hash: u64 = 14695981039346656037;
        for (value) |byte| {
            hash ^= byte;
            hash *%= 1099511628211;
        }
        if (hash == 0) hash = 1;
        var probe: usize = 0;
        while (probe < self.interned_string_hashes.len) : (probe += 1) {
            const slot = (@as(usize, @truncate(hash)) + probe) % self.interned_string_hashes.len;
            if (self.interned_string_hashes[slot] == hash and equals(self.stringBytes(self.interned_string_refs[slot]), value)) {
                return self.interned_string_refs[slot];
            }
            if (self.interned_string_hashes[slot] != 0) continue;
            const alias_offset = self.stringAliasOffset(value);
            try self.ensureStringCapacity(value.len);
            const source = if (alias_offset) |offset| self.strings[offset .. offset + value.len] else value;
            const ref = StringRef{ .offset = @intCast(self.string_len), .len = @intCast(value.len) };
            if (value.len > 0) @memcpy(self.strings[self.string_len .. self.string_len + value.len], source);
            self.string_len += value.len;
            self.interned_string_hashes[slot] = hash;
            self.interned_string_refs[slot] = ref;
            return ref;
        }
        const alias_offset = self.stringAliasOffset(value);
        try self.ensureStringCapacity(value.len);
        const source = if (alias_offset) |offset| self.strings[offset .. offset + value.len] else value;
        const ref = StringRef{ .offset = @intCast(self.string_len), .len = @intCast(value.len) };
        if (value.len > 0) @memcpy(self.strings[self.string_len .. self.string_len + value.len], source);
        self.string_len += value.len;
        return ref;
    }

    fn stringAliasOffset(self: *const Runtime, value: []const u8) ?usize {
        if (value.len == 0 or self.string_capacity == 0) return null;
        const storage_start = @intFromPtr(self.strings);
        const value_start = @intFromPtr(value.ptr);
        if (value_start < storage_start or value_start > storage_start + self.string_len) return null;
        const offset = value_start - storage_start;
        if (value.len > self.string_len -| offset) return null;
        return offset;
    }

    fn ensureStringCapacity(self: *Runtime, additional: usize) Error!void {
        const required = std.math.add(usize, self.string_len, additional) catch return error.StringLimit;
        if (required <= self.string_capacity) return;
        if (required > max_strings) {
            self.diagnostic_limit_required = required;
            self.diagnostic_limit_available = max_strings;
            return error.StringLimit;
        }
        var capacity = @max(initial_string_bytes, self.string_capacity);
        while (capacity < required) capacity = @min(max_strings, capacity * 2);
        const replacement = self.program_allocator.allocate(self.program_allocator.context, capacity, @alignOf(u8)) orelse return error.ProgramAllocation;
        if (self.string_len > 0) @memcpy(replacement[0..self.string_len], self.strings[0..self.string_len]);
        if (self.string_capacity > 0)
            self.program_allocator.free(self.program_allocator.context, self.strings, self.string_capacity, @alignOf(u8));
        self.strings = replacement;
        self.string_capacity = capacity;
    }

    fn releaseStringStorage(self: *Runtime) void {
        if (self.string_capacity > 0)
            self.program_allocator.free(self.program_allocator.context, self.strings, self.string_capacity, @alignOf(u8));
        self.string_capacity = 0;
        self.string_len = 0;
    }

    fn stringBytes(self: *const Runtime, ref: StringRef) []const u8 {
        return ref.bytes(self.strings[0..self.string_len]);
    }

    fn checkpoint(self: *Runtime) Error!void {
        if (self.stop.requested != null) {
            if (self.stop_check_countdown == 0) {
                if (self.stop.isRequested()) return error.Cancelled;
                self.stop_check_countdown = @max(self.stop.check_interval, 1) - 1;
            } else {
                self.stop_check_countdown -= 1;
            }
        }
        if (self.stats.steps >= self.step_budget) return error.StepLimit;
        if (self.bytecode_frame_count > 0 and self.stats.allocations >= self.next_gc_allocation) self.collectGarbage();
        self.stats.steps += 1;
    }

    fn pushRoot(self: *Runtime, value: Value) Error!void {
        if (self.root_count >= self.roots.len) return error.RootLimit;
        self.roots[self.root_count] = value;
        self.root_count += 1;
    }

    fn popRoot(self: *Runtime) void {
        if (self.root_count > 0) self.root_count -= 1;
    }

    fn markValue(self: *Runtime, value: Value) void {
        switch (value) {
            .cell => |index| self.markCell(index),
            .bigint => |index| self.markCell(index),
            .string => |ref| self.markSymbolRef(ref),
            else => {},
        }
    }

    fn markSymbolRef(self: *Runtime, ref: StringRef) void {
        const id = self.symbolId(ref) orelse return;
        if (id >= max_gc_symbol_ids) return;
        const mask = @as(u64, 1) << @intCast(id % 64);
        if (self.gc_symbol_marks[id / 64] & mask != 0) return;
        self.gc_symbol_marks[id / 64] |= mask;
        self.gc_mark_progress += 1;
    }

    fn weakKeyMarked(self: *const Runtime, value: Value) bool {
        return switch (value) {
            .cell => |index| index < self.cells.len and self.cells[index].occupied and self.cells[index].marked,
            .string => |ref| if (self.symbolId(ref)) |id| id >= max_gc_symbol_ids or self.gc_symbol_marks[id / 64] & (@as(u64, 1) << @intCast(id % 64)) != 0 else false,
            else => false,
        };
    }

    fn markExecutionSnapshot(self: *Runtime, snapshot: *const ExecutionSnapshot) void {
        self.markCell(snapshot.active_env);
        self.markCell(snapshot.active_exports);
        if (snapshot.active_generator_state) |state| if (state.occupied) self.markCell(state.owner_cell);
        if (snapshot.active_async_state) |state| if (state.occupied) self.markCell(state.owner_promise);
        for (snapshot.call_environments[0..snapshot.call_depth]) |environment| self.markCell(environment);
        self.markValue(snapshot.pending_exception);
        self.markValue(snapshot.pending_generator_return);
        self.markValue(snapshot.diagnostic_value);
        for (snapshot.roots[0..snapshot.root_count]) |value| self.markValue(value);
        for (snapshot.bytecode_values[0..snapshot.bytecode_value_count]) |value| self.markValue(value);
        for (snapshot.bytecode_frames[0..snapshot.bytecode_frame_count]) |frame| {
            self.markCell(frame.environment);
            self.markValue(frame.last_value);
        }
    }

    fn markGeneratorState(self: *Runtime, raw_state: ?*anyopaque) void {
        const state: *GeneratorFiberState = @ptrCast(@alignCast(raw_state orelse return));
        if (!state.occupied) return;
        self.markCell(state.function_cell);
        self.markValue(state.receiver);
        for (state.arguments[0..state.argument_count]) |argument| self.markValue(argument);
        self.markValue(state.resume_value);
        self.markValue(state.result);
        self.markValue(state.await_value);
        var request_index: usize = 0;
        while (request_index < state.request_count) : (request_index += 1) {
            const request = state.requests[(state.request_head + request_index) % state.requests.len];
            self.markValue(request.value);
            self.markCell(request.promise);
        }
        self.markExecutionSnapshot(&state.generator_execution);
        self.markExecutionSnapshot(&state.caller_execution);
    }

    fn markAsyncState(self: *Runtime, raw_state: ?*anyopaque) void {
        const state: *AsyncFiberState = @ptrCast(@alignCast(raw_state orelse return));
        if (!state.occupied) return;
        self.markCell(state.owner_promise);
        self.markCell(state.function_cell);
        self.markValue(state.receiver);
        for (state.arguments[0..state.argument_count]) |argument| self.markValue(argument);
        self.markValue(state.resume_value);
        self.markValue(state.result);
        self.markExecutionSnapshot(&state.async_execution);
        self.markExecutionSnapshot(&state.caller_execution);
    }

    fn releaseAsyncState(self: *Runtime, cell: *Cell) void {
        const state: *AsyncFiberState = @ptrCast(@alignCast(cell.host_context orelse return));
        cell.host_context = null;
        if (!state.occupied) return;
        self.detachAsyncState(state);
    }

    fn releaseAsyncStates(self: *Runtime) void {
        var current = self.async_state_head;
        while (current) |state| {
            const next = state.next;
            state.occupied = false;
            if (state.owner_promise != none and state.owner_promise < self.cells.len and
                self.cells[state.owner_promise].host_context == @as(*anyopaque, @ptrCast(state)))
                self.cells[state.owner_promise].host_context = null;
            if (state.stack_memory) |stack| self.program_allocator.free(self.program_allocator.context, stack, fiber_stack_bytes, 16);
            self.program_allocator.free(
                self.program_allocator.context,
                @ptrCast(state),
                @sizeOf(AsyncFiberState),
                @alignOf(AsyncFiberState),
            );
            current = next;
        }
        self.async_state_head = null;
        self.active_async_state = null;
    }

    fn releaseGeneratorState(self: *Runtime, cell: *Cell) void {
        const state: *GeneratorFiberState = @ptrCast(@alignCast(cell.host_context orelse return));
        cell.host_context = null;
        if (!state.occupied) return;
        if (state.previous) |previous|
            previous.next = state.next
        else
            self.generator_state_head = state.next;
        if (state.next) |next| next.previous = state.previous;
        if (self.active_generator_state == state) self.active_generator_state = null;
        state.occupied = false;
        self.releaseGeneratorStack(state);
        self.program_allocator.free(
            self.program_allocator.context,
            @ptrCast(state),
            @sizeOf(GeneratorFiberState),
            @alignOf(GeneratorFiberState),
        );
    }

    fn releaseGeneratorStates(self: *Runtime) void {
        var current = self.generator_state_head;
        while (current) |state| {
            const next = state.next;
            state.occupied = false;
            self.releaseGeneratorStack(state);
            self.program_allocator.free(
                self.program_allocator.context,
                @ptrCast(state),
                @sizeOf(GeneratorFiberState),
                @alignOf(GeneratorFiberState),
            );
            current = next;
        }
        self.generator_state_head = null;
        self.active_generator_state = null;
    }

    fn markCell(self: *Runtime, index: u16) void {
        if (index == none or index >= self.cells.len) return;
        var cell = &self.cells[index];
        if (!cell.occupied or cell.marked) return;
        cell.marked = true;
        self.gc_mark_progress += 1;
        if (self.mark_queue_count < self.mark_queue.len) {
            self.mark_queue[self.mark_queue_count] = index;
            self.mark_queue_count += 1;
        }
    }

    fn countLiveCells(self: *const Runtime) usize {
        var count: usize = 0;
        for (&self.cells) |*cell| if (cell.occupied) {
            count += 1;
        };
        return count;
    }

    fn releaseModules(self: *Runtime) void {
        var index: usize = 0;
        while (index < self.module_count) : (index += 1) {
            const program = self.modules[index].program orelse continue;
            self.program_allocator.destroy(self.program_allocator.context, program);
            self.modules[index].program = null;
            self.modules[index].occupied = false;
        }
        self.module_count = 0;
    }

    fn releaseDynamicPrograms(self: *Runtime) void {
        var index: usize = 0;
        while (index < self.dynamic_program_count) : (index += 1) {
            const program = self.dynamic_programs[index] orelse continue;
            self.program_allocator.destroy(self.program_allocator.context, program);
            self.dynamic_programs[index] = null;
        }
        self.dynamic_program_count = 0;
    }

    fn validateModuleLinks(self: *Runtime) Error!void {
        for (self.modules[0..self.module_count]) |module| {
            if (!module.occupied or module.state != .evaluated) continue;
            if (module.environment == none or module.environment >= self.cells.len) return error.SyntaxError;
            const environment = &self.cells[module.environment];
            for (self.bindingStorageConst(module.environment)[0..environment.binding_count]) |binding| {
                if (binding.import_module == none) continue;
                if (!self.moduleResolvesExport(binding.import_module, self.stringBytes(binding.import_name), 0))
                    return error.SyntaxError;
            }
            for (module.export_entries[0..module.export_count]) |entry| switch (entry.kind) {
                .local, .ambiguous => {},
                .indirect => if (!self.moduleResolvesExport(entry.source_module, self.stringBytes(entry.local_name), 0))
                    return error.SyntaxError,
                .namespace => if (entry.source_module == none or entry.source_module >= self.module_count)
                    return error.SyntaxError,
            };
        }
    }

    fn moduleResolvesExport(self: *const Runtime, module_index: u16, name: []const u8, depth: usize) bool {
        if (module_index == none or module_index >= self.module_count or depth > max_modules * 2) return false;
        const module = &self.modules[module_index];
        for (module.export_entries[0..module.export_count]) |entry| {
            if (!equals(self.stringBytes(entry.name), name)) continue;
            return switch (entry.kind) {
                .local => module.environment != none and self.lookupOwnConst(module.environment, self.stringBytes(entry.local_name)),
                .indirect => self.moduleResolvesExport(entry.source_module, self.stringBytes(entry.local_name), depth + 1),
                .namespace => entry.source_module != none and entry.source_module < self.module_count,
                .ambiguous => false,
            };
        }
        return false;
    }

    fn lookupOwnConst(self: *const Runtime, environment: u16, name: []const u8) bool {
        if (environment == none or environment >= self.cells.len or !self.cells[environment].occupied) return false;
        for (self.bindingStorageConst(environment)[0..self.cells[environment].binding_count]) |binding|
            if (equals(self.stringBytes(binding.name), name)) return true;
        return false;
    }

    fn resolveModuleIndex(self: *const Runtime, referrer: u16, specifier: []const u8) ?usize {
        if (self.findModule(specifier)) |index| return index;
        if (referrer == none or referrer >= self.module_count or specifier.len == 0) return null;
        const relative = std.mem.startsWith(u8, specifier, "./") or std.mem.startsWith(u8, specifier, "../") or
            equals(specifier, ".") or equals(specifier, "..") or specifier[0] == '/';
        if (!relative) return null;
        const base = self.stringBytes(self.modules[referrer].name);
        var combined: [max_module_specifier_bytes]u8 = undefined;
        var combined_len: usize = 0;
        if (specifier[0] == '/') {
            if (moduleOriginEnd(base)) |origin_end| {
                if (origin_end + specifier.len > combined.len) return null;
                @memcpy(combined[0..origin_end], base[0..origin_end]);
                combined_len = origin_end;
            }
        } else {
            const directory_end = moduleDirectoryEnd(base);
            if (directory_end + specifier.len > combined.len) return null;
            if (directory_end > 0) @memcpy(combined[0..directory_end], base[0..directory_end]);
            combined_len = directory_end;
            if (moduleOriginEnd(base)) |origin_end| if (origin_end == base.len) {
                if (combined_len >= combined.len) return null;
                combined[combined_len] = '/';
                combined_len += 1;
            };
        }
        if (specifier.len > combined.len - combined_len) return null;
        @memcpy(combined[combined_len .. combined_len + specifier.len], specifier);
        combined_len += specifier.len;
        var normalized: [max_module_specifier_bytes]u8 = undefined;
        const normalized_len = normalizeModuleSpecifier(combined[0..combined_len], normalized[0..]) orelse return null;
        return self.findModule(normalized[0..normalized_len]);
    }

    fn findModule(self: *const Runtime, name: []const u8) ?usize {
        for (self.modules[0..self.module_count], 0..) |module, index| {
            if (module.occupied and equals(module.name.bytes(self.strings[0..self.string_len]), name)) return index;
        }
        return null;
    }
};

fn moduleOriginEnd(name: []const u8) ?usize {
    const scheme = std.mem.indexOf(u8, name, "://") orelse return null;
    const authority_start = scheme + 3;
    const path = std.mem.indexOfScalar(u8, name[authority_start..], '/') orelse return name.len;
    return authority_start + path;
}

fn moduleDirectoryEnd(name: []const u8) usize {
    if (moduleOriginEnd(name)) |origin_end| {
        if (origin_end == name.len) return name.len;
        const slash = std.mem.lastIndexOfScalar(u8, name[origin_end..], '/') orelse return origin_end + 1;
        return origin_end + slash + 1;
    }
    return if (std.mem.lastIndexOfScalar(u8, name, '/')) |slash| slash + 1 else 0;
}

fn normalizeModuleSpecifier(source: []const u8, output: []u8) ?usize {
    const origin_end = moduleOriginEnd(source) orelse 0;
    if (origin_end > output.len) return null;
    if (origin_end > 0) @memcpy(output[0..origin_end], source[0..origin_end]);
    var output_len = origin_end;
    var cursor = origin_end;
    const absolute = cursor < source.len and source[cursor] == '/';
    while (cursor < source.len and source[cursor] == '/') cursor += 1;
    var segment_positions: [256]usize = undefined;
    var segment_count: usize = 0;
    while (cursor <= source.len) {
        const end = if (cursor < source.len)
            (std.mem.indexOfScalar(u8, source[cursor..], '/') orelse source.len - cursor) + cursor
        else
            source.len;
        const segment = source[cursor..end];
        if (segment.len != 0 and !equals(segment, ".")) {
            if (equals(segment, "..") and segment_count > 0) {
                segment_count -= 1;
                output_len = segment_positions[segment_count];
            } else if (!equals(segment, "..") or !absolute) {
                if (segment_count >= segment_positions.len) return null;
                const restore = output_len;
                if ((origin_end > 0 or absolute or output_len > 0) and (output_len == 0 or output[output_len - 1] != '/')) {
                    if (output_len >= output.len) return null;
                    output[output_len] = '/';
                    output_len += 1;
                }
                if (segment.len > output.len - output_len) return null;
                segment_positions[segment_count] = restore;
                segment_count += 1;
                @memcpy(output[output_len .. output_len + segment.len], segment);
                output_len += segment.len;
            }
        }
        if (end == source.len) break;
        cursor = end + 1;
        while (cursor < source.len and source[cursor] == '/') cursor += 1;
    }
    return output_len;
}

const JsonParser = struct {
    runtime: *Runtime,
    source: []const u8,
    cursor: usize = 0,
    depth: usize = 0,
    records: []JsonSourceRecord = &.{},
    record_count: usize = 0,
    root_start: usize = 0,
    root_end: usize = 0,

    fn parse(self: *JsonParser) Error!Value {
        self.skipWhitespace();
        self.root_start = self.cursor;
        const value = try self.parseValue();
        self.root_end = self.cursor;
        self.skipWhitespace();
        if (self.cursor != self.source.len) return error.SyntaxError;
        return value;
    }

    fn parseValue(self: *JsonParser) Error!Value {
        self.skipWhitespace();
        if (self.cursor >= self.source.len) return error.SyntaxError;
        return switch (self.source[self.cursor]) {
            'n' => self.parseLiteral("null", .null_value),
            't' => self.parseLiteral("true", .{ .boolean = true }),
            'f' => self.parseLiteral("false", .{ .boolean = false }),
            '"' => .{ .string = try self.parseString() },
            '[' => self.parseArray(),
            '{' => self.parseObject(),
            '-', '0'...'9' => self.parseNumber(),
            else => error.SyntaxError,
        };
    }

    fn parseLiteral(self: *JsonParser, text: []const u8, value: Value) Error!Value {
        if (self.source.len - self.cursor < text.len or !equals(self.source[self.cursor .. self.cursor + text.len], text))
            return error.SyntaxError;
        self.cursor += text.len;
        return value;
    }

    fn parseArray(self: *JsonParser) Error!Value {
        if (self.depth >= 64) return error.RangeError;
        self.depth += 1;
        defer self.depth -= 1;
        self.cursor += 1;
        const array = Value{ .cell = try self.runtime.allocateCell(.array) };
        const root_base = self.runtime.root_count;
        defer self.runtime.root_count = root_base;
        try self.runtime.pushRoot(array);
        self.skipWhitespace();
        if (self.consume(']')) return array;
        while (true) {
            self.skipWhitespace();
            const source_start = self.cursor;
            const value = try self.parseValue();
            const source_end = self.cursor;
            try self.runtime.pushRoot(value);
            const index = self.runtime.cells[array.cell].item_count;
            try self.runtime.ensureItemCapacity(array.cell, index + 1);
            self.runtime.itemStorage(array.cell)[index] = value;
            self.runtime.setArrayItemPresent(array.cell, index, true);
            self.runtime.cells[array.cell].item_count += 1;
            self.runtime.cells[array.cell].array_length = self.runtime.cells[array.cell].item_count;
            if (value != .cell) {
                var key_buffer: [32]u8 = undefined;
                const key = std.fmt.bufPrint(key_buffer[0..], "{d}", .{index}) catch return error.StringLimit;
                try self.addSource(array.cell, key, value, source_start, source_end);
            }
            self.runtime.root_count = root_base + 1;
            self.skipWhitespace();
            if (self.consume(']')) break;
            if (!self.consume(',')) return error.SyntaxError;
            self.skipWhitespace();
        }
        return array;
    }

    fn parseObject(self: *JsonParser) Error!Value {
        if (self.depth >= 64) return error.RangeError;
        self.depth += 1;
        defer self.depth -= 1;
        self.cursor += 1;
        const object = Value{ .cell = try self.runtime.allocateCell(.object) };
        const root_base = self.runtime.root_count;
        defer self.runtime.root_count = root_base;
        try self.runtime.pushRoot(object);
        self.skipWhitespace();
        if (self.consume('}')) return object;
        while (true) {
            if (self.cursor >= self.source.len or self.source[self.cursor] != '"') return error.SyntaxError;
            const key = try self.parseString();
            self.skipWhitespace();
            if (!self.consume(':')) return error.SyntaxError;
            self.skipWhitespace();
            const source_start = self.cursor;
            const value = try self.parseValue();
            const source_end = self.cursor;
            try self.runtime.pushRoot(value);
            try self.runtime.defineOwnDataProperty(object, self.runtime.stringBytes(key), value);
            if (value != .cell)
                try self.addSource(object.cell, self.runtime.stringBytes(key), value, source_start, source_end);
            self.runtime.root_count = root_base + 1;
            self.skipWhitespace();
            if (self.consume('}')) break;
            if (!self.consume(',')) return error.SyntaxError;
            self.skipWhitespace();
        }
        return object;
    }

    fn parseNumber(self: *JsonParser) Error!Value {
        const start = self.cursor;
        if (self.consume('-') and (self.cursor >= self.source.len or !std.ascii.isDigit(self.source[self.cursor])))
            return error.SyntaxError;
        if (self.consume('0')) {
            if (self.cursor < self.source.len and std.ascii.isDigit(self.source[self.cursor])) return error.SyntaxError;
        } else {
            if (self.cursor >= self.source.len or self.source[self.cursor] < '1' or self.source[self.cursor] > '9') return error.SyntaxError;
            while (self.cursor < self.source.len and std.ascii.isDigit(self.source[self.cursor])) self.cursor += 1;
        }
        if (self.consume('.')) {
            const fraction_start = self.cursor;
            while (self.cursor < self.source.len and std.ascii.isDigit(self.source[self.cursor])) self.cursor += 1;
            if (self.cursor == fraction_start) return error.SyntaxError;
        }
        if (self.cursor < self.source.len and (self.source[self.cursor] == 'e' or self.source[self.cursor] == 'E')) {
            self.cursor += 1;
            if (self.cursor < self.source.len and (self.source[self.cursor] == '+' or self.source[self.cursor] == '-')) self.cursor += 1;
            const exponent_start = self.cursor;
            while (self.cursor < self.source.len and std.ascii.isDigit(self.source[self.cursor])) self.cursor += 1;
            if (self.cursor == exponent_start) return error.SyntaxError;
        }
        const number = std.fmt.parseFloat(f64, self.source[start..self.cursor]) catch return error.SyntaxError;
        return .{ .number = number };
    }

    fn parseString(self: *JsonParser) Error!StringRef {
        if (!self.consume('"')) return error.SyntaxError;
        var buffer: [max_source_bytes]u8 = undefined;
        var length: usize = 0;
        while (self.cursor < self.source.len) {
            const byte = self.source[self.cursor];
            self.cursor += 1;
            if (byte == '"') return self.runtime.storeString(buffer[0..length]);
            if (byte < 0x20) return error.SyntaxError;
            if (byte != '\\') {
                const sequence_length = std.unicode.utf8ByteSequenceLength(byte) catch return error.SyntaxError;
                const count: usize = sequence_length;
                const start = self.cursor - 1;
                if (start + count > self.source.len) return error.SyntaxError;
                _ = std.unicode.utf8Decode(self.source[start .. start + count]) catch return error.SyntaxError;
                try appendBytes(buffer[0..], &length, self.source[start .. start + count]);
                self.cursor = start + count;
                continue;
            }
            if (self.cursor >= self.source.len) return error.SyntaxError;
            const escape = self.source[self.cursor];
            self.cursor += 1;
            switch (escape) {
                '"', '\\', '/' => try appendBytes(buffer[0..], &length, &.{escape}),
                'b' => try appendBytes(buffer[0..], &length, &.{0x08}),
                'f' => try appendBytes(buffer[0..], &length, &.{0x0c}),
                'n' => try appendBytes(buffer[0..], &length, "\n"),
                'r' => try appendBytes(buffer[0..], &length, "\r"),
                't' => try appendBytes(buffer[0..], &length, "\t"),
                'u' => {
                    var codepoint = try self.parseHexCodeUnit();
                    if (codepoint >= 0xd800 and codepoint <= 0xdbff) {
                        if (self.cursor + 2 > self.source.len or self.source[self.cursor] != '\\' or self.source[self.cursor + 1] != 'u')
                            return error.SyntaxError;
                        self.cursor += 2;
                        const low = try self.parseHexCodeUnit();
                        if (low < 0xdc00 or low > 0xdfff) return error.SyntaxError;
                        codepoint = 0x10000 + ((codepoint - 0xd800) << 10) + (low - 0xdc00);
                    } else if (codepoint >= 0xdc00 and codepoint <= 0xdfff) {
                        return error.SyntaxError;
                    }
                    try appendUtf8CodePoint(buffer[0..], &length, codepoint);
                },
                else => return error.SyntaxError,
            }
        }
        return error.SyntaxError;
    }

    fn parseHexCodeUnit(self: *JsonParser) Error!u32 {
        if (self.cursor + 4 > self.source.len) return error.SyntaxError;
        var value: u32 = 0;
        for (self.source[self.cursor .. self.cursor + 4]) |byte| {
            value = (value << 4) | (hexDigit(byte) orelse return error.SyntaxError);
        }
        self.cursor += 4;
        return value;
    }

    fn addSource(self: *JsonParser, owner: u16, key: []const u8, value: Value, start: usize, end: usize) Error!void {
        if (self.records.len == 0) return;
        if (self.record_count >= self.records.len or end < start or end > self.source.len) return error.RangeError;
        self.records[self.record_count] = .{
            .owner = owner,
            .key = try self.runtime.storeString(key),
            .value = value,
            .source = try self.runtime.storeString(self.source[start..end]),
        };
        self.record_count += 1;
    }

    fn skipWhitespace(self: *JsonParser) void {
        while (self.cursor < self.source.len) : (self.cursor += 1) switch (self.source[self.cursor]) {
            ' ', '\t', '\r', '\n' => {},
            else => break,
        };
    }

    fn consume(self: *JsonParser, byte: u8) bool {
        if (self.cursor >= self.source.len or self.source[self.cursor] != byte) return false;
        self.cursor += 1;
        return true;
    }
};

const JsonSourceRecord = struct {
    owner: u16 = none,
    key: StringRef = .{},
    value: Value = .undefined,
    source: StringRef = .{},
};

const JsonStringifier = struct {
    runtime: *Runtime,
    program: *const Program,
    replacer: Value = .undefined,
    property_list: [max_properties]StringRef = undefined,
    property_count: usize = 0,
    gap: [40]u8 = undefined,
    gap_len: usize = 0,
    stack: [64]u16 = undefined,
    stack_count: usize = 0,
    output: [max_source_bytes]u8 = undefined,
    output_len: usize = 0,

    fn buildPropertyList(self: *JsonStringifier, array: u16) Error!void {
        const length = self.runtime.effectiveArrayLength(array);
        var index: usize = 0;
        while (index < length and self.property_count < self.property_list.len) : (index += 1) {
            if (index >= self.runtime.cells[array].item_count) continue;
            var item = self.runtime.itemStorageConst(array)[index];
            if (item == .cell) item = self.runtime.toPrimitive(item, .string) catch continue;
            if (item != .string and item != .number) continue;
            const key = try self.runtime.toString(item);
            var duplicate = false;
            for (self.property_list[0..self.property_count]) |existing| {
                if (equals(self.runtime.stringBytes(existing), self.runtime.stringBytes(key))) {
                    duplicate = true;
                    break;
                }
            }
            if (!duplicate) {
                self.property_list[self.property_count] = key;
                self.property_count += 1;
            }
        }
    }

    fn setGap(self: *JsonStringifier, raw_space: Value) Error!void {
        var space = raw_space;
        if (space == .cell) space = self.runtime.toPrimitive(space, .number) catch .undefined;
        if (space == .number) {
            if (std.math.isNan(space.number) or space.number <= 0) return;
            self.gap_len = @min(@as(usize, 10), @as(usize, @intFromFloat(@min(@floor(space.number), 10))));
            @memset(self.gap[0..self.gap_len], ' ');
        } else if (space == .string) {
            const bytes = self.runtime.stringBytes(space.string);
            var cursor: usize = 0;
            var elements: usize = 0;
            while (cursor < bytes.len and elements < 10) : (elements += 1) {
                const count: usize = std.unicode.utf8ByteSequenceLength(bytes[cursor]) catch 1;
                if (cursor + count > bytes.len or cursor + count > self.gap.len) break;
                cursor += count;
            }
            self.gap_len = cursor;
            if (cursor > 0) @memcpy(self.gap[0..cursor], bytes[0..cursor]);
        }
    }

    fn writeProperty(self: *JsonStringifier, holder: Value, key: []const u8, array_item: bool, depth: usize) Error!bool {
        const root_base = self.runtime.root_count;
        defer self.runtime.root_count = root_base;
        try self.runtime.pushRoot(holder);
        var value = try self.runtime.getProperty(holder, key);
        try self.runtime.pushRoot(value);
        if (value == .cell or value == .bigint) {
            const to_json = try self.runtime.getProperty(value, "toJSON");
            if (self.runtime.isCallableValue(to_json)) {
                const key_value = Value{ .string = try self.runtime.storeString(key) };
                value = try self.runtime.call(self.program, to_json, value, &.{key_value}, false);
                try self.runtime.pushRoot(value);
            }
        }
        if (self.replacer != .undefined) {
            const key_value = Value{ .string = try self.runtime.storeString(key) };
            value = try self.runtime.call(self.program, self.replacer, holder, &.{ key_value, value }, false);
            try self.runtime.pushRoot(value);
        }
        if (value == .cell and value.cell < self.runtime.cells.len and self.runtime.cells[value.cell].occupied and
            (self.runtime.cells[value.cell].host_tag == boxed_boolean_tag or self.runtime.cells[value.cell].host_tag == boxed_number_tag or self.runtime.cells[value.cell].host_tag == boxed_bigint_tag or self.runtime.cells[value.cell].host_tag == boxed_symbol_tag))
        {
            value = self.runtime.cells[value.cell].receiver;
        }
        const included = try self.writeValue(value, depth);
        if (!included and array_item) try self.append("null");
        return included or array_item;
    }

    fn writeValue(self: *JsonStringifier, value: Value, depth: usize) Error!bool {
        switch (value) {
            .undefined => return false,
            .null_value => try self.append("null"),
            .boolean => |boolean| try self.append(if (boolean) "true" else "false"),
            .number => |number| {
                if (!std.math.isFinite(number)) {
                    try self.append("null");
                } else if (number == 0) {
                    try self.append("0");
                } else {
                    var buffer: [64]u8 = undefined;
                    const text = std.fmt.bufPrint(buffer[0..], "{d}", .{number}) catch return error.StringLimit;
                    try self.append(text);
                }
            },
            .bigint => return error.TypeError,
            .string => |string| {
                if (self.runtime.symbolParts(string) != null) return false;
                try self.writeQuoted(self.runtime.stringBytes(string));
            },
            .cell => |index| {
                if (self.runtime.isRawJson(value)) {
                    const raw = try self.runtime.getProperty(value, "rawJSON");
                    if (raw != .string) return error.TypeError;
                    try self.append(self.runtime.stringBytes(raw.string));
                    return true;
                }
                if (self.runtime.isCallableValue(value)) return false;
                if (depth >= self.stack.len) return error.RangeError;
                for (self.stack[0..self.stack_count]) |ancestor| if (ancestor == index) return error.TypeError;
                self.stack[self.stack_count] = index;
                self.stack_count += 1;
                defer self.stack_count -= 1;
                if (self.runtime.cells[index].kind == .array)
                    try self.writeArray(value, depth)
                else
                    try self.writeObject(value, depth);
            },
        }
        return true;
    }

    fn writeArray(self: *JsonStringifier, array: Value, depth: usize) Error!void {
        try self.append("[");
        const length = self.runtime.effectiveArrayLength(array.cell);
        var index: usize = 0;
        while (index < length) : (index += 1) {
            if (index > 0) try self.append(",");
            if (self.gap_len > 0) {
                try self.append("\n");
                try self.writeIndent(depth + 1);
            }
            var key_buffer: [32]u8 = undefined;
            const key = std.fmt.bufPrint(key_buffer[0..], "{d}", .{index}) catch return error.StringLimit;
            _ = try self.writeProperty(array, key, true, depth + 1);
        }
        if (length > 0 and self.gap_len > 0) {
            try self.append("\n");
            try self.writeIndent(depth);
        }
        try self.append("]");
    }

    fn writeObject(self: *JsonStringifier, object: Value, depth: usize) Error!void {
        try self.append("{");
        const index = try self.runtime.expectObject(object);
        var keys: [max_properties]StringRef = undefined;
        var key_count: usize = 0;
        if (self.property_count > 0) {
            for (self.property_list[0..self.property_count]) |key| {
                keys[key_count] = key;
                key_count += 1;
            }
        } else {
            for (self.runtime.propertyStorageConst(index)[0..self.runtime.cells[index].property_count]) |property| {
                if (!property.enumerable) continue;
                if (self.runtime.symbolParts(property.key) != null) continue;
                keys[key_count] = property.key;
                key_count += 1;
            }
        }
        var written: usize = 0;
        for (keys[0..key_count]) |key_ref| {
            const key = self.runtime.stringBytes(key_ref);
            const checkpoint = self.output_len;
            if (written > 0) try self.append(",");
            if (self.gap_len > 0) {
                try self.append("\n");
                try self.writeIndent(depth + 1);
            }
            try self.writeQuoted(key);
            try self.append(if (self.gap_len > 0) ": " else ":");
            if (!try self.writeProperty(object, key, false, depth + 1)) {
                self.output_len = checkpoint;
                continue;
            }
            written += 1;
        }
        if (written > 0 and self.gap_len > 0) {
            try self.append("\n");
            try self.writeIndent(depth);
        }
        try self.append("}");
    }

    fn writeQuoted(self: *JsonStringifier, value: []const u8) Error!void {
        try self.append("\"");
        var cursor: usize = 0;
        while (cursor < value.len) {
            const byte = value[cursor];
            cursor += 1;
            switch (byte) {
                '"' => try self.append("\\\""),
                '\\' => try self.append("\\\\"),
                0x08 => try self.append("\\b"),
                0x0c => try self.append("\\f"),
                '\n' => try self.append("\\n"),
                '\r' => try self.append("\\r"),
                '\t' => try self.append("\\t"),
                0...0x07, 0x0b, 0x0e...0x1f => {
                    var escape: [6]u8 = undefined;
                    const text = std.fmt.bufPrint(escape[0..], "\\u00{x:0>2}", .{byte}) catch return error.StringLimit;
                    try self.append(text);
                },
                else => {
                    if (byte >= 0x80) {
                        const count: usize = std.unicode.utf8ByteSequenceLength(byte) catch return error.TypeError;
                        const start = cursor - 1;
                        if (start + count > value.len) return error.TypeError;
                        _ = std.unicode.utf8Decode(value[start .. start + count]) catch return error.TypeError;
                        try self.append(value[start .. start + count]);
                        cursor = start + count;
                    } else {
                        try self.append(value[cursor - 1 .. cursor]);
                    }
                },
            }
        }
        try self.append("\"");
    }

    fn writeIndent(self: *JsonStringifier, depth: usize) Error!void {
        var level: usize = 0;
        while (level < depth) : (level += 1) try self.append(self.gap[0..self.gap_len]);
    }

    fn append(self: *JsonStringifier, value: []const u8) Error!void {
        try appendBytes(self.output[0..], &self.output_len, value);
    }
};

fn appendNode(program: *Program, first: *u16, last: *u16, node: u16) void {
    if (first.* == none) {
        first.* = node;
    } else {
        program.nodes[last.*].next = node;
    }
    last.* = node;
}

fn classBrandBindingName(class_index: u16, buffer: []u8) ![]const u8 {
    return std.fmt.bufPrint(buffer, "\x01R4JS_CLASS_{d}", .{class_index});
}

fn privateBrandBucketName(brand: u16, buffer: []u8) ![]const u8 {
    return std.fmt.bufPrint(buffer, "\x01R4JS_BRAND_{d}", .{brand});
}

fn isStatementKind(kind: NodeKind) bool {
    return switch (kind) {
        .program,
        .block,
        .empty,
        .expression_statement,
        .variable,
        .function_declaration,
        .class_declaration,
        .return_statement,
        .if_statement,
        .while_statement,
        .do_while_statement,
        .for_statement,
        .for_in_statement,
        .for_of_statement,
        .switch_statement,
        .switch_case,
        .labeled_statement,
        .break_statement,
        .continue_statement,
        .with_statement,
        .throw_statement,
        .try_statement,
        .import_statement,
        .export_list,
        .export_default,
        => true,
        else => false,
    };
}

fn isPatternKind(kind: NodeKind) bool {
    return kind == .array_pattern or kind == .object_pattern;
}

fn keyword(text: []const u8) TokenKind {
    const entries = [_]struct { text: []const u8, kind: TokenKind }{
        .{ .text = "let", .kind = .kw_let },
        .{ .text = "const", .kind = .kw_const },
        .{ .text = "var", .kind = .kw_var },
        .{ .text = "function", .kind = .kw_function },
        .{ .text = "return", .kind = .kw_return },
        .{ .text = "if", .kind = .kw_if },
        .{ .text = "else", .kind = .kw_else },
        .{ .text = "while", .kind = .kw_while },
        .{ .text = "do", .kind = .kw_do },
        .{ .text = "for", .kind = .kw_for },
        .{ .text = "switch", .kind = .kw_switch },
        .{ .text = "case", .kind = .kw_case },
        .{ .text = "default", .kind = .kw_default },
        .{ .text = "break", .kind = .kw_break },
        .{ .text = "continue", .kind = .kw_continue },
        .{ .text = "debugger", .kind = .kw_debugger },
        .{ .text = "with", .kind = .kw_with },
        .{ .text = "true", .kind = .kw_true },
        .{ .text = "false", .kind = .kw_false },
        .{ .text = "null", .kind = .kw_null },
        .{ .text = "throw", .kind = .kw_throw },
        .{ .text = "try", .kind = .kw_try },
        .{ .text = "catch", .kind = .kw_catch },
        .{ .text = "finally", .kind = .kw_finally },
        .{ .text = "new", .kind = .kw_new },
        .{ .text = "this", .kind = .kw_this },
        .{ .text = "typeof", .kind = .kw_typeof },
        .{ .text = "void", .kind = .kw_void },
        .{ .text = "delete", .kind = .kw_delete },
        .{ .text = "in", .kind = .kw_in },
        .{ .text = "instanceof", .kind = .kw_instanceof },
        .{ .text = "export", .kind = .kw_export },
        .{ .text = "import", .kind = .kw_import },
        .{ .text = "from", .kind = .kw_from },
        .{ .text = "as", .kind = .kw_as },
        .{ .text = "async", .kind = .kw_async },
        .{ .text = "class", .kind = .kw_class },
        .{ .text = "extends", .kind = .kw_extends },
        .{ .text = "super", .kind = .kw_super },
    };
    for (entries) |entry| if (equals(text, entry.text)) return entry.kind;
    return .identifier;
}

fn isReservedKeyword(kind: TokenKind) bool {
    return switch (kind) {
        .identifier, .kw_async, .kw_from, .kw_as => false,
        else => true,
    };
}

fn isPropertyNameToken(kind: TokenKind) bool {
    return switch (kind) {
        .identifier,
        .escaped_reserved,
        .kw_let,
        .kw_const,
        .kw_var,
        .kw_function,
        .kw_return,
        .kw_if,
        .kw_else,
        .kw_while,
        .kw_do,
        .kw_for,
        .kw_switch,
        .kw_case,
        .kw_default,
        .kw_break,
        .kw_continue,
        .kw_debugger,
        .kw_with,
        .kw_true,
        .kw_false,
        .kw_null,
        .kw_throw,
        .kw_try,
        .kw_catch,
        .kw_finally,
        .kw_new,
        .kw_this,
        .kw_typeof,
        .kw_void,
        .kw_delete,
        .kw_in,
        .kw_instanceof,
        .kw_export,
        .kw_import,
        .kw_from,
        .kw_as,
        .kw_async,
        .kw_class,
        .kw_extends,
        .kw_super,
        => true,
        else => false,
    };
}

fn scanNumber(source: []const u8, start: usize) usize {
    var cursor = start;
    if (cursor + 1 < source.len and source[cursor] == '0' and
        (source[cursor + 1] == 'x' or source[cursor + 1] == 'X' or
            source[cursor + 1] == 'b' or source[cursor + 1] == 'B' or
            source[cursor + 1] == 'o' or source[cursor + 1] == 'O'))
    {
        cursor += 2;
        while (cursor < source.len and (std.ascii.isAlphanumeric(source[cursor]) or source[cursor] == '_')) cursor += 1;
        return cursor;
    }
    while (cursor < source.len and (std.ascii.isDigit(source[cursor]) or source[cursor] == '_')) cursor += 1;
    if (cursor < source.len and source[cursor] == '.') {
        cursor += 1;
        while (cursor < source.len and (std.ascii.isDigit(source[cursor]) or source[cursor] == '_')) cursor += 1;
    }
    if (cursor < source.len and (source[cursor] == 'e' or source[cursor] == 'E')) {
        cursor += 1;
        if (cursor < source.len and (source[cursor] == '+' or source[cursor] == '-')) cursor += 1;
        while (cursor < source.len and (std.ascii.isDigit(source[cursor]) or source[cursor] == '_')) cursor += 1;
    }
    if (cursor < source.len and source[cursor] == 'n') cursor += 1;
    return cursor;
}

fn bigIntLiteralValid(text: []const u8) bool {
    if (text.len < 2 or text[text.len - 1] != 'n') return false;
    const body = text[0 .. text.len - 1];
    var radix: u8 = 10;
    var digits = body;
    if (body.len >= 2 and body[0] == '0') {
        radix = switch (body[1]) {
            'x', 'X' => 16,
            'b', 'B' => 2,
            'o', 'O' => 8,
            else => 10,
        };
        if (radix != 10) digits = body[2..];
    }
    if (digits.len == 0) return false;
    if (radix == 10 and digits.len > 1 and digits[0] == '0') return false;
    for (digits, 0..) |byte, index| {
        if (byte == '_') {
            if (index == 0 or index + 1 == digits.len) return false;
            const before = numberDigitValue(digits[index - 1]) orelse return false;
            const after = numberDigitValue(digits[index + 1]) orelse return false;
            if (before >= radix or after >= radix) return false;
            continue;
        }
        const digit = numberDigitValue(byte) orelse return false;
        if (digit >= radix) return false;
    }
    return true;
}

fn parseNumber(text: []const u8) !f64 {
    if (text.len > 1 and text[0] == '0') {
        const radix: ?u8 = switch (text[1]) {
            'x', 'X' => 16,
            'b', 'B' => 2,
            'o', 'O' => 8,
            else => null,
        };
        if (radix) |base| return parseRadixNumber(text[2..], base);
    }
    if (text.len > 1 and text[0] == '0' and text[1] == '_') return error.InvalidCharacter;
    return parseDecimalNumber(text);
}

fn parseDecimalNumber(text: []const u8) !f64 {
    var value: f64 = 0;
    var fraction_scale: f64 = 0.1;
    var saw_digit = false;
    var saw_dot = false;
    var cursor: usize = 0;
    while (cursor < text.len and text[cursor] != 'e' and text[cursor] != 'E') : (cursor += 1) {
        const byte = text[cursor];
        if (byte == '_') {
            if (cursor == 0 or cursor + 1 >= text.len or !std.ascii.isDigit(text[cursor - 1]) or !std.ascii.isDigit(text[cursor + 1]))
                return error.InvalidCharacter;
            continue;
        }
        if (byte == '.') {
            if (saw_dot) return error.InvalidCharacter;
            saw_dot = true;
            continue;
        }
        if (!std.ascii.isDigit(byte)) return error.InvalidCharacter;
        saw_digit = true;
        const digit: f64 = @floatFromInt(byte - '0');
        if (saw_dot) {
            value += digit * fraction_scale;
            fraction_scale *= 0.1;
        } else {
            value = value * 10 + digit;
        }
    }
    if (!saw_digit) return error.InvalidCharacter;
    if (cursor == text.len) return value;

    cursor += 1;
    var exponent_negative = false;
    if (cursor < text.len and (text[cursor] == '+' or text[cursor] == '-')) {
        exponent_negative = text[cursor] == '-';
        cursor += 1;
    }
    const exponent_start = cursor;
    var exponent: usize = 0;
    var exponent_digits: usize = 0;
    while (cursor < text.len) : (cursor += 1) {
        const byte = text[cursor];
        if (byte == '_') {
            if (cursor == exponent_start or cursor + 1 >= text.len or !std.ascii.isDigit(text[cursor - 1]) or !std.ascii.isDigit(text[cursor + 1]))
                return error.InvalidCharacter;
            continue;
        }
        if (!std.ascii.isDigit(byte)) return error.InvalidCharacter;
        exponent = @min(exponent * 10 + byte - '0', 10_000);
        exponent_digits += 1;
    }
    if (exponent_digits == 0) return error.InvalidCharacter;
    const magnitude = std.math.pow(f64, 10, @floatFromInt(@min(exponent, 400)));
    return if (exponent_negative) value / magnitude else value * magnitude;
}

fn parseRadixNumber(text: []const u8, radix: u8) !f64 {
    if (text.len == 0) return error.InvalidCharacter;
    var value: f64 = 0;
    var digits: usize = 0;
    for (text, 0..) |byte, index| {
        if (byte == '_') {
            if (index == 0 or index + 1 >= text.len) return error.InvalidCharacter;
            const previous = digitValue(text[index - 1]) orelse return error.InvalidCharacter;
            const next = digitValue(text[index + 1]) orelse return error.InvalidCharacter;
            if (previous >= radix or next >= radix) return error.InvalidCharacter;
            continue;
        }
        const digit = digitValue(byte) orelse return error.InvalidCharacter;
        if (digit >= radix) return error.InvalidCharacter;
        value = value * @as(f64, @floatFromInt(radix)) + @as(f64, @floatFromInt(digit));
        digits += 1;
    }
    if (digits == 0) return error.InvalidCharacter;
    return value;
}

fn digitValue(byte: u8) ?u8 {
    if (byte >= '0' and byte <= '9') return byte - '0';
    if (byte >= 'a' and byte <= 'f') return byte - 'a' + 10;
    if (byte >= 'A' and byte <= 'F') return byte - 'A' + 10;
    return null;
}

fn makeSourceRef(offset: usize, len: usize) StringRef {
    return .{ .offset = @intCast(offset), .len = @intCast(len) };
}

fn makeIdentifierRef(offset: usize, len: usize) StringRef {
    return .{ .offset = identifier_ref_bit | @as(u32, @intCast(offset)), .len = @intCast(len) };
}

fn advancePosition(byte: u8, line: *u32, column: *u32) void {
    if (byte == '\n') {
        line.* += 1;
        column.* = 1;
    } else {
        column.* += 1;
    }
}

fn advanceSourcePosition(source: []const u8, cursor: *usize, line: *u32, column: *u32) Error!void {
    const codepoint = try decodeSourceCodePoint(source, cursor.*);
    cursor.* = codepoint.end;
    if (codepoint.value == '\r') {
        if (cursor.* < source.len and source[cursor.*] == '\n') cursor.* += 1;
        line.* += 1;
        column.* = 1;
    } else if (isEcmaLineTerminator(codepoint.value)) {
        line.* += 1;
        column.* = 1;
    } else {
        column.* += 1;
    }
}

fn isEcmaLineTerminator(codepoint: u21) bool {
    return codepoint == '\n' or codepoint == '\r' or codepoint == 0x2028 or codepoint == 0x2029;
}

fn isEcmaWhiteSpace(codepoint: u21) bool {
    return switch (codepoint) {
        '\t', 0x0b, 0x0c, ' ', 0x00a0, 0x1680, 0x2000...0x200a, 0x202f, 0x205f, 0x3000, 0xfeff => true,
        else => false,
    };
}

fn appendUtf8CodePoint(buffer: []u8, output: *usize, codepoint: u32) Error!void {
    const length: usize = if (codepoint < 0x80) 1 else if (codepoint < 0x800) 2 else if (codepoint < 0x10000) 3 else if (codepoint <= 0x10ffff) 4 else return error.SyntaxError;
    if (output.* + length > buffer.len) return error.StringLimit;
    switch (length) {
        1 => buffer[output.*] = @intCast(codepoint),
        2 => {
            buffer[output.*] = @intCast(0xc0 | (codepoint >> 6));
            buffer[output.* + 1] = @intCast(0x80 | (codepoint & 0x3f));
        },
        3 => {
            buffer[output.*] = @intCast(0xe0 | (codepoint >> 12));
            buffer[output.* + 1] = @intCast(0x80 | ((codepoint >> 6) & 0x3f));
            buffer[output.* + 2] = @intCast(0x80 | (codepoint & 0x3f));
        },
        4 => {
            buffer[output.*] = @intCast(0xf0 | (codepoint >> 18));
            buffer[output.* + 1] = @intCast(0x80 | ((codepoint >> 12) & 0x3f));
            buffer[output.* + 2] = @intCast(0x80 | ((codepoint >> 6) & 0x3f));
            buffer[output.* + 3] = @intCast(0x80 | (codepoint & 0x3f));
        },
        else => unreachable,
    }
    output.* += length;
}

const RuntimeStringScalar = struct {
    value: u32,
    length: usize,
};

fn runtimeStringDecode(value: []const u8, cursor: usize) RuntimeStringScalar {
    const first = value[cursor];
    const expected: usize = std.unicode.utf8ByteSequenceLength(first) catch 1;
    if (expected == 1 or cursor + expected > value.len) return .{ .value = first, .length = 1 };
    var codepoint: u32 = switch (expected) {
        2 => first & 0x1f,
        3 => first & 0x0f,
        4 => first & 0x07,
        else => return .{ .value = first, .length = 1 },
    };
    for (value[cursor + 1 .. cursor + expected]) |continuation| {
        if (continuation & 0xc0 != 0x80) return .{ .value = first, .length = 1 };
        codepoint = (codepoint << 6) | (continuation & 0x3f);
    }
    const minimum: u32 = switch (expected) {
        2 => 0x80,
        3 => 0x800,
        4 => 0x10000,
        else => unreachable,
    };
    if (codepoint < minimum or codepoint > 0x10ffff) return .{ .value = first, .length = 1 };
    return .{ .value = codepoint, .length = expected };
}

fn regexExpandCodeUnits(source: []const u8, output: []u8) Error!usize {
    var source_cursor: usize = 0;
    var output_length: usize = 0;
    while (source_cursor < source.len) {
        const scalar = runtimeStringDecode(source, source_cursor);
        if (scalar.value > 0xffff) {
            const adjusted = scalar.value - 0x10000;
            try appendUtf8CodePoint(output, &output_length, @intCast(0xd800 + (adjusted >> 10)));
            try appendUtf8CodePoint(output, &output_length, @intCast(0xdc00 + (adjusted & 0x3ff)));
        } else {
            try appendBytes(output, &output_length, source[source_cursor .. source_cursor + scalar.length]);
        }
        source_cursor += scalar.length;
    }
    return output_length;
}

fn runtimeStringUnitCount(value: []const u8) usize {
    var count: usize = 0;
    var cursor: usize = 0;
    while (cursor < value.len) {
        const scalar = runtimeStringDecode(value, cursor);
        count += if (scalar.value > 0xffff) 2 else 1;
        cursor += scalar.length;
    }
    return count;
}

fn runtimeStringUnitAt(value: []const u8, wanted: usize) ?u16 {
    var unit_index: usize = 0;
    var cursor: usize = 0;
    while (cursor < value.len) {
        const scalar = runtimeStringDecode(value, cursor);
        if (scalar.value <= 0xffff) {
            if (unit_index == wanted) return @intCast(scalar.value);
            unit_index += 1;
        } else {
            const adjusted = scalar.value - 0x10000;
            if (unit_index == wanted) return @intCast(0xd800 + (adjusted >> 10));
            if (unit_index + 1 == wanted) return @intCast(0xdc00 + (adjusted & 0x3ff));
            unit_index += 2;
        }
        cursor += scalar.length;
    }
    return null;
}

fn runtimeStringByteOffsetAtUnit(value: []const u8, wanted: usize) ?usize {
    if (wanted == 0) return 0;
    var unit_index: usize = 0;
    var cursor: usize = 0;
    while (cursor < value.len) {
        const scalar = runtimeStringDecode(value, cursor);
        unit_index += if (scalar.value > 0xffff) 2 else 1;
        cursor += scalar.length;
        if (unit_index == wanted) return cursor;
        if (unit_index > wanted) return null;
    }
    return if (unit_index == wanted) cursor else null;
}

fn runtimeStringCodePointAtUnit(value: []const u8, wanted: usize) ?u32 {
    const first = runtimeStringUnitAt(value, wanted) orelse return null;
    if (first >= 0xd800 and first <= 0xdbff) {
        if (runtimeStringUnitAt(value, wanted + 1)) |second| {
            if (second >= 0xdc00 and second <= 0xdfff)
                return 0x10000 + ((@as(u32, first) - 0xd800) << 10) + (@as(u32, second) - 0xdc00);
        }
    }
    return first;
}

fn appendRuntimeStringUnits(buffer: []u8, output: *usize, value: []const u8, start: usize, end: usize) Error!void {
    var unit_index = start;
    while (unit_index < end) {
        const first = runtimeStringUnitAt(value, unit_index) orelse break;
        if (first >= 0xd800 and first <= 0xdbff and unit_index + 1 < end) {
            if (runtimeStringUnitAt(value, unit_index + 1)) |second| {
                if (second >= 0xdc00 and second <= 0xdfff) {
                    const codepoint = 0x10000 + ((@as(u32, first) - 0xd800) << 10) + (@as(u32, second) - 0xdc00);
                    try appendUtf8CodePoint(buffer, output, codepoint);
                    unit_index += 2;
                    continue;
                }
            }
        }
        try appendUtf8CodePoint(buffer, output, first);
        unit_index += 1;
    }
}

fn runtimeStringUnitsEqualAt(haystack: []const u8, needle: []const u8, position: usize) bool {
    const needle_length = runtimeStringUnitCount(needle);
    if (position + needle_length > runtimeStringUnitCount(haystack)) return false;
    for (0..needle_length) |offset| {
        if (runtimeStringUnitAt(haystack, position + offset) != runtimeStringUnitAt(needle, offset)) return false;
    }
    return true;
}

fn runtimeStringIndexOfUnits(haystack: []const u8, needle: []const u8, start: usize) ?usize {
    const haystack_length = runtimeStringUnitCount(haystack);
    const needle_length = runtimeStringUnitCount(needle);
    if (needle_length == 0) return @min(start, haystack_length);
    if (needle_length > haystack_length or start > haystack_length - needle_length) return null;
    var position = start;
    while (position <= haystack_length - needle_length) : (position += 1)
        if (runtimeStringUnitsEqualAt(haystack, needle, position)) return position;
    return null;
}

fn runtimeStringFinalSigma(value: []const u8, start: usize) bool {
    var cursor = start;
    while (cursor < value.len) {
        const scalar = runtimeStringDecode(value, cursor);
        const codepoint: u21 = @intCast(scalar.value);
        if (unicode_string_case.isCased(codepoint)) return false;
        if (!unicode_string_case.isCaseIgnorable(codepoint)) return true;
        cursor += scalar.length;
    }
    return true;
}

const HangulDecomposition = struct {
    values: [3]u21,
    length: u2,
};

fn decomposeHangul(codepoint: u21) ?HangulDecomposition {
    const s_base: u21 = 0xac00;
    const l_base: u21 = 0x1100;
    const v_base: u21 = 0x1161;
    const t_base: u21 = 0x11a7;
    const l_count: u21 = 19;
    const v_count: u21 = 21;
    const t_count: u21 = 28;
    const n_count = v_count * t_count;
    const s_count = l_count * n_count;
    if (codepoint < s_base or codepoint >= s_base + s_count) return null;
    const index = codepoint - s_base;
    const trailing = index % t_count;
    return .{
        .values = .{ l_base + index / n_count, v_base + (index % n_count) / t_count, t_base + trailing },
        .length = if (trailing == 0) 2 else 3,
    };
}

fn composeUnicodePair(first: u21, second: u21) ?u21 {
    const s_base: u21 = 0xac00;
    const l_base: u21 = 0x1100;
    const v_base: u21 = 0x1161;
    const t_base: u21 = 0x11a7;
    const l_count: u21 = 19;
    const v_count: u21 = 21;
    const t_count: u21 = 28;
    const n_count = v_count * t_count;
    const s_count = l_count * n_count;
    if (first >= l_base and first < l_base + l_count and second >= v_base and second < v_base + v_count)
        return s_base + ((first - l_base) * v_count + (second - v_base)) * t_count;
    if (first >= s_base and first < s_base + s_count and (first - s_base) % t_count == 0 and second > t_base and second < t_base + t_count)
        return first + (second - t_base);
    return unicode_string_normalization.compose(first, second);
}

fn runtimeStringElementCount(value: []const u8) usize {
    var count: usize = 0;
    var cursor: usize = 0;
    while (cursor < value.len) : (count += 1) {
        cursor += runtimeStringDecode(value, cursor).length;
    }
    return count;
}

fn runtimeStringElementAt(value: []const u8, wanted: usize) ?[]const u8 {
    var index: usize = 0;
    var cursor: usize = 0;
    while (cursor < value.len) : (index += 1) {
        const length = runtimeStringDecode(value, cursor).length;
        if (index == wanted) return value[cursor .. cursor + length];
        cursor += length;
    }
    return null;
}

fn isPotentialIdentifierStart(byte: u8) bool {
    return std.ascii.isAlphabetic(byte) or byte == '_' or byte == '$' or byte == '\\' or byte >= 0x80;
}

fn startsWith(value: []const u8, prefix: []const u8) bool {
    return value.len >= prefix.len and equals(value[0..prefix.len], prefix);
}

fn equals(left: []const u8, right: []const u8) bool {
    return std.mem.eql(u8, left, right);
}

fn jsonRawBoundary(byte: u8, first: bool) bool {
    if (std.ascii.isLower(byte) or std.ascii.isDigit(byte) or byte == '"') return true;
    return first and byte == '-';
}

fn sameJsonValue(runtime: *const Runtime, left: Value, right: Value) bool {
    if (std.meta.activeTag(left) != std.meta.activeTag(right)) return false;
    return switch (left) {
        .undefined, .null_value => true,
        .boolean => |value| value == right.boolean,
        .number => |value| (std.math.isNan(value) and std.math.isNan(right.number)) or
            @as(u64, @bitCast(value)) == @as(u64, @bitCast(right.number)),
        .bigint => BigIntCore.Const.eql(runtime.bigIntConst(left) catch return false, runtime.bigIntConst(right) catch return false),
        .string => |value| equals(runtime.stringBytes(value), runtime.stringBytes(right.string)),
        .cell => |value| value == right.cell,
    };
}

fn trimNumberWhitespace(value: []const u8) []const u8 {
    var cursor: usize = 0;
    while (cursor < value.len) {
        const sequence_length: usize = std.unicode.utf8ByteSequenceLength(value[cursor]) catch break;
        if (cursor + sequence_length > value.len) break;
        const codepoint = std.unicode.utf8Decode(value[cursor .. cursor + sequence_length]) catch break;
        if (!isEcmaWhiteSpace(codepoint) and !isEcmaLineTerminator(codepoint)) break;
        cursor += sequence_length;
    }
    const start = cursor;
    var end = start;
    while (cursor < value.len) {
        const sequence_length: usize = std.unicode.utf8ByteSequenceLength(value[cursor]) catch {
            cursor += 1;
            end = cursor;
            continue;
        };
        if (cursor + sequence_length > value.len) return value[start..value.len];
        const codepoint = std.unicode.utf8Decode(value[cursor .. cursor + sequence_length]) catch {
            cursor += 1;
            end = cursor;
            continue;
        };
        cursor += sequence_length;
        if (!isEcmaWhiteSpace(codepoint) and !isEcmaLineTerminator(codepoint)) end = cursor;
    }
    return value[start..end];
}

fn ecmaStringToNumber(text: []const u8) f64 {
    if (text.len == 0) return 0;
    if (equals(text, "Infinity") or equals(text, "+Infinity")) return std.math.inf(f64);
    if (equals(text, "-Infinity")) return -std.math.inf(f64);
    if (text.len > 2 and text[0] == '0') {
        const radix: ?u8 = switch (text[1]) {
            'x', 'X' => 16,
            'b', 'B' => 2,
            'o', 'O' => 8,
            else => null,
        };
        if (radix) |base| {
            var value: f64 = 0;
            var digits: usize = 0;
            for (text[2..]) |byte| {
                const digit = numberDigitValue(byte) orelse return std.math.nan(f64);
                if (digit >= base) return std.math.nan(f64);
                value = value * @as(f64, @floatFromInt(base)) + @as(f64, @floatFromInt(digit));
                digits += 1;
            }
            return if (digits == 0) std.math.nan(f64) else value;
        }
    }
    return std.fmt.parseFloat(f64, text) catch std.math.nan(f64);
}

fn numberDigit(value: u8) u8 {
    return if (value < 10) '0' + value else 'a' + value - 10;
}

fn numberDigitValue(value: u8) ?u8 {
    if (value >= '0' and value <= '9') return value - '0';
    if (value >= 'a' and value <= 'z') return value - 'a' + 10;
    if (value >= 'A' and value <= 'Z') return value - 'A' + 10;
    return null;
}

fn normalizeNumberExponent(value: []const u8, output: []u8) Error![]const u8 {
    const marker = std.mem.indexOfScalar(u8, value, 'e') orelse return value;
    var length: usize = 0;
    try appendBytes(output, &length, value[0 .. marker + 1]);
    var cursor = marker + 1;
    if (cursor < value.len and (value[cursor] == '+' or value[cursor] == '-')) {
        try appendBytes(output, &length, value[cursor .. cursor + 1]);
        cursor += 1;
    } else {
        try appendBytes(output, &length, "+");
    }
    while (cursor + 1 < value.len and value[cursor] == '0') cursor += 1;
    try appendBytes(output, &length, value[cursor..]);
    return output[0..length];
}

fn parseArrayIndex(name: []const u8) ?usize {
    if (name.len == 0) return null;
    for (name) |byte| if (!std.ascii.isDigit(byte)) return null;
    return std.fmt.parseInt(usize, name, 10) catch null;
}

fn canonicalPropertyIndex(name: []const u8) ?u32 {
    if (name.len == 0 or (name.len > 1 and name[0] == '0')) return null;
    for (name) |byte| if (!std.ascii.isDigit(byte)) return null;
    const value = std.fmt.parseInt(u64, name, 10) catch return null;
    if (value >= 0xffff_ffff) return null;
    return @intCast(value);
}

fn functionParameterLength(program: *const Program, first: u16) usize {
    var count: usize = 0;
    var parameter = first;
    while (parameter != none and parameter < program.node_count) : (parameter = program.nodes[parameter].next) {
        const node = program.nodes[parameter];
        if (node.kind != .parameter or node.flags & flag_rest != 0 or node.a != none) break;
        count += 1;
    }
    return count;
}

fn hexDigit(byte: u8) ?u8 {
    if (byte >= '0' and byte <= '9') return byte - '0';
    if (byte >= 'a' and byte <= 'f') return byte - 'a' + 10;
    if (byte >= 'A' and byte <= 'F') return byte - 'A' + 10;
    return null;
}

fn clampIndex(value: f64, length: usize) usize {
    if (std.math.isNan(value)) return 0;
    const integer: i64 = @intFromFloat(@trunc(value));
    if (integer < 0) {
        const adjusted = @as(i64, @intCast(length)) + integer;
        return @intCast(@max(0, adjusted));
    }
    return @min(length, @as(usize, @intCast(integer)));
}

fn relativeStringIndex(value: f64, length: usize) usize {
    if (std.math.isNan(value)) return 0;
    if (value == -std.math.inf(f64)) return 0;
    if (value == std.math.inf(f64)) return length;
    const integer: i64 = @intFromFloat(@trunc(value));
    if (integer < 0) return @intCast(@max(0, @as(i64, @intCast(length)) + integer));
    return @min(length, @as(usize, @intCast(integer)));
}

fn arrayLengthValue(value: f64) Error!usize {
    if (!std.math.isFinite(value) or value < 0 or @trunc(value) != value or value > @as(f64, @floatFromInt(max_items)))
        return error.RangeError;
    return @intFromFloat(value);
}

fn stringMethod(name: []const u8) ?NativeId {
    if (equals(name, "toString")) return .primitive_to_string;
    if (equals(name, "valueOf")) return .primitive_value_of;
    if (equals(name, "concat")) return .string_concat;
    if (equals(name, "includes")) return .string_includes;
    if (equals(name, "indexOf")) return .string_index_of;
    if (equals(name, "slice")) return .string_slice;
    if (equals(name, "substring")) return .string_substring;
    if (equals(name, "charCodeAt")) return .string_char_code_at;
    if (equals(name, "toUpperCase")) return .string_upper;
    if (equals(name, "toLowerCase")) return .string_lower;
    if (equals(name, "split")) return .string_split;
    if (equals(name, "replace")) return .string_replace;
    if (equals(name, "substr")) return .string_substr;
    return null;
}

fn base64Value(byte: u8) ?u32 {
    if (byte >= 'A' and byte <= 'Z') return byte - 'A';
    if (byte >= 'a' and byte <= 'z') return byte - 'a' + 26;
    if (byte >= '0' and byte <= '9') return byte - '0' + 52;
    if (byte == '+') return 62;
    if (byte == '/') return 63;
    return null;
}

fn clampSubstringIndex(value: f64, length: usize) usize {
    if (std.math.isNan(value) or value <= 0) return 0;
    if (!std.math.isFinite(value) or value >= @as(f64, @floatFromInt(length))) return length;
    return @intFromFloat(@trunc(value));
}

fn arrayMethod(name: []const u8) ?NativeId {
    if (equals(name, "at")) return .array_at;
    if (equals(name, "push")) return .array_push;
    if (equals(name, "unshift")) return .array_unshift;
    if (equals(name, "join")) return .array_join;
    if (equals(name, "forEach")) return .array_for_each;
    if (equals(name, "every")) return .array_every;
    if (equals(name, "some")) return .array_some;
    if (equals(name, "map")) return .array_map;
    if (equals(name, "flat")) return .array_flat;
    if (equals(name, "flatMap")) return .array_flat_map;
    if (equals(name, "find")) return .array_find;
    if (equals(name, "findIndex")) return .array_find_index;
    if (equals(name, "findLast")) return .array_find_last;
    if (equals(name, "findLastIndex")) return .array_find_last_index;
    if (equals(name, "concat")) return .array_concat;
    if (equals(name, "copyWithin")) return .array_copy_within;
    if (equals(name, "fill")) return .array_fill;
    if (equals(name, "reverse")) return .array_reverse;
    if (equals(name, "shift")) return .array_shift;
    if (equals(name, "pop")) return .array_pop;
    if (equals(name, "slice")) return .array_slice;
    if (equals(name, "splice")) return .array_splice;
    if (equals(name, "includes")) return .array_includes;
    if (equals(name, "indexOf")) return .array_index_of;
    if (equals(name, "lastIndexOf")) return .array_last_index_of;
    if (equals(name, "filter")) return .array_filter;
    if (equals(name, "reduce")) return .array_reduce;
    if (equals(name, "reduceRight")) return .array_reduce_right;
    if (equals(name, "sort")) return .array_sort;
    if (equals(name, "entries")) return .array_entries;
    if (equals(name, "keys")) return .array_keys;
    if (equals(name, "values")) return .array_values;
    if (equals(name, "toString")) return .array_to_string;
    if (equals(name, "toLocaleString")) return .array_to_locale_string;
    if (equals(name, "toReversed")) return .array_to_reversed;
    if (equals(name, "toSorted")) return .array_to_sorted;
    if (equals(name, "toSpliced")) return .array_to_spliced;
    if (equals(name, "with")) return .array_with;
    return null;
}

fn appendBytes(buffer: []u8, length: *usize, value: []const u8) Error!void {
    if (value.len > buffer.len -| length.*) return error.StringLimit;
    if (value.len > 0) @memcpy(buffer[length.* .. length.* + value.len], value);
    length.* += value.len;
}

fn appendRegexHexEscape(buffer: []u8, length: *usize, marker: u8, value: u16, digits: usize) Error!void {
    const alphabet = "0123456789abcdef";
    if (digits != 2 and digits != 4) return error.TypeError;
    var encoded: [6]u8 = undefined;
    encoded[0] = '\\';
    encoded[1] = marker;
    var index: usize = 0;
    while (index < digits) : (index += 1) {
        const shift: u4 = @intCast((digits - index - 1) * 4);
        encoded[index + 2] = alphabet[@as(usize, (value >> shift) & 0xf)];
    }
    try appendBytes(buffer, length, encoded[0 .. digits + 2]);
}

fn enqueue(queue: *[max_jobs]Job, head: *usize, count: *usize, job: Job) Error!void {
    if (count.* >= queue.len) return error.JobLimit;
    queue[(head.* + count.*) % queue.len] = job;
    count.* += 1;
}

fn valueCellOrNone(value: Value) u16 {
    return switch (value) {
        .cell => |cell| cell,
        else => none,
    };
}

fn dequeue(queue: *[max_jobs]Job, head: *usize, count: *usize) Job {
    const job = queue[head.*];
    head.* = (head.* + 1) % queue.len;
    count.* -= 1;
    return job;
}

fn markJobs(runtime: *Runtime, queue: []const Job, head: usize, count: usize) void {
    var index: usize = 0;
    while (index < count) : (index += 1) {
        const job = queue[(head + index) % queue.len];
        runtime.markValue(job.callback);
        runtime.markValue(job.argument);
        runtime.markCell(job.promise);
        runtime.markCell(job.generator);
    }
}

fn toUint32(value: f64) u32 {
    if (!std.math.isFinite(value) or value == 0) return 0;
    const modulo = @mod(@trunc(value), 4294967296.0);
    return @intFromFloat(modulo);
}

fn toInt32(value: f64) i32 {
    return @bitCast(toUint32(value));
}

const RegexCapture = struct {
    start: u32 = std.math.maxInt(u32),
    end: u32 = 0,

    fn matched(self: RegexCapture) bool {
        return self.start != std.math.maxInt(u32);
    }
};

const RegexState = struct {
    end: usize,
    captures: [max_regex_captures]RegexCapture = [_]RegexCapture{.{}} ** max_regex_captures,
};

const RegexStates = struct {
    values: [max_regex_states]RegexState = undefined,
    count: usize = 0,
    limited: bool = false,

    fn add(self: *RegexStates, value: RegexState) void {
        for (self.values[0..self.count]) |existing| {
            if (sameState(existing, value)) return;
        }
        if (self.count >= self.values.len) {
            self.limited = true;
            return;
        }
        self.values[self.count] = value;
        self.count += 1;
    }

    fn append(self: *RegexStates, source: *const RegexStates) void {
        for (source.values[0..source.count]) |value| self.add(value);
        self.limited = self.limited or source.limited;
    }

    fn prepend(self: *RegexStates, source: *const RegexStates) void {
        var source_index = source.count;
        while (source_index > 0) {
            source_index -= 1;
            self.prependOne(source.values[source_index]);
        }
        self.limited = self.limited or source.limited;
    }

    fn prependOne(self: *RegexStates, value: RegexState) void {
        var existing_index: ?usize = null;
        for (self.values[0..self.count], 0..) |existing, index| {
            if (sameState(existing, value)) {
                existing_index = index;
                break;
            }
        }
        if (existing_index) |index| {
            var move = index + 1;
            while (move < self.count) : (move += 1) self.values[move - 1] = self.values[move];
            self.count -= 1;
        } else if (self.count == self.values.len) {
            self.count -= 1;
            self.limited = true;
        }
        if (self.count > 0)
            std.mem.copyBackwards(RegexState, self.values[1 .. self.count + 1], self.values[0..self.count]);
        self.values[0] = value;
        self.count += 1;
    }

    fn sameState(left: RegexState, right: RegexState) bool {
        if (left.end != right.end) return false;
        for (left.captures, right.captures) |left_capture, right_capture| {
            if (left_capture.start != right_capture.start or left_capture.end != right_capture.end) return false;
        }
        return true;
    }
};

const RegexMatch = struct {
    start: usize,
    end: usize,
    captures: [max_regex_captures]RegexCapture,
    capture_count: usize,
};

const RegexOptions = struct {
    ignore_case: bool = false,
    multiline: bool = false,
    dot_all: bool = false,
    unicode: bool = false,
    unicode_sets: bool = false,
};

fn regexFind(pattern: []const u8, input: []const u8, options: RegexOptions, start_from: usize, sticky: bool) Error!?RegexMatch {
    const anchored = pattern.len > 0 and pattern[0] == '^';
    const capture_count = regexCaptureCount(pattern);
    if (capture_count > max_regex_captures) return null;
    var input_start = @min(start_from, input.len);
    while (input_start <= input.len) {
        if (anchored and !regexStartAssertionMatches(input, input_start, options.multiline)) {
            if (!options.multiline or sticky) break;
            input_start += if (input_start < input.len) runtimeStringDecode(input, input_start).length else 1;
            continue;
        }
        var states = RegexStates{};
        try regexAlternatives(pattern, 0, pattern.len, input, .{ .end = input_start }, options, &states, 0);
        if (states.count > 0) {
            return .{
                .start = input_start,
                .end = states.values[0].end,
                .captures = states.values[0].captures,
                .capture_count = capture_count,
            };
        }
        if (states.limited) return error.RangeError;
        if (sticky or (anchored and !options.multiline)) break;
        if (input_start == input.len) break;
        input_start += runtimeStringDecode(input, input_start).length;
    }
    return null;
}

fn regexTest(pattern: []const u8, input: []const u8, ignore_case: bool) Error!bool {
    return (try regexFind(pattern, input, .{ .ignore_case = ignore_case }, 0, false)) != null;
}

fn regexAlternatives(
    pattern: []const u8,
    start: usize,
    end: usize,
    input: []const u8,
    input_state: RegexState,
    options: RegexOptions,
    out: *RegexStates,
    depth: usize,
) Error!void {
    if (depth > max_regex_backtrack_depth) return error.RangeError;
    var branch_start = start;
    var cursor = start;
    var group_depth: usize = 0;
    var in_class = false;
    var escaped = false;
    while (cursor < end) : (cursor += 1) {
        const byte = pattern[cursor];
        if (escaped) {
            escaped = false;
            continue;
        }
        if (byte == '\\') {
            escaped = true;
            continue;
        }
        if (byte == '[') in_class = true else if (byte == ']') in_class = false;
        if (in_class) continue;
        if (byte == '(') group_depth += 1 else if (byte == ')' and group_depth > 0) group_depth -= 1;
        if (byte == '|' and group_depth == 0) {
            try regexSequence(pattern, branch_start, cursor, input, input_state, options, out, depth + 1);
            branch_start = cursor + 1;
        }
    }
    try regexSequence(pattern, branch_start, end, input, input_state, options, out, depth + 1);
}

const RegexQuantifier = struct {
    minimum: usize,
    maximum: ?usize,
    next: usize,
    greedy: bool,
};

fn regexQuantifierValue(digits: []const u8) usize {
    var value: usize = 0;
    for (digits) |digit| {
        if (value > max_items) return max_items + 1;
        value = value * 10 + digit - '0';
        if (value > max_items) return max_items + 1;
    }
    return value;
}

fn regexDecimalLess(left_raw: []const u8, right_raw: []const u8) bool {
    var left = left_raw;
    var right = right_raw;
    while (left.len > 1 and left[0] == '0') left = left[1..];
    while (right.len > 1 and right[0] == '0') right = right[1..];
    if (left.len != right.len) return left.len < right.len;
    return std.mem.order(u8, left, right) == .lt;
}

fn regexLooksLikeBraceQuantifier(pattern: []const u8, start: usize, end: usize) bool {
    if (start >= end or pattern[start] != '{') return false;
    var cursor = start + 1;
    if (cursor >= end or !std.ascii.isDigit(pattern[cursor])) return false;
    while (cursor < end and std.ascii.isDigit(pattern[cursor])) : (cursor += 1) {}
    if (cursor < end and pattern[cursor] == ',') {
        cursor += 1;
        while (cursor < end and std.ascii.isDigit(pattern[cursor])) : (cursor += 1) {}
    }
    return cursor < end and pattern[cursor] == '}';
}

fn regexQuantifierAt(pattern: []const u8, start: usize, end: usize) ?RegexQuantifier {
    if (start >= end) return null;
    var quantifier: RegexQuantifier = switch (pattern[start]) {
        '*' => .{ .minimum = 0, .maximum = null, .next = start + 1, .greedy = true },
        '+' => .{ .minimum = 1, .maximum = null, .next = start + 1, .greedy = true },
        '?' => .{ .minimum = 0, .maximum = 1, .next = start + 1, .greedy = true },
        '{' => quantifier: {
            var cursor = start + 1;
            if (cursor >= end or !std.ascii.isDigit(pattern[cursor])) return null;
            const minimum_start = cursor;
            while (cursor < end and std.ascii.isDigit(pattern[cursor])) : (cursor += 1) {}
            const minimum_digits = pattern[minimum_start..cursor];
            const minimum = regexQuantifierValue(minimum_digits);
            var maximum: ?usize = minimum;
            if (cursor < end and pattern[cursor] == ',') {
                cursor += 1;
                maximum = null;
                if (cursor < end and std.ascii.isDigit(pattern[cursor])) {
                    const maximum_start = cursor;
                    while (cursor < end and std.ascii.isDigit(pattern[cursor])) : (cursor += 1) {}
                    const maximum_digits = pattern[maximum_start..cursor];
                    if (regexDecimalLess(maximum_digits, minimum_digits)) return null;
                    maximum = regexQuantifierValue(maximum_digits);
                }
            }
            if (cursor >= end or pattern[cursor] != '}') return null;
            break :quantifier .{ .minimum = minimum, .maximum = maximum, .next = cursor + 1, .greedy = true };
        },
        else => return null,
    };
    if (quantifier.next < end and pattern[quantifier.next] == '?') {
        quantifier.greedy = false;
        quantifier.next += 1;
    }
    return quantifier;
}

fn regexSequence(
    pattern: []const u8,
    start: usize,
    end: usize,
    input: []const u8,
    input_state: RegexState,
    options: RegexOptions,
    out: *RegexStates,
    depth: usize,
) Error!void {
    if (depth > max_regex_backtrack_depth) return error.RangeError;
    var cursor = start;
    var current = input_state;
    var atom_count: usize = 0;
    while (cursor < end) {
        if (atom_count >= max_items) return error.RangeError;
        atom_count += 1;
        const atom_end = regexAtomEnd(pattern, cursor, end, options) orelse return;
        const quantifier = regexQuantifierAt(pattern, atom_end, end) orelse RegexQuantifier{ .minimum = 1, .maximum = 1, .next = atom_end, .greedy = true };
        if (quantifier.minimum == 1 and quantifier.maximum != null and quantifier.maximum.? == 1) {
            var matched = RegexStates{};
            try regexMatchAtom(pattern, cursor, atom_end, input, current, options, &matched, depth + 1);
            if (matched.count == 1 and !matched.limited) {
                current = matched.values[0];
                cursor = quantifier.next;
                continue;
            }
            for (matched.values[0..matched.count]) |state|
                try regexAlternatives(pattern, quantifier.next, end, input, state, options, out, depth + 1);
            out.limited = out.limited or matched.limited;
            return;
        }
        try regexQuantifiedSequence(pattern, cursor, atom_end, quantifier, end, input, current, options, out, depth);
        return;
    }
    out.add(current);
}

fn regexQuantifiedSequence(
    pattern: []const u8,
    start: usize,
    atom_end: usize,
    quantifier: RegexQuantifier,
    end: usize,
    input: []const u8,
    input_state: RegexState,
    options: RegexOptions,
    out: *RegexStates,
    depth: usize,
) Error!void {
    var frontier = RegexStates{};
    frontier.add(input_state);
    var ordered = RegexStates{};
    var repetitions: usize = 0;
    var no_progress = false;
    while (frontier.count > 0) {
        if (repetitions > max_items) return error.RangeError;
        if (repetitions >= quantifier.minimum) {
            var layer = RegexStates{};
            for (frontier.values[0..frontier.count]) |position|
                try regexAlternatives(pattern, quantifier.next, end, input, position, options, &layer, depth + 1);
            layer.limited = layer.limited or frontier.limited;
            if (quantifier.greedy) ordered.prepend(&layer) else ordered.append(&layer);
        }
        if (quantifier.maximum) |maximum| if (repetitions >= maximum) break;
        if (no_progress and repetitions >= quantifier.minimum) break;
        var following = RegexStates{};
        var advanced = false;
        for (frontier.values[0..frontier.count]) |position| {
            var matched = RegexStates{};
            try regexMatchAtom(pattern, start, atom_end, input, position, options, &matched, depth + 1);
            for (matched.values[0..matched.count]) |match_state| {
                if (match_state.end > position.end) advanced = true;
                following.add(match_state);
            }
            following.limited = following.limited or matched.limited;
        }
        following.limited = following.limited or frontier.limited;
        frontier = following;
        repetitions += 1;
        no_progress = !advanced;
    }
    ordered.limited = ordered.limited or frontier.limited;
    out.append(&ordered);
}

fn regexAtomEnd(pattern: []const u8, start: usize, end: usize, options: RegexOptions) ?usize {
    if (start >= end) return null;
    if (pattern[start] == '\\') {
        if (start + 1 >= end) return null;
        if (pattern[start + 1] >= '1' and pattern[start + 1] <= '9') {
            var cursor = start + 2;
            while (cursor < end and pattern[cursor] >= '0' and pattern[cursor] <= '9') : (cursor += 1) {}
            var reference: usize = 0;
            for (pattern[start + 1 .. cursor]) |digit| {
                if (reference > max_regex_captures) break;
                reference = reference * 10 + digit - '0';
            }
            if (reference > 0 and reference <= regexCaptureCount(pattern)) return cursor;
            if (options.unicode or pattern[start + 1] >= '8') return start + 2;
            const maximum_digits: usize = if (pattern[start + 1] <= '3') 3 else 2;
            var octal_end = start + 2;
            while (octal_end < end and octal_end - (start + 1) < maximum_digits and pattern[octal_end] >= '0' and pattern[octal_end] <= '7') : (octal_end += 1) {}
            return octal_end;
        }
        if (pattern[start + 1] == 'k' and start + 2 < end and pattern[start + 2] == '<') {
            const name_end = std.mem.indexOfScalarPos(u8, pattern, start + 3, '>') orelse return null;
            return name_end + 1;
        }
        if ((pattern[start + 1] == 'p' or pattern[start + 1] == 'P') and start + 2 < end and pattern[start + 2] == '{') {
            const property_end = std.mem.indexOfScalarPos(u8, pattern, start + 3, '}') orelse return null;
            return property_end + 1;
        }
        if (pattern[start + 1] == 'c') return if (start + 3 <= end) start + 3 else null;
        if (pattern[start + 1] == 'x') return if (start + 4 <= end) start + 4 else null;
        if (pattern[start + 1] == 'u') {
            if (start + 2 < end and pattern[start + 2] == '{') {
                const brace_end = std.mem.indexOfScalarPos(u8, pattern, start + 3, '}') orelse return null;
                return brace_end + 1;
            }
            if (start + 6 > end) return null;
            if (options.unicode and start + 12 <= end and pattern[start + 6] == '\\' and pattern[start + 7] == 'u') {
                const high = std.fmt.parseInt(u16, pattern[start + 2 .. start + 6], 16) catch return start + 6;
                const low = std.fmt.parseInt(u16, pattern[start + 8 .. start + 12], 16) catch return start + 6;
                if (high >= 0xd800 and high <= 0xdbff and low >= 0xdc00 and low <= 0xdfff) return start + 12;
            }
            return start + 6;
        }
        if (!options.unicode and pattern[start + 1] >= '0' and pattern[start + 1] <= '7') {
            const maximum_digits: usize = if (pattern[start + 1] <= '3') 3 else 2;
            var octal_end = start + 2;
            while (octal_end < end and octal_end - (start + 1) < maximum_digits and pattern[octal_end] >= '0' and pattern[octal_end] <= '7') : (octal_end += 1) {}
            return octal_end;
        }
        return start + 2;
    }
    if (pattern[start] == '[') {
        var cursor = start + 1;
        var nesting: usize = 1;
        var escaped = false;
        while (cursor < end) : (cursor += 1) {
            if (!escaped and options.unicode_sets and pattern[cursor] == '[') {
                nesting += 1;
                continue;
            }
            if (!escaped and pattern[cursor] == ']') {
                nesting -= 1;
                if (nesting == 0) return cursor + 1;
                continue;
            }
            if (!escaped and pattern[cursor] == '\\') escaped = true else escaped = false;
        }
        return null;
    }
    if (pattern[start] == '(') {
        var cursor = start + 1;
        var nesting: usize = 1;
        var in_class = false;
        var escaped = false;
        while (cursor < end) : (cursor += 1) {
            const byte = pattern[cursor];
            if (escaped) {
                escaped = false;
                continue;
            }
            if (byte == '\\') {
                escaped = true;
                continue;
            }
            if (byte == '[') in_class = true else if (byte == ']') in_class = false;
            if (in_class) continue;
            if (byte == '(') nesting += 1 else if (byte == ')') {
                nesting -= 1;
                if (nesting == 0) return cursor + 1;
            }
        }
        return null;
    }
    if (pattern[start] >= 0x80) return @min(end, start + runtimeStringDecode(pattern, start).length);
    return start + 1;
}

fn regexMatchAtom(
    pattern: []const u8,
    start: usize,
    end: usize,
    input: []const u8,
    input_state: RegexState,
    options: RegexOptions,
    out: *RegexStates,
    depth: usize,
) Error!void {
    if (input_state.end > input.len or start >= end) return;
    if (pattern[start] == '^') {
        if (regexStartAssertionMatches(input, input_state.end, options.multiline)) out.add(input_state);
        return;
    }
    if (pattern[start] == '$') {
        if (regexEndAssertionMatches(input, input_state.end, options.multiline)) out.add(input_state);
        return;
    }
    if (pattern[start] == '\\' and start + 1 < end and (pattern[start + 1] == 'b' or pattern[start + 1] == 'B')) {
        const previous_word = if (regexPreviousCodepoint(input, input_state.end)) |codepoint| regexUnicodeWord(codepoint, options.unicode and options.ignore_case) else false;
        const next_word = input_state.end < input.len and regexUnicodeWord(@intCast(runtimeStringDecode(input, input_state.end).value), options.unicode and options.ignore_case);
        const boundary = previous_word != next_word;
        if (boundary == (pattern[start + 1] == 'b')) out.add(input_state);
        return;
    }
    if (pattern[start] == '(') {
        const group = regexGroupInfo(pattern, start, end) orelse return;
        var group_options = options;
        if (group.enable_modifiers & 1 != 0) group_options.ignore_case = true;
        if (group.enable_modifiers & 2 != 0) group_options.multiline = true;
        if (group.enable_modifiers & 4 != 0) group_options.dot_all = true;
        if (group.disable_modifiers & 1 != 0) group_options.ignore_case = false;
        if (group.disable_modifiers & 2 != 0) group_options.multiline = false;
        if (group.disable_modifiers & 4 != 0) group_options.dot_all = false;
        var grouped = RegexStates{};
        if (group.kind == .positive_lookbehind or group.kind == .negative_lookbehind) {
            var candidate_start = input_state.end + 1;
            while (candidate_start > 0) {
                candidate_start -= 1;
                var candidates = RegexStates{};
                try regexAlternatives(pattern, group.body_start, end - 1, input, .{ .end = candidate_start, .captures = input_state.captures }, group_options, &candidates, depth + 1);
                for (candidates.values[0..candidates.count]) |candidate| if (candidate.end == input_state.end) grouped.add(candidate);
                grouped.limited = grouped.limited or candidates.limited;
            }
        } else {
            try regexAlternatives(pattern, group.body_start, end - 1, input, input_state, group_options, &grouped, depth + 1);
        }
        if (group.kind == .negative_lookahead or group.kind == .negative_lookbehind) {
            if (grouped.count == 0) {
                if (grouped.limited) out.limited = true else out.add(input_state);
            }
            return;
        }
        for (grouped.values[0..grouped.count]) |matched| {
            var captured = matched;
            if (group.capture_index) |capture_index| captured.captures[capture_index] = .{ .start = @intCast(input_state.end), .end = @intCast(matched.end) };
            if (group.kind != .capturing and group.kind != .noncapturing) captured.end = input_state.end;
            out.add(captured);
        }
        out.limited = out.limited or grouped.limited;
        return;
    }
    if (pattern[start] == '\\' and start + 1 < end and pattern[start + 1] >= '1' and pattern[start + 1] <= '9') {
        var capture_number: usize = 0;
        for (pattern[start + 1 .. end]) |digit| {
            if (capture_number > max_regex_captures) break;
            capture_number = capture_number * 10 + digit - '0';
        }
        const capture_count = regexCaptureCount(pattern);
        if (capture_number > 0 and capture_number <= capture_count) {
            try regexMatchBackreference(input, input_state, input_state.captures[capture_number - 1], options, out);
            return;
        }
        if (options.unicode or input_state.end >= input.len) return;
        const expected: u21 = if (pattern[start + 1] >= '8')
            pattern[start + 1]
        else
            std.fmt.parseInt(u21, pattern[start + 1 .. end], 8) catch return;
        const actual = runtimeStringDecode(input, input_state.end);
        if (regexCodepointEqual(expected, @intCast(actual.value), options.ignore_case)) {
            var matched = input_state;
            matched.end += actual.length;
            out.add(matched);
        }
        return;
    }
    if (pattern[start] == '\\' and start + 3 < end and pattern[start + 1] == 'k' and pattern[start + 2] == '<') {
        const capture_index = regexNamedCaptureIndex(pattern, pattern[start + 3 .. end - 1]) orelse return;
        try regexMatchBackreference(input, input_state, input_state.captures[capture_index], options, out);
        return;
    }
    if (input_state.end >= input.len) return;
    if (regexPropertyEscape(pattern, start, end)) |property| {
        if (options.unicode_sets) {
            if (unicode_regex.stringProperty(property.expression)) |string_property| {
                var string_ends = RegexStringEnds{};
                regexUnicodeStringPropertyMatches(string_property, input, input_state.end, options.ignore_case, &string_ends);
                var string_index = string_ends.count;
                while (string_index > 0) {
                    string_index -= 1;
                    var matched_state = input_state;
                    matched_state.end = string_ends.values[string_index];
                    out.add(matched_state);
                }
                return;
            }
        }
        const actual = runtimeStringDecode(input, input_state.end);
        const property_match = unicode_regex.matches(property.expression, @intCast(actual.value)) orelse return;
        if (property_match != property.negated) {
            var matched_state = input_state;
            matched_state.end += actual.length;
            out.add(matched_state);
        }
        return;
    }
    if (pattern[start] == '\\') {
        if (regexEscapeCodepoint(pattern, start, end)) |expected| {
            const actual = runtimeStringDecode(input, input_state.end);
            if (regexCodepointEqual(expected, @intCast(actual.value), options.ignore_case)) {
                var matched_state = input_state;
                matched_state.end += actual.length;
                out.add(matched_state);
            }
            return;
        }
        if (!options.unicode and start + 1 < end and pattern[start + 1] >= '0' and pattern[start + 1] <= '7') {
            const expected = std.fmt.parseInt(u21, pattern[start + 1 .. end], 8) catch return;
            const actual = runtimeStringDecode(input, input_state.end);
            if (regexCodepointEqual(expected, @intCast(actual.value), options.ignore_case)) {
                var matched_state = input_state;
                matched_state.end += actual.length;
                out.add(matched_state);
            }
            return;
        }
    }
    if (pattern[start] == '[') {
        const actual = runtimeStringDecode(input, input_state.end);
        const class_source = pattern[start + 1 .. end - 1];
        if (options.unicode_sets) {
            var string_ends = RegexStringEnds{};
            regexUnicodeClassStringMatches(class_source, input, input_state.end, options.ignore_case, &string_ends);
            var string_index = string_ends.count;
            while (string_index > 0) {
                string_index -= 1;
                var matched = input_state;
                matched.end = string_ends.values[string_index];
                out.add(matched);
            }
        }
        if (regexUnicodeClassMatches(class_source, @intCast(actual.value), options.ignore_case, options.unicode_sets)) {
            var matched = input_state;
            matched.end += actual.length;
            out.add(matched);
        }
        return;
    }
    if (pattern[start] == '\\' and start + 1 < end and (pattern[start + 1] == 'd' or pattern[start + 1] == 'D' or pattern[start + 1] == 's' or pattern[start + 1] == 'S' or pattern[start + 1] == 'w' or pattern[start + 1] == 'W')) {
        const actual = runtimeStringDecode(input, input_state.end);
        const codepoint: u21 = @intCast(actual.value);
        const escaped = pattern[start + 1];
        const matched = switch (escaped) {
            'd' => codepoint >= '0' and codepoint <= '9',
            'D' => codepoint < '0' or codepoint > '9',
            's' => regexUnicodeWhitespace(codepoint),
            'S' => !regexUnicodeWhitespace(codepoint),
            'w' => regexUnicodeWord(codepoint, options.unicode and options.ignore_case),
            'W' => !regexUnicodeWord(codepoint, options.unicode and options.ignore_case),
            else => unreachable,
        };
        if (matched) {
            var matched_state = input_state;
            matched_state.end += actual.length;
            out.add(matched_state);
        }
        return;
    }
    if (pattern[start] == '\\' and start + 1 < end) {
        const actual = runtimeStringDecode(input, input_state.end);
        const codepoint: u21 = @intCast(actual.value);
        const escaped = pattern[start + 1];
        const matched = switch (escaped) {
            'n' => codepoint == '\n',
            'r' => codepoint == '\r',
            't' => codepoint == '\t',
            'f' => codepoint == 0x0c,
            'v' => codepoint == 0x0b,
            '0' => codepoint == 0,
            else => regexCodepointEqual(escaped, codepoint, options.ignore_case),
        };
        if (matched) {
            var matched_state = input_state;
            matched_state.end += actual.length;
            out.add(matched_state);
        }
        return;
    }
    const actual = runtimeStringDecode(input, input_state.end);
    const expected = runtimeStringDecode(pattern, start);
    const matched = if (pattern[start] == '.') options.dot_all or !regexCodepointLineTerminator(actual.value) else regexCodepointEqual(@intCast(expected.value), @intCast(actual.value), options.ignore_case);
    if (!matched) return;
    var matched_state = input_state;
    matched_state.end += actual.length;
    out.add(matched_state);
}

const RegexGroupInfo = struct {
    body_start: usize,
    capture_index: ?usize,
    kind: enum { capturing, noncapturing, positive_lookahead, negative_lookahead, positive_lookbehind, negative_lookbehind },
    enable_modifiers: u3 = 0,
    disable_modifiers: u3 = 0,
};

fn regexGroupInfo(pattern: []const u8, start: usize, end: usize) ?RegexGroupInfo {
    if (start >= end or pattern[start] != '(' or end <= start + 1) return null;
    if (pattern[start + 1] != '?') return .{ .body_start = start + 1, .capture_index = regexCaptureIndex(pattern, start), .kind = .capturing };
    if (start + 2 < end and pattern[start + 2] == ':') return .{ .body_start = start + 3, .capture_index = null, .kind = .noncapturing };
    if (start + 2 < end and pattern[start + 2] == '=') return .{ .body_start = start + 3, .capture_index = null, .kind = .positive_lookahead };
    if (start + 2 < end and pattern[start + 2] == '!') return .{ .body_start = start + 3, .capture_index = null, .kind = .negative_lookahead };
    if (start + 3 < end and pattern[start + 2] == '<' and pattern[start + 3] == '=') return .{ .body_start = start + 4, .capture_index = null, .kind = .positive_lookbehind };
    if (start + 3 < end and pattern[start + 2] == '<' and pattern[start + 3] == '!') return .{ .body_start = start + 4, .capture_index = null, .kind = .negative_lookbehind };
    if (start + 3 < end and pattern[start + 2] == '<' and pattern[start + 3] != '=' and pattern[start + 3] != '!') {
        const name_end = std.mem.indexOfScalarPos(u8, pattern, start + 3, '>') orelse return null;
        if (name_end >= end - 1 or name_end == start + 3) return null;
        return .{ .body_start = name_end + 1, .capture_index = regexCaptureIndex(pattern, start), .kind = .capturing };
    }
    var cursor = start + 2;
    var enable: u3 = 0;
    var disable: u3 = 0;
    var subtract = false;
    var saw_modifier = false;
    while (cursor < end and pattern[cursor] != ':') : (cursor += 1) {
        if (pattern[cursor] == '-' and !subtract) {
            subtract = true;
            continue;
        }
        const bit: u3 = switch (pattern[cursor]) {
            'i' => 1,
            'm' => 2,
            's' => 4,
            else => return null,
        };
        if ((enable | disable) & bit != 0) return null;
        if (subtract) disable |= bit else enable |= bit;
        saw_modifier = true;
    }
    if (!saw_modifier or cursor >= end or pattern[cursor] != ':' or (subtract and disable == 0) or (enable & disable) != 0) return null;
    return .{ .body_start = cursor + 1, .capture_index = null, .kind = .noncapturing, .enable_modifiers = enable, .disable_modifiers = disable };
}

fn regexGroupCaptures(pattern: []const u8, start: usize) bool {
    if (start + 1 >= pattern.len or pattern[start] != '(') return false;
    if (pattern[start + 1] != '?') return true;
    return start + 3 < pattern.len and pattern[start + 2] == '<' and pattern[start + 3] != '=' and pattern[start + 3] != '!';
}

fn regexCaptureIndex(pattern: []const u8, target: usize) usize {
    var count: usize = 0;
    var cursor: usize = 0;
    var in_class = false;
    var escaped = false;
    while (cursor < target) : (cursor += 1) {
        const byte = pattern[cursor];
        if (escaped) {
            escaped = false;
            continue;
        }
        if (byte == '\\') {
            escaped = true;
            continue;
        }
        if (byte == '[') in_class = true else if (byte == ']') in_class = false;
        if (!in_class and byte == '(' and regexGroupCaptures(pattern, cursor)) count += 1;
    }
    return count;
}

fn regexCaptureCount(pattern: []const u8) usize {
    return regexCaptureIndex(pattern, pattern.len);
}

fn regexNamedCapture(pattern: []const u8, capture_index: usize) ?[]const u8 {
    var current: usize = 0;
    var cursor: usize = 0;
    var in_class = false;
    var escaped = false;
    while (cursor < pattern.len) : (cursor += 1) {
        const byte = pattern[cursor];
        if (escaped) {
            escaped = false;
            continue;
        }
        if (byte == '\\') {
            escaped = true;
            continue;
        }
        if (byte == '[') in_class = true else if (byte == ']') in_class = false;
        if (in_class or byte != '(' or !regexGroupCaptures(pattern, cursor)) continue;
        if (current == capture_index) {
            if (cursor + 3 < pattern.len and pattern[cursor + 1] == '?' and pattern[cursor + 2] == '<') {
                const name_end = std.mem.indexOfScalarPos(u8, pattern, cursor + 3, '>') orelse return null;
                return pattern[cursor + 3 .. name_end];
            }
            return null;
        }
        current += 1;
    }
    return null;
}

fn regexCaptureNameCodepoint(name: []const u8, cursor: *usize) ?u21 {
    if (cursor.* >= name.len) return null;
    if (name[cursor.*] != '\\') {
        const scalar = runtimeStringDecode(name, cursor.*);
        cursor.* += scalar.length;
        if (scalar.value > 0x10ffff or (scalar.value >= 0xd800 and scalar.value <= 0xdfff)) return null;
        return @intCast(scalar.value);
    }
    const start = cursor.*;
    if (start + 2 >= name.len or name[start + 1] != 'u') return null;
    if (name[start + 2] == '{') {
        const brace_end = std.mem.indexOfScalarPos(u8, name, start + 3, '}') orelse return null;
        if (brace_end == start + 3) return null;
        const value = std.fmt.parseInt(u32, name[start + 3 .. brace_end], 16) catch return null;
        if (value > 0x10ffff or (value >= 0xd800 and value <= 0xdfff)) return null;
        cursor.* = brace_end + 1;
        return @intCast(value);
    }
    if (start + 6 > name.len) return null;
    const high = std.fmt.parseInt(u16, name[start + 2 .. start + 6], 16) catch return null;
    cursor.* = start + 6;
    if (high >= 0xd800 and high <= 0xdbff and cursor.* + 6 <= name.len and name[cursor.*] == '\\' and name[cursor.* + 1] == 'u') {
        const low = std.fmt.parseInt(u16, name[cursor.* + 2 .. cursor.* + 6], 16) catch return null;
        if (low >= 0xdc00 and low <= 0xdfff) {
            cursor.* += 6;
            return @intCast(0x10000 + ((@as(u32, high) - 0xd800) << 10) + (@as(u32, low) - 0xdc00));
        }
    }
    if (high >= 0xd800 and high <= 0xdfff) return null;
    return @intCast(high);
}

fn regexCaptureNameEqual(left: []const u8, right: []const u8) bool {
    var left_cursor: usize = 0;
    var right_cursor: usize = 0;
    while (left_cursor < left.len and right_cursor < right.len) {
        const left_value = regexCaptureNameCodepoint(left, &left_cursor) orelse return false;
        const right_value = regexCaptureNameCodepoint(right, &right_cursor) orelse return false;
        if (left_value != right_value) return false;
    }
    return left_cursor == left.len and right_cursor == right.len;
}

fn regexCaptureNameDecode(name: []const u8, output: []u8) ?[]const u8 {
    var cursor: usize = 0;
    var length: usize = 0;
    while (cursor < name.len) {
        const codepoint = regexCaptureNameCodepoint(name, &cursor) orelse return null;
        var encoded: [4]u8 = undefined;
        const encoded_length = std.unicode.utf8Encode(codepoint, encoded[0..]) catch return null;
        if (length + encoded_length > output.len) return null;
        @memcpy(output[length .. length + encoded_length], encoded[0..encoded_length]);
        length += encoded_length;
    }
    return output[0..length];
}

fn regexNamedCaptureIndex(pattern: []const u8, name: []const u8) ?usize {
    const capture_count = regexCaptureCount(pattern);
    for (0..capture_count) |capture_index| {
        if (regexNamedCapture(pattern, capture_index)) |candidate| if (regexCaptureNameEqual(candidate, name)) return capture_index;
    }
    return null;
}

fn regexCapturePosition(pattern: []const u8, capture_index: usize) ?usize {
    var current: usize = 0;
    var cursor: usize = 0;
    var in_class = false;
    var escaped = false;
    while (cursor < pattern.len) : (cursor += 1) {
        const byte = pattern[cursor];
        if (escaped) {
            escaped = false;
            continue;
        }
        if (byte == '\\') {
            escaped = true;
            continue;
        }
        if (byte == '[') in_class = true else if (byte == ']') in_class = false;
        if (in_class or byte != '(' or !regexGroupCaptures(pattern, cursor)) continue;
        if (current == capture_index) return cursor;
        current += 1;
    }
    return null;
}

fn regexCaptureAlternativesDisjoint(pattern: []const u8, left_position: usize, right_position: usize) bool {
    const left = @min(left_position, right_position);
    const right = @max(left_position, right_position);
    var depth: usize = 0;
    var left_depth: usize = 0;
    var right_depth: usize = 0;
    var cursor: usize = 0;
    var in_class = false;
    var escaped = false;
    while (cursor <= right and cursor < pattern.len) : (cursor += 1) {
        const byte = pattern[cursor];
        if (escaped) {
            escaped = false;
            continue;
        }
        if (byte == '\\') {
            escaped = true;
            continue;
        }
        if (byte == '[') in_class = true else if (byte == ']') in_class = false;
        if (in_class) continue;
        if (cursor == left) left_depth = depth;
        if (cursor == right) right_depth = depth;
        if (byte == '(') depth += 1 else if (byte == ')' and depth > 0) depth -= 1;
    }
    const shared_depth = @min(left_depth, right_depth);
    depth = 0;
    cursor = 0;
    in_class = false;
    escaped = false;
    while (cursor < right and cursor < pattern.len) : (cursor += 1) {
        const byte = pattern[cursor];
        if (escaped) {
            escaped = false;
            continue;
        }
        if (byte == '\\') {
            escaped = true;
            continue;
        }
        if (byte == '[') in_class = true else if (byte == ']') in_class = false;
        if (in_class) continue;
        if (byte == '(') depth += 1 else if (byte == ')' and depth > 0) depth -= 1 else if (cursor > left and byte == '|' and depth <= shared_depth) return true;
    }
    return false;
}

const RegexPropertyEscape = struct {
    expression: []const u8,
    negated: bool,
    next: usize,
};

fn regexPropertyEscape(pattern: []const u8, start: usize, end: usize) ?RegexPropertyEscape {
    if (start + 3 >= end or pattern[start] != '\\' or (pattern[start + 1] != 'p' and pattern[start + 1] != 'P') or pattern[start + 2] != '{') return null;
    const property_end = std.mem.indexOfScalarPos(u8, pattern, start + 3, '}') orelse return null;
    if (property_end + 1 > end or property_end == start + 3) return null;
    return .{ .expression = pattern[start + 3 .. property_end], .negated = pattern[start + 1] == 'P', .next = property_end + 1 };
}

fn regexLineTerminator(byte: u8) bool {
    return byte == '\n' or byte == '\r';
}

fn regexCodepointLineTerminator(codepoint: u32) bool {
    return codepoint == '\n' or codepoint == '\r' or codepoint == 0x2028 or codepoint == 0x2029;
}

fn regexWordByte(byte: u8) bool {
    return std.ascii.isAlphanumeric(byte) or byte == '_';
}

fn regexUnicodeWord(codepoint: u21, ignore_case: bool) bool {
    if (codepoint <= 0x7f and regexWordByte(@intCast(codepoint))) return true;
    if (!ignore_case) return false;
    const folded = unicode_string_case.fold(codepoint);
    return folded.length == 1 and folded.values[0] <= 0x7f and regexWordByte(@intCast(folded.values[0]));
}

fn regexUnicodeWhitespace(codepoint: u21) bool {
    return codepoint == 0x0009 or codepoint == 0x000a or codepoint == 0x000b or codepoint == 0x000c or codepoint == 0x000d or codepoint == 0x0020 or codepoint == 0x00a0 or codepoint == 0x1680 or (codepoint >= 0x2000 and codepoint <= 0x200a) or codepoint == 0x2028 or codepoint == 0x2029 or codepoint == 0x202f or codepoint == 0x205f or codepoint == 0x3000 or codepoint == 0xfeff;
}

fn regexPreviousCodepoint(input: []const u8, position: usize) ?u21 {
    if (position == 0 or position > input.len) return null;
    var start = position - 1;
    while (start > 0 and input[start] & 0xc0 == 0x80) : (start -= 1) {}
    const scalar = runtimeStringDecode(input, start);
    if (start + scalar.length != position) return @intCast(input[position - 1]);
    return @intCast(scalar.value);
}

fn regexStartAssertionMatches(input: []const u8, position: usize, multiline: bool) bool {
    if (position == 0) return true;
    if (!multiline or position > input.len) return false;
    return if (regexPreviousCodepoint(input, position)) |codepoint| regexCodepointLineTerminator(codepoint) else false;
}

fn regexEndAssertionMatches(input: []const u8, position: usize, multiline: bool) bool {
    if (position == input.len) return true;
    if (position > input.len) return false;
    const scalar = runtimeStringDecode(input, position);
    if (!regexCodepointLineTerminator(scalar.value)) return false;
    if (multiline) return true;
    if (position + scalar.length == input.len) return true;
    return scalar.value == '\r' and position + scalar.length < input.len and runtimeStringDecode(input, position + scalar.length).value == '\n' and position + scalar.length + 1 == input.len;
}

fn regexMatchBackreference(input: []const u8, input_state: RegexState, capture: RegexCapture, options: RegexOptions, out: *RegexStates) Error!void {
    if (!capture.matched()) {
        out.add(input_state);
        return;
    }
    const capture_start: usize = @intCast(capture.start);
    const capture_end: usize = @intCast(capture.end);
    const expected = input[capture_start..capture_end];
    var expected_cursor: usize = 0;
    var actual_cursor = input_state.end;
    while (expected_cursor < expected.len) {
        if (actual_cursor >= input.len) return;
        const expected_scalar = runtimeStringDecode(expected, expected_cursor);
        const actual_scalar = runtimeStringDecode(input, actual_cursor);
        if (!regexCodepointEqual(@intCast(expected_scalar.value), @intCast(actual_scalar.value), options.ignore_case)) return;
        expected_cursor += expected_scalar.length;
        actual_cursor += actual_scalar.length;
    }
    var matched = input_state;
    matched.end = actual_cursor;
    out.add(matched);
}

fn regexEscapeCodepoint(pattern: []const u8, start: usize, end: usize) ?u21 {
    if (start + 1 >= end or pattern[start] != '\\') return null;
    if (pattern[start + 1] == 'x' and end == start + 4) {
        return std.fmt.parseInt(u21, pattern[start + 2 .. end], 16) catch null;
    }
    if (pattern[start + 1] == 'c' and end == start + 3 and std.ascii.isAlphabetic(pattern[start + 2]))
        return @intCast(pattern[start + 2] & 0x1f);
    if (pattern[start + 1] != 'u') return null;
    if (end == start + 12 and pattern[start + 6] == '\\' and pattern[start + 7] == 'u') {
        const high = std.fmt.parseInt(u16, pattern[start + 2 .. start + 6], 16) catch return null;
        const low = std.fmt.parseInt(u16, pattern[start + 8 .. start + 12], 16) catch return null;
        if (high < 0xd800 or high > 0xdbff or low < 0xdc00 or low > 0xdfff) return null;
        return @intCast(0x10000 + ((@as(u32, high) - 0xd800) << 10) + (@as(u32, low) - 0xdc00));
    }
    const digits = if (start + 2 < end and pattern[start + 2] == '{') pattern[start + 3 .. end - 1] else pattern[start + 2 .. end];
    if (digits.len == 0) return null;
    const codepoint = std.fmt.parseInt(u32, digits, 16) catch return null;
    if (codepoint > 0x10ffff) return null;
    return @intCast(codepoint);
}

fn regexCodepointEqual(left: u21, right: u21, ignore_case: bool) bool {
    if (left == right) return true;
    if (!ignore_case) return false;
    const left_fold = unicode_string_case.fold(left);
    const right_fold = unicode_string_case.fold(right);
    if (left_fold.length == 1 and right_fold.length == 1 and left_fold.values[0] == right_fold.values[0]) return true;
    const left_upper = unicode_string_case.upper(left);
    const right_upper = unicode_string_case.upper(right);
    if (left_upper.length == 1 and right_upper.length == 1 and left_upper.values[0] == right_upper.values[0]) return true;
    const left_lower = unicode_string_case.lower(left);
    const right_lower = unicode_string_case.lower(right);
    return left_lower.length == 1 and right_lower.length == 1 and left_lower.values[0] == right_lower.values[0];
}

fn regexCaptureNameValid(name: []const u8) bool {
    if (name.len == 0) return false;
    var cursor: usize = 0;
    const first = regexCaptureNameCodepoint(name, &cursor) orelse return false;
    if (first != '_' and first != '$' and !unicode_identifier.isIdentifierStart(first)) return false;
    while (cursor < name.len) {
        const codepoint = regexCaptureNameCodepoint(name, &cursor) orelse return false;
        if (codepoint != '_' and codepoint != '$' and codepoint != 0x200c and codepoint != 0x200d and !unicode_identifier.isIdentifierContinue(codepoint)) return false;
    }
    return cursor == name.len;
}

fn regexClassSyntaxValid(source: []const u8, unicode_sets: bool) bool {
    if (unicode_sets) return true;
    var cursor: usize = if (source.len > 0 and source[0] == '^') 1 else 0;
    while (cursor < source.len) {
        const first_property = regexPropertyEscape(source, cursor, source.len);
        const first = if (first_property) |property|
            RegexUnicodeClassAtom{ .value = 0, .next = property.next, .literal = false }
        else
            regexUnicodeClassAtom(source, cursor) orelse return false;
        if (first.next < source.len and source[first.next] == '-' and first.next + 1 < source.len) {
            const last_start = first.next + 1;
            const last_property = regexPropertyEscape(source, last_start, source.len);
            const last = if (last_property) |property|
                RegexUnicodeClassAtom{ .value = 0, .next = property.next, .literal = false }
            else
                regexUnicodeClassAtom(source, last_start) orelse return false;
            if (!first.literal or !last.literal or first.value > last.value) return false;
            cursor = last.next;
        } else {
            cursor = first.next;
        }
    }
    return true;
}

fn regexTermsValid(pattern: []const u8, start: usize, end: usize, options: RegexOptions, depth: usize) bool {
    if (depth > 32) return false;
    var cursor = start;
    while (cursor < end) {
        if (pattern[cursor] == '|') {
            cursor += 1;
            continue;
        }
        if (pattern[cursor] == '*' or pattern[cursor] == '+' or pattern[cursor] == '?') return false;
        if (options.unicode and (pattern[cursor] == ']' or pattern[cursor] == '}')) return false;
        if (pattern[cursor] == '{') {
            if (options.unicode or regexLooksLikeBraceQuantifier(pattern, cursor, end)) return false;
            cursor += 1;
            continue;
        }
        const atom_end = regexAtomEnd(pattern, cursor, end, options) orelse return false;
        var assertion = pattern[cursor] == '^' or pattern[cursor] == '$' or
            (pattern[cursor] == '\\' and cursor + 1 < atom_end and (pattern[cursor + 1] == 'b' or pattern[cursor + 1] == 'B'));
        var legacy_quantifiable_lookahead = false;
        if (pattern[cursor] == '(') {
            const group = regexGroupInfo(pattern, cursor, atom_end) orelse return false;
            if (!regexTermsValid(pattern, group.body_start, atom_end - 1, options, depth + 1)) return false;
            assertion = group.kind != .capturing and group.kind != .noncapturing;
            legacy_quantifiable_lookahead = group.kind == .positive_lookahead or group.kind == .negative_lookahead;
        }
        const quantifier = regexQuantifierAt(pattern, atom_end, end);
        if (quantifier) |value| {
            if (assertion and (options.unicode or !legacy_quantifiable_lookahead)) return false;
            cursor = value.next;
        } else {
            if (atom_end < end and pattern[atom_end] == '{' and regexLooksLikeBraceQuantifier(pattern, atom_end, end)) return false;
            cursor = atom_end;
        }
    }
    return true;
}

fn regexPatternValid(pattern: []const u8, unicode: bool, unicode_sets: bool) bool {
    var group_depth: usize = 0;
    var class_depth: usize = 0;
    var cursor: usize = 0;
    while (cursor < pattern.len) : (cursor += 1) {
        const byte = pattern[cursor];
        if (byte == '\\') {
            if (cursor + 1 >= pattern.len) return false;
            const in_class = class_depth > 0;
            if (pattern[cursor + 1] == 'q') {
                if (!unicode_sets or class_depth == 0 or cursor + 2 >= pattern.len or pattern[cursor + 2] != '{') return false;
                const disjunction_end = std.mem.indexOfScalarPos(u8, pattern, cursor + 3, '}') orelse return false;
                cursor = disjunction_end;
                continue;
            }
