                if (!unicode) return false;
                const property = regexPropertyEscape(pattern, cursor, pattern.len) orelse return false;
                const string_property = if (unicode_sets) unicode_regex.stringProperty(property.expression) else null;
                if (unicode_regex.matches(property.expression, 0) == null and string_property == null) return false;
                if (property.negated and string_property != null) return false;
                cursor = property.next - 1;
                continue;
            }
