                if (cursor + 2 >= pattern.len or !std.ascii.isAlphabetic(pattern[cursor + 2])) return false;
                cursor += 2;
                continue;
            }
            if (pattern[cursor + 1] == 'u') {
                const escape_end = if (cursor + 2 < pattern.len and pattern[cursor + 2] == '{')
                    (std.mem.indexOfScalarPos(u8, pattern, cursor + 3, '}') orelse return false) + 1
                else if (cursor + 6 <= pattern.len)
                    cursor + 6
                else
                    return false;
                if (regexEscapeCodepoint(pattern, cursor, escape_end) == null) return false;
                cursor = escape_end - 1;
                continue;
            }
            if (unicode) {
                const escaped = pattern[cursor + 1];
                if (escaped == '0') {
                    if (cursor + 2 < pattern.len and std.ascii.isDigit(pattern[cursor + 2])) return false;
                    cursor += 1;
                    continue;
                }
                if (std.ascii.isDigit(escaped)) {
                    if (in_class) return false;
                    cursor += 1;
                    continue;
                }
                const class_escape = escaped == 'd' or escaped == 'D' or escaped == 's' or escaped == 'S' or escaped == 'w' or escaped == 'W';
                const control_escape = escaped == 'f' or escaped == 'n' or escaped == 'r' or escaped == 't' or escaped == 'v';
                const assertion_escape = !in_class and (escaped == 'b' or escaped == 'B');
                const class_backspace = in_class and escaped == 'b';
                const named_reference = !in_class and escaped == 'k' and cursor + 2 < pattern.len and pattern[cursor + 2] == '<';
                const syntax_escape = escaped == '^' or escaped == '$' or escaped == '\\' or escaped == '.' or escaped == '*' or escaped == '+' or escaped == '?' or escaped == '(' or escaped == ')' or escaped == '[' or escaped == ']' or escaped == '{' or escaped == '}' or escaped == '|' or escaped == '/' or (in_class and escaped == '-');
                if (!class_escape and !control_escape and !assertion_escape and !class_backspace and !named_reference and !syntax_escape) return false;
            }
            cursor += 1;
            continue;
        }
        if (class_depth > 0) {
            if (unicode_sets and byte == '[') class_depth += 1 else if (byte == ']') class_depth -= 1;
            continue;
        }
        if (byte == '[') {
            class_depth = 1;
            continue;
        }
        if (byte == '(') {
            group_depth += 1;
            if (cursor + 1 < pattern.len and pattern[cursor + 1] == '?') {
                if (cursor + 2 >= pattern.len) return false;
                if (pattern[cursor + 2] == ':' or pattern[cursor + 2] == '=' or pattern[cursor + 2] == '!') continue;
                if (pattern[cursor + 2] == 'i' or pattern[cursor + 2] == 'm' or pattern[cursor + 2] == 's' or pattern[cursor + 2] == '-') {
                    if (regexGroupInfo(pattern, cursor, pattern.len) == null) return false;
                    continue;
                }
                if (pattern[cursor + 2] != '<' or cursor + 3 >= pattern.len) return false;
                if (pattern[cursor + 3] == '=' or pattern[cursor + 3] == '!') continue;
                const name_end = std.mem.indexOfScalarPos(u8, pattern, cursor + 3, '>') orelse return false;
                if (!regexCaptureNameValid(pattern[cursor + 3 .. name_end])) return false;
            }
            continue;
        }
        if (byte == ')') {
            if (group_depth == 0) return false;
            group_depth -= 1;
        }
    }
    if (class_depth != 0 or group_depth != 0) return false;
    if (!regexTermsValid(pattern, 0, pattern.len, .{ .unicode = unicode, .unicode_sets = unicode_sets }, 0)) return false;
    cursor = 0;
    while (cursor < pattern.len) {
        if (pattern[cursor] == '\\') {
            cursor += @min(@as(usize, 2), pattern.len - cursor);
            continue;
        }
        if (pattern[cursor] != '[') {
            cursor += 1;
            continue;
        }
        const class_end = regexAtomEnd(pattern, cursor, pattern.len, .{ .unicode = unicode, .unicode_sets = unicode_sets }) orelse return false;
        if (!regexClassSyntaxValid(pattern[cursor + 1 .. class_end - 1], unicode_sets)) return false;
        cursor = class_end;
    }
    const capture_count = regexCaptureCount(pattern);
    if (capture_count > max_regex_captures) return false;
    for (0..capture_count) |capture_index| {
        const name = regexNamedCapture(pattern, capture_index) orelse continue;
        for (0..capture_index) |previous_index| {
            if (regexNamedCapture(pattern, previous_index)) |previous| {
                if (!regexCaptureNameEqual(name, previous)) continue;
                const left = regexCapturePosition(pattern, previous_index) orelse return false;
                const right = regexCapturePosition(pattern, capture_index) orelse return false;
                if (!regexCaptureAlternativesDisjoint(pattern, left, right)) return false;
            }
        }
    }
    cursor = 0;
    var in_class = false;
    while (cursor < pattern.len) : (cursor += 1) {
        if (pattern[cursor] == '[') {
            in_class = true;
            continue;
        }
        if (pattern[cursor] == ']' and in_class) {
            in_class = false;
            continue;
        }
        if (pattern[cursor] != '\\' or cursor + 1 >= pattern.len) continue;
        if (in_class) {
            cursor += 1;
            continue;
        }
        if (pattern[cursor + 1] >= '1' and pattern[cursor + 1] <= '9') {
            var reference: usize = 0;
            cursor += 1;
            while (cursor < pattern.len and pattern[cursor] >= '0' and pattern[cursor] <= '9') : (cursor += 1) {
                if (reference <= max_regex_captures) reference = reference * 10 + pattern[cursor] - '0';
            }
            if (unicode and (reference == 0 or reference > capture_count)) return false;
            cursor -= 1;
            continue;
        }
        if (pattern[cursor + 1] == 'k' and cursor + 2 < pattern.len and pattern[cursor + 2] == '<') {
            const name_end = std.mem.indexOfScalarPos(u8, pattern, cursor + 3, '>') orelse return false;
            const name = pattern[cursor + 3 .. name_end];
            if (!regexCaptureNameValid(name) or regexNamedCaptureIndex(pattern, name) == null) return false;
            cursor = name_end;
            continue;
        }
        cursor += 1;
    }
    return true;
}

fn regexClassMatches(source: []const u8, input: u8, ignore_case: bool) bool {
    var cursor: usize = 0;
    const negated = source.len > 0 and source[0] == '^';
    if (negated) cursor = 1;
    var matched = false;
    while (cursor < source.len) {
        const first = regexClassAtom(source, cursor) orelse break;
        if (first.literal and first.next < source.len and source[first.next] == '-' and first.next + 1 < source.len) {
            const last = regexClassAtom(source, first.next + 1) orelse break;
            if (!last.literal) {
                if (regexClassAtomMatches(first, input, ignore_case)) matched = true;
                cursor = first.next;
                continue;
            }
            const value = if (ignore_case) std.ascii.toLower(input) else input;
            const low = if (ignore_case) std.ascii.toLower(first.value) else first.value;
            const high = if (ignore_case) std.ascii.toLower(last.value) else last.value;
            if (value >= low and value <= high) matched = true;
            cursor = last.next;
        } else {
            if (regexClassAtomMatches(first, input, ignore_case)) matched = true;
            cursor = first.next;
        }
    }
    return if (negated) !matched else matched;
}

const RegexClassAtom = struct {
    value: u8,
    next: usize,
    literal: bool,
};

fn regexClassAtom(source: []const u8, start: usize) ?RegexClassAtom {
    if (start >= source.len) return null;
    if (source[start] != '\\') return .{ .value = source[start], .next = start + 1, .literal = true };
    if (start + 1 >= source.len) return null;
    const escaped = source[start + 1];
    if (escaped == 'c' and start + 2 < source.len and std.ascii.isAlphabetic(source[start + 2]))
        return .{ .value = source[start + 2] & 0x1f, .next = start + 3, .literal = true };
    if (escaped >= '0' and escaped <= '7') {
        const maximum_digits: usize = if (escaped <= '3') 3 else 2;
        var octal_end = start + 2;
        while (octal_end < source.len and octal_end - (start + 1) < maximum_digits and source[octal_end] >= '0' and source[octal_end] <= '7') : (octal_end += 1) {}
        const value = std.fmt.parseInt(u8, source[start + 1 .. octal_end], 8) catch return null;
        return .{ .value = value, .next = octal_end, .literal = true };
    }
    return switch (escaped) {
        'd', 'D', 's', 'S', 'w', 'W' => .{ .value = escaped, .next = start + 2, .literal = false },
        'b' => .{ .value = 0x08, .next = start + 2, .literal = true },
        'n' => .{ .value = '\n', .next = start + 2, .literal = true },
        'r' => .{ .value = '\r', .next = start + 2, .literal = true },
        't' => .{ .value = '\t', .next = start + 2, .literal = true },
        'f' => .{ .value = 0x0c, .next = start + 2, .literal = true },
        'v' => .{ .value = 0x0b, .next = start + 2, .literal = true },
        '0' => .{ .value = 0, .next = start + 2, .literal = true },
        else => .{ .value = escaped, .next = start + 2, .literal = true },
    };
}

fn regexClassAtomMatches(atom: RegexClassAtom, input: u8, ignore_case: bool) bool {
    if (atom.literal) return regexByteEqual(atom.value, input, ignore_case);
    return switch (atom.value) {
        'd' => std.ascii.isDigit(input),
        'D' => !std.ascii.isDigit(input),
        's' => std.ascii.isWhitespace(input),
        'S' => !std.ascii.isWhitespace(input),
        'w' => regexWordByte(input),
        'W' => !regexWordByte(input),
        else => false,
    };
}

const RegexUnicodeClassAtom = struct {
    value: u21,
    next: usize,
    literal: bool,
};

fn regexUnicodeClassAtom(source: []const u8, start: usize) ?RegexUnicodeClassAtom {
    if (start >= source.len) return null;
    if (source[start] != '\\') {
        const scalar = runtimeStringDecode(source, start);
        return .{ .value = @intCast(scalar.value), .next = start + scalar.length, .literal = true };
    }
    if (start + 1 >= source.len) return null;
    const escaped = source[start + 1];
    if (escaped == 'c' and start + 2 < source.len and std.ascii.isAlphabetic(source[start + 2]))
        return .{ .value = @intCast(source[start + 2] & 0x1f), .next = start + 3, .literal = true };
    if (escaped >= '0' and escaped <= '7') {
        const maximum_digits: usize = if (escaped <= '3') 3 else 2;
        var octal_end = start + 2;
        while (octal_end < source.len and octal_end - (start + 1) < maximum_digits and source[octal_end] >= '0' and source[octal_end] <= '7') : (octal_end += 1) {}
        const value = std.fmt.parseInt(u21, source[start + 1 .. octal_end], 8) catch return null;
        return .{ .value = value, .next = octal_end, .literal = true };
    }
    if (escaped == 'x' and start + 4 <= source.len) {
        const value = std.fmt.parseInt(u21, source[start + 2 .. start + 4], 16) catch return null;
        return .{ .value = value, .next = start + 4, .literal = true };
    }
    if (escaped == 'u') {
        const escape_end = if (start + 2 < source.len and source[start + 2] == '{')
            (std.mem.indexOfScalarPos(u8, source, start + 3, '}') orelse return null) + 1
        else if (start + 6 <= source.len)
            start + 6
        else
            return null;
        const value = regexEscapeCodepoint(source, start, escape_end) orelse return null;
        return .{ .value = value, .next = escape_end, .literal = true };
    }
    return switch (escaped) {
        'd', 'D', 's', 'S', 'w', 'W' => .{ .value = escaped, .next = start + 2, .literal = false },
        'b' => .{ .value = 0x08, .next = start + 2, .literal = true },
        'n' => .{ .value = '\n', .next = start + 2, .literal = true },
        'r' => .{ .value = '\r', .next = start + 2, .literal = true },
        't' => .{ .value = '\t', .next = start + 2, .literal = true },
        'f' => .{ .value = 0x0c, .next = start + 2, .literal = true },
        'v' => .{ .value = 0x0b, .next = start + 2, .literal = true },
        '0' => .{ .value = 0, .next = start + 2, .literal = true },
        else => .{ .value = escaped, .next = start + 2, .literal = true },
    };
}

fn regexUnicodeClassAtomMatches(atom: RegexUnicodeClassAtom, input: u21, ignore_case: bool) bool {
    if (atom.literal) return regexCodepointEqual(atom.value, input, ignore_case);
    return switch (@as(u8, @intCast(atom.value))) {
        'd' => input >= '0' and input <= '9',
        'D' => input < '0' or input > '9',
        's' => regexUnicodeWhitespace(input),
        'S' => !regexUnicodeWhitespace(input),
        'w' => regexUnicodeWord(input, ignore_case),
        'W' => !regexUnicodeWord(input, ignore_case),
        else => false,
    };
}

fn regexUnicodeClassMatches(source: []const u8, input: u21, ignore_case: bool, unicode_sets: bool) bool {
    var cursor: usize = 0;
    const negated = source.len > 0 and source[0] == '^';
    if (negated) cursor = 1;
    const body = source[cursor..];
    const matched = if (unicode_sets) regexUnicodeSetExpressionMatches(body, input, ignore_case) else regexUnicodeClassUnionMatches(body, input, ignore_case, false);
    return if (negated) !matched else matched;
}

const RegexSetOperator = enum { intersection, subtraction };

fn regexUnicodeSetExpressionMatches(source: []const u8, input: u21, ignore_case: bool) bool {
    var segment_start: usize = 0;
    var cursor: usize = 0;
    var nesting: usize = 0;
    var operator: ?RegexSetOperator = null;
    var result = false;
    var have_segment = false;
    while (cursor <= source.len) {
        var found_operator: ?RegexSetOperator = null;
        if (cursor + 1 < source.len and nesting == 0) {
            if (source[cursor] == '&' and source[cursor + 1] == '&') found_operator = .intersection;
            if (source[cursor] == '-' and source[cursor + 1] == '-') found_operator = .subtraction;
        }
        if (cursor == source.len or found_operator != null) {
            const segment_match = regexUnicodeClassUnionMatches(source[segment_start..cursor], input, ignore_case, true);
            if (!have_segment) {
                result = segment_match;
                have_segment = true;
            } else switch (operator.?) {
                .intersection => result = result and segment_match,
                .subtraction => result = result and !segment_match,
            }
            if (cursor == source.len) break;
            if (operator != null and operator.? != found_operator.?) return false;
            operator = found_operator;
            cursor += 2;
            segment_start = cursor;
            continue;
        }
        if (source[cursor] == '\\') {
            if (regexPropertyEscape(source, cursor, source.len)) |property| {
                cursor = property.next;
                continue;
            }
            cursor += @min(@as(usize, 2), source.len - cursor);
            continue;
        }
        if (source[cursor] == '[') nesting += 1 else if (source[cursor] == ']' and nesting > 0) nesting -= 1;
        cursor += 1;
    }
    return have_segment and result;
}

fn regexNestedClassEnd(source: []const u8, start: usize) ?usize {
    if (start >= source.len or source[start] != '[') return null;
    var nesting: usize = 1;
    var cursor = start + 1;
    var escaped = false;
    while (cursor < source.len) : (cursor += 1) {
        if (escaped) {
            escaped = false;
            continue;
        }
        if (source[cursor] == '\\') {
            escaped = true;
            continue;
        }
        if (source[cursor] == '[') nesting += 1 else if (source[cursor] == ']') {
            nesting -= 1;
            if (nesting == 0) return cursor + 1;
        }
    }
    return null;
}

fn regexUnicodeClassUnionMatches(source: []const u8, input: u21, ignore_case: bool, unicode_sets: bool) bool {
    var cursor: usize = 0;
    var matched = false;
    while (cursor < source.len) {
        if (unicode_sets and cursor + 2 < source.len and source[cursor] == '\\' and source[cursor + 1] == 'q' and source[cursor + 2] == '{') {
            const disjunction_end = std.mem.indexOfScalarPos(u8, source, cursor + 3, '}') orelse break;
            cursor = disjunction_end + 1;
            continue;
        }
        if (unicode_sets and source[cursor] == '[') {
            const nested_end = regexNestedClassEnd(source, cursor) orelse break;
            if (regexUnicodeClassMatches(source[cursor + 1 .. nested_end - 1], input, ignore_case, true)) matched = true;
            cursor = nested_end;
            continue;
        }
        if (regexPropertyEscape(source, cursor, source.len)) |property| {
            if (unicode_regex.matches(property.expression, input)) |property_match| {
                if (property_match != property.negated) matched = true;
            }
            cursor = property.next;
            continue;
        }
        const first = regexUnicodeClassAtom(source, cursor) orelse break;
        if (first.literal and first.next < source.len and source[first.next] == '-' and first.next + 1 < source.len) {
            const last = regexUnicodeClassAtom(source, first.next + 1) orelse break;
            if (!last.literal) {
                if (regexUnicodeClassAtomMatches(first, input, ignore_case)) matched = true;
                cursor = first.next;
                continue;
            }
            const folded_input = regexFoldCodepoint(input, ignore_case);
            const low = regexFoldCodepoint(first.value, ignore_case);
            const high = regexFoldCodepoint(last.value, ignore_case);
            if (folded_input >= low and folded_input <= high) matched = true;
            cursor = last.next;
        } else {
            if (regexUnicodeClassAtomMatches(first, input, ignore_case)) matched = true;
            cursor = first.next;
        }
    }
    return matched;
}

fn regexFoldCodepoint(codepoint: u21, ignore_case: bool) u21 {
    if (!ignore_case) return codepoint;
    const folded = unicode_string_case.fold(codepoint);
    return if (folded.length == 1) folded.values[0] else codepoint;
}

const RegexStringEnds = struct {
    values: [max_regex_states]usize = undefined,
    count: usize = 0,

    fn add(self: *RegexStringEnds, value: usize) void {
        for (self.values[0..self.count]) |existing| if (existing == value) return;
        if (self.count >= self.values.len) return;
        var insert_at: usize = 0;
        while (insert_at < self.count and self.values[insert_at] < value) : (insert_at += 1) {}
        var move = self.count;
        while (move > insert_at) : (move -= 1) self.values[move] = self.values[move - 1];
        self.values[insert_at] = value;
        self.count += 1;
    }
};

fn regexUnicodeClassStringMatches(source: []const u8, input: []const u8, input_start: usize, ignore_case: bool, out: *RegexStringEnds) void {
    var cursor: usize = 0;
    while (cursor + 3 < source.len) : (cursor += 1) {
        if (regexPropertyEscape(source, cursor, source.len)) |property| {
            if (!property.negated) {
                if (unicode_regex.stringProperty(property.expression)) |string_property| {
                    regexUnicodeStringPropertyMatches(string_property, input, input_start, ignore_case, out);
                }
            }
            cursor = property.next - 1;
            continue;
        }
        if (source[cursor] != '\\' or source[cursor + 1] != 'q' or source[cursor + 2] != '{') continue;
        const disjunction_end = std.mem.indexOfScalarPos(u8, source, cursor + 3, '}') orelse return;
        var alternative_start = cursor + 3;
        var alternative_cursor = alternative_start;
        while (alternative_cursor <= disjunction_end) : (alternative_cursor += 1) {
            if (alternative_cursor != disjunction_end and source[alternative_cursor] != '|') continue;
            if (regexUnicodeClassStringAlternative(source[alternative_start..alternative_cursor], input, input_start, ignore_case)) |match_end| out.add(match_end);
            alternative_start = alternative_cursor + 1;
        }
        cursor = disjunction_end;
    }
}

fn regexUnicodeStringPropertyMatches(property: unicode_regex.StringProperty, input: []const u8, input_start: usize, ignore_case: bool, out: *RegexStringEnds) void {
    for (unicode_regex.stringSequences(property)) |sequence| {
        var input_cursor = input_start;
        var matches = true;
        for (unicode_regex.stringSequenceValues(sequence)) |expected| {
            if (input_cursor >= input.len) {
                matches = false;
                break;
            }
            const actual = runtimeStringDecode(input, input_cursor);
            if (!regexCodepointEqual(expected, @intCast(actual.value), ignore_case)) {
                matches = false;
                break;
            }
            input_cursor += actual.length;
        }
        if (matches) out.add(input_cursor);
    }
}

fn regexUnicodeClassStringAlternative(source: []const u8, input: []const u8, input_start: usize, ignore_case: bool) ?usize {
    var source_cursor: usize = 0;
    var input_cursor = input_start;
    while (source_cursor < source.len) {
        if (input_cursor >= input.len) return null;
        var expected: u21 = undefined;
        if (source[source_cursor] == '\\' and source_cursor + 1 < source.len and (source[source_cursor + 1] == 'u' or source[source_cursor + 1] == 'x')) {
            const escape_end = if (source[source_cursor + 1] == 'x')
                source_cursor + 4
            else if (source_cursor + 2 < source.len and source[source_cursor + 2] == '{')
                (std.mem.indexOfScalarPos(u8, source, source_cursor + 3, '}') orelse return null) + 1
            else
                source_cursor + 6;
            if (escape_end > source.len) return null;
            expected = regexEscapeCodepoint(source, source_cursor, escape_end) orelse return null;
            source_cursor = escape_end;
        } else {
            const scalar = runtimeStringDecode(source, source_cursor);
            expected = @intCast(scalar.value);
            source_cursor += scalar.length;
        }
        const actual = runtimeStringDecode(input, input_cursor);
        if (!regexCodepointEqual(expected, @intCast(actual.value), ignore_case)) return null;
        input_cursor += actual.length;
    }
    return input_cursor;
}

fn regexByteEqual(left: u8, right: u8, ignore_case: bool) bool {
    return if (ignore_case) std.ascii.toLower(left) == std.ascii.toLower(right) else left == right;
}

fn stopAfter(context: ?*anyopaque) bool {
    const counter: *usize = @ptrCast(@alignCast(context.?));
    if (counter.* == 0) return true;
    counter.* -= 1;
    return false;
}

fn hostTestCallback(runtime: *Runtime, context: ?*anyopaque, tag: u16, receiver: Value, arguments: []const Value) Error!Value {
    _ = receiver;
    const calls: *usize = @ptrCast(@alignCast(context orelse return error.TypeError));
    calls.* += 1;
    const input = if (arguments.len > 0) try runtime.valueNumber(arguments[0]) else 0;
    return .{ .number = input + @as(f64, @floatFromInt(tag)) };
}

fn hostDiagnosticCallback(_: *Runtime, _: ?*anyopaque, _: u16, _: Value, _: []const Value) Error!Value {
    return error.RangeError;
}

fn testingProgramCreate(_: *anyopaque) ?*Program {
    return std.testing.allocator.create(Program) catch null;
}

fn testingProgramDestroy(_: *anyopaque, program: *Program) void {
    std.testing.allocator.destroy(program);
}

fn testingMemoryAllocate(_: *anyopaque, length: usize, alignment: usize) ?[*]u8 {
    return std.testing.allocator.rawAlloc(length, .fromByteUnits(alignment), @returnAddress());
}

fn testingMemoryFree(_: *anyopaque, memory: [*]u8, length: usize, alignment: usize) void {
    std.testing.allocator.rawFree(memory[0..length], .fromByteUnits(alignment), @returnAddress());
}

const TestingAllocationCounter = struct {
    programs_created: usize = 0,
    programs_destroyed: usize = 0,
    bytes_allocated: usize = 0,
    bytes_freed: usize = 0,
};

fn countedProgramCreate(context: *anyopaque) ?*Program {
    const counter: *TestingAllocationCounter = @ptrCast(@alignCast(context));
    const program = std.testing.allocator.create(Program) catch return null;
    counter.programs_created += 1;
    return program;
}

fn countedProgramDestroy(context: *anyopaque, program: *Program) void {
    const counter: *TestingAllocationCounter = @ptrCast(@alignCast(context));
    counter.programs_destroyed += 1;
    std.testing.allocator.destroy(program);
}

fn countedMemoryAllocate(context: *anyopaque, length: usize, alignment: usize) ?[*]u8 {
    const memory = std.testing.allocator.rawAlloc(length, .fromByteUnits(alignment), @returnAddress()) orelse return null;
    const counter: *TestingAllocationCounter = @ptrCast(@alignCast(context));
    counter.bytes_allocated += length;
    return memory;
}

fn countedMemoryFree(context: *anyopaque, memory: [*]u8, length: usize, alignment: usize) void {
    const counter: *TestingAllocationCounter = @ptrCast(@alignCast(context));
    counter.bytes_freed += length;
    std.testing.allocator.rawFree(memory[0..length], .fromByteUnits(alignment), @returnAddress());
}

fn initTestingRuntime(runtime: *Runtime) Error!void {
    runtime.initialize(.{
        .context = @ptrCast(runtime),
        .create = testingProgramCreate,
        .destroy = testingProgramDestroy,
        .allocate = testingMemoryAllocate,
        .free = testingMemoryFree,
    });
    try runtime.init();
}

const ParsedDateTime = struct { milliseconds: i64, local: bool };
const TestingClock = struct { now: f64, offset: i32 };

fn testingClockNow(context: ?*anyopaque) f64 {
    const clock: *TestingClock = @ptrCast(@alignCast(context orelse return 0));
    return clock.now;
}

fn testingClockOffset(context: ?*anyopaque, _: f64) i32 {
    const clock: *TestingClock = @ptrCast(@alignCast(context orelse return 0));
    return clock.offset;
}

fn timeClip(value: f64) f64 {
    if (!std.math.isFinite(value) or @abs(value) > 8.64e15) return std.math.nan(f64);
    const clipped = @trunc(value);
    return if (clipped == 0) 0 else clipped;
}

fn makeDateMilliseconds(year: i64, month: i64, date_value: i64, hours: i64, minutes: i64, seconds: i64, milliseconds: i64) i64 {
    const year_wide: i128 = year;
    const month_wide: i128 = month;
    const normalized_year = year_wide + @divFloor(month_wide, 12);
    const normalized_month = @mod(month_wide, 12) + 1;
    const days = daysFromCivilWide(normalized_year, normalized_month, 1) + date_value - 1;
    const total = (((days * 24 + hours) * 60 + minutes) * 60 + seconds) * 1000 + milliseconds;
    if (total > std.math.maxInt(i64)) return std.math.maxInt(i64);
    if (total < std.math.minInt(i64)) return std.math.minInt(i64);
    return @intCast(total);
}

fn daysFromCivilWide(raw_year: i128, month: i128, day: i128) i128 {
    const year = raw_year - @as(i128, if (month <= 2) 1 else 0);
    const era = @divFloor(year, 400);
    const year_of_era = year - era * 400;
    const shifted_month = month + (if (month > 2) @as(i128, -3) else 9);
    const day_of_year = @divFloor(153 * shifted_month + 2, 5) + day - 1;
    const day_of_era = year_of_era * 365 + @divFloor(year_of_era, 4) - @divFloor(year_of_era, 100) + day_of_year;
    return era * 146097 + day_of_era - 719468;
}

fn civilFromDays(days: i64) struct { year: i64, month: i64, date: i64 } {
    const shifted = days + 719468;
    const era = @divFloor(shifted, 146097);
    const day_of_era = shifted - era * 146097;
    const year_of_era = @divFloor(day_of_era - @divFloor(day_of_era, 1460) + @divFloor(day_of_era, 36524) - @divFloor(day_of_era, 146096), 365);
    var year = year_of_era + era * 400;
    const day_of_year = day_of_era - (365 * year_of_era + @divFloor(year_of_era, 4) - @divFloor(year_of_era, 100));
    const month_prime = @divFloor(5 * day_of_year + 2, 153);
    const date_value = day_of_year - @divFloor(153 * month_prime + 2, 5) + 1;
    const month = month_prime + (if (month_prime < 10) @as(i64, 3) else -9);
    year += if (month <= 2) 1 else 0;
    return .{ .year = year, .month = month, .date = date_value };
}

fn dateParts(milliseconds: i64) DateParts {
    const day = @divFloor(milliseconds, 86400000);
    const within_day = @mod(milliseconds, 86400000);
    const civil = civilFromDays(day);
    return .{
        .year = civil.year,
        .month = civil.month - 1,
        .date = civil.date,
        .day = @mod(day + 4, 7),
        .hours = @divFloor(within_day, 3600000),
        .minutes = @mod(@divFloor(within_day, 60000), 60),
        .seconds = @mod(@divFloor(within_day, 1000), 60),
        .milliseconds = @mod(within_day, 1000),
    };
}

fn leapYearWide(year: i64) bool {
    return @mod(year, 4) == 0 and (@mod(year, 100) != 0 or @mod(year, 400) == 0);
}

fn daysInMonthWide(year: i64, month: i64) i64 {
    return switch (month) {
        1, 3, 5, 7, 8, 10, 12 => 31,
        4, 6, 9, 11 => 30,
        2 => if (leapYearWide(year)) 29 else 28,
        else => 0,
    };
}

fn appendFixedUnsigned(buffer: []u8, length: *usize, value: u64, width: usize) Error!void {
    if (width > 20 or length.* + width > buffer.len) return error.StringLimit;
    var divisor: u64 = 1;
    var index: usize = 1;
    while (index < width) : (index += 1) divisor *= 10;
    const remainder = value;
    for (0..width) |_| {
        buffer[length.*] = @intCast('0' + (remainder / divisor) % 10);
        length.* += 1;
        if (divisor > 1) divisor /= 10;
    }
}

fn appendYear(buffer: []u8, length: *usize, year: i64, iso: bool) Error!void {
    if (year >= 0 and year <= 9999) return appendFixedUnsigned(buffer, length, @intCast(year), 4);
    if (!iso and year >= 0) {
        const text = std.fmt.bufPrint(buffer[length.*..], "{d}", .{year}) catch return error.StringLimit;
        length.* += text.len;
        return;
    }
    if (length.* >= buffer.len) return error.StringLimit;
    buffer[length.*] = if (year < 0) '-' else '+';
    length.* += 1;
    const magnitude: u64 = @intCast(if (year < 0) -year else year);
    return appendFixedUnsigned(buffer, length, magnitude, 6);
}

const weekday_names = [_][]const u8{ "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };
const month_names = [_][]const u8{ "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };

fn formatIsoDate(buffer: []u8, length: *usize, parts: DateParts) Error!void {
    try appendYear(buffer, length, parts.year, true);
    try appendBytes(buffer, length, "-");
    try appendFixedUnsigned(buffer, length, @intCast(parts.month + 1), 2);
    try appendBytes(buffer, length, "-");
    try appendFixedUnsigned(buffer, length, @intCast(parts.date), 2);
    try appendBytes(buffer, length, "T");
    try appendFixedUnsigned(buffer, length, @intCast(parts.hours), 2);
    try appendBytes(buffer, length, ":");
    try appendFixedUnsigned(buffer, length, @intCast(parts.minutes), 2);
    try appendBytes(buffer, length, ":");
    try appendFixedUnsigned(buffer, length, @intCast(parts.seconds), 2);
    try appendBytes(buffer, length, ".");
    try appendFixedUnsigned(buffer, length, @intCast(parts.milliseconds), 3);
    try appendBytes(buffer, length, "Z");
}

fn formatUtcDate(buffer: []u8, length: *usize, parts: DateParts) Error!void {
    try appendBytes(buffer, length, weekday_names[@intCast(parts.day)]);
    try appendBytes(buffer, length, ", ");
    try appendFixedUnsigned(buffer, length, @intCast(parts.date), 2);
    try appendBytes(buffer, length, " ");
    try appendBytes(buffer, length, month_names[@intCast(parts.month)]);
    try appendBytes(buffer, length, " ");
    try appendYear(buffer, length, parts.year, false);
    try appendBytes(buffer, length, " ");
    try appendClock(buffer, length, parts);
    try appendBytes(buffer, length, " GMT");
}

fn formatDateOnly(buffer: []u8, length: *usize, parts: DateParts) Error!void {
    try appendBytes(buffer, length, weekday_names[@intCast(parts.day)]);
    try appendBytes(buffer, length, " ");
    try appendBytes(buffer, length, month_names[@intCast(parts.month)]);
    try appendBytes(buffer, length, " ");
    try appendFixedUnsigned(buffer, length, @intCast(parts.date), 2);
    try appendBytes(buffer, length, " ");
    try appendYear(buffer, length, parts.year, false);
}

fn appendClock(buffer: []u8, length: *usize, parts: DateParts) Error!void {
    try appendFixedUnsigned(buffer, length, @intCast(parts.hours), 2);
    try appendBytes(buffer, length, ":");
    try appendFixedUnsigned(buffer, length, @intCast(parts.minutes), 2);
    try appendBytes(buffer, length, ":");
    try appendFixedUnsigned(buffer, length, @intCast(parts.seconds), 2);
}

fn formatTimeOnly(buffer: []u8, length: *usize, parts: DateParts, offset: i32) Error!void {
    try appendClock(buffer, length, parts);
    try appendBytes(buffer, length, " GMT");
    if (length.* >= buffer.len) return error.StringLimit;
    buffer[length.*] = if (offset < 0) '-' else '+';
    length.* += 1;
    const magnitude: u64 = @intCast(if (offset < 0) -offset else offset);
    try appendFixedUnsigned(buffer, length, magnitude / 60, 2);
    try appendFixedUnsigned(buffer, length, magnitude % 60, 2);
}

fn formatLocaleDate(buffer: []u8, length: *usize, parts: DateParts) Error!void {
    const text = std.fmt.bufPrint(buffer[length.*..], "{d}/{d}/{d}", .{ parts.month + 1, parts.date, parts.year }) catch return error.StringLimit;
    length.* += text.len;
}

fn formatLocaleTime(buffer: []u8, length: *usize, parts: DateParts) Error!void {
    const hour = if (@mod(parts.hours, 12) == 0) 12 else @mod(parts.hours, 12);
    const hour_text = std.fmt.bufPrint(buffer[length.*..], "{d}", .{hour}) catch return error.StringLimit;
    length.* += hour_text.len;
    try appendBytes(buffer, length, ":");
    try appendFixedUnsigned(buffer, length, @intCast(parts.minutes), 2);
    try appendBytes(buffer, length, ":");
    try appendFixedUnsigned(buffer, length, @intCast(parts.seconds), 2);
    try appendBytes(buffer, length, if (parts.hours < 12) " AM" else " PM");
}

fn parseFixedDigits(text: []const u8, cursor: *usize, count: usize) ?i64 {
    if (cursor.* + count > text.len) return null;
    var value: i64 = 0;
    for (text[cursor.* .. cursor.* + count]) |byte| {
        if (!std.ascii.isDigit(byte)) return null;
        value = value * 10 + byte - '0';
    }
    cursor.* += count;
    return value;
}

fn consumeByte(text: []const u8, cursor: *usize, expected: u8) bool {
    if (cursor.* >= text.len or text[cursor.*] != expected) return false;
    cursor.* += 1;
    return true;
}

fn parseIsoDateTime(text: []const u8) ?ParsedDateTime {
    if (text.len < 4) return null;
    var cursor: usize = 0;
    var year: i64 = 0;
    if (text[0] == '+' or text[0] == '-') {
        const negative = text[0] == '-';
        cursor = 1;
        year = parseFixedDigits(text, &cursor, 6) orelse return null;
        if (negative) year = -year;
        if (negative and year == 0) return null;
    } else year = parseFixedDigits(text, &cursor, 4) orelse return null;
    var month: i64 = 1;
    var date_value: i64 = 1;
    if (cursor < text.len and text[cursor] == '-') {
        cursor += 1;
        month = parseFixedDigits(text, &cursor, 2) orelse return null;
        if (cursor < text.len and text[cursor] == '-') {
            cursor += 1;
            date_value = parseFixedDigits(text, &cursor, 2) orelse return null;
        }
    }
    if (month < 1 or month > 12 or date_value < 1 or date_value > daysInMonthWide(year, month)) return null;
    var hours: i64 = 0;
    var minutes: i64 = 0;
    var seconds: i64 = 0;
    var milliseconds: i64 = 0;
    var local = false;
    var offset_minutes: i64 = 0;
    const has_time = cursor < text.len;
    if (has_time) {
        if (!consumeByte(text, &cursor, 'T')) return null;
        hours = parseFixedDigits(text, &cursor, 2) orelse return null;
        if (!consumeByte(text, &cursor, ':')) return null;
        minutes = parseFixedDigits(text, &cursor, 2) orelse return null;
        if (cursor < text.len and text[cursor] == ':') {
            cursor += 1;
            seconds = parseFixedDigits(text, &cursor, 2) orelse return null;
            if (cursor < text.len and text[cursor] == '.') {
                cursor += 1;
                const start = cursor;
                while (cursor < text.len and std.ascii.isDigit(text[cursor])) cursor += 1;
                if (cursor == start) return null;
                var fraction_cursor = start;
                var digits: usize = 0;
                while (fraction_cursor < cursor and digits < 3) : ({
                    fraction_cursor += 1;
                    digits += 1;
                }) milliseconds = milliseconds * 10 + text[fraction_cursor] - '0';
                while (digits < 3) : (digits += 1) milliseconds *= 10;
            }
        }
        if (minutes > 59 or seconds > 59 or hours > 24 or (hours == 24 and (minutes != 0 or seconds != 0 or milliseconds != 0))) return null;
        if (cursor == text.len) {
            local = true;
        } else if (text[cursor] == 'Z') {
            cursor += 1;
        } else if (text[cursor] == '+' or text[cursor] == '-') {
            const negative = text[cursor] == '-';
            cursor += 1;
            const offset_hours = parseFixedDigits(text, &cursor, 2) orelse return null;
            _ = consumeByte(text, &cursor, ':');
            const offset_minute_part = parseFixedDigits(text, &cursor, 2) orelse return null;
            if (offset_hours > 23 or offset_minute_part > 59) return null;
            offset_minutes = offset_hours * 60 + offset_minute_part;
            if (negative) offset_minutes = -offset_minutes;
        } else return null;
    }
    if (cursor != text.len) return null;
    const milliseconds_value = makeDateMilliseconds(year, month - 1, date_value, hours, minutes, seconds, milliseconds);
    return .{ .milliseconds = milliseconds_value - offset_minutes * 60000, .local = local };
}

fn parseMonthName(text: []const u8) ?i64 {
    for (month_names, 1..) |name, month| if (std.ascii.eqlIgnoreCase(text, name)) return @intCast(month);
    return null;
}

fn parseClockText(text: []const u8) ?struct { hours: i64, minutes: i64, seconds: i64 } {
    if (text.len != 8 or text[2] != ':' or text[5] != ':') return null;
    var cursor: usize = 0;
    const hours = parseFixedDigits(text, &cursor, 2) orelse return null;
    cursor += 1;
    const minutes = parseFixedDigits(text, &cursor, 2) orelse return null;
    cursor += 1;
    const seconds = parseFixedDigits(text, &cursor, 2) orelse return null;
    if (hours > 23 or minutes > 59 or seconds > 59) return null;
    return .{ .hours = hours, .minutes = minutes, .seconds = seconds };
}

fn parseRfcDateTime(text: []const u8) ?i64 {
    var source = text;
    if (std.mem.indexOf(u8, source, ", ")) |comma| source = source[comma + 2 ..];
    var tokens = std.mem.tokenizeScalar(u8, source, ' ');
    const day_text = tokens.next() orelse return null;
    const month_text = tokens.next() orelse return null;
    const year_text = tokens.next() orelse return null;
    const clock_text = tokens.next() orelse return null;
    const zone = tokens.next() orelse return null;
    if (tokens.next() != null or !equals(zone, "GMT")) return null;
    const day = std.fmt.parseInt(i64, day_text, 10) catch return null;
    const month = parseMonthName(month_text) orelse return null;
    const year = std.fmt.parseInt(i64, year_text, 10) catch return null;
    const clock = parseClockText(clock_text) orelse return null;
    if (day < 1 or day > daysInMonthWide(year, month)) return null;
    return makeDateMilliseconds(year, month - 1, day, clock.hours, clock.minutes, clock.seconds, 0);
}

fn parseRuntimeDateTime(text: []const u8) ?i64 {
    var tokens = std.mem.tokenizeScalar(u8, text, ' ');
    _ = tokens.next() orelse return null;
    const month_text = tokens.next() orelse return null;
    const day_text = tokens.next() orelse return null;
    const year_text = tokens.next() orelse return null;
    const clock_text = tokens.next() orelse return null;
    const zone_text = tokens.next() orelse return null;
    if (tokens.next() != null or zone_text.len != 8 or !std.mem.startsWith(u8, zone_text, "GMT")) return null;
    const day = std.fmt.parseInt(i64, day_text, 10) catch return null;
    const month = parseMonthName(month_text) orelse return null;
    const year = std.fmt.parseInt(i64, year_text, 10) catch return null;
    const clock = parseClockText(clock_text) orelse return null;
    const sign: i64 = if (zone_text[3] == '-') -1 else if (zone_text[3] == '+') 1 else return null;
    const offset_hour = std.fmt.parseInt(i64, zone_text[4..6], 10) catch return null;
    const offset_minute = std.fmt.parseInt(i64, zone_text[6..8], 10) catch return null;
    if (day < 1 or day > daysInMonthWide(year, month) or offset_hour > 23 or offset_minute > 59) return null;
    return makeDateMilliseconds(year, month - 1, day, clock.hours, clock.minutes, clock.seconds, 0) - sign * (offset_hour * 60 + offset_minute) * 60000;
}

fn createTestingRuntime() !*Runtime {
    const runtime = try std.testing.allocator.create(Runtime);
    errdefer std.testing.allocator.destroy(runtime);
    try initTestingRuntime(runtime);
    return runtime;
}

fn destroyTestingRuntime(runtime: *Runtime) void {
    runtime.deinit();
    std.testing.allocator.destroy(runtime);
}

test "parser accepts modern lexical functions objects arrays and modules" {
    var program: Program = .{};
    const stats = try program.parse(
        "import { value as input } from 'base';" ++
            "export const answer = ((x) => x * 2)(input);" ++
            "export async function later(v) { return { value: v ?? 0, list: [1, 2, 3] }; }",
    );
    try std.testing.expect(stats.tokens > 30);
    try std.testing.expect(stats.nodes > 20);
    try std.testing.expectEqual(@as(usize, 2), stats.functions);
    try std.testing.expectEqual(@as(usize, 3), stats.modules);
}

test "bytecode VM evaluates closures control flow exceptions and standard types" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};
    const value = try runtime.evaluateSource(&program, "const add = makeAdder(7);" ++
        "function makeAdder(base) { return (value) => base + value; }" ++
        "let total = 0;" ++
        "for (let i = 0; i < 4; i++) { total += i; }" ++
        "try { if (total === 6) throw 'ok'; } catch (reason) { total = add(total); }" ++
        "const list = [total, Math.max(2, 9)];" ++
        "list.push(parseInt('11'));" ++
        "return list.join('-');");
    try std.testing.expectEqualStrings("13-9-11", runtime.valueString(value));
    try std.testing.expect(runtime.stats.bytecode_instructions > 0);
    try std.testing.expectEqual(runtime.stats.steps, runtime.stats.bytecode_instructions);
}

test "bytecode compiler validates compact segments before execution" {
    var program: Program = .{};
    const source = "let total=0; for(let i=0;i<8;i++){total+=i;} return total;";
    const stats = try program.parseHostSource(source);
    try std.testing.expect(program.bytecodeReady());
    try std.testing.expect(program.verifyBytecodeIntegrity());
    const first_generation = program.bytecodeGeneration();
    try std.testing.expect(first_generation != 0);
    try std.testing.expect(stats.bytecode_instructions > 0);
    try std.testing.expect(stats.bytecode_instructions <= stats.nodes * 3);
    try std.testing.expect(stats.bytecode_segments > 0);
    try std.testing.expectEqual(@as(usize, 8), @sizeOf(BytecodeInstruction));

    const saved_flags = program.workspace.compiled.instructions[0].flags;
    program.workspace.compiled.instructions[0].flags ^= 1;
    try std.testing.expect(program.bytecodeReady());
    try std.testing.expect(!program.verifyBytecodeIntegrity());
    program.invalidateBytecode();
    try std.testing.expect(!program.bytecodeReady());
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    try std.testing.expectError(error.BytecodeInvalid, runtime.evaluate(&program));
    program.workspace.compiled.instructions[0].flags = saved_flags;
    _ = try program.parseHostSource(source);
    try std.testing.expect(program.bytecodeReady());
    try std.testing.expect(program.verifyBytecodeIntegrity());
    try std.testing.expect(program.bytecodeGeneration() != first_generation);

    const invalid = try std.testing.allocator.create(Program);
    defer std.testing.allocator.destroy(invalid);
    invalid.* = .{};
    _ = try invalid.parseHostSource("return 1;");
    invalid.workspace.compiled.segment_ends[invalid.root_segment] = @intCast(invalid.bytecode_count + 1);
    try std.testing.expectError(error.BytecodeInvalid, invalid.validateBytecode());

    invalid.* = .{};
    _ = try invalid.parse("1;");
    const statement = invalid.nodes[invalid.root].a;
    const expression_segment = invalid.workspace.compiled.node_segments[statement];
    const expression_start: usize = invalid.workspace.compiled.segment_starts[expression_segment];
    invalid.workspace.compiled.instructions[expression_start].op = .binary;
    try std.testing.expectError(error.BytecodeStack, invalid.validateBytecode());
}

test "normal generator and async calls retain one bytecode generation" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};
    _ = try runtime.evaluateSource(
        &program,
        "let result=0;function normal(value){return value+1;}" ++
            "function* values(){yield normal(1);return normal(2);}" ++
            "async function later(){return normal(3);}" ++
            "const iterator=values();result=iterator.next().value+iterator.next().value;" ++
            "later().then(value=>result+=value);",
    );
    const generation = program.bytecodeGeneration();
    try std.testing.expect(generation != 0);
    _ = try runtime.drainJobs(&program, 8);
    try std.testing.expectEqual(@as(f64, 9), try runtime.valueNumber(runtime.global("result").?));
    try std.testing.expectEqual(generation, program.bytecodeGeneration());
    try std.testing.expect(program.verifyBytecodeIntegrity());
}

