        &program,
        "function* values(){const sent=yield 1;yield sent+1;return 9;}" ++
            "const iterator=values();" ++
            "const first=iterator.next(99);const second=iterator.next(4);const final=iterator.next();" ++
            "return first.value*1000+second.value*100+final.value*10+" ++
