test "ECMAScript 2026 generator return throw delegation and finally preserve completions" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};
    const value = try runtime.evaluateSource(
        &program,
        "function* withFinally(){try{yield 1;}finally{yield 2;}}" ++
            "const a=withFinally();const a1=a.next();const a2=a.return(9);const a3=a.next();" ++
            "function* catches(){try{yield 3;}catch(reason){yield reason+1;}return 7;}" ++
            "const b=catches();b.next();const b1=b.throw(4);const b2=b.next();" ++
            "function* inner(){const sent=yield 5;return sent+4;}" ++
            "function* outer(){return yield* inner();}" ++
            "const c=outer();const c1=c.next();const c2=c.next(6);" ++
            "const methods={*items(){yield 8;yield 9;}};const spread=[...methods.items()];" ++
            "class Box{*items(){yield 10;}}const box=new Box();const classValue=box.items().next().value;" ++
            "return a1.value+a2.value*10+a3.value*100+(a3.done?1000:0)+" ++
            "b1.value*10000+b2.value*100000+(b2.done?1000000:0)+" ++
            "c1.value*10000000+c2.value*100000000+(c2.done?1000000000:0)+" ++
            "spread[0]+spread[1]*10+classValue*100;",
    );
    try std.testing.expectEqual(@as(f64, 2_051_753_019), try runtime.valueNumber(value));
}

test "ECMAScript 2026 generator grammar reserves yield only in generator contexts" {
    var program: Program = .{};
    const invalid = [_][]const u8{
        "function* g(yield){}",
        "function* g(x=yield){}",
        "function* g(){let yield=1;}",
        "function* g(){return y\\u0069eld;}",
        "function* g(){(x=yield)=>x;}",
        "function* g(a,a){}",
        "function* g(){yield*;}",
    };
    for (invalid) |source| try std.testing.expectError(error.SyntaxError, program.parse(source));
    _ = try program.parseHostSource("let yield=3;function* produce(){yield 1;}return yield;");
}

test "ECMAScript 2026 generators retain suspended roots and release dynamic fibers" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};
    const iterator = try runtime.evaluateSource(
        &program,
        "function* values(){const retained={value:4};yield retained.value;return retained.value+1;}return values();",
    );
    try std.testing.expect(runtime.generator_state_head != null);
    try std.testing.expect(runtime.generator_state_head.?.stack_memory == null);
    try runtime.pushRoot(iterator);
    const next = try runtime.getProperty(iterator, "next");
    const first = try runtime.call(&program, next, iterator, &.{}, false);
    try std.testing.expect(runtime.generator_state_head.?.stack_memory != null);
    try std.testing.expectEqual(@as(f64, 4), try runtime.valueNumber(try runtime.getProperty(first, "value")));
    runtime.collectGarbage();
    const final = try runtime.call(&program, next, iterator, &.{}, false);
    try std.testing.expectEqual(@as(f64, 5), try runtime.valueNumber(try runtime.getProperty(final, "value")));
    try std.testing.expect(runtime.valueBoolean(try runtime.getProperty(final, "done")));
    try std.testing.expect(runtime.generator_state_head.?.stack_memory == null);
    runtime.popRoot();
    runtime.collectGarbage();
    try std.testing.expect(runtime.generator_state_head == null);
}

test "ECMAScript 2026 generator delegation forwards next return throw and closes correctly" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};
    const value = try runtime.evaluateSource(
        &program,
        "let log='';" ++
            "const delegated={index:0,[Symbol.iterator](){return this;}," ++
            "next(value){log+='n'+(value===undefined?'u':value);this.index++;return {value:this.index,done:false};}," ++
            "return(value){log+='r'+value;return {value:value+1,done:true};}," ++
            "throw(value){log+='t'+value;return {value:value+2,done:false};}};" ++
            "function* outer(){try{return yield* delegated;}finally{log+='f';}}" ++
            "const a=outer();const a1=a.next();const a2=a.throw(4);const a3=a.return(7);" ++
            "let missingClosed=0;const missingThrow={[Symbol.iterator](){return {next(){return {value:3,done:false};}," ++
            "return(){missingClosed++;return {done:true};}};}};" ++
            "const b=(function*(){yield* missingThrow;})();b.next();let typeError=0;try{b.throw(9);}catch(reason){typeError=reason instanceof Error;}" ++
            "return a1.value+a2.value*10+a3.value*100+(a3.done?1000:0)+" ++
            "(log==='nu'+'t4'+'r7'+'f'?10000:0)+missingClosed*100000+typeError*1000000;",
    );
    try std.testing.expectEqual(@as(f64, 1_111_861), try runtime.valueNumber(value));
}

test "ECMAScript 2026 generator lifecycle is lazy reentrancy-safe and non-constructible" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};
    const value = try runtime.evaluateSource(
        &program,
        "let side=0;function* lazy(input=(side++,3)){side++;yield this.value+input;return 6;}" ++
            "const holder={value:4,g:lazy};const iterator=holder.g();const before=side;" ++
            "const proto=Object.getPrototypeOf(iterator)===lazy.prototype;const instance=iterator instanceof lazy;" ++
            "let constructError=0;try{new lazy();}catch(reason){constructError=reason instanceof Error;}" ++
            "const first=iterator.next();const final=iterator.next();const after=iterator.next();" ++
            "const early=lazy();const earlyResult=early.return(8);const afterEarly=side;" ++
            "const initialThrow=lazy();let thrown=0;try{initialThrow.throw(11);}catch(reason){thrown=reason;}" ++
            "let reentrant;function* guarded(){try{reentrant.next();}catch(reason){yield reason instanceof Error;}}" ++
            "reentrant=guarded();const guardedResult=reentrant.next();" ++
            "function* newline(){yield\n12;return 13;}const line=newline();const line1=line.next();const line2=line.next();" ++
            "return before+(proto?10:0)+(instance?100:0)+constructError*1000+first.value*10000+" ++
            "final.value*100000+(final.done?1000000:0)+(after.done?2000000:0)+" ++
            "earlyResult.value*10000000+(earlyResult.done?100000000:0)+afterEarly*1000000000+" ++
            "thrown*10000000000+(guardedResult.value?100000000000:0)+" ++
            "(line1.value===undefined?1000000000000:0)+line2.value*10000000000000;",
    );
    try std.testing.expectEqual(@as(f64, 131_212_183_671_110), try runtime.valueNumber(value));
}

test "ECMAScript 2026 async generators queue requests across await and yield" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};
    _ = try runtime.evaluateSource(&program, "let results='';let release;" ++
        "const source=new Promise(resolve=>release=resolve);" ++
        "async function* sequence(){const first=await source;const sent=yield first;" ++
        "yield await Promise.resolve(sent+1);return 9;}" ++
        "const iterator=sequence();const identity=iterator[Symbol.asyncIterator]()===iterator;" ++
        "const noSync=iterator[Symbol.iterator]===undefined;" ++
        "iterator.next().then(result=>{results+=result.value+':'+result.done+';';return iterator.next(5);})" ++
        ".then(result=>{results+=result.value+':'+result.done+';';return iterator.next();})" ++
        ".then(result=>results+=result.value+':'+result.done+';');release(3);" ++
        "async function* queued(){yield 1;yield 2;}const queue=queued();" ++
        "queue.next().then(result=>results+='Q'+result.value);queue.next().then(result=>results+='Q'+result.value);");
    const jobs = try runtime.drainJobs(&program, 64);
    try std.testing.expect(jobs >= 10);
    try std.testing.expectEqualStrings("Q13:false;Q26:false;9:true;", runtime.valueString(runtime.global("results").?));
    try std.testing.expect(runtime.global("identity").?.boolean);
    try std.testing.expect(runtime.global("noSync").?.boolean);
    const iterator = runtime.global("iterator").?;
    const state: *GeneratorFiberState = @ptrCast(@alignCast(runtime.cells[iterator.cell].host_context.?));
    try std.testing.expectEqual(GeneratorStatus.completed, state.status);
    try std.testing.expect(state.stack_memory == null);
    try std.testing.expectEqual(@as(usize, 0), state.request_count);
}

test "ECMAScript 2026 async generator return throw and finally remain asynchronous" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};
    _ = try runtime.evaluateSource(&program, "let trace='';let summary='';" ++
        "async function* closing(){try{yield 1;}finally{trace+=await Promise.resolve('F');yield 2;}}" ++
        "const iterator=closing();iterator.next().then(result=>{summary+=result.value+':'+result.done+';';return iterator.return(7);})" ++
        ".then(result=>{summary+=result.value+':'+result.done+';';return iterator.return(7);})" ++
        ".then(result=>{summary+=result.value+':'+result.done+';';return iterator.throw(8);})" ++
        ".catch(reason=>summary+='E'+reason);");
    _ = try runtime.drainJobs(&program, 64);
    try std.testing.expectEqualStrings("F", runtime.valueString(runtime.global("trace").?));
    try std.testing.expectEqualStrings("1:false;2:false;7:true;E8", runtime.valueString(runtime.global("summary").?));

    try runtime.reset();
    _ = try runtime.evaluateSource(&program, "let completed='';async function* values(){yield 1;}const first=values();" ++
        "first.next().then(()=>first.return(Promise.resolve(7))).then(result=>completed+=result.value+':'+result.done+';');" ++
        "const second=values();second.next().then(()=>second.return(Promise.reject('R'))).catch(reason=>completed+='E'+reason);");
    _ = try runtime.drainJobs(&program, 64);
    try std.testing.expectEqualStrings("7:true;ER", runtime.valueString(runtime.global("completed").?));

    try runtime.reset();
    _ = try runtime.evaluateSource(&program, "let value=0;async function* recursive(depth){" ++
        "if(depth===0)return 1;const child=recursive(depth-1);return (await child.next()).value+1;}" ++
        "recursive(3).next().then(result=>value=result.value);");
    _ = try runtime.drainJobs(&program, 64);
    try std.testing.expectEqual(@as(f64, 4), try runtime.valueNumber(runtime.global("value").?));
}

test "ECMAScript 2026 for-await-of consumes async and sync iterables and closes early" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};
    _ = try runtime.evaluateSource(&program, "let asyncSum=0;let syncSum=0;let closed=0;" ++
        "const values={[Symbol.asyncIterator](){let index=0;return {" ++
        "next(){index++;return Promise.resolve(index<=3?{value:index,done:false}:{done:true});}," ++
        "return(){closed++;return Promise.resolve({done:true});}};}};" ++
        "async function consume(){for await(const value of values){asyncSum+=value;if(value===2)break;}" ++
        "for await(const value of [Promise.resolve(2),3])syncSum+=value;return asyncSum+syncSum;}" ++
        "consume().then(value=>asyncSum=value);");
    _ = try runtime.drainJobs(&program, 64);
    try std.testing.expectEqual(@as(f64, 8), try runtime.valueNumber(runtime.global("asyncSum").?));
    try std.testing.expectEqual(@as(f64, 5), try runtime.valueNumber(runtime.global("syncSum").?));
    try std.testing.expectEqual(@as(f64, 1), try runtime.valueNumber(runtime.global("closed").?));

    try std.testing.expectError(error.SyntaxError, program.parse("function invalid(){for await(const value of []){}}"));
    _ = try program.parse("async function valid(){for await(const value of []){}}");
    try std.testing.expectError(error.SyntaxError, program.parse("async function invalid(){for await(const key in {}){}}"));
}

test "ECMAScript 2026 async yield-star forwards async iterator completions" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};
    _ = try runtime.evaluateSource(&program, "let log='';let summary='';" ++
        "const delegated={index:0,[Symbol.asyncIterator](){return this;}," ++
        "next(value){log+='n'+(value===undefined?'u':value);this.index++;" ++
        "return Promise.resolve(this.index<=2?{value:Promise.resolve(this.index),done:false}:{value:7,done:true});}," ++
        "return(value){log+='r'+value;return Promise.resolve({value:value+1,done:true});}," ++
        "throw(value){log+='t'+value;return Promise.resolve({value:value+2,done:false});}};" ++
        "async function* outer(){try{return yield* delegated;}finally{log+='f';}}const iterator=outer();" ++
        "iterator.next().then(result=>{summary+=result.value+':'+result.done+';';return iterator.next(4);})" ++
        ".then(result=>{summary+=result.value+':'+result.done+';';return iterator.next();})" ++
        ".then(result=>summary+=result.value+':'+result.done+';');");
    _ = try runtime.drainJobs(&program, 128);
    try std.testing.expectEqualStrings("1:false;2:false;7:true;", runtime.valueString(runtime.global("summary").?));
