test "ECMAScript 2026 promise rejection tracker reports reject and later handle" {
    const Tracker = struct {
        rejected: usize = 0,
        handled: usize = 0,

        fn track(_: *Runtime, raw_context: ?*anyopaque, _: Value, _: Value, was_handled: bool) void {
            const context: *@This() = @ptrCast(@alignCast(raw_context.?));
            if (was_handled) context.handled += 1 else context.rejected += 1;
        }
    };
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var tracker: Tracker = .{};
    runtime.setPromiseRejectionTracker(.{ .context = &tracker, .track = Tracker.track });
    var program: Program = .{};
    _ = try runtime.evaluateSource(&program, "let late=Promise.reject('A');Promise.reject('B').catch(()=>{});" ++
        "let rejectPending;const pending=new Promise((resolve,reject)=>rejectPending=reject);pending.catch(()=>{});rejectPending('C');");
    try std.testing.expectEqual(@as(usize, 2), tracker.rejected);
    try std.testing.expectEqual(@as(usize, 1), tracker.handled);
    _ = try runtime.evaluateSource(&program, "late.catch(()=>{});");
    try std.testing.expectEqual(@as(usize, 2), tracker.handled);
    _ = try runtime.drainJobs(&program, 32);
}

