test "R4JS GC reclaims large cycles and reset releases programs fibers buffers and jobs" {
    var counter: TestingAllocationCounter = .{};
    const runtime = try std.testing.allocator.create(Runtime);
    defer std.testing.allocator.destroy(runtime);
    runtime.initialize(.{
        .context = &counter,
        .create = countedProgramCreate,
        .destroy = countedProgramDestroy,
        .allocate = countedMemoryAllocate,
        .free = countedMemoryFree,
    });
    try runtime.init();
    defer runtime.deinit();
    const baseline_external_bytes = counter.bytes_allocated - counter.bytes_freed;

    var program: Program = .{};
    _ = try runtime.evaluateSource(&program, "let graph=[];for(let index=0;index<2048;index++){let left={index:index};let right={index:index};left.peer=right;right.peer=left;graph.push(left);}graph=null;");
    const graph_cells = runtime.countLiveCells();
    runtime.collectGarbage();
    try std.testing.expect(runtime.countLiveCells() + 4000 < graph_cells);

    var generation: usize = 0;
    while (generation < 12) : (generation += 1) {
        try runtime.registerModule("https://reset.test/module.js", "export const value=1;");
        _ = try runtime.evaluateModule("https://reset.test/module.js");
        _ = try runtime.evaluateSource(&program, "eval('(value)=>value+1');" ++
            "async function pending(){await new Promise(()=>{});}pending();" ++
            "function* suspended(){yield {retained:true};}let iterator=suspended();iterator.next();iterator=null;" ++
            "let bytes=new ArrayBuffer(4096);let integer=1234567890123456789012345678901234567890n;" ++
            "queueMicrotask(()=>{throw 1;});");
        try std.testing.expect(runtime.dynamic_program_count > 0);
        try std.testing.expect(runtime.module_count > 0);
        try std.testing.expect(runtime.async_state_head != null);
        try std.testing.expect(runtime.generator_state_head != null);
        try std.testing.expect(runtime.microtask_count > 0);

        try runtime.reset();
        try std.testing.expectEqual(@as(usize, 0), runtime.dynamic_program_count);
        try std.testing.expectEqual(@as(usize, 0), runtime.module_count);
        try std.testing.expect(runtime.async_state_head == null);
        try std.testing.expect(runtime.generator_state_head == null);
        try std.testing.expectEqual(@as(usize, 0), runtime.task_count);
        try std.testing.expectEqual(@as(usize, 0), runtime.microtask_count);
        try std.testing.expectEqual(counter.programs_created, counter.programs_destroyed);
        try std.testing.expectEqual(baseline_external_bytes, counter.bytes_allocated - counter.bytes_freed);
    }
}

