    _ = try runtime.evaluateSource(&program, "let asyncResult=0;let asyncParameter=0;let asyncRest=0;let asyncArguments=0;" ++
        "function launch(){const calculate=async (value=2,...rest)=>{asyncArguments=arguments.length;asyncParameter=value;asyncRest=rest[0];return value+rest[0];};" ++
        "return calculate(undefined,3);}launch(9,8,7).then(value=>asyncResult=value);");
