        "try{parts.push('x');}catch(reason){blocked=true;}" ++
        "return same&&blocked&&(delete parts[0])===false&&parts[0]==='A\\n'&&parts.raw[0]==='A\\\\n'&&parts[1]==='B'&&values.length===1&&values[0]>0;}" ++
