        "const wellKnown=['asyncDispose','asyncIterator','dispose','hasInstance','isConcatSpreadable','iterator','match','matchAll','replace','search','species','split','toPrimitive','toStringTag','unscopables'];" ++
        "let known=true;for(const name of wellKnown){known=known&&typeof Symbol[name]==='symbol';}" ++
        "return [typeof empty==='symbol',empty.description===undefined,named.description==='name',named.toString()==='Symbol(name)',String(empty)==='Symbol()',named!==other," ++
        "Symbol.for('shared')===registered,Symbol.keyFor(registered)==='shared',Symbol.keyFor(named)===undefined,Object.getPrototypeOf(boxed)===Symbol.prototype," ++
        "boxed.valueOf()===named,Object.prototype.toString.call(named)==='[object Symbol]',Object.prototype.toString.call(boxed)==='[object Symbol]'," ++
        "Object.keys(object).join(',')==='text',Object.getOwnPropertyNames(object).join(',')==='text',symbols.length===1,symbols[0]===key,object[key]===1," ++
        "Object.hasOwn(object,key),object.propertyIsEnumerable(key),descriptors[key].value===1,copied[key]===1,JSON.stringify(object)==='{\"text\":2}'," ++
        "JSON.stringify({value:named})==='{}',JSON.stringify([named])==='[null]',JSON.stringify(named)===undefined,constructed,concatenated,String(custom)==='text',custom+1===5,known," ++
