        "const typed=new TypeError('bad',{cause:base});const aggregate=new AggregateError([base,typed],'many',{cause:7});" ++
        "const plainAggregate=AggregateError([1,2]);const messageDescriptor=Object.getOwnPropertyDescriptor(base,'message');" ++
        "const causeDescriptor=Object.getOwnPropertyDescriptor(base,'cause');const errorsDescriptor=Object.getOwnPropertyDescriptor(aggregate,'errors');" ++
        "const prototypeDescriptor=Object.getOwnPropertyDescriptor(Error,'prototype');" ++
        "const types=[EvalError,RangeError,ReferenceError,SyntaxError,TypeError,URIError,AggregateError];let chains=true;" ++
        "for(const Constructor of types){const instance=Constructor===AggregateError?new Constructor([]):new Constructor();chains=chains&&instance instanceof Constructor&&instance instanceof Error&&instance.name===Constructor.name;}" ++
        "let syntax=false;try{new RegExp('[');}catch(reason){syntax=reason instanceof SyntaxError&&reason instanceof Error&&reason.name==='SyntaxError';}" ++
        "class CustomError extends TypeError{}const custom=new CustomError('custom');" ++
        "return Error.length===1&&AggregateError.length===2&&Error.prototype.name==='Error'&&Error.prototype.message===''&&" ++
        "base.message==='base'&&base.cause===3&&!omitted.hasOwnProperty('message')&&Object.keys(base).length===0&&new Error(0).message==='0'&&" ++
        "typed.name==='TypeError'&&typed.cause===base&&typed instanceof TypeError&&typed instanceof Error&&!(typed instanceof EvalError)&&" ++
        "aggregate.name==='AggregateError'&&aggregate.message==='many'&&aggregate.cause===7&&aggregate.errors.length===2&&aggregate.errors[0]===base&&aggregate.errors[1]===typed&&" ++
        "plainAggregate.errors.join(',')==='1,2'&&!plainAggregate.hasOwnProperty('message')&&aggregate instanceof AggregateError&&aggregate instanceof Error&&" ++
        "messageDescriptor.writable&&!messageDescriptor.enumerable&&messageDescriptor.configurable&&causeDescriptor.writable&&!causeDescriptor.enumerable&&causeDescriptor.configurable&&" ++
        "errorsDescriptor.writable&&!errorsDescriptor.enumerable&&errorsDescriptor.configurable&&!prototypeDescriptor.writable&&!prototypeDescriptor.enumerable&&!prototypeDescriptor.configurable&&" ++
        "base.toString()==='Error: base'&&Error.prototype.toString.call({name:'',message:'only'})==='only'&&Error.prototype.toString.call({name:'Only',message:''})==='Only'&&" ++
        "Error.prototype.toString.call({})==='Error'&&Object.prototype.toString.call(base)==='[object Error]'&&chains&&syntax&&" ++
        "custom instanceof CustomError&&custom instanceof TypeError&&custom instanceof Error&&custom.name==='TypeError';");
    try std.testing.expectEqual(true, runtime.valueBoolean(value));
}

test "numeric lexical if chains dispatch without changing dynamic lookup semantics" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};

    var value = try runtime.evaluateSource(&program, "function dispatch(P){let i=0;for(P=1;i<1000;i++){if(P===1)P=2;else if(P===2)P=3;else if(P===3)P=4;else if(P===4)P=1;}return P;}return dispatch(0);");
    try std.testing.expectEqual(@as(f64, 1), try runtime.valueNumber(value));
    try std.testing.expect(runtime.stats.steps < 20_000);

    try runtime.reset();
    value = try runtime.evaluateSource(&program, "function cached(){let value=3;let total=0;let index=0;while(index<200){total=total+value;index++;}return total;}return cached();");
    try std.testing.expectEqual(@as(f64, 600), try runtime.valueNumber(value));
    try std.testing.expect(runtime.stats.identifier_cache_hits > 200);

    try runtime.reset();
    value = try runtime.evaluateSource(&program, "let reads=0;let result=0;const source={get P(){reads++;return reads===2?2:0;}};" ++
        "with(source){if(P===1)result=1;else if(P===2)result=2;else if(P===3)result=3;}return reads*10+result;");
    try std.testing.expectEqual(@as(f64, 22), try runtime.valueNumber(value));

    try runtime.reset();
    value = try runtime.evaluateSource(&program, "let P='2';let result=0;if(P==1)result=1;else if(P==2)result=2;else if(P==3)result=3;return result;");
    try std.testing.expectEqual(@as(f64, 2), try runtime.valueNumber(value));
}

test "numeric expression fusion preserves primitive and dynamic lookup semantics" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};

    var value = try runtime.evaluateSource(&program, "let a=5;let b=9;return ((a<<3)^(b*7))-~a;");
    try std.testing.expectEqual(@as(f64, 29), try runtime.valueNumber(value));
    try std.testing.expect(runtime.stats.steps < 20);

    try runtime.reset();
    value = try runtime.evaluateSource(&program, "let a='5';return a+2;");
    try std.testing.expectEqualStrings("52", runtime.valueString(value));

    try runtime.reset();
    value = try runtime.evaluateSource(&program, "let reads=0;const source={get a(){reads++;return 5;}};let result=0;with(source){result=(a<<1)+1;}return reads*100+result;");
    try std.testing.expectEqual(@as(f64, 111), try runtime.valueNumber(value));

    try runtime.reset();
    value = try runtime.evaluateSource(&program, "let reads=0;const box={get value(){reads++;return 5;},run(){return this.value*2+1;}};const result=box.run();return reads*100+result;");
    try std.testing.expectEqual(@as(f64, 111), try runtime.valueNumber(value));

    try runtime.reset();
    value = try runtime.evaluateSource(&program, "let a=1,b=2,c=0;c=(a+=2,b++,a*b);return a*100+b*10+c;");
    try std.testing.expectEqual(@as(f64, 339), try runtime.valueNumber(value));

    try runtime.reset();
    value = try runtime.evaluateSource(&program, "let values=[1,2],i=0;const result=(values[i++]+=4,values[i++]=7,i);return values[0]*100+values[1]*10+result;");
    try std.testing.expectEqual(@as(f64, 572), try runtime.valueNumber(value));

    try runtime.reset();
    value = try runtime.evaluateSource(&program, "let reads=0,writes=0,stored=3;const box={get value(){reads++;return stored;},set value(next){writes++;stored=next;}};box.value+=2;return reads*100+writes*10+stored;");
    try std.testing.expectEqual(@as(f64, 115), try runtime.valueNumber(value));

    try runtime.reset();
    value = try runtime.evaluateSource(&program, "const left={get value(){return {valueOf(){return 7;}};}};const right={get trigger(){let i=0;while(i<300){[i,i+1];i++;}return 1;}};return left.value+right.trigger;");
    try std.testing.expectEqual(@as(f64, 8), try runtime.valueNumber(value));

    try runtime.reset();
    value = try runtime.evaluateSource(&program, "function make(value){return function(){return value+1;};}const one=make(1);const ten=make(10);let total=0;for(let i=0;i<200;i++)total+=i&1?one():ten();return total;");
    try std.testing.expectEqual(@as(f64, 1300), try runtime.valueNumber(value));
    try std.testing.expect(runtime.stats.identifier_cache_hits > 200);
}

test "unused arguments objects are elided without changing lexical semantics" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};

    const value = try runtime.evaluateSource(&program, "function plain(value){return value+1;}" ++
        "function observed(value){return arguments[0];}" ++
        "function dynamic(value){return eval('arguments[0]');}" ++
        "function outer(value){return ()=>arguments[0];}" ++
        "return [plain(2),observed(3),dynamic(4),outer(5)()].join(',');");
    try std.testing.expectEqualStrings("3,3,4,5", runtime.valueString(value));

    var plain_needs_arguments = true;
    var observed_needs_arguments = false;
    var dynamic_needs_arguments = false;
    var outer_needs_arguments = false;
    for (program.nodes[0..program.node_count]) |node| {
        if (node.kind != .function_declaration) continue;
        const name = program.text(node.text);
        if (equals(name, "plain")) plain_needs_arguments = node.flags & flag_needs_arguments != 0;
        if (equals(name, "observed")) observed_needs_arguments = node.flags & flag_needs_arguments != 0;
        if (equals(name, "dynamic")) dynamic_needs_arguments = node.flags & flag_needs_arguments != 0;
        if (equals(name, "outer")) outer_needs_arguments = node.flags & flag_needs_arguments != 0;
    }
    try std.testing.expect(!plain_needs_arguments);
    try std.testing.expect(observed_needs_arguments);
    try std.testing.expect(dynamic_needs_arguments);
    try std.testing.expect(outer_needs_arguments);
}

test "bytecode benchmarks keep small medium large and allocation challenge work bounded" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};
    const cases = [_]struct {
        source: []const u8,
        expected: f64,
        maximum_steps: usize,
        maximum_peak_cells: usize,
    }{
        .{ .source = "return 1+2*3;", .expected = 7, .maximum_steps = 64, .maximum_peak_cells = 640 },
        .{ .source = "let total=0;for(let i=0;i<1000;i++){total+=i;}return total;", .expected = 499500, .maximum_steps = 32_000, .maximum_peak_cells = 2048 },
        .{ .source = "let total=0;for(let i=0;i<20000;i++){total+=i;}return total;", .expected = 199990000, .maximum_steps = 400_000, .maximum_peak_cells = 8192 },
        .{ .source = "let total=0;let i=0;while(i<1000){const pair=[i,i+1];total+=pair[1]-pair[0];i++;}return total;", .expected = 1000, .maximum_steps = 64_000, .maximum_peak_cells = 8192 },
    };
    for (cases) |case| {
        try runtime.reset();
        const value = try runtime.evaluateSource(&program, case.source);
        try std.testing.expectEqual(case.expected, try runtime.valueNumber(value));
        try std.testing.expect(runtime.stats.steps <= case.maximum_steps);
        try std.testing.expectEqual(runtime.stats.steps, runtime.stats.bytecode_instructions);
        try std.testing.expect(runtime.stats.peak_cells <= case.maximum_peak_cells);
        try std.testing.expect(runtime.stats.bytecode_frames_peak <= max_bytecode_frames);
    }
}

test "syntax limits const errors step budget and cancellation fail visibly" {
