}

test "R4JS cooperative scheduler bounds job slices and cancellation" {
    const runtime = try createTestingRuntime();
    defer destroyTestingRuntime(runtime);
    var program: Program = .{};
    _ = try runtime.evaluateSource(&program, "let completed=0;for(let index=0;index<10;index++){queueMicrotask(()=>completed++);}");
    try std.testing.expectEqual(@as(usize, 3), try runtime.drainJobs(&program, 3));
    try std.testing.expectEqual(@as(f64, 3), try runtime.valueNumber(runtime.global("completed").?));
    try std.testing.expectEqual(@as(usize, 7), try runtime.drainJobs(&program, 32));
    try std.testing.expectEqual(@as(f64, 10), try runtime.valueNumber(runtime.global("completed").?));

    try runtime.reset();
    _ = try runtime.evaluateSource(&program, "queueTask(()=>{let value=0;while(true){value++;}});");
    var remaining: usize = 32;
    runtime.setStop(.{ .context = &remaining, .requested = stopAfter });
    try std.testing.expectError(error.Cancelled, runtime.drainJobs(&program, 1));
}

