    runtime.setStepBudget(default_step_budget);
    try runtime.defineGlobal("hostFailure", try runtime.createHostFunction(0, null, hostDiagnosticCallback), true);
    try std.testing.expectError(error.RangeError, runtime.evaluateNamedScriptSource(&program, "host.js", "function invoke(){return hostFailure();}\ninvoke();"));
    try std.testing.expectEqual(DiagnosticPhase.host, runtime.diagnosticPhase());
    try std.testing.expectEqualStrings("RangeError", runtime.diagnosticErrorName());
    try std.testing.expectEqualStrings("host.js", runtime.diagnosticSourceName());
    try std.testing.expect(std.mem.indexOf(u8, runtime.diagnosticStack(), "host.js:") != null);

    const caught = try runtime.evaluateNamedScriptSource(&program, "caught.js", "let result=false;try{missingName;}catch(reason){result=typeof reason.stack==='string'&&reason.sourceName==='caught.js'&&reason.lineNumber>=1&&reason.columnNumber>=1;}result;");
    try std.testing.expectEqual(true, runtime.valueBoolean(caught));

    try runtime.registerModule("https://diagnostic.test/failure.js", "export function fail(){return missingModuleValue;}");
    try runtime.registerModule("https://diagnostic.test/app.js", "import {fail} from './failure.js';fail();");
    try std.testing.expectError(error.UnknownIdentifier, runtime.evaluateModule("https://diagnostic.test/app.js"));
    try std.testing.expectEqualStrings("https://diagnostic.test/failure.js", runtime.diagnosticSourceName());
    try std.testing.expect(std.mem.indexOf(u8, runtime.diagnosticStack(), "https://diagnostic.test/failure.js:") != null);
    try std.testing.expect(std.mem.indexOf(u8, runtime.diagnosticStack(), "https://diagnostic.test/app.js:") != null);
}

