const FiberSwitchTestState = struct {
    caller: FiberContext = .{},
    fiber: FiberContext = .{},
    count: usize = 0,
};

fn fiberSwitchTestEntry(raw_state: *anyopaque, expected_argument: usize) callconv(.c) noreturn {
    const state: *FiberSwitchTestState = @ptrCast(@alignCast(raw_state));
    state.count = expected_argument;
    fiberSwitch(&state.fiber, &state.caller);
    state.count += 1;
    fiberSwitch(&state.fiber, &state.caller);
    while (true) fiberSwitch(&state.fiber, &state.caller);
}

test "resumable fiber context preserves an independent x86_64 stack" {
    const stack = try std.testing.allocator.alloc(u8, 64 * 1024);
    defer std.testing.allocator.free(stack);
    var state = FiberSwitchTestState{};
    initializeFiberContext(&state.fiber, stack, fiberSwitchTestEntry, &state, 41);
    fiberSwitch(&state.caller, &state.fiber);
    try std.testing.expectEqual(@as(usize, 41), state.count);
    fiberSwitch(&state.caller, &state.fiber);
    try std.testing.expectEqual(@as(usize, 42), state.count);
}

